	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (252, '1WmIo9ORq1IDlovUWFmo4Y', 'Pat', 'Martino', '8b8b7c42-8210-4267-bb93-4c2df5b2c438', 357709, 2, 'https://en.wikipedia.org/wiki/Pat_Martino', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Pat_Martino.jpg/500px-Pat_Martino.jpg', 'Tom Beetz @ http://home.hetnet.nl/~tbeetz/index.html', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Pat_Martino.jpg', '{"Intro":"Pat Martino (born Patrick Carmen Azzara; August 25, 1944 – November 1, 2021) was an American jazz guitarist and composer.","Early Life":"Martino was born Patrick Carmen Azzara in Philadelphia, Pennsylvania, United States, to father Carmen \"Mickey\" Azzara (d. 1990) and mother Jean (née Orlando, d. 1989). He was first exposed to jazz by his father, who sang in local clubs and briefly studied guitar.","Career":"Martino studied with renowned jazz teacher Dennis Sandole, and in his studio met some of Sandole''s other students, among them John Coltrane, James Moody, McCoy Tyner and others. Martino began playing professionally at age 15 after moving to New York City. He lived for a period with Les Paul and began playing at jazz clubs such as Smalls Paradise. Martino later moved into a suite in the President Hotel on 48th Street. He played at Smalls for six months of the year, and played summers at the Club Harlem in Atlantic City, New Jersey.\nMartino played and recorded early in his career with Lloyd Price, Willis Jackson, and Eric Kloss. He also worked with jazz organists Charles Earland, Richard \"Groove\" Holmes, Jack McDuff, Don Patterson, Trudy Pitts, Jimmy Smith, Gene Ludwig, Ray Allen (Raymond Chenot) and Joey DeFrancesco.\nIn 1980, Martino suffered a hemorrhaged arteriovenous malformation that caused a \"near-fatal seizure\". The resulting surgery, which removed part of his brain, left him with amnesia and no recollection or knowledge of his career or how to play the instrument that made him successful. Martino said he came out of surgery with complete forgetfulness, and had to learn to focus on the present rather than the past or the possible future. He had to completely re-learn how to play.\nHe was subsequently chosen as Guitar Player of the Year in the Down Beat magazine Readers'' Poll of 2004. In 2006, Mobile Fidelity Sound Lab reissued his album East! on Ultradisc UHR SACD.\nIn 2017, he created a series of educational videos, A Study of the Opposites and How They Manifest on the Guitar.\nMartino''s recording career spanned more than 150 releases across multiple major jazz labels, with his work distributed among Prestige, Blue Note, Muse Records and HighNote Records, among others. His discography spans a variety of sounds, such as soul-jazz organ trio work, fusion experimentation, and his post-recovery mainstream recordings.","Musical Style":"Martino''s influences were Les Paul, Johnny Smith, Hank Garland, Joe Pass, and especially Wes Montgomery. To a lesser extent, he was influenced by the guitar stylings of Jim Hall, Mundell Lowe and Barry Galbraith.\nMartino said, \"There are elements within an instrument’s architecture that initiate a continuous source of valuable information. For the guitar, there are two. The first is the major third interval, and the second is the minor third interval. Once we view their repetitive information, they begin to appear as a series of automatic functions.\"\nMartino''s lines contain chromatic links outside any particular IIm7 chord that might be conceptualized over a chord progression, even in the examples he provides in his books and instructional videos. On his bulletin board he has stated that he formulated the system more as a way to explain his playing rather than as something to use to create music. In his own words, \"Although the analysis of some of my recorded solos have been referred to as modal, personally I''ve never operated in that way. I''ve always depended upon my own melodic instinct, instead of scale-like formulas.\"","Personal Life":"Martino was married to Ayako Asahi Martino; they met in Tokyo, Japan in 1995. Due to a chronic respiratory disorder, he stopped performing in 2018.  He died on November 1, 2021, at the age of 77.","Legacy":"Jazz music educator Wolf Marshall said Martino is \"a living legend, a national treasure, and an inspiration to musicians and music lovers of all stripes\"."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (253, '1WmIo9ORq1IDlovUWFmo4Y', 'Pat', 'Metheny', '7daac7f9-8fcc-485f-a14f-f8091d98cf25', 20185, 2, 'https://en.wikipedia.org/wiki/Pat_Metheny', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Pat_metheny_orch2.jpg/500px-Pat_metheny_orch2.jpg', 'R. Steven Rainwater from Dallas, US', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Pat_metheny_orch2.jpg', '{"Intro":"Patrick Bruce Metheny ( məth-EE-nee; born August 12, 1954) is an American jazz guitarist and composer.\nHe was the leader of the Pat Metheny Group (1977–2010) and continues to work in various small-combo, duet, and solo settings, as well as other side projects. His style incorporates elements of progressive and contemporary jazz, latin jazz, and jazz fusion. He has three gold albums and 20 Grammy Awards, and is the only person to have won Grammys in 10 categories.","Biography":"Metheny was born in Lee''s Summit, Missouri. His father Dave played trumpet, his mother Lois sang, and his maternal grandfather Delmar was a professional trumpeter. Metheny''s first instrument was the trumpet, which he was taught by his brother, Mike. Pat''s brother, father, and grandfather played trios together at home. His parents were fans of Glenn Miller and swing music. They took Pat to concerts to hear Clark Terry and Doc Severinsen, but they had little respect for guitar. Pat''s interest in guitar increased around 1964 when he saw the Beatles perform on TV. For his 12th birthday, his parents allowed him to buy a guitar, which was a Gibson ES-140 3/4.\nPat Metheny''s life changed after hearing the album Four & More by Miles Davis. Soon after, he was captivated by Wes Montgomery''s album Smokin'' at the Half Note which was released in 1965. He cites the Beatles, Miles Davis, and Montgomery as having the biggest impact on his music.\nWhen he was 15, Metheny won a scholarship from Down Beat magazine to a one-week jazz camp where he was mentored by guitarist Attila Zoller, who then invited him to New York City to meet guitarist Jim Hall and bassist Ron Carter.\nWhile playing at a club in Kansas City, Metheny was approached by Bill Lee, a dean at the University of Miami, and offered a scholarship. After less than a week at college, Metheny realized that playing guitar all day during his teens had left him unprepared for classes. He admitted this to Lee, who offered him a job to teach as a professor, as the school had recently introduced electric guitar as a course of study.\nHe moved to Boston in the early 1970s to teach at the Berklee College of Music under the supervision of jazz vibraphonist Gary Burton and established a reputation as a prodigy.\nMetheny at KJAZ radio, Alameda, California, December 1980\nIn 1974, Metheny joined Burton''s band alongside fellow guitarist Mick Goodrick, Steve Swallow and Eberhard Weber on bass, and percussionist Bob Moses. While Goodrick played 6-string electric guitar, Metheny introduced the electric 12-string guitar to the sound palette.  He immediately appeared on Burton''s studio recordings, from the 1974 Ring, Dreams So Real (1976), and Passengers in 1977. With Moses he had also a working trio that included their friend Jaco Pastorius on bass guitar.\nIn June 1974, he and Pastorius were in New York and took part in a session with pianist Paul Bley and Bruce Ditmas on drums, unaware that they were in an actual studio and were being recorded. An album with the material was released two years later on Bley''s Improvising Artists label, unofficially titled Jaco.\nFor his debut album, Bright Size Life (1976), in December 1975 the trio flew to Europe and recorded the album during two days in Ludwigsburg (Germany) in one of the preferred studios of producer Manfred Eicher. Metheny and Moses had already been there in July for Gary Burton''s Ring, also released through Eicher''s label ECM. Initially they rehearsed the material for the recording with Dave Holland on bass, because Eicher refused to have an electric bass on the recording; but in the end he accepted Pastorius to play. According to Metheny, it was Burton, who was present in the studio for the trio recording and acted informally as their actual producer (without being credited).\nHis next album, Watercolors (ECM, 1977), was recorded with Eberhard Weber on bass and Danny Gottlieb on drums, and significantly marked Metheny''s first outing with pianist Lyle Mays, who would become his key collaborator in forming the Pat Metheny Group later that year. With Mark Egan on bass, the lineup was set for the group''s self-titled debut album, Pat Metheny Group (ECM, 1978).","Early Years And Education":"Metheny was born in Lee''s Summit, Missouri. His father Dave played trumpet, his mother Lois sang, and his maternal grandfather Delmar was a professional trumpeter. Metheny''s first instrument was the trumpet, which he was taught by his brother, Mike. Pat''s brother, father, and grandfather played trios together at home. His parents were fans of Glenn Miller and swing music. They took Pat to concerts to hear Clark Terry and Doc Severinsen, but they had little respect for guitar. Pat''s interest in guitar increased around 1964 when he saw the Beatles perform on TV. For his 12th birthday, his parents allowed him to buy a guitar, which was a Gibson ES-140 3/4.\nPat Metheny''s life changed after hearing the album Four & More by Miles Davis. Soon after, he was captivated by Wes Montgomery''s album Smokin'' at the Half Note which was released in 1965. He cites the Beatles, Miles Davis, and Montgomery as having the biggest impact on his music.\nWhen he was 15, Metheny won a scholarship from Down Beat magazine to a one-week jazz camp where he was mentored by guitarist Attila Zoller, who then invited him to New York City to meet guitarist Jim Hall and bassist Ron Carter.\nWhile playing at a club in Kansas City, Metheny was approached by Bill Lee, a dean at the University of Miami, and offered a scholarship. After less than a week at college, Metheny realized that playing guitar all day during his teens had left him unprepared for classes. He admitted this to Lee, who offered him a job to teach as a professor, as the school had recently introduced electric guitar as a course of study.\nHe moved to Boston in the early 1970s to teach at the Berklee College of Music under the supervision of jazz vibraphonist Gary Burton and established a reputation as a prodigy.","Personal Life":"Metheny is the younger brother of jazz flugelhornist Mike Metheny. He lives in New York City with his wife, Latifa (née Azhar), and three children. Latifa has been credited for album photography.\nMetheny was once in a relationship with Sônia Braga.\nDue to an unscheduled medical procedure he had to interrupt his concerts in China in May 2025."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (254, '1WmIo9ORq1IDlovUWFmo4Y', 'Paul', 'Bley', '5ff0b393-1706-47ce-8bda-a0fd3fe9b98a', 253098, 3, 'https://en.wikipedia.org/wiki/Paul_Bley', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Paul_Bley%2C_1968.jpg/500px-Paul_Bley%2C_1968.jpg', 'Unknown photographer', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Paul_Bley,_1968.jpg', '{"Intro":"Paul Bley, CM (November 10, 1932 – January 3, 2016) was a Canadian jazz pianist known for his contributions to the free jazz movement of the 1960s as well as his innovations and influence on trio playing and his early live performance on the Moog and ARP synthesizers. His music has been described by Ben Ratliff of the New York Times as \"deeply original and aesthetically aggressive\". Bley''s prolific output includes influential recordings from the 1950s through to his solo piano recordings of the 2000s.","Early Life":"Bley was born in Montreal, Quebec, on November 10, 1932. His adoptive parents were Betty Marcovitch, an immigrant from Romania, and Joseph Bley, owner of an embroidery factory, who named him Hyman Bley. However, in 1993 a relative from the New York branch of the Bley family walked into the Sweet Basil Jazz Club in New York City and informed Bley that his father was actually his biological parent. At age five Bley began studying the violin, but at age seven, after his mother divorced his father, he decided to switch to the piano. By eleven he had received a junior diploma from the McGill Conservatory in Montreal. At thirteen he formed a band which played at summer resorts in Ste. Agathe, Quebec. As a teenager he changed his name to \"Paul,\" thinking that girls would find it more attractive. Also as a teenager, he played with touring American bands, including Al Cowan''s Tramp Band. In 1949, when Bley was starting his senior year of high school, Oscar Peterson asked Bley to fulfill his contract at the Alberta Lounge in Montreal. The next year Bley left Montreal for New York City and Juilliard. Bley lived in the United States for his entire adult life, but never renounced his Canadian citizenship."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (255, '1WmIo9ORq1IDlovUWFmo4Y', 'Paul', 'Chambers', 'b6ff4fd0-03ae-41a6-942e-7de13124b970', 259778, 1, 'https://en.wikipedia.org/wiki/Paul_Chambers', NULL, NULL, NULL, NULL, '{"Intro":"Paul Laurence Dunbar Chambers Jr. (April 22, 1935 – January 4, 1969) was an American jazz double bassist. A fixture of rhythm sections during the 1950s and 1960s, he has become one of the most widely-known jazz bassists of the hard bop era. He was also known for his bowed solos. Chambers recorded about a dozen albums as a leader or co-leader, and more than 100 as a sideman, especially as the anchor of trumpeter Miles Davis''s \"first great quintet\" (1955–63) and with pianist Wynton Kelly (1963–68).","Biography":"Born in Pittsburgh, Pennsylvania, on April 22, 1935, to Paul Lawrence Chambers and Margaret Echos, he was brought up in Detroit, Michigan, following the death of his mother. He began playing music with several of his schoolmates on the baritone horn. Later he took up the tuba. \"I got along pretty well, but it''s quite a job to carry it around in those long parades, and I didn''t like the instrument that much\".","Personal Life":"Chambers developed addictions to both alcohol and heroin. He was hospitalized at the end of 1968 with what was thought to be a severe case of influenza, but tests revealed that he had tuberculosis. As his organ functions deteriorated, Chambers lapsed into a coma for 18 days. It is believed his addictions to heroin and alcohol contributed to his health problems. On January 4, 1969, he died of tuberculosis at the age of 33."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (256, '1WmIo9ORq1IDlovUWFmo4Y', 'Paul', 'Desmond', 'd5bf3447-c526-4f7c-9931-4b7c80fe34de', 170329, 6, 'https://en.wikipedia.org/wiki/Paul_Desmond', 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Paul_Desmond_1962.jpg', 'Associated Booking Corporation (management)', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Paul_Desmond_1962.jpg', '{"Intro":"Paul Desmond (born Paul Emil Breitenfeld; November 25, 1924 – May 30, 1977) was an American jazz alto saxophonist and composer and proponent of cool jazz. He was a member of the Dave Brubeck Quartet and composed the group''s biggest hit, \"Take Five\". The song remains the best-selling jazz song of all time.\nIn addition to his work with Brubeck, he led several groups and collaborated with Gerry Mulligan, Chet Baker, Jim Hall, and Ed Bickert. After years of chain smoking and poor health, Desmond succumbed to lung cancer in 1977 after a tour with Brubeck.","Early Life":"Desmond was born Paul Emil Breitenfeld in San Francisco, California, in 1924, the son of Shirley (née King) and Emil Aron Breitenfeld. His grandfather Sigmund Breitenfeld, a medical doctor, was born on 17 November 1857 in Kameničky in Eastern Bohemia; he emigrated to the US in 1885 and on 2 May 1886, in New York, married Hermina Lewy. They had four children (including Emil, father of Paul Emil). Paul Desmond and members of his father''s family \"frequently speculated as to whether Sigmund or Hermine Breitenfeld had Jewish backgrounds\", but they did not identify as Jewish, or observe Jewish traditions. However, Fred Barton, songwriter/arranger and Desmond''s cousin, found extensive genealogical proof that both the Breitenfeld and Löwy families were Bohemian Jews. The Breitenfeld family in Bohemia and Vienna featured musicians in every generation throughout the 1800s, 1900s, and to the present day. Desmond''s mother, born Shirley King, was of an Irish Catholic family.\nDesmond''s father Emil Breitenfeld was a pianist, organist, arranger, and composer who accompanied silent films in movie theaters and produced musical arrangements for printed publication and for live theatrical productions. During World War I, while training with the 17th New York Regiment in Plattsburgh, New York, he composed The Last Long Mile, one of the best-known soldiers'' songs of that war.\nDesmond''s mother, Shirley, was emotionally unstable throughout his upbringing, and appears to have suffered from obsessive–compulsive disorder and other mental illnesses. Starting in 1933, Desmond spent nearly five years living with relatives in New Rochelle, New York due to his mother''s mental health problems.\nDesmond started playing the clarinet at the age of twelve and continued to do so throughout his time at San Francisco Polytechnic High School. While in high school, he expressed an interest in learning the violin, but his father discouraged him, claiming that violin players were \"a dime a dozen\" and warning him that with the violin, \"you''ll starve.\" During high school, Desmond also developed a talent for writing and became the co-editor of his school newspaper. In this role, he had the opportunity to interview comedian Bob Hope when he visited San Francisco. After graduating from high school, Desmond enrolled at San Francisco State College, where he majored in English. While in college, Desmond began playing the alto saxophone, after being influenced by the likes of Lester Young and Charlie Parker. In his first year of college, Desmond was drafted into the United States Army and joined the Army band while stationed in San Francisco. He spent three years in the military, but his unit was not called to combat.\nFollowing his military discharge, Paul Emil Breitenfeld legally changed his last name from Breitenfeld to Desmond in 1946. He told many stories over the years regarding how he chose the name Desmond, but his biographer Doug Ramsey offers an account from Desmond''s friend Hal Strack that the two were listening to the Glenn Miller band singer Johnny Desmond in 1942, and Desmond told Strack, \"that''s such a great name. It''s so smooth and yet it''s uncommon....If I ever decide I need another name, it''s going to be Desmond.\"\nDesmond was married from 1947 to 1949 to Duane Reeves Lamon. He never remarried.","Career":"After World War II, Desmond started working in the San Francisco Bay Area, working as a backing musician. He worked occasionally for Dave Brubeck at the Geary Cellar in San Francisco. For several weeks, he led a small jazz combo at the Band Box in Redwood City that included Dave Brubeck. Desmond had a falling out with Brubeck when he resigned from the Band Box and prevented Brubeck from taking over the residency. In 1950, Desmond joined the band of Jack Fina and toured with Fina for several months, but he returned to California after hearing Brubeck''s trio on the radio and deciding that he should repair his relationship with Brubeck and attempt to join Brubeck''s increasingly successful band.\nAt the time, Brubeck and his wife Iola had three small children, and Brubeck had instructed Iola not to let Desmond set foot in the family home. Desmond appeared at Brubeck''s San Francisco apartment one day while Dave was in the back yard hanging diapers on a laundry line, and Iola, defying Brubeck''s wishes, let Desmond in and took him to Dave. Desmond offered to perform arranging and administrative work for Brubeck''s band, and to babysit Brubeck''s children, and Brubeck finally relented and agreed to try working with Desmond again.\nSome people called him the stork—''Cause he would stand on one leg and leaned on the piano. But that ... that was when he was playing great. What used to scare me is I''d look at him and it would just be whites in his eyes, wouldn''t be any eyeballs.\nDave Brubeck(PBS interview with Hedrick Smith)\nDesmond met Dave Brubeck in 1944 in the military. Brubeck was trying out for the 253rd Army band, to which Desmond belonged. After making the cut he—unlike Desmond—was sent overseas in 1944, to Europe. Desmond once told Marian McPartland of National Public Radio''s Piano Jazz that he was taken aback by the chord changes which Brubeck introduced during that 1944 audition. After Desmond persuaded Brubeck to hire him following his stint with Jack Fina, the two had a contract drafted (of which Brubeck was the sole signatory); the wording forbade Brubeck from firing him, ensured Brubeck''s status as group leader, and gave Desmond twenty percent of all profits generated from the quartet. This established the Dave Brubeck Quartet, which lasted from 1951 to December 1967.\nThe quartet became especially popular with college-age audiences, often performing in college settings, including their ground-breaking 1953 album Jazz at Oberlin at Oberlin College and at the campuses of Ohio University and the University of Michigan. The success of the quartet led to a Time magazine piece on them in 1954, with the famous cover featuring Brubeck''s face.\nAfter drummer Joe Dodge decided to leave the group, Joe Morello joined in late 1956, on Desmond''s recommendation. Despite this,  differences in musical aspirations and taste made their relationship a tense one for many years. Desmond hoped for a  \"tinky-boom\" background-type drummer while Morello wanted to be recognized and featured. During Morello''s first performance with the group, he was featured by Brubeck and received an ovation from the audience for his solo. Desmond resented this, and threatened to leave the group. Brubeck managed to keep both Desmond and Morello in the group but with frictions between them for years. Desmond''s grudge against Morello could also be heard during their performance. In their ''Take The ‘A’ Train'' performance in Hanover, Germany in 1958, for example, Desmond''s playing sounded lackluster and uninterested. After a passage of rhythmically complex playing from Morello, Desmond would sometimes play very quietly and or even drop out for a few bars. In their later years they reconciled and became close friends.\nThe Dave Brubeck Quartet played until 1967, when Brubeck switched his musical focus from performance to composition and dissolved the group. During the 1970s Desmond joined Brubeck for several reunion tours, including \"Two Generations of Brubeck\". Accompanying them were Brubeck''s sons Chris Brubeck, Dan Brubeck and Darius Brubeck. In 1976 Desmond played 25 shows in 25 nights with Brubeck, touring the United States by bus.\nPlaying with Desmond and Mulligan was really mind-blowing because they were such heroes for me.\nDesmond worked several times during his career with baritone saxophonist and band leader Gerry Mulligan. They made two studio albums together (Gerry Mulligan - Paul Desmond Quartet (1957), and Two of a Mind (1962)). In June 1969 Desmond appeared at the New Orleans Jazz Festival with Gerry Mulligan, with favorable reactions from critics and audience members. During Brubeck''s Two Generations tours, Desmond and Mulligan shared the stage in 1974. Unlike Brubeck, Mulligan had much in common with Desmond; they were similar in their interests and humor, and both were prone to addiction.\nDesmond had a celebrated studio partnership with guitarist Jim Hall. Hall played on several albums recorded by Desmond between 1959 and 1963 for Warner Bros. and RCA Victor. After a period of inactivity, Desmond was asked to play the Half Note in New York City in 1971 by Hall. With his customary wryness, Desmond said that he took the job only because he was nearby and could tumble out of bed to work. The two continued to play at the club to packed audiences. Desmond also joined the Modern Jazz Quartet for a Christmas concert in 1971 at the New York Town Hall.\nDesmond was a guest artist on five tracks by Chet Baker recorded between 1975 and 1977. These were released on the albums She Was Too Good to Me (CTI, 1974), You Can''t Go Home Again, and The Best Thing for You. Baker and Desmond also appeared together on two tracks included on Jim Hall''s 1975 Concierto album.\nDesmond met Canadian guitarist Ed Bickert through a recommendation by Jim Hall, and Desmond performed with Bickert at several clubs in the Toronto area during 1974–1975. Desmond featured Bickert on his 1975 studio album Pure Desmond, and the two played together at the 1976 Edmonton Jazz Festival. Live recordings of that concert and club dates with Bickert performed during 1974-1975 were released during and after Desmond''s lifetime.","Personal Life":"In their private lives Dave Brubeck and his family were very close to Paul Desmond, though the two men possessed very different personalities. Darius Brubeck recalls thinking that Desmond was his uncle almost into adolescence. Desmond grew especially close to Dave''s son Michael, to whom he left his saxophone upon his death. Desmond was also described as a womanizer who was unable to form (and was uninterested in maintaining) steady relationships with women, though he had no shortage of female companions throughout his life. Desmond is reported to have quipped, upon seeing a former girlfriend on the street, \"There she goes, not with a whim but a banker\" (a semi-Spoonerism reference to T.S. Eliot''s \"This is the way the world ends / Not with a bang but a whimper\"). In contrast, Brubeck was deeply religious and a stalwart family man.\nI have won several prizes as the world''s slowest alto player, as well as a special award in 1961 for quietness.\nDesmond enjoyed reading works by thinkers of his generation like Timothy Leary and Jack Kerouac who advocated or relied upon the use of recreational drugs, and sometimes used LSD. He had several addictions, including Dewar''s Scotch whisky and Pall Mall cigarettes. In the 1940s and 1950s, Desmond frequently took amphetamines, and in the 1970s he was known to use cocaine. His chemical dependency problems would sometimes drain him of energy on the road. Clarinetist Perry Robinson recalls in his autobiography that Desmond would sometimes need a vitamin B12 shot just to go on playing during his later career.\nPristine, perfect. One of the great livers of our time. Awash in Dewar''s and full of health.\nDesmond died on May 30, 1977, not of his heavy alcohol habit but of lung cancer, the result of his longtime heavy smoking. He was 52. Never without his humor, after he was diagnosed with cancer he expressed pleasure at the health of his liver. His last concert was with Brubeck in February 1977, in New York City. His fans were unaware of his rapidly declining health. Desmond specified in his will that all proceeds from \"Take Five\" would go to the Red Cross following his death. Desmond reportedly owned a Baldwin grand piano, which he lent to Bradley Cunningham, owner of Bradley''s piano bar in Greenwich Village, provided that Cunningham move the large piano back to Desmond''s Upper West Side apartment to become part of Desmond''s estate. After this long and expensive process, Desmond willed the piano to Cunningham, a characteristic and final prank. The Paul Desmond Papers (and other Brubeck adjacent archival collections) are held at the Holt-Atherton Special Collections and Archives in the University of the Pacific Library.\nDesmond was cremated and his ashes were scattered."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (257, '1WmIo9ORq1IDlovUWFmo4Y', 'Paul', 'Gonsalves', '033fae4c-cb99-4e3b-8213-f0d0c1bc677d', 309988, 6, 'https://en.wikipedia.org/wiki/Paul_Gonsalves', NULL, NULL, NULL, NULL, '{"Intro":"Paul Gonsalves ((1920-07-12)July 12, 1920 – (1974-05-15)May 15, 1974) was an American jazz tenor saxophonist best known for his association with Duke Ellington. At the 1956 Newport Jazz Festival, Gonsalves played a 27-chorus solo in the middle of Ellington''s \"Diminuendo and Crescendo in Blue\", a performance credited with revitalizing Ellington''s waning career in the 1950s.","Biography":"Gonsalves was born in Brockton, Massachusetts, United States, to Portuguese Cape Verdean parents. His first instrument was the guitar, and as a child he was regularly asked to play Cape Verdean folk songs for his family. He grew up in New Bedford, Massachusetts, and played as a member of the Sabby Lewis Orchestra. His first professional engagement in Boston was with the same group on tenor saxophone, in which he played before and after his military service during World War II. He also played with fellow Cape Verdean Americans in Phil Edmund''s band in the 1940s. Before joining Duke Ellington''s orchestra in 1950, Gonsalves also played in big bands led by Count Basie (1947–1949) and Dizzy Gillespie (1949–1950).\nAt the 1956 Newport Jazz Festival, Gonsalves played a solo in Ellington''s \"Diminuendo and Crescendo in Blue\" that went through 27 choruses; the publicity from this performance is credited with reviving Ellington''s career. The performance is captured on the album Ellington at Newport. Gonsalves was a featured soloist in numerous Ellingtonian settings. He received the nickname \"The Strolling Violins\" from Ellington for playing solos while walking through the crowd.\nGonsalves died in London, England, ten days before Duke Ellington''s death, after a lifetime of addiction to alcohol and narcotics. Mercer Ellington refused to tell Duke of the passing of Gonsalves, fearing the shock might further accelerate his father''s decline. Ellington and Gonsalves, along with trombonist Tyree Glenn, lay side by side in the same New York funeral home for a period of time.\nGonsalves is buried at Long Island National Cemetery in Farmingdale, New York."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (258, '1WmIo9ORq1IDlovUWFmo4Y', 'Pee Wee', 'Russell', '81e26fc9-ddb5-42cf-9b31-2e0f55bf6342', 261340, 10, 'https://en.wikipedia.org/wiki/Pee_Wee_Russell', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Pee_Wee_Russell_%28Gottlieb_07571%29.jpg/500px-Pee_Wee_Russell_%28Gottlieb_07571%29.jpg', 'William P. Gottlieb', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Pee_Wee_Russell_(Gottlieb_07571).jpg', '{"Intro":"Charles Ellsworth \"Pee Wee\" Russell (March 27, 1906 – February 15, 1969) was an American jazz musician. Early in his career he played clarinet and saxophones, but he eventually focused solely on clarinet.\nWith a highly individualistic and spontaneous clarinet style that \"defied classification\", Russell began his career playing traditional jazz, but throughout his career incorporated elements of newer developments such as swing, bebop, and free jazz. Writing in 1961, the poet Philip Larkin commented: \"No one familiar with the characteristic excitement of his solos, their lurid, snuffling, asthmatic voicelessness, notes leant on till they split, and sudden passionate intensities, could deny the uniqueness of his contribution to jazz.\"","Early Life":"Pee Wee Russell was born in Maplewood, Missouri, United States, and grew up in Muskogee, Oklahoma. As a child, he first studied violin, but \"couldn''t get along with it\", then piano, disliking the scales and chord exercises, and then drums – including all the associated special effects. Then his father sneaked young Ellsworth into a dance at the local Elks Club to a four- or five-piece band led by New Orleans jazz clarinetist Alcide \"Yellow\" Nunez. Russell was amazed by Nunez''s improvisations: \" played the melody, then got hot and played jazz. That was something. How did he know where he was or where he was going?\" Pee Wee now decided that his primary instrument would be the clarinet, and the type of music he would play would be jazz. He approached the clarinettist in the pit band at the local theatre for lessons, and bought an Albert-system instrument. His teacher was named Charlie Merrill, and used to pop out for shots of corn whiskey during lessons.\nHis family moved to St. Louis, Missouri, in 1920, and that September Russell was enrolled in the Western Military Academy in Alton, Illinois. He remained enrolled there until October the following year, though he spent most of his time playing clarinet with various dance and jazz bands. He began touring professionally in 1922, and travelled widely with the Allen Brothers tent show and on riverboats St. Paul and J.S. He also played with a Charles Creath band at the Booker T. Washington Theater, a cultural epicenter for African Americans at the time. Russell''s recording debut was in 1924 with Herb Berger''s Band in St. Louis on \"Fuzzy Wuzzy Bird.\".","Career":"Pee Wee Russell, Muggsy Spanier, Miff Mole and Joe Grauso, Nick''s (Tavern), New York, ca. June 1946\nFrom his earliest career, Russell''s style was distinctive. The notes he played were somewhat unorthodox when compared to his contemporaries, and he was sometimes accused of playing out of tune. By the mid-1920s, Russell was a sought-after jazz clarinetist and worked with Jack Teagarden in pianist Peck Kelly''s band in Texas. Back in St. Louis, Russell played with Frankie Trumbauer and Bix Beiderbecke at the Arcadia Ballroom, which had hired Trumbauer as bandleader for the season spanning September 1925 and May 1926. For a short while, Jack Teagarden also played at the Arcadia, and Russell claimed that this was the greatest band he had ever played in. In 1926, he joined Jean Goldkette''s band, and the following year he left for New York City to join Red Nichols. While with Nichols''s band, Russell did frequent freelance recording studio work, on clarinet, soprano, alto and tenor sax, and bass clarinet. In 1932 he recorded with the Rhythmakers in New York City. He worked with various bandleaders (including Louis Prima) before beginning a series of residences at the jazz club \"Nick''s\" in Greenwich Village, Manhattan, in 1937.  He played with Bobby Hackett''s big band, and began playing with Eddie Condon, with whom he would continue to work, off and on, for much of the rest of his life – though he complained, \"Those guys  made a joke, of me, a clown, and I let myself be treated that way because I was afraid. I didn''t know where else to go, where to take refuge\".\nDuring World War II, he recorded V-Disc sides with Muggsy Spanier and the V-Disc All Stars. His composition \"Pee Wee Speaks\" with Spanier was released as a V-Disc, as Navy V-Disc 135 and as Army V-Disc 344 in January, 1945.\nFrom the 1940s onwards, Russell''s health was often poor, exacerbated by alcoholism – \"I lived on brandy milkshakes and scrambled-egg sandwiches. And on whiskey ... I had to drink half a pint of whiskey in the morning before I could get out of bed\" – which led to a major medical breakdown in 1951. He had periods when he could not play. Some people considered that his style was different after his breakdown: Larkin characterized it as \"a hollow feathery tone framing phrases of an almost Chinese introspection with a tendency to inconclusive garrulity that would have been unheard of in the days when Pee Wee could pack more into a middle eight than any other thirties pick-up player\".\nHe played with Art Hodes, Muggsy Spanier and occasionally bands under his own name in addition to Condon.  In his last decade, Russell often played at jazz festivals and international tours organized by George Wein, including an appearance with Thelonious Monk with an extended solo on Blue Monk at the 1963 Newport Jazz Festival, a meeting which has a mixed reputation (first available on the LP, Miles & Monk at Newport, and currently available as part of the Monk 2-CD set At Newport 1963–65). Russell formed a quartet with valve trombone player Marshall Brown, and included John Coltrane and Ornette Coleman tunes in his repertoire. Though often labeled a Dixieland musician by virtue of the company he kept, he tended to reject any label.   Russell''s unique and sometimes derided approach was praised as ahead of its time and cited by some as an early example of free jazz. At the time of their 1961 recording  Jazz Reunion (Candid), Coleman Hawkins (who had originally recorded with Russell in 1929 and considered him to be color-blind) observed that ''\"For thirty years, I’ve been listening to him play those funny notes. He used to think they were wrong, but they weren''t. He’s always been way out, but they didn''t have a name for it then.\" George Wein''s George Wein & the Newport All-Stars album includes a slow blues by Russell called \"The Bend''s Blues.\"\nBy this time, encouraged by Mary, his wife, Russell had taken up painting abstract art as a hobby. Mary''s death in the spring of 1967 had a severe effect on him.  His last gig was with Wein at the inaugural ball for President Richard Nixon on January 21, 1969. Russell died in a hospital in Alexandria, Virginia, less than three weeks later."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (259, '1WmIo9ORq1IDlovUWFmo4Y', 'Peter', 'Brotzmann', '9b3a1099-3a25-43ca-a5d7-2291af2ba1f3', 120328, 6, 'https://en.wikipedia.org/wiki/Peter_Brötzmann', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Peter_Broetzmann_05N2754.jpg/500px-Peter_Broetzmann_05N2754.jpg', 'Nomo michael hoefner / http://www.zwo5.de', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Peter_Broetzmann_05N2754.jpg', '{"Intro":"Peter Brötzmann (6 March 1941 – 22 June 2023) was a German jazz saxophonist and clarinetist regarded as a central and pioneering figure in European free jazz. Throughout his career, he released over fifty albums as a bandleader. Amongst his many collaborators were key figures in free jazz, including Derek Bailey, Anthony Braxton and Cecil Taylor, as well as experimental musicians such as Keiji Haino and Charles Hayward. His 1968 Machine Gun became \"one of the landmark albums of 20th-century free jazz\".","Biography":"Brötzmann was born in Remscheid on 6 March 1941. He studied painting in Wuppertal and was involved with the Fluxus movement but grew dissatisfied with art galleries and exhibitions. He experienced his first jazz concert when he saw American jazz musician Sidney Bechet while still in school at Wuppertal, and it made a lasting impression. He was also inspired by Miles Davis and John Coltrane.\nBrötzmann had not abandoned his art training, designing most of his album covers. He taught himself to play clarinet and saxophone, and is also known for playing the tárogató. Among his first musical partnerships was with double bassist Peter Kowald. For Adolphe Sax, Brötzmann''s first recording, was released in 1967 and featured Kowald and drummer Sven-Åke Johansson. In 1968, Machine Gun, an octet recording, was released. The album was self-produced under his BRO record label imprint and sold at concerts, and later marketed by FMP. In 2007, Atavistic reissued Machine Gun. \"Machine Gun\" was a nickname Don Cherry gave him \"to describe his violent style\".\nBrötzmann died on 22 June 2023, at the age of 82, at home in Wuppertal, Germany.\nThe album Nipples was recorded in 1969 with many of the Machine Gun musicians, including drummer Han Bennink, pianist Fred Van Hove, tenor saxophonist Evan Parker, and British guitarist Derek Bailey. The second set of takes from these sessions, called More Nipples, is more raucous. Fuck de Boere (dedicated to Johnny Dyani) is a live album of free sessions from these early years, containing two long improvisations, a 1968 recording of \"Machine Gun\" live (earlier than the studio version) and a longer jam from 1970. Brötzmann was a member of Bennink''s Instant Composers Pool, a collective of musicians who released their own records and that grew into a 10-piece orchestra.\nThe logistics of touring with the ICP tentet or his octet resulted in Brötzmann reducing the group to a trio with Han Bennink and Fred Van Hove. Bennink was a partner in Schwarzwaldfahrt, an album of duets recorded outside in the Black Forest in 1977, with Bennink drumming on trees and other objects in the woods.\nIn 1981, Brötzmann made a radio broadcast with Frank Wright and Willem Breuker (saxophones), Toshinori Kondo (trumpet), Hannes Bauer and Alan Tomlinson (trombones), Alexander von Schlippenbach (piano), Louis Moholo (drums), and Harry Miller (bass). This was released as the album Alarm.\nIn the 1980s, Brötzmann''s music was influenced by heavy metal and noise rock. He was a member of Last Exit and recorded music with the band''s bass guitarist and producer Bill Laswell.\nBrötzmann on tenor saxophone, Minnesota Sur Seine, 2006\nBrötzmann at the Sonore concert, Lviv, December 2008\nBrötzmann released over fifty albums as a bandleader and appeared on dozens more. His \"Die Like a Dog Quartet\" (with Toshinori Kondo, William Parker, and drummer Hamid Drake) was loosely inspired by saxophonist Albert Ayler, a prime influence on Brötzmann''s music. Beginning in 1997, he toured and recorded regularly with the Peter Brötzmann Chicago Tentet (initially an octet), which he disbanded after an ensemble performance in November 2012 in Strasbourg, France.\nBrötzmann also recorded or performed with Cecil Taylor, Keiji Haino, Willem van Manen, Mats Gustafsson, Ken Vandermark, Conny Bauer, Joe McPhee, Paal Nilssen-Love, with Oxbow, and with Caspar Brötzmann, his son.","Life":"Brötzmann was born in Remscheid on 6 March 1941. He studied painting in Wuppertal and was involved with the Fluxus movement but grew dissatisfied with art galleries and exhibitions. He experienced his first jazz concert when he saw American jazz musician Sidney Bechet while still in school at Wuppertal, and it made a lasting impression. He was also inspired by Miles Davis and John Coltrane.\nBrötzmann had not abandoned his art training, designing most of his album covers. He taught himself to play clarinet and saxophone, and is also known for playing the tárogató. Among his first musical partnerships was with double bassist Peter Kowald. For Adolphe Sax, Brötzmann''s first recording, was released in 1967 and featured Kowald and drummer Sven-Åke Johansson. In 1968, Machine Gun, an octet recording, was released. The album was self-produced under his BRO record label imprint and sold at concerts, and later marketed by FMP. In 2007, Atavistic reissued Machine Gun. \"Machine Gun\" was a nickname Don Cherry gave him \"to describe his violent style\".\nBrötzmann died on 22 June 2023, at the age of 82, at home in Wuppertal, Germany.","Career":"The album Nipples was recorded in 1969 with many of the Machine Gun musicians, including drummer Han Bennink, pianist Fred Van Hove, tenor saxophonist Evan Parker, and British guitarist Derek Bailey. The second set of takes from these sessions, called More Nipples, is more raucous. Fuck de Boere (dedicated to Johnny Dyani) is a live album of free sessions from these early years, containing two long improvisations, a 1968 recording of \"Machine Gun\" live (earlier than the studio version) and a longer jam from 1970. Brötzmann was a member of Bennink''s Instant Composers Pool, a collective of musicians who released their own records and that grew into a 10-piece orchestra.\nThe logistics of touring with the ICP tentet or his octet resulted in Brötzmann reducing the group to a trio with Han Bennink and Fred Van Hove. Bennink was a partner in Schwarzwaldfahrt, an album of duets recorded outside in the Black Forest in 1977, with Bennink drumming on trees and other objects in the woods.\nIn 1981, Brötzmann made a radio broadcast with Frank Wright and Willem Breuker (saxophones), Toshinori Kondo (trumpet), Hannes Bauer and Alan Tomlinson (trombones), Alexander von Schlippenbach (piano), Louis Moholo (drums), and Harry Miller (bass). This was released as the album Alarm.\nIn the 1980s, Brötzmann''s music was influenced by heavy metal and noise rock. He was a member of Last Exit and recorded music with the band''s bass guitarist and producer Bill Laswell.\nBrötzmann on tenor saxophone, Minnesota Sur Seine, 2006\nBrötzmann at the Sonore concert, Lviv, December 2008\nBrötzmann released over fifty albums as a bandleader and appeared on dozens more. His \"Die Like a Dog Quartet\" (with Toshinori Kondo, William Parker, and drummer Hamid Drake) was loosely inspired by saxophonist Albert Ayler, a prime influence on Brötzmann''s music. Beginning in 1997, he toured and recorded regularly with the Peter Brötzmann Chicago Tentet (initially an octet), which he disbanded after an ensemble performance in November 2012 in Strasbourg, France.\nBrötzmann also recorded or performed with Cecil Taylor, Keiji Haino, Willem van Manen, Mats Gustafsson, Ken Vandermark, Conny Bauer, Joe McPhee, Paal Nilssen-Love, with Oxbow, and with Caspar Brötzmann, his son."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (260, '1WmIo9ORq1IDlovUWFmo4Y', 'Peter', 'Erskine', '3086927c-e46f-4200-9c57-fb615ac8da2c', 257421, 4, 'https://en.wikipedia.org/wiki/Peter_Erskine', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Lee_Ritenour_with_Larry_Goldings_and_Peter_Erskine_%40_Dimitriou%27s_Jazz_Alley_%289572851583%29.jpg/500px-Lee_Ritenour_with_Larry_Goldings_and_Peter_Erskine_%40_Dimitriou%27s_Jazz_Alley_%289572851583%29.jpg', 'Johan Broberg from Seattle, United States', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Lee_Ritenour_with_Larry_Goldings_and_Peter_Erskine_@_Dimitriou%27s_Jazz_Alley_(9572851583).jpg', '{"Intro":"Peter Clark Erskine (born June 5, 1954) is an American jazz drummer who was a member of the jazz fusion groups Weather Report and Steps Ahead.","Early Life And Education":"Erskine was born in Somers Point, New Jersey, U.S. He began playing the drums at the age of four. He graduated from the Interlochen Arts Academy in Michigan and then studied percussion at Indiana University.","Career":"His professional music career started in 1972 when he joined the Stan Kenton Orchestra. After four years with Kenton, he joined Maynard Ferguson for two years. In 1978, he joined Weather Report, joining Jaco Pastorius in the rhythm section. After four years and five albums with Weather Report and the Jaco Pastorius big band''s Word of Mouth, he joined Steps Ahead.\nIn 1983, he performed on the Antilles Records release Swingrass ''83. He toured the US in 1992 with Chick Corea.\nErskine splits his time as a musician and a professor at the Thornton School of Music at the University of Southern California.\nHe was featured on Kate Bush''s 2005 album Aerial, where Erskine teamed with bass player Eberhard Weber. Diana Krall, Eliane Elias, Queen Latifah and Linda Ronstadt, as well as Scottish and Finnish classical orchestras, have had Erskine perform as a featured musician.\nIn 2011, he appeared on stage at the Royal Opera House, London in the new opera Anna Nicole.","Personal Life":"Erskine is married to Mutsuko Erskine. The two have two children, actress and writer Maya Erskine, and film editor and producer Taichi Erskine."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (261, '1WmIo9ORq1IDlovUWFmo4Y', 'Pharoah', 'Sanders', 'b3a0912a-a62a-4388-9368-7cb21ed5caf9', 21147, 6, 'https://en.wikipedia.org/wiki/Pharoah_Sanders', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Pharoah_Sanders_photo.jpg/500px-Pharoah_Sanders_photo.jpg', 'Dmitry Scherbie New York', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Pharoah_Sanders_photo.jpg', '{"Intro":"Pharoah Sanders (born Ferrell Lee Sanders; October 13, 1940 – September 24, 2022) was an American jazz saxophonist. Known for his overblowing, harmonic, and multiphonic techniques on the saxophone, as well as his use of \"sheets of sound\", Sanders played a prominent role in the development of free jazz and spiritual jazz through his work as a member of John Coltrane''s groups in the mid-1960s, and later through his solo work. He released more than thirty albums as a leader and collaborated extensively with vocalist Leon Thomas and pianist Alice Coltrane, among many others. Fellow saxophonist Ornette Coleman once described him as \"probably the best tenor player in the world\".\nSanders'' take on spiritual jazz was rooted in his inspiration from religious concepts such as karma and tawhid, and his rich, meditative performance aesthetic. This style was seen as a continuation of Coltrane''s work on albums such as A Love Supreme. As a result, Sanders was considered to have been a disciple of Coltrane or, as Albert Ayler said, \"Trane was the Father, Pharoah was the Son, I am the Holy Ghost\".","Early Life":"Pharoah Sanders was born on October 13, 1940, in Little Rock, Arkansas. His mother worked as a cook in a school cafeteria, and his father worked for the City of Little Rock. An only child, Sanders began his musical career accompanying church hymns on clarinet. His initial artistic accomplishments were in the visual arts, but when he was at Scipio Jones High School in North Little Rock, Sanders began playing the tenor saxophone.\nAfter graduating from high school in 1959, Sanders moved to Oakland, California, where he lived with relatives. He briefly studied art and music at Oakland City College. He earned a Bachelor of Fine Arts from an unknown art institution.","Career":"Sanders performing at The Jazz Cafe in London, England, 2008\nPharoah Sanders began his professional career playing tenor saxophone in Oakland, then moved to New York City in 1962. Sun Ra''s biographer wrote that Sanders was often homeless and Ra gave him a place to live, clothes, and encouraged him to use the name \"Pharoah\". According to Sanders himself, his grandmother had wanted to name him after the pharaohs in the Bible but chose \"Ferrell\" instead. Sanders chose \"Pharoah\" as an artist name upon joining the New York musicians'' union. Initially it was sometimes misspelled as \"pharaoh\".\nBy 1963, he was playing with musicians such as Billy Higgins and Don Cherry and had caught the attention of Eric Dolphy and John Coltrane. In 1965, he became a member of Coltrane''s band, as the latter gravitated towards the avant-garde jazz of Albert Ayler, Sun Ra, and Cecil Taylor. Sanders first recorded with Coltrane on Ascension (recorded in June 1965), then on their dual-tenor album Meditations (recorded in November 1965). After this, Sanders joined Coltrane''s final quintet, usually playing long, dissonant solos. Coltrane''s later style was influenced by Sanders.\nAlthough Sanders'' musical voice developed differently from John Coltrane''s, Sanders was influenced by their collaboration. Spiritual elements, such as the chanting in Om, would later show up in many of Sanders'' own works. Sanders would also go on to produce much free jazz, modified from Coltrane''s solo-centric conception. In 1968, he participated in Michael Mantler and Carla Bley''s Jazz Composer''s Orchestra Association album The Jazz Composer''s Orchestra, featuring Cecil Taylor, Don Cherry, Larry Coryell, and Gato Barbieri.\nPharoah''s first album, Pharoah''s First, was not what he expected. The musicians playing with him were much more straightforward than Sanders, which made their respective solos a bit out of place. Starting in 1966, Sanders signed with  Impulse! and recorded Tauhid, released the following year.  The years Sanders spent with the label were both a commercial and critical success.\nIn the 1970s, Sanders continued to produce his own recordings and also continued to work with Alice Coltrane on Journey in Satchidananda. Most of Sanders'' best-selling work was made in the late 1960s and early 1970s for Impulse!. Notably including the 30-minute, wave-on-wave \"The Creator Has a Master Plan\" from the spiritual free-jazz album Karma. This composition featured vocalist Leon Thomas''s unique, \"umbo weti\" yodeling, and Sanders'' key musical partner, pianist Lonnie Liston Smith, who worked with Sanders from 1969 to 1971. Other members of his groups in this period include bassist Cecil McBee, on albums such as Jewels of Thought, Izipho Zam, Deaf Dumb Blind, and Thembi.\nAlthough supported by African-American radio, Sanders'' brand of brave free jazz became less popular. From the experiments with African rhythms on the 1971 album Black Unity (with bassist Stanley Clarke) onwards he began to diversify his sound. In the late 1970s and 1980s, Sanders explored different musical modes including R&B (Love Will Find a Way), modal jazz, and hard bop. Sanders left Impulse! in 1973 and explored various other labels, such as Theresa in 1980, which was sold to Evidence in 1991.\nA 1979 recording titled Ed Kelly and Friend, which Sanders completed for Theresa Records was reissued in 1992 under Evidence (Ed Kelly and Pharoah Sanders). The 1992 reissue contained extra tracks which featured Pharoah''s pupil Robert Stewart. In 1994, Sanders traveled to Morocco to record the Bill Laswell-produced album The Trance Of Seven Colors with Gnawa musician Mahmoud Guinia. That same year, he appeared on the Red Hot Organization album Stolen Moments: Red Hot + Cool with the track \"This is Madness\" with Umar Bin Hassan and Abiodun Oyewole and with the bonus track \"The Creator Has A Master Plan (Trip Hop Remix).\"  The album was named \"Album of the Year\" by Time. He also collaborated with drummer–composer Franklin Kiermyer on Kiermyer''s album Solomon''s Daughter, which was also released on the Evidence label (re-released with 3 previously unreleased tracks on the Dot Time label in 2019).\nSanders'' major-label return came in 1995 with Message from Home under Verve Records. This was followed by Save Our Children (1998). In both, Sanders worked with Laswell, Jah Wobble, and others. Again, however. Sanders'' distaste with the recording business prompted him to leave the label. In 1997 he was featured on several Tisziji Muñoz albums which include Rashied Ali. In 1999, in an interview, he mentioned his trouble finding work, despite his artistic pedigree.\nIn the 2000s, a resurgence of interest in jazz kept Sanders playing concerts, releasing albums and playing festivals, including the 2004 Bluesfest Byron Bay, the 2007 Melbourne Jazz Festival, and the 2008 Big Chill Festival.\nIn 2000, Sanders released Spirits. In 2003, he recorded with the Japanese band Sleep Walker (He has a strong following in Japan). That same year, he released a live album titled The Creator Has a Master Plan (not to be confused with the single). He was awarded a National Endowment for the Arts Jazz Masters Fellowship in 2016 and was honored at a tribute concert in Washington DC on April 4, 2016.\nIn 2020, Sanders recorded an album titled Promises, with the English electronic music producer Floating Points and the London Symphony Orchestra. It was released in March 2021, the first major new album by Sanders in nearly two decades. It was widely acclaimed, with Pitchfork declaring it \"a clear late-career masterpiece\". Promises was the last album Sanders released before his death.\nSanders died on September 24, 2022, at his home in Los Angeles, at the age of 81. It was disclosed publicly by Luaka Bop. A cause of death was not specified.","Death":"Sanders died on September 24, 2022, at his home in Los Angeles, at the age of 81. It was disclosed publicly by Luaka Bop. A cause of death was not specified."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (262, '1WmIo9ORq1IDlovUWFmo4Y', 'Phil', 'Woods', 'df555225-0856-4cd9-ae46-b4734ee1418d', 253777, 6, 'https://en.wikipedia.org/wiki/Phil_Woods', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Phil_Woods_1978.jpg/500px-Phil_Woods_1978.jpg', 'Tom Marcello Webster, New York, USA', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Phil_Woods_1978.jpg', '{"Intro":"Philip Wells Woods (November 2, 1931 – September 29, 2015) was an American jazz alto saxophonist, clarinetist, bandleader, and composer.","Biography":"Woods was born in Springfield, Massachusetts. After inheriting a saxophone at age 12, he began taking lessons from Harvey LaRose at a local music shop. His heroes on the alto saxophone included Benny Carter and Johnny Hodges. He studied music with Lennie Tristano at the Manhattan School of Music and at the Juilliard School. His friend, Joe Lopes, coached him on clarinet as there was no saxophone major at Juilliard at the time and received a bachelor’s degree in 1952. Although he did not copy Charlie Parker, Woods was known as the New Bird, a nickname also given to other alto saxophone players such as Sonny Stitt and Cannonball Adderley.\nIn the 1950s, Woods began to lead his own bands. Quincy Jones invited him to accompany Dizzy Gillespie on a world tour sponsored by the U.S. State Department. A few years later he toured Europe with Jones, and in 1962 he toured Russia with Benny Goodman.\nAfter moving to France in 1968, Woods led the European Rhythm Machine, which tended toward avant-garde jazz. He returned to the United States in 1972 and, after an unsuccessful attempt to establish an electronic group, he formed a quintet, which was still performing, with some changes of personnel, in 2004. As his theme, Woods used a piece titled \"How''s Your Mama?\"\nWoods earned the top alto sax player award almost 30 times in DownBeat magazine''s annual readers'' poll. His quintet was awarded the top small combo title several times.\nIn 1979, Woods recorded the album More Live at Armadillo World Headquarters in Austin, Texas. His best known recorded work as a sideman is a pop piece, his alto sax solo on Billy Joel''s 1977 \"Just the Way You Are\". He also played the alto sax solo on Steely Dan''s \"Doctor Wu\" from their 1975 album Katy Lied, as well as Paul Simon''s \"Have a Good Time\" from the 1975 album Still Crazy After All These Years.\nAlthough Woods was primarily a saxophonist, he was also a clarinet player, and solos are scattered through his recordings. One example is his clarinet solo on \"Misirlou\" on the compilation album, Into the Woods.\nWoods, along with Rick Chamberlain and Ed Joubert, founded the organization Celebration of the Arts (COTA) in 1978 late one night in the bar at the Deer Head Inn in Delaware Water Gap, Pennsylvania. The organization would eventually become the Delaware Water Gap Celebration of the Arts. Their initial goal was to help foster an appreciation of jazz and its relationship to other artistic disciplines. Each year, the organization hosts the Celebration of the Arts Festival in September.\nIn 2005, Jazzed Media released the documentary Phil Woods: A Life in E Flat – Portrait of a Jazz Legend, directed by Rich Lerner and produced by Graham Carter.\nWoods was married to Chan Parker, the common-law wife of Charlie Parker, for seventeen years and was the stepfather to Chan''s daughter, Kim. They divorced in 1973. In 1985, he married Jill Goodwin, the sister of his drummer Bill Goodwin. On September 4, 2015, he performed a tribute to Charlie Parker with Strings at the Manchester Craftsmen''s Guild and announced at the end of the show that he would be retiring. He died a little more than three weeks later of emphysema on September 29, 2015, at the age of 83."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (263, '1WmIo9ORq1IDlovUWFmo4Y', 'Philly Joe', 'Jones', '53717b9b-62ab-4d83-94dd-e559164e10dc', 257251, 4, 'https://en.wikipedia.org/wiki/Philly_Joe_Jones', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Philly_Joe_Jones_Advertisement.jpg/500px-Philly_Joe_Jones_Advertisement.jpg', 'Gretsch Drums', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Philly_Joe_Jones_Advertisement.jpg', '{"Intro":"Joseph Rudolph \"Philly Joe\" Jones (July 15, 1923 – August 30, 1985) was an American jazz drummer. He was noted for being able to adjust his style of playing to allow for any group or individual''s needs.","Biography":"As a child, Jones appeared as a featured tap dancer on The Kiddie Show on the Philadelphia radio station WIP. He was in the US Army during World War II.\nIn 1947 he became the house drummer at Café Society in New York City, where he played with the leading bebop players of the day, including Tadd Dameron. From 1955 to 1958, Jones toured and recorded with the Miles Davis Quintet – a band that became known as \"the Quintet\" (along with Red Garland on piano, John Coltrane on sax, and Paul Chambers on bass). Davis acknowledged that Jones was his favorite drummer, and stated in his autobiography that he would always listen for Jones in other drummers.\nFrom 1958, Jones worked as a leader, but continued to work as a sideman with other musicians, including Bill Evans and Hank Mobley. Evans, like Davis, also openly stated that Jones was his all-time favorite drummer.\nBetween late 1967 and 1972 Jones lived in London and Paris, performing and recording with musicians including Archie Shepp, Mal Waldron and Hank Mobley. For two years (1967–1969) Jones taught at a specially organized school in Hampstead, London, but was prevented from otherwise working in the UK by the Musicians'' Union. His 1968 album Mo'' Joe (also released as Trailways Express) was recorded in London with local musicians (including Peter King, Harold McNair, Chris Pyne, Kenny Wheeler and others).\nJones toured with Bill Evans in 1976 and 1978, recorded for Galaxy in 1977–1979, and made studio and live recordings with Red Garland in 1977. In 1981, Jones helped to found the group Dameronia, dedicated to the music of the composer Tadd Dameron, and led it until Jones'' death from a heart attack in 1985.","Early Career":"As a child, Jones appeared as a featured tap dancer on The Kiddie Show on the Philadelphia radio station WIP. He was in the US Army during World War II.\nIn 1947 he became the house drummer at Café Society in New York City, where he played with the leading bebop players of the day, including Tadd Dameron. From 1955 to 1958, Jones toured and recorded with the Miles Davis Quintet – a band that became known as \"the Quintet\" (along with Red Garland on piano, John Coltrane on sax, and Paul Chambers on bass). Davis acknowledged that Jones was his favorite drummer, and stated in his autobiography that he would always listen for Jones in other drummers.\nFrom 1958, Jones worked as a leader, but continued to work as a sideman with other musicians, including Bill Evans and Hank Mobley. Evans, like Davis, also openly stated that Jones was his all-time favorite drummer.","Later Years":"Jones toured with Bill Evans in 1976 and 1978, recorded for Galaxy in 1977–1979, and made studio and live recordings with Red Garland in 1977. In 1981, Jones helped to found the group Dameronia, dedicated to the music of the composer Tadd Dameron, and led it until Jones'' death from a heart attack in 1985."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (264, '1WmIo9ORq1IDlovUWFmo4Y', 'Phineas', 'Newborn', 'e77a6903-a064-4048-b9b9-0a240b6d10c9', 824909, 3, 'https://en.wikipedia.org/wiki/Phineas_Newborn_Jr.', NULL, NULL, NULL, NULL, '{"Intro":"Phineas Newborn Jr. (December 14, 1931 – May 26, 1989) was an American jazz pianist, whose principal influences were Art Tatum, Oscar Peterson, and Bud Powell.","Biography":"Newborn was born in Whiteville, Tennessee, and came from a musical family: his father, Phineas Newborn Sr., was a drummer in blues bands, and his younger brother, Calvin, a jazz guitarist. He studied piano as well as trumpet, and tenor and baritone saxophone.\nBefore moving on to work with Lionel Hampton, Charles Mingus, and others, Newborn first played in an R&B band led by his father on drums, with his brother Calvin on guitar, Tuff Green on bass, Ben Branch and future Hi Records star Willie Mitchell. The group was the house band at the now famous Plantation Inn Club in West Memphis, Arkansas, from 1947 to 1951, and recorded as B. B. King''s band on his first recordings in 1949, as well as the Sun Records sessions in 1950. They left West Memphis in 1951 to tour with Jackie Brenston as the \"Delta Cats\" in support of the record \"Rocket 88\", recorded by Sam Phillips and considered by many to be the first ever rock & roll record (it was the first Billboard No. 1 record for Chess Records).\nAmong his earliest recordings, from the early 1950s, are those for Sun Records with blues harmonica player Big Walter Horton.\nIn 1956, Newborn began to perform in New York City, recording his first album as a leader in that year, Here Is Phineas for Atlantic Records. His trios and quartets at that time included his brother Calvin on guitar, bassists Oscar Pettiford, George Joyner and drummers Kenny Clarke and Philly Joe Jones. Newborn created enough interest internationally to work as a solo pianist in Stockholm, Sweden, in 1958 and in Rome, Italy, the following year. He drew much critical acclaim, for both his leonine technique and meticulously artful playing at any tempo. The most often-noted feature of Newborn''s playing is fast-tempo parallel improvisation, two octaves apart in the manner of Oscar Peterson, which requires great ambidexterity.\nOn March 16, 1960, 29-year-old Newborn replaced Thelonious Monk and performed \"It''s All Right with Me\" on the ABC-TV series Music for a Spring Night. Newborn moved to Los Angeles that year, and recorded a sequence of piano trio albums for the Contemporary label. Critics often noted his playing style as being too technical, and Newborn developed emotional problems as a result. He was admitted to the Camarillo State Mental Hospital for some periods, and suffered a nervous breakdown related to conflicts with a record label during his career. Newborn later sustained a hand injury that hindered his playing.\nNewborn''s later work was intermittent due to ongoing health problems. This is most true of the period from the mid-1960s to mid-1970s when he faded from view, underappreciated and underrecorded. He made a partial comeback in the late 1970s and early 1980s, although this return ultimately failed to benefit his financial situation. He died in 1989 after the discovery of a growth on his lungs and was buried in Memphis National Cemetery.","Legacy":"According to jazz historian Nat Hentoff, Newborn''s plight spurred the 1989 founding of the Jazz Foundation of America, a group dedicated to helping with the medical bills and other financial needs of retired jazz greats. In the early 1990s the four-player Contemporary Piano Ensemble was formed by pianists Harold Mabern, James Williams, Mulgrew Miller, and Geoff Keezer to pay tribute to Newborn; it recorded two albums and toured internationally."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (265, '1WmIo9ORq1IDlovUWFmo4Y', 'Pops', 'Foster', '6c097081-53d9-417f-a169-2eface036ca7', 307454, 1, 'https://en.wikipedia.org/wiki/Pops_Foster', NULL, NULL, NULL, NULL, '{"Intro":"George Murphy \"Pops\" Foster (May 19, 1892 – October 30, 1969) was an American jazz musician, best known for his vigorous slap bass playing of the string bass. He also played the tuba and trumpet professionally.","Biography":"Foster was born to Charley and Annie Foster, who \"was nearly fullblooded Cherokee,\" on a plantation near McCall in Ascension Parish near Donaldsonville in south Louisiana, United States. His family moved to New Orleans when he was about 10 years of age. His older brother, Willard Foster, began playing banjo and guitar; George started out on a cello then switched to string bass. Foster married twice: to Bertha Foster in 1912 and Alma Foster in 1936.\nPops Foster was playing professionally by 1907 and worked with Jack Carey, Kid Ory, Armand Piron, King Oliver and other prominent hot bands of the era. In 1921, he moved to St. Louis, Missouri, to play with the Charlie Creath and Dewey Jackson bands, in which he would be active for much of the decade. He also joined Ory in Los Angeles. He acquired the nickname \"Pops\" because he was far older than any of the other players in the band.\nIn 1929, Foster moved to New York City, where he played with the bands of Luis Russell and Louis Armstrong through 1940. He gigged with New York-based bands through the 1940s, including those of Sidney Bechet, Art Hodes, and regularly participated in the national This Is Jazz radio program. He recorded with the Mezzrow-Bechet Quintet (Bechet, Mezz Mezzrow, Fitz Weston, and Kaiser Marshall) and Septet (on two consecutive dates in 1945, with Hot Lips Page (as Pappa Snow White), Sammy Price (as Jimmy Blythe Jr.), Danny Barker and Sid Catlett, and on the second session with Cousin Joe on vocals).\nIn the late 1940s, he began touring more widely and played in many countries in Europe, especially in France, and throughout the United States including returns to New Orleans and California.\nThe Autobiography of Pops Foster was published in 1971, with a new edition in 2005. Foster is quoted, \"Some of the books are fouled up on the times in New Orleans\", \"and some of the guys weren''t telling the truth.\" \"The critics and guys who write about jazz think they know more about what went on in New Orleans than the guys that were there.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (266, '1WmIo9ORq1IDlovUWFmo4Y', 'Quincy', 'Jones', '5803c81e-739a-4057-9a5c-cf84e55db630', 17546, 13, 'https://en.wikipedia.org/wiki/Quincy_Jones', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Quincy_jones_1980_%28cropped%29.jpg/500px-Quincy_jones_1980_%28cropped%29.jpg', 'Los Angeles Times', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Quincy_jones_1980_(cropped).jpg', '{"Intro":"Quincy Delight Jones Jr. (March 14, 1933 – November 3, 2024) was an American record producer, composer, arranger, record executive, conductor, trumpeter, film and television producer, and bandleader. During his seven-decade career, he received dozens of accolades, including 28 Grammy Awards, a Primetime Emmy Award, and a Tony Award as well as nominations for seven Academy Awards and four Golden Globe Awards.\nJones came to prominence in the 1950s as a jazz arranger and conductor before producing pop hit records for Lesley Gore in the early 1960s (including \"It''s My Party\") and serving as an arranger and conductor for several collaborations between Frank Sinatra and the jazz artist Count Basie. Jones produced three of the most successful albums by Michael Jackson: Off the Wall (1979), Thriller (1982), and Bad (1987). In 1985, Jones produced and conducted the charity song \"We Are the World\", which raised funds for victims of famine in Ethiopia.\nJones composed numerous film scores including for The Pawnbroker (1965), In the Heat of the Night, In Cold Blood (both 1967), The Italian Job (1969), The Wiz (1978), and The Color Purple (1985). He won the Primetime Emmy Award for Outstanding Music Composition for a Series for the miniseries Roots (1977) and received a Tony Award for Best Revival of a Musical as a producer for the revival of The Color Purple (2016).\nJones received many honorary awards, including the Grammy Legend Award in 1992, the Jean Hersholt Humanitarian Award in 1995, the Kennedy Center Honors in 2001, the National Medal of the Arts in 2011, the Ordre des Arts et des Lettres in 2014, and the Academy Honorary Award in June 2024. He was named one of the most influential jazz musicians of the 20th century by Time.","Early Life And Education":"Quincy Delight Jones Jr. was born in the South Side of Chicago on March 14, 1933, the elder of two sons to Sara Frances (née Wells; Later Taylor; 1904–1999), a bank officer and apartment complex manager, and Quincy Delight Jones (1895–1971), a semi-professional baseball player and carpenter from Charleston, South Carolina. Quincy Jr.''s paternal grandmother was an ex-slave from Louisville, and he later discovered that his paternal grandfather was Welsh.\nFurthermore, Jones said, \"He had a baby with my great-grandmother , and my  grandmother was born there . We traced this all the way back to the Laniers, the same family as Tennessee Williams.\" Learning that the Lanier immigrant ancestors were French Huguenots who had court musicians among their ancestors, Jones attributed some of his musicianship to them.\nFor the 2006 PBS television program African American Lives, Jones had his DNA tested and genealogists researched his family history again. His DNA revealed he was mostly African, but also had 34% European ancestry on both sides of his family. Research showed that he had English, French, Italian, and Welsh ancestry through his father. His mother''s side was of West and Central African descent, specifically from the Tikar people of Cameroon. His mother also had European ancestry, including Lanier male ancestors who fought for the Confederacy, making him eligible for membership in the Sons of Confederate Veterans. Among his ancestors was Elizabeth Washington Lewis, a sister of president George Washington.\nJones''s family moved to Chicago during the Great Migration. Jones had a younger brother, Lloyd, who was an engineer for the Seattle television station KOMO-TV until his death in 1998. Jones was introduced to music by his mother who always sang religious songs, and next-door neighbor Lucy Jackson. When Jones was five or six, Jackson played stride piano next door, and he would listen through the walls. Jackson recalled that after he heard her playing one day, she could not get him off her piano.\nWhen Jones was young, his mother had a schizophrenic breakdown and was sent to a mental institution. His father divorced her and married Elvera Jones, who already had three children: Waymond, Theresa, and Katherine. Elvera and Quincy Sr. had three more children together: Jeanette, Margie, and Richard. The family moved to Sinclair Park, a segregated community in Bremerton, Washington, in 1943. Jones''s father took a wartime job at the Puget Sound Naval Shipyard.\nAfter the war, the family moved to Seattle, where Jones attended Garfield High School and developed his skills as a trumpeter and arranger. His classmates included Charles Taylor, who played saxophone and whose mother, Evelyn Bundy, was one of Seattle''s first society jazz bandleaders. Jones and Taylor began playing music together,\nAt the age of fourteen, Jones joined Taylor''s group playing Seattle''s Washington Social Club, the Black Elks Club, and all over the Northwest, backing Billie Holiday and Billy Eckstine. He met Ray Charles, then an unknown 16-year-old musician from Florida going by R.C. Robinson, playing bebop piano and alto sax and singing like Nat Cole.\nJones credited his father''s sturdy work ethic with giving him the means to proceed, and his loving nature with holding the family together. Jones cited his father''s rhyming motto: \"Once a task is just begun, never leave until it''s done. Be the labor great or small, do it well or not at all.\"\nJones earned a scholarship to Seattle University in 1951. After one semester, he transferred to what is now the Berklee College of Music in Boston on another scholarship, where he played at Izzy Ort''s Bar & Grille with Bunny Campbell and Preston Sandiford, whom he cited as important influences.","Career":"1953–1960: Career beginnings with jazz music\nIn 1953, at age 20, Jones traveled with jazz bandleader Lionel Hampton for a European tour of the Hampton orchestra. He said the tour changed his view of racism in the United States, \"It gave you some sense of perspective on past, present, and future. It took the myopic conflict between just black and white in the United States and put it on another level because you saw the turmoil between the Armenians and the Turks, and the Cypriots and the Greeks, and the Swedes and the Danes, and the Koreans and the Japanese. Everybody had these hassles, and you saw it was a basic part of human nature, these conflicts. It opened my soul; it opened my mind.\"\nAfter leaving the Hampton band in 1954, Jones settled in New York, and started writing \"for anyone who would pay\". In early 1956, he accepted a temporary job at CBS'' Stage Show hosted by Jimmy and Tommy Dorsey that was broadcast live from Studio 50 in New York City (known today as the Ed Sullivan Theater). On January 28, February 4, 11 and 18, as well as on March 17 and 24, Jones played second trumpet in the studio band that supported 21-year-old Elvis Presley in his first six television appearances. Presley sang \"Heartbreak Hotel\", which became his first No. 1 record and the Billboard magazine Pop Record of the year. Soon after, as a trumpeter and musical director for Dizzy Gillespie, Jones went on tour of the Middle East and South America sponsored by the United States Information Agency. After returning, he signed a contract with ABC-Paramount and started his recording career as the leader of his band. In 1957, he moved to Paris, where he studied composition and theory with Nadia Boulanger and Olivier Messiaen and performed at the Paris Olympia. Jones became music director at Barclay, a French record company (and the licensee for Mercury in France).\nIn the 1950s, Jones toured Europe with several jazz orchestras. As musical director of Harold Arlen''s jazz musical Free and Easy, he took to the road again. With musicians from the Arlen show, he formed his big band, The Jones Boys, with eighteen musicians. The band included double bass player Eddie Jones and trumpeter Reunald Jones. None of the three were related. The band toured North America and Europe, and the concerts met enthusiastic audiences and sparkling reviews, but the earnings failed to support a band of this size. Poor budget planning resulted in an economic disaster. The band dissolved, leaving Jones in a financial crisis. \"We had the best jazz band on the planet, and yet we were literally starving. That''s when I discovered that there was music, and there was the music business. If I were to survive, I would have to learn the difference between the two.\" Irving Green, head of Mercury, helped Jones with a personal loan and a job as musical director of the company''s New York division.\nJones first worked with Frank Sinatra in 1958 when invited by Princess Grace to arrange a benefit concert at the Monaco Sporting Club. Six years later, Sinatra hired him to arrange and conduct Sinatra''s second album with Count Basie, It Might as Well Be Swing (1964). Jones conducted and arranged Sinatra''s live album with the Basie Band, Sinatra at the Sands (1966). Jones was also the arranger/conductor when Sinatra, Sammy Davis Jr., Dean Martin, and Johnny Carson performed with the Basie orchestra in June 1965 in St. Louis, Missouri, in a benefit for Dismas House. The fund-raiser was broadcast to movie theaters around the country and eventually released on VHS. Later that year, Jones was the arranger/conductor when Sinatra and Basie appeared on The Hollywood Palace TV variety show on October 16, 1965. Nineteen years later, Sinatra and Jones teamed up for the 1984 album L.A. Is My Lady. Jones said,\nFrank Sinatra took me to a whole new planet. I worked with him until he passed away in ''98. He left me his ring. I never take it off. Now, when I go to Sicily, I don''t need a passport. I just flash my ring.\nIn 1961, Jones was promoted and became the vice-president of Mercury, the first African American to hold the position. In 1963 he had his first number 1 record with \"It''s My Party\" by Lesley Gore. At the invitation of director Sidney Lumet, he composed music for The Pawnbroker (1964). It was the first of his nearly 40 major motion picture scores. Following the success of The Pawnbroker, Jones left Mercury and moved to Los Angeles. After composing film scores for Mirage and The Slender Thread in 1965, he was in constant demand as a composer.\nHis film credits over the next seven years came to include Walk, Don''t Run, The Deadly Affair, In Cold Blood, In the Heat of the Night, Mackenna''s Gold, The Italian Job, Bob & Carol & Ted & Alice, Cactus Flower, The Out-of-Towners, They Call Me Mister Tibbs!, The Anderson Tapes, $ (Dollars), and The Getaway. He composed \"The Streetbeater\", which became the theme music for the television sitcom Sanford and Son, starring his close friend Redd Foxx, and the themes for other TV shows, including Ironside, Rebop, Banacek, The Bill Cosby Show, the opening episode of Roots, Mad TV, and the game show Now You See It.\nIn the 1960s, Jones worked as an arranger for Billy Eckstine, Ella Fitzgerald, Shirley Horn, Peggy Lee, Nana Mouskouri, Frank Sinatra, Sarah Vaughan, and Dinah Washington. His solo recordings included Walking in Space, Gula Matari, Smackwater Jack, You''ve Got It Bad Girl, Body Heat, Mellow Madness, and I Heard That!!\nJones''s 1962 tune \"Soul Bossa Nova\", which originated on the Big Band Bossa Nova album, was later used as the theme for the 1997 spy comedy Austin Powers: International Man of Mystery.\nJones produced all four million-selling singles for Lesley Gore during the early and mid-1960s, including \"It''s My Party\" (UK No. 8; US No. 1), its sequel \"Judy''s Turn to Cry\" (US No. 5), \"She''s a Fool\" (also a US No. 5) in 1963, and \"You Don''t Own Me\" (US No. 2 for four weeks in 1964). He continued to produce for Gore until 1966, including notable hits like \"That''s the Way Boys Are\" (US No. 12 in 1964), the Greenwich/Barry hits \"Look of Love\" (US No. 27 in 1965) and \"Maybe I Know\" (UK No. 20; US No. 14 in 1964), \"Sunshine, Lollipops And Rainbows\" (No. 13 in 1965), and \"My Town, My Guy And Me\" (No. 32 in 1965).  In 1975, Jones founded Qwest Productions, for which he arranged and produced successful albums by Frank Sinatra and others. He also reunited with Lesley Gore that year, producing her critically acclaimed album Love Me By Name, released on A&M Records.\nJones with Michael Jackson at the 26th Annual Grammy Awards in 1984; he produced three of his albums: Off the Wall (1979), Thriller (1982) and Bad (1987).\nIn 1978, he produced the soundtrack for The Wiz, the musical adaptation of The Wizard of Oz, which starred Michael Jackson and Diana Ross. While working on The Wiz, Jackson asked Jones to recommend some producers for his upcoming solo album. Jones offered some names but eventually offered to produce the record himself. Jackson accepted and the resulting record, Off the Wall, sold about 20 million copies. This made Jones the most powerful record producer in the industry at that time. Jones and Jackson''s next collaboration, Thriller, sold 70 million copies and became the highest-selling album of all time. The rise of MTV and the advent of music videos as promotional tools also contributed to Thriller''s sales. Jones worked on Jackson''s album Bad, which sold 35 million copies, and was the last time they worked with each other. Audio interviews with Jones are included in the 2001 special editions of Off the Wall, Thriller, and Bad.\nHis 1981 album The Dude yielded the hits \"Ai No Corrida\" (a remake of a song by Chaz Jankel), \"Just Once\", and \"One Hundred Ways\", both sung by James Ingram. Marking Jones''s debut as a film producer, 1985''s The Color Purple received 11 Oscar nominations that year, including one for Jones''s score. Jones, Thomas Newman, and Alan Silvestri are the only composers besides John Williams to have written scores for a Steven Spielberg-directed theatrical feature film. Additionally, through this picture, Jones is credited with introducing Whoopi Goldberg and Oprah Winfrey to film audiences around the world.\nAfter the 1985 American Music Awards ceremony, Jones used his influence to draw most of the major American recording artists of the day into a studio to record the song \"We Are the World\" to raise money for the victims of famine in Ethiopia. When people marveled at his ability to make the collaboration work, Jones explained that he had taped a sign on the entrance reading \"Check Your Ego at the Door\". He was also quoted as saying, \"We don''t want to make a hunger record in tuxedos\", requiring all participants to wear casual clothing in the studio. In 1986, Jones started off Qwest Entertainment to produce theatrical feature films, through Qwest Film and Television. He launched a home video label, Qwest Home Video, in order to manage the home video titles made by the studio. Qwest Entertainment continued to operate their pre-existing subsidiaries like Qwest Records, Quincy Jones Productions and Qwest Music Publishing.\nIn 1990, Quincy Jones Productions joined with Time Warner to create Quincy Jones Entertainment (QJE). The company signed a 10-picture deal with Warner Bros. and a two-series deal with NBC Productions, now Universal Television. The television show The Fresh Prince of Bel-Air (Will Smith''s first acting credit) began in 1990, while In the House (on NBC and UPN) aired from 1995 to 1999. Jones also produced first-run syndication''s The Jenny Jones Show (in association with Telepictures Productions, 1994–1997 only) and FOX''s Mad TV, which ran for 14 seasons. In the early 1990s, he started a huge, ongoing project called \"The Evolution of Black Music\". QJE started a weekly talk show with Jones''s friend, Reverend Jesse Jackson, as the host.\nBeginning in the late 1970s, Jones had tried to convince Miles Davis to revive the music he recorded on several classic albums of the 1950s, which was arranged by Gil Evans. Davis always refused, citing a desire to avoid revisiting the past. In 1991, Davis relented. Despite having pneumonia, he agreed to perform the music at the Montreux Jazz Festival. The recording, Miles & Quincy Live at Montreux, was his last album; he died several months afterward. Jones had a brief appearance in the 1990 video for the Time song \"Jerk Out\", and was a guest actor on an episode of The Boondocks. He appeared with Ray Charles in the music video of their song \"One Mint Julep\" and also with Ray Charles and Chaka Khan in the music video of their song \"I''ll Be Good to You\". Jones hosted an episode of Saturday Night Live on February 10, 1990, during SNL''s 15th season. The episode was notable for having 10 musical guests, the most any SNL episode has had in its years on the air: Tevin Campbell, Andrae Crouch, Sandra Crouch, rappers Kool Moe Dee and Big Daddy Kane, Melle Mel, Quincy D III, Siedah Garrett, Al Jarreau, and Take 6, and for a performance of Dizzy Gillespie''s \"Manteca\" by the SNL Band, conducted by Jones. Jones impersonated Marion Barry, the former mayor of Washington, D.C., in the recurring sketch The Bob Waltman Special. He later produced his own sketch comedy show, FOX''s Mad TV, which ran from 1995 to 2009.\nJones during an annual meeting  of the World Economic Forum in Davos, Switzerland, January 2004\nIn 1993, Jones collaborated with David Salzman to produce the concert An American Reunion, a celebration of Bill Clinton''s inauguration as President of the United States. During the same year, he and Salzman renamed his company to Quincy Jones/David Salzman Entertainment.\nIn 2001, Jones published his autobiography Q: The Autobiography of Quincy Jones. In a 2002 interview, when asked if he would work with Jones again, Michael Jackson suggested he might. But in 2007, when Jones was asked by NME, he said: \"Man, please! We already did that. I have talked to him about working with him again but I''ve got too much to do. I''ve got 900 products, I''m 74 years old.\" Following Jackson''s death on June 25, 2009, Jones said, \"I am absolutely devastated at this tragic and unexpected news. For Michael to be taken away from us so suddenly at such a young age, I just don''t have the words. Divinity brought our souls together on The Wiz and allowed us to do what we were able to throughout the ''80s. To this day, the music we created together on Off the Wall, Thriller and Bad is played in every corner of the world, and the reason for that is because he had it all ... talent, grace, professionalism, and dedication. He was the consummate entertainer, and his contributions and legacy will be felt upon the world forever. I''ve lost my little brother today, and part of my soul has gone with him.\"\nJones appeared in the 1999 Walt Disney Pictures animated film Fantasia 2000, introducing the set piece of George Gershwin''s Rhapsody in Blue. In 2002, he made a cameo appearance as himself in the film Austin Powers in Goldmember. On February 10, 2008, Jones joined Usher in presenting the Grammy Award for Album of the Year to Herbie Hancock.\nOn January 6, 2009, Jones appeared on NBC''s Last Call with Carson Daly to discuss his career. Daly informally floated the idea that Jones should become the first minister of culture for the United States, pending the inauguration of Barack Obama as president. Daly noted that only the US and Germany, among leading world countries, did not have a cabinet-level position for this role. Commentators on NPR and in the Chronicle of Higher Education also discussed the topic of a minister of culture.\nIn July 2007, Jones partnered with Wizzard Media to start the Quincy Jones Video Podcast. In each episode, he shares his knowledge and experience in the music industry. The first episode features him in the studio producing \"I Knew I Loved You\" for Celine Dion. This song is included on the Ennio Morricone tribute album We All Love Ennio Morricone. Jones helped produce Anita Hall''s 2009 album Send Love. In 2013, he produced Emily Bear''s album Diversity. After that, he produced albums for Grace, Justin Kauflin, Alfredo Rodríguez, Andreas Varady, and Nikki Yanofsky. He also became a mentor to Jacob Collier.\nIn 2010, Jones, along with brand strategist Chris Vance, co-founded Playground Sessions, a NY City-based developer of subscription software that teaches people to play the piano using interactive videos. Pianists Harry Connick Jr. and David Sides are among the company''s video instructors. Jones worked with Vance and Sides to develop the video lessons and incorporate techniques to modernize the instruction format.\nIn February 2014, Jones appeared in Keep on Keepin'' On, a documentary about his friend, jazz trumpeter and flugelhorn player Clark Terry. In the film, Terry introduces Jones to his protégé Justin Kauflin, whom Jones then signs to his band and label. In July 2014, Jones starred in a documentary film called The Distortion of Sound. He was featured on Jacob Collier''s YouTube cover of Michael Jackson''s \"P.Y.T. (Pretty Young Thing)\". On February 28, 2016, he and Pharrell Williams presented Ennio Morricone with the Oscar for Best Original Score. In August 2016, he and his music were featured at the BBC Proms in the Royal Albert Hall, London. In 2017, Jones and French producer Reza Ackbaraly started Qwest TV, the world''s first subscription video-on-demand (SVOD) service for jazz and eclectic music from around the world. The platform features a handpicked selection of ad-free concerts, interviews, documentaries, and exclusive, original content, all in HD or 4K.\nOn March 20, 2020, Jones appeared in a music video by Travis Scott and Young Thug for the song \"Out West\". In January 2022, Jones appeared on the album Dawn FM by Canadian singer the Weeknd, performing a monolog in the sixth track, \"A Tale by Quincy\".","1953–1960: Career Beginnings With Jazz Music":"In 1953, at age 20, Jones traveled with jazz bandleader Lionel Hampton for a European tour of the Hampton orchestra. He said the tour changed his view of racism in the United States, \"It gave you some sense of perspective on past, present, and future. It took the myopic conflict between just black and white in the United States and put it on another level because you saw the turmoil between the Armenians and the Turks, and the Cypriots and the Greeks, and the Swedes and the Danes, and the Koreans and the Japanese. Everybody had these hassles, and you saw it was a basic part of human nature, these conflicts. It opened my soul; it opened my mind.\"\nAfter leaving the Hampton band in 1954, Jones settled in New York, and started writing \"for anyone who would pay\". In early 1956, he accepted a temporary job at CBS'' Stage Show hosted by Jimmy and Tommy Dorsey that was broadcast live from Studio 50 in New York City (known today as the Ed Sullivan Theater). On January 28, February 4, 11 and 18, as well as on March 17 and 24, Jones played second trumpet in the studio band that supported 21-year-old Elvis Presley in his first six television appearances. Presley sang \"Heartbreak Hotel\", which became his first No. 1 record and the Billboard magazine Pop Record of the year. Soon after, as a trumpeter and musical director for Dizzy Gillespie, Jones went on tour of the Middle East and South America sponsored by the United States Information Agency. After returning, he signed a contract with ABC-Paramount and started his recording career as the leader of his band. In 1957, he moved to Paris, where he studied composition and theory with Nadia Boulanger and Olivier Messiaen and performed at the Paris Olympia. Jones became music director at Barclay, a French record company (and the licensee for Mercury in France).\nIn the 1950s, Jones toured Europe with several jazz orchestras. As musical director of Harold Arlen''s jazz musical Free and Easy, he took to the road again. With musicians from the Arlen show, he formed his big band, The Jones Boys, with eighteen musicians. The band included double bass player Eddie Jones and trumpeter Reunald Jones. None of the three were related. The band toured North America and Europe, and the concerts met enthusiastic audiences and sparkling reviews, but the earnings failed to support a band of this size. Poor budget planning resulted in an economic disaster. The band dissolved, leaving Jones in a financial crisis. \"We had the best jazz band on the planet, and yet we were literally starving. That''s when I discovered that there was music, and there was the music business. If I were to survive, I would have to learn the difference between the two.\" Irving Green, head of Mercury, helped Jones with a personal loan and a job as musical director of the company''s New York division.\nJones first worked with Frank Sinatra in 1958 when invited by Princess Grace to arrange a benefit concert at the Monaco Sporting Club. Six years later, Sinatra hired him to arrange and conduct Sinatra''s second album with Count Basie, It Might as Well Be Swing (1964). Jones conducted and arranged Sinatra''s live album with the Basie Band, Sinatra at the Sands (1966). Jones was also the arranger/conductor when Sinatra, Sammy Davis Jr., Dean Martin, and Johnny Carson performed with the Basie orchestra in June 1965 in St. Louis, Missouri, in a benefit for Dismas House. The fund-raiser was broadcast to movie theaters around the country and eventually released on VHS. Later that year, Jones was the arranger/conductor when Sinatra and Basie appeared on The Hollywood Palace TV variety show on October 16, 1965. Nineteen years later, Sinatra and Jones teamed up for the 1984 album L.A. Is My Lady. Jones said,\nFrank Sinatra took me to a whole new planet. I worked with him until he passed away in ''98. He left me his ring. I never take it off. Now, when I go to Sicily, I don''t need a passport. I just flash my ring.","1978–1989: Exploration Into Pop Music":"Jones with Michael Jackson at the 26th Annual Grammy Awards in 1984; he produced three of his albums: Off the Wall (1979), Thriller (1982) and Bad (1987).\nIn 1978, he produced the soundtrack for The Wiz, the musical adaptation of The Wizard of Oz, which starred Michael Jackson and Diana Ross. While working on The Wiz, Jackson asked Jones to recommend some producers for his upcoming solo album. Jones offered some names but eventually offered to produce the record himself. Jackson accepted and the resulting record, Off the Wall, sold about 20 million copies. This made Jones the most powerful record producer in the industry at that time. Jones and Jackson''s next collaboration, Thriller, sold 70 million copies and became the highest-selling album of all time. The rise of MTV and the advent of music videos as promotional tools also contributed to Thriller''s sales. Jones worked on Jackson''s album Bad, which sold 35 million copies, and was the last time they worked with each other. Audio interviews with Jones are included in the 2001 special editions of Off the Wall, Thriller, and Bad.\nHis 1981 album The Dude yielded the hits \"Ai No Corrida\" (a remake of a song by Chaz Jankel), \"Just Once\", and \"One Hundred Ways\", both sung by James Ingram. Marking Jones''s debut as a film producer, 1985''s The Color Purple received 11 Oscar nominations that year, including one for Jones''s score. Jones, Thomas Newman, and Alan Silvestri are the only composers besides John Williams to have written scores for a Steven Spielberg-directed theatrical feature film. Additionally, through this picture, Jones is credited with introducing Whoopi Goldberg and Oprah Winfrey to film audiences around the world.\nAfter the 1985 American Music Awards ceremony, Jones used his influence to draw most of the major American recording artists of the day into a studio to record the song \"We Are the World\" to raise money for the victims of famine in Ethiopia. When people marveled at his ability to make the collaboration work, Jones explained that he had taped a sign on the entrance reading \"Check Your Ego at the Door\". He was also quoted as saying, \"We don''t want to make a hunger record in tuxedos\", requiring all participants to wear casual clothing in the studio. In 1986, Jones started off Qwest Entertainment to produce theatrical feature films, through Qwest Film and Television. He launched a home video label, Qwest Home Video, in order to manage the home video titles made by the studio. Qwest Entertainment continued to operate their pre-existing subsidiaries like Qwest Records, Quincy Jones Productions and Qwest Music Publishing.","1990–2024: Established Career":"In 1990, Quincy Jones Productions joined with Time Warner to create Quincy Jones Entertainment (QJE). The company signed a 10-picture deal with Warner Bros. and a two-series deal with NBC Productions, now Universal Television. The television show The Fresh Prince of Bel-Air (Will Smith''s first acting credit) began in 1990, while In the House (on NBC and UPN) aired from 1995 to 1999. Jones also produced first-run syndication''s The Jenny Jones Show (in association with Telepictures Productions, 1994–1997 only) and FOX''s Mad TV, which ran for 14 seasons. In the early 1990s, he started a huge, ongoing project called \"The Evolution of Black Music\". QJE started a weekly talk show with Jones''s friend, Reverend Jesse Jackson, as the host.\nBeginning in the late 1970s, Jones had tried to convince Miles Davis to revive the music he recorded on several classic albums of the 1950s, which was arranged by Gil Evans. Davis always refused, citing a desire to avoid revisiting the past. In 1991, Davis relented. Despite having pneumonia, he agreed to perform the music at the Montreux Jazz Festival. The recording, Miles & Quincy Live at Montreux, was his last album; he died several months afterward. Jones had a brief appearance in the 1990 video for the Time song \"Jerk Out\", and was a guest actor on an episode of The Boondocks. He appeared with Ray Charles in the music video of their song \"One Mint Julep\" and also with Ray Charles and Chaka Khan in the music video of their song \"I''ll Be Good to You\". Jones hosted an episode of Saturday Night Live on February 10, 1990, during SNL''s 15th season. The episode was notable for having 10 musical guests, the most any SNL episode has had in its years on the air: Tevin Campbell, Andrae Crouch, Sandra Crouch, rappers Kool Moe Dee and Big Daddy Kane, Melle Mel, Quincy D III, Siedah Garrett, Al Jarreau, and Take 6, and for a performance of Dizzy Gillespie''s \"Manteca\" by the SNL Band, conducted by Jones. Jones impersonated Marion Barry, the former mayor of Washington, D.C., in the recurring sketch The Bob Waltman Special. He later produced his own sketch comedy show, FOX''s Mad TV, which ran from 1995 to 2009.\nJones during an annual meeting  of the World Economic Forum in Davos, Switzerland, January 2004\nIn 1993, Jones collaborated with David Salzman to produce the concert An American Reunion, a celebration of Bill Clinton''s inauguration as President of the United States. During the same year, he and Salzman renamed his company to Quincy Jones/David Salzman Entertainment.\nIn 2001, Jones published his autobiography Q: The Autobiography of Quincy Jones. In a 2002 interview, when asked if he would work with Jones again, Michael Jackson suggested he might. But in 2007, when Jones was asked by NME, he said: \"Man, please! We already did that. I have talked to him about working with him again but I''ve got too much to do. I''ve got 900 products, I''m 74 years old.\" Following Jackson''s death on June 25, 2009, Jones said, \"I am absolutely devastated at this tragic and unexpected news. For Michael to be taken away from us so suddenly at such a young age, I just don''t have the words. Divinity brought our souls together on The Wiz and allowed us to do what we were able to throughout the ''80s. To this day, the music we created together on Off the Wall, Thriller and Bad is played in every corner of the world, and the reason for that is because he had it all ... talent, grace, professionalism, and dedication. He was the consummate entertainer, and his contributions and legacy will be felt upon the world forever. I''ve lost my little brother today, and part of my soul has gone with him.\"\nJones appeared in the 1999 Walt Disney Pictures animated film Fantasia 2000, introducing the set piece of George Gershwin''s Rhapsody in Blue. In 2002, he made a cameo appearance as himself in the film Austin Powers in Goldmember. On February 10, 2008, Jones joined Usher in presenting the Grammy Award for Album of the Year to Herbie Hancock.\nOn January 6, 2009, Jones appeared on NBC''s Last Call with Carson Daly to discuss his career. Daly informally floated the idea that Jones should become the first minister of culture for the United States, pending the inauguration of Barack Obama as president. Daly noted that only the US and Germany, among leading world countries, did not have a cabinet-level position for this role. Commentators on NPR and in the Chronicle of Higher Education also discussed the topic of a minister of culture.\nIn July 2007, Jones partnered with Wizzard Media to start the Quincy Jones Video Podcast. In each episode, he shares his knowledge and experience in the music industry. The first episode features him in the studio producing \"I Knew I Loved You\" for Celine Dion. This song is included on the Ennio Morricone tribute album We All Love Ennio Morricone. Jones helped produce Anita Hall''s 2009 album Send Love. In 2013, he produced Emily Bear''s album Diversity. After that, he produced albums for Grace, Justin Kauflin, Alfredo Rodríguez, Andreas Varady, and Nikki Yanofsky. He also became a mentor to Jacob Collier.\nIn 2010, Jones, along with brand strategist Chris Vance, co-founded Playground Sessions, a NY City-based developer of subscription software that teaches people to play the piano using interactive videos. Pianists Harry Connick Jr. and David Sides are among the company''s video instructors. Jones worked with Vance and Sides to develop the video lessons and incorporate techniques to modernize the instruction format.\nIn February 2014, Jones appeared in Keep on Keepin'' On, a documentary about his friend, jazz trumpeter and flugelhorn player Clark Terry. In the film, Terry introduces Jones to his protégé Justin Kauflin, whom Jones then signs to his band and label. In July 2014, Jones starred in a documentary film called The Distortion of Sound. He was featured on Jacob Collier''s YouTube cover of Michael Jackson''s \"P.Y.T. (Pretty Young Thing)\". On February 28, 2016, he and Pharrell Williams presented Ennio Morricone with the Oscar for Best Original Score. In August 2016, he and his music were featured at the BBC Proms in the Royal Albert Hall, London. In 2017, Jones and French producer Reza Ackbaraly started Qwest TV, the world''s first subscription video-on-demand (SVOD) service for jazz and eclectic music from around the world. The platform features a handpicked selection of ad-free concerts, interviews, documentaries, and exclusive, original content, all in HD or 4K.\nOn March 20, 2020, Jones appeared in a music video by Travis Scott and Young Thug for the song \"Out West\". In January 2022, Jones appeared on the album Dawn FM by Canadian singer the Weeknd, performing a monolog in the sixth track, \"A Tale by Quincy\".","Personal Life":"Jones was married three times and had seven children with five women. He was married to Jeri Caldwell from 1957 to 1966, and they had a daughter named Jolie. He had a brief affair with Carol Reynolds, and they had a daughter named Rachel. He was later married to Swedish actress Ulla Andersson from 1967 to 1974, and they had a daughter named Martina and a son named Quincy, who also became a music producer.\nThe day after his divorce from Andersson, Jones married American actress Peggy Lipton. They had two daughters, Kidada, who was born before they were married, and Rashida, both of whom became actresses. Jones and Lipton divorced in 1990. He later dated and lived with German actress Nastassja Kinski from 1991 to 1995, and they had a daughter named Kenya, who became a fashion model. In an interview with New York Magazine Jones stated that he dated Ivanka Trump.\nIn 1994, rapper Tupac Shakur criticized Jones for having relationships with white women, prompting Jones''s daughter, Rashida, to pen a scathing open letter in response, which was published in The Source. Jones''s daughter, Kidada, developed a romantic relationship with Shakur, became engaged to him, and had been living with him for four months at the time of his death.\nJones never learned to drive. At age 14, he was riding to a rodeo in Yakima in a car with a group of friends when a bus hit them. He said everybody in the car died except him; the scene was gruesome and left him traumatized. He attempted to take driving lessons a few years later but he \"just couldn''t do it\" and never drove again.\nJones said that Ray Charles introduced him to heroin at the age of 15, and he stopped using it after five months.\nHe was a believer in astrology. He said in February 2018 that he believed in a God that opposes the love of money but dismissed the notion of an afterlife. He held a negative opinion of the Catholic Church, believing it is built upon the notions of money and \"fear, smoke, and murder\". Jones claimed to have knowledge of the truth of the Kennedy assassination, stating his belief that mobster Sam Giancana was involved.\nIn October 2013, the BBC and The Hollywood Reporter said Jones planned to sue Michael Jackson''s estate for $10 million. Jones said that MJJ Productions, a song company managed by Jackson''s estate and Sony Music Entertainment, improperly re-edited songs to deprive him of royalties and production fees and breached an agreement giving him the right to remix master recordings for albums released after Jackson''s death. The songs Jones produced for Jackson were used in the film This Is It. Jones was reported to be filing the suits against the Michael Jackson Cirque du Soleil shows and the 25th-anniversary edition of the Bad album. He believed he should have received a producer credit in the film.\nIn 1974, Jones developed a life-threatening brain aneurysm, leading to a decision to reduce his workload to spend time with his friends and family. Since his family and friends believed that Jones''s life was coming to an end, they started to plan a memorial service for him. He attended his own service with his neurologist by his side, in case the excitement overwhelmed him. Some of the entertainers at his service were Richard Pryor, Marvin Gaye, Sarah Vaughan, and Sidney Poitier.\nJones had two brain surgeries, and after the second was warned to never play the trumpet again, because \"if he blew a trumpet in the ways that a trumpet player must, the clip  would come free and he would die\". He ignored that advice, went on tour in Japan, and one night after playing trumpet had a pain in his head. Doctors said the plate in his brain had nearly come loose, as they had warned, and Jones never played the trumpet again.","Music Videos":"\"Love Is in Control (Finger on the Trigger)\"\n\"The Secret Garden (Sweet Seduction Suite)\"","Death":"On November 3, 2024, Jones died at his home in the Bel Air neighborhood of Los Angeles at the age of 91. His publicist confirmed his death. The cause of death was not immediately disclosed, but was later revealed to be pancreatic cancer. Jones is interred at Hillside Memorial Park Cemetery in Culver City, California.","Artistry, Legacy And Tributes":"President Joe Biden issued a statement praising Jones as \"a great unifier, who believed deeply in the healing power of music to restore hope and uplift those suffering from hunger, poverty, and violence, in America and the continent of Africa\". Former President Barack Obama praised Jones for \"building a career that took him from the streets of Chicago to the heights of Hollywood ... paving the way for generations of Black executives to leave their mark on the entertainment business\". Former President Bill Clinton stated, \"He changed the face of the music industry forever\". Vice President Kamala Harris called him a \"trailblazer\" and remembered him for his \"championing of civil and human rights\".\nNumerous celebrities and public figures paid their tributes to Jones such as Steven Spielberg, Michael Caine, Whoopi Goldberg, Oprah Winfrey, Morgan Freeman, Lin-Manuel Miranda, Ron Howard, Francis Ford Coppola, Colman Domingo, Will Smith, Clive Davis and Berry Gordy. Several musicians that have paid tribute include Paul McCartney, BP Fallon, Elton John, Stevie Wonder, Lionel Richie, John Legend, Lenny Kravitz, Darius Rucker, Nile Rodgers, David Guetta, Kelly Rowland, Victoria Monét, Gladys Knight, Ice-T, The Weeknd, Pharrell Williams, and Russ.\nActresses Rashida and Kidada Jones shared their tributes on their father''s legacy. Rashida spoke out in a statement five days after Quincy''s death, in part: \"My dad was nocturnal his whole adult life. He kept ''jazz hours'' starting in high school and never looked back. He would smile and bring me into his arms while he continued to work. There was no safer place in the world for me. I was fortunate enough to experience this love in close proximity. Daddy, it has been an honor to be your daughter. Your love lives forever.\"\nOn November 24, 2024, Kidada wrote in tribute, saying: “Music says everything words cannot. Music is the language of the heart. It’s no wonder you found a home in music, Dad. Now I will know you in this new invisible way as well. Your vessel is gone, but your force is omnipresent. Molecularly, we are inseparable and so our father daughter journey continues. Thank you for showering me with love, presence, affection, wisdom, optimisim, and so much joy.”\nBrazilian musicians Simone, Ivan Lins, Milton Nascimento and percussionist Paulinho da Costa were close friends and partners in Jones''s most recent works. Japanese film composer Joe Hisaishi came up with his alias (久石 譲, Hisaishi Jō) as a play on Jones''s name."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (267, '1WmIo9ORq1IDlovUWFmo4Y', 'Rahsaan Roland', 'Kirk', '4a1f7fe0-e509-4c4a-9fa1-9cf6c3ca891c', 218045, 6, 'https://en.wikipedia.org/wiki/Rahsaan_Roland_Kirk', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Roland-Kirk.jpg/500px-Roland-Kirk.jpg', 'Heinrich Klaffs', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Roland-Kirk.jpg', '{"Intro":"Rahsaan Roland Kirk (born Ronald Theodore Kirk; August 7, 1935 – December 5, 1977), known earlier in his career simply as Roland Kirk, was an American jazz multi-instrumentalist who played tenor saxophone, flute, and many other instruments. He was renowned for his onstage vitality; in his shows, virtuoso improvisation was accompanied by comic banter, political ranting, and the simultaneous playing of several instruments.","Life":"Ronald Theodore Kirk was born in Columbus, Ohio, where he lived in a neighborhood known as Flytown. He became blind at two years old, which he said was a result of improper medical treatment. As a teenager, Kirk studied at the Ohio State School for the Blind. By 15, he was on the road playing rhythm and blues on weekends with Boyd Moore''s band. According to saxophonist Hank Crawford, \"He would be like this 14-year-old blind kid playing two horns at once. They would bring him out and he would tear the joint up.\" Crawford heard him during this period and said he was unbelievable. He remarked, \"Now they had him doing all kinds of goofy stuff but he was playing the two horns and he was playing the shit out of them. He was an original from the beginning.\" Kirk felt compelled by a dream to transpose two letters in his first name to make \"Roland\". In 1970, Kirk added \"Rahsaan\" to his name after hearing it in a dream.\nKirk was politically outspoken. During his concerts, between songs he often talked about topical issues, including African-American history and the Civil Rights Movement. His monologues were often laced with satire and absurdist humor. According to comedian Jay Leno, when Leno toured with Kirk as Kirk''s opening act, Kirk would introduce him by saying: \"I want to introduce a young brother who knows the black experience and knows all about the white devils.... Please welcome Jay Leno!\"\nIn 1975, Kirk had a major stroke which led to partial paralysis of one side of his body. He continued to perform and record, modifying his instruments to enable him to play with one arm. At a live performance at Ronnie Scott''s Jazz Club in London he even managed to play two instruments, and carried on to tour internationally and to appear on television.\nHe died from a second stroke in 1977, aged 42, the morning after performing in the Frangipani Room of the Indiana University Student Union in Bloomington, Indiana.\nColumbus Mayor Jack Sensenbrenner declared Saturday, December 10, 1970, \"Rahsaan day\", according to the Columbus Dispatch obituary that appeared on Thursday, December 8, 1977.\nKirk''s hometown of Columbus was not appreciative of his work for most of his career. He was thrown out of a local nightclub because his music was too difficult to understand, and he left for Los Angeles and further touring. In the 21st century, jazz fans in Columbus have been embracing his legacy.\nHis widow Dorthaan Kirk became notable in her own right for her work as a curator and producer of jazz events primarily connected with Newark, dating back to her joining WBGO, New Jersey''s first public jazz station, in 1978, leading to her being a recipient of the 2020 A.B. Spellman NEA Jazz Masters Fellowship for Jazz Advocacy.","Legacy And Influence":"Ian Anderson, leader and flautist of Jethro Tull recorded a version of Kirk''s \"Serenade to a Cuckoo\" on their first album This Was (1968). Roland Kirk''s playing prompted Anderson to believe he could bring a flute into rock music. Anderson learned Kirk''s vocalizing style on the flute and Anderson''s flute playing became the signature element of Jethro Tull''s sound. Anderson got to know Kirk at the 1969 Newport Jazz Festival where they both performed the same night. Anderson said of Kirk: \"There''s something about these colourful shamans. They can tease us, but we go along with it, because we know they''re touched by genius, but at the same time there''s a little bit of the snake oil for sale.\"\nJeff Coffin, the saxophonist in Béla Fleck and the Flecktones was heavily influenced by Kirk''s music and says he learned through Kirk that it''s OK to experiment with an instrument. He used Kirk''s multi-horn inventions with the Flecktones and on his solo album Mutopia.\nGuitarist Jimi Hendrix \"idolized\" Kirk, and even hoped to collaborate with him one day.\nFrank Zappa had been influenced by Kirk''s music to a considerable extent early in his career. In the liner notes to his 1966 debut album with The Mothers of Invention, Freak Out!, Zappa cites Kirk as one of many in a lengthy list of personal musical influences. Kirk and Zappa performed live together at least once, at the 1969 Boston Globe Jazz Festival.\nDerek Trucks, a huge Kirk fan, recorded Kirk''s composition \"Volunteered Slavery\" with his namesake group for the 2004 album Live at Georgia Theatre, the 2006 studio album Songlines, and the DVD Songlines Live. He said that hearing Kirk''s music \"felt much the same way those Hendrix records felt, that he was blowing the rules wide open...\"\nDavid Jackson, of Van der Graaf Generator, was also highly influenced by the style and technique of Kirk, and he plays multiple saxophones simultaneously since at least 1969.\nGuitarist Michael Angelo Batio said in a 2008 interview with Ultimate Guitar Archive that Kirk''s playing of two saxophones at once inspired him to create his \"double guitar\".\nT.J. Kirk was a band named after the three artists it tributed: Thelonious Monk, James Brown, and Rahsaan Roland Kirk. Formed by eight-string guitarist Charlie Hunter as a side group to his own self-titled band, the band''s other members include Scott Amendola, Will Bernard, and John Schott.\nPaul Weller cited the Kirk album I Talk with the Spirits (1964) as one of his \"Most Influential Albums\" in an interview with The Times in 2009.\nBjörk named The Inflated Tear as one of her favorite jazz pieces, calling it \"primitive and instinctive\", \"open to nature\", and \"punk\".\nDavey Payne''s twin saxophone solo on \"Hit Me with Your Rhythm Stick\" (Ian Dury & the Blockheads, 1978) was inspired by Kirk.\nTerry Edwards'' twin saxophone solo on \"The Ministry of Defence\" by PJ Harvey (2016) was inspired by Kirk.\nEric Burdon and War''s 1970 debut album Eric Burdon Declares War features the track \"The Vision of Rassan\", which is broken up into two pieces \"Dedication\" and \"Roll on Kirk\".\nThe English post-punk group Rip Rig + Panic  were named after the album of the same name by Roland Kirk.\nClutch pay tribute to Roland Kirk in the song \"Three Golden Horns\" ob their 2022 album Sunrise on Slaughter Beach.\nJazz producer berlioz pays homage to Roland Kirk in the track \"ode to rahsaan\" on berlioz''s 2024 album open this wall.\nSaxophonist  Michael Blake recorded tenor and soprano saxophone simultaneously on several albums in the 2000s. He covered Kirk''s Three for Dizzy on Danish drummer Kresten Osgood''s Hammond Rens (2002) and can be heard playing both horns on New Blues, Old News (Michael Blake, Elevated) and Weazy (Ben Allison, Riding the Nuclear Tiger)."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (268, '1WmIo9ORq1IDlovUWFmo4Y', 'Ralph', 'Sutton', '11fdabfd-778c-48e4-b156-7618f32f2dac', 501615, 3, 'https://en.wikipedia.org/wiki/Ralph_Sutton', NULL, NULL, NULL, NULL, '{"Intro":"Ralph Earl Sutton (November 4, 1922 – December 30, 2001) was an American jazz pianist born in Hamburg, Missouri. He was a stride pianist in the tradition of James P. Johnson and Fats Waller.","Biography":"Ralph Sutton at the Bach Dancing & Dynamite Society, Half Moon Bay, California, July 26, 1987\nSutton was born in Hamburg, Missouri, United States, the son of Earl and Edna Sutton. His younger sister Barbara Sutton Curtis was also a jazz pianist.\nSutton had a stint as a session musician with Jack Teagarden''s band, before joining the US Army during World War II. After the war, he played at various venues in Missouri, eventually ending up at Eddie Condon''s club in Greenwich Village. In 1956, he relocated to San Francisco, California, where he recorded several albums with Bob Scobey''s dixieland band. From the 1960s onward, he worked mostly on his own. However, when the World''s Greatest Jazz Band was established in 1968, he was the natural choice for piano. He left that band in 1974 due to the extensive travel involved, and joined an old sidekick, Peanuts Hucko, in a quartet in Denver, near his home in Evergreen, Colorado.–4, 133, 202\nFellow jazz pianist Jess Stacy said this about Ralph Sutton: \"He is a superb piano player and a great guy. There''s nothing upstage about him. I really admire the way he plays. He''s one of the few piano players who uses both hands, and it''s sure nice to know that a player like Ralph is still around. I can''t say enough good things about him. He''s one of the greats, and I hope he gets the recognition he deserves.\"\nSutton died of a stroke in Evergreen, Colorado, at the age of 79."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (269, '1WmIo9ORq1IDlovUWFmo4Y', 'Randy', 'Brecker', '4244b5b1-9528-4f20-94cf-f2134e09b068', 253774, 7, 'https://en.wikipedia.org/wiki/Randy_Brecker', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Randy_Brecker_Kongsberg_Jazzfestival_2018_%28224735%29.jpg/500px-Randy_Brecker_Kongsberg_Jazzfestival_2018_%28224735%29.jpg', 'Tore Sætre', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Randy_Brecker_Kongsberg_Jazzfestival_2018_(224735).jpg', '{"Intro":"Randal Edward Brecker (born November 27, 1945) is an American trumpeter, flugelhornist, and composer.  His versatility has made him a popular studio musician who has recorded with acts in jazz, rock, and R&B.","Early Life And Education":"Brecker was born in Cheltenham, Pennsylvania, on November 27, 1945, to a musical family. His father Bob (Bobby) was a lawyer who played jazz piano, and his mother Sylvia was a portrait artist.\nRandy described his father as a semipro jazz pianist and trumpet fanatic. \"In school when I was eight, they only offered trumpet or clarinet. I chose trumpet from hearing Diz, Miles, Clifford, and Chet Baker at home. My brother (Michael Brecker) didn''t want to play the same instrument as I did, so three years later he chose the clarinet!\"\nRandy''s father, Bob, was also a songwriter and singer who loved to listen to recordings of the great jazz trumpet players such as Miles Davis, Dizzy Gillespie and Clifford Brown.  He took Randy and his younger brother Michael Brecker to see Davis, Thelonious Monk, Duke Ellington, and many other jazz icons.\nBrecker attended Cheltenham High School from 1959 to 1963 and then Indiana University from 1963 to 1966 studying with Bill Adam, David Baker and Jerry Coker and later moved to New York and performed with Clark Terry''s Big Bad Band, the Duke Pearson and the Thad Jones/Mel Lewis Orchestra.","Career":"In 1967, Brecker ventured into jazz-rock with the band Blood, Sweat & Tears, on their first album Child Is Father to the Man, but left to join the Horace Silver Quintet. Brecker recorded his first solo album, Score, in 1968, featuring his brother Michael Brecker.\nAfter Horace Silver, Randy Brecker joined Art Blakey''s Jazz Messengers before teaming up with brother Michael, Barry Rogers, Billy Cobham, and John Abercrombie to form the fusion group Dreams. The group recorded two albums: Dreams and Imagine My Surprise  for Columbia Records before they disbanded in 1971.\nIn the early 1970s, Brecker performed live with many artists, including The Eleventh House, Stevie Wonder, and Billy Cobham. He also recorded several albums with his brother under pianist/composer Hal Galper.\nBy 1975, Randy and Michael formed the Brecker Brothers band. They released six albums on Arista and garnered seven Grammy nominations between 1975 and 1981.  Their first record, The Brecker Bros., featured Randy''s composition \"Some Skunk Funk\", and he composed several pieces on this and subsequent albums.\nAfter the Brecker Brothers disbanded in 1982, Randy recorded and toured as a member of Jaco Pastorius'' Word of Mouth big band. It was soon thereafter that he met and later married Brazilian jazz pianist Eliane Elias. Eliane and Randy formed their own band, touring the world several times and recording one album named after their daughter together, Amanda, on Passport Records.\nIn 1977 he founded the jazz club Seventh Avenue South with his brother Michael Brecker.\nBrecker performing at the Aarhus International Jazz Festival in Denmark in 2017\nIn 1992 Randy and Michael reunited for a world tour and the triple-Grammy nominated GRP recording The Return of the Brecker Brothers.  The follow-up, 1994''s Out of the Loop, was a double-Grammy winner. In 1995, he was featured on Turtles, an album by Polish composer Włodek Pawlik.\nIn 1997, Into the Sun (Concord), a recording featuring Brecker''s impressions of Brazil, garnered Brecker his first Grammy as a solo artist.\nIn 2001, Brecker released Hangin'' in the City (ESC), a solo project that introduced his alter-ego Randroid with lyrics and vocals by Randroid himself. This CD was released in Europe, where Brecker toured extensively with his own line-up.\nBrecker''s next CD for ESC Records, 34th N Lex, won him his third Grammy for Best Contemporary Jazz Album in 2003. That summer he went back to Europe with the Bill Evans Soulbop Band.\nIn the summer of 2003, the Brecker Brothers appeared in Japan at the Mount Fuji Jazz Festival.\n2004 saw Brecker touring Europe as co-leader (with Bill Evans) of the band Soulbop. The WDR Big Band also invited Brecker to perform at the . The date was of significance to Randy as it was the last time he played with his brother, who took ill shortly thereafter with a rare form of leukemia known as MDS.\nIn 2005, Brecker''s wife Ada (married 2001) sat in for the first time. Brecker''s schedule continued with the Randy Brecker Band performing throughout Eastern Europe.\nIn 2007, Brecker was awarded his fourth Grammy for Randy Brecker Live with the WDR Big Band (Telarc/BHM), the live recording (also available in DVD format) of his performance with Michael at the Leverkusen Jazz Fest in 2004. Michael died that same year on January 13.\n2007 also saw the release of a two-CD set of live recordings of the band Soulbop (BHM) featuring Dave Kikoski, Victor Bailey, Steve Smith, Rodney Holmes and Hiram Bullock.\nBrecker returned to Brazilian music in 2008 for the album Randy in Brazil, which was recorded in São Paulo with Brazilian musicians and released on Summit Records. Chosen as one of the top 10 CDs of 2008 by All About Jazz, the CD won the Grammy for \"Best Contemporary Jazz Album\", bringing his Grammy total to five.\nA Tribute to the Brecker Brothers featuring Randy and recorded live at the Hamamatsu Jazz Festival in Japan with Yoichi Murata''s Solid Brass & Big Band was released by JVC Victor in Japan in late 2008.\nIn 2009, Brecker released Jazz Suite Tykocin, a project initiated and conceived by Włodek Pawlik, featuring Randy as a soloist with members of the Bialystok Philharmonic. Tykocin is the area in Poland where Brecker''s ancestors (mother''s maiden name: Tecosky) hail from, a fact that Pawlik discovered.\n2011 saw the release of The Jazz Ballad Song Book: Randy Brecker with the Danish Radio Big Band and The Danish National Chamber Orchestra, which garnered four Grammy nominations and critical acclaim. In 2012, Legacy Recordings released the boxed set The Brecker Brothers – The Complete Arista Albums Collection. In November of that year the album Night in Calisia, a collaboration between Brecker, the Wlodek Pawlik Trio, the Kalisz Philharmonic Orchestra and Adam Klocek was released in Poland. The album came out in the US in August 2013, and won the 2014 Grammy Award for Best Large Jazz Ensemble Album, Brecker''s sixth Grammy Award.\nA Brecker Brothers Band Reunion tour of European festivals in the summer of 2013 supported Brecker''s Brecker Brothers Band Reunion, a dual-disk project which was released on September 25, 2013, on Piloo Records. It features a live DVD recorded at the Blue Note in New York City with a new 11-song studio recording featuring members of the Brecker Brothers bands from throughout the years including David Sanborn, Mike Stern, Will Lee, and Dave Weckl. George Whitty produced the album, and Brecker''s wife, Ada Rovatti, also played saxophone. The recording was released in North America by Magenta/E-One, in Europe by Moosicus Records in November, and in Japan by Victor. It is dedicated to his brother, Michael, and other departed Brecker Brothers Band members.\nIn 2022, Brecker began performing the acoustic jazz compositions of his brother Michael, arranged for the first time to include trumpet, with saxophonist Tod Dickow and the Bay Area trio, Charged Particles.  Performances have included shows at Birdland in New York, at Ronnie Scott''s Jazz Club in London, England, plus The Merchants House in Glasgow, Scotland, SF Jazz in San Francisco,  Vibrato in Los Angeles, the Scarborough Jazz Festival in North Yorkshire, England, the San Jose Jazz, the new Palo Alto jazz club, The Spin Jazz Club in Oxford, England, plus The Stoller Hall, also in England.  The collaboration was the subject of an article in the San Jose Mercury News, and a review of the Dazzle performance written by Geoff Anderson."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (270, '1WmIo9ORq1IDlovUWFmo4Y', 'Randy', 'Weston', '7e198258-7093-46ac-a71e-91075fd0f5af', 281957, 3, 'https://en.wikipedia.org/wiki/Randy_Weston', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Randy_Weston_-_American_jazz_pianist.jpg/500px-Randy_Weston_-_American_jazz_pianist.jpg', 'Bob Travis Casco, Maine, USA', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Randy_Weston_-_American_jazz_pianist.jpg', '{"Intro":"Randolph Edward \"Randy\" Weston (April 6, 1926 – September 1, 2018) was an American jazz pianist and composer whose creativity was inspired by his ancestral African connection.\nWeston''s piano style owed much to Duke Ellington and Thelonious Monk, whom he cited in a 2018 video as among pianists he counted as influences, as well as Count Basie, Nat King Cole and Earl Hines. Beginning in the 1950s, Weston worked often with trombonist and arranger Melba Liston.\nDescribed as \"America''s African Musical Ambassador\", Weston once said: \"What I do I do because it''s about teaching and informing everyone about our most natural cultural phenomenon. It''s really about Africa and her music.\"","Biography":"Randolph Edward Weston was born on April 6, 1926, to Vivian (née Moore) and Frank Weston and was raised in Brooklyn, New York, where his father owned a restaurant. His mother was from Virginia and his father was of Jamaican-Panamanian descent, a staunch Garveyite, who passed self-reliant values to his son. Weston studied classical piano as a child and took dance lessons. He graduated from Boys High School in Bedford-Stuyvesant, where he had been sent by his father because of the school''s reputation for high standards. Weston took piano lessons from someone known as Professor Atwell who, unlike his former piano teacher Mrs Lucy Chapman, allowed him to play songs outside the classical music repertoire.\nDrafted into the U.S. Army during World War II, Weston served three years from 1944, reaching the rank of staff sergeant, and was stationed for a year in Okinawa, Japan. On his return to Brooklyn, he ran his father''s restaurant, which was frequented by many jazz musicians. Among Weston''s piano heroes were Count Basie, Nat King Cole, Art Tatum, Duke Ellington, and his cousin Wynton Kelly, but it was Thelonious Monk who made the biggest impact, as Weston described in a 2003 interview: \"When I first heard Monk, I heard Monk with Coleman Hawkins. When I heard Monk play, his sound, his direction, I just fell in love with it. I spent about three years just hanging out with Monk. I would pick him up in the car and bring him to Brooklyn and he was a great master because, for me, he put the magic back into the music.\"\nIn the late 1940s, Weston began performing with Bull Moose Jackson, Frank Culley and Eddie \"Cleanhead\" Vinson. In 1951, retreating from the atmosphere of drug use common on the New York jazz scene, Weston moved to Lenox, Massachusetts, in the Berkshires. There at the Music Inn, a venue where jazz historian Marshall Stearns taught, Weston first learned about the African roots of jazz. He would return in subsequent summers to perform at the Music Inn, where he wrote his composition \"Berkshire Blues\", interacting with artists and intellectuals such as Geoffrey Holder, Babatunde Olatunji, Langston Hughes and Willis James, about which experience Weston said: \"I got a lot of my inspiration for African music by being at Music Inn.... They were all explaining the African-American experience in a global perspective, which was unusual at the time.\"\nWeston worked with Kenny Dorham in 1953, and in 1954 with Cecil Payne, before forming his own trio and quartet and releasing his debut recording as a leader in 1954, Cole Porter in a Modern Mood. Weston was voted New Star Pianist in DownBeat magazine''s International Critics'' Poll of 1955. Several fine albums followed, with the best being Little Niles near the end of that decade, dedicated to his children Niles and Pamela, with all the tunes being written in 3/4 time. Melba Liston, as well as playing trombone on the record, provided excellent arrangements for a sextet playing several of Weston''s best compositions: the title track, \"Earth Birth\", \"Babe''s Blues\", \"Pam''s Waltz\", and others.\nIn the 1960s, Weston''s music prominently incorporated African elements, as shown on the large-scale suite Uhuru Afrika (1960, with the participation of poet Langston Hughes) and Highlife (full title:  Music from the New African Nations featuring the Highlife), the latter recorded in 1963, two years after Weston traveled for the first time to Africa, as part of a U.S. cultural exchange programme to Lagos, Nigeria (the contingent also including Langston Hughes, musicians Lionel Hampton and Ahmed Abdul-Malik, and singers Nina Simone and Brock Peters). On both these albums he teamed up with the arranger Melba Liston. Uhuru Afrika, or Freedom Africa, is considered a historic landmark album that celebrates several new African countries obtaining their Independence.\nIn addition, during these years, his band often featured the tenor saxophonist Booker Ervin. Weston covered the Nigerian Bobby Benson''s piece \"Niger Mambo\", which included Caribbean and jazz elements within a Highlife style, and has recorded this number many times throughout his career.\nIn 1967, Weston traveled throughout Africa with a U.S. cultural delegation. The last stop of the tour was Morocco, where he decided to settle, running his African Rhythms Club in Tangier for five years, from 1967 to 1972. He said in a 2015 interview: \"We had everything in there from Chicago blues singers to singers from the Congo.... The whole idea was to trace African people wherever we are and what we do with music.\"\nIn 1972, he produced Blue Moses for CTI Records, a best-selling record on which he plays electric keyboard. As he explained in a July 2018 interview, \"We were still living in Tangier, so my son and I came from Tangier to do the recording, but when I got there, Creed Taylor said his formula is electric piano.  I was not happy with that, but it was my only hit record. People loved it.\" In the summer of 1975, he played at the Festival of Tabarka in Tunisia, North Africa (later known as the Tabarka Jazz Festival), accompanied by his son Azzedin Weston on percussion, with other notable acts including Dizzy Gillespie.\nIn 1977, Weston participated in FESTAC, the Second World Black and African Festival of Arts and Culture, held in Lagos, Nigeria; other artists appearing there included Osibisa, Miriam Makeba, Bembeya Jazz, Louis Moholo, Dudu Pukwana, Donald Byrd, Stevie Wonder and Sun Ra.\nFor a long stretch, Weston recorded infrequently on smaller record labels. He also made a two-CD recording titled The Spirits of Our Ancestors (recorded 1991, released 1992), which featured arrangements by his long-time collaborator Melba Liston. The album contained new, expanded versions of many of his well-known pieces and featured an ensemble including some African musicians, with guests such as Dizzy Gillespie and Pharoah Sanders also contributing. The music director was saxophonist Talib Kibwe (also known as T. K. Blue), who subsequently continued in that role. The Spirits of Our Ancestors has been described as \"one of the most imaginative explorations of ''world jazz'' ever recorded.\"\nWeston produced a series of albums in a variety of formats: solo, trio, mid-sized groups, and collaborations with the Gnawa musicians of Morocco. His most popular compositions include \"Hi-Fly\", which he said was inspired by his experience of being 6'' 8\" and looking down at the ground, \"Little Niles\", named for his son (who was later known as Azzedin), \"African Sunrise\", \"Blue Moses\", \"The Healers\", and \"Berkshire Blues\". Weston''s compositions have frequently been recorded by such prominent musicians as Abdullah Ibrahim, Houston Person, and Booker Ervin, among others.\nA five-night celebration of Weston''s music took place at the Montreal Jazz Festival in 1995, featuring gnawa musicians and a duet with saxophonist David Murray.\nIn 2002, Weston performed with bassist James Lewis for the inauguration of the Bibliotheca Alexandrina in Alexandria, Egypt. During the same year, Weston performed with Gnawa musicians at Canterbury Cathedral at the invitation of the Archbishop of Canterbury. Weston also played at the Kamigamo Shrine in Japan in 2008.\nOn June 21, 2009, he participated in a memorial at the Jazz Gallery in New York for Ghanaian drummer Kofi Ghanaba (formerly known as Guy Warren), whose composition \"Love, the Mystery of...\" Weston used as his theme for some 40 years.\nIn 2013, Sunnyside released Weston''s album The Roots of the Blues, a duo session with tenor saxophonist Billy Harper. On November 17, 2014, as part of the London Jazz Festival, Weston played a duo concert with Harper at the Queen Elizabeth Hall. Reviewing the event, Kevin Le Gendre said the two musicians reached \"the kind of advanced conversational intimacy only master players achieve\".\nIn 2015, Weston was artist-in-residence at The New School in New York, participating in a lecture series, performing, and mentoring students.\nWeston celebrated his 90th birthday in 2016 with a concert at Carnegie Hall, among other activities, and continued thereafter to tour and speak internationally. He performed at the Gnawa Festival in Morocco in April 2016, took part in the Spoleto Festival in Charleston, SC, on June 2, and was among the opening acts at the 50th Montreux Jazz Festival. In July 2016, he was a keynote speaker at the 32nd World Conference of the International Society for Music Education in Glasgow.\nAn African Nubian Suite (2017) is a recording of a concert at the Institute of African American Affairs of New York University on April 8, 2012, Easter Sunday, with Cecil Bridgewater, Robert Trowers, Howard Johnson, T. K. Blue, Billy Harper, Alex Blake, Lewis Nash, Candido, Ayodele Maakheru, Lhoussine Bouhamidy, Saliou Souso, Martin Kwaku Obeng, Min Xiao-Fen, Tanpani Demda Cissoko, Neil Clarke and Ayanda Clarke, and the poet Jayne Cortez. Describing it as an \"epic work\", the Black Grooves reviewer wrote that The African Nubian Suite \"traces the history of the human race through music, with a narration by inspirational speaker Wayne B. Chandler, and introductions and stories by Weston in his role as griot.... Stressing the unity of humankind, Weston incorporates music that ''stretches across millennia''—from the Nubian region along the Nile Delta, to the holy city of Touba in Senegal, to China''s Shang dynasty, as well as African folk music and African American blues.... In these troubling times when our nation is divided by politics, race and religion, Weston uses The African Nubian Suite as a vehicle to remind us of our common heritage: ''We all come from the same place – we all come from Africa.''\" Coinciding with his 91st birthday, Weston played four shows at the Jazz Standard, April 6–April 9, 2017, performing music from An African Nubian Suite.\nWeston''s last release, the double-CD set titled Sound (2018), was a recording of a solo piano concert that took place at the Hotel Montreux Palace, Switzerland, on July 17 and 18, 2001. In a review for The Wall Street Journal, Larry Blumenfeld wrote: \"If these two discs amount to a grand gesture, Mr. Weston communicates most and best via small details. The power of a single note. The meaning of a single note repeated many times. The force of a crashing left-hand figure. The tension held between two dissonant tones or within an unexpected silence. All of which are packed into the three-plus minutes of ''Love, The Mystery Of,'' which was composed by the Ghanaian drummer Kofi Ghanaba (then known as Guy Warren) for Mr. Weston’s 1963 album ''Highlife,'' and now, more than a half-century later, provides this album’s most riveting moments.\"\nRandy Weston died at his home in Brooklyn on the morning of September 1, 2018, aged 92.","Early Life":"Randolph Edward Weston was born on April 6, 1926, to Vivian (née Moore) and Frank Weston and was raised in Brooklyn, New York, where his father owned a restaurant. His mother was from Virginia and his father was of Jamaican-Panamanian descent, a staunch Garveyite, who passed self-reliant values to his son. Weston studied classical piano as a child and took dance lessons. He graduated from Boys High School in Bedford-Stuyvesant, where he had been sent by his father because of the school''s reputation for high standards. Weston took piano lessons from someone known as Professor Atwell who, unlike his former piano teacher Mrs Lucy Chapman, allowed him to play songs outside the classical music repertoire.\nDrafted into the U.S. Army during World War II, Weston served three years from 1944, reaching the rank of staff sergeant, and was stationed for a year in Okinawa, Japan. On his return to Brooklyn, he ran his father''s restaurant, which was frequented by many jazz musicians. Among Weston''s piano heroes were Count Basie, Nat King Cole, Art Tatum, Duke Ellington, and his cousin Wynton Kelly, but it was Thelonious Monk who made the biggest impact, as Weston described in a 2003 interview: \"When I first heard Monk, I heard Monk with Coleman Hawkins. When I heard Monk play, his sound, his direction, I just fell in love with it. I spent about three years just hanging out with Monk. I would pick him up in the car and bring him to Brooklyn and he was a great master because, for me, he put the magic back into the music.\"","Early Career: 1940S–''50S":"In the late 1940s, Weston began performing with Bull Moose Jackson, Frank Culley and Eddie \"Cleanhead\" Vinson. In 1951, retreating from the atmosphere of drug use common on the New York jazz scene, Weston moved to Lenox, Massachusetts, in the Berkshires. There at the Music Inn, a venue where jazz historian Marshall Stearns taught, Weston first learned about the African roots of jazz. He would return in subsequent summers to perform at the Music Inn, where he wrote his composition \"Berkshire Blues\", interacting with artists and intellectuals such as Geoffrey Holder, Babatunde Olatunji, Langston Hughes and Willis James, about which experience Weston said: \"I got a lot of my inspiration for African music by being at Music Inn.... They were all explaining the African-American experience in a global perspective, which was unusual at the time.\"\nWeston worked with Kenny Dorham in 1953, and in 1954 with Cecil Payne, before forming his own trio and quartet and releasing his debut recording as a leader in 1954, Cole Porter in a Modern Mood. Weston was voted New Star Pianist in DownBeat magazine''s International Critics'' Poll of 1955. Several fine albums followed, with the best being Little Niles near the end of that decade, dedicated to his children Niles and Pamela, with all the tunes being written in 3/4 time. Melba Liston, as well as playing trombone on the record, provided excellent arrangements for a sextet playing several of Weston''s best compositions: the title track, \"Earth Birth\", \"Babe''s Blues\", \"Pam''s Waltz\", and others.","Later Career":"For a long stretch, Weston recorded infrequently on smaller record labels. He also made a two-CD recording titled The Spirits of Our Ancestors (recorded 1991, released 1992), which featured arrangements by his long-time collaborator Melba Liston. The album contained new, expanded versions of many of his well-known pieces and featured an ensemble including some African musicians, with guests such as Dizzy Gillespie and Pharoah Sanders also contributing. The music director was saxophonist Talib Kibwe (also known as T. K. Blue), who subsequently continued in that role. The Spirits of Our Ancestors has been described as \"one of the most imaginative explorations of ''world jazz'' ever recorded.\"\nWeston produced a series of albums in a variety of formats: solo, trio, mid-sized groups, and collaborations with the Gnawa musicians of Morocco. His most popular compositions include \"Hi-Fly\", which he said was inspired by his experience of being 6'' 8\" and looking down at the ground, \"Little Niles\", named for his son (who was later known as Azzedin), \"African Sunrise\", \"Blue Moses\", \"The Healers\", and \"Berkshire Blues\". Weston''s compositions have frequently been recorded by such prominent musicians as Abdullah Ibrahim, Houston Person, and Booker Ervin, among others.\nA five-night celebration of Weston''s music took place at the Montreal Jazz Festival in 1995, featuring gnawa musicians and a duet with saxophonist David Murray.\nIn 2002, Weston performed with bassist James Lewis for the inauguration of the Bibliotheca Alexandrina in Alexandria, Egypt. During the same year, Weston performed with Gnawa musicians at Canterbury Cathedral at the invitation of the Archbishop of Canterbury. Weston also played at the Kamigamo Shrine in Japan in 2008.\nOn June 21, 2009, he participated in a memorial at the Jazz Gallery in New York for Ghanaian drummer Kofi Ghanaba (formerly known as Guy Warren), whose composition \"Love, the Mystery of...\" Weston used as his theme for some 40 years.\nIn 2013, Sunnyside released Weston''s album The Roots of the Blues, a duo session with tenor saxophonist Billy Harper. On November 17, 2014, as part of the London Jazz Festival, Weston played a duo concert with Harper at the Queen Elizabeth Hall. Reviewing the event, Kevin Le Gendre said the two musicians reached \"the kind of advanced conversational intimacy only master players achieve\".\nIn 2015, Weston was artist-in-residence at The New School in New York, participating in a lecture series, performing, and mentoring students.\nWeston celebrated his 90th birthday in 2016 with a concert at Carnegie Hall, among other activities, and continued thereafter to tour and speak internationally. He performed at the Gnawa Festival in Morocco in April 2016, took part in the Spoleto Festival in Charleston, SC, on June 2, and was among the opening acts at the 50th Montreux Jazz Festival. In July 2016, he was a keynote speaker at the 32nd World Conference of the International Society for Music Education in Glasgow.\nAn African Nubian Suite (2017) is a recording of a concert at the Institute of African American Affairs of New York University on April 8, 2012, Easter Sunday, with Cecil Bridgewater, Robert Trowers, Howard Johnson, T. K. Blue, Billy Harper, Alex Blake, Lewis Nash, Candido, Ayodele Maakheru, Lhoussine Bouhamidy, Saliou Souso, Martin Kwaku Obeng, Min Xiao-Fen, Tanpani Demda Cissoko, Neil Clarke and Ayanda Clarke, and the poet Jayne Cortez. Describing it as an \"epic work\", the Black Grooves reviewer wrote that The African Nubian Suite \"traces the history of the human race through music, with a narration by inspirational speaker Wayne B. Chandler, and introductions and stories by Weston in his role as griot.... Stressing the unity of humankind, Weston incorporates music that ''stretches across millennia''—from the Nubian region along the Nile Delta, to the holy city of Touba in Senegal, to China''s Shang dynasty, as well as African folk music and African American blues.... In these troubling times when our nation is divided by politics, race and religion, Weston uses The African Nubian Suite as a vehicle to remind us of our common heritage: ''We all come from the same place – we all come from Africa.''\" Coinciding with his 91st birthday, Weston played four shows at the Jazz Standard, April 6–April 9, 2017, performing music from An African Nubian Suite.\nWeston''s last release, the double-CD set titled Sound (2018), was a recording of a solo piano concert that took place at the Hotel Montreux Palace, Switzerland, on July 17 and 18, 2001. In a review for The Wall Street Journal, Larry Blumenfeld wrote: \"If these two discs amount to a grand gesture, Mr. Weston communicates most and best via small details. The power of a single note. The meaning of a single note repeated many times. The force of a crashing left-hand figure. The tension held between two dissonant tones or within an unexpected silence. All of which are packed into the three-plus minutes of ''Love, The Mystery Of,'' which was composed by the Ghanaian drummer Kofi Ghanaba (then known as Guy Warren) for Mr. Weston’s 1963 album ''Highlife,'' and now, more than a half-century later, provides this album’s most riveting moments.\"\nRandy Weston died at his home in Brooklyn on the morning of September 1, 2018, aged 92.","Personal Life":"Weston''s first marriage, to Mildred Mosley, ended in divorce. His son Azzedin having predeceased him, Weston was survived by his wife Fatoumata Mbengue-Weston, whom he met in 1994; three daughters, Cheryl, Pamela and Kim; seven grandchildren; six great-grandchildren; and one great-great-grandchild.","Autobiography":"In October 2010, Duke University Press published African Rhythms: The Autobiography of Randy Weston, \"composed by Randy Weston, arranged by Willard Jenkins\". It was hailed as \"an important addition to the jazz historiography and a long anticipated read for fans of this giant of African American music, aka jazz.\" Reviewer Larry Reni Thomas wrote: \"Randy Weston’s long-anticipated, much-talked-about, consciousness-raising, African-centered autobiography, African Rhythms, is a serious breath of fresh air and is a much-needed antidote in this world of mediocre musicians, and men. He takes the reader on a wonderful, exciting journey from America to Africa and back with the ease of a person who loved every minute of it. The book is hard to put down and is an engaging, pleasing literary work that is worthy of being required reading in any history or literature school course.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (271, '1WmIo9ORq1IDlovUWFmo4Y', 'Ray', 'Brown', 'd8a1a9e8-295d-4999-9c70-0a4c8bdb36e8', 252998, 1, 'https://en.wikipedia.org/wiki/Ray_Brown_(musician)', 'https://upload.wikimedia.org/wikipedia/commons/9/98/Ray_Brown.jpg', 'Kay Musical Instrument Company', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Ray_Brown.jpg', '{"Intro":"Raymond Matthews Brown (October 13, 1926 – July 2, 2002) was an American jazz double bassist, known for his extensive work with Oscar Peterson and Ella Fitzgerald. He was also a founding member of the group that would later develop into the Modern Jazz Quartet.","Early Life":"Ray Brown was born on October 13, 1926, in Pittsburgh, Pennsylvania, and took piano lessons as a child. After noticing how many pianists attended his high school, he thought of taking up the trombone, but his father was unable to afford one. With a vacancy in the high school jazz orchestra, he took up the upright bass instead.\nA major early influence on Brown''s bass playing was Jimmy Blanton, the bassist in the Duke Ellington band. Brown''s high school music teacher believed that he was a diligent student, as he took the bass home with him on weekends. Brown, however, was already using the school bass in gigs; when this was discovered, the bass had to be returned and Brown''s father bought him one. Brown graduated from high school in 1944.","Later Life And Career":"As a young man Brown became increasingly well known in the Pittsburgh jazz scene, with his first experiences playing in bands with the Jimmy Hinsley Sextet and the Snookum Russell band. Later, having heard stories about the burgeoning jazz scene on 52nd Street in New York City, he bought a one-way ticket to New York. He arrived in New York at the age of 20, met up with Hank Jones, with whom he had previously worked, and was introduced to Dizzy Gillespie, who was looking for a bass player. Gillespie hired Brown on the spot, and he soon played with such established musicians as Art Tatum and Charlie Parker. In 1948, Brown left Dizzy''s band to start a trio with Hank Jones and Charlie Smith.\nFrom 1946 to 1951, Brown played in Gillespie''s band. Brown, along with the vibraphonist Milt Jackson, drummer Kenny Clarke, and pianist John Lewis formed the rhythm section of the Gillespie band. Lewis, Clarke, and Jackson eventually formed the Modern Jazz Quartet. Brown became acquainted with singer Ella Fitzgerald when she joined the Gillespie band as a special attraction for a tour of the southern United States in 1947. The two married that year, and together they adopted a child born to Fitzgerald''s half-sister Frances, whom they christened Ray Brown, Jr. Fitzgerald and Brown divorced in 1953, bowing to the various career pressures both were experiencing at the time, though they would continue to perform together.\nMilt Jackson and Ray Brown (left), New York, between 1946 and 1948 (William P. Gottlieb 04461)\nFrom 1951 to 1965, Brown was a member of the Oscar Peterson Trio. The trio included a guitarist until 1958 (initially Barney Kessel, and then Herb Ellis). After Ellis left the group, Peterson decided to continue the trio with Brown and drummer Ed Thigpen. Brown recorded extensively as a session musician for producer Norman Granz during the 1950s (for Granz''s Clef, Norgran, and Verve record labels), often alongside Peterson. After leaving the Oscar Peterson Trio, Brown concentrated on studio work in Los Angeles.\nIn the early 1960s, Brown began teaching, at the Advanced School of Contemporary Music, based in Toronto.\nBrown guested as a bass player on \"Razor Boy\", the second track on Steely Dan''s second album, Countdown to Ecstasy, released in 1973.\nFrom 1974 to 1982, Brown performed and recorded a series of albums with guitarist Laurindo Almeida, saxophonist and flutist Bud Shank, and drummer Shelly Manne (replaced by Jeff Hamilton after 1977) under the name The L.A. Four.\nIn the 1980s and 1990s Brown led his own trios and continued to refine his bass playing style. In his later years he recorded and toured extensively with pianist Gene Harris. In the early 1980s, Brown met Diana Krall in a restaurant in Nanaimo, British Columbia. According to Jeff Hamilton, in an interview recorded on the Diana Krall Live in Rio DVD, he first heard Krall play at a workshop and, impressed with her piano skills (she was not yet singing), introduced her to bassist John Clayton. Hamilton and Clayton both encouraged Krall to move to Los Angeles to study under Brown and others. In 1986 Brown played bass on the song “Poisoned Rose” on Elvis Costello’s King of America album. In 1990, he teamed up with pianist Bobby Enriquez and drummer Foster, for Enriquez''s album, The Wildman Returns.\nBrown, c. 1947 in a band with Dizzy Gillespie\nAround the same time, Brown made seven albums with pianist André Previn when, after a hiatus of two decades, Previn returned to jazz to perform and record regularly again between 1989 and 2002: After Hours (1989, with guitarist Joe Pass), Uptown (1990, with guitarist Mundell Lowe), Old Friends (1992, live recording, with guitarist Mundell Lowe), Kiri Sidetracks. The Jazz Album (1992, with singer Kiri Te Kanawa and guitarist Mundell Lowe), What Headphones? (1992, with Mundell Lowe, Jim Pugh on trombone, Warren Vache on cornet, Richard Todd on horn, Grady Tate on drums, and The Antioch Baptist Choir), André Previn and Friends Play Show Boat (1995, with Mundell Lowe and Grady Tate), and Jazz at the Musikverein (1997, live recording, with Mundell Lowe). Brown and Previn had recorded together before in the 1960s on 4 To Go! (1963, with guitarist Herb Ellis and drummer Shelly Manne) and Right as the Rain (1967, with singer Leontyne Price). An hour-long film, Together on Broadway. The Making of Sidetracks documents the work on the album Kiri Sidetracks. The Jazz Album.\nBrown played for a time with the \"Quartet\" with Monty Alexander, Milt Jackson, and Mickey Roker. After that he toured again with his own trio, with several young pianists such as Benny Green, Geoffrey Keezer, and Larry Fuller. The last edition of the Ray Brown Trio included pianist Larry Fuller and drummer Karriem Riggins. With that trio, Brown continued to perform until his death. Brown died in his sleep on July 2, 2002, after having played golf, before a show in Indianapolis.\nCite error: There are <ref group=lower-alpha> tags or {{efn}} templates on this page, but the references will not show without a {{reflist|group=lower-alpha}} template or {{notelist}} template (see the help page)."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (272, '1WmIo9ORq1IDlovUWFmo4Y', 'Ray', 'Charles', '8518b7af-5e33-498a-90c9-9fd772f4c422', 980630, 3, '''https://en.wikipedia.org/wiki/Ray_Charles_(musician', NULL, NULL, NULL, NULL, NULL);
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (273, '1WmIo9ORq1IDlovUWFmo4Y', 'Red', 'Nichols', '48a2c05d-b5c8-47e0-9f11-8425c7807000', 269598, 7, 'https://en.wikipedia.org/wiki/Red_Nichols', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Red_Nichols_from_sheet_music.jpg/500px-Red_Nichols_from_sheet_music.jpg', 'Unknown authorUnknown author', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Red_Nichols_from_sheet_music.jpg', '{"Intro":"Ernest Loring \"Red\" Nichols (May 8, 1905 – June 28, 1965) was an American jazz cornetist, composer, and jazz bandleader. He was one of the most prolific and influential jazz musicians in the late 1920s and early 1930s, appearing on over 4,000 recordings. In 1959, a biopic was made of his life and career, The Five Pennies, starring Danny Kaye.","Biography":"Nichols was born in Ogden, Utah, United States. He was of the Mormon faith. His father was a college music professor, and Nichols was something of a child prodigy, playing difficult set pieces for his father''s brass band by the age of 12. Young Nichols heard the early recordings of the Original Dixieland Jazz Band and later those of Bix Beiderbecke, and these had a strong influence on him. His style became polished, clean, and incisive.\nIn the early 1920s, Nichols moved to the Midwest and joined a band called the Syncopating Seven. When that band broke up, he joined the Johnny Johnson Orchestra and went with it to New York City in 1923. In New York, he met trombonist Miff Mole, and the two were inseparable for the next decade. Before signing with Brunswick, Nichols and Mole recorded for Pathé-Perfect under the name the Red Heads.\nNichols could read music and easily gained studio work. In 1926, Mole and he began recording with a variety of bands as Red Nichols and His Five Pennies. Few of these groups were quintets; the name was a pun on \"nickel\". With the Five Pennies, he recorded more than 100 sides for Brunswick. He also recorded as the Arkansas Travelers, the California Red Heads, the Louisiana Rhythm Kings, the Charleston Chasers, Red and Miff''s Stompers, and Miff Mole and His Little Molers. During some weeks in this period, Nichols and his bands were recording 10 to 12 two-sided records.\nNichols'' band started with Mole on trombone and Jimmy Dorsey on alto saxophone and clarinet. Other musicians in his bands in the following decade included Benny Goodman (clarinet), Glenn Miller (trombone), Jack Teagarden (trombone), Pee Wee Russell (clarinet), Joe Venuti (violin), Eddie Lang (banjo and guitar), and Gene Krupa (drums). The Five Pennies'' version of \"Ida, Sweet as Apple Cider\" was a surprise hit record. It sold over a million copies and was awarded a gold disc by the Recording Industry Association of America. His composition \"Nervous Charlie Stomp\" was recorded by one of the top jazz bands of the 1920s, Fletcher Henderson''s orchestra featuring Coleman Hawkins on sax, and released as a 78 single.\nIn the next decade, more structured swing eclipsed the improvisational hot jazz Nichols loved to play. He tried to follow the changes and formed a swing band, but his recording career seemed to stall in 1932. Music critic Michael Brooks wrote,\nWhat went wrong? Part of it was too much, too soon. Much of his vast recorded output was released in Europe, where he was regarded by early jazz critics as the equal, if not the superior, of Louis Armstrong and Bix Beiderbecke. People who make fools of themselves usually find a scapegoat, and when the critics were exposed to the music of Duke Ellington, Benny Carter, Coleman Hawkins, and others, they turned on Nichols and savaged him, trashing him as unfairly as they had revered him. Nichols'' chief fault was an overly stiff, academic approach to jazz trumpet, but he did recognize merit as far as other jazz musicians were concerned and made some wonderful small-group recordings.\nOther labels Nichols recorded for included Edison 1926, Victor 1927, 1928, 1930, 1931 (individual sessions), Bluebird 1934, 1939, back to Brunswick for a session in 1934, Variety 1937, and OKeh in 1940.\nNichols survived the Great Depression by playing in show bands and pit orchestras. He led Bob Hope''s orchestra for a while, moving to California. Nichols married Willa Stutsman, a \"stunning\" George White''s Scandals dancer, and they had a daughter. In 1942, their daughter contracted polio, which was misdiagnosed at first as spinal meningitis, and Nichols left Glen Gray and the Casa Loma Orchestra to work in the wartime shipyards. On May 2, 1942, Nichols left his band to take an army commission after completing an engagement at Lantz''s Merry-Go-Round in Dayton, Ohio.\nDrawn back to music after the war, Nichols formed another Five Pennies band and began playing in small clubs in Los Angeles. Club dates turned into performances at bigger venues, such as the Zebra Room, the Tudor Room of the Palace Hotel in San Francisco, and the Huntington-Sheraton Hotel in Pasadena, California. He toured Europe as a goodwill ambassador for the State Department. Nichols and his band performed in the 1950 film Quicksand starring Mickey Rooney. In 1956, he was the subject of an episode of the television program This Is Your Life in which he reunited with Miff Mole, Phil Harris, and Jimmy Dorsey, who praised Nichols as a bandleader who ensured everyone was paid.\nIn 1965, Nichols took his Five Pennies band to the Mint Hotel in Las Vegas. On June 28, 1965, a few days after he began performing, he had chest pains while he was sleeping. He phoned the front desk, but was dead by the time the ambulance arrived. The band performed as scheduled with a spotlight on Nichols'' empty chair.\nIn 1929, he appeared in the Vitaphone film short (reel #870) with his band the Five Pennies along with Eddie Condon and Pee Wee Russell.\nIn 1935, he appeared in the Paramount Pictures film short The Parade of the Maestros along with Ferde Grofe performing \"In the Middle of a Kiss\".\nRed Nichols performed in and is also mentioned in the 1950 Mickey Rooney and Jeanne Cagney film Quicksand. Rooney''s character asks out Jean Cagney; he asks if she likes \"Red Nichols and his outfit?\" and she responds, \"I think they''re great!\" They then go to the club to watch Red Nichols and his band perform.\nThe 1959 Hollywood film The Five Pennies, the film biography of Red Nichols, starring Danny Kaye as Red Nichols, was loosely based on Nichols'' life and career. Nichols played his own cornet parts for the film and appeared briefly as one of the \"Clicquot Club Eskimos\" on screen. The Paramount Pictures movie received four Academy Award nominations. Jazz contemporary Louis Armstrong also appeared in the film. The Five Pennies movie theme song and other songs for the film were composed by Sylvia Fine, Danny Kaye''s wife.\nNichols also made cameo appearances in the 1951 film Disc Jockey with Tommy Dorsey, and The Gene Krupa Story in 1959.\nHis recording of \"Poor Butterfly\" is heard in the 1994 Woody Allen film Bullets Over Broadway and his recording of \"(Back Home Again in) Indiana\" in Allen''s 1999 film Sweet and Lowdown.","Early Life And Career":"Nichols was born in Ogden, Utah, United States. He was of the Mormon faith. His father was a college music professor, and Nichols was something of a child prodigy, playing difficult set pieces for his father''s brass band by the age of 12. Young Nichols heard the early recordings of the Original Dixieland Jazz Band and later those of Bix Beiderbecke, and these had a strong influence on him. His style became polished, clean, and incisive.\nIn the early 1920s, Nichols moved to the Midwest and joined a band called the Syncopating Seven. When that band broke up, he joined the Johnny Johnson Orchestra and went with it to New York City in 1923. In New York, he met trombonist Miff Mole, and the two were inseparable for the next decade. Before signing with Brunswick, Nichols and Mole recorded for Pathé-Perfect under the name the Red Heads.","Brunswick Records Era":"Nichols could read music and easily gained studio work. In 1926, Mole and he began recording with a variety of bands as Red Nichols and His Five Pennies. Few of these groups were quintets; the name was a pun on \"nickel\". With the Five Pennies, he recorded more than 100 sides for Brunswick. He also recorded as the Arkansas Travelers, the California Red Heads, the Louisiana Rhythm Kings, the Charleston Chasers, Red and Miff''s Stompers, and Miff Mole and His Little Molers. During some weeks in this period, Nichols and his bands were recording 10 to 12 two-sided records.\nNichols'' band started with Mole on trombone and Jimmy Dorsey on alto saxophone and clarinet. Other musicians in his bands in the following decade included Benny Goodman (clarinet), Glenn Miller (trombone), Jack Teagarden (trombone), Pee Wee Russell (clarinet), Joe Venuti (violin), Eddie Lang (banjo and guitar), and Gene Krupa (drums). The Five Pennies'' version of \"Ida, Sweet as Apple Cider\" was a surprise hit record. It sold over a million copies and was awarded a gold disc by the Recording Industry Association of America. His composition \"Nervous Charlie Stomp\" was recorded by one of the top jazz bands of the 1920s, Fletcher Henderson''s orchestra featuring Coleman Hawkins on sax, and released as a 78 single.\nIn the next decade, more structured swing eclipsed the improvisational hot jazz Nichols loved to play. He tried to follow the changes and formed a swing band, but his recording career seemed to stall in 1932. Music critic Michael Brooks wrote,\nWhat went wrong? Part of it was too much, too soon. Much of his vast recorded output was released in Europe, where he was regarded by early jazz critics as the equal, if not the superior, of Louis Armstrong and Bix Beiderbecke. People who make fools of themselves usually find a scapegoat, and when the critics were exposed to the music of Duke Ellington, Benny Carter, Coleman Hawkins, and others, they turned on Nichols and savaged him, trashing him as unfairly as they had revered him. Nichols'' chief fault was an overly stiff, academic approach to jazz trumpet, but he did recognize merit as far as other jazz musicians were concerned and made some wonderful small-group recordings.\nOther labels Nichols recorded for included Edison 1926, Victor 1927, 1928, 1930, 1931 (individual sessions), Bluebird 1934, 1939, back to Brunswick for a session in 1934, Variety 1937, and OKeh in 1940.","Later Career":"Nichols survived the Great Depression by playing in show bands and pit orchestras. He led Bob Hope''s orchestra for a while, moving to California. Nichols married Willa Stutsman, a \"stunning\" George White''s Scandals dancer, and they had a daughter. In 1942, their daughter contracted polio, which was misdiagnosed at first as spinal meningitis, and Nichols left Glen Gray and the Casa Loma Orchestra to work in the wartime shipyards. On May 2, 1942, Nichols left his band to take an army commission after completing an engagement at Lantz''s Merry-Go-Round in Dayton, Ohio.\nDrawn back to music after the war, Nichols formed another Five Pennies band and began playing in small clubs in Los Angeles. Club dates turned into performances at bigger venues, such as the Zebra Room, the Tudor Room of the Palace Hotel in San Francisco, and the Huntington-Sheraton Hotel in Pasadena, California. He toured Europe as a goodwill ambassador for the State Department. Nichols and his band performed in the 1950 film Quicksand starring Mickey Rooney. In 1956, he was the subject of an episode of the television program This Is Your Life in which he reunited with Miff Mole, Phil Harris, and Jimmy Dorsey, who praised Nichols as a bandleader who ensured everyone was paid.","Biographical Film And Film Career":"In 1929, he appeared in the Vitaphone film short (reel #870) with his band the Five Pennies along with Eddie Condon and Pee Wee Russell.\nIn 1935, he appeared in the Paramount Pictures film short The Parade of the Maestros along with Ferde Grofe performing \"In the Middle of a Kiss\".\nRed Nichols performed in and is also mentioned in the 1950 Mickey Rooney and Jeanne Cagney film Quicksand. Rooney''s character asks out Jean Cagney; he asks if she likes \"Red Nichols and his outfit?\" and she responds, \"I think they''re great!\" They then go to the club to watch Red Nichols and his band perform.\nThe 1959 Hollywood film The Five Pennies, the film biography of Red Nichols, starring Danny Kaye as Red Nichols, was loosely based on Nichols'' life and career. Nichols played his own cornet parts for the film and appeared briefly as one of the \"Clicquot Club Eskimos\" on screen. The Paramount Pictures movie received four Academy Award nominations. Jazz contemporary Louis Armstrong also appeared in the film. The Five Pennies movie theme song and other songs for the film were composed by Sylvia Fine, Danny Kaye''s wife.\nNichols also made cameo appearances in the 1951 film Disc Jockey with Tommy Dorsey, and The Gene Krupa Story in 1959.\nHis recording of \"Poor Butterfly\" is heard in the 1994 Woody Allen film Bullets Over Broadway and his recording of \"(Back Home Again in) Indiana\" in Allen''s 1999 film Sweet and Lowdown.","Death":"In 1965, Nichols took his Five Pennies band to the Mint Hotel in Las Vegas. On June 28, 1965, a few days after he began performing, he had chest pains while he was sleeping. He phoned the front desk, but was dead by the time the ambulance arrived. The band performed as scheduled with a spotlight on Nichols'' empty chair."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (274, '1WmIo9ORq1IDlovUWFmo4Y', 'Red', 'Rodney', '0d18da0d-49ab-4ca0-ac52-181f6039f3dc', 312519, 7, 'https://en.wikipedia.org/wiki/Red_Rodney', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Red_Rodney%2C_ca._June_1946_%28William_P._Gottlieb%29.jpg/500px-Red_Rodney%2C_ca._June_1946_%28William_P._Gottlieb%29.jpg', 'William P. Gottlieb', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Red_Rodney,_ca._June_1946_(William_P._Gottlieb).jpg', '{"Intro":"Robert Roland Chudnick (September 27, 1927 – May 27, 1994), known professionally as Red Rodney, was an American jazz trumpeter.","Biography":"Born in Philadelphia, Pennsylvania, he became a professional musician at 15, working in the mid-1940s for the big bands of Jerry Wald, Jimmy Dorsey, Georgie Auld, Elliot Lawrence, Benny Goodman, and Les Brown. He was inspired by hearing Dizzy Gillespie and Charlie Parker to change his style to bebop, moving on to play with Claude Thornhill, Gene Krupa, and Woody Herman. He was Jewish.\nHe accepted an invitation from Charlie Parker to join his quintet and was a member of the band from 1949 to 1951. Being the only white member of the group, when playing in the southern United States he was billed as \"Albino Red\" as a ruse to avoid prejudice against mixed race musical combos. During this time he recorded extensively.\nDuring the 1950s, he worked as a bandleader in Philadelphia and recorded with Ira Sullivan. He became addicted to heroin and started a pattern of dropping in and out of jazz.  At one point, he disguised himself as an US Army disbursement officer, General Arnold T. MacIntyre, whose appearance was similar to his own.  In this guise, he robbed the Atomic Energy Commission of some $10,000; he was later caught and served prison time.\nDuring 1969, Rodney played in Las Vegas with fellow Woody Herman colleague, trombonist Bill Harris, as part of the Flamingo casino house band led by Russ Black. Similar work continued through 1972.\nIn the early 1970s he was bankrupted by medical costs following a stroke. He returned to jazz. In 1975 he was incarcerated in Lexington, Kentucky for drug offenses. While jailed he gave music lessons to guitarist Wayne Kramer of the MC5.\nRed Rodney at Bach Dancing & Dynamite Society, Half Moon Bay CA 1982\nHe reunited with Ira Sullivan and performed with Dizzy Gillespie. From 1980 to 1982, Rodney made five albums with Sullivan. On these albums he started to play post bop jazz. He continued to work and record into the 1990s. He performed on a Charlie Parker tribute album by Charlie Watts, drummer for the Rolling Stones. He provided an early showcase for saxophonist Chris Potter, who was a member of his group and only 19 years old when Rodney recorded Red Alert in late 1990.\nHe performed at Jazz at Lincoln Center and the JVC Jazz Festival. He worked as an adviser for Bird, a movie about Charlie Parker directed by Clint Eastwood. Michael Zelniker played him in the movie.\nRodney died on May 27, 1994, from lung cancer."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (275, '1WmIo9ORq1IDlovUWFmo4Y', 'Richard', 'Davis', 'b59843a1-bb97-45f0-84b9-ff9017878cdd', 263441, 1, 'https://en.wikipedia.org/wiki/Richard_Davis_(bassist)', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Richard_Davis.jpg', 'Brianmcmillen', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Richard_Davis.jpg', '{"Intro":"Richard Davis (April 15, 1930 – September 6, 2023) was an American jazz bassist. Among his best-known contributions to the albums of others are Eric Dolphy''s Out to Lunch!, Andrew Hill''s Point of Departure, and Van Morrison''s Astral Weeks, of which critic Greil Marcus wrote (in The Rolling Stone Illustrated History of Rock and Roll), \"Richard Davis provided the greatest bass ever heard on a rock album.\"","Early Life":"Davis was born in Chicago, Illinois, on April 15, 1930. His mother died during childbirth, and he was raised by Robert and Elmora Johnson. Davis gravitated towards playing the bass, and began his musical career singing bass in his family''s vocal trio. He studied double bass in high school under Walter Dyett, and was a member of the Youth Orchestra of Greater Chicago, playing in the orchestra''s first performance at Chicago''s Orchestra Hall on November 14, 1947. After high school, he studied double bass with Rudolf Fahsbender of the Chicago Symphony Orchestra while attending VanderCook College of Music.","Career":"After college, Davis performed in dance bands.  In the early 1950s, Richard Davis met and played with Sonny Blount (globally celebrated later as the other-worldly orchestral revolutionary Sun Ra) and spent a year with the artistically and commercially successful pianist Ahmad Jamal’s trio. Ahmad Jamal boosted Davis’ career from the start. The connections he made led him to pianist Don Shirley. In 1954, he and Shirley moved to New York City and performed together until 1956, when Davis began playing with the Sauter-Finegan Orchestra. In 1957, he became part of Sarah Vaughan''s rhythm section, touring and recording with her until 1960.\nDuring the 1960s, Davis was in demand in a variety of musical circles. He worked with many of the small jazz groups of the time, including those led by Eric Dolphy, Jaki Byard, Booker Ervin, Andrew Hill, Elvin Jones, and Cal Tjader. From 1966 to 1972, he was a member of The Thad Jones/Mel Lewis Orchestra. He has also played with Don Sebesky, Oliver Nelson, Frank Sinatra, Miles Davis, Dexter Gordon, Joe Henderson and Ahmad Jamal.  Davis became a prolific contributor to numerous groundbreaking jazz projects. Notably, he played on Eric Dolphy’s avant-garde masterpiece Out to Lunch! with its bold shapes and structures, and on teenage drums prodigy Tony Williams’ album debut, Life Time. Eric Dolphy assisted Davis in his ability to expand his versatility in relation to playing jazz music. Although Dolphy''s music was different from the one he had previously been working on with Sarah Vaughan he knew he was in the right place.\nIn 1964 Davis partnered with Andrew Hill’s rhythmically intricate Point of Departure. As Richard Davis continued developing he took a lot of inspiration from Mingus . In 1968 with Van Morrison’s Astral Weeks, Davis served as the de facto musical director, leading the improvisational ensemble through the album’s creation. Producer Lewis Merenstein described Davis as “the soul of the album.” His bass lines on Astral Weeks were lauded by critics for their emotional depth, propelling the album to its status as a classic.\nDavis recorded with pop and rock musicians in the 1970s, appearing on Laura Nyro''s Smile and Bruce Springsteen''s Greetings From Asbury Park, N.J. and Born to Run. During his career he performed classical music with conductors Igor Stravinsky, Leonard Bernstein, Pierre Boulez, Leopold Stokowski, and Gunther Schuller.","Career Highlights And Collaborations":"In 1964 Richard Davis featured on Tony Williams’s debut album Life Time, showcasing his innovative approach. He played on Frank Sinatra’s Watertown (1969), Paul Simon’s Something So Right (1973), and on several classic tracks from 1975, including Bruce Springsteen’s Meeting Across the River, Laura Nyro’s Smile, and Janis Ian’s At Seventeen. Beyond his contributions to pop and rock, Davis was a founding member and regular participant in the Thad Jones/Mel Lewis Orchestra from 1966 to 1972. He performed as part of the New York Bass Violin Choir led by Bill Lee.\nIn the late 1980s he established the Madison chapter of the Institute for the Healing of Racism and held meetings at his home. In the 1990s he also participated in a series of post bop trio recordings with the pianist John Hicks and the drummer Tatsuya Nakamura. In May 2000 he released a CD that was recorded in Japan called The Bassist which paid homage to Diversity (King Records). His second CD with King Records So In Love was also later released. Davis always continued to play and record semi-regularly with him performing with The Bassist which paid homage to Diversity (Palmetto) in 2001. And on March 2009 he participated at the Anderson’s Chicago club, the Velvet Lounge, from March 18–22 celebrating legend Fred Anderson turning 80 on March 22.","Death":"Davis died on September 6, 2023, after two years in hospice care, at the age of 93."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (276, '1WmIo9ORq1IDlovUWFmo4Y', 'Robin', 'Eubanks', '7ab487f9-ab05-4310-93b6-f5d543924c80', 84213, 11, 'https://en.wikipedia.org/wiki/Robin_Eubanks', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Robin_Eubanks.jpg/500px-Robin_Eubanks.jpg', 'Salvatore Desiato Italia', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Robin_Eubanks.jpg', '{"Intro":"Robin Eubanks (born October 25, 1955) is an American jazz and jazz fusion slide trombonist, the brother of guitarist Kevin Eubanks and trumpeter Duane Eubanks. Younger brother Shane Eubanks, twin to Duane Eubanks, is a DJ. His uncles are jazz pianist Ray Bryant and bassist Tommy Bryant. His mother, Vera Eubanks, was famed pianist Kenny Barron''s first piano teacher.","Biography":"Robin Eubanks was born on October 25, 1955, in Philadelphia. After graduating cum laude from the University of the Arts, he moved to New York City where he first appeared on the jazz scene in the early 1980s. He played with Slide Hampton, Sun Ra, and Stevie Wonder.  Eubanks was the musical director for jazz drummer Art Blakey and the Jazz Messengers. He also was a member of jazz drummer Elvin Jones’ Jazz Machine. He was a contributor on fellow jazz trombonist Steve Turre''s 2003 release One4J: Paying Homage to J.J. Johnson. Eubanks has also released several albums as a bandleader.\nHe played for 15 years in double bassist Dave Holland''s quintet, sextet, octet and big band.\nJ.J. Johnson recommended Eubanks for the position at the Oberlin Conservatory in Ohio, where he taught for 20 years as a tenured professor of Jazz Trombone and Jazz Composition. He has also taught at New England Conservatory and Berklee College of Music in Boston. He was a member in the all-star group the SFJAZZ Collective for 10 years 2008-2019. His notable students include trombonist Andy Hunter of the  WDR Big Band.\nRobin is one of the pioneers of M-Base. He has appeared on numerous television shows and specials, including The Tonight Show, Saturday Night Live and The Grammys. He also pioneered the use of electronic effects with the trombone.\nRobin is a frequent lecturer, guest soloist and clinician at various colleges and universities in the U.S. and around the world.\nEubanks was voted #1 Trombonist by Down Beat magazine and Jazz Times."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (277, '1WmIo9ORq1IDlovUWFmo4Y', 'Ron', 'Carter', '57db3f59-9c58-4f68-a00e-e044666c4828', 95088, 1, 'https://en.wikipedia.org/wiki/Ron_Carter', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Ron_Carter_Berkeley1.jpg/500px-Ron_Carter_Berkeley1.jpg', 'Brianmcmillen', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Ron_Carter_Berkeley1.jpg', '{"Intro":"Ronald Levin Carter (born May 4, 1937) is an American jazz double bassist. His appearances on 2,221 recording sessions make him the most-recorded jazz bassist in history. He has won three Grammy Awards, and is also a cellist who has recorded numerous times on the instrument. In addition to a solo career of more than 60 years, Carter is well-known for playing on numerous iconic Blue Note albums in the 1960s, as well as being the anchor of trumpeter Miles Davis''s \"Second Great Quintet\" from 1963-1968.\nBeginning with Where? in 1961, Carter''s studio albums as leader also include Uptown Conversation (1969), Blues Farm (1973), All Blues (1973), Spanish Blue (1974), Anything Goes (1975), Yellow & Green (1976), Pastels (1976), Piccolo (1977), Third Plane (1977), Peg Leg (1978), A Song for You (1978), Etudes (1982), The Golden Striker (2003), Dear Miles (2006), and Ron Carter''s Great Big Band (2011).","Early Life":"Carter was born in Ferndale, Michigan. At the age of 10, he started playing the cello, switching to bass while at Cass Technical High School. He earned a B.A. in music from the Eastman School of Music (1959) and a master''s degree in music from the Manhattan School of Music (1961). While at Eastman, Carter began the shift from classical to jazz when he, Pee Wee Ellis and other friends put together a house band to play at the Pythodd Room, a club on Clarissa Street in segregated Rochester, where he met players on the Chitlin Circuit who encouraged him to go to New York City.\nCarter''s first jobs as a jazz musician were playing bass with Chico Hamilton in 1959, followed by freelance work with Jaki Byard, Cannonball Adderley, Randy Weston, Bobby Timmons, and Thelonious Monk.  One of his first recorded appearances was on Hamilton alumnus Eric Dolphy''s Out There, recorded on August 15, 1960, and featuring George Duvivier on bass, Roy Haynes on drums, and Carter on cello. The album''s advanced harmonies and concepts were in step with the third stream movement. In early October 1960, Carter recorded How Time Passes with Don Ellis, and on June 20, 1961, he recorded Where?, his first album as a leader, featuring Dolphy on alto sax, flute, and bass clarinet; Mal Waldron on piano; Charlie Persip on drums; and Duvivier playing basslines on tracks where Carter played cello.","Career":"Carter was a member of the second Miles Davis Quintet in the mid-1960s, which also included Herbie Hancock, Wayne Shorter, and drummer Tony Williams. Carter joined Davis''s group in 1963, appearing on the album Seven Steps to Heaven and the follow-up E.S.P., the latter being the first album to feature only the full quintet. It also featured three of Carter''s compositions (the only time he contributed compositions to Davis''s group). He stayed with Davis until 1968 (when he was replaced by Dave Holland), and participated in a couple of studio sessions with Davis in 1969 and 1970.  Although he played electric bass occasionally during this era of early jazz-rock fusion, he has subsequently stopped playing that instrument, and in the 2000s plays only double bass.\nCarter also performed on some of Hancock, Williams and Shorter''s recordings during the 1960s for Blue Note.  He was a sideman on many Blue Note recordings of the era, playing with Sam Rivers, Freddie Hubbard, Duke Pearson, Lee Morgan, McCoy Tyner, Andrew Hill, Horace Silver, and others. He also played on soul-pop star Roberta Flack''s album First Take and Gil Scott-Heron''s Pieces of a Man, including the iconic bass-line on \"The Revolution Will Not Be Televised\".\nAfter leaving Davis, Carter was for several years a mainstay of CTI Records, making albums under his own name and also appearing on many of the label''s records with a diverse range of other musicians.  Notable musical partnerships in the 1970s and 1980s included Joe Henderson, Houston Person, Hank Jones, Gabor Szabo and Cedar Walton.  During the 1970s he was a member of the New York Jazz Quartet. In 1986, Carter played double bass on \"Big Man on Mulberry Street\" on Billy Joel''s album The Bridge. In 1987, Carter won a Grammy for \"an instrumental composition for the film\" Round Midnight.\nCarter performing at the European Jazz Expò 2007\nIn 1994, he won his second Grammy Award for Best Jazz Instrumental Group for a tribute album to Miles Davis. He appeared on the alternative hip hop group A Tribe Called Quest''s influential album The Low End Theory on a track called \"Verses from the Abstract\". Carter also recorded as a member of the jazz combo the Classical Jazz Quartet. In 1994, Carter appeared on the Red Hot Organization''s compilation album, Stolen Moments: Red Hot + Cool. The album, meant to raise awareness and funds in support of the AIDS epidemic in relation to the African-American community, was heralded as \"Album of the Year\" by TIME.  In 2001, Carter collaborated with Black Star and John Patton to record \"Money Jungle\" for the Red Hot Organization''s compilation album, Red Hot + Indigo, a tribute to Duke Ellington.\nBeginning in the 1990s, Carter became a Distinguished Professor Emeritus of the music department of City College of New York, having taught there for 20 years, and received an honorary doctorate from the Berklee College of Music in spring 2005. He joined the faculty of the Juilliard School in New York City in 2008, teaching bass in the school''s Jazz Studies program. Carter made an appearance in Robert Altman''s 1996 film, Kansas City, at the center of which is a jazz club called the Hey Hey Club. The film''s end credits feature Carter and fellow bassist Christian McBride duetting on \"Solitude\" at the club, owned by a black gangster called Seldom Seen, who was played by a \"show-stealing\" Harry Belafonte. (In a 2023 tribute, Carter would reveal how it came about that Belafonte had been his landlord.)\nCarter sits on the advisory committee of the board of directors of The Jazz Foundation of America and on the Honorary Founder''s Committee. Carter has worked with the Jazz Foundation since its inception to save the homes and the lives of America''s elderly jazz and blues musicians including musicians that survived Hurricane Katrina.\nCarter appeared as himself in an episode of the HBO series Treme entitled \"What Is New Orleans\". His authorized biography, Ron Carter: Finding the Right Notes (ISBN 978-0989982511), by Dan Ouellette, was published by ArtistShare in 2008.\nIn 2010, Carter was honored with France''s premier cultural award, the medallion and title of Commander of the Ordre des Arts et des Lettres. Carter was elected to the DownBeat Jazz Hall of Fame in 2012.\nIn August 2021, Carter was the featured guest in a 47-minute video interview with YouTuber and musician Rick Beato. In November 2021, the Japanese government honored Carter with The Order of the Rising Sun, Gold Rays with Rosette. Japanese officials credited Carter with helping to popularize jazz in Japan and facilitating cultural exchange. In April 2022 Carter sat in with Bob Weir at Radio City Music Hall. In May 2022, Carter celebrated his birthday by releasing a Tiny Desk Concert recorded at the Blue Note Jazz Club featuring Russell Malone and Donald Vega.\nCarter continues to record as a sideman, most recently appearing on Daniele Cordisco''s 2023 album \"Bitter Head.\" In August 2024 he was inducted into the Alabama Jazz Hall of Fame\nCarter at George Wein''s CareFusion Jazz Festival 2009, Newport, Rhode Island","Personal Life":"Carter was married to Janet Hasbrouck Carter, a champion of African and African-American art; she died in 2000. He had two sons, Ron Carter Jr and Myles Carter who was a painter and graffiti artist. Myles’ death, from a stroke, is discussed in Ron Carter: Finding the Right Notes."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (278, '1WmIo9ORq1IDlovUWFmo4Y', 'Ronnie', 'Scott', 'ba22290c-f172-4b19-9176-e63da9991b7d', 272669, 6, 'https://en.wikipedia.org/wiki/Ronnie_Scott', NULL, NULL, NULL, NULL, '{"Intro":"Ronnie Scott OBE (born Ronald Schatt; 28 January 1927 – 23 December 1996) was a British jazz tenor saxophonist and jazz club owner. He co-founded Ronnie Scott''s Jazz Club in London''s Soho district, in 1959.","Life And Career":"Memorial to Ronnie Scott, Golders Green Crematorium\nRonnie Scott was born in Aldgate, East London, into a Jewish family. His father, Joseph Schatt, was of Russian ancestry, and his mother Sylvia''s family attended the Portuguese synagogue in Alie Street. Scott attended the Central Foundation Boys'' School.\nScott began playing in small jazz clubs at the age of 16. He toured with trumpeter Johnny Claes from 1944 to 1945 and with Ted Heath in 1946. That same year, he appeared as one of the band members in George in Civvy Street. He worked with Ambrose, Cab Kaye, and Tito Burns. He was involved in the short-lived musicians'' co-operative Club Eleven band and club (1948–50) with Johnny Dankworth. Scott became an acquaintance of the arranger/composer Tadd Dameron, when the American was working in the UK for Heath, and is reported to have performed with Dameron as the pianist, at one Club Eleven gig.\nScott was a member of the generation of British musicians who worked on the Cunard liner Queen Mary intermittently from 1946 to around 1950. The ship would sail to New York City where they were exposed to Bebop, the new form of jazz being played in the clubs there. Scott was among the earliest British musicians to have been influenced by Charlie Parker and other players of modern jazz.\nIn 1952, Scott joined Jack Parnell''s orchestra and from 1953 to 1956 led a nine-piece band and quintet which included Pete King, with whom he later opened his jazz club, Victor Feldman, Hank Shaw, and Phil Seamen. He co-led The Jazz Couriers with Tubby Hayes from 1957 to 1959 and was leader of a quartet that included Stan Tracey (1960–67).\nFrom 1967 to 1969, Scott was a member of the Kenny Clarke/Francy Boland Big Band, which toured Europe and included Johnny Griffin and Eddie \"Lockjaw\" Davis. Simultaneously he ran his octet, which included John Surman and Kenny Wheeler, and a trio with Mike Carr on keyboards and Bobby Gien on drums (1971–1975). Scott''s other bands often included John Critchinson on keyboards and Martin Drew on drums. He did occasional session work, which included performing the solo on \"Lady Madonna\", the 1968 single by the Beatles, playing on Roy Budd''s score for the film Fear Is the Key (1972), and performing the tenor sax solo on \"I Missed Again\", the 1981 single by Phil Collins.\nIn the 1981 New Year Honours, Scott was appointed an Officer of the Order of the British Empire (OBE) for services to jazz music.\nCharles Mingus said of him in 1961, \"Of the white boys, Ronnie Scott gets closer to the negro blues feeling, the way Zoot Sims does.\" Scott recorded infrequently during the last few decades of his career. He suffered from depression. While recovering from surgery for tooth implants, he died at the age of 69 from an accidental overdose of barbiturate prescribed by his dentist. The Westminster coroner''s inquest in February 1997 recorded a verdict of ''death by misadventure''.\nRonnie Scott''s widow, Mary Scott, and her daughter, Rebecca Scott, wrote the memoir A Fine Kind of Madness: Ronnie Scott Remembered, with a foreword by Spike Milligan. The book was published in 1999 in London by Headline Book Publishing."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (279, '1WmIo9ORq1IDlovUWFmo4Y', 'Roscoe', 'Mitchell', '56f33083-6014-4f4e-9c43-b9652cde55be', 255026, 6, 'https://en.wikipedia.org/wiki/Roscoe_Mitchell', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Deutsches_Jazzfestival_2015_-_DeJonette_Mitchell_Garrison_-_Roscoe_Mitchell_-_02.jpg/500px-Deutsches_Jazzfestival_2015_-_DeJonette_Mitchell_Garrison_-_Roscoe_Mitchell_-_02.jpg', 'Oliver Abels', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Deutsches_Jazzfestival_2015_-_DeJonette_Mitchell_Garrison_-_Roscoe_Mitchell_-_02.jpg', '{"Intro":"Roscoe Mitchell (born August 3, 1940) is an American composer, jazz instrumentalist, and educator, known for being \"a technically superb – if idiosyncratic – saxophonist\". The Penguin Guide to Jazz described him as \"one of the key figures\" in avant-garde jazz; All About Jazz stated in 2004 that he had been \"at the forefront of modern music\" for more than 35 years. Critic Jon Pareles in The New York Times has mentioned that Mitchell \"qualifies as an iconoclast\". In addition to his own work as a bandleader, Mitchell is known for cofounding the Art Ensemble of Chicago and the Association for the Advancement of Creative Musicians (AACM).","Early Life":"Mitchell, who is African American, was born in Chicago, Illinois, United States. He grew up in the Chicago area, where he played saxophone and clarinet at around age twelve. His family was always involved in music with many different styles playing in the house when he was a child as well as having a secular music background. His brother, Norman, in particular was the one who introduced Mitchell to jazz. While attending Englewood High School in Chicago, he furthered his study of the clarinet. In the 1950s, he joined the United States Army, during which time he was stationed in Heidelberg, Germany and played in military parades with fellow saxophonists Albert Ayler and Rubin Cooper, the latter of whom, Mitchell commented, \"took me under his wing and taught me a lot of stuff\". He also studied under the first clarinetist of the Heidelberg Symphony while in Germany. Mitchell returned to the United States in the early 1960s, relocated to the Chicago area, and performed in a band with Wilson Junior College undergraduates Malachi Favors (bass), Joseph Jarman, Henry Threadgill, and Anthony Braxton (all saxophonists). Mitchell also studied with Muhal Richard Abrams and played in his band, the Muhal Richard Abrams'' Experimental Band, starting in 1961."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (280, '1WmIo9ORq1IDlovUWFmo4Y', 'Roy', 'Hargrove', '8cdf780e-b909-4d25-9060-e552e95b3414', 99438, 7, 'https://en.wikipedia.org/wiki/Roy_Hargrove', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Roy_Hargrove_Quintet_%28ZMF_2018%29_IMGP7150.jpg/500px-Roy_Hargrove_Quintet_%28ZMF_2018%29_IMGP7150.jpg', 'Ice Boy Tell', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Roy_Hargrove_Quintet_(ZMF_2018)_IMGP7150.jpg', '{"Intro":"Roy Anthony Hargrove (October 16, 1969 – November 2, 2018) was an American jazz musician and composer whose principal instruments were the trumpet and flugelhorn. He achieved critical acclaim after winning two Grammy Awards for differing styles of jazz in 1998 and 2002. Hargrove primarily played in the hard bop style for the majority of his albums, but also had a penchant for genre-crossing exploration and collaboration with a variety of hip-hop, neo soul, R&B and alternative rock artists. As Hargrove told one reporter, \"I''ve been around all kinds of musicians, and if a cat can play, a cat can play. If it''s gospel, funk, R&B, jazz or hip-hop, if it''s something that gets in your ear and it''s good, that''s what matters.\"","Biography":"Hargrove was born in Waco, Texas, to Roy Allan Hargrove and Jacklyn Hargrove. When he was 9, his family moved to Dallas, Texas. He took lessons at school initially on cornet before turning to trumpet. One of Hargrove''s most profound early influences was a visit to his junior high school by saxophonist David \"Fathead\" Newman, who performed as a sideman in Ray Charles''s Band. Hargrove''s junior high music teacher, Dean Hill, whom Hargrove called his \"musical father\", taught him to improvise and solo. He was discovered by Wynton Marsalis when Marsalis visited the Booker T. Washington High School for the Performing and Visual Arts in Dallas. Hargrove credited trumpeter Freddie Hubbard as having the greatest influence on his sound.\nHargrove continued his musical studies at Boston''s Berklee College of Music, but soon transferred to The New School in New York, enabling Hargrove to frequent the Greenwich Village jazz clubs and participate in jam-sessions, most notably at Bradley''s, where he played alongside many of his mentors and heroes. Hargrove''s first studio recording after relocating to New York was with saxophonist Bobby Watson, for Watson''s album No Question About It. Shortly thereafter, Hargrove recorded with the band Superblue featuring Watson, Mulgrew Miller, Frank Lacy, Don Sickler, and Kenny Washington.Roy Hargrove at Monterey Jazz Festival 1992Hargrove''s debut album as leader, Diamond in the Rough, was released on the Novus/RCA label in 1990. This album, and the three succeeding recordings Hargrove produced for Novus with his quintet, were among the most commercially successful jazz recordings of the early 1990s and made him one of jazz''s in-demand players. His burgeoning fame also propelled him to his first live national television performance in June 1992 on The Tonight Show with Jay Leno. It was during this time that Hargrove topped the category \"Rising Star–Trumpet\" in the DownBeat Critics Poll in 1991, 1992, and 1993 and became associated with the \"Young Lions\", a group of rising jazz musicians — including, among others, Marcus Roberts, Mark Whitfield and Christian McBride — who, embracing the foundations of jazz, played principally bebop, hard bop and the Great American Songbook standards. A number of the \"Young Lions\", including Hargrove, formed Jazz Futures, which released one critically acclaimed album, Live in Concert.\nAs a side project to his solo and quintet recordings, Hargrove also was the leader of The Jazz Networks, an ensemble of American and Japanese musicians which released 5 albums between 1992 and 1996 and featured other notable jazz artists, including Antonio Hart, Rodney Whitaker, and Joshua Redman. These albums were originally released in Japan and Europe only but, following Hargrove''s death, arrangements were made by his estate for their release on US music streaming platforms. During this period, Hargrove also participated in several one-off ensemble recordings, including the albums New York Stories featuring Danny Gatton and Bobby Watson and Pride of Lions featuring Philip Bailey, Billy Childs, and Tony Williams.\nIn 1994, Hargrove signed with Verve and recorded With the Tenors of Our Time, featuring Joe Henderson, Stanley Turrentine, Johnny Griffin, Joshua Redman, and Branford Marsalis. Soon afterwards, Hargrove released his second album for Verve, Family, which included his original song \"Roy Allan\", named after his father, which thereafter became a popular jazz composition for others. That same year, in 1995, he experimented with a trio format on Parker''s Mood, an album recorded with bassist Christian McBride and pianist Stephen Scott. The Penguin Guide to Jazz identifies Parker''s Mood as one of the \"1001 Best Albums\" in the history of the genre.\nAlso in 1995, Hargrove formed the Roy Hargrove Big Band to perform at the Panasonic Village Jazz Festival in New York. The band would go on to record and perform worldwide and feature big band arrangements of Hargrove''s own compositions as well as his favorite songs by respected contemporaries.\nAs Hargrove toured more broadly outside the US, his popularity grew, especially in Europe, Japan, and Latin America. In 1997, the Dutch public television station Nederlandse Programma Stichting (now NTR) aired the documentary \"Jazzportret: Roy Hargrove\" directed by Hans Hylkema, a respected Dutch filmmaker known for music documentaries. The documentary features extensive selections from Hargrove''s live performance at the North Sea Jazz Festival in the Hague in 1996 as well as interviews with Hargrove, his mother, managers and the music teachers in Dallas who guided him.\nIn 1998, Hargrove won the Grammy Award for Best Latin Jazz Album for Habana with Roy Hargrove''s Crisol, an ensemble of Cuban and American musicians which included Chucho Valdés, Russell Malone, Frank Lacy, Jose Luis \"Changuito\" Quintana, and Miguel \"Angá\" Díaz, among others. That same year, Hargrove sat for an extended interview and performed duets with host Marian McPartland on her NPR program Piano Jazz. Hargrove recounted his Texas upbringing, his initial fascination with his father''s cornet, his early influences and thoughts about arranging and more; the program also includes a rare and moving performance by Hargrove, on piano, of his composition \"Ballad for the Children\".\nThroughout the late 1990s and early 2000s, Hargrove collaborated with the Soulquarians, a collective of experimental jazz, hip-hop and soul artists that included Questlove, D''Angelo, J Dilla, and others. Hargrove added jazz and funk-influenced horns to D''Angelo''s Grammy-winning album Voodoo and supported D''Angelo on tour as a member of The Soultronics, a backing \"supergroup\" featuring Questlove and Pino Palladino, among others. That same year, as part of the Soulquarians collective, Hargrove contributed horn performances for recordings by Common and Erykah Badu.\nAlso in 2000, as part of the Verizon Jazz Festival, Hargrove performed in Roz Nixon''s musical production \"Dedicated To Louis Armstrong\" and released his first and only album backed by a string section, Moment to Moment, featuring tasteful accompaniment by the Monterey Jazz Festival Chamber Orchestra.\nIn 2001, Hargrove was selected as a resident artist by the Montreal International Jazz Festival and performed in five different ensembles during the festival: as leader of his own quintet; as leader of a \"special trio\" with Christian McBride and Russell Malone; as a sideman with Monty Alexander and his band; with McBride in a duet; and with the I Musici de Montréal Chamber Orchestra, with which he performed his album, Moment to Moment.\nIn 2002, Hargrove won his second Grammy for Best Jazz Instrumental Album for Directions in Music: Live at Massey Hall with co-leaders Herbie Hancock and Michael Brecker. Hargrove was nominated for four other Grammy Awards during his career.\nAlso in 2002, Hargrove collaborated with D''Angelo, Macy Gray, The Soultronics, and Nile Rodgers on two tracks for Red Hot + Riot: The Music and Spirit of Fela Kuti, a compilation album in tribute to the music of afrobeat pioneer Fela Kuti. He also acted as a sideman for jazz vocalist/pianist Shirley Horn and supported singer Erykah Badu on her album Worldwide Underground.\nFrom 2003 to 2006, he released three albums as the leader of Roy Hargrove''s The RH Factor, a group that blended jazz, soul, hip-hop and funk idioms. The band''s debut album, Hard Groove, was hailed as \"genre-busting\" by critics and ushered in a new era of hip hop-accented jazz. The band''s second release, Strength, was nominated for a Grammy Award for \"Best Contemporary Jazz Album\".\nIn 2007, Hargrove participated as a sideman in the first of two albums he recorded with Jimmy Cobb''s Quartet, Cobb''s Corner, a collection of 10 standards including \"Never Let Me Go\", a track that Hargrove often played in live performances with his own quintet. Two years later, Hargrove added his signature sound again to Cobb''s quartet on the album Jazz in the Key of Blue, another collection of standards, this time also featuring Russell Malone on guitar.Roy Hargrove (right) with his quintet, including Justin Robinson (left), at Dimitriou''s Jazz Alley, Seattle, in 2012After signing with Universal/EmArcy in 2008, Hargrove released Earfood, a quintet recording \"steeped in tradition and sophistication\", which Jazziz selected as one of the five \"essential albums\" of that year. He followed in 2009 with Emergence, an album recorded with the Roy Hargrove Big Band; he received a Grammy nomination for \"Best Improvised Jazz Solo\" for his performance on the track \"Ms. Garvey, Ms. Garvey\" on that record. In 2010, Hargrove released Live at the New Morning, a DVD of an intimate club performance with his quintet in Paris. Thereafter, until his death in 2018, Hargrove did not release additional albums but toured extensively and appeared as a sideman on recordings by Jimmy Cobb, Roy Haynes, Cyrille Aimée, The 1975, D''Angelo, Johnny O''Neal, Kandace Springs and others. Hargrove told KNKX radio in 2017 that recording albums no longer made \"financial sense\".\nIn July 2021, Hargrove''s estate released posthumously via Resonance Records the double-album In Harmony, a live duet recording made in 2006 and 2007 with pianist Mulgrew Miller that returned Hargrove to the Top 5 of the Billboard jazz chart. Slate selected In Harmony as one of the best jazz albums of 2021. The Académie du Jazz awarded In Harmony its prize for \"Best Reissue or Best Unpublished\" album of 2021.\nHargrove was posthumously elected to the DownBeat Magazine \"Jazz Hall of Fame\" in November 2021.\nIn June 2022, the documentary Hargrove, filmed during the final year of his life, debuted at the Tribeca Festival. Hargrove''s estate issued a statement objecting to the film as not what he had envisioned when agreeing to participate. Rio Sakairi, the Artistic Director of New York''s \"The Jazz Gallery\", an art and performance space which Hargrove co-founded in 1995, also issued a statement objecting to accusations made in the film about Hargrove''s managers.\nCelebrating the 30th anniversary of its performance, in October 2023, Jazz at Lincoln Center released a live recording of Hargrove''s original composition The Love Suite: In Mahogany, a five-movement piece which he did not play again live after its debut performance in 1993. Jazziz Magazine called the album an \"unearthed gem\" that \"showcases the much-missed trumpeter’s virtuosity and soulful songwriting\". Jazz critic Nate Chinen of NPR applauded the album as \"a flat-out marvel — maybe the most vivid example we have of Roy''s ability to marshal hard-bop fire in a new form, steeped in swinging tradition but sparking and crackling right now\".\nA year later, in September 2024, Verve Records announced the release of a previously-unheard archival album titled Grande-Terre by Roy Hargrove''s Crisol that had originally been recorded back in 1998. Music critic Sharonne Cohen of Everything Jazz praised the recording, noting that \"Grande-Terre brims with Crisol''s intricate and sophisticated arrangements, Hargrove''s explosive, imaginative and soul-stirring playing, and the band''s powerful, singular sound.\" The New York Times was equally effusive about the album, noting that it \"shows off the high-wire, from-the-gut jazz Hargrove played most nights of his life\". NPR Music included Grande-Terre among its \"50 Best Albums of 2024\", comparing it favorably to its predecessor Habana as \"an even more fluent and focused celebration of Afro-Cuban musical lineage, with Hargrove and his Crisol band both in exceptionally strong form\".\nIn November 2025, Roy Hargrove Legacy announced Live at KNKX, an EP of live radio performances recorded at Seattle public radio station KNKX in 2009 and 2017. Released on January 7, 2026, it features four Hargrove originals: \"Top of My Head\", which was also issued as an advance single, \"The Seattle Vibe\", \"Angels\", and \"Soulful\", none of which were included on any of his studio albums. SoulTracks praised the EP as revealing \"the artistry, emotional depth and spontaneity that made Hargrove one of the defining jazz voices of his generation.\" \"Top of My Head\" received significant airplay on jazz radio, drawing in a new generation of fans.","Early Life And Career":"Hargrove was born in Waco, Texas, to Roy Allan Hargrove and Jacklyn Hargrove. When he was 9, his family moved to Dallas, Texas. He took lessons at school initially on cornet before turning to trumpet. One of Hargrove''s most profound early influences was a visit to his junior high school by saxophonist David \"Fathead\" Newman, who performed as a sideman in Ray Charles''s Band. Hargrove''s junior high music teacher, Dean Hill, whom Hargrove called his \"musical father\", taught him to improvise and solo. He was discovered by Wynton Marsalis when Marsalis visited the Booker T. Washington High School for the Performing and Visual Arts in Dallas. Hargrove credited trumpeter Freddie Hubbard as having the greatest influence on his sound.\nHargrove continued his musical studies at Boston''s Berklee College of Music, but soon transferred to The New School in New York, enabling Hargrove to frequent the Greenwich Village jazz clubs and participate in jam-sessions, most notably at Bradley''s, where he played alongside many of his mentors and heroes. Hargrove''s first studio recording after relocating to New York was with saxophonist Bobby Watson, for Watson''s album No Question About It. Shortly thereafter, Hargrove recorded with the band Superblue featuring Watson, Mulgrew Miller, Frank Lacy, Don Sickler, and Kenny Washington.Roy Hargrove at Monterey Jazz Festival 1992Hargrove''s debut album as leader, Diamond in the Rough, was released on the Novus/RCA label in 1990. This album, and the three succeeding recordings Hargrove produced for Novus with his quintet, were among the most commercially successful jazz recordings of the early 1990s and made him one of jazz''s in-demand players. His burgeoning fame also propelled him to his first live national television performance in June 1992 on The Tonight Show with Jay Leno. It was during this time that Hargrove topped the category \"Rising Star–Trumpet\" in the DownBeat Critics Poll in 1991, 1992, and 1993 and became associated with the \"Young Lions\", a group of rising jazz musicians — including, among others, Marcus Roberts, Mark Whitfield and Christian McBride — who, embracing the foundations of jazz, played principally bebop, hard bop and the Great American Songbook standards. A number of the \"Young Lions\", including Hargrove, formed Jazz Futures, which released one critically acclaimed album, Live in Concert.\nAs a side project to his solo and quintet recordings, Hargrove also was the leader of The Jazz Networks, an ensemble of American and Japanese musicians which released 5 albums between 1992 and 1996 and featured other notable jazz artists, including Antonio Hart, Rodney Whitaker, and Joshua Redman. These albums were originally released in Japan and Europe only but, following Hargrove''s death, arrangements were made by his estate for their release on US music streaming platforms. During this period, Hargrove also participated in several one-off ensemble recordings, including the albums New York Stories featuring Danny Gatton and Bobby Watson and Pride of Lions featuring Philip Bailey, Billy Childs, and Tony Williams.","Verve And Emarcy Era":"In 1994, Hargrove signed with Verve and recorded With the Tenors of Our Time, featuring Joe Henderson, Stanley Turrentine, Johnny Griffin, Joshua Redman, and Branford Marsalis. Soon afterwards, Hargrove released his second album for Verve, Family, which included his original song \"Roy Allan\", named after his father, which thereafter became a popular jazz composition for others. That same year, in 1995, he experimented with a trio format on Parker''s Mood, an album recorded with bassist Christian McBride and pianist Stephen Scott. The Penguin Guide to Jazz identifies Parker''s Mood as one of the \"1001 Best Albums\" in the history of the genre.\nAlso in 1995, Hargrove formed the Roy Hargrove Big Band to perform at the Panasonic Village Jazz Festival in New York. The band would go on to record and perform worldwide and feature big band arrangements of Hargrove''s own compositions as well as his favorite songs by respected contemporaries.\nAs Hargrove toured more broadly outside the US, his popularity grew, especially in Europe, Japan, and Latin America. In 1997, the Dutch public television station Nederlandse Programma Stichting (now NTR) aired the documentary \"Jazzportret: Roy Hargrove\" directed by Hans Hylkema, a respected Dutch filmmaker known for music documentaries. The documentary features extensive selections from Hargrove''s live performance at the North Sea Jazz Festival in the Hague in 1996 as well as interviews with Hargrove, his mother, managers and the music teachers in Dallas who guided him.\nIn 1998, Hargrove won the Grammy Award for Best Latin Jazz Album for Habana with Roy Hargrove''s Crisol, an ensemble of Cuban and American musicians which included Chucho Valdés, Russell Malone, Frank Lacy, Jose Luis \"Changuito\" Quintana, and Miguel \"Angá\" Díaz, among others. That same year, Hargrove sat for an extended interview and performed duets with host Marian McPartland on her NPR program Piano Jazz. Hargrove recounted his Texas upbringing, his initial fascination with his father''s cornet, his early influences and thoughts about arranging and more; the program also includes a rare and moving performance by Hargrove, on piano, of his composition \"Ballad for the Children\".\nThroughout the late 1990s and early 2000s, Hargrove collaborated with the Soulquarians, a collective of experimental jazz, hip-hop and soul artists that included Questlove, D''Angelo, J Dilla, and others. Hargrove added jazz and funk-influenced horns to D''Angelo''s Grammy-winning album Voodoo and supported D''Angelo on tour as a member of The Soultronics, a backing \"supergroup\" featuring Questlove and Pino Palladino, among others. That same year, as part of the Soulquarians collective, Hargrove contributed horn performances for recordings by Common and Erykah Badu.\nAlso in 2000, as part of the Verizon Jazz Festival, Hargrove performed in Roz Nixon''s musical production \"Dedicated To Louis Armstrong\" and released his first and only album backed by a string section, Moment to Moment, featuring tasteful accompaniment by the Monterey Jazz Festival Chamber Orchestra.\nIn 2001, Hargrove was selected as a resident artist by the Montreal International Jazz Festival and performed in five different ensembles during the festival: as leader of his own quintet; as leader of a \"special trio\" with Christian McBride and Russell Malone; as a sideman with Monty Alexander and his band; with McBride in a duet; and with the I Musici de Montréal Chamber Orchestra, with which he performed his album, Moment to Moment.\nIn 2002, Hargrove won his second Grammy for Best Jazz Instrumental Album for Directions in Music: Live at Massey Hall with co-leaders Herbie Hancock and Michael Brecker. Hargrove was nominated for four other Grammy Awards during his career.\nAlso in 2002, Hargrove collaborated with D''Angelo, Macy Gray, The Soultronics, and Nile Rodgers on two tracks for Red Hot + Riot: The Music and Spirit of Fela Kuti, a compilation album in tribute to the music of afrobeat pioneer Fela Kuti. He also acted as a sideman for jazz vocalist/pianist Shirley Horn and supported singer Erykah Badu on her album Worldwide Underground.\nFrom 2003 to 2006, he released three albums as the leader of Roy Hargrove''s The RH Factor, a group that blended jazz, soul, hip-hop and funk idioms. The band''s debut album, Hard Groove, was hailed as \"genre-busting\" by critics and ushered in a new era of hip hop-accented jazz. The band''s second release, Strength, was nominated for a Grammy Award for \"Best Contemporary Jazz Album\".\nIn 2007, Hargrove participated as a sideman in the first of two albums he recorded with Jimmy Cobb''s Quartet, Cobb''s Corner, a collection of 10 standards including \"Never Let Me Go\", a track that Hargrove often played in live performances with his own quintet. Two years later, Hargrove added his signature sound again to Cobb''s quartet on the album Jazz in the Key of Blue, another collection of standards, this time also featuring Russell Malone on guitar.Roy Hargrove (right) with his quintet, including Justin Robinson (left), at Dimitriou''s Jazz Alley, Seattle, in 2012After signing with Universal/EmArcy in 2008, Hargrove released Earfood, a quintet recording \"steeped in tradition and sophistication\", which Jazziz selected as one of the five \"essential albums\" of that year. He followed in 2009 with Emergence, an album recorded with the Roy Hargrove Big Band; he received a Grammy nomination for \"Best Improvised Jazz Solo\" for his performance on the track \"Ms. Garvey, Ms. Garvey\" on that record. In 2010, Hargrove released Live at the New Morning, a DVD of an intimate club performance with his quintet in Paris. Thereafter, until his death in 2018, Hargrove did not release additional albums but toured extensively and appeared as a sideman on recordings by Jimmy Cobb, Roy Haynes, Cyrille Aimée, The 1975, D''Angelo, Johnny O''Neal, Kandace Springs and others. Hargrove told KNKX radio in 2017 that recording albums no longer made \"financial sense\".","Posthumous Career":"In July 2021, Hargrove''s estate released posthumously via Resonance Records the double-album In Harmony, a live duet recording made in 2006 and 2007 with pianist Mulgrew Miller that returned Hargrove to the Top 5 of the Billboard jazz chart. Slate selected In Harmony as one of the best jazz albums of 2021. The Académie du Jazz awarded In Harmony its prize for \"Best Reissue or Best Unpublished\" album of 2021.\nHargrove was posthumously elected to the DownBeat Magazine \"Jazz Hall of Fame\" in November 2021.\nIn June 2022, the documentary Hargrove, filmed during the final year of his life, debuted at the Tribeca Festival. Hargrove''s estate issued a statement objecting to the film as not what he had envisioned when agreeing to participate. Rio Sakairi, the Artistic Director of New York''s \"The Jazz Gallery\", an art and performance space which Hargrove co-founded in 1995, also issued a statement objecting to accusations made in the film about Hargrove''s managers.\nCelebrating the 30th anniversary of its performance, in October 2023, Jazz at Lincoln Center released a live recording of Hargrove''s original composition The Love Suite: In Mahogany, a five-movement piece which he did not play again live after its debut performance in 1993. Jazziz Magazine called the album an \"unearthed gem\" that \"showcases the much-missed trumpeter’s virtuosity and soulful songwriting\". Jazz critic Nate Chinen of NPR applauded the album as \"a flat-out marvel — maybe the most vivid example we have of Roy''s ability to marshal hard-bop fire in a new form, steeped in swinging tradition but sparking and crackling right now\".\nA year later, in September 2024, Verve Records announced the release of a previously-unheard archival album titled Grande-Terre by Roy Hargrove''s Crisol that had originally been recorded back in 1998. Music critic Sharonne Cohen of Everything Jazz praised the recording, noting that \"Grande-Terre brims with Crisol''s intricate and sophisticated arrangements, Hargrove''s explosive, imaginative and soul-stirring playing, and the band''s powerful, singular sound.\" The New York Times was equally effusive about the album, noting that it \"shows off the high-wire, from-the-gut jazz Hargrove played most nights of his life\". NPR Music included Grande-Terre among its \"50 Best Albums of 2024\", comparing it favorably to its predecessor Habana as \"an even more fluent and focused celebration of Afro-Cuban musical lineage, with Hargrove and his Crisol band both in exceptionally strong form\".\nIn November 2025, Roy Hargrove Legacy announced Live at KNKX, an EP of live radio performances recorded at Seattle public radio station KNKX in 2009 and 2017. Released on January 7, 2026, it features four Hargrove originals: \"Top of My Head\", which was also issued as an advance single, \"The Seattle Vibe\", \"Angels\", and \"Soulful\", none of which were included on any of his studio albums. SoulTracks praised the EP as revealing \"the artistry, emotional depth and spontaneity that made Hargrove one of the defining jazz voices of his generation.\" \"Top of My Head\" received significant airplay on jazz radio, drawing in a new generation of fans.","Personal Life And Death":"A quiet and retiring person in life, Hargrove struggled with kidney failure and substance abuse. He died at the age of 49 of cardiac arrest brought on by a kidney disease on November 2, 2018, while hospitalized in New Jersey. According to his long-time manager, Larry Clothier, Hargrove had been on dialysis for the last 14 years of his life.\nHargrove met his wife, Aida Brandes-Hargrove, in 2006 when working with jazz trombonist Slide Hampton; she was the daughter of one of Hampton''s close friends.  In 2020, Brandes-Hargrove and daughter Kamala Hargrove launched the company Roy Hargrove Legacy LLC to preserve and extend his legacy. In 2022, Roy Hargrove Legacy re-formed the Roy Hargrove Big Band, which gives live performances featuring original band members and other musicians who supported Hargrove in his various ensembles."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (281, '1WmIo9ORq1IDlovUWFmo4Y', 'Roy', 'Haynes', '2c090b57-5e9d-49c5-9b71-6f0a331cc1ca', 255556, 4, 'https://en.wikipedia.org/wiki/Roy_Haynes', 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Roy_Haynes_drummer_%28cropped%29.jpg', 'Brianmcmillen', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Roy_Haynes_drummer_(cropped).jpg', '{"Intro":"Roy Owen Haynes (March 13, 1925 – November 12, 2024) was an American jazz drummer. In the 1950s, he was given the nickname \"Snap Crackle\" for his distinctive snare drum sound and musical vocabulary. He is among the most recorded drummers in jazz. In a career spanning more than eight decades, he played swing, bebop, jazz fusion and avant-garde jazz. He is considered to be a pioneer of jazz drumming.\nHaynes led bands, including the Hip Ensemble. His albums Fountain of Youth and Whereas were nominated for a Grammy Award. He was inducted into the Modern Drummer Hall of Fame in 1999.","Career":"Haynes was born on March 13, 1925, in the Roxbury neighborhood of Boston, to Gustavas and Edna Haynes, immigrants from Barbados. His younger brother, Michael E. Haynes, became an important leader in the African American community in Massachusetts, working with Martin Luther King Jr. during the civil rights movement, representing Roxbury in the Massachusetts House of Representatives and for forty years serving as pastor of the Twelfth Baptist Church. King had been a member at the church while he pursued his doctoral degree at Boston University.\nHaynes made his professional debut in 1942 in Boston and began his full-time professional career in 1945. From 1947 to 1949 he worked with saxophonist Lester Young, and from 1949 to 1952 was a member of saxophonist Charlie Parker''s quintet. He also recorded at the time with pianist Bud Powell and saxophonists Wardell Gray and Stan Getz. From 1953 to 1958, he toured with singer Sarah Vaughan and recorded with her. In the 1950s he was given the nickname \"Snap Crackle\". In the 1960s, he was a member of the John Coltrane Quartet, often working as a sub for drummer Elvin Jones. In 1990, he co-led the album Question and Answer with Pat Metheny. Haynes led bands including the Hip Ensemble.\nA tribute song was recorded by Jim Keltner and Charlie Watts of the Rolling Stones, and he appeared on stage with the Allman Brothers Band in 2006 and Page McConnell of Phish in 2008. \"Age seems to have just passed him by,\" Watts observed. \"He''s eighty-three and in 2006 he was voted Best Contemporary Jazz Drummer . He''s amazing.\"\nHaynes, George Wein''s CareFusion Jazz Festival 55, Newport, Rhode Island, August 2009\nIn 2008, Haynes voiced a DJ for the fictional classic jazz radio station, Jazz Nation Radio 108.5 on the open-world video game Grand Theft Auto IV. His last album, Roy-Alty, was released in 2011.","Personal Life":"His son Graham Haynes is a cornetist; another son Craig Holiday Haynes and grandson Marcus Gilmore are both drummers.\nHaynes was known to celebrate his birthdays on stage and in later years at the Blue Note Jazz Club in New York City. His 95th birthday celebration in 2020 was canceled due to the COVID-19 pandemic.\nOn November 12, 2024, following a short illness, Haynes died at age 99 in Nassau County, New York, on the South Shore of Long Island."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (282, '1WmIo9ORq1IDlovUWFmo4Y', 'Ruby', 'Braff', '30235fb0-eaab-4e4e-a4cb-a64c565446c9', 296955, 7, 'https://en.wikipedia.org/wiki/Ruby_Braff', NULL, NULL, NULL, NULL, '{"Intro":"Reuben \"Ruby\" Braff (March 16, 1927 – February 9, 2003) was an American jazz trumpeter and cornetist. Jack Teagarden was once asked about him on the Garry Moore television show and described Ruby as \"the Ivy League Louis Armstrong\".\nBraff, who was of Jewish heritage, was born in Boston, Massachusetts, United States. He was renowned for working in an idiom ultimately derived from the playing of Louis Armstrong and Bix Beiderbecke. He began playing in local clubs in the 1940s. In 1949, he was hired to play with the Edmond Hall Orchestra at the Savoy Cafe of Boston. He relocated to New York in 1953 where he was much in demand for band dates and recordings.\nHe resided in Harwich, Massachusetts and died of complications from emphysema, heart failure, and glaucoma on February 9, 2003, in Chatham, Massachusetts. He had spent a good part of his life living in the Riverdale section of The Bronx, New York City."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (283, '1WmIo9ORq1IDlovUWFmo4Y', 'Scott', 'Joplin', 'aec8a328-d2e8-4780-b2ea-318c7f8d6f75', 272275, 3, 'https://en.wikipedia.org/wiki/Scott_Joplin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Scott_Joplin_in_1912.jpg/500px-Scott_Joplin_in_1912.jpg', 'Unknown authorUnknown author', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Scott_Joplin_in_1912.jpg', '{"Intro":"Scott Joplin (November 24, 1868 – April 1, 1917) was an American composer and pianist. Dubbed the \"King of Ragtime\", he composed more than 40 ragtime pieces, one ragtime ballet (original version of \"The Ragtime Dance\", 1899/1902), and two operas. One of his first and most popular pieces, the \"Maple Leaf Rag\", became the genre''s first and most influential hit, later being recognized as the quintessential rag. Joplin considered ragtime to be a form of classical music meant to be played in concert halls and largely disdained the performance of ragtime as honky tonk music most common in saloons.\nJoplin grew up in a musical family of railway laborers in Texarkana, Texas. During the late 1880s, he traveled the American South as a musician. He went to Chicago for the World''s Fair of 1893, which helped make ragtime a national craze by 1897. Joplin moved to Sedalia, Missouri, in 1894 and worked as a piano teacher. He began publishing music in 1895, and his \"Maple Leaf Rag\" in 1899 brought him fame and a steady income. In 1901, Joplin moved to St. Louis and two years later scored his first opera, A Guest of Honor. It was confiscated—along with his belongings—for non-payment of bills and is now considered lost. In 1907, Joplin moved to New York City to (unsuccessfully) find a producer for a new opera. In 1916, Joplin descended into dementia from neurosyphilis. His 1917 death marks the end of the ragtime era.\nJoplin''s music was rediscovered and returned to popularity in the early 1970s with the release of a million-selling album recorded by Joshua Rifkin. This was followed by the Academy Award–winning 1973 film The Sting, which featured several of Joplin''s compositions. Treemonisha, his second opera, was produced in 1972; and, in 1976, Joplin was awarded a Pulitzer Prize.","Early Life":"Joplin was the second of six children born to Giles Joplin, a former slave from North Carolina, and Florence Givens, a freeborn African-American woman from Kentucky. His birth date was accepted by early biographers Rudi Blesh and James Haskins as November 24, 1868, although later biographer Edward A. Berlin showed this was most likely incorrect. Nonetheless, it is generally accepted he was born between the summer of 1867 and January 1868. There is disagreement over his exact place of birth in Texas, with Blesh identifying Texarkana, and Berlin showing the earliest record of Joplin being the June 1870 census which locates him as a two-year-old in Linden (about 40 miles from Texarkana).\nBy 1880, the Joplins had moved to Texarkana, Arkansas, where Giles worked as a railroad laborer and Florence as a cleaner. As Joplin''s father had played the violin for plantation parties in North Carolina and his mother sang and played the banjo, Joplin was given a rudimentary musical education by his family, and from the age of seven he was allowed to play the piano while his mother cleaned.\nAt some point in the early 1880s, Giles Joplin left the family for another woman and Florence struggled to support her children through domestic work. Biographer Susan Curtis speculates that Florence''s support of her son''s musical education was a critical factor behind her separation from Giles, who wanted the boy to pursue practical employment that would supplement the family income.\nAt 16, Joplin performed in a vocal quartet with three other boys in and around Texarkana, also playing piano. He also taught guitar and mandolin. According to a family friend, the young Joplin was serious and ambitious in studying music and playing the piano after school. While a few local teachers aided him, he received most of his musical education from Julius Weiss, a German-born American Jewish music professor who had immigrated to Texas in the late 1860s and was employed as music tutor by a prominent local business family. Weiss, as described by San Diego Jewish World writer Eric George Tauber, \"was no stranger to  race hatred ... As a Jew in Germany, he was often slapped and called a ''Christ-killer''\". Weiss had studied music at a German university and was listed in town records as a professor of music. Impressed by Joplin''s talent, and realizing the Joplin family''s dire straits, Weiss taught him free of charge. While tutoring Joplin from the ages of 11 to 16, Weiss introduced him to folk and classical music, including opera. Weiss helped Joplin appreciate music as an \"art as well as an entertainment\" and helped Florence acquire a used piano. According to Joplin''s widow Lottie, Joplin never forgot Weiss. In his later years, after achieving fame as a composer, Joplin sent his former teacher \"gifts of money when he was old and ill\" until Weiss died.","Life In The Southern States And Chicago":"In the late 1880s, having performed at various local events as a teenager, Joplin gave up his job as a railroad laborer and left Texarkana to become a traveling musician. Little is known about his movements at this time, although he is recorded in Texarkana in July 1891 as a member of the Texarkana Minstrels, who were raising money for a monument to Jefferson Davis, president of the former Confederate States of America. However, Joplin soon learned that there were few opportunities for black pianists. Churches and brothels were among the few options for steady work. Joplin played pre-ragtime \"jig-piano\" in various red-light districts throughout the mid-South, and some claim he was in Sedalia and St. Louis, Missouri, during this time.\nIn 1893, while in Chicago for the World''s Fair, Joplin formed a band in which he played cornet and also arranged the band''s music. Although the World''s Fair minimized the involvement of African Americans, black performers still came to the saloons, cafés, and brothels that lined the fair. The exposition was attended by 27 million visitors and had a profound effect on many areas of American cultural life, including ragtime. Although specific information is sparse, numerous sources have credited the Chicago World''s Fair with spreading the popularity of ragtime. Joplin found that his music, as well as that of other black performers, was popular with visitors. By 1897, ragtime had become a national craze in U.S. cities and was described by the St. Louis Dispatch as \"a veritable call of the wild, which mightily stirred the pulses of city-bred people\".","Life In Missouri":"1906 recording of the \"Maple Leaf Rag\" by the United States Marine Band. This is the oldest surviving recording of the \"Maple Leaf Rag\"\nFront cover of the third edition of the \"Maple Leaf Rag\" sheet music with Joplin portrait\nIn 1894, Joplin arrived in Sedalia, Missouri. At first, Joplin stayed with the family of Arthur Marshall, a 13-year-old boy who later became one of Joplin''s students and a ragtime composer in his own right. There is no record of Joplin having a residence in the town until 1904, as Joplin was making a living as a touring musician.\nThere is little precise evidence known about Joplin''s activities at this time, although he performed as a solo musician at dances and at the major black clubs in Sedalia, the Black 400 Club and the Maple Leaf Club. He performed in the Queen City Cornet Band and his own six-piece dance orchestra. A tour with his own singing group, the Texas Medley Quartet, gave him his first opportunity to publish his own compositions, and it is known that he went to Syracuse, New York, and Texas. Three businessmen from Syracuse (M. L. Mantell and the Leiter brothers) published Joplin''s first two works, the songs \"Please Say You Will\" and \"A Picture of Her Face\", in 1895. Joplin''s visit to Temple, Texas, enabled him to have three pieces published there in 1896, including the \"Great Crush Collision March\", which commemorated a planned train crash on the Missouri–Kansas–Texas Railroad on September 15 that he may have witnessed. The march was described by one of Joplin''s biographers as a \"special ... early essay in ragtime\". While in Sedalia, Joplin taught piano to students who included future ragtime composers Arthur Marshall, Brun Campbell and Scott Hayden. Joplin enrolled at the George R. Smith College, where he apparently studied \"advanced harmony and composition\". The college''s records were destroyed in a fire in 1925, and biographer Edward A. Berlin notes that it was unlikely that a small college for African-Americans would be able to provide such a course.\nAlthough there were hundreds of rags in print by the time the \"Maple Leaf Rag\" was published, Joplin was not far behind. He completed his first published rag, \"Original Rags\" in 1897, the same year that the first ragtime work appeared in print, the \"Mississippi Rag\" by William Krell. The \"Maple Leaf Rag\" was likely to have been known in Sedalia before its publication in 1899; Brun Campbell claimed to have seen the manuscript of the work in around 1898. The exact circumstances that led to the publication of the \"Maple Leaf Rag\" are unknown and a number of versions of the event contradict each other. After several unsuccessful approaches to publishers, Joplin signed a contract on August 10, 1899, with John Stillwell Stark, a retailer of musical instruments who became his most important publisher. The contract stipulated that Joplin would receive a 1% royalty on all sales of the rag, with a minimum sales price of 25 cents. With the inscription \"To the Maple Leaf Club\" prominently visible along the top of at least some editions, it is likely that the rag was named after the Maple Leaf Club, although there is no direct evidence to prove the link, and there were many other possible sources for the name in and around Sedalia at the time.\nScott Joplin House in St. Louis, Missouri\nCover of Scott Joplin''s 1905 work \"Bethena\"; the woman on the cover may be Joplin''s second wife, Freddie Alexander\nThere have been many claims about the sales of the \"Maple Leaf Rag\", one being that Joplin was the first musician to sell 1 million copies of a piece of instrumental music. Joplin''s first biographer, Rudi Blesh, wrote that during its first six months the piece sold 75,000 copies and became \"the first great instrumental sheet music hit in America\". However, research by Joplin''s later biographer Edward A. Berlin demonstrated that this was not the case; the initial print-run of 400 took one year to sell, and, under the terms of Joplin''s contract with a 1% royalty, would have given Joplin an income of $4 (or approximately $155 at current prices). Later sales were steady and would have given Joplin an income that would have covered his expenses. In 1909, estimated sales would have given him an income of $600 annually (approximately $16,968 in current prices).\nThe \"Maple Leaf Rag\" did serve as a model for the hundreds of rags to come from future composers, especially in the development of classic ragtime. After the publication of the \"Maple Leaf Rag\", Joplin was soon being described as \"King of rag time writers\", not least by himself on the covers of his own work, such as \"The Easy Winners\" and \"Elite Syncopations\".\nDuring his time in St. Louis, Joplin collaborated with Scott Hayden in the composition of four rags. It was in St. Louis that Joplin produced some of his best-known works, including \"The Entertainer\", \"March Majestic\", and the short theatrical work \"The Ragtime Dance\". In 1901, Joplin married his first wife Belle Jones (1875–1903) a sister-in-law of Scott Hayden. By 1903, the Joplins had moved to a 13-room house, renting some of the rooms to lodgers, who included pianist-composers Arthur Marshall and Scott Hayden. Joplin did not work as a pianist in the saloons in St Louis, which was usually a major source of income for musicians, as he was \"probably outclassed by the competition\" and was, according to Stark''s son, \"a mediocre pianist\". Biographer Berlin speculated that by 1903 Joplin was already showing early signs of syphilis, which reduced his coordination and \"pianistic skills\". In 1903, Joplin''s only child—a daughter—died. After returning to Arkansas, Joplin and his first wife drifted apart, ending their marriage.\nIn June 1904, Joplin married Freddie Alexander of Little Rock, Arkansas, the young woman to whom he had dedicated \"The Chrysanthemum\". She died on September 10, 1904, of complications resulting from a cold, ten weeks after their wedding. \"Bethena\", Joplin''s first work copyrighted after Freddie''s death, was described by one biographer as \"an enchantingly beautiful piece that is among the greatest of ragtime waltzes\".\nDuring this time, Joplin created an opera company of 30 people and produced his first opera A Guest of Honor for a national tour. It is not certain how many productions were staged, or even whether this was an all-black show or a racially mixed production. During the tour, either in Springfield, Illinois, or Pittsburg, Kansas, someone associated with the company stole the box office receipts. Joplin could not meet the company''s payroll or pay for its lodgings at a theatrical boarding house. It is believed that the score for A Guest of Honor was lost and perhaps destroyed because of non-payment of the company''s boarding house bill.","Later Years And Death":"Front cover of the \"Wall Street Rag\" (1909) sheet music\nIn 1907, Joplin moved to New York City, which he believed was the best place to find a producer for a new opera. After his move to New York, Joplin met Lottie Stokes, whom he married in 1909. In 1911, unable to find a publisher, Joplin undertook the financial burden of publishing Treemonisha himself in piano-vocal format. In 1915, as a last-ditch effort to see it performed, he invited a small audience to hear it at a rehearsal hall in Harlem. Poorly staged and with only Joplin on piano accompaniment, it was \"a miserable failure\" to a public not ready for \"crude\" black musical forms—so different from the European grand opera of that time. The audience, including potential backers, was indifferent and walked out. Scott writes that \"after a disastrous single performance...Joplin suffered a breakdown. He was bankrupt, discouraged, and worn out.\" He concludes that few American artists of his generation faced such obstacles: \"Treemonisha went unnoticed and unreviewed, largely because Joplin had abandoned commercial music in favor of art music, a field closed to African Americans.\" It was not until the 1970s that the opera received a full theatrical staging.\nIn 1914, Joplin and Lottie self-published his \"Magnetic Rag\" as the Scott Joplin Music Company, which he had formed the previous December. Biographer Vera Brodsky Lawrence speculates that Joplin was aware of his advancing deterioration due to syphilis and was \"consciously racing against time\". In her sleeve notes on the 1992 Deutsche Grammophon release of Treemonisha, she notes that he \"plunged feverishly into the task of orchestrating his opera, day and night, with his friend Sam Patterson standing by to copy out the parts, page by page, as each page of the full score was completed.\"\nBy 1916, Joplin had developed tertiary syphilis, but more specifically it was likely neurosyphilis. On February 2, 1917, he was admitted to Manhattan State Hospital, a mental institution. The \"King of Ragtime\" died there on April 1 of syphilitic dementia at the age of 48 and was buried in a pauper''s grave that remained unmarked for 57 years. His grave, located at St. Michael''s Cemetery in East Elmhurst was finally given a marker in 1974, the year The Sting, which showcased his music, won Best Picture at the Oscars.","Legacy":"A commemorative plaque to Joplin in Texas\nJoplin and his fellow ragtime composers rejuvenated American popular music, fostering an appreciation for African American music among European Americans by creating exhilarating and liberating dance tunes. \"Its syncopation and rhythmic drive gave it a vitality and freshness attractive to young urban audiences indifferent to Victorian proprieties...Joplin''s ragtime expressed the intensity and energy of a modern urban America.\"\nJoshua Rifkin, a leading Joplin recording artist, wrote, \"A pervasive sense of lyricism infuses his work, and even at his most high-spirited, he cannot repress a hint of melancholy or adversity...He had little in common with the fast and flashy school of ragtime that grew up after him.\" Joplin historian Bill Ryerson adds that \"In the hands of authentic practitioners like Joplin, ragtime was a disciplined form capable of astonishing variety and subtlety...Joplin did for the rag what Chopin did for the mazurka. His style ranged from tones of torment to stunning serenades that incorporated the bolero and the tango.\" Biographer Susan Curtis wrote that Joplin''s music had helped to \"revolutionise American music and culture\" by removing Victorian restraint.\nComposer and actor Max Morath found it striking that the vast majority of Joplin''s work did not enjoy the popularity of the \"Maple Leaf Rag\", because while the compositions were of increasing lyrical beauty and delicate syncopation, they remained obscure and unheralded during his life. According to music historian Ian Whitcomb, Joplin apparently realized that his music was ahead of its time:\n opined that \"Maple Leaf Rag\" would make him \"King of Ragtime Composers\" but he also knew that he would not be a pop hero in his own lifetime. \"When I''m dead twenty-five years, people are going to recognize me\", he told a friend.\nJust over thirty years later he was recognized, and later historian Rudi Blesh wrote a large book about ragtime, which he dedicated to the memory of Joplin.\nAlthough he was penniless and disappointed at the end of his life, Joplin set the standard for ragtime compositions and played a key role in the development of ragtime music. While ragtime''s popularity faded around then, New Orleans jazz, stride, and novelty piano subsequently adopted many of its traits. And as a pioneer composer and performer, he helped pave the way for young black artists to reach American audiences of all races. After his death, jazz historian Floyd Levin noted: \"Those few who realized his greatness bowed their heads in sorrow. This was the passing of the king of all ragtime writers, the man who gave America a genuine native music.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (284, '1WmIo9ORq1IDlovUWFmo4Y', 'Scott', 'Lafaro', '97cc902a-2850-4db8-8218-186f3b5a1ea5', 272982, 1, 'https://en.wikipedia.org/wiki/Scott_LaFaro', NULL, NULL, NULL, NULL, '{"Intro":"Rocco Scott LaFaro (April 3, 1936 – July 6, 1961) was an American jazz double bassist known for his work with the Bill Evans Trio. LaFaro broke new ground on the instrument, developing a countermelodic style of accompaniment rather than playing traditional walking basslines, as well as virtuosity that was practically unmatched by any of his contemporaries. Despite his short career and death at the age of 25, he remains one of the most influential jazz bassists, and was ranked number 16 on Bass Player magazine''s top 100 bass players of all time.","Early Life":"LaFaro was born in Newark, New Jersey, the son of a big band musician. He was five when his family moved to Geneva, New York. He started playing piano in elementary school, bass clarinet in middle school, and tenor saxophone when he entered high school. He took up double bass at 18 before entering college because learning a string instrument was required of music education majors. After three months at Ithaca College, he concentrated on bass. He played in groups at the College Spa and Joe''s Restaurant on State Street in downtown Ithaca.","Career":"Beginning in 1955, he was a member of the Buddy Morrow big band. He left that organization to work in Los Angeles. LaFaro spent most of his days practicing his instrument. He practiced from sheet music for the higher-pitched clarinet to improve his facility with the upper register for bass. Fellow bassist Red Mitchell taught him how to pluck strings with both the index and middle fingers independently. For much of 1958, LaFaro was with pianist/vibraphonist Victor Feldman''s band, also recording with Hampton Hawes.\nIn 1959, after working with trumpeter Chet Baker, bandleader Stan Kenton, vibraphonist Cal Tjader, and clarinetist Benny Goodman, LaFaro returned east and joined Bill Evans, who had recently left the Miles Davis Sextet. With Evans and drummer Paul Motian he developed the counter-melodic style that would come to characterize his playing. Evans, LaFaro, and Motian were committed to the idea of three equal voices in the trio, working together for a singular musical idea and often without any musician explicitly keeping time.\nBy late 1960, LaFaro was in demand as a bassist. He replaced Charlie Haden as Ornette Coleman''s bassist in January 1961. For a time, Haden and LaFaro shared an apartment. He also played in Stan Getz''s band between jobs with the Bill Evans trio. Around this time, he received a greeting card from Miles Davis that suggested Davis wanted to hire him.\nIn June 1961, the Bill Evans trio began two weeks of performances at the Village Vanguard in New York City. The trio attracted attention for its style. The last day was recorded for two albums, Sunday at the Village Vanguard and Waltz for Debby.","Death":"LaFaro died in an automobile accident on July 6, 1961, in Seneca, New York, on U.S. Route 20 between Geneva and Canandaigua, four days after accompanying Stan Getz at the Newport Jazz Festival. According to Paul Motian, the death of LaFaro left Bill Evans \"numb with grief,\" \"in a state of shock,\" and \"like a ghost.\" Obsessively, he played \"I Loves You, Porgy,\" a tune that had become synonymous with him and LaFaro. Evans stopped performing for several months.\nEvans said that LaFaro had been \"one of the most, if not the most outstanding talents in jazz.\" Legendary bassist Ray Brown added, \"This was one of the most talented youngsters I''ve seen come up in a long time. For his age, he really had it covered. ... It''s a shame, really a shame. It''s going to set the instrument back ten years.\" Motian noted, \"We were supposed to make a record date with Miles : the trio, Bill, myself and Scott. ... We were talking to Miles about it, it was all set up, and then Scott got killed and the whole thing got forgotten.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (285, '1WmIo9ORq1IDlovUWFmo4Y', 'Sheila', 'Jordan', '92d3929a-f2e3-41e1-9cfa-54181a185f2c', 318910, 5, 'https://en.wikipedia.org/wiki/Sheila_Jordan', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Sheila_Jordan_Unterfahrt_2011-10-19-001.jpg/500px-Sheila_Jordan_Unterfahrt_2011-10-19-001.jpg', 'OhWeh', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Sheila_Jordan_Unterfahrt_2011-10-19-001.jpg', '{"Intro":"Sheila Jeannette Jordan (née Dawson; November 18, 1928 – August 11, 2025) was an American jazz singer and songwriter. She recorded as a session musician with an array of critically acclaimed artists in addition to recording her own albums. Jordan pioneered a bebop and scat jazz singing style, with an upright bass as the only accompaniment. Jordan''s music has earned praise from many critics, particularly for her ability to improvise lyrics; Scott Yanow described her as \"one of the most consistently creative of all jazz singers\". Charlie Parker often introduced Jordan as \"the lady with the million dollar ears\".","Life And Career":"Sheila Jeanette Dawson was born in Detroit, on November 18, 1928. Her father left soon after her birth and remarried. (She later met her half-siblings.) Her mother struggled with alcoholism, and she was soon sent to live with her maternal grandparents in Summerhill, Pennsylvania, a small coal mining town in the Allegheny Mountains. Her grandparents raised her with little warmth or affection, and her grandfather also struggled with alcoholism. She recalled their hardship and poverty:We were probably the poorest people in a poor town . e had an outhouse and no water in the house . In the wintertime  sleep in one bedroom without any sheets or pillowcases on the beds; we just had blankets.\nJordan returned to live with her mother in Detroit by 1942, performing as a jazz club singer and pianist. She helped write lyrics to Charlie Parker''s music in the trio Skeeter, Mitch, and Jean (Skeeter Spight, Leroi Mitchell, and Sheila \"Jean\"). They met Parker at his Detroit performances, and he invited them to sing.\nJordan moved to New York City in 1951, studying music theory with Lennie Tristano and Charles Mingus. She focused on the music of Parker, whom she befriended and considered a teacher, later recalling: \"I guess I was chasin'' the Bird .\" Asked if the song \"Chasin'' the Bird\" was written for her, she said: \"No. I don''t know how that rumor got started.\" In 1952, she married a Parker bandmate, pianist Duke Jordan.\nIn the early 1960s, she performed at the Page Three Club in Greenwich Village with pianist Herbie Nichols and at other New York venues. Duke Jordan''s heroin addiction contributed to their 1962 divorce, but they had a daughter, Tracey, whom she \"could truly love\" and was \"sure would love me back\". Jordan partly withdrew from clubs in the 1960s to raise Tracey, and sang in church instead. She worked as a typist and legal secretary for 20 years, with less time for music until she was aged 58. In 1962, she recorded \"You Are My Sunshine\" with George Russell on his album The Outer View (Riverside) and also recorded her debut album Portrait of Sheila, released on Blue Note in 1963. She began a long collaboration with Steve Kuhn in the early 1960s and played with Don Heckman (1967–68), Lee Konitz (1972), and Roswell Rudd (1972–75).\nIn 1974, Jordan was Artist-in-Residence at the City College of New York, and taught there from 1978 to 2005. She received the Manhattan Association of Cabarets & Clubs (MAC) Lifetime Achievement Award in 2006, while celebrating 28 years as an adjunct professor of music. She also taught at the University of Massachusetts at Amherst and the Vermont Jazz Center, Interplay Jazz and Arts, as well as teaching international workshops.\nOn July 12, 1975, she recorded Confirmation. One year later she released the duet album Sheila, with Arild Andersen for SteepleChase. In 1979, she founded a quartet with Steve Kuhn, Harvie S, and Bob Moses. During the 1980s, she worked with Harvie S as a duo and played on several records with him. Until 1987 she worked in an advertising agency and recorded Lost and Found in 1989.\nJordan was a songwriter who worked in bebop and free jazz. In addition to the aforementioned musicians, she recorded with the George Gruntz Concert Jazz Band, Cameron Brown, Carla Bley, and Steve Swallow.  Jordan led recordings for Blue Note,  East Wind, ECM, Grapevine, Muse, Palo Alto, and SteepleChase.\nIn 2012, she received the NEA Jazz Masters Award. Her biography, Jazz Child: A Portrait of Sheila Jordan, written by vocalist and educator Ellen Johnson, was published in 2014. Jordan describes her own struggles with addiction in the book.\nJordan died at her apartment in New York City, on August 11, 2025, at the age of 96.","Early Career":"Sheila Jeanette Dawson was born in Detroit, on November 18, 1928. Her father left soon after her birth and remarried. (She later met her half-siblings.) Her mother struggled with alcoholism, and she was soon sent to live with her maternal grandparents in Summerhill, Pennsylvania, a small coal mining town in the Allegheny Mountains. Her grandparents raised her with little warmth or affection, and her grandfather also struggled with alcoholism. She recalled their hardship and poverty:We were probably the poorest people in a poor town . e had an outhouse and no water in the house . In the wintertime  sleep in one bedroom without any sheets or pillowcases on the beds; we just had blankets.\nJordan returned to live with her mother in Detroit by 1942, performing as a jazz club singer and pianist. She helped write lyrics to Charlie Parker''s music in the trio Skeeter, Mitch, and Jean (Skeeter Spight, Leroi Mitchell, and Sheila \"Jean\"). They met Parker at his Detroit performances, and he invited them to sing.\nJordan moved to New York City in 1951, studying music theory with Lennie Tristano and Charles Mingus. She focused on the music of Parker, whom she befriended and considered a teacher, later recalling: \"I guess I was chasin'' the Bird .\" Asked if the song \"Chasin'' the Bird\" was written for her, she said: \"No. I don''t know how that rumor got started.\" In 1952, she married a Parker bandmate, pianist Duke Jordan.","Later Career (1960–2025)":"In the early 1960s, she performed at the Page Three Club in Greenwich Village with pianist Herbie Nichols and at other New York venues. Duke Jordan''s heroin addiction contributed to their 1962 divorce, but they had a daughter, Tracey, whom she \"could truly love\" and was \"sure would love me back\". Jordan partly withdrew from clubs in the 1960s to raise Tracey, and sang in church instead. She worked as a typist and legal secretary for 20 years, with less time for music until she was aged 58. In 1962, she recorded \"You Are My Sunshine\" with George Russell on his album The Outer View (Riverside) and also recorded her debut album Portrait of Sheila, released on Blue Note in 1963. She began a long collaboration with Steve Kuhn in the early 1960s and played with Don Heckman (1967–68), Lee Konitz (1972), and Roswell Rudd (1972–75).\nIn 1974, Jordan was Artist-in-Residence at the City College of New York, and taught there from 1978 to 2005. She received the Manhattan Association of Cabarets & Clubs (MAC) Lifetime Achievement Award in 2006, while celebrating 28 years as an adjunct professor of music. She also taught at the University of Massachusetts at Amherst and the Vermont Jazz Center, Interplay Jazz and Arts, as well as teaching international workshops.\nOn July 12, 1975, she recorded Confirmation. One year later she released the duet album Sheila, with Arild Andersen for SteepleChase. In 1979, she founded a quartet with Steve Kuhn, Harvie S, and Bob Moses. During the 1980s, she worked with Harvie S as a duo and played on several records with him. Until 1987 she worked in an advertising agency and recorded Lost and Found in 1989.\nJordan was a songwriter who worked in bebop and free jazz. In addition to the aforementioned musicians, she recorded with the George Gruntz Concert Jazz Band, Cameron Brown, Carla Bley, and Steve Swallow.  Jordan led recordings for Blue Note,  East Wind, ECM, Grapevine, Muse, Palo Alto, and SteepleChase.\nIn 2012, she received the NEA Jazz Masters Award. Her biography, Jazz Child: A Portrait of Sheila Jordan, written by vocalist and educator Ellen Johnson, was published in 2014. Jordan describes her own struggles with addiction in the book.\nJordan died at her apartment in New York City, on August 11, 2025, at the age of 96."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (286, '1WmIo9ORq1IDlovUWFmo4Y', 'Slim', 'Gaillard', '48b82408-3db2-4a96-bd97-129fbdeddfc4', 257745, 5, 'https://en.wikipedia.org/wiki/Slim_Gaillard', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Slim_Gaillard.jpg/500px-Slim_Gaillard.jpg', 'Phil Wight', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Slim_Gaillard.jpg', '{"Intro":"Bulee \"Slim\" Gaillard (January 9, 1911 – February 26, 1991), also known as McVouty, was an American jazz singer and songwriter who played piano, guitar, vibraphone, and tenor saxophone. Gaillard was noted for his comedic vocalese singing and word play in his own constructed language called \"Vout-o-Reenee\", for which he wrote a dictionary.\nIn addition to English, he spoke five languages (Spanish, German, Greek, Arabic, and Armenian) with varying degrees of fluency.\nHe rose to prominence in the late 1930s with hits such as \"Flat Foot Floogie (with a Floy Floy)\" and \"Cement Mixer (Put-Ti-Put-Ti)\" after forming Slim and Slam with Leroy Eliot \"Slam\" Stewart. During World War II, Gaillard served in the U.S. Army Air Forces. In 1944, he resumed his music career and performed with such notable jazz musicians as Charlie Parker, Dizzy Gillespie, and Dodo Marmarosa.\nIn the 1960s and 1970s, he acted in films—sometimes as himself—and also appeared in bit parts in television series such as Roots: The Next Generations. Gaillard resumed touring the circuit of European jazz festivals during the 1980s.","Early Life":"Along with Gaillard''s birthdate, his lineage and place of birth are disputed. Many sources state that he was born in Detroit, Michigan, though Gaillard said himself that he was born in Santa Clara, Cuba, of an Afro-Cuban mother called Maria (Mary Gaillard) and a German-Jewish father called Theophilus (Theophilus Rothschild) who worked as a ship''s steward.\nDuring an interview in 1989, Gaillard added: \"They all think I was born in Detroit because that was the first place I got into when I got to America.\" However, the 1920 census lists one \"Beuler Gillard\"  as living in Pensacola, Florida, having been born in April 1918 in Alabama. Researchers Bob Eagle and Eric LeBlanc have concluded that Gaillard was probably born in June 1918 in Claiborne, Alabama, where a \"Theophilus Rothchild\"  had been raised the son of a successful merchant in the small town of Burnt Corn; other documents give his name as Wilson, Bulee, or Beuler Gillard or Gaillard. Several documents from the federal government of the United States give an earlier birth year: Gaillard''s draft registration card—dated October 14, 1940, and signed by him—lists his birth date as January 4, 1911, in Pensacola, Florida; his World War II enlistment record with the U.S. Army also lists his birth year as 1911; and his entry in the Social Security Death Index gives his date of birth as January 9, 1911.\nAt age 12, Gaillard accompanied his father on a world voyage and was accidentally left behind on the island of Crete. On a television documentary in 1989, he said, \"When I was stranded in Crete, I was only 12 years old. I stayed there for four years. I traveled on the boats to Beirut and Syria and I learned to speak the language and the people''s way of life.\" After learning a few words of Greek, he worked on the island \"making shoes and hats\". He then joined a ship working the eastern Mediterranean ports, mainly Beirut, where he picked up some knowledge of Arabic.\nWhen Gaillard was about 15, he re-crossed the Atlantic, hoping the ship would take him home to Cuba, but it was bound for the U.S. and he ended up in Detroit. He never saw either of his parents again. Alone and unable to speak English, he tried to get a job at Ford Motor Company but was rejected because of his age. Gaillard worked at a general store owned by an Armenian family, with whom he lived for some time, then tried to become a boxer. During Prohibition, in 1931 or 1932, he drove a hearse with a coffin that was packed with whiskey for the Purple Gang.\nGaillard attended evening classes in music and taught himself to play guitar and piano. When Duke Ellington came to Detroit, Gaillard went backstage and met his hero. Determined to become a musical entertainer, he moved to New York City and entered the world of show business as a \"professional amateur\". As Gaillard recalled much later: \"The MC would say, ''Here they come, all the hopefuls!'' Well, we may have been hopefuls but we weren''t amateurs. Of course, you had to be a little bad in spots. If you were too good you''d lose the amateur image. I would be a tap dancer this week, next week I''d play guitar, two weeks later some boogie-woogie piano. They paid us $16 a show. I did one with Frank Sinatra, I got $16 and he got $16. Every time I see him I say, ''Got a raise yet, Frank?''\"","Career":"Gaillard first rose to prominence in the late 1930s as part of Slim & Slam, a jazz novelty act he formed with bassist Slam Stewart. Their hits included \"Flat Foot Floogie (with a Floy Floy)\" and \"Cement Mixer (Put-Ti-Put-Ti)\". The duo performs in the 1941 movie Hellzapoppin''.\nGaillard''s appeal was similar to Cab Calloway''s and Louis Jordan''s in that he presented a hip style with broad appeal (e.g. in his children''s song \"Down by the Station\"). Unlike Calloway and Jordan, however, he was a master improviser whose stream of consciousness vocals ranged far from the original lyrics. He sang wild interpolations of nonsense syllables, such as \"MacVoutie O-Reeney\". One such performance is celebrated in the 1957 novel On the Road by Jack Kerouac. Gaillard, with Dodo Marmarosa on piano, appeared as a guest several times on Command Performance, recorded at KNX radio studios in Hollywood in the 1940s and distributed on transcription discs to American troops during World War II.\nGaillard in a press photo for the 1954 film Go, Man, Go!\nIn December 1942, Gaillard was drafted into the United States Army Air Forces. There, Corporal Gaillard was an assistant crew chief working on Martin B-26 Marauder bombers at Laughlin Army Air Field in Del Rio, Texas. He was discharged before the end of the war after a year and seven months of service, six  months after being diagnosed with chronic frontal sinusitis.\nHe resumed his music career on his release from the draft in 1944. Upon his return he released the song \"Atomic Cocktail\", which featured seemingly lighthearted lyrics laced with symbolism about nuclear war.\nGaillard later teamed with bassist Bam Brown, and their successes included the hipster anthem \"Opera in Vout (Groove Juice Symphony)\". They can be seen in O''Voutie O''Rooney, a 1947 motion picture featurette filmed live at one of their nightclub performances. Slim and Bam were featured at the first Cavalcade of Jazz concert at Wrigley Field in Los Angeles produced by Leon Hefflin Sr. on September 23, 1945, along with Count Basie. Gaillard also played for the 2nd Cavalcade of Jazz at Wrigley Field on October 12, 1946, and for the 3rd Cavalcade of Jazz, also at Wrigley Field on September 7, 1947.\nIn the late 1940s and early 1950s, Gaillard frequently opened at Birdland for Charlie Parker, Flip Phillips, and Coleman Hawkins. His December 1945 session with Parker and Dizzy Gillespie is notable, both musically and for its relaxed convivial air. \"Slim''s Jam\", from that session, is one of the earliest known recordings of Parker''s speaking voice. In 1949, Gaillard was playing in San Francisco. An account of meeting Gaillard at a performance there can be found near the end of Part Two of On the Road.\nGaillard could play several instruments and manage to turn the performance from jazz to comedy. He would play guitar with his left hand fretting with fingers pointing down over the fingerboard (instead of the usual way up from under it), or would play credible piano solos with palms facing up.\nGaillard wrote the theme for the Peter Potter radio show, and wrote and recorded the \"Don Pitts On the Air\" theme in 1950 for San Francisco DJ Don Pitts. On March 27, 2008, the Pitts theme entered the archives of the Rock and Roll Hall of Fame in Cleveland, Ohio.\nIn the early 1960s, Gaillard lived in San Diego, California. During that time, he recorded several singles and performed with local bands. Under the name Slim Delgado, he recorded \"Frank Rhoads Round\", a rock-and-roll single for the Xavier label. On the B-side is a song called \"Dr. Free\".\nGaillard appeared on several TV shows during the 1960s and 1970s, including Marcus Welby, M.D., Charlie''s Angels, Mission: Impossible, Medical Center, The Flip Wilson Show, and Then Came Bronson. He also appeared in the 1970s TV series Roots: The Next Generations and reprised some of his old hits on the NBC prime-time variety program The Chuck Barris Rah Rah Show.\nBy the early 1980s, Gaillard was touring the European jazz festival circuit, playing with such musicians as Arnett Cobb. He also performed with George Melly and John Chilton''s Feetwarmers, appearing on their BBC television series and occasionally deputising for Melly when he was unwell. Gaillard''s onstage behavior was often erratic and nerve-wracking for the accompanying musicians. He made a guest appearance on Show 106 of the 1980s program Night Music, an NBC late-night music series hosted by David Sanborn.\nGaillard followed Dizzy Gillespie''s advice to move to Europe and settled in London in 1983. Around Christmas 1985, Gaillard recorded the album Siboney at Gateway Studios in Battersea, London, produced by Joe Massot. As Massot recalled later:\nI was introduced as Cuban. \"Rooney! I am Cuban too.\"  Slim said how much he wanted to make a Latin record and talked about his friend the great Cuban leader Machito. This was 1985. I had been flying between Angola, where Cuban troops were fighting and Miami where one million exiled Cubans live. We talked of all those Cubans who wanted to go back to Cuba but couldn''t.  In his inimitable, enthusiastic way Slim was trying to sell me, a movie maker, the idea of recording an album.\nIn 1986, Gaillard appeared in the musical film Absolute Beginners, singing \"Selling Out\". In the autumn of 1989, the BBC aired director Anthony Wall''s four-part documentary on Gaillard entitled Slim Gaillard''s Civilisation.","Death":"Gaillard died of cancer in London on February 26, 1991. His unique and varied career spanned nearly six decades. Gaillard was survived by a number of children including Janis Hunter Gaye (1956 – 2022), former wife of singer-songwriter Marvin Gaye."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (287, '1WmIo9ORq1IDlovUWFmo4Y', 'Sonny', 'Sharrock', 'ebd39596-e2bb-4b3c-a661-412a4198a083', 174748, 2, 'https://en.wikipedia.org/wiki/Sonny_Sharrock', NULL, NULL, NULL, NULL, '{"Intro":"Warren Harding \"Sonny\" Sharrock (August 27, 1940 – May 25, 1994) was an American jazz guitarist. His first wife was singer Linda Sharrock, with whom he recorded and performed.\nOne of only a few prominent guitarists who participated in the first wave of free jazz during the 1960s, Sharrock was known for his heavily chorded attack, use of feedback, and distorted saxophone-like lines. His early work also features creative use of slide guitar.","Biography":"Sonny Sharrock was born Warren Harding Sharrock on August 27, 1940, in Ossining, New York. He began his musical career singing doo-wop in his teen years. He collaborated with Pharoah Sanders and Byard Lancaster in the late 1960s, first appearing on Sanders''s 1966 album Tauhid. He made several appearances with flautist Herbie Mann and an uncredited appearance on Miles Davis'' A Tribute to Jack Johnson.\nSharrock first wanted to play tenor saxophone after hearing John Coltrane on Davis'' Kind of Blue at age 19, but his asthma prevented this. However, he considered himself \"a horn player with a really fucked up axe.\"\nThree albums under Sharrock''s name were released from the late 1960s to the mid-1970s: Black Woman, Monkey-Pockie-Boo, and Paradise (which he later disavowed).\nAfter the release of Paradise, Sharrock semi-retired for much of the 1970s and early 1980s. Undergoing a divorce from his wife and collaborator Linda in 1978, he worked as a chauffeur and a caretaker for mentally challenged children. At bassist and producer Bill Laswell’s urging, Sharrock came out of retirement to appear on Material''s 1981 album Memory Serves. Starting in 1986, Sharrock was a member of Last Exit with Laswell, saxophonist Peter Brötzmann, and drummer Ronald Shannon Jackson. During the late 1980s, he performed extensively with the New York-based band Machine Gun and led his own band. Sharrock flourished with Laswell''s help, noting in a 1991 interview that \"the last five years have been pretty strange for me, because I went twelve years without making a record at all, and then in the last five years, I''ve made seven records under my own name. That''s pretty strange.\"\nLaswell produced most of Sharrock''s later recordings, including the entirely solo Guitar, the \"metal-influenced\" Seize the Rainbow, and Highlife. Sharrock''s band at the time featured Abe Speller on percussion, Lance Carter on drums, Charles Baldwin on bass, and David Snider on keyboards. These albums were followed by Ask the Ages in 1991, which featured Pharoah Sanders and drummer Elvin Jones. One writer described Ask the Ages as \"hands down, Sharrock''s finest hour, and the ideal album to play for those who claim to hate jazz guitar.\" Sharrock recorded music, including the opening and ending themes, for Cartoon Network''s Space Ghost Coast to Coast with drummer Lance Carter; this was one of the last projects he completed in the studio before his death. The Space Ghost Coast to Coast episode \"Sharrock\" carried a dedication to him at the end, and previously unheard music that he had recorded for the show was featured throughout most of the episode.\nOn May 25, 1994, as he was on the verge of signing his first major label contract, Sharrock died of a heart attack in Ossining. He was 53 years old. He is survived by his second wife, Dannette Hill, and their daughter Jasmyn.","Early Life And Career":"Sonny Sharrock was born Warren Harding Sharrock on August 27, 1940, in Ossining, New York. He began his musical career singing doo-wop in his teen years. He collaborated with Pharoah Sanders and Byard Lancaster in the late 1960s, first appearing on Sanders''s 1966 album Tauhid. He made several appearances with flautist Herbie Mann and an uncredited appearance on Miles Davis'' A Tribute to Jack Johnson.\nSharrock first wanted to play tenor saxophone after hearing John Coltrane on Davis'' Kind of Blue at age 19, but his asthma prevented this. However, he considered himself \"a horn player with a really fucked up axe.\"\nThree albums under Sharrock''s name were released from the late 1960s to the mid-1970s: Black Woman, Monkey-Pockie-Boo, and Paradise (which he later disavowed).","Career Revival":"After the release of Paradise, Sharrock semi-retired for much of the 1970s and early 1980s. Undergoing a divorce from his wife and collaborator Linda in 1978, he worked as a chauffeur and a caretaker for mentally challenged children. At bassist and producer Bill Laswell’s urging, Sharrock came out of retirement to appear on Material''s 1981 album Memory Serves. Starting in 1986, Sharrock was a member of Last Exit with Laswell, saxophonist Peter Brötzmann, and drummer Ronald Shannon Jackson. During the late 1980s, he performed extensively with the New York-based band Machine Gun and led his own band. Sharrock flourished with Laswell''s help, noting in a 1991 interview that \"the last five years have been pretty strange for me, because I went twelve years without making a record at all, and then in the last five years, I''ve made seven records under my own name. That''s pretty strange.\"\nLaswell produced most of Sharrock''s later recordings, including the entirely solo Guitar, the \"metal-influenced\" Seize the Rainbow, and Highlife. Sharrock''s band at the time featured Abe Speller on percussion, Lance Carter on drums, Charles Baldwin on bass, and David Snider on keyboards. These albums were followed by Ask the Ages in 1991, which featured Pharoah Sanders and drummer Elvin Jones. One writer described Ask the Ages as \"hands down, Sharrock''s finest hour, and the ideal album to play for those who claim to hate jazz guitar.\" Sharrock recorded music, including the opening and ending themes, for Cartoon Network''s Space Ghost Coast to Coast with drummer Lance Carter; this was one of the last projects he completed in the studio before his death. The Space Ghost Coast to Coast episode \"Sharrock\" carried a dedication to him at the end, and previously unheard music that he had recorded for the show was featured throughout most of the episode.","Death":"On May 25, 1994, as he was on the verge of signing his first major label contract, Sharrock died of a heart attack in Ossining. He was 53 years old. He is survived by his second wife, Dannette Hill, and their daughter Jasmyn."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (288, '1WmIo9ORq1IDlovUWFmo4Y', 'Sonny', 'Stitt', 'd7828cdd-7d63-49c0-b09b-cf3df7ecaf80', 135930, 6, 'https://en.wikipedia.org/wiki/Sonny_Stitt', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Sonny_Stitt.jpg/500px-Sonny_Stitt.jpg', 'Tom Marcello Webster, New York, USA', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Sonny_Stitt.jpg', '{"Intro":"Sonny Stitt (born Edward Hammond Boatner Jr.; February 2, 1924 – July 22, 1982) was an American jazz saxophonist of the bebop/hard bop idiom. Known for his warm tone, he was one of the best-documented saxophonists of his era, recording over 100 albums. He was nicknamed the \"Lone Wolf\" by jazz critic Dan Morgenstern because of his tendency to rarely work with the same musicians for long despite his relentless touring and devotion to the craft. Stitt was sometimes regarded as a Charlie Parker mimic early in his career, but gradually developed his own sound and style, particularly when performing on the tenor saxophone and even occasionally baritone saxophone.","Early Life":"Edward Hammond Boatner Jr. was born in Boston, Massachusetts, and grew up in Saginaw, Michigan. He had a musical background: his father, Edward Boatner, was a baritone singer, composer, and college music professor; his brother was a classically trained pianist, and his mother was a piano teacher. He was placed for adoption in 1924 by his father and adopted by the Stitt family in Saginaw. He later began calling himself \"Sonny\". While in high school in Saginaw, he played in the Len Francke Band, a local popular swing band.\nIn 1943, Stitt met Charlie Parker. As he often recalled, the two men had similar styles. Parker is alleged to have remarked, \"Well, I''ll be damned, you sound just like me\", to which Stitt responded, \"Well, I can''t help the way I sound. It''s the only way I know how to play.\" Kenny Clarke said of Stitt, \"Even if there had not been a Bird, there would have been a Sonny Stitt.\"\nDuring the 1940s, he played alto saxophone as a member of Tiny Bradshaw''s big band, Billy Eckstine''s big band with Gene Ammons and Dexter Gordon, and Dizzy Gillespie''s big band. Stitt was a leader of Bebop Boys and Galaxy in 1946 and 1948, respectively.\nWhen playing tenor saxophone Stitt seemed to break free from some of the criticism that he was imitating Parker''s style, and began to develop a far more distinctive sound. He played with other bop musicians including Horace Parlan, Bud Powell, and Eddie \"Lockjaw\" Davis, a fellow tenor with a distinctly tough tone in comparison to Stitt, in the 1950s, and recorded a number of sides for Prestige Records as well as albums for Argo, Verve, and Roost. Stitt experimented with Afro-Cuban jazz in the late 1950s, and the results can be heard on his recordings for Roost and Verve, on which he teamed up with Thad Jones and Chick Corea for Latin versions of such standards as \"Autumn Leaves\".\nIn 1952, Stitt played with pianist Jimmy Jones, and the next year performed orchestral music with Johnny Richards. Under Quincy Jones''s guidance in 1955, he played uptempos and ballads such as \"My Funny Valentine\" and \"Star Dust\" and the same year performed \"Afterwards\" and \"There Will Never Be Another You\" with Hank Jones. Stitt joined Dolo Coker in 1957 to perform \"Blues for Yard\" and \"Blue Moon\" before returning to Hank to perform \"Cherokee\".\nStitt joined Miles Davis briefly in 1960, and recordings with Davis''s quintet can be found only in live settings on the tour of 1960. Concerts in Manchester and Paris are available commercially and also a number of concerts (which include sets by the earlier quintet with John Coltrane) on the record Live at Stockholm (Dragon), all of which featured Wynton Kelly, Jimmy Cobb, and Paul Chambers. However, Miles fired Stitt due to the excessive drinking habit he had developed, and replaced him with Hank Mobley. Later in the 1960s, Stitt paid homage to Parker on the album Stitt Plays Bird, which features Jim Hall on guitar.\nStitt recorded several times with his friend Gene Ammons in sessions that were interrupted by Ammons''s own imprisonment for narcotics possession. The records recorded by these two saxophonists are regarded by many as some of both Ammons’s and Stitt''s best work. The Ammons/Stitt partnership went down in posterity as one of the best dueling partnerships in jazz, alongside Zoot Sims and Al Cohn, and Johnny Griffin with Eddie \"Lockjaw\" Davis.\nStitt ventured into soul jazz and recorded with fellow tenor saxophonist Booker Ervin in 1964 on the Soul People album. Stitt also recorded with Duke Ellington alumnus Paul Gonsalves in 1963 for Impulse! on the Salt and Pepper album in 1964. Around that time, he appeared regularly at Ronnie Scott''s in London, and a live 1964 encounter with Ronnie Scott, The Night Has a Thousand Eyes, eventually surfaced. Stitt recorded at Ronnie Scott''s again in 1966 with resident guitarist Ernest Ranglin and British tenor saxophonist Dick Morrissey. Stitt was one of the first jazz musicians to experiment with the Selmer Varitone amplification system, as heard on the albums What''s New!!! in 1966 and Parallel-a-Stitt in 1967.","Later Life":"In the 1970s Stitt slowed his recording output slightly but in 1972 produced another classic, Tune-Up!, which was and still is regarded by many jazz critics, such as Scott Yanow, as his definitive record. Indeed, his fiery and ebullient soloing was reminiscent of his earlier playing. In 1971 he managed to record four albums; Turn It On! with Leon Spencer, Melvin Sparks, Idris Muhammad, and Virgil Jones, You Talk That Talk! with Gene Ammons and George Freeman as new members of the group, Just the Way It Was (Live at the Left Bank) with Don Patterson and Billy James, and Black Vibrations which featured the same group as in Turn It On!. Just the Way It Was (Live at the Left Bank) which was released in 2000 also featured Stitt as an electric saxophone player, which was the first album which encompassed it.\nStitt''s productivity dropped in the 1970s due to alcoholism. He drank heavily after giving up heroin in the late fifties and the abuse was beginning to take its toll. A series of alcohol-induced seizures caused Stitt to abstain and quit for good.\nStitt joined the all-star group The Giants of Jazz (which also featured Art Blakey, Dizzy Gillespie, Thelonious Monk, Kai Winding and bassist Al McKibbon) and made albums for Atlantic, Concord and EmArcy. His last recordings were made in Japan. A rejuvenated Stitt also toured with Red Holloway in the late 1970s, who noted a marked improvement in his playing. In 1975, Stitt performed with Ron Burton, Major Holley and drummer John Lewis at the Village Vanguard.\nIn 1981, Stitt performed with George Duvivier and Jimmy Cobb, Six weeks before his death, Stitt recorded two consecutive sessions which were with George Duvivier, Jimmy Cobb, Bill Hardman and either Junior Mance or Walter Davis Jr. on piano.\nIn 1982, Stitt was diagnosed with cancer, and died on July 22 in Washington, D.C. He is buried in a wall crypt at Fort Lincoln Cemetery, Brentwood, Maryland."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (289, '1WmIo9ORq1IDlovUWFmo4Y', 'Stan', 'Kenton', 'f19ce47e-2ceb-484c-9c4d-c04dcc7aff7e', 212786, 3, 'https://en.wikipedia.org/wiki/Stan_Kenton', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/%28Portrait_of_Stan_Kenton%2C_New_York%2C_N.Y.%28%3F%29%2C_ca._Jan._1947%29_%28LOC%29_%285019798027%29.jpg/500px-%28Portrait_of_Stan_Kenton%2C_New_York%2C_N.Y.%28%3F%29%2C_ca._Jan._1947%29_%28LOC%29_%285019798027%29.jpg', 'The Library of Congress', 'Public domain', 'https://commons.wikimedia.org/wiki/File:(Portrait_of_Stan_Kenton,_New_York,_N.Y.(%3F),_ca._Jan._1947)_(LOC)_(5019798027).jpg', '{"Intro":"Stanley Newcomb Kenton (December 15, 1911 – August 25, 1979) was an American popular music and jazz artist. As a pianist, composer, arranger and band leader, he led an innovative and influential jazz orchestra for almost four decades. Though Kenton had several pop hits from the early 1940s into the 1960s, his music was always forward-looking. Kenton was also a pioneer in the field of jazz education, creating the Stan Kenton Jazz Camp in 1959 at Indiana University.","Early Life":"Stan Kenton was born on December 15, 1911, in Wichita, Kansas; he had two sisters (Beulah and Erma Mae) born three and eight years after him, respectively. His parents, Floyd and Stella Kenton, moved the family to Colorado, and in 1924, to the Greater Los Angeles Area, settling in suburban Bell, California.\nKenton attended Bell High School; his high-school yearbook picture has the prophetic notation \"Old Man Jazz\". Kenton started learning piano as a teen from a local pianist and organist. When he was around 15 and in high school, pianist and arranger Ralph Yaw introduced him to the music of Louis Armstrong and Earl Hines. He graduated from high school in 1930.\nBy the age of 16, Kenton was already playing a regular solo piano gig at a local hamburger eatery for 50 cents a night plus tips; during that time he had his own performing group named \"The Bell-Tones\". His first arrangement was written during this time for a local eight-piece band that played in nearby Long Beach.","Career":"With little money, Kenton traveled to San Diego and Las Vegas playing piano in speakeasies.  By 1932 he was playing with the Francis Gilbert Territory band and toured through Arizona. He worked with the Everett Hoagland Orchestra in 1933, his first time playing at the Rendezvous Ballroom in Balboa, California, where he later recorded popular live albums.  After playing with Russ Plummer and Hal Grayson, Kenton finally got his big break with Gus Arnheim.\nIn April 1936, Arnheim reorganized his band into the style of Benny Goodman''s groups and Kenton took the piano chair. This is where Kenton made his first  recordings when Arnheim made 14 sides for the Brunswick label in summer 1937. Once he departed from Gus Arnheim''s group, Kenton went back to study with private teachers on both the piano and in composition. In 1938 Kenton joined Vido Musso in a short-lived band, but a very educational experience for him.\nFrom the core of this group came the lineup of the first Stan Kenton groups of the 1940s. Kenton worked with the NBC House Band and in various Hollywood studios and clubs. Producer George Avakian took notice of Kenton during this time while he worked as the pianist and Assistant Musical Director at the Earl Carroll Theatre Restaurant in Hollywood. Kenton started to get the idea of running his own band from this experience, so he created a rehearsal band of his own, which eventually became his group in the 1940s.\nStan Kenton, Billboard magazine, October 1942\nIn 1940, Kenton formed his first orchestra. Kenton worked in the early days with his own groups as much more of an arranger than a featured pianist. Although there were no \"name\" musicians in his first band (with the possible exception of bassist Howard Rumsey and trumpeter Chico Alvarez), Kenton spent the summer of 1941 playing regularly before an audience at the Rendezvous Ballroom on the Balboa Peninsula at Newport Beach, CA. Influenced by Benny Carter and Jimmie Lunceford, the Stan Kenton Orchestra struggled for a time after its initial success. Its Decca recordings were not big sellers and a stint as Bob Hope''s backup radio band during the 1943–44 season was an unhappy experience, as Les Brown permanently took Kenton''s place.\nStan Kenton with bassist Eddie Safranski, 1947 or 1948 Kenton''s first appearance in New York was in February 1942 at the Roseland Ballroom, with the marquee featuring an endorsement by Fred Astaire. By late 1943, with a contract with the newly formed Capitol Records, a popular record in \"Eager Beaver\", and growing recognition, the Stan Kenton Orchestra was gradually catching on; it developed into one of the best-known West Coast ensembles of the 1940s. Its soloists during the war years included Art Pepper, briefly Stan Getz, altoist Boots Mussulli, and singer Anita O''Day. By 1945, the band had evolved. The songwriter Joe Greene provided the lyrics for hit songs like \"And Her Tears Flowed Like Wine\" and \"Don''t Let the Sun Catch You Cryin''\". Pete Rugolo became the chief arranger (extending Kenton''s ideas), Bob Cooper and Vido Musso offered very different tenor styles, and June Christy was Kenton''s new singer; her hits (including \"Tampico\" and Greene''s \"Across the Alley from the Alamo\") made it possible for Kenton to finance his more ambitious projects.\nSam Donahue and orchestra, Kenton on right, New York, 1946 When composer/arranger Pete Rugolo joined the Stan Kenton Orchestra as staff arranger in late 1945, he brought with him his love of jazz, Stravinsky and Bartók. Given free rein by Kenton, Rugolo experimented. Although Kenton himself was already trying experimental scores prior to Rugolo''s tenure, it was Rugolo who brought extra jazz and classical influences much needed to move the band forward artistically.\nDuring his first six months on the staff, Rugolo tried to copy Kenton''s sound; on encouragement from the leader, he explored his own voice. By incorporating compositional techniques borrowed from the modern classical music he studied, Rugolo was a key part of one of Kenton''s most fertile and creative periods.\n(From left:) Pete Rugolo, Stan Kenton (age 36), and Bob Graettinger (1948)\nAfter a string of mostly arrangements, Rugolo turned out three originals that Kenton featured on the band''s first album in 1946 (Artistry in Rhythm): \"Artistry in Percussion\", \"Safranski\" and \"Artistry in Bolero\". Added to this mix came \"Machito\", \"Rhythm Incorporated\", \"Monotony\", and \"Interlude\" in early 1947 (although some were not recorded until later in the year). These compositions, along with June Christy''s voice, came to define the Artistry in Rhythm band.  Afro-Cuban writing was added to the Kenton book with compositions like Rugolo''s \"Machito\". The resulting instrumentation, utilizing significant amounts of brass, was described as a \"wall of sound\" (a term later coined independently by Andrew Loog Oldham for Phil Spector''s production methods).\nThe Artistry in Rhythm ensemble was a formative band, with outstanding soloists. By early 1947, the Stan Kenton Orchestra had reached a high point of financial and popular success. They played in the best theaters and ballrooms in America, and had numerous hit records. Dances at the ballrooms were typically four hours a night and theater dates generally involved playing mini-concerts between each showing of the movie. This was sometimes five or six a day, stretching from morning to late night. Most days not actually playing were spent in buses or cars. Days off from performing were rare. For Kenton they just allowed for more record signing, radio station interviews, and advertising for Capitol Records. Due to the financial and personal demands, following an April performance in Tuscaloosa, he broke up the Artistry in Rhythm incarnation of Kenton ensembles.\nAfter a hiatus of five months, Kenton formed a new, larger ensemble to present Concerts in Progressive Jazz. Sustaining the ensemble on its own proved mostly attainable but the band still had to fill in its schedule by booking dances and movie theater jobs, especially over the summer.\nPete Rugolo composed and arranged the great bulk of the new music; Kenton declared these works to be Progressive Jazz. A student of famed composer and educator Russ Garcia, Bob Graettinger wrote numerous works for the band, starting with his composition Thermopylae. His ground-breaking composition City of Glass was premiered by the band in Chicago in April 1948, but not recorded for another two and a half years, in a reworked version for the Innovations Orchestra. Ken Hanna, who began the tour as a trumpet player, contributed a few compositions to the new band, including Somnambulism. Kenton contributed no new scores to the Progressive Jazz band, although several of his older works were performed on concerts, including Concerto to End All Concertos, Eager Beaver, Opus in Pastels, and Artistry in Rhythm.\nStan Kenton (age 36) with Pete Rugolo (1948)\nCuban inflected titles from the Progressive Jazz period include Rugolo''s Introduction to a Latin Rhythm, Cuban Carnival, The Peanut Vendor, Journey to Brazil, and Bob Graettinger''s Cuban Pastorale. The addition of a full-time bongo player and a Brazilian guitarist in the band enabled Kenton''s cadre of composers to explore Afro-Latin rhythms to far greater possibilities.\nThe Progressive Jazz period lasted 14 months, beginning on September 24, 1947, when the Stan Kenton Orchestra played a concert at the Rendezvous Ballroom. And it ended after the last show at the Paramount Theatre in New York City on December 14, 1948. The band produced only one album and a handful of singles, due to a recording ban by the American Federation of Musicians that lasted the entirety of 1948.\nThe lone record, \"A Presentation of Progressive Jazz\", received a 3 out of 4 rating from Tom Herrick in DownBeat. Metronome rated it \"C\" calling it a \"jerry-built jumble of effects and counter-effects\" and \"this album presents very little that can justifiably be called either jazz or progressive\". Billboard scored it 80 out of 100, but declared it \"as mumbo-jumbo a collection of cacophony as has ever been loosed on an unsuspecting public.\nMany sidemen from the Artistry band returned, but there were significant changes. Laurindo Almeida on classical guitar, and Jack Costanzo on bongos dramatically changed the band''s timbre. Both were firsts for the Kenton band, or any jazz band for that matter. The rhythm section included returnees Eddie Safranski (bass) and Shelly Manne (drums), both destined to win first-place Down Beat awards.\nKids are going haywire over the sheer noise of this band...There is a danger of an entire generation growing up with the idea that jazz and the atom bomb are essentially the same natural phenomenon.— Barry Ulanov, Metronome, 1948\nFour of the five trumpet players returned: Buddy Childers, Ray Wetzel, Chico Alvarez, and Ken Hanna. Al Porcino was added to the already powerhouse section. Conte Candoli joined the band, replacing Porcino, in February 1948.\nKai Winding, star trombonist of the Artistry in Rhythm band, would not be a part of the Progressive Jazz era, except for a few dates on which he subbed. Milt Bernhart came in on lead trombone. And Bart Varsalona returned on bass trombone. Bernhart''s first big solo with the Kenton band proved to be a major hit, The Peanut Vendor.\nThe saxophone section was much improved and modernized. Returning saxophonists included baritone Bob Gioga, holding down his chair since the very start, and Bob Cooper on tenor. With Vido Musso''s departure, Cooper and his modernist sound became the featured tenor soloist. Art Pepper came on as second alto, the \"jazz\" chair. And the new lead alto was George Weidler.\nThey received five first place awards in the Down Beat poll at the end of 1947, and similar awards from the other magazines. The arrangers continued to push the limits of the instrumentalists in their compositions. Works from this period are some of the first and most successful \"third stream\" compositions.\nThe band criss-crossed the country, appearing in the nation''s top concert venues, including Carnegie Hall, Boston Symphony Hall, Chicago Civic Opera House, Academy of Music (Philadelphia), and the Hollywood Bowl. They had extended stays at New York''s Paramount Theatre and Hotel Commodore, Philadelphia''s Click, Detroit''s Eastwood Gardens, Radio City Theater in Minneapolis, and the Rendezvous Ballroom, a special place in Kenton''s musical life.\nKenton''s band was the first to present a concert in the famous outdoor arena, the Hollywood Bowl. His concert there on June 12, 1948, drew more than 15,000 people, and was both an artistic and commercial success. Kenton pocketed half of the box office, walking away with US$13,000 (equivalent to $174,204 in 2025) for the evening''s concert.\nThe band broke attendance records all across the country. Thanks to Kenton''s public relations acumen, he was able to convince concert goers and record buyers of the importance of his music. Comedy numbers and June Christy vocals helped break up the seriousness of the new music.\nKenton''s successes did not sit well with everyone. In an essay entitled Economics and Race in Jazz, Leslie B. Rout Jr. wrote: \"The real scourge of the 1946–1949 period was the all-white Stan Kenton band. Dubbing his musical repertoire progressive jazz, Kenton saw his orchestra become the first in jazz history to reach an annual gross of US$1,000,000 in 1948.\" (equivalent to $13.4 million in 2025)— Leslie Rout (1968) Rout contrasted this with the relative lack of critical and public recognition for another leading jazz artist: \"Dizzy Gillespie as the premiere bopper could not be transformed into coin of the realm.\"— Leslie Rout (1968)\nAt the end of 1948, as the band was fulfilling an extended engagement at the Paramount Theater in New York City, the leader notified his sidemen, his bookers, and the press, that he would be disbanding once more. Kenton''s most artistically and commercially successful band ceased to be at the top of their game. On December 14, 1948, the Stan Kenton Orchestra played their last notes for more than a year. They would return with new faces, new music, and a string section.\nAfter a year''s hiatus, in 1950 Kenton assembled the large 39-piece Innovations in Modern Music Orchestra that included 16 strings, a woodwind section, and two French horns. The music was an extension of the works composed and recorded since 1947 by Bob Graettinger, Manny Albam, Franklyn Marks and others. Name jazz musicians such as Maynard Ferguson, Shorty Rogers, Milt Bernhart, John Graas, Art Pepper, Bud Shank, Bob Cooper, Laurindo Almeida, Shelly Manne, and June Christy were part of these musical ensembles. The groups managed two tours during 1950–51, from a commercial standpoint it would be Stan Kenton''s first major failure. Kenton soon reverted to a more standard 19-piece lineup.\nIn order to be more commercially viable, Kenton reformed the band in 1951 to a much more standard instrumentation: five saxes, five trombones, five trumpets, piano, guitar, bass, drums. The charts of such arrangers as Gerry Mulligan, Johnny Richards, and particularly Bill Holman and Bill Russo began to dominate the repertoire. The music was written to better reflect the style of cutting edge, be-bop oriented big bands, such as those of Dizzy Gillespie or Woody Herman. Young, talented players and outstanding jazz soloists such as Maynard Ferguson, Lee Konitz, Conte Candoli, Sal Salvador, and Frank Rosolino made strong contributions to the level of the 1952–53 band. The music composed and arranged during this time was far more tailor-made to contemporary jazz tastes; the 1953 album New Concepts of Artistry in Rhythm is noted as one of the high points in Kenton''s career as band leader. Though the band was to have a very strong \"concert book\", Kenton also made sure the dance book was made new, fresh and contemporary. The album Sketches on Standards from 1953 is an excellent example of Kenton appealing to a wider audience while using the band and Bill Russo''s arranging skills to their fullest potential. Even though the personnel changed rather rapidly, Kenton''s focus was very clear on where he would lead things musically. By this time producer Lee Gillette worked well in concert with Kenton to create a balanced set of recordings that were both commercially viable and cutting edge musically.\nArguably the most \"swinging\" band Kenton was to field came when drummer Mel Lewis joined the orchestra in 1954. Kenton''s Contemporary Concepts (1955) and Kenton in Hi-Fi (1956) albums during this time are very impressive as a be-bop recording and then a standard dance recording (respectively).  Kenton in Hi-Fi''s popularity and sales benefited from the fact it was his greatest hits of ten years earlier re-recorded in stereo with a contemporary and higher-level band. The album climbed all the way up to No. 22 on the Billboard albums chart and provided much needed revenue at a time when rock and roll had started to become the dominant pop music in the United States.  It would become more and more difficult for Kenton to alternate between ''dance'' and serious ''jazz'' albums while staying financially solvent.\nDuring the summer of 1955 (July–September), Kenton was to become the host of the CBS television series Music 55.   While it offered 10 weeks of great exposure to a rapidly expanding television audience, the show failed. It was plagued by poor production techniques and a strange combination of guests that did not work well with what Kenton had envisioned. He ended up being stiff and out of place with what the producers tried to achieve. Kenton had to burn the candle at both ends, flying in to do the show and then flying back to meet his band on the road. The New York production team was limited to using an American Federation of Musicians roster of local players; Kenton wanted his own band to do the show. There would be another attempt for the Kenton organization to place the band on regularly scheduled television programming in 1958. After six Kenton-financed episodes on KTTV in Los Angeles, there would be no sponsors to step up and back the show.\nStan Kenton''s Cuban Fire! album featured the music of composer Johnny Richards.\nOne of the standout projects and recordings for the mid-1950s band is the Cuban Fire! album released in 1956. Though Stan Kenton had recorded earlier hits such as The Peanut Vendor in 1947 with Latin percussionist Machito, as well as many other Latin flavored singles, the Cuban Fire! suite and LP stands as a watershed set of compositions for Johnny Richards'' career and an outstanding commercial/artistic achievement for the Kenton orchestra, and a singular landmark in large ensemble Latin jazz recordings.  \"CUBAN FIRE is completely authentic, the way it combines big-band jazz with genuine Latin-American rhythms.\"  The success of the Cuban Fire! album can be gauged in part by the immediate ascent of Johnny Richards'' star after its release; he was suddenly offered a contract by Bethlehem Records to record what would be the first of several recordings with his own groups.\nAt one point, Kenton faced a controversy in 1956 with comments he made when the band returned from a European tour. The current Critics Poll in Down Beat was now dominated by African-American musicians in virtually every category. The Kenton band was playing in Ontario, Canada, at the time, and Kenton dispatched a telegram which lamented \"a new minority, white jazz musicians\", and stated his \"disgust  literary geniuses of jazz\". Jazz critic Leonard Feather responded in the October 3, 1956, issue of Down Beat with an open letter that questioned Kenton''s racial views. Feather implied that Kenton''s failure to win the Critics Poll was probably the real reason for the complaint, and wondered if racial prejudice was involved. Less than 2% of the more than 600 sidemen with the Kenton band were African American.\nBy the end of the decade Kenton was with the last incarnation of a 19-piece, 1950s-style Kenton orchestra. Many bands have been called a leader''s \"best\"; this last Kenton 1959 incarnation of the 1950s bands may very well be the best. The group would pull off one of Kenton''s most artistic, subtle and introspective recordings, Standards in Silhouette.  As trombonist Archie LeCoque recalled of this album of very slow ballads, \"...it was hard, but at the time we were all young and straight-ahead, we got through it and (two) albums came out well.\"  By 1959 Stereophonic sound recording was now being fully utilized with all major labels. One of the great triumphs of the Standards in Silhouette album is the mature writing, the combination of the room used, a live group with very few overdubs, and the recording being in full stereo fidelity (and later remastered to digital).  Bill Mathieu was highly skeptical of the decision to record his music like Cuban Fire! in a cavernous ballroom. Mathieu adds: \"Stan and producer Lee Gillette were absolutely right: the band sounds alive and awake (which is not easy when recording many hours of slow-tempo music in a studio), and most importantly, the players could hear themselves well in the live room. The end result is the band sounds strong and cohesive, and the album is well recorded.\"  This is the last set of studio dates before Kenton would retool the entire orchestra in 1960.\nStan Kenton with Bill Holman in December 1961 for the Adventures In Jazz  recording sessions at Capitol Studios, Hollywood, California\nThe Kenton orchestra had been on a slow decline in sales and popularity in the late 1950s with having to compete with newer, popular music artists such as Elvis Presley, Bobby Darin, and The Platters. The nadir of this decline was around 1958 and coincided with a recession that was affecting the entire country. There were far fewer big bands on the road and live music venues were hard to book for the Kenton orchestra. The band would end 1959 beaten up by poor attendance at concerts and having to rely far more on dance halls than real jazz concerts.  The band would reform in 1960 with a new look, a new sound, a larger group with a ''mellophonium'' section added and an upsurge in Kenton''s popularity.\nThe Mellophonium was a featured instrument by Stan Kenton from 1960 through the end of 1963. Though intonation was problematic, it added a unique color to the sound palate of the orchestra.The new instrument was used by Kenton to \"bridge the gap\" in range, color, and tonality between his trumpet and trombone sections. Essentially it creates a conical, midrange sound that is common in a symphonic setting with a horn (French horn) but the bell of the instrument faces forward. Kenton''s 1961 recording The Romantic Approach for Capitol is the first of 11 LPs that would feature the \"mellophonium band\". Kenton arranged the whole first mellophonium album himself and it was very well received in a September 1961 review in Down Beat.\nI loved playing Johnny''s music, and so did Stan. West Side Story was probably the toughest album I ever recorded...\nThe Kenton Orchestra from 1960 to 1963 had numerous successes; the band had a relentless recording schedule. The albums Kenton''s West Side Story (arrangements by Johnny Richards) and Adventures In Jazz, each won Grammy awards in 1962 and 1963 respectively. Ralph Carmichael wrote a superb set of Christmas charts for Kenton which translated into one of the most popular recordings from the band leader to date: A Merry Christmas!.   Also, Johnny Richards'' Adventures in Time suite (recorded in 1962) was the culmination of all things the mellophonium band was capable of.   After the Fall 1963 U.S./U.K. tour ended in November, the mellophonium incarnation of Kenton bands was done. The conditions of Stan''s divorce from jazz singer Ann Richards was that a judge ordered Stan to take a year off the road to help raise their two children or lose custody altogether. Kenton would not reform another road band for tour until 1965.\nKenton had ties from earlier writing of country/western songs that were a success with Capitol and again he tried his hand in that genre during the early 1960s. In a music market that was becoming increasingly tight, in 1962 he cut the hit single \"Mama Sang a Song\"; his last Top-40 (No. 32 Billboard, No. 22 Music Vendor). The song was a narration written by country singer Bill Anderson and spoken by Kenton. The single also received a Grammy nomination the following year in the Best Documentary or Spoken Word Recording category. The other attempt he made into that market was the far less successful Stan Kenton! Tex Ritter!, released in 1962 as a full LP.\nAfter the breakup of the mellophonium band, Kenton / Wagner (1964) was an important recording project that Kenton himself arranged, again moving towards \"progressive jazz\" or third stream music. This album was not a financial success but kept Kenton at the forefront of ''art music'' interpretation in the commercial music world. Stan Kenton Conducts the Los Angeles Neophonic Orchestra (1965) was an artistic success that garnered another Grammy nomination for the band leader.  During this time Kenton also co-wrote the theme music for the short lived NBC television series Mister Roberts (1965–66).\nThe 1966–1969 Capitol releases for Stan Kenton were a severe low point for his recording career. Capitol producer Lee Gillette was trying to exploit the money making possibilities of numerous popular hits to include the 1968 musical Hair featuring contemporary rock music.   Due to lack of promotion by Capitol, four LPs were financial failures; this would be the last releases for Kenton under the aegis of long time Kenton producer Lee Gillette and Capitol.   In fact, by the time it was recorded Kenton had no involvement in the Hair LP except for Kenton''s name placed on the jacket cover; Ralph Carmichael and Lennie Niehaus were placed in charge of the project. Two exceptions to this late 1960s period are the Billboard charted single the band cut of the Dragnet theme (1967) and another Kenton presents release featuring the music of composer and ex-bandsman Dee Barton: The Jazz Compositions of Dee Barton (1967). The album featuring Barton''s music was another unsung artistic success for the Kenton band though widely unseen commercially by the a music listening public.\nStan Kenton with his band in Munich, Germany (September 1973)\nThe transition from Capitol to Creative World Records in 1970 was fraught with difficulties during a time when the music business was changing rapidly. As a viable jazz artist who was trying to keep a loyal but dwindling following, Kenton turned to arrangers such as Hank Levy and Bob Curnow to write material that appealed to a younger audience.  The first releases for the Creative World label were live concerts and Kenton had the control he wanted over content but lacked substantial resources to engineer, mix, and promote what Capitol underwrote in the past. Kenton would take a big gamble to bypass the current record industry and rely far more on the direct mail lists of jazz fans which the newly formed Creative World label would need to sell records.  Kenton also made his print music available to college and high-school stage bands with several publishers. Kenton continued leading and touring with his big band up to his final performance on August 20, 1978, when he disbanded the group due to his failing health.\nStan Kenton (age 62) with Bob Curnow, Universal Studios in Chicago, Illinois, US (1974)\nIn June 1973 Bob Curnow had started as the new artists and repertoire manager overseeing the whole operation of the Creative World Records.  It was just the year before (in 1972) the Kenton orchestra recorded the National Anthems of the World double LP with 40 arrangements all done by Curnow. As per Curnow himself: \"That was a remarkable and very difficult time for me. I was managing (Stan''s) record company with NO experience in business, writing music like mad, living in a new place and culture (Los Angeles was another world), traveling a LOT (out with the band at least 1 week a month) and trying to keep it together at home.\"— Bob Curnow (2013)\nStan Kenton with Al \"Jazzbeaux\" Collins 1978\nWhen Kenton took to the road during the early 1970s (one in London in 1972) and up to his last tour, he took with him seasoned veteran musicians (John Worster, Willie Maiden, Warren Gale, Graham Ellis, and others) teaming them with relatively unknown young artists, and new arrangements (including those by Hank Levy, Bill Holman, Bob Curnow, Willie Maiden, and Ken Hanna) were used. Many alumni associated with Kenton from this era became educators (Mike Vax, John Von Ohlen, Chuck Carter, Lisa Hittle, and Richard Torres), and a few went on to take their musical careers to the next level, such as Peter Erskine, Douglas Purviance, and Tim Hagans.","Personal Life":"Kenton''s birth certificate stated that he was born on December 15, 1911,  according to British biographer Michael Sparke.\nKenton was conceived out of wedlock, and his parents told him that he was born on February 19, 1912, two months later than the actual date, to obscure this fact. Kenton believed well into adulthood that the February date was his birthday, and recorded the Birthday In Britain concert album on February 19, 1973.\nThe true date remained secret, and his grave marker shows the incorrect February birthdate.\nKenton was married three times. He had three children from the first two marriages. His first marriage was to Violet Rhoda Peters in 1935 and lasted 15 years. The couple had a daughter in 1941, Leslie. In her 2010 memoir Love Affair, Leslie Kenton wrote that, from 1952 to 1954 when she was between the ages of 11 and 13, her father sexually abused her. She nonetheless maintained a close relationship with him, though she states that she was emotionally scarred by the experience. She said that the abuse happened when he was drunk. Twenty years later he apologized.\nIn 1955, Stan Kenton married San Diego-born singer Ann Richards, who was 23 years his junior. They had two children. In 1961, Richards posed for a nude layout in Playboy magazine''s June 1961 issue. She signed a contract to record with Atco Records, without her husband''s knowledge. The Playboy shoot was done without Kenton''s knowledge; he found out about it while playing at the Aragon Ballroom in Chicago when handed the magazine by Charles Suter, who was the editor of Down Beat magazine at the time. Richards was not typically on the road with the band, though she had recorded the album Two Much! with Kenton in 1960. Richards filed for divorce in August 1961; it was finalized in 1962. He retained custody of their two children.\nKenton''s third marriage was to KABC production assistant Jo Ann Hill, in 1967. This also ended in a separation in 1969 with the divorce following in 1970.\nIn his later years he lived with his public relations secretary and last business manager, Audree Coke Kenton, though they never married.\nKenton''s heavy consumption of alcohol contributed to frequent accidents and the physical difficulties he encountered during the last 10 years of his life.\nKenton''s son Lance became a member of the controversial Synanon new-age community in California, and served as one of its \"Imperial Marines\", a group entrusted with committing violence against former members and others considered enemies of the community. In 1978 he was arrested for helping to put a rattlesnake in the mailbox of an anti-Synanon lawyer, and was sentenced to a year in prison.\nKenton had two serious falls, one in the early 1970s and one in May 1977 whilst on tour in Reading, Pennsylvania, the second of which fractured his skull. On August 17, 1979, he was admitted to Midway Hospital near his home in Los Angeles after a stroke; he died eight days later, on August 25. Kenton was interred in the Westwood Village Memorial Park Cemetery, Los Angeles.","Artistry In Rhythm":"Sam Donahue and orchestra, Kenton on right, New York, 1946 When composer/arranger Pete Rugolo joined the Stan Kenton Orchestra as staff arranger in late 1945, he brought with him his love of jazz, Stravinsky and Bartók. Given free rein by Kenton, Rugolo experimented. Although Kenton himself was already trying experimental scores prior to Rugolo''s tenure, it was Rugolo who brought extra jazz and classical influences much needed to move the band forward artistically.\nDuring his first six months on the staff, Rugolo tried to copy Kenton''s sound; on encouragement from the leader, he explored his own voice. By incorporating compositional techniques borrowed from the modern classical music he studied, Rugolo was a key part of one of Kenton''s most fertile and creative periods.\n(From left:) Pete Rugolo, Stan Kenton (age 36), and Bob Graettinger (1948)\nAfter a string of mostly arrangements, Rugolo turned out three originals that Kenton featured on the band''s first album in 1946 (Artistry in Rhythm): \"Artistry in Percussion\", \"Safranski\" and \"Artistry in Bolero\". Added to this mix came \"Machito\", \"Rhythm Incorporated\", \"Monotony\", and \"Interlude\" in early 1947 (although some were not recorded until later in the year). These compositions, along with June Christy''s voice, came to define the Artistry in Rhythm band.  Afro-Cuban writing was added to the Kenton book with compositions like Rugolo''s \"Machito\". The resulting instrumentation, utilizing significant amounts of brass, was described as a \"wall of sound\" (a term later coined independently by Andrew Loog Oldham for Phil Spector''s production methods).\nThe Artistry in Rhythm ensemble was a formative band, with outstanding soloists. By early 1947, the Stan Kenton Orchestra had reached a high point of financial and popular success. They played in the best theaters and ballrooms in America, and had numerous hit records. Dances at the ballrooms were typically four hours a night and theater dates generally involved playing mini-concerts between each showing of the movie. This was sometimes five or six a day, stretching from morning to late night. Most days not actually playing were spent in buses or cars. Days off from performing were rare. For Kenton they just allowed for more record signing, radio station interviews, and advertising for Capitol Records. Due to the financial and personal demands, following an April performance in Tuscaloosa, he broke up the Artistry in Rhythm incarnation of Kenton ensembles.","Legacy":"Kenton was a significant figure on the American musical scene and made an indelible mark on the arranged type of big band jazz. Kenton''s music evolved with the times from 1940 through the 1970s. He was at the vanguard of promoting jazz and jazz improvisation through his service as an educator through his Stan Kenton Band Clinics. The \"Kenton Style\" continues to permeate big bands at the high school and collegiate level, and the framework he designed for the \"jazz clinic\" is still widely in use today.\nStarting in the waning days of the big band era, Kenton found many ways to progress his art form. In his hands the size of the jazz orchestra expanded greatly, at times exceeding forty musicians. The frequency range (high and low notes) was also increased with the use of bass trombones and tuba, and baritone and bass saxophones. The dynamic range was pushed on both ends; the band could play softer and louder than any other big band. Kenton was the primary band leader responsible for moving the big band from the dance hall to the concert hall; one of the most important and successful players in the Third Stream movement.\nInterest in his music has experienced somewhat of a resurgence, with critical \"rediscovery\" of his music and many reissues of his recordings. An alumni band named for him tours, led by lead trumpeter Mike Vax, which performs not only classic Kenton arrangements, but also new music written and performed by the band members (much like Kenton''s own groups). Kenton donated his entire library to the music library of North Texas State University (now the University of North Texas), and the Stan Kenton Jazz Recital Hall was named in his honor, although has recently been changed due to concerns over his history of sexual misconduct. His arrangements are now published by Sierra Music Publications.\nWhen compared with the four longest running touring jazz orchestras (Stan Kenton, Woody Herman, Count Basie, and Duke Ellington), Kenton''s band had the highest turnover of personnel: Bob Gioga, Buddy Childers, and Dick Shearer are among only the few who played for Kenton for over a decade. Other important soloists such as Lennie Niehaus, Bill Perkins and Chico Alvarez had lengthy stays on the band as well. The full list of notable jazz players, studio musicians, et al. who served a stint is in itself impressive, as is the consistency of the group as a going concern from 1941 right until the decade of Kenton''s death in 1979. Kenton''s leadership and musical vision marshalled the numerous forces of an evolving and transient diverse set of players and arrangers for nearly four decades."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (290, '1WmIo9ORq1IDlovUWFmo4Y', 'Stan', 'Tracey', 'adc90de8-d2c8-427c-8592-9773221bb9ab', 314915, 3, 'https://en.wikipedia.org/wiki/Stan_Tracey', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/StanTracey100ClubLondon_1980s.jpg/500px-StanTracey100ClubLondon_1980s.jpg', 'Suqpecoc at en.wikipedia', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:StanTracey100ClubLondon_1980s.jpg', '{"Intro":"Stanley William Tracey (30 December 1926 – 6 December 2013) was a British jazz pianist and composer, whose most important influences were Duke Ellington and Thelonious Monk. Tracey''s best known recording is the 1965 album Jazz Suite Inspired by Dylan Thomas''s \"Under Milk Wood\", which is based on the BBC radio drama Under Milk Wood by Dylan Thomas.","Early Career":"The Second World War meant that Tracey had a disrupted formal education, and he became a professional musician at the age of sixteen as a member of an ENSA touring group playing the accordion, his first instrument. He joined Ralph Reader''s Gang Shows at the age of nineteen, while in the RAF and formed a brief acquaintance with the comedian Tony Hancock. Later, in the early 1950s, he worked in groups on the transatlantic liners Queen Mary and Caronia and toured the UK in 1951 with Cab Calloway. By the mid-1950s, he had also taken up the vibraphone, but later ceased playing it. At this time he worked widely with leading British modernists, including drummer Tony Crombie, clarinettist Vic Ash, the saxophonist-arranger Kenny Graham and trumpeter Dizzy Reece.\nIn February 1957, he toured the United States with Ronnie Scott''s group, and became the pianist with Ted Heath''s Orchestra in September for two years (1958–59), including a US tour with singer Carmen McRae. Although Tracey disliked Heath''s music, he gained a regular income and was well featured as a soloist on both piano and vibes, and contributed compositions and arrangements that stayed in the Heath book for many years. The following year he recorded his first album as leader, Showcase, for English Decca (also Heath''s label) and Little Klunk in 1959; he had first recorded in 1952 with the trumpeter Kenny Baker. At Decca Records, Tracey met his future wife, Jackie Buckland (3 April 1929 – 13 August 2009); the couple had two children Clark and Sarah."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (291, '1WmIo9ORq1IDlovUWFmo4Y', 'Stanley', 'Clarke', '5ab6ca23-9e17-43f2-ad92-869d28bdbf11', 87519, 1, 'https://en.wikipedia.org/wiki/Stanley_Clarke', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Stanley_Clarke_-_Leverkusener_Jazztage_2016-AL4909.jpg/500px-Stanley_Clarke_-_Leverkusener_Jazztage_2016-AL4909.jpg', 'Andreas Lawen, Fotandi', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Stanley_Clarke_-_Leverkusener_Jazztage_2016-AL4909.jpg', '{"Intro":"Stanley Clarke (born June 30, 1951) is an American bassist, composer and founding member of Return to Forever, one of the first jazz fusion bands. Clarke gave the bass guitar a prominence it lacked in jazz-related music. He is the first jazz-fusion bassist to headline tours, sell out shows worldwide and have recordings reach gold status.\nClarke is the recipient of five Grammy Awards, with 15 nominations, three as a solo artist, one with the Stanley Clarke Band, and one with Return to Forever. Clarke was selected to become a 2022 recipient of the National Endowment for the Arts Jazz Masters Fellowship.\nA Stanley Clarke electric bass is permanently on display at the National Museum of African American History and Culture in Washington, D.C.","Music Career":"Clarke with Return to Forever, Onondaga Community College, Syracuse, New York, 1974\nClarke was born on June 30, 1951, in Philadelphia. His mother sang opera around the house, belonged to a church choir, and encouraged him to study music. He started on accordion, then tried violin. But he felt awkward holding such a small instrument in his big hands when he was twelve years old and over six feet tall. No one wanted the acoustic bass in the corner, so he picked it up. He took lessons on the double bass at the Settlement Music School in Philadelphia, studying classical bass for five years under Eligio Rossi. He picked up bass guitar in his teens so that he could perform at parties and imitate the rock and pop bands that girls liked.\nClarke attended the Philadelphia Musical Academy (later known as the Philadelphia College of the Performing Arts, and ultimately as the University of the Arts, after having merged with the Philadelphia College of Art) and after graduating moved to New York City in 1971. His recording debut was with Curtis Fuller. He worked with Joe Henderson and Pharoah Sanders, then in 1972 with Tony Williams Lifetime Experience, Stan Getz, Dexter Gordon, and Art Blakey, followed by Gil Evans, Mel Lewis, and Horace Silver.\nClarke intended to become the first black musician in the Philadelphia Orchestra until he met jazz pianist Chick Corea. At the time, Corea was working with Stan Getz putting together a new backing band for him and writing music for the group; these pieces first surfaced on two albums recorded in February/March 1972 in New York, Captain Marvel (credited to Getz, released in 1975) and Return to Forever (credited to Corea, issued in Europe in 1972). Clarke''s playing and improvising was prominent on both albums; the band also played a couple of gigs with Getz in Europe. At this early stage, the band as separate from Getz was mostly a studio side project, but the members soon realized that it had potential as a regular live band, and so the band Return to Forever had been born.\nThe first edition of Return to Forever performed primarily Latin-oriented music and used only acoustic instruments (except for Corea''s Fender Rhodes piano). This band consisted of singer Flora Purim, her husband Airto Moreira (both Brazilians) on drums and percussion, Corea''s longtime musical co-worker Joe Farrell on saxophone and flute, and Clarke on bass. Their first album, titled Return to Forever, was recorded for ECM Records in 1972. The second album, Light as a Feather (1973), was released by Polydor and included the song \"Spain\".\nAfter the second album, Farrell, Purim and Moreira left the group to form their own band, and guitarist Bill Connors, drummer Steve Gadd and percussionist Mingo Lewis were added. Lenny White (who had played with Corea in Miles Davis''s band) replaced Gadd and Lewis on drums and percussion, and the group''s third album, Hymn of the Seventh Galaxy (1973), was released.\nFusion was a combination of rock and jazz which they helped develop in the early 1970s. Clarke was playing a new kind of music, using new techniques, and giving the bass guitar a prominence it lacked. He drew attention to the bass guitar as a solo instrument that could be melodic and dominant in addition to being part of the rhythm section. For helping to bring the bass guitar to the front of the band, Clarke cites Jaco Pastorius, Paul McCartney, Jack Bruce, and Larry Graham.\nAfter Return to Forever''s second album, Light as a Feather, Clarke received job offers from Bill Evans, Miles Davis, and Ray Manzarek of the Doors, but he remained with Return to Forever until 1977. During the early 1980s, he toured with Corea and Return to Forever, then worked with Bobby Lyle, Eliane Elias, David Benoit and Michel Petrucciani. He toured in a band with Herbie Hancock and Wayne Shorter in 1991. In 1998 he founded Superband with Lenny White, Larry Carlton, and Jeff Lorber.\nCorea produced Clarke''s first solo album, Children of Forever (1973), and played keyboards on it with guitarist Pat Martino, drummer Lenny White, flautist Art Webb, and vocalists Andy Bey and Dee Dee Bridgewater. Clarke played double bass and bass guitar.\nClarke''s second self-titled album Stanley Clarke (1974) featured Tony Williams on drums, Bill Connors on electric and acoustic guitar, and Jan Hammer on synthesizer , electric piano, organ, and piano .\nWhile on tour, British guitarist Jeff Beck was performing the song \"Power\" from that album, and this was the impetus for their meeting and Beck''s introduction to Hammer. They toured together, and Beck appeared on some of Clarke''s albums, including Journey to Love (1975) and Modern Man (1978).\nThe album School Days (Nemperor Records, 1976) brought Clarke the most attention and praise he had received so far. With its memorable riff, the title song became so revered that fans called out for it during concerts.\nStanley Clarke and Victor Wooten in the SMV Thunder Tour, Stockholm Jazz Festival, 2009\nClarke has spent much of his career outside jazz. In 1979, Ronnie Wood of the Rolling Stones formed the New Barbarians with Clarke and Keith Richards. Two years later, Clarke and keyboardist George Duke formed the Clarke/Duke Project, which combined pop, jazz, funk, and R&B. They met in 1971 in Finland when Duke was with Cannonball Adderley. They recorded together for the first time on Clarke''s album Journey to Love. Their first album contained the single \"Sweet Baby\", which became a top 20 pop hit. They reunited for tours during the 1990s and the 2000s.\nClarke joined fellow bassist Paul McCartney in 1981 to play bass guitar on McCartney''s solo studio albums Tug of War (1982) and Pipes of Peace (1983).\nThe Stanley Clarke Band is an American jazz band led by Clarke. He founded the band in 1985, with Ruslan Sirota, Shariq Tucker, Cameron Graves, Beka Gochiashvili, Salar Nader, and Evan Garr. They released the album Find Out!. With a new group, The Stanley Clarke Band released the album The Stanley Clarke Band which won the 2011 Grammy Award for Best Contemporary Jazz Album. Their album The Message was released in 2018.\nThe band''s first album Find Out! was recorded at Sunset Sound Studios and was released in 1985 by Sony. With a band composed of Stanley Clarke on bass, Ronald Bruner Jr. on drums, and Ruslan Sirota on keyboards, the Stanley Clarke Band released The Stanley Clarke Band album. It was produced by Lenny White and Stanley Clarke and featured pianist Hiromi.\"\nThe album The Stanley Clarke Band won the Grammy Award for Best Contemporary Jazz Album at the 53rd Annual Grammy Awards. Additionally, the track \"No Mystery\" was nominated for Best Pop Instrumental Performance.\nThe Stanley Clarke Band with Clarke, Bruner Jr., and Sirota released The Message.\nThe Stanley Clarke Band (Heads Up, 2010)","Early Years":"Clarke with Return to Forever, Onondaga Community College, Syracuse, New York, 1974\nClarke was born on June 30, 1951, in Philadelphia. His mother sang opera around the house, belonged to a church choir, and encouraged him to study music. He started on accordion, then tried violin. But he felt awkward holding such a small instrument in his big hands when he was twelve years old and over six feet tall. No one wanted the acoustic bass in the corner, so he picked it up. He took lessons on the double bass at the Settlement Music School in Philadelphia, studying classical bass for five years under Eligio Rossi. He picked up bass guitar in his teens so that he could perform at parties and imitate the rock and pop bands that girls liked.\nClarke attended the Philadelphia Musical Academy (later known as the Philadelphia College of the Performing Arts, and ultimately as the University of the Arts, after having merged with the Philadelphia College of Art) and after graduating moved to New York City in 1971. His recording debut was with Curtis Fuller. He worked with Joe Henderson and Pharoah Sanders, then in 1972 with Tony Williams Lifetime Experience, Stan Getz, Dexter Gordon, and Art Blakey, followed by Gil Evans, Mel Lewis, and Horace Silver.","Career":"The band''s first album Find Out! was recorded at Sunset Sound Studios and was released in 1985 by Sony. With a band composed of Stanley Clarke on bass, Ronald Bruner Jr. on drums, and Ruslan Sirota on keyboards, the Stanley Clarke Band released The Stanley Clarke Band album. It was produced by Lenny White and Stanley Clarke and featured pianist Hiromi.\"\nThe album The Stanley Clarke Band won the Grammy Award for Best Contemporary Jazz Album at the 53rd Annual Grammy Awards. Additionally, the track \"No Mystery\" was nominated for Best Pop Instrumental Performance.\nThe Stanley Clarke Band with Clarke, Bruner Jr., and Sirota released The Message.\nThe Stanley Clarke Band (Heads Up, 2010)"}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (292, '1WmIo9ORq1IDlovUWFmo4Y', 'Stephane', 'Grappelli', 'bfc03211-a3a2-4700-8fa3-00968c02c5d0', 267089, 8, 'https://en.wikipedia.org/wiki/Stéphane_Grappelli', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Stephane_Grappelli_Allan_Warren.jpg/500px-Stephane_Grappelli_Allan_Warren.jpg', 'Allan warren', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Stephane_Grappelli_Allan_Warren.jpg', '{"Intro":"Stéphane Grappelli (French pronunciation: ; 26 January 1908 – 1 December 1997) was a French jazz violinist. He is best known as a founder of the Quintette du Hot Club de France with guitarist Django Reinhardt in 1934. It was one of the first all-string jazz bands. He has been called \"the grandfather of jazz violinists\" and continued playing concerts around the world well into his eighties.\nFor the first three decades of his career, he was billed using a gallicised spelling of his last name, Grappelly, reverting to the Italian spelling Grappelli in 1969. The latter is used when referring to the violinist, including reissues of his early work.","Biography":"Grappelli was born at Hôpital Lariboisière in Paris, France. His father, Italian Ernesto Grappelli, was born in Alatri, Lazio, while his French mother, Anna Emilie Hanoque, was from St-Omer. Ernesto was a scholar who taught Italian, sold translations, and wrote articles for local journals. Grappelli''s mother died when he was five, leaving his father to care for him. Although he was residing in France when World War I began, Ernesto was still an Italian citizen, and was consequently drafted into the Italian Army in 1914.\nHaving written about American dancer Isadora Duncan, who was living in Paris, Ernesto appealed to her to care for his son. Stéphane was enrolled in Duncan''s dance school at the age of six, and he learned to love French Impressionist music. With the war approaching, Duncan fled the country; she turned over her château to be used as a military hospital. Ernesto subsequently entrusted his son to a Catholic orphanage. Grappelli said of this time:\nI look back at it as an abominable memory ... The place was supposed to be under the eye of the government, but the government looked elsewhere. We slept on the floor, and often were without food. There were many times when I had to fight for a crust of bread.\nGrappelli compared his early life to a Dickens novel, and said that he once tried to eat flies to ease his hunger. He stayed at the orphanage until his father returned from the war in 1918, settling them in an apartment in Barbès. Having been sickened by his experiences with the Italian military, Ernesto took Stéphane to city hall, pulled two witnesses off the street, and had his son naturalized as a French citizen on 28 July 1919. His first name Stefano was Gallicized to Stéphane.\nGrappelli began playing the violin at the age of 12 on a three-quarter-sized violin, which his father purchased by pawning a suit. Although Stéphane received violin lessons, he preferred to learn the instrument on his own:\nMy first lessons were in the streets, watching how other violinists played ... The first violinist that I saw play was at the Barbès metro station, sheltered under the overhead metro tracks. When I asked how one should play, he exploded in laughter. I left, completely humiliated with my violin under my arm.\nAfter a brief period of independent learning, Grappelli was enrolled at the Conservatoire de Paris on 31 December 1920, which his father hoped would give him a chance to learn music theory, ear-training, and solfeggio. In 1923, Grappelli graduated with a second-tier medal. Around this time, his father married a woman named Anna Fuchs and moved to Strasbourg. Grappelli remained in Paris because he disliked Fuchs.\nAt the age of 15, Grappelli began busking full-time to support himself. His playing caught the attention of an elderly violinist, who invited him to accompany silent films in the pit orchestra at the Théâtre Gaumont. He played there for six hours daily over a two-year period. During orchestra breaks, he visited Le Boudon, a brasserie, where he would listen to songs from an American proto-jukebox. Here he was introduced to jazz. In 1928, Grappelli was a member of the orchestra at the Ambassador Hotel while bandleader Paul Whiteman and jazz violinist Joe Venuti were performing there. Jazz violinists were rare, and though Venuti played mainly commercial jazz themes and seldom improvised, Grappelli was struck by his bowing when he played \"Dinah\". As a result, Grappelli began developing a jazz-influenced style of violin music.\nGrappelli lived with Michel Warlop, a classically trained violinist. Warlop admired Grappelli''s jazz-inspired playing, while Grappelli envied Warlop''s income. After experimenting with the piano, Grappelli stopped playing the violin, choosing simplicity, a new sound, and paid performances over familiarity. He began playing piano in a big band led by a musician called Grégor. In 1929, after a night of drinking, Grégor learned that Grappelli used to play the violin. Grégor borrowed a violin and asked Grappelli to improvise over \"Dinah\". Delighted by what he heard, Grégor urged Grappelli to return to playing the violin.\nIn 1930, Grégor ran into financial trouble. He was involved in an automobile accident that resulted in several deaths, and fled to South America to avoid arrest. Grégor''s band reunited as a jazz ensemble under the leadership of pianist Alain Romans and saxophonist André Ekyan. While playing with this band, Grappelli met gypsy jazz guitarist Django Reinhardt in 1931. Looking for a violinist interested in jazz, he invited Grappelli to play with him in his caravan. Although the two played for hours that afternoon, their commitments to their respective bands prevented them from pursuing a career together.\nIn the summer of 1934 they met again while both were engaged as members of a band led by bassist Louis Vola playing at the Hôtel Claridge on the Champs-Élysées in Paris, and began a musical partnership. Pierre Nourry, the secretary of the Hot Club de France, invited Reinhardt and Grappelli to form the Quintette du Hot Club de France, with Louis Vola on bass and Joseph Reinhardt and Roger Chaput on guitar.\nAlso located in the Montmartre district was the artistic salon of R-26, at which Grappelli and Reinhardt performed regularly.\nThe Quintette du Hot Club de France disbanded in 1939 upon the outbreak of World War II; Grappelli was in London at the time, and stayed there for the duration of the war. In 1940, jazz pianist George Shearing made his debut as a sideman in Grappelli''s band.\nWhen the war was over, Reinhardt came to England for a reunion with Grappelli. They recorded some titles in London with the \"English Quintette\" during January and February 1946 for EMI and Decca, using a rhythm section consisting of English guitarists Jack Llewelyn and Alan Hodgkiss together with the Jamaican jazz bassist Coleridge Goode. Grappelli chose to remain in England, while Reinhardt returned to Paris before undertaking an only moderately successful visit to the United States, where he performed in a new style using an amplified archtop guitar with Duke Ellington''s orchestra. On Reinhardt''s return, he and Grappelli reunited periodically for concerts on occasions when the latter was visiting Paris; however, the pre-war Quintette was never re-formed. The pair also briefly toured Italy, where they were supported by an Italian rhythm section of piano, bass and drums; the tour was documented, with around 50 tracks recorded for an Italian radio station, about half of which can be heard on the album Djangology (released in 2005). This was to be the last set of recordings featuring the pair, with Reinhardt moving into a more bebop/modern jazz idiom and playing with younger French musicians prior to his early death in 1953, aged only 43.\nThroughout the 1950s, Grappelli made occasional visits to the recording studio, but the opportunities for a swing violinist of his generation were becoming limited; despite attempts to modernise his style, Grappelli was never particularly interested in the bebop style which was then fashionable in the jazz world. He made a brief filmed appearance in Paul Paviot''s 1957 film Django Reinhardt, in which he plays \"Minor Swing\" alongside Joseph Reinhardt, Henri Crolla and others. In the 1960s, Grappelli made regular appearances on the BBC Light Programme, French Public Radio, and the pirate station Radio Luxembourg. In 1967, he returned to Paris to take up a regular engagement providing music for diners at the \"Le Toit de Paris\" restaurant in the Paris Hilton Hotel, a position he kept up until 1972, for it provided regular work plus accommodation at the hotel. He played in a standard \"lounge jazz\" format, accompanied by a pianist and drummer. Grappelli was making a living, but by now had very little impact on the jazz world.\nIn 1971, British chat-show host Michael Parkinson, a longtime jazz fan, came up with the idea of including Grappelli on his show Parkinson, where he would be joined by the classical violinist Yehudi Menuhin, with the two musicians performing a duet. Although Menuhin had no jazz training and a distinctly classical style of playing, the result went down very well with the British public. The pair went on to record three collaborative albums between 1972 and 1976, with Menuhin playing parts written out by Grappelli while the latter improvised in a classic jazz fashion. During their appearance on Parkinson''s show, Menuhin played his prized Stradivari dating from 1714, while Grappelli revealed his instrument was made by Goffredo Cappa in 1695.\nIn 1973, British guitarist Diz Disley had the idea of prising Grappelli away from his \"lounge jazz\" format with piano players to play once again with the backing of acoustic guitars and double bass, re-creating a version of the \"Hot Club\" sound, but now with Grappelli as sole leader. Grappelli''s reservations about returning to this format were dissipated following a rapturous reception for the \"new\" (old) format group at that year''s Cambridge Folk Festival, after which he favoured the guitar-based trio (with double bass) for a series of increasingly successful concert tours around the globe. These tours would virtually occupy the remainder of Grappelli''s life; away from the touring circuit, however, he also favoured numerous other instrumental combinations on record. Other guitarists in the British \"Diz Disley Trio\" providing his instrumental backing over the years included Denny Wright, Ike Isaacs, the Irish guitarist Louis Stewart, John Etheridge and Martin Taylor, while double bass was often provided by Dutchman Jack Sewing; in his later years, Grappelli also used a Parisian trio which included guitarist Marc Fosset and bassist Patrice Caratini.\nIn April 1973, Grappelli performed with great success during a week at \"Jazz Power\" in Milan, accompanied by Italian jazz musicians as guitarist Franco Cerri, bassist/arranger Pino Presti and drummer Tullio De Piscopo.\nGrappelli played on hundreds of recordings, including sessions with Duke Ellington, jazz pianists Oscar Peterson, Michel Petrucciani and Claude Bolling, jazz violinists Svend Asmussen, Jean-Luc Ponty, and Stuff Smith, Indian classical violinist L. Subramaniam, vibraphonist Gary Burton, pop singer Paul Simon, mandolin player David Grisman, classical violinist Yehudi Menuhin, orchestral conductor André Previn, guitar player Bucky Pizzarelli, guitar player Joe Pass, cello player Yo Yo Ma, harmonica and jazz guitar player Toots Thielemans, jazz guitarist Henri Crolla, bassist Jon Burr and fiddler Mark O''Connor.\nGrappelli recorded a solo for the title track of Pink Floyd''s 1975 album Wish You Were Here. This was made almost inaudible in the mix, and so the violinist was not credited, according to Roger Waters, as it would be \"a bit of an insult\". A remastered version with Grappelli''s contribution fully audible can be found on the 2011 editions of Wish You Were Here.\nGrappelli composed the score for two French films: Going Places (Bertrand Blier, 1974) and May Fools (Louis Malle, 1990).\nGrappelli made a cameo appearance in the 1978 film King of the Gypsies with mandolinist David Grisman. Three years later they performed in concert. He also made a 1975 cameo as a violinist in Little House on the Prairie season 2, episode 8. In the 1980s he gave several concerts with British cellist Julian Lloyd Webber. In 1997, Grappelli received the Grammy Lifetime Achievement Award. He is an inductee of the Down Beat Jazz Hall of Fame.\nGrappelli continued touring up to the last year of his life; in 1997, although his health was by then poor, he toured the United Kingdom in March and then played concerts in Australia and New Zealand, giving his last public performance in Christchurch, New Zealand, before returning to Paris via Hong Kong. He made his final recording, four tracks with the classical violinist Iwao Furusawa, plus guitarist Marc Fosset and bassist Philippe Viret, in Paris in August 1996 (released as As Time Goes By: Stéphane Grappelli and Iwao Furusawa).","Early Years":"Grappelli was born at Hôpital Lariboisière in Paris, France. His father, Italian Ernesto Grappelli, was born in Alatri, Lazio, while his French mother, Anna Emilie Hanoque, was from St-Omer. Ernesto was a scholar who taught Italian, sold translations, and wrote articles for local journals. Grappelli''s mother died when he was five, leaving his father to care for him. Although he was residing in France when World War I began, Ernesto was still an Italian citizen, and was consequently drafted into the Italian Army in 1914.\nHaving written about American dancer Isadora Duncan, who was living in Paris, Ernesto appealed to her to care for his son. Stéphane was enrolled in Duncan''s dance school at the age of six, and he learned to love French Impressionist music. With the war approaching, Duncan fled the country; she turned over her château to be used as a military hospital. Ernesto subsequently entrusted his son to a Catholic orphanage. Grappelli said of this time:\nI look back at it as an abominable memory ... The place was supposed to be under the eye of the government, but the government looked elsewhere. We slept on the floor, and often were without food. There were many times when I had to fight for a crust of bread.\nGrappelli compared his early life to a Dickens novel, and said that he once tried to eat flies to ease his hunger. He stayed at the orphanage until his father returned from the war in 1918, settling them in an apartment in Barbès. Having been sickened by his experiences with the Italian military, Ernesto took Stéphane to city hall, pulled two witnesses off the street, and had his son naturalized as a French citizen on 28 July 1919. His first name Stefano was Gallicized to Stéphane.\nGrappelli began playing the violin at the age of 12 on a three-quarter-sized violin, which his father purchased by pawning a suit. Although Stéphane received violin lessons, he preferred to learn the instrument on his own:\nMy first lessons were in the streets, watching how other violinists played ... The first violinist that I saw play was at the Barbès metro station, sheltered under the overhead metro tracks. When I asked how one should play, he exploded in laughter. I left, completely humiliated with my violin under my arm.\nAfter a brief period of independent learning, Grappelli was enrolled at the Conservatoire de Paris on 31 December 1920, which his father hoped would give him a chance to learn music theory, ear-training, and solfeggio. In 1923, Grappelli graduated with a second-tier medal. Around this time, his father married a woman named Anna Fuchs and moved to Strasbourg. Grappelli remained in Paris because he disliked Fuchs.\nAt the age of 15, Grappelli began busking full-time to support himself. His playing caught the attention of an elderly violinist, who invited him to accompany silent films in the pit orchestra at the Théâtre Gaumont. He played there for six hours daily over a two-year period. During orchestra breaks, he visited Le Boudon, a brasserie, where he would listen to songs from an American proto-jukebox. Here he was introduced to jazz. In 1928, Grappelli was a member of the orchestra at the Ambassador Hotel while bandleader Paul Whiteman and jazz violinist Joe Venuti were performing there. Jazz violinists were rare, and though Venuti played mainly commercial jazz themes and seldom improvised, Grappelli was struck by his bowing when he played \"Dinah\". As a result, Grappelli began developing a jazz-influenced style of violin music.\nGrappelli lived with Michel Warlop, a classically trained violinist. Warlop admired Grappelli''s jazz-inspired playing, while Grappelli envied Warlop''s income. After experimenting with the piano, Grappelli stopped playing the violin, choosing simplicity, a new sound, and paid performances over familiarity. He began playing piano in a big band led by a musician called Grégor. In 1929, after a night of drinking, Grégor learned that Grappelli used to play the violin. Grégor borrowed a violin and asked Grappelli to improvise over \"Dinah\". Delighted by what he heard, Grégor urged Grappelli to return to playing the violin.\nIn 1930, Grégor ran into financial trouble. He was involved in an automobile accident that resulted in several deaths, and fled to South America to avoid arrest. Grégor''s band reunited as a jazz ensemble under the leadership of pianist Alain Romans and saxophonist André Ekyan. While playing with this band, Grappelli met gypsy jazz guitarist Django Reinhardt in 1931. Looking for a violinist interested in jazz, he invited Grappelli to play with him in his caravan. Although the two played for hours that afternoon, their commitments to their respective bands prevented them from pursuing a career together.\nIn the summer of 1934 they met again while both were engaged as members of a band led by bassist Louis Vola playing at the Hôtel Claridge on the Champs-Élysées in Paris, and began a musical partnership. Pierre Nourry, the secretary of the Hot Club de France, invited Reinhardt and Grappelli to form the Quintette du Hot Club de France, with Louis Vola on bass and Joseph Reinhardt and Roger Chaput on guitar.\nAlso located in the Montmartre district was the artistic salon of R-26, at which Grappelli and Reinhardt performed regularly.\nThe Quintette du Hot Club de France disbanded in 1939 upon the outbreak of World War II; Grappelli was in London at the time, and stayed there for the duration of the war. In 1940, jazz pianist George Shearing made his debut as a sideman in Grappelli''s band.","Personal Life And Legacy":"Grappelli''s final resting place in crypt 417 of Division 87 (Columbarium) at Pere Lachaise Cemetery\nIn May 1935, Grappelli had a brief affair with Sylvia Caro that resulted in a daughter named Evelyne. Sylvia remained in Paris with her daughter for the duration of World War II. Father and daughter were reunited in 1946 when Evelyne travelled to London from France to stay with Grappelli for about a year. From 1952 to 1980, he shared much of his life with a female friend, Jean Barclay, for whom he felt a deep brotherly affection. Grappelli never married, however, and it is widely accepted that he was gay; in 1981 he met Joseph Oldenhove, who would be his companion until his death.\nGrappelli died in Paris on 1 December 1997, suffering heart failure after a series of minor cerebral attacks. His funeral, on 5 December, took place at the Église Saint-Vincent-de-Paul, Paris, within sight of the entrance to the Lariboisière Hospital where he had been born 89 years earlier. His body was cremated and his ashes entombed in the city''s Père Lachaise Cemetery.\nHe is the subject of the documentary Stéphane Grappelli – A Life in the Jazz Century."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (293, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Coleman', '0f1ae3cd-2ab3-435c-8a5b-245e8073d91a', 44115, 6, 'https://en.wikipedia.org/wiki/Steve_Coleman', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Steve_Coleman_1611.JPG/500px-Steve_Coleman_1611.JPG', 'No machine-readable author provided. Mbase1235 assumed (based on copyright claims).', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Steve_Coleman_1611.JPG', '{"Intro":"Steve Coleman (born September 20, 1956) is an American saxophonist, composer, bandleader and music theorist. In 2014, he was named a MacArthur Fellow.","Early Life":"Steve Coleman was born and grew up in South Side, Chicago. He started playing alto saxophone at the age of 14. Coleman attended Illinois Wesleyan University for two years, followed by a transfer to Roosevelt University (Chicago Musical College).\nColeman moved to New York in 1978 and worked in big bands such as the Thad Jones/Mel Lewis Orchestra, Slide Hampton''s big band, Sam Rivers'' Studio Rivbea Orchestra, and briefly in Cecil Taylor''s big band. Shortly thereafter, Coleman began working as a sideman with David Murray, Doug Hammond, Dave Holland, Michael Brecker and Abbey Lincoln. During his first four years in New York, Coleman played in the streets and in small clubs with a band that he put together with trumpeter Graham Haynes. This group would evolve into Steve Coleman and Five Elements, which would serve as the main ensemble for Coleman''s activities. In this group, he developed his concept of improvisation within nested looping structures. Coleman collaborated with other young African-American musicians such as Cassandra Wilson and Greg Osby, and they founded the so-called M-Base movement."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (294, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Grossman', 'dd21e106-2c27-430a-98a9-7039e1606abb', 256167, 6, 'https://en.wikipedia.org/wiki/Steve_Grossman_(saxophonist)', 'https://upload.wikimedia.org/wikipedia/commons/b/bb/Steve_Grossman.jpg', 'Mfiskum. Marius Fiskum. www.fototopia.no', 'CC BY 3.0', 'https://commons.wikimedia.org/wiki/File:Steve_Grossman.jpg', '{"Intro":"Steven Mark Grossman (January 18, 1951 – August 13, 2020) was an American jazz fusion and hard bop saxophonist.\nGrossman was Wayne Shorter''s replacement in Miles Davis''s jazz-fusion band. He played with Chick Corea on the album \"The Sun\" in 1970, then, from 1971 to 1973, he was in Elvin Jones''s band.\nIn the late 1970s, he was part of the Stone Alliance trio with percussionist Don Alias and bassist Gene Perla. The group released four albums during this period, including one featuring Brazilian trumpeter Márcio Montarroyos. The albums also feature an array of other musicians. They went on to release three live reunion albums during the 2000s.","Personal Life":"Grossman was born in Brooklyn, New York, United States, on January 18, 1951, to Rosalind, an amateur pianist, and Irving, an RCA salesman and later president of KLH Research and Development Corporation. He died of cardiac arrest in Glen Cove, New York, on August 13, 2020, at the age of 69."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (295, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Lacy', 'ca9766a0-1c30-43e6-a213-bac1334efc4a', 97532, 6, 'https://en.wikipedia.org/wiki/Steve_Lacy_(saxophonist)', 'https://upload.wikimedia.org/wikipedia/commons/8/87/Steve_Lacy.jpg', 'Lioneldecoster', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Steve_Lacy.jpg', '{"Intro":"Steve Lacy (born Steven Norman Lackritz; July 23, 1934 – June 4, 2004) was an American jazz saxophonist and composer recognized as one of the important players of soprano saxophone. Coming to prominence in the 1950s as a progressive dixieland musician, Lacy went on to a long and prolific career. He worked extensively in experimental jazz and to a lesser extent in free improvisation, but Lacy''s music was typically melodic and tightly-structured. Lacy also became a highly distinctive composer, with compositions often built out of little more than a single questioning phrase, repeated several times.\nThe music of Thelonious Monk became a permanent part of Lacy''s repertoire after a stint in the pianist''s band, with Monk''s works appearing on virtually every Lacy album and concert program; Lacy often partnered with trombonist Roswell Rudd in exploring Monk''s work. Beyond Monk, Lacy performed the work of jazz composers such as Charles Mingus, Duke Ellington and Herbie Nichols; unlike many jazz musicians he rarely played standard popular or show tunes.","Early Life And Career":"Lacy began his career at sixteen playing Dixieland music with much older musicians such as Henry \"Red\" Allen, Pee Wee Russell, George \"Pops\" Foster and Zutty Singleton and then with Kansas City jazz players like Buck Clayton, Dicky Wells, and Jimmy Rushing. He then became involved with the avant-garde, performing on Jazz Advance (1956), the debut album of Cecil Taylor, and appearing with Taylor''s groundbreaking quartet at the 1957 Newport Jazz Festival; he also made a notable appearance on an early Gil Evans album. His most enduring relationship, however, was with the music of Thelonious Monk: he recorded the first album to feature only Monk compositions (Reflections, Prestige, 1958) and briefly played in Monk''s band in 1960 and later on Monk''s Big Band and Quartet in Concert album (Columbia, 1963).","Later Career":"In 1992, he was the recipient of a MacArthur Fellowship (nicknamed the \"genius grant\").\nHe also collaborated with a wide range of musicians, from traditional jazz to the avant-garde to contemporary classical music. Outside of his regular sextet, his most regular collaborator was pianist Mal Waldron,–245  with whom he recorded a number of duet albums (notably Sempre Amore, a collection of Ellington/Strayhorn material, Soul Note, 1987).\nLacy played his ''farewell concerts to Europe'' in Belgium, in duo and solo, for a small but motivated public. This happened in Brussels, Antwerp, Ghent, Bruges and Mons. In duo he played with Fred Van Hove, Joëlle Léandre, Mikhail Bezverkhni, Irène Aebi, Frederic Rzewski, Christopher Culpo and the dancer Shiro Daimon. This recollection is published by Naked Music, Afkikker, Ghent. In Ghent he played with the classical violinist Mikhail Bezverkhni, winner of Queen Elisabeth Concours. Two of these concerts were organized by Rita De Vuyst, his last muse in Europe, to whom he dedicated his solo CD Mother Goose solo @ afkikker. This CD is published within the book, Bone, a tribute to Lacy. He returned to the United States in 2002, where he began teaching at the New England Conservatory of Music in Boston, Massachusetts. One of his last public performances was in front of 25,000 people at the close of a peace rally on Boston Common in March 2003, shortly before the US-led invasion of Iraq.\nAfter Lacy was diagnosed with liver cancer in August 2003, he continued playing and teaching until weeks before his death on June 4, 2004, at the age of 69."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (296, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Mccall', 'a478c780-f183-4de5-b654-2051d20f20f6', 276969, 4, 'https://en.wikipedia.org/wiki/Steve_McCall_(drummer)', NULL, NULL, NULL, NULL, '{"Intro":"Steve McCall (September 30, 1933 – May 24, 1989) was an American jazz drummer.","Biography":"McCall was born in Chicago, Illinois, United States. As a young child, he \"experienced a musical epiphany\" when he was given an opportunity to play a drum in Chicago''s annual Bud Billiken Parade. As a teenager, he attended Englewood High School in Chicago and studied music theory, Latin percussion, and classical percussion. After high school, he left to join the U. S. Air Force, then, in 1954, returned to Chicago, where he took a job in the airline industry. He soon bought his first drum set and began using free air travel passes to study with drummer Charles \"Specs\" Wright in Philadelphia. He also began freelancing, playing with Lucky Carmichael, Booker Ervin, Charles Stepney, Gene Shaw, and Ramsey Lewis.\nIn 1961, McCall befriended pianist Muhal Richard Abrams, and began playing with Abrams'' Experimental Band, which brought him into contact with like-minded Chicago-based musicians. Over the coming years the two also played in a trio format with multi-instrumentalist Donald Rafael Garrett, and well as in a quintet which included Garrett plus saxophonists Gene Dinwiddie and Roscoe Mitchell. McCall went on to become one of the founders of the AACM, established in 1965, initially serving as treasurer. During the mid-1960s, he continued to freelance with musicians and groups in a wide range of styles, from blues to bop to free jazz. In 1966, he participated in the recording of Joseph Jarman''s debut album Song For.\nIn 1967, McCall moved to Amsterdam, the first AACM member to visit Europe, and was soon playing with expatriates such as Don Byas and Dexter Gordon. In 1968, he began playing in a group led by Marion Brown, featuring Gunter Hampel, Ambrose Jackson, and Barre Phillips. McCall would go on to record five albums with Brown. That year, McCall moved to Paris and joined an existing group whose members were Anthony Braxton, Leo Smith, and Leroy Jenkins. (The Braxton/Smith/Jenkins trio had recently completed work on the album 3 Compositions of New Jazz). Together, the four recorded the albums Anthony Braxton and This Time... for BYG Actuel. During his stay in Paris, McCall served as a link between the first generation of European free jazz musicians and members of the AACM, playing and recording with Willem Breuker, the Instant Composers Pool, John Surman, Tony Oxley, and Gunter Hampel. Notable albums recorded during this time included Hampel''s The 8th Of July 1969, which also featured Braxton and Jeanne Lee, as well as Gittin'' to Know Y''All, recorded during the 1969 Baden-Baden Free Jazz Meeting.\nIn 1970, McCall moved back to Chicago. In May of that year, he reunited with Braxton, Smith and Jenkins, forming a group which also included Muhal Richard Abrams and Richard Davis, and which became known as the Creative Construction Company. The group performed a concert at the Peace Church in New York City, a recording of which was released in two volumes. That summer, McCall also recorded the album The Chase! with Dexter Gordon and Gene Ammons. The following year, he played with Henry Threadgill and Fred Hopkins in a short-lived trio called Reflection. The group would later reunite under the name Air. In 1972, McCall played with both the Fred Anderson quartet and the Muhal Richard Abrams Sextet.\nIn 1974, McCall moved back to Europe. He then returned to the United States in 1975, moving to New York City and reuniting with Threadgill and Hopkins. The trio, now called Air, would go on to record eleven albums, with McCall participating in all but the last two. During the mid to late 1970s, McCall also performed and recorded with Abrams, Billy Bang, Arthur Blythe, Ted Curson, Chico Freeman, Cecil McBee, and Butch Morris. During the early 1980s, he recorded a number of albums with David Murray, and in the mid-1980s, he joined Cecil Taylor''s group, recording Olu Iwa, and worked with Roscoe Mitchell again, recording The Flow of Things.\nMcCall died in 1989 at South Shore Hospital in Chicago. Despite his lengthy career, he never recorded a session as a leader. However, McCall received equal billing with tenor sax player Fred Anderson on the posthumously released Vintage Duets album, recorded in 1980 and issued in 1994.","Legacy And Tributes":"Writer Gary Giddins called McCall \"an immensely likable man whose work with Air was a benchmark of the ''70s\", and praised his drumming as \"ingeniously volatile\". The authors of The Penguin Guide to Jazz noted McCall''s \"ability to combine forward drive with outbreaks of complete rhythmic anarchy\". John Litweiler wrote that McCall''s \"sensitivity to subtle gradations of sound textures... put him in wide demand as an accompanist; uniquely in jazz, he was a drummer who conveyed emotional subtlety.\"\nHenry Threadgill recalled: \"Steve plays so unorthodox, the way he used to handle space, he would free me so I''d have a number of levels to play on.\" Sunny Murray called McCall \"the best surprise with the left hand I ever heard\".\nDavid Murray recorded a tribute composed by Butch Morris entitled \"Calling Steve McCall\" on his 1991 album David Murray Big Band. In 1992, Roscoe Mitchell recorded an album titled This Dance Is for Steve McCall as a tribute. In 2015, the Artifacts Trio (Nicole Mitchell, Tomeka Reid, and Mike Reed) included two of McCall''s compositions on their album Artifacts as part of a celebration of the AACM''s legacy."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (297, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Swallow', 'd94cd4f9-3178-4cc5-9e96-c9306385ffb0', 284204, 1, 'https://en.wikipedia.org/wiki/Steve_Swallow', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Steve_Swallow_05N8681.jpg/500px-Steve_Swallow_05N8681.jpg', 'Nomo michael hoefner http://www.zwo5.de', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Steve_Swallow_05N8681.jpg', '{"Intro":"Steve Swallow (born October 4, 1940) is an American jazz bassist and composer, known for his collaborations with Jimmy Giuffre, Gary Burton, and Carla Bley. He was one of the first jazz double bassists to switch entirely to electric bass guitar.","Biography":"Born in Fair Lawn, New Jersey, United States, Swallow studied piano and trumpet, as a child, before turning to the double bass at the age of 14. While attending a prep school, he began trying his hand in jazz improvisation. In 1960, he left Yale University, where he was studying composition, and settled in New York City, playing at the time in Jimmy Giuffre''s trio along with Paul Bley. After joining Art Farmer''s quartet in 1963, Swallow began to write. It is in the 1960s that his long-term association with Gary Burton''s various bands began.\nIn the early 1970s, Swallow switched exclusively to electric bass guitar, of which he prefers the five-string variety. He was first introduced to the electric bass while doing a music trade show with Gary Burton and trying a Gibson EB-2. Along with Monk Montgomery and Bob Cranshaw, Swallow was among the first jazz bassists to do so (with much encouragement from Roy Haynes, one of Swallow''s favorite drummers). He plays with a pick (made of copper by Hotlicks), and his style involves intricate solos in the upper register. He was one of the early adopters of the high C string on a bass guitar.\nFrom 1974 to 1976, Swallow taught at the Berklee College of Music. He contributed several of his compositions to the Berklee students who assembled the first edition of The Real Book. He later recorded an album, Real Book, with the picture of a well-worn, coffee-stained book on the cover.\nIn 1978, Swallow became a member of Carla Bley''s band. He was Bley''s romantic partner from the 1980s until her death in 2023. He toured extensively with John Scofield in the early 1980s, and has returned to this collaboration several times over the years.\nSwallow has consistently won the electric bass category in DownBeat yearly polls, both Critics'' and Readers'', since the mid-1980s. His compositions have been covered by, among others, Jim Hall (who recorded his first tune, \"Eiderdown\"), Bill Evans, Chick Corea, Stan Getz and Gary Burton. Swallow''s instruments are built by Harvey Citron."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (298, '1WmIo9ORq1IDlovUWFmo4Y', 'Steve', 'Turre', '1751f9e8-e0b5-4d3c-99b6-d93e0e1f4895', 174447, 11, 'https://en.wikipedia.org/wiki/Steve_Turre', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Steve_Turre_in_2010.jpg/500px-Steve_Turre_in_2010.jpg', 'Tom Beetz', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Steve_Turre_in_2010.jpg', '{"Intro":"Stephen Johnson Turre (born September 12, 1948, in Omaha, Nebraska) is an American jazz trombonist and a pioneer of using seashells as instruments, a composer, arranger, and educator at the collegiate-conservatory level. For sixty-two years, Turre has been active in jazz, rock, and Latin jazz – in live venues, recording studios, television, and cinema production.\nHe has recorded over 20 albums as a bandleader, and appeared on many more as a contributor or sideman. As a studio musician, Turre is among the most prolific living jazz trombonists in the world. He has been a member of the Saturday Night Live Band since 1985.","Early Life":"Turre is one of five children born to James Boles Turre (1921–1997) and Carmen Marie (née Johnson). His father was of Northern Italian ancestry and his mother was of Mexican ancestry. His grandfather Ernest Turre was a founder of the San Francisco 49ers with Tony Morabito. His four siblings are Michael James Turre (b. 1946), Suzanne Turre (born 1952), Michele Anita Turre (born 1953), and Peter Joseph Turre (born 1957). Michael and Peter were musicians – saxophone-woodwinds and drums, respectively.\nTurre was raised in Lafayette, California (San Francisco Bay area). He began playing trombone at age ten, during his fourth grade in school. In his early teens, he played in a band with his elder brother, Michael. Although he entered California State University, Sacramento, on a football scholarship, he studied music theory there for two years before transferring to the University of North Texas College of Music, where he studied from 1968 to 1969 and played in a band led by trumpeter Hannibal Peterson.\nTurre has been a resident of Montclair, New Jersey.","Personal Life":"Turre has been married three times. His first wife was Susan J. Beard, whom he married in 1970 in Dallas, Texas, and divorced in 1972 in San Francisco. His second wife was cellist Akua Dixon (born 1948) from 1978 to 2012, with whom he had two children: Andromeda Turre, a jazz vocalist and composer, and Orion Turre, a jazz drummer.\nHis present wife is Pamela Turre, whom he married on September 24, 2017.","Career Highlights":"L to R: Big Sam Williams, Jeff Albert, Steve Turre, and Kirk Joseph\nIn 1968, Turre played with Rahsaan Roland Kirk. In 1970 he recorded with Carlos Santana, and in 1972 he toured with Ray Charles. He has been trombonist for the Saturday Night Live band since 1985 and has taught jazz trombone at the Manhattan School of Music since 1988.\nFor fifty-six years (since 1970), Turre has been an exponent of seashells – conch in particular – as serious musical instruments. According to Turre, encouragement came from Kirk who was known for using a vast array of saxophones, flutes and other instruments. Turre has a collection of shells of various sizes, most of them picked up during his travels in the Caribbean and elsewhere. The shells have their mouthpieces carefully cut and are tuned to specific pitches. When playing them as a soloist, he frequently switches between shells, as each is limited in its register (the smallest shells, for example, have a practical register of only a fifth). His largest shell, from the Great Barrier Reef of Australia, has a range between the D and E below middle C, and was painted by a Cuban artist. He also leads \"Sanctified Shells,\" which is a \"shell choir\" made up of brass players who double on seashell (using shells from Turre''s collection, which he loans out for rehearsals and performances). The group released its first, eponymous album in 1993. Turre has had a long experience with Latin jazz and is a skilled player of the cowbell and Venezuelan maracas.\nSteve Turre on shells, with Libre at the Village Gate (1980s).\nTurre has been a member of the Juilliard School faculty for nineteen years – since 2008, and previously from 2001 to 2003.\nTurre  earned his bachelor''s degree from the University of Massachusetts Amherst through the University Without Walls in 1980 with a focus in Afro-American Music and Jazz."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (299, '1WmIo9ORq1IDlovUWFmo4Y', 'Sun', 'Ra', 'c27cac8e-4c4a-48c0-a4ba-41399b9c176d', 35328, 13, 'https://en.wikipedia.org/wiki/Sun_Ra', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Sun_Ra_%281973_publicity_photo_-_Impulse_ABC_Dunhill%29.jpg/500px-Sun_Ra_%281973_publicity_photo_-_Impulse_ABC_Dunhill%29.jpg', 'Distributed by Impulse! Records and ABC/Dunhill Records. Photographer uncredited on the publicity photo itself; most likely Francis Ing, who is credited for the photography on Astro Black (see Discogs link above).', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Sun_Ra_(1973_publicity_photo_-_Impulse_ABC_Dunhill).jpg', '{"Intro":"Le Sony''r Ra (born Herman Poole Blount, May 22, 1914 – May 30, 1993), better known as Sun Ra, was an American jazz composer, bandleader, piano and synthesizer player, and poet known for his experimental music, \"cosmic\" philosophy, prolific output, and theatrical performances. For much of his career, Ra led The Arkestra, an ensemble with an ever-changing name and flexible line-up.\nBorn and raised in Alabama, Blount became involved in the Chicago jazz scene during the late 1940s. He soon abandoned his birth name, taking the name Le Sony''r Ra, shortened to Sun Ra (after Ra, the Egyptian god of the Sun). Claiming to be an alien from Saturn on a mission to preach peace, he developed a mythical persona and an idiosyncratic credo that made him a pioneer of Afrofuturism. Throughout his life he denied ties to his prior identity saying, \"Any name that I use other than Ra is a pseudonym.\" His widely eclectic and avant-garde music echoed the entire history of jazz, from ragtime and early New Orleans hot jazz, to swing music, bebop, free jazz and fusion. His compositions ranged from keyboard solos to works for big bands of over 30 musicians, along with electronic excursions, songs, chants, percussion pieces, and anthems.\nFrom the mid-1950s until his death, Ra led the musical collective The Arkestra, which featured artists such as Marshall Allen, John Gilmore and June Tyson throughout its various iterations. Its performances often included dancers and musicians dressed in elaborate, futuristic costumes inspired by ancient Egyptian attire and the Space Age. Following Ra''s retirement in 1992 due to illness, the band remained active as The Sun Ra Arkestra, and, as of 2026, continues performing under the leadership of veteran Ra sideman Marshall Allen.\nThough his mainstream success was limited, Ra was a prolific recording artist and frequent live performer, and remained influential throughout his life for his music and persona. He is now widely considered an innovator; among his distinctions are his pioneering work in free improvisation and modal jazz and his early use of electronic keyboards and synthesizers. Over his career, he recorded dozens of singles and over 100 full-length albums, comprising well over 1,000 songs, making him one of the most prolific recording artists of the 20th century.","Biography":"He was born Herman Blount on May 22, 1914, in Birmingham, Alabama, as discovered by his biographer, John F. Szwed, and published in his 1997 book, Space Is the Place: The Lives and Times of Sun Ra. He was named after the popular vaudeville stage magician Black Herman, who had deeply impressed his mother. He was nicknamed \"Sonny\" from his childhood, had an older sister and half-brother, and was doted upon by his mother and grandmother.\nFor decades, very little was known about Sun Ra''s early life, and he contributed to its mystique. As a self-invented person, he routinely gave evasive, contradictory or seemingly nonsensical answers to personal questions, and denied his birth name. He speculated, only half in jest, that he was distantly related to Elijah Poole, later known as Elijah Muhammad, leader of the Nation of Islam. His birthday for years remained unknown, as his claims ranged from 1910 to 1918. Only a few years before his death, the date of Sun Ra''s birth was still a mystery. Jim Macnie''s notes for Blue Delight (1989) said that Sun Ra was believed to be about 75 years old. This turned out to be correct; Szwed was able to uncover a wealth of information about his early life, and confirmed a birth date of May 22, 1914.\nAs a child, Blount was a skilled pianist. By the age of 11 or 12, he was composing and sight reading music. Birmingham was an important stop for touring musicians and he saw prominent musicians such as Fletcher Henderson, Duke Ellington, and Fats Waller, and other less well known performers. Sun Ra once said, \"The world let down a lot of good musicians\".\nIn his teenage years, Blount demonstrated prodigious musical talent: many times, according to acquaintances, he went to big band performances and then produced full transcriptions of the bands'' songs from memory. By his mid-teens, Blount was performing semi-professionally as a solo pianist, or as a member of various ad hoc jazz and R&B groups. He attended Birmingham''s segregated Industrial High School (now known as Parker High School), where he studied under music teacher John T. \"Fess\" Whatley, a demanding disciplinarian who was widely respected and whose classes produced many professional musicians.–22\nThough deeply religious, his family was not formally associated with any Christian church or sect. Blount had few or no close friends in high school but was remembered as kind-natured and quiet, an honor roll student, and a voracious reader. He took advantage of the Black Masonic Lodge as one of the few places in Birmingham where African Americans had unlimited access to books. Its collection on Freemasonry and other esoteric concepts made a strong impression on him.\nBy his teens, Blount suffered from cryptorchidism. It left him with a nearly constant discomfort that sometimes flared into severe pain. Szwed suggests that Blount felt shame about it and the condition contributed to his isolation.\nIn 1934, Blount was offered his first full-time musical job by Ethel Harper, his biology teacher from the high school, who had organized a band to pursue a career as a singer. Blount joined a musicians'' trade union and toured with Harper''s group through the US Southeast and Midwest. When Harper left the group mid-tour to move to New York (she later was a member of the modestly successful singing group the Ginger Snaps), Blount took over leadership of the group, renaming it the Sonny Blount Orchestra. They continued touring for several months before dissolving as unprofitable.–26  Though the first edition of the Sonny Blount Orchestra was not financially successful, they earned positive notice from fans and other musicians. Blount afterward found steady employment as a musician in Birmingham.\nBirmingham clubs often featured exotic trappings, such as vivid lighting and murals with tropical or oasis scenes. Some believe these influenced the elements Sun Ra incorporated in his later stage shows. Playing for the big bands gave black musicians a sense of pride and togetherness, and they were highly regarded in the black community. They were expected to be disciplined and presentable, and in the segregated South, black musicians had wide acceptance in white society. They often played for elite white society audiences (though they were typically forbidden from associating with the audience).\nIn 1936, Whatley''s intercession led to Blount''s being awarded a scholarship at Alabama Agricultural and Mechanical University. He was a music education major, studying composition, orchestration, and music theory. He dropped out after a year.–32\nBlount left college because, he claimed, he had a visionary experience as a college student that had a major, long-term influence on him. In 1936 or 1937, in the midst of deep religious concentration, Sun Ra claimed that a bright light appeared around him, and, as he later said:\nMy whole body changed into something else. I could see through myself. And I went up...  I wasn''t in human form... I landed on a planet that I identified as Saturn... they teleported me and I was down on  stage with them. They wanted to talk with me. They had one little antenna on each ear. A little antenna over each eye. They talked to me. They told me to stop  because there was going to be great trouble in schools... the world was going into complete chaos... I would speak , and the world would listen. That''s what they told me.\nBlount claimed that this experience occurred in 1936 or 1937. According to Szwed, the musician''s closest associates cannot date the story any earlier than 1952. (Blount also said that the incident happened when he was living in Chicago, where he did not settle until the late 1940s). Sun Ra discussed the vision, with no substantive variation, to the end of his life. His trip to Saturn allegedly occurred a full decade before flying saucers entered public consciousness with the 1947 encounter of Kenneth Arnold. It was earlier than other public accounts: about 15 years before George Adamski wrote about contact with benevolent beings; and almost 20 years before the 1961 case of Barney and Betty Hill, who recounted sinister UFO abductions. Szwed says that, \"even if this story is revisionist autobiography... Sonny was pulling together several strains of his life. He was both prophesizing his future and explaining his past with a single act of personal mythology.\" Steingo emphasizes understanding Sun Ra''s statements about his life in relation to his music. Steingo writes: \"Rather than think of  music as a performance and then consider only the content of his spoken words, we might instead understand everything he did as part of the same project to listen otherwise.\"\nAfter leaving college, Blount became known as the most singularly devoted musician in Birmingham. He rarely slept, citing Thomas Edison, Leonardo da Vinci, and Napoleon as fellow highly productive cat-nappers. He transformed the first floor of his family''s home into a conservatory-workshop, where he wrote songs, transcribed recordings, rehearsed with the many musicians who drifted in and out, and discussed Biblical and esoteric concepts with whoever was interested.\nBlount became a regular at Birmingham''s Forbes Piano Company, a white-owned company. Blount visited the Forbes building almost daily to play music, swap ideas with staff and customers, or copy sheet music into his notebooks. He formed a new band, and like his old teacher Whatley, insisted on rigorous daily rehearsals. The new Sonny Blount Orchestra earned a reputation as an impressive, disciplined band that could play in a wide variety of styles with equal skill.\nIn October 1942, Blount received a selective service notification that he had been drafted into the Military of the United States. He quickly declared himself a conscientious objector, citing religious objections to war and killing, his financial support of his great-aunt Ida, and his chronic hernia. The local draft board rejected his claim. In an appeal to the national draft board, Blount wrote that the lack of black men on the draft appeal board \"smacks of Hitlerism.\" Sonny''s refusal to join the military deeply embarrassed his family, and many relatives ostracized him. He was eventually approved for alternate service at Civilian Public Service camp in Pennsylvania, but he did not appear at the camp as required on December 8, 1942. Shortly after, he was arrested in Alabama.\nIn court, Blount said that alternate service was unacceptable; he debated the judge on points of law and Biblical interpretation. The judge ruled that Blount was violating the law and was at risk for being drafted into the U.S. military. Blount responded that if inducted, he would use military weapons and training to kill the first high-ranking military officer possible. The judge sentenced Blount to jail (pending draft board and CPS rulings), and then said, \"I''ve never seen a nigger like you before.\" Blount replied, \"No, and you never will again.\"\nIn January 1943, Blount wrote to the United States Marshals Service from the Walker County, Alabama jail in Jasper. He said he was facing a nervous breakdown from the stress of imprisonment, that he was suicidal, and that he was in constant fear of sexual assault. When his conscientious objector status was reaffirmed in February 1943, he was escorted to Pennsylvania. He did forestry work as assigned during the day and was allowed to play piano at night. Psychiatrists there described him as \"a psychopathic personality  sexually perverted,\" but also as \"a well-educated colored intellectual.\"\nIn March 1943, the draft board reclassified Blount as 4-F because of his hernia, and he returned to Birmingham, embittered and angered. He formed a new band and soon was playing professionally. After his beloved great-aunt Ida died in 1945, Blount felt no reason to stay in Birmingham. He dissolved the band, and moved to Chicago—part of the Second Great Migration, southern African Americans who moved north during and after World War II.\nIn Chicago, Blount quickly found work, notably with blues singer Wynonie Harris, with whom he made his recording debut on two 1946 singles, Dig This Boogie/Lightning Struck the Poorhouse, and My Baby''s Barrelhouse/Drinking By Myself. Dig This Boogie was also Blount''s first recorded piano solo. He performed with the locally successful Lil Green band and played bump-and-grind music for months in Calumet City strip clubs.\nIn August 1946, Blount earned a lengthy engagement at the Club DeLisa under bandleader and composer Fletcher Henderson. Blount had long admired Henderson, but Henderson''s fortunes had declined (his band was now made of up middling musicians rather than the stars of earlier years) in large part because of his instability, due to Henderson''s long-term injuries from a car accident. Henderson hired Blount as pianist and arranger, replacing Marl Young. Blount''s arrangements initially showed a degree of bebop influence, but the band members resisted the new music, despite Henderson''s encouragement.\nIn 1948, Blount performed briefly in a trio with saxophonist Coleman Hawkins and violinist Stuff Smith, both preeminent musicians. There are no known recordings of this trio, but home recordings of two different Blount-Smith duets from 1953 appear on Sound Sun Pleasure!! and Deep Purple, and one of Sun Ra''s final recordings in 1992 was a rare sideman appearance on violinist Billy Bang''s Tribute to Stuff Smith.\nIn addition to enabling professional advancement, what he encountered in Chicago changed Blount''s personal outlook. The city was a center of African-American political activism and fringe movements, with Black Muslims, Black Hebrews, and others proselytizing, debating, and printing leaflets or books. Blount absorbed it all and was fascinated with the city''s many ancient Egyptian-styled buildings and monuments. He read books such as George G.M. James''s Stolen Legacy (which argued that classical Greek philosophy had its roots in ancient Egypt). Blount concluded that the accomplishments and history of Africans had been systematically suppressed and denied by European cultures.\nBy 1952, Blount was leading the Space Trio with drummer Tommy \"Bugs\" Hunter and saxophonist Pat Patrick, two of the most accomplished musicians he had known. They performed regularly, and Sun Ra began writing more advanced songs.\nOn October 20, 1952, Blount legally changed his name to Le Sony''r Ra. Sun Ra claimed to have always been uncomfortable with his birth name of Blount. He considered it a slave name, from a family that was not his. David Martinelli suggested that his change was similar to \"Malcolm X and Muhammad Ali...  their slave names in the process of attaining a new self-awareness and self-esteem\".\nPatrick left the group to move to Florida with his new wife. His friend John Gilmore (tenor sax) joined the group, and Marshall Allen (alto sax) soon followed. Patrick was in and out of the group until the end of his life, but Allen and Gilmore were the two most devoted members of the Arkestra. In fact, Gilmore is often criticized for staying with Sun Ra for over forty years when he could have been a strong leader in his own right. Saxophonist James Spaulding and trombonist Julian Priester also recorded with Sun Ra in Chicago, and both went on to careers of their own. The Chicago tenor Von Freeman also did a short stint with the band of the early 1950s.\nIn Chicago, Sun Ra met Alton Abraham, a precociously intelligent teenager and something of a kindred spirit. He became the Arkestra''s biggest booster and one of Sun Ra''s closest friends. Both men felt like outsiders and shared an interest in esoterica. Abraham''s strengths balanced Ra''s shortcomings: though he was a disciplined bandleader, Sun Ra was somewhat introverted and lacked business sense (a trait that haunted his entire career). Abraham was outgoing, well-connected, and practical. Though still a teenager, Abraham eventually became Sun Ra''s de facto business manager: he booked performances, suggested musicians for the Arkestra, and introduced several popular songs into the group''s repertoire. Ra, Abraham and others formed a sort of book club to trade ideas and discuss the offbeat topics that so intrigued them. This group printed a number of pamphlets and broadsides explaining their conclusions and ideas. Some of these were collected by critic John Corbett and Anthony Elms as The Wisdom of Sun Ra: Sun Ra''s Polemical Broadsheets and Streetcorner Leaflets (2006).\nIn the mid-1950s, Sun Ra and Abraham formed an independent record label that was generally known as El Saturn Records. (It had several name variations.) Initially focused on 45 rpm singles by Sun Ra and artists related to him, Saturn Records issued two full-length albums during the 1950s: Super-Sonic Jazz (1957) and Jazz in Silhouette (1959). Producer Tom Wilson was the first to release a Sun Ra album, through his independent label Transition Records in 1957, entitled Jazz by Sun Ra. During this era, Sun Ra recorded the first of dozens of singles as a band-for-hire backing a range of doo wop and R&B singers; several dozen of these were reissued in a two-CD set, The Singles, by Evidence Records.\nIn the late 1950s, Sun Ra and his band began to wear outlandish, Egyptian-styled or science fiction-themed costumes and headdresses. These costumes had multiple purposes: they expressed Sun Ra''s fascination with ancient Egypt and the space age, they provided a recognizable uniform for the Arkestra, they provided a new identity for the band onstage, and comic relief. (Sun Ra thought avant garde musicians typically took themselves far too seriously.)\nSun Ra and the Arkestra moved to New York City in the fall of 1961. To save money, Sun Ra and his band members lived communally. This enabled Sun Ra to request rehearsals spontaneously and at any time, which was his established habit. It was during this time in New York that Sun Ra recorded the album The Futuristic Sound of Sun Ra.\nIn March 1966, the Arkestra secured a regular Monday night gig at Slug''s Saloon. This was a breakthrough to new audiences and recognition. Sun Ra''s popularity reached an early peak during this period, as the beat generation and early followers of psychedelia embraced him. Regularly for the next year and a half (and intermittently for another half-decade afterwards), Sun Ra and company performed at Slug''s for audiences that eventually came to include music critics and leading jazz musicians. Opinions of Sun Ra''s music were divided (and hecklers were not uncommon).\nHigh praise, however, came from two of the architects of bebop. Trumpeter Dizzy Gillespie offered encouragement, once stating, \"Keep it up, Sonny, they tried to do the same shit to me,\" and pianist Thelonious Monk chided someone who said Sun Ra was \"too far out\" by responding: \"Yeah, but it swings.\"\nAlso in 1966, Sun Ra, with members of the Arkestra and Al Kooper''s Blues Project, recorded the album Batman and Robin under the pseudonym, The Sensational Guitars of Dan and Dale. The album consisted primarily of instrumental variations on the Batman Theme and public domain classical music, with an uncredited female vocalist singing the \"Robin Theme.\"\nIn 1968, when the New York building they were renting was put up for sale, Sun Ra and the Arkestra relocated to the Germantown section of Philadelphia. Sun Ra moved into a house on Morton Street that became the Arkestra''s base of operations until his death. It eventually became known as the Arkestral Institute of Sun Ra. Apart from occasional complaints about the noise of rehearsals, they were soon regarded as good neighbors because of their friendliness, drug-free living, and rapport with youngsters. The saxophonist Danny Ray Thompson owned and operated the Pharaoh''s Den, a convenience store in the neighborhood. When lightning struck a tree on their street, Sun Ra took it as a good omen. James Jacson fashioned the Cosmic Infinity Drum from the scorched tree trunk. They commuted via railroad to New York for the Monday night gig at Slug''s and for other engagements.\nSun Ra became a fixture in Philadelphia, appearing semi-regularly on WXPN radio, giving lectures to community groups, or visiting the city''s libraries. In the mid-1970s, the Arkestra sometimes played free Saturday afternoon concerts in a Germantown park near their home. At their mid-1970s shows in Philadelphia nightclubs, someone stood at the back of the room, selling stacks of unmarked LPs in plain white sleeves, pressed from recordings of the band''s live performances.\nSun Ra at the New England Conservatory of Music, February 27, 1992\nIn late 1968, Sun Ra and the Arkestra made their first tour of the US West Coast. Reactions were mixed. Some hippies accustomed to long-form psychedelia like the Grateful Dead were entranced and enthralled by the Arkestra, others merely bewildered. San Francisco was friendly to avant garde jazz from the early 50s and quickly welcomed Sun Ra''s music.  By this time, the performance included 20–30 musicians, dancers, singers, fire-eaters, and elaborate lighting. John Burks of Rolling Stone wrote a positive review of a San Jose State College concert. Sun Ra was featured on the April 19, 1969, cover of Rolling Stone magazine, which introduced his inscrutable gaze to millions. During this tour, Damon Choice, then an art student at San Jose, joined the Arkestra and became its vibraphonist.\nStarting with concerts in France, Germany, and the United Kingdom in 1970, the Arkestra began to tour internationally. They played to audiences who had known his music only through records. Sun Ra continued playing in Europe almost to the end of his life. The saxophonist Danny Ray Thompson became a de facto tour and business manager during this era, specializing in what he called \"no bullshit C.O.D.,\" preferring to take cash before performing or delivering records.\nIn early 1971, Sun Ra was appointed as artist-in-residence at University of California, Berkeley, teaching a course called The Black Man in the Cosmos. Few students enrolled, but his classes were often full of curious people from the surrounding community. One half-hour of each class was devoted to a lecture (complete with handouts and homework assignments), the other half-hour to an Arkestra performance or Sun Ra keyboard solo. Reading lists included the works of Madame Blavatsky and Henry Dumas, the Tibetan Book of the Dead, Alexander Hislop''s The Two Babylons, The Book of Oahspe, and assorted volumes concerning Egyptian hieroglyphs, African American folklore, and other topics.\nIn 1971, Sun Ra traveled throughout Egypt with the Arkestra at the invitation of the drummer Salah Ragab. He returned to Egypt in 1983 and 1984, when he recorded with Ragab. Recordings made in Egypt were released as Live in Egypt, Nidhamu, Sun Ra Meets Salah Ragab, Egypt Strut and Horizon.\nIn 1972, San Francisco public TV station KQED producer John Coney, producer Jim Newman, and screenwriter Joshua Smith worked with Sun Ra to produce an 85-minute feature film, entitled Space Is the Place, with Sun Ra''s Arkestra and an ensemble of actors assembled by the production team. It was filmed in Oakland and San Francisco. A 1975 show concert by the Arkestra in Cleveland featured an early lineup of Devo as the opening act. On May 20, 1978, Sun Ra and the Arkestra appeared on the TV show Saturday Night Live (S3 E20).\nIn New York City in the fall of 1979, Sun Ra and the Arkestra played as the \"house band\" at the Squat Theatre on 23rd Street, which was the performance venue of the avant-garde Hungarian theater troupe. Janos, their manager, transformed the theater into a nightclub while most of the troupe was away that season performing in Europe. Debbie Harry, The Velvet Underground''s John Cale and Nico (from Andy Warhol''s Factory days), John Lurie and The Lounge Lizards, and other pop and avant-garde musicians were regulars. Sun Ra was disciplined and drank only club soda at the gigs, but did not impose his strict code on his musicians. They respected his discipline and authority. Soft-spoken and charismatic, Sun Ra turned Squat Theater into a universe of big band \"space\" jazz backed by a floor show of sexy Jupiterettes. He directed while playing three synthesizers at the same time. In those days, \"Space Is The Place\" was the space at Squat.\nThe Arkestra continued their touring and recording through the 1980s and into the 1990s.\nSun Ra had a stroke in 1990, but kept composing, performing, and leading the Arkestra. Late in his career, he opened a few concerts for the New York–based rock group Sonic Youth. When too ill to perform and tour, Sun Ra appointed Gilmore to lead the Arkestra. Gilmore was frail from emphysema; after his death in 1995, Allen took over leadership of the Arkestra.\nIn late 1992, Sun Ra returned to his birth city of Birmingham to live with his older sister, Mary Jenkins, who (along with various Blount cousins) became his caretaker. In January, he was admitted to Princeton Baptist Medical Center, suffering from congestive heart failure, respiratory failure, strokes, circulatory problems, and other serious maladies. He died in the hospital on May 30, 1993, and was buried at the Elmwood Cemetery. The footstone reads \"Herman Sonny Blount aka Le Sony''r Ra\".","Early Life":"He was born Herman Blount on May 22, 1914, in Birmingham, Alabama, as discovered by his biographer, John F. Szwed, and published in his 1997 book, Space Is the Place: The Lives and Times of Sun Ra. He was named after the popular vaudeville stage magician Black Herman, who had deeply impressed his mother. He was nicknamed \"Sonny\" from his childhood, had an older sister and half-brother, and was doted upon by his mother and grandmother.\nFor decades, very little was known about Sun Ra''s early life, and he contributed to its mystique. As a self-invented person, he routinely gave evasive, contradictory or seemingly nonsensical answers to personal questions, and denied his birth name. He speculated, only half in jest, that he was distantly related to Elijah Poole, later known as Elijah Muhammad, leader of the Nation of Islam. His birthday for years remained unknown, as his claims ranged from 1910 to 1918. Only a few years before his death, the date of Sun Ra''s birth was still a mystery. Jim Macnie''s notes for Blue Delight (1989) said that Sun Ra was believed to be about 75 years old. This turned out to be correct; Szwed was able to uncover a wealth of information about his early life, and confirmed a birth date of May 22, 1914.\nAs a child, Blount was a skilled pianist. By the age of 11 or 12, he was composing and sight reading music. Birmingham was an important stop for touring musicians and he saw prominent musicians such as Fletcher Henderson, Duke Ellington, and Fats Waller, and other less well known performers. Sun Ra once said, \"The world let down a lot of good musicians\".\nIn his teenage years, Blount demonstrated prodigious musical talent: many times, according to acquaintances, he went to big band performances and then produced full transcriptions of the bands'' songs from memory. By his mid-teens, Blount was performing semi-professionally as a solo pianist, or as a member of various ad hoc jazz and R&B groups. He attended Birmingham''s segregated Industrial High School (now known as Parker High School), where he studied under music teacher John T. \"Fess\" Whatley, a demanding disciplinarian who was widely respected and whose classes produced many professional musicians.–22\nThough deeply religious, his family was not formally associated with any Christian church or sect. Blount had few or no close friends in high school but was remembered as kind-natured and quiet, an honor roll student, and a voracious reader. He took advantage of the Black Masonic Lodge as one of the few places in Birmingham where African Americans had unlimited access to books. Its collection on Freemasonry and other esoteric concepts made a strong impression on him.\nBy his teens, Blount suffered from cryptorchidism. It left him with a nearly constant discomfort that sometimes flared into severe pain. Szwed suggests that Blount felt shame about it and the condition contributed to his isolation.","Early Professional Career And College":"In 1934, Blount was offered his first full-time musical job by Ethel Harper, his biology teacher from the high school, who had organized a band to pursue a career as a singer. Blount joined a musicians'' trade union and toured with Harper''s group through the US Southeast and Midwest. When Harper left the group mid-tour to move to New York (she later was a member of the modestly successful singing group the Ginger Snaps), Blount took over leadership of the group, renaming it the Sonny Blount Orchestra. They continued touring for several months before dissolving as unprofitable.–26  Though the first edition of the Sonny Blount Orchestra was not financially successful, they earned positive notice from fans and other musicians. Blount afterward found steady employment as a musician in Birmingham.\nBirmingham clubs often featured exotic trappings, such as vivid lighting and murals with tropical or oasis scenes. Some believe these influenced the elements Sun Ra incorporated in his later stage shows. Playing for the big bands gave black musicians a sense of pride and togetherness, and they were highly regarded in the black community. They were expected to be disciplined and presentable, and in the segregated South, black musicians had wide acceptance in white society. They often played for elite white society audiences (though they were typically forbidden from associating with the audience).\nIn 1936, Whatley''s intercession led to Blount''s being awarded a scholarship at Alabama Agricultural and Mechanical University. He was a music education major, studying composition, orchestration, and music theory. He dropped out after a year.–32","New Devotion To Music (Late 1930S)":"After leaving college, Blount became known as the most singularly devoted musician in Birmingham. He rarely slept, citing Thomas Edison, Leonardo da Vinci, and Napoleon as fellow highly productive cat-nappers. He transformed the first floor of his family''s home into a conservatory-workshop, where he wrote songs, transcribed recordings, rehearsed with the many musicians who drifted in and out, and discussed Biblical and esoteric concepts with whoever was interested.\nBlount became a regular at Birmingham''s Forbes Piano Company, a white-owned company. Blount visited the Forbes building almost daily to play music, swap ideas with staff and customers, or copy sheet music into his notebooks. He formed a new band, and like his old teacher Whatley, insisted on rigorous daily rehearsals. The new Sonny Blount Orchestra earned a reputation as an impressive, disciplined band that could play in a wide variety of styles with equal skill.","Chicago Years (1945–1961)":"In Chicago, Blount quickly found work, notably with blues singer Wynonie Harris, with whom he made his recording debut on two 1946 singles, Dig This Boogie/Lightning Struck the Poorhouse, and My Baby''s Barrelhouse/Drinking By Myself. Dig This Boogie was also Blount''s first recorded piano solo. He performed with the locally successful Lil Green band and played bump-and-grind music for months in Calumet City strip clubs.\nIn August 1946, Blount earned a lengthy engagement at the Club DeLisa under bandleader and composer Fletcher Henderson. Blount had long admired Henderson, but Henderson''s fortunes had declined (his band was now made of up middling musicians rather than the stars of earlier years) in large part because of his instability, due to Henderson''s long-term injuries from a car accident. Henderson hired Blount as pianist and arranger, replacing Marl Young. Blount''s arrangements initially showed a degree of bebop influence, but the band members resisted the new music, despite Henderson''s encouragement.\nIn 1948, Blount performed briefly in a trio with saxophonist Coleman Hawkins and violinist Stuff Smith, both preeminent musicians. There are no known recordings of this trio, but home recordings of two different Blount-Smith duets from 1953 appear on Sound Sun Pleasure!! and Deep Purple, and one of Sun Ra''s final recordings in 1992 was a rare sideman appearance on violinist Billy Bang''s Tribute to Stuff Smith.\nIn addition to enabling professional advancement, what he encountered in Chicago changed Blount''s personal outlook. The city was a center of African-American political activism and fringe movements, with Black Muslims, Black Hebrews, and others proselytizing, debating, and printing leaflets or books. Blount absorbed it all and was fascinated with the city''s many ancient Egyptian-styled buildings and monuments. He read books such as George G.M. James''s Stolen Legacy (which argued that classical Greek philosophy had its roots in ancient Egypt). Blount concluded that the accomplishments and history of Africans had been systematically suppressed and denied by European cultures.\nBy 1952, Blount was leading the Space Trio with drummer Tommy \"Bugs\" Hunter and saxophonist Pat Patrick, two of the most accomplished musicians he had known. They performed regularly, and Sun Ra began writing more advanced songs.\nOn October 20, 1952, Blount legally changed his name to Le Sony''r Ra. Sun Ra claimed to have always been uncomfortable with his birth name of Blount. He considered it a slave name, from a family that was not his. David Martinelli suggested that his change was similar to \"Malcolm X and Muhammad Ali...  their slave names in the process of attaining a new self-awareness and self-esteem\".\nPatrick left the group to move to Florida with his new wife. His friend John Gilmore (tenor sax) joined the group, and Marshall Allen (alto sax) soon followed. Patrick was in and out of the group until the end of his life, but Allen and Gilmore were the two most devoted members of the Arkestra. In fact, Gilmore is often criticized for staying with Sun Ra for over forty years when he could have been a strong leader in his own right. Saxophonist James Spaulding and trombonist Julian Priester also recorded with Sun Ra in Chicago, and both went on to careers of their own. The Chicago tenor Von Freeman also did a short stint with the band of the early 1950s.\nIn Chicago, Sun Ra met Alton Abraham, a precociously intelligent teenager and something of a kindred spirit. He became the Arkestra''s biggest booster and one of Sun Ra''s closest friends. Both men felt like outsiders and shared an interest in esoterica. Abraham''s strengths balanced Ra''s shortcomings: though he was a disciplined bandleader, Sun Ra was somewhat introverted and lacked business sense (a trait that haunted his entire career). Abraham was outgoing, well-connected, and practical. Though still a teenager, Abraham eventually became Sun Ra''s de facto business manager: he booked performances, suggested musicians for the Arkestra, and introduced several popular songs into the group''s repertoire. Ra, Abraham and others formed a sort of book club to trade ideas and discuss the offbeat topics that so intrigued them. This group printed a number of pamphlets and broadsides explaining their conclusions and ideas. Some of these were collected by critic John Corbett and Anthony Elms as The Wisdom of Sun Ra: Sun Ra''s Polemical Broadsheets and Streetcorner Leaflets (2006).\nIn the mid-1950s, Sun Ra and Abraham formed an independent record label that was generally known as El Saturn Records. (It had several name variations.) Initially focused on 45 rpm singles by Sun Ra and artists related to him, Saturn Records issued two full-length albums during the 1950s: Super-Sonic Jazz (1957) and Jazz in Silhouette (1959). Producer Tom Wilson was the first to release a Sun Ra album, through his independent label Transition Records in 1957, entitled Jazz by Sun Ra. During this era, Sun Ra recorded the first of dozens of singles as a band-for-hire backing a range of doo wop and R&B singers; several dozen of these were reissued in a two-CD set, The Singles, by Evidence Records.\nIn the late 1950s, Sun Ra and his band began to wear outlandish, Egyptian-styled or science fiction-themed costumes and headdresses. These costumes had multiple purposes: they expressed Sun Ra''s fascination with ancient Egypt and the space age, they provided a recognizable uniform for the Arkestra, they provided a new identity for the band onstage, and comic relief. (Sun Ra thought avant garde musicians typically took themselves far too seriously.)","New York Years (1961–1968)":"Sun Ra and the Arkestra moved to New York City in the fall of 1961. To save money, Sun Ra and his band members lived communally. This enabled Sun Ra to request rehearsals spontaneously and at any time, which was his established habit. It was during this time in New York that Sun Ra recorded the album The Futuristic Sound of Sun Ra.\nIn March 1966, the Arkestra secured a regular Monday night gig at Slug''s Saloon. This was a breakthrough to new audiences and recognition. Sun Ra''s popularity reached an early peak during this period, as the beat generation and early followers of psychedelia embraced him. Regularly for the next year and a half (and intermittently for another half-decade afterwards), Sun Ra and company performed at Slug''s for audiences that eventually came to include music critics and leading jazz musicians. Opinions of Sun Ra''s music were divided (and hecklers were not uncommon).\nHigh praise, however, came from two of the architects of bebop. Trumpeter Dizzy Gillespie offered encouragement, once stating, \"Keep it up, Sonny, they tried to do the same shit to me,\" and pianist Thelonious Monk chided someone who said Sun Ra was \"too far out\" by responding: \"Yeah, but it swings.\"\nAlso in 1966, Sun Ra, with members of the Arkestra and Al Kooper''s Blues Project, recorded the album Batman and Robin under the pseudonym, The Sensational Guitars of Dan and Dale. The album consisted primarily of instrumental variations on the Batman Theme and public domain classical music, with an uncredited female vocalist singing the \"Robin Theme.\"","Philadelphia Years (1968)":"In 1968, when the New York building they were renting was put up for sale, Sun Ra and the Arkestra relocated to the Germantown section of Philadelphia. Sun Ra moved into a house on Morton Street that became the Arkestra''s base of operations until his death. It eventually became known as the Arkestral Institute of Sun Ra. Apart from occasional complaints about the noise of rehearsals, they were soon regarded as good neighbors because of their friendliness, drug-free living, and rapport with youngsters. The saxophonist Danny Ray Thompson owned and operated the Pharaoh''s Den, a convenience store in the neighborhood. When lightning struck a tree on their street, Sun Ra took it as a good omen. James Jacson fashioned the Cosmic Infinity Drum from the scorched tree trunk. They commuted via railroad to New York for the Monday night gig at Slug''s and for other engagements.\nSun Ra became a fixture in Philadelphia, appearing semi-regularly on WXPN radio, giving lectures to community groups, or visiting the city''s libraries. In the mid-1970s, the Arkestra sometimes played free Saturday afternoon concerts in a Germantown park near their home. At their mid-1970s shows in Philadelphia nightclubs, someone stood at the back of the room, selling stacks of unmarked LPs in plain white sleeves, pressed from recordings of the band''s live performances.","Music":"Sun Ra''s piano technique touched on many styles: his youthful fascination with boogie woogie, stride piano and blues, a sometimes refined touch reminiscent of Count Basie or Ahmad Jamal, and angular phrases in the style of Thelonious Monk or brutal, percussive attacks like Cecil Taylor. Often overlooked is the range of influences from classical music – Sun Ra cited Chopin, Rachmaninoff, Schoenberg and Shostakovich as his favorite composers for the piano.\nSun Ra''s music can be roughly divided into three phases, but his records and performances were full of surprises and the following categories should be regarded only as approximations.\nThe first period occurred in the 1950s when Sun Ra''s music evolved from big band swing into the outer-space-themed \"cosmic jazz\" for which he was best known. Music critics and jazz historians say some of his best work was recorded during this period and it is also some of his most accessible music. Sun Ra''s music in this era was often tightly arranged and sometimes reminiscent of Duke Ellington''s, Count Basie''s, or other important swing music ensembles. However, there was a strong influence from post-swing styles like bebop, hard bop, and modal jazz, and touches of the exotic and hints of the experimentalism that dominated his later music. Notable Sun Ra albums from the 1950s include Sun Ra Visits Planet Earth, Interstellar Low Ways, Super-Sonic Jazz, We Travel the Space Ways, The Nubians of Plutonia and Jazz in Silhouette.\nRonnie Boykins, Sun Ra''s bassist, has been described as \"the pivot around which much of Sun Ra''s music revolved for eight years.\" This is especially pronounced on the key recordings from 1965 (The Magic City, The Heliocentric Worlds of Sun Ra, Volume One, and The Heliocentric Worlds of Sun Ra, Volume Two) where the intertwining lines of Boykins'' bass and Ra''s electronic keyboards provide cohesion.\nAfter the move to New York, Sun Ra and company plunged headlong into the experimentalism that they had only hinted at in Chicago. The music was often extremely loud and the Arkestra grew to include multiple drummers and percussionists. In recordings of this era, Ra began to use new technologies—such as extensive use of tape delay—to assemble spatial sound pieces, such as \"Saturn\", which were far removed from earlier compositions. Recordings and live performances often featured passages for unusual instrumental combinations, and passages of collective playing that incorporated free improvisation. It is often difficult to tell where compositions end and improvisations begin.\nIn this era, Sun Ra began conducting using hand and body gestures. This system inspired cornetist Butch Morris, who later developed his own more highly refined way to conduct improvisers.\nThough often associated with avant-garde jazz, Sun Ra did not believe his work could be classified as \"free music\": \"I have to make sure that every note, every nuance, is correct... If you want to call it that, spell it p-h-r-e, because ph is a definite article and re is the name of the sun. So I play phre music – music of the sun.\"\nSeeking to broaden his compositional possibilities, Sun Ra insisted all band members double on various percussion instruments – predating world music by drawing on various ethnic musical forms – and most saxophonists became multireedists, adding instruments such as flutes, oboes, or clarinets to their arsenals. In this era, Sun Ra was among the first of any musicians to make extensive and pioneering use of synthesizers and other various electronic keyboards; he was given a prototype Minimoog by its inventor, Robert Moog. According to the Bob Moog Foundation: \"Sun Ra first met Robert Moog after Downbeat journalist and Sun Ra acquaintance Tam Fiofori arranged for a visit to Moog’s factory in Trumansburg in the Fall of 1969....it was during this visit that Moog loaned Sun Ra a prototype Minimoog (Model B), several months before the commercial instrument (Model D) was introduced in March 1970. Ra immediately added the instrument to his repertoire of keyboards, later acquired a second, and featured the Minimoog prominently on many of his recordings of the early 1970s.\"\nNotable titles from this period include The Magic City, Cosmic Tones for Mental Therapy, When Sun Comes Out, The Heliocentric Worlds of Sun Ra, Volume One, Atlantis, Secrets of the Sun and Other Planes of There.\nDuring their third period, beginning around 1976, Sun Ra and the Arkestra settled down into a relatively conventional sound, often incorporating swing standards, although their records and concerts were still highly eclectic and energetic, and typically included at least one lengthy, semi-improvised percussion jam. Sun Ra was explicitly asserting a continuity with the ignored jazz tradition: \"They tried to fool you, now I got to school you, about jazz, about jazz\" he chanted in concerts, framing the inclusion of pieces by Fletcher Henderson and Jelly Roll Morton.\nIn the 1970s Sun Ra took a liking to the films of Walt Disney. He incorporated smatterings of Disney musical numbers into many of his performances from then on. In the late 1980s the Arkestra performed a concert at Walt Disney World. The Arkestra''s version of \"Pink Elephants on Parade\" is available on Stay Awake, a tribute album of Disney tunes played by various artists and produced by Hal Willner. A number of Sun Ra''s 1970s concerts are available on CD, but none have received a wide release in comparison to his earlier music. In 1978–1980 performances, Sun Ra added a large electronic creation, the Outerspace Visual Communicator, which produced images rather than sounds; this was performed at a keyboard by its inventor, Bill Sebastian. During concerts, the OVC usually was positioned at center stage behind the Arkestra while Sebastian sat on stage with the musicians.\nDozens of musicians—perhaps hundreds—passed through Sun Ra''s bands over the years. Some stayed with him for decades, whilst others played on only a few recordings or performances.\nSun Ra was personally responsible for the vast majority of the constant changes in the Arkestra''s lineup. According to contrabassist Jiunie Booth, a member of the Arkestra, Sun Ra did not confront any musician whose performance he was unsatisfied with. Instead, he would simply gather the entire Arkestra minus the offending musician, and skip town—leaving the fired musician stranded.\nThe following is a partial list of musical collaborators, and the eras when they played with Sun Ra or the Arkestra:\nYahya Abdul-Majid, tenor saxophone (1980–2020)\nLuqman Ali (Edward Skinner), drums (1960, 1977–?)\nMarshall Allen, alto saxophone, flute, oboe (1957–present)\nAtakatune (Stanley Morgan), percussion (1972–1992)\nAyé Aton (Robert Underwood), drums and percussion (1972–1976)\nOwen \"Fiidla\" Brown, violin, dance, vocals (1987–1990s and later appearances)\nFrancisco Mora Catlett, drums (1973–1980)\nSamarai Celestial (Eric Walker), drums (1979–1997)\nVincent Chancey, French horn (1976–1995)\nDanny Davis, alto saxophone, flute (1962–1977, 1985)\nJoey DeStefano, alto saxophone (1968–1969)\nJohn Gilmore, tenor saxophone, bass clarinet (1954–1964, 1965–1995)\nKwame Hadi (Lamont McClamb), trumpet, conga, vibraphone (1969–1996)\nTommy \"Bugs\" Hunter, drums, sound engineer (1951–1990)\nJames Jacson, bassoon, oboe, flute, Ancient Egyptian infinity drum (1963–1997)\nClifford Jarvis, drums, (1961–1976, 1983)\nArt Jenkins, vocals (1960–1971, 1988–2012)\nDr. VonFiend (musician), various instruments, effects (2006–2009)\nElson Nascimento, percussion, vocals (1987–present)\nPat Patrick, baritone saxophone, alto saxophone, clarinet, flute (1950–1959, 1961–1977, 1985–1988)\nJulian Priester, trombone (1955–1956, 1980s–1990s)\nKnoel Scott, alto saxophone, tenor saxophone, baritone saxophone, singer and dancer (1979–present)\nBill Sebastian, outerspace visual communicator (1978–1980)\nAlan Silva, double bass, cello, violin (early 1970s)\nDanny Ray Thompson, baritone saxophone (1967–1995, 2002–2020)\nThe Outer Space Visual Communicator was a giant machine that was played with hands and feet to create light designs, similar to how musicians create and sound with their instruments. The name of the instrument arose from Bill Sebastian''s collaboration with Sun Ra, who incorporated the OVC into the Arkestra from 1978 to 1980 and experimented on video applications from 1981 to 1987.","Musicians":"Dozens of musicians—perhaps hundreds—passed through Sun Ra''s bands over the years. Some stayed with him for decades, whilst others played on only a few recordings or performances.\nSun Ra was personally responsible for the vast majority of the constant changes in the Arkestra''s lineup. According to contrabassist Jiunie Booth, a member of the Arkestra, Sun Ra did not confront any musician whose performance he was unsatisfied with. Instead, he would simply gather the entire Arkestra minus the offending musician, and skip town—leaving the fired musician stranded.\nThe following is a partial list of musical collaborators, and the eras when they played with Sun Ra or the Arkestra:\nYahya Abdul-Majid, tenor saxophone (1980–2020)\nLuqman Ali (Edward Skinner), drums (1960, 1977–?)\nMarshall Allen, alto saxophone, flute, oboe (1957–present)\nAtakatune (Stanley Morgan), percussion (1972–1992)\nAyé Aton (Robert Underwood), drums and percussion (1972–1976)\nOwen \"Fiidla\" Brown, violin, dance, vocals (1987–1990s and later appearances)\nFrancisco Mora Catlett, drums (1973–1980)\nSamarai Celestial (Eric Walker), drums (1979–1997)\nVincent Chancey, French horn (1976–1995)\nDanny Davis, alto saxophone, flute (1962–1977, 1985)\nJoey DeStefano, alto saxophone (1968–1969)\nJohn Gilmore, tenor saxophone, bass clarinet (1954–1964, 1965–1995)\nKwame Hadi (Lamont McClamb), trumpet, conga, vibraphone (1969–1996)\nTommy \"Bugs\" Hunter, drums, sound engineer (1951–1990)\nJames Jacson, bassoon, oboe, flute, Ancient Egyptian infinity drum (1963–1997)\nClifford Jarvis, drums, (1961–1976, 1983)\nArt Jenkins, vocals (1960–1971, 1988–2012)\nDr. VonFiend (musician), various instruments, effects (2006–2009)\nElson Nascimento, percussion, vocals (1987–present)\nPat Patrick, baritone saxophone, alto saxophone, clarinet, flute (1950–1959, 1961–1977, 1985–1988)\nJulian Priester, trombone (1955–1956, 1980s–1990s)\nKnoel Scott, alto saxophone, tenor saxophone, baritone saxophone, singer and dancer (1979–present)\nBill Sebastian, outerspace visual communicator (1978–1980)\nAlan Silva, double bass, cello, violin (early 1970s)\nDanny Ray Thompson, baritone saxophone (1967–1995, 2002–2020)","Death":"Sun Ra had a stroke in 1990, but kept composing, performing, and leading the Arkestra. Late in his career, he opened a few concerts for the New York–based rock group Sonic Youth. When too ill to perform and tour, Sun Ra appointed Gilmore to lead the Arkestra. Gilmore was frail from emphysema; after his death in 1995, Allen took over leadership of the Arkestra.\nIn late 1992, Sun Ra returned to his birth city of Birmingham to live with his older sister, Mary Jenkins, who (along with various Blount cousins) became his caretaker. In January, he was admitted to Princeton Baptist Medical Center, suffering from congestive heart failure, respiratory failure, strokes, circulatory problems, and other serious maladies. He died in the hospital on May 30, 1993, and was buried at the Elmwood Cemetery. The footstone reads \"Herman Sonny Blount aka Le Sony''r Ra\".","Influence And Legacy":"Many of Sun Ra''s innovations remain important and groundbreaking. Ra was one of the first jazz leaders to use two double basses, to employ the electric bass, to play electronic keyboards, to use extensive percussion and polyrhythms, to explore modal music and to pioneer solo and group freeform improvisations. In addition, he made his mark in the wider cultural context: he proclaimed the African origins of jazz, reaffirmed pride in black history and reasserted the spiritual and mystical dimensions of music, all important factors in the black cultural/political renaissance of the 1960s.\nNRBQ recorded \"Rocket #9\" in 1968 for their debut album on Columbia. Sun Ra had given NRBQ''s Terry Adams a copy of the song on 45 and told him, \"This is especially for you,\" which Adams reported inspired him to reform the band after a period of inactivity. The band still includes Sun Ra''s compositions in their performances, and besides \"Rocket #9\" have released recordings of \"We Travel the Spaceways\" and \"Love in Outer Space.\" Several members of the Arkestra have toured with NRBQ over the years, including Pat Patrick, Marshall Allen, Knoel Scott, Tyrone Hill and Danny Thompson. Adams has joined the Arkestra as their pianist on several tours, most recently during a February 2016 tour of cities in the US southeast.\nDetroit''s MC5 played a handful of shows with Sun Ra and were influenced by his works immensely. One of their songs from their premiere album Kick Out the Jams (1969) featured a track called \"Starship\", which was based on a poem by Ra.\nSun Ra was inducted into the Alabama Jazz Hall of Fame in 1979.\nThe Sun Ra Repatriation Project was started in 2008 with the aim of using interplanetary communication with a view to facilitating Sun Ra''s return to planet Earth.\nFilmmaker and visual artist Cauleen Smith has heavily researched the life and legacy of Sun Ra. Her 2013 exhibition \"17\" \"arises out of  research into the legacy of Sun Ra, who was himself a student of numerology and achieved a kind of cultural immortality the number 17 might be said to refer to\". Her project \"The Solar Flare Arkestral Marching Band\" includes several components related to Sun Ra. \"One component (2010) of the project is the production of five flash mob street performances involving a marching band inspired by Sun Ra''s Arkestra. The second component of the project ... is a full-length video that chronicles the urban legends of Sun Ra’s time in Chicago as well as the contemporary artists who live and work in this city\".\nThe \"Sun Ra Revival Post-Krautrock Archestra\", formed in Australia during 2014, paid tribute to Sun Ra''s philosophies and musical ideas within their albums Realm Beyond Realm and Sun Ra Kills the World.\nThe Spatial AKA Orchestra, formed in 2006 by Jerry Dammers (the main songwriter of British ska revival band The Specials), was originally created as a tribute to Sun Ra, borrowing many of the ideas, themes and tropes from Sun Ra''s own performances.\nIn 2022, a building at 5626 Morton Street known as the Arkestral Institute of Sun Ra was listed as a historic landmark in the Philadelphia Register of Historic Places. One of its inhabitants, Marshall Allen, known for his work with The Sun Ra Arkestra, began living there in 1968.\nThe University of Chicago has an extensive collection of Sun Ra''s works and personal items in the Special Collections Research Center at the Regenstein Library. The collection was assembled by Ra''s business manager Alton Abraham and is open to the public upon request. The Special Collections Research Center has also repeatedly exhibited Sun Ra''s work."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (300, '1WmIo9ORq1IDlovUWFmo4Y', 'Sunny', 'Murray', '3870c548-7743-4a14-b9c5-4327e964e729', 253093, 4, 'https://en.wikipedia.org/wiki/Sunny_Murray', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Sunny_Murray.jpg/500px-Sunny_Murray.jpg', 'Andy Newcombe Farnborough, UK', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Sunny_Murray.jpg', '{"Intro":"James Marcellus Arthur \"Sunny\" Murray (September 21, 1936 – December 7, 2017) was an American musician, and was one of the pioneers of the free jazz style of drumming.","Biography":"Murray was born in Idabel, Oklahoma, where he was raised by an uncle who later died after being refused treatment at a hospital because of his race. He began playing drums at the age of nine. As a teen, he lived in a rough part of Philadelphia, and spent two years in a reformatory. In 1956, he moved to New York City, where he worked in a car wash and as a building superintendent. During this time, he played with musicians such as trumpeters Red Allen and Ted Curson, pianist Willie \"The Lion\" Smith, and saxophonists Rocky Boyd and Jackie McLean.\nIn 1959, he played for the first time with pianist Cecil Taylor and, according to Murray, \"or six years all the other things were wiped from my mind...\" \"With Cecil, I had to originate a complete new direction on drums.\" Murray stated: \"We played for about a year, just practicing, studying — we went to workshops with Varèse, did a lot of creative things, just experimenting, without a job.\" In 1961, Murray made a recording with Taylor''s group that was released under the auspices of Gil Evans as one side of Into the Hot.\nIn 1962, Murray went to Europe for the first time with Taylor and saxophonist Jimmy Lyons. (Bassist Henry Grimes was supposed to join them, but fell ill at the last moment.) During that time, the group made a stylistic breakthrough; Murray stated: \"We were in Sweden and we had finally decided to be free... The way Cecil and Jimmy and I were playing, we could absorb any different thing at that period, because we were so fresh!\" While in Denmark later that year, the trio recorded the influential concerts released as Nefertiti the Beautiful One Has Come.\nThat same year, while in Sweden with Taylor, Murray met saxophonist Albert Ayler. (According to Murray, after hearing Taylor''s group perform, Ayler approached them and said \"I''ve been waiting for you, man. You''re the guys I''ve been waiting for.\" He also recalled that Taylor \"jumped half out of his chair\" the first time Ayler played with the group.) With Ayler, the group recorded together for Danish television as the Cecil Taylor Unit (the track \"Four,\" featured on the Ayler box set Holy Ghost, was recorded during this time), and, upon returning to the United States, the group (with Ayler) performed at the Take Three club in Greenwich Village and at Philharmonic Hall, Lincoln Center in New York City on December 31, 1963, as the Cecil Taylor Jazz Unit, with Grimes back on bass. (The concert also featured Art Blakey and The Jazz Messengers and the John Coltrane Quintet featuring Eric Dolphy.) Murray stated that Ayler \"didn''t know New York from a can of beans. So, he came over to my house, and I took him to meet Archie (Shepp) and all the cats.\" Murray continued to play with Ayler, and went on to join Ayler''s trio with bassist Gary Peacock. Murray recorded a number of albums with Ayler, including the historic Spiritual Unity. Val Wilmer wrote that Murray was \"one of those crucial figures in jazz who appear just at the time they are needed. His unchained approach to percussion gave Ayler the freedom to travel his own road that had hitherto been lacking.\" Murray also stated that he played with John Coltrane in 1964, and was offered a spot in Coltrane''s band, but turned it down.\nMurray went on to record his own compositions under his own name, beginning in 1965 with Sonny''s Time Now, which was released on Leroi Jones''s Jihad label. The album features Ayler, Don Cherry, Henry Grimes, and Lewis Worrell, as well as Jones, who recites his poem \"Black Art\". (Murray stated \"It’s a strange record because Albert and Don  are playing like this .\") Later, when he moved to Europe, he released three recordings on BYG Actuel. In addition, he continued to play and record as a sideman for a variety of musicians. In 1980, he reunited with Cecil Taylor for the recording of It Is in the Brewing Luminous, and in 1996, he recorded with Taylor again, resulting in the album Corona, released in 2018. He died on December 7, 2017, from multiple organ failure at the age of 81.\nA documentary on Murray, entitled Sunny''s Time Now: A Portrait of Jazz Drummer Sunny Murray, was released on DVD in 2008 by director Antoine Prum."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (301, '1WmIo9ORq1IDlovUWFmo4Y', 'Tadd', 'Dameron', '52763c17-465b-48e9-9e2b-3345ea8ba761', 251783, 3, 'https://en.wikipedia.org/wiki/Tadd_Dameron', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Tadd_Dameron%2C_ca._1946-1948.jpg/500px-Tadd_Dameron%2C_ca._1946-1948.jpg', 'William P. Gottlieb', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Tadd_Dameron,_ca._1946-1948.jpg', '{"Intro":"Tadley Ewing Peake Dameron (February 21, 1917 – March 8, 1965) was an American jazz composer, arranger, and pianist.","Biography":"Dameron, Mary Lou Williams, and Dizzy Gillespie in Williams''s apartment, c. June 1946 Photograph by William P. Gottlieb.\nBorn in Cleveland, Ohio, United States, Dameron was the most influential arranger of the bebop era, but also wrote charts for swing and hard bop players. The bands he arranged for included those of Count Basie, Artie Shaw, Jimmie Lunceford, Dizzy Gillespie, Billy Eckstine, and Sarah Vaughan. In 1940–41, Dameron was the piano player and arranger for the Kansas City band Harlan Leonard and his Rockets. He and lyricist Carl Sigman wrote \"If You Could See Me Now\" for Sarah Vaughan and it became one of her first signature songs. According to the composer, his greatest influences were George Gershwin and Duke Ellington.\nIn the late 1940s, Dameron wrote arrangements for the big band of Dizzy Gillespie, who gave the première of his large-scale orchestral piece Soulphony in Three Hearts at Carnegie Hall in 1948. Also in 1948, Dameron led his own group in New York, which included Fats Navarro; the following year, Dameron was at the Paris Jazz Festival with Miles Davis. From 1961, Dameron scored for recordings by Milt Jackson, Sonny Stitt, and Blue Mitchell.\nDameron additionally arranged and played for rhythm and blues musician Bull Moose Jackson. Playing for Jackson at that same time was Benny Golson, who went on to become a jazz composer in his own right. Golson said that Dameron was the most important influence on his writing.\nDameron composed several bop and swing standards, including \"Hot House\", \"If You Could See Me Now\", \"Our Delight\", \"Good Bait\" (composed for Count Basie) and \"Lady Bird\". Dameron''s bands from the late 1940s and early 1950s featured leading players such as Fats Navarro, Miles Davis, Dexter Gordon, Sonny Rollins, Wardell Gray, and Clifford Brown. In 1956, Dameron led two sessions based on his compositions, released as the 1956 album Fontainebleau and the 1957 album Mating Call, the latter featuring John Coltrane.\nDameron developed an addiction to narcotics toward the end of his career. He was arrested on drug charges in 1957 and 1958, and served time (1959–60) in a federal prison hospital in Lexington, Kentucky. After his release, Dameron recorded a single notable project as a leader, The Magic Touch (1962), but was sidelined by health problems; he had several heart attacks before dying of cancer in 1965, at the age of 48. He was buried at Ferncliff Cemetery in Hartsdale, New York."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (302, '1WmIo9ORq1IDlovUWFmo4Y', 'Tal', 'Farlow', '177e3c4c-fb44-4981-bbe6-9b34d9c53bfd', 339515, 2, 'https://en.wikipedia.org/wiki/Tal_Farlow', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Tal_Farlow_5.jpg/500px-Tal_Farlow_5.jpg', 'Vernon Hyde', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Tal_Farlow_5.jpg', '{"Intro":"Talmage Holt Farlow (June 7, 1921 – July 25, 1998) was an American jazz guitarist. He was nicknamed \"Octopus\" because of how his large, quick hands spread over the fretboard.","Early Life And Education":"Talmage Holt Farlow was born in Greensboro, North Carolina. He taught himself how to play guitar, which he started when he was 22 years old. He learned chord melodies by playing a mandolin tuned like a ukulele. He said playing the ukulele was the reason he used the higher four strings on the guitar for the melody and chord structure, with the two bottom strings for bass counterpoint, which he played with his thumb. His only professional training was as an apprentice sign painter. He requested the night shift so he could listen to big band standards on the shop radio. He listened to Bix Beiderbecke, Louis Armstrong, and Eddie Lang.","Career":"Farlow''s career was inspired by hearing Charlie Christian playing electric guitar with the Benny Goodman band. He stated he made his own electric guitar because he could not afford to purchase one.\nFarlow employed artificial harmonics and tapped his guitar for percussion, creating a flat, snare drum sound or a hollow backbeat like the bongos. His large, quick hands earned him the nickname \"The Octopus\".\nTal Farlow at Keystone Korner, San Francisco, playing with Red Norvo, July 28, 1981\nHe caught the public''s attention in 1949 when he was in a trio with Red Norvo and Charles Mingus. In 1953, he was a member of the Gramercy Five led by Artie Shaw, and two years later he led his own trio with Vinnie Burke and Eddie Costa in New York City. After getting married in 1958, he partially retired and settled in Sea Bright, New Jersey, returning to a career as a sign painter. He continued to play occasional dates in local clubs. In 1962 the Gibson Guitar Corporation, with Farlow''s participation, produced the \"Tal Farlow\" model. In 1976, Farlow started recording again. A documentary about him was released in 1981.\nLater in his career, Farlow performed as a member of Great Guitars with a DVD released in 2005 after his death.\nFarlow died of esophageal cancer at Memorial Sloan-Kettering Cancer Center in New York City on July 25, 1998, at the age of 77.","Music":"Farlow''s career was inspired by hearing Charlie Christian playing electric guitar with the Benny Goodman band. He stated he made his own electric guitar because he could not afford to purchase one.\nFarlow employed artificial harmonics and tapped his guitar for percussion, creating a flat, snare drum sound or a hollow backbeat like the bongos. His large, quick hands earned him the nickname \"The Octopus\".\nTal Farlow at Keystone Korner, San Francisco, playing with Red Norvo, July 28, 1981\nHe caught the public''s attention in 1949 when he was in a trio with Red Norvo and Charles Mingus. In 1953, he was a member of the Gramercy Five led by Artie Shaw, and two years later he led his own trio with Vinnie Burke and Eddie Costa in New York City. After getting married in 1958, he partially retired and settled in Sea Bright, New Jersey, returning to a career as a sign painter. He continued to play occasional dates in local clubs. In 1962 the Gibson Guitar Corporation, with Farlow''s participation, produced the \"Tal Farlow\" model. In 1976, Farlow started recording again. A documentary about him was released in 1981.","Later Career And Death":"Later in his career, Farlow performed as a member of Great Guitars with a DVD released in 2005 after his death.\nFarlow died of esophageal cancer at Memorial Sloan-Kettering Cancer Center in New York City on July 25, 1998, at the age of 77."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (303, '1WmIo9ORq1IDlovUWFmo4Y', 'Ted', 'Greene', 'ad740587-d7b0-43ac-85e4-a6213f380fdc', 532585, 2, 'https://en.wikipedia.org/wiki/Ted_Greene', NULL, NULL, NULL, NULL, '{"Intro":"Theodore Greene (September 26, 1946 – July 23, 2005) was an American fingerstyle guitarist, columnist, session musician and educator based in Encino, California.","Career":"Greene began his own guitar studies at the age of 11, and was an accomplished player while still in high school, occasionally collaborating with local rock and R&B bands. He briefly studied accounting at California State University, Northridge, but dropped out to devote more time to music.\nIn the 1960s he was a member of the rock band Natural Selection and a blues rock group called Bluesberry Jam, which included  future Canned Heat drummer Fito de la Parra. He was a friend and collaborator with Joseph Byrd, on whose Columbia Masterworks album The American Metaphysical Circus he was featured (he also provided the whimsical name of the studio band who performed it, \"The Field Hippies\"). During the late 1960s and early 1970s he did commercial studio work with Byrd. He was again called on in 1977 to provide guitar tablature for three arrangements of Bix Beiderbecke''s piano music for the Ry Cooder album Jazz, which Byrd arranged and produced.\nAlthough Greene is often regarded as a jazz musician, he played many musical styles. He was widely known for his personalized teaching approach, offering thousands of one-on-one lessons throughout his career. He created highly detailed handwritten notes for each student, covering topics such as chord melody, voice leading, and adapting keyboard harmony for guitar. Greene encouraged students to focus more on harmonic and inner voice leadings rather than solely relying on scale patterns. His accumulation of notes, transcriptions, and analyses were later digitized and made available online as the Ted Greene Archives. He also provided seminars at the Guitar Institute of Technology, columns for Guitar Player magazine, and his instructional books on harmony, chord melody, and single-note soloing. A voracious reader of almost any book on music theory, especially from the common practice period (circa 1600–1900) he distilled complex concepts regarding the structure of western music and would write out more accessible versions for students to understand (handed out to students in the form of lesson \"sheets\"), often applying keyboard concepts to the guitar. For example, many transcriptions of the chorales of J. S. Bach would be re-written for guitar with useful analysis applicable to any musical setting.\nHe would also make occasional live appearances at clubs in the San Fernando Valley, usually playing a Fender Telecaster.\nGreene typically worked as a vocal accompanist, which he preferred because he found group settings restrictive. While he was a sought-after session musician, he derived much of his income from tutoring. He wrote several influential books on the subject of jazz guitar performance and theory: Chord Chemistry, Modern Chord Progressions: Jazz and Classical Voicings for Guitar, and the two-volume Jazz Guitar: Single Note Soloing. Published in 1971, Chord Chemistry  became widely regarded as a foundational jazz guitar harmony known for its complex catalog of chord voicings.\nHis playing style included techniques such as harp-like arpeggios combined with gentle, tasteful neck vibrato, creating a \"shimmer\" to his sound. Other notable techniques included playing songs with a walking bass line with simultaneous melodies. Greene used counterpoint to improvise in a variety of styles, playing, for instance, a jazz standard such as Autumn Leaves in Baroque style. He used a large variety of chord voicings, often creating the effect of two simultaneous players.\nGreene recorded one album, Solo Guitar, which was produced by William Perry and Leon White, and released in 1977 on PMP Records. The album contains no overdubbing (recording on multiple tracks).\nAlthough not widely known to the general public, Greene was highly respected among professional guitarists. Guitarist Steve Vai has praised Greene''s musical knowledge and perceptiveness on Solo Guitar, stating that Greene \"is totally in touch with the potential of harmonic constructions\" which allows him to create an \"organic and inspired listening delight.\" In a 1982 discussion with Robert Fripp, John McLaughlin described Greene as \"really unbelievable\", noting that \"it''s so difficult to move around on a guitar in the harmonic way one can do on a keyboard...He''s the only guitar player who accomplishes this thing that really turns me on.\"\nTed Greene: Sound, Time, and Unlimited Possibility, by guitarist Terrence McManus, published in 2015, is the most complete analysis of Greene''s work that exists.\nGreene helped Fender design a 1952 Telecaster vintage reissue (their first such reissue) by making reference to his collection of old Telecasters, Esquires, Broadcasters and Nocasters.\nGreene died in his Encino apartment of a heart attack on July 23, 2005, at age 58. In 2009 Barbara Franklin wrote the biography My Life with The Chord Chemist: A Memoir of Ted Greene, Apotheosis of Solo Guitar. She died on August 13, 2011."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (304, '1WmIo9ORq1IDlovUWFmo4Y', 'Teodross', 'Avery', '62b448fa-939a-49dc-9c79-efc597a8670d', 206780, 6, 'https://en.wikipedia.org/wiki/Teodross_Avery', NULL, NULL, NULL, NULL, '{"Intro":"Teodross Avery (born July 2, 1973) is an American jazz tenor saxophonist, who has released albums for the record labels including GRP Records and Impulse! Records.\nA native of the San Francisco Bay Area, his 2019 album, After the Rain: A Night for Coltrane, was released on Tompkins Square Records in May that year. Harlem Stories: The Music of Thelonious Monk followed in September 2020."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (305, '1WmIo9ORq1IDlovUWFmo4Y', 'Terence', 'Blanchard', 'f21be110-0169-45f5-b5e7-c64a71d218e5', 272499, 7, 'https://en.wikipedia.org/wiki/Terence_Blanchard', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Terence_Blanchard_performing.jpg/500px-Terence_Blanchard_performing.jpg', 'jhderojas', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Terence_Blanchard_performing.jpg', '{"Intro":"Terence Oliver Blanchard (born March 13, 1962) is an American jazz trumpeter and composer. He has also written two operas and more than 80 film and television scores. Blanchard has been nominated for two Academy Awards for Original Score for BlacKkKlansman (2018) and Da 5 Bloods (2020), both directed by Spike Lee, a frequent collaborator.\nBlanchard started his career in 1980 playing in the Lionel Hampton Orchestra while studying jazz at Rutgers University. In 1982, just before he turned 20, he dropped out of Rutgers to join The Jazz Messengers, launching a professional career now in its fifth decade. The Metropolitan Opera in New York staged Blanchard''s opera Fire Shut Up in My Bones in its 2021–2022 season, the first opera by an African American composer in the organization''s history.\nBlanchard is also a passionate educational mentor. From 2000 to 2011, Blanchard served as artistic director of the Thelonious Monk Institute of Jazz. In 2011, he was named artistic director of the Henry Mancini Institute at the University of Miami, and in 2015, he became a visiting scholar in jazz composition at the Berklee College of Music. In 2019, the University of California, Los Angeles (UCLA), named Blanchard to its Endowed Chair in Jazz Studies, where he remained until 2023. In 2023, SFJAZZ announced the appointment of Blanchard as Executive Artistic Director. He leads the organization''s artistic programming and guides its overall creative direction.\nBlanchard was selected as the 2024 National Endowment for the Arts Jazz Masters.","Early Life":"Blanchard was born in New Orleans, Louisiana, the only child of Wilhelmina and Joseph Oliver Blanchard. His father was a manager at an insurance company and an amateur opera singer.\nBlanchard began playing piano at the age of five, and then at age eight, he switched to the trumpet after hearing Alvin Alcorn perform at his school. Blanchard played trumpet in summer music camps alongside his childhood friends, Wynton Marsalis and Branford Marsalis.\nBlanchard attended St. Augustine High School until transferring to John F. Kennedy High School so he could attend the prestigious New Orleans Center for Creative Arts where he studied under Roger Dickerson and Ellis Marsalis. From 1980 to 1982, Blanchard studied under jazz saxophonist Paul Jeffrey and trumpeter Bill Fielder at Rutgers University.","Career":"The Jazz Messengers of 1985, from left: Jean Toussaint, Terence Blanchard, Donald Harrison, and Lonnie Plaxico\nWhile at Rutgers University, Blanchard began touring with the Lionel Hampton Orchestra. In 1982, Wynton Marsalis recommended Blanchard as his replacement in Art Blakey''s Jazz Messengers and Blakey would appoint Blanchard the band''s musical director. Along with his New Orleans homeboy, Donald Harrison, Blanchard toured extensively and recorded five albums with the legendary band.\nIn 1986, Blanchard and Harrison left the Jazz Messengers to form their own quintet, featuring a rhythm section of young lions, Cyrus Chestnut, Rodney Whitaker, and drummer Carl Allen. The band influenced a new generation of young jazz musicians like Christian McBride, Nicholas Payton, Geoff Keezer, and Roy Hargrove.\nIn 1989, Blanchard stepped away from performance to correct his embouchure, and then a year later launched his solo career. Columbia Records released his self-titled debut, which reached No. 3 on the Billboard Jazz chart.\nAfter performing on soundtracks for Spike Lee movies, including Do the Right Thing (1989) and Mo'' Better Blues (1990), Lee hired Blanchard to compose the score for Jungle Fever (1991). Since then, Blanchard has composed the original score for most of Spike Lee''s films, including Malcolm X (1992), Clockers (1995), Summer of Sam (1999), 25th Hour (2002), Inside Man (2006), BlacKkKlansman (2018), and Da 5 Bloods (2020).\nIn addition to composing the score for Spike Lee''s four-hour Hurricane Katrina documentary for HBO entitled, When the Levees Broke: A Requiem in Four Acts (2006), Blanchard appeared onscreen with his mother to document their search for her destroyed home. A year later, Blue Note Records released Blanchard''s A Tale of God''s Will (A Requiem for Katrina). The album features Blanchard''s rearrangements of his score along with new compositions, providing listeners with his most personal and deeply affecting music to date. The recording won a 2008 Grammy Award for Best Large Jazz Ensemble Album.\nBlanchard has also composed for other directors, including Gina Prince-Bythewood, Regina King, Taylor Hackford, Ron Shelton, and Kasi Lemmons. Entertainment Weekly proclaimed Blanchard \"central to a general resurgence of jazz composition for film.\"\nBlanchard recorded several award-winning albums for Columbia Records, including Simply Stated (1992), The Malcolm X Jazz Suite (1993), In My Solitude: The Billie Holiday Songbook (1994), Romantic Defiance (1995), and The Heart Speaks (1996) featuring Ivan Lins, which was nominated for a Best Latin Jazz Performance Grammy Award.\nIn 1999, producer Peter Gelb signed Blanchard to the Sony Classical label and released Jazz In Film, which reunited Blanchard with Donald Harrison on three tracks. It also featured jazz legends Joe Henderson and Kenny Kirkland, both of whom died soon after the recording.\nBlanchard''s next album entitled, Wandering Moon (2000), scored him another Grammy nomination and the prestigious honor of Downbeat Magazine''s Artist of the Year.\nIn 2001, Blanchard released his third and final album for Sony Classical entitled, Let''s Get Lost. It featured arrangements of classic songs written by Jimmy McHugh performed by his quintet with guest vocalists Diana Krall, Jane Monheit, Dianne Reeves, and Cassandra Wilson. However, it was his instrumental only version of \"Lost In A Fog\" that got Blanchard another Grammy nomination for Best Jazz Instrumental Solo.\nIn 2003, Blanchard signed with Blue Note Records and released Bounce produced by Michael Cuscuna. Two years later, legendary pianist Herbie Hancock produced Flow, garnering two more Grammy Award nominations.\nIn between the two Blue Note recordings, Blanchard was featured on McCoy Tyner''s Illuminations with Gary Bartz, Christian McBride and Lewis Nash. The ensemble won the Grammy Award for Best Jazz Instrumental Album.\nBlanchard was a judge for the fifth annual Independent Music Awards to support independent artists'' careers.\nIn Disney''s 2009 film The Princess and the Frog, Blanchard performed all of the trumpet parts for the alligator character Louis. Blanchard also voiced the role of Earl the bandleader in the riverboat band.\nFifteen years later, Blanchard was invited to produce music for the theme park attraction Tiana''s Bayou Adventure, which is inspired by The Princess and the Frog.\nBlanchard made history when his Fire Shut Up in My Bones became the first opera by a Black composer to be presented by the Metropolitan Opera in New York City, opening the company''s 2021–22 season.\nA year later, the Met premiered another Blanchard opera entitled, Champion, marking the first time since Richard Strauss that a living composer had two operas premiere in successive seasons.","Print Biography":"This section of a biography of a living person does not include any references or sources. Please help by adding reliable sources. Contentious material about living persons that is unsourced or poorly sourced must be removed immediately, especially if potentially libelous or harmful.  (February 2025) (Learn how and when to remove this message)\nIn 2002, Scarecrow Press, a member of the Rowman & Littlefield Publishing Group, published Contemporary Cat: Terence Blanchard with Special Guests, an authorized biography of Blanchard written by Anthony Magro. The book features extensive interviews with Blanchard and other jazz and film greats like Branford Marsalis, Wynton Marsalis, Christian McBride, Spike Lee, Kasi Lemmons, and Michael Cristofer. Choice Reviews wrote: \"Magro augments the conversations with background and connecting material so that the text flows nicely. History will view Blanchard as an important figure in jazz, and this book makes the case compellingly.\"","Operas":"On June 15, 2013, after a workshop with Opera Fusion: New Works, Blanchard premiered his first opera, Champion, at the Opera Theatre of Saint Louis. It is about the life of prize fighting boxer Emile Griffith from St. Thomas, with a libretto by Pulitzer Prize-winning Michael Cristofer. It starred Denyce Graves, Aubrey Allicock, Robert Orth, and Arthur Woodley.  Champion made its Metropolitan Opera premiere in 2023, receiving the best opera recording Grammy, and its Lyric Opera of Chicago premier in 2024.\nOn June 15, 2019, Blanchard''s second opera, Fire Shut Up in My Bones, with a libretto by Kasi Lemmons, was premiered by the Opera Theatre of Saint Louis. The opera, based on the 2014 memoir of the same title by Charles Blow, was expanded with added dance sequences and a larger role for the part of Billie, Charles''s mother, and opened the Metropolitan Opera''s 2021–2022 season. It closed the Lyric Opera of Chicago''s 2021⁠–2022 mainstage opera season. Blanchard is the first Black composer to have an opera performed at the Metropolitan Opera."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (306, '1WmIo9ORq1IDlovUWFmo4Y', 'Terry', 'Gibbs', 'd39fff26-8132-4901-9faa-852c4223e777', 312534, 9, 'https://en.wikipedia.org/wiki/Terry_Gibbs', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Terry_Gibbs.jpg/500px-Terry_Gibbs.jpg', 'Laura Kolb Satellite Beach, Fl.- Taos,N.M., USA', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Terry_Gibbs.jpg', '{"Intro":"Terry Gibbs (born Julius Gubenko; October 13, 1924) is an American jazz vibraphonist and band leader.\nGibbs has performed or recorded with Tommy Dorsey, Chubby Jackson, Buddy Rich, Woody Herman, Benny Goodman, Alice Coltrane, Louie Bellson, Charlie Shavers, Mel Tormé, Buddy DeFranco, and others. Gibbs also worked in film and TV studios in Los Angeles.","The Music Stop":"In the mid 1960s, Gibbs opened a musical instrument store in Canoga Park, California, with former Benny Goodman drummer Mel Zelnick. Terry Gibbs and Mel Zelnick Music Stop was also the first teaching facility of Freddie Gruber and Henry Bellson, brother of Louie."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (307, '1WmIo9ORq1IDlovUWFmo4Y', 'Thad', 'Jones', '2676ce19-1319-48af-93dd-1b6313c126ca', 271154, 7, 'https://en.wikipedia.org/wiki/Thad_Jones', NULL, NULL, NULL, NULL, '{"Intro":"Thaddeus Joseph Jones (March 28, 1923 – August 20, 1986) was an American jazz trumpeter, composer and bandleader who has been called \"one of the all-time greatest jazz trumpet soloists\".","Early Life, Family And Education":"Thad Jones was born in Pontiac, Michigan, to Henry and Olivia Jones, a musical family of 10 (an older brother was pianist Hank Jones and a younger brother was drummer Elvin Jones). A self-taught musician, Thad began performing professionally at the age of 16. He served in U.S. Army bands during World War II (1943–1946).\nMany years later, while teaching jazz at the Royal Danish Conservatory in Copenhagen, Jones studied composition formally during this period. He also began learning the valve trombone.","Career":"After his military service, which included an association with the US Military School of Music and working with area bands in Des Moines, Iowa; and Oklahoma City, Oklahoma, Jones became a member of the Count Basie Orchestra in May 1954. He was featured as a soloist on such well-known tunes as \"April in Paris\", \"Shiny Stockings\", and \"Corner Pocket\". However, his main contribution to Basie''s organization was nearly two dozen arrangements and compositions, which included \"The Deacon\", \"H.R.H.\" (Her Royal Highness – in honor of the band''s command performance in London), \"Counter Block\", and lesser known tracks such as \"Speaking of Sounds\". His hymn-like ballad \"To You\" was performed by the Basie band combined with the Duke Ellington Orchestra in their only recording together, and the recording Dance Along With Basie contains nearly an entire album of Jones''s uncredited arrangements of standard tunes. In 1959, Jones played cornet on Thelonious Monk''s 5 by Monk by 5 album.\nJones left the Basie Orchestra in 1963 to become a freelance arranger and musician in New York City. In 1965, he and drummer Mel Lewis formed the Thad Jones/Mel Lewis Orchestra. The group started with informal late-night jam sessions among New York City''s top studio musicians. They began performing at the Village Vanguard in February 1966, to wide acclaim, and continued with Jones in the lead for 12 years. They won a 1978 Grammy Award for their album Live in Munich.\nJones taught at William Paterson College in New Jersey. At what is now the Thad Jones Archive site, pencil scores and vintage photos are available as part of the Living Jazz Archives.\nAfter abruptly relocating to Copenhagen (as had several other US jazz musicians), he became the leader of The Danish Radio Big Band, Jones transformed the Danish Radio Big Band into one of the world''s best. The result can be heard on a live-recording from the Montmartre in Copenhagen. In July 1979, Jones formed a new big band, Eclipse, with which he recorded a live album, Eclipse. Several Americans were on the album: pianist Horace Parlan, baritonist Sahib Shihab, trumpeter Tim Hagans, and trombonist/vocalist Richard B. Boone. The rest of the band comprised trombonists Bjarne Thanning and Ture Larsen, trumpeter Lars Togeby, altoists Ole Thøger and Michael Hove, tenor saxophonist Bent Jædig, and bassist Jesper Lundgaard. Jones further composed for the Danish Radio Big Band and taught jazz at the Royal Danish Conservatory in Copenhagen. He studied composition formally during this period, and also took up the valve trombone. In later years, his playing ability was diminished due to a lip injury, but his composing and arranging skills blossomed. His best-known composition is the standard \"A Child Is Born\".\nIn February 1985, Jones returned to the US to take over the leadership of the Count Basie Orchestra, upon his former leader''s death. Jones fronted the Basie band on numerous tours, also writing arrangements for recordings and performances with vocalist Caterina Valente and the Manhattan Transfer, but had to step down due to ill health.","Personal Life":"Jones had a daughter Thedia and a son Bruce from his first marriage in the US.\nIn January 1979, Jones suddenly moved to Copenhagen, Denmark, to the great surprise of his New York bandmates. He married a Danish woman, Lis. They named their son Thaddeus Joseph William Jones (born 4.January 1980).\nJones returned to the US in 1985 to lead the Count Basie Orchestra after his former leader''s death. Jones'' decline in health caused him to retire from performing. He returned to his home in Copenhagen for the last few months of his life. He died of cancer on August 20, 1986, aged 63, at Herlev Hospital. He is buried in Copenhagen''s Vestre Kirkegård Cemetery (Western Churchyard Cemetery).\nThad Jones Vej (Thad Jones Street) in southern Copenhagen  is named for Jones."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (308, '1WmIo9ORq1IDlovUWFmo4Y', 'Tim', 'Berne', '5451228f-9291-413f-981b-dbb3082777d1', 222596, 6, 'https://en.wikipedia.org/wiki/Tim_Berne', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Tim_Berne.jpg/500px-Tim_Berne.jpg', 'Matt Brown Guildford, UK', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Tim_Berne.jpg', '{"Intro":"Tim Berne (born October 16, 1954) is an American avant-garde jazz saxophonist and record label owner. His primary instruments are the alto and baritone saxophones.","Biography":"Berne was born in Syracuse, New York, United States. He has said that he had no interest in playing an instrument until he attended Lewis & Clark College in Oregon. Hearing the album Dogon A.D. (1972) by Julius Hemphill turned his attention toward jazz. He was a fan of rhythm and blues, and it seemed to him that Hemphill was playing jazz with the soulfulness of R&B. In 1974, he went to New York to find Hemphill, who gave him saxophone lessons and advice on how to manage his career. Berne started the record label Empire Productions in 1979.\nFor Empire, he recorded four albums with avant-garde jazz musicians such as John Carter, Alex Cline, Nels Cline, Olu Dara, Vinny Golia, Paul Motian, and Ed Schuller. His next two albums appeared on Soul Note in the early 1980s. In these sessions he worked with Motian, Schuller, Ray Anderson, Herb Robertson and others. He then got a contract with Columbia and recorded with Robertson, Hank Roberts, Bill Frisell and others. During this time he also recorded a duo album with Frisell and two albums with John Zorn. After two albums with Columbia, he signed with JMT, a label known for avant-garde jazz.\nIn the 1990s, he recorded in the trio, Miniature, with Roberts and Joey Baron, and in the band Caos Totale with Django Bates, Mark Dresser, Marc Ducret, Steve Swell, and Bobby Previte. He led a trio with Michael Formanek and Jim Black, then added Chris Speed to form the quartet Bloodcount (which was occasionally a quintet with the addition of Ducret). PolyGram bought JMT and closed it. This motivated Berne to start Screwgun Records as the outlet for his albums.\nScrewgun''s first release was a 3-disc set by Bloodcount called Unwound, the music of which exemplified Berne''s characteristic style of \"explod the walls of traditional compositional form: instead of adhering to anything remotely resembling theme and variations, he intersperses thematic material–sometimes repeated, elongated, or truncated–with the careening pleasures of free improvisation.\" During the late 1990s he continued to perform with Bloodcount, formed Paraphrase, a trio with Drew Gress and Tom Rainey , and Big Satan, a trio with Ducret and Rainey.\nIn the early 2000s, Berne formed several groups, including the trio Hard Cell with Rainey and Craig Taborn and the quartet Science Friction (Berne, Ducret, Rainey, and Taborn). He also collaborated with members of The Bad Plus for the project Buffalo Collision , with Nels Cline of Wilco for the critically acclaimed album The Veil in 2011, and with David Torn on several projects and recordings.\nBerne formed the band Snakeoil with Matt Mitchell, Oscar Noriega, and Ches Smith, which released a self-titled album in 2012 , and six more recordings, with slight personnel changes, over the next decade. During this time, he has also recorded with members of The Bad Plus as Broken Shadows , and in duos with several musicians. In 2023 he released Oceans And with Hank Roberts and Aurora Nealand.\nIn the late 2010s albums by other musicians interpreting Berne''s music have begun to appear. These include Førage by Matt Mitchell , Koi by Gregg Belisle-Chi , Palm Sweat by Marc Ducret , and Oddly Enough by Gordon Grdina.","Albums Featuring Music By Tim Berne":"Gregg Belisle-Chi - Koi (Relative Pitch, 2021)\nGordon Grdina - Oddly Enough (Attaboygirl, 2022)\nMarc Ducret - Palm Sweat (Out Of Your Head/Screwgun, 2023)\nGregg Belisle-Chi - Slow Crawl (Intakt, 2025)"}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (309, '1WmIo9ORq1IDlovUWFmo4Y', 'Tom', 'Harrell', '8943189a-0f1e-486c-b639-8df4a5b5fd62', 297675, 7, 'https://en.wikipedia.org/wiki/Tom_Harrell', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Tom_Harrell_2011.jpg/500px-Tom_Harrell_2011.jpg', 'Tom Beetz', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Tom_Harrell_2011.jpg', '{"Intro":"Tom Harrell (born June 16, 1946) is an American jazz trumpeter, flugelhornist, composer, and arranger. Voted Trumpeter of the Year of 2018 by Jazz Journalists Association, Harrell has won awards and grants throughout his career, including multiple Trumpeter of the Year awards from DownBeat magazine, SESAC Jazz Award, BMI (Broadcast Music Incorporated) Composers Award, and Prix Oscar du Jazz.  He received a Grammy Award nomination for his big band album, Time''s Mirror.","Biography":"Tom Harrell was born in Urbana, Illinois, United States, but moved to the San Francisco Bay Area at the age of five.  He started playing trumpet at eight, and within five years he was playing gigs with local bands. In 1969 he graduated from Stanford University with a music composition degree and joined Stan Kenton''s orchestra, touring and recording with them throughout 1969. Harrell pursued his musical career despite experiencing symptoms of schizophrenia since he was an adolescent.\nAfter leaving Kenton, Harrell played with Woody Herman''s big band (1970–1971), Azteca (1972), the Horace Silver Quintet (1973–1977), with whom he made five albums, the Sam Jones-Tom Harrell Big Band, the Lee Konitz Nonet (1979–1981), George Russell, and the Mel Lewis Orchestra (1981). From 1983 to 1989, he was a pivotal member of the Phil Woods Quintet and made seven albums with the group.\nIn addition, he performed with Vince Guaraldi on the Peanuts television specials You''re Not Elected, Charlie Brown (1972), There''s No Time for Love, Charlie Brown, A Charlie Brown Thanksgiving (both 1973) and It''s a Mystery, Charlie Brown (1974).\nHarrell also performed with Bill Evans, Dizzy Gillespie, Jim Hall, Ronnie Cuber, Bob Brookmeyer, Lionel Hampton, Bob Berg, Cecil Payne, Bobby Shew, Philip Catherine, Ivan Paduart , Joe Lovano, Charlie Haden''s Liberation Orchestra, Charles McPherson, David Sánchez, Sheila Jordan, Jane Monheit, the King''s Singers and Kathleen Battle among others. Harrell is featured on Bill Evans'' final studio recording, We Will Meet Again, which won a Grammy Award for Best Instrumental Jazz Performance, Group.\nWhile Harrell recorded several albums as a leader during his tenure with the Phil Woods Quintet, it was after his departure that he started producing albums as a leader, in succession for Contemporary Records (now owned by Concord), Chesky, and RCA/BMG. During his years as a BMG artist (1996–2003) first with RCA, then Bluebird and finally Arista, Harrell made six albums, many of which feature his arrangements for larger groups. Since the early 1990s, Harrell has toured and performed with his own groups of various sizes and instrumentation.\nHarrell is a prolific arranger and composer.  He has arranged for Vince Guaraldi''s work on Peanuts, Carlos Santana, the Metropole Orchestra, the Danish Radio Big Band, the Vanguard Jazz Orchestra, and Elisabeth Kontomanou with the Orchestre National de Lorraine , among others. His compositions have been recorded by other jazz artists including Ron Carter, Kenny Barron, Art Farmer, Chris Potter, Tom Scott, Steve Kuhn, Kenny Werner and Hank Jones. Harrell''s composition and big band arrangement entitled \"Humility\" was recorded on the Grammy-winning album by Arturo O''Farrill''s Afro-Latin Jazz Orchestra, Song for Chico. As a composer and arranger, Harrell works in different genres, including classical music."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (310, '1WmIo9ORq1IDlovUWFmo4Y', 'Tommy', 'Dorsey', 'b1cfd018-b393-4632-babc-8a343edb4baa', 229639, 11, 'https://en.wikipedia.org/wiki/Tommy_Dorsey', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Tommy_Dorsey%2C_WMCA%2C_New_York%2C_ca._Oct._1947_%28William_P._Gottlieb_02111%29.jpg/500px-Tommy_Dorsey%2C_WMCA%2C_New_York%2C_ca._Oct._1947_%28William_P._Gottlieb_02111%29.jpg', 'William P. Gottlieb', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Tommy_Dorsey,_WMCA,_New_York,_ca._Oct._1947_(William_P._Gottlieb_02111).jpg', '{"Intro":"Thomas Francis Dorsey Jr. (November 19, 1905 – November 26, 1956) was an American jazz trombonist, composer, conductor and bandleader of the big band era. He was known as the \"Sentimental Gentleman of Swing\" because of his smooth-toned trombone playing. His theme song was \"I''m Getting Sentimental Over You\". His technical skill on the trombone gave him renown among other musicians. He was the younger brother of bandleader Jimmy Dorsey. After Dorsey broke with his brother in the mid-1930s, he led an extremely successful band from the late 1930s into the 1950s. He is best remembered for standards such as \"Opus One\", \"This Love of Mine\" (no. 3 in 1941) featuring Frank Sinatra on vocals, \"Song of India\", \"Marie\", \"On Treasure Island\", and his biggest hit single, \"I''ll Never Smile Again\" (no. 1 for 12 weeks in 1940).","Early Life":"Born in Mahanoy Plane, Pennsylvania, Thomas Francis Dorsey Jr. was the second of four children born to Thomas Francis Dorsey Sr., a bandleader, and Theresa (née Langton) Dorsey. He and Jimmy, his older brother by slightly less than two years, became known as the Dorsey Brothers. The two younger siblings were Mary and Edward, who died young. Tommy Dorsey studied the trumpet with his father but later switched to trombone.\nAt age 15, Jimmy recommended Tommy to replace Russ Morgan in the Scranton Sirens, a territory band in the 1920s. Tommy and Jimmy worked in bands led by Tal Henry, Rudy Vallee, Vincent Lopez, and Nathaniel Shilkret. In 1923, Dorsey followed Jimmy to Detroit to play in Jean Goldkette''s band and returned to New York in 1925 to play with the California Ramblers. In 1927, he joined Paul Whiteman. In 1929, the Dorsey Brothers had their first hit with \"Coquette\" for OKeh Records.\nIn 1934, the Dorsey Brothers band signed with Decca, having a hit with \"I Believe in Miracles\". Glenn Miller was a member of the Dorsey Brothers Orchestra in 1934 and 1935, composing \"Annie''s Cousin Fanny\", \"Tomorrow''s Another Day\", \"Harlem Chapel Chimes\", and \"Dese Dem Dose\", all recorded for Decca, for the band. Acrimony between the brothers led to Tommy Dorsey walking out to form his own band in 1935 as the orchestra was having a hit with \"Every Little Moment\". Dorsey''s orchestra was known primarily for its renderings of ballads at dance tempos, frequently with singers such as Jack Leonard and Frank Sinatra.\nOn August 21, 1949, Tommy, along with trumpeter Charlie Shavers and singer Red Wooten, survived a plane crash uninjured. The aircraft, departing from Windsor, Ontario, Canada, crash-landed in a cornfield after the engine failed shortly after takeoff, according to the pilot.","Personal Life":"Dorsey was married three times. His first wife was 16-year-old Mildred \"Toots\" Kraft, with whom he eloped in 1922, when he was 17. The couple had two children, Patricia and Thomas F. Dorsey III (nicknamed \"Skipper\"). In 1935, they moved to \"Tall Oaks\", a 21-acre (8.5 ha) estate in Bernardsville, New Jersey. They divorced in 1943 after Dorsey''s affair with his former singer Edythe Wright.\nDorsey''s second wife was film actress Patricia Dane in 1943, and they were divorced in 1947, but not before he gained headlines for striking actor Jon Hall when Hall embraced her. Finally, Dorsey married Jane Carl New on March 27, 1948, in Atlanta, Georgia. She had been a dancer at the Copacabana nightclub in New York City. Tommy and Jane Dorsey had two children, Catherine Susan and Steve.\nDorsey died on November 26, 1956, at his home in Greenwich, Connecticut, a week after his 51st birthday. He had begun taking sleeping pills regularly at this time, causing him to become heavily sedated; he choked to death in his sleep after eating a large meal. Jimmy Dorsey led his brother''s band until his own death from throat cancer the following year. At that point, trombonist Warren Covington became leader of the band with Jane Dorsey''s blessing as she owned the rights to her late husband''s band and name. Billed as the Tommy Dorsey Orchestra Starring Warren Covington, they reached number seven on the Billboard chart and earned a gold record in the fall of 1958 with the hit single \"Tea for Two Cha-Cha\". The band was also fronted by Urbie Green after Dorsey''s death in 1956.\nAfter Covington left the band, tenor saxophonist Sam Donahue led it from 1961, continuing until 1966. Frank Sinatra Jr. made his professional singing debut with the band at Dallas Memorial Theater in Texas in 1963. Later, trombonist and bandleader Buddy Morrow led the Tommy Dorsey Orchestra from 1977 until his death on September 27, 2010. Jane Dorsey died of natural causes at the age of 79, in Miami, Florida, in 2003. Tommy and Jane Dorsey are interred together in Kensico Cemetery in Valhalla, New York.\nThe grave of Tommy and Jane Dorsey in Kensico Cemetery","Death And Aftermath":"Dorsey died on November 26, 1956, at his home in Greenwich, Connecticut, a week after his 51st birthday. He had begun taking sleeping pills regularly at this time, causing him to become heavily sedated; he choked to death in his sleep after eating a large meal. Jimmy Dorsey led his brother''s band until his own death from throat cancer the following year. At that point, trombonist Warren Covington became leader of the band with Jane Dorsey''s blessing as she owned the rights to her late husband''s band and name. Billed as the Tommy Dorsey Orchestra Starring Warren Covington, they reached number seven on the Billboard chart and earned a gold record in the fall of 1958 with the hit single \"Tea for Two Cha-Cha\". The band was also fronted by Urbie Green after Dorsey''s death in 1956.\nAfter Covington left the band, tenor saxophonist Sam Donahue led it from 1961, continuing until 1966. Frank Sinatra Jr. made his professional singing debut with the band at Dallas Memorial Theater in Texas in 1963. Later, trombonist and bandleader Buddy Morrow led the Tommy Dorsey Orchestra from 1977 until his death on September 27, 2010. Jane Dorsey died of natural causes at the age of 79, in Miami, Florida, in 2003. Tommy and Jane Dorsey are interred together in Kensico Cemetery in Valhalla, New York.\nThe grave of Tommy and Jane Dorsey in Kensico Cemetery"}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (311, '1WmIo9ORq1IDlovUWFmo4Y', 'Tommy', 'Flanagan', 'c39a1eeb-e646-43e9-b984-4ffdc92b0241', 253443, 3, 'https://en.wikipedia.org/wiki/Tommy_Flanagan_(musician)', 'https://upload.wikimedia.org/wikipedia/commons/b/b9/Tommy_Flanagan.jpg', 'Laura Kolb Satellite Beach, Florida - Taos, New Mexico, U.S.A.', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Tommy_Flanagan.jpg', '{"Intro":"Thomas Lee Flanagan (March 16, 1930 – November 16, 2001) was an American jazz pianist and composer. He grew up in Detroit, initially influenced by such pianists as Art Tatum, Teddy Wilson, and Nat King Cole, and then by bebop musicians. Within months of moving to New York in 1956, he had recorded with Miles Davis and on Sonny Rollins'' album Saxophone Colossus. Recordings under various leaders, including  Giant Steps of John Coltrane, continued well into 1962, when he became the full-time accompanist to Ella Fitzgerald. He worked with Fitzgerald for three years until 1965, and then in 1968 returned to be her pianist and musical director, this time for a decade.\nAfter leaving Fitzgerald in 1978, Flanagan attracted praise for the elegance of his playing, which was principally in trio settings when under his own leadership. In his 45-year recording career, he recorded more than three dozen albums under his own name and more than 200 as a sideman. By the time of his death, he was one of the most widely admired jazz pianists and had influenced both his contemporaries and later generations of players.","Early Life":"Flanagan was born in Conant Gardens, Detroit, Michigan, on March 16, 1930. He was the youngest of six children – five boys and a girl. His parents were both originally from Georgia. His father, Johnson Sr., was a postman, and his mother, Ida Mae, worked in the garment industry.\nAt the age of six, Flanagan''s parents gave him a clarinet for Christmas. He learned to read music from playing the clarinet, but within a few years he preferred the piano. The family had a piano in the house, and Flanagan received lessons from one of his brothers, Johnson, and Gladys Wade Dillard, who also taught Kirk Lightsey and Barry Harris. Flanagan graduated from Northern High School, which he attended with other future musicians, including saxophonist Sonny Red.\nFlanagan''s early influences included Art Tatum and Teddy Wilson, both of whom he heard on the radio and playing in the Detroit area, as well as Nat King Cole and local pianists Earl Van Riper and Willie Anderson. These, however, played in an earlier style, and the young Flanagan and his friends were more interested in the newer bebop, including that played by pianist Bud Powell, who had a strong effect on Flanagan''s musical thinking and improvising.","Later Life And Career":"Flanagan''s first concert was around 1945, with trombonist Frank Rosolino. Given Flanagan was only around 15 years old at the time, he could not stay in the bar area of the club between sets, so he went to another room and did some homework. As a teenager, he played in a band led by Lucky Thompson that also contained Pepper Adams and Kenny Burrell. Still in his teens, Flanagan also sat in on piano for some appearances by Charlie Parker in Detroit. During 1949, Flanagan had his first residence, at the Blue Bird Inn in Detroit. In 1950, he played with Rudy Rutherford, until the clarinetist returned to the Count Basie band. Flanagan then played jazz and rhythm and blues with saxophonist George Benson in Toledo, Ohio, before being drafted into the army in 1951.\nAfter basic training in Fort Leonard Wood, Missouri, Flanagan auditioned as a pianist for an army show. He gained the role, which prevented him from being sent to the Korean War at that time; approximately a year later, however, he was sent to Kunsan, with the war ongoing. There, he worked as a motion-picture projectionist. After two years'' service he was discharged and returned to Detroit, where he soon became pianist at the Blue Bird again. He again worked with Burrell, as well as Donald Byrd and Yusef Lateef, among others.\n1956–early 1978 – After move to New York\nFlanagan moved to New York in 1956. He was unsure of how long he would stay, having been persuaded to go by Burrell; the two men initially stayed with Burrell''s aunt in Harlem. Flanagan soon found work in clubs and studios, including recording Detroit – New York Junction with Thad Jones in March. Later that month, he returned to recording, this time with Miles Davis and Sonny Rollins, for tracks released on Collectors'' Items. Rollins was leader for another session three months later: Saxophone Colossus, which was labeled an \"undisputed masterpiece\" by The Penguin Guide to Jazz.\nFlanagan also first accompanied Ella Fitzgerald in 1956, for around a month, including at the Newport Jazz Festival. Later that year, he joined trombonist J. J. Johnson, with whom he recorded several albums in 1957 and then toured Europe. While in Sweden, Flanagan, with bassist Wilbur Little and drummer Elvin Jones, recorded his first album as leader, Overseas. Late in 1957, he was part of Miles Davis'' band for a short period, before returning to Johnson early the following year, for another stay of 10 months. A period leading his own trio in 1958 was followed by working with trombonist Tyree Glenn.\nThroughout the late 1950s and early 1960s, Flanagan made frequent appearances in recording studios, for many leaders and record labels. In May 1959, he was part of a groundbreaking recording: John Coltrane''s Giant Steps, described by The Penguin Guide to Jazz as the saxophonist''s \"first genuinely iconic record\". The technical complexity of the music, particularly of the title track, meant that there were numerous false starts and rejected takes, and the initially released take of \"Giant Steps\" is a rare instance on record of Flanagan sounding uncertain. Another appearance on a landmark recording came in January of the following year: Flanagan was a member of the quartet that made The Incredible Jazz Guitar of Wes Montgomery; his playing complemented that of the guitarist, using controlled force on bebop numbers and delicacy on a ballad track.\nFlanagan was with trumpeter Harry Edison in 1959–60, and tenor saxophonist Coleman Hawkins in 1961–62, including a UK tour. In this period, Flanagan recorded albums with several leaders from an earlier era, including Lionel Hampton, Jo Jones, and Pee Wee Russell, as well as one with Edison and around 10 with Hawkins. Flanagan then played with guitarist Jim Hall and bassist Percy Heath as a trio in New York.\nIn 1962, Flanagan was asked by jazz impresario Norman Granz to become Ella Fitzgerald''s full-time accompanist. Flanagan was looking for steadier work than was available with Hawkins, so he accepted. He worked with Fitzgerald from 1962 to 1965. They toured internationally, including to Japan in 1964. He also played with other bands when not required by the vocalist; these included a brief reunion with Rollins in 1965. Later the same year, Flanagan left Fitzgerald and was part of Art Farmer''s short-lived New York Jazz Sextet, which recorded Group Therapy. Flanagan then became accompanist to Tony Bennett for part of 1966, and lived on the West Coast.\nFlanagan returned to working with Fitzgerald in 1968. In addition to being her pianist, mostly as part of a trio, he was her musical director. Her profile was high enough for the group to tour for 40–45 weeks a year, including at least one tour of Europe a year (29 cities on the continent in 1970, for example). During these concerts, Flanagan often played a set as part of his trio, without the singer. Beginning in 1974, he again began to perform and record as a leader: his 1975 trio release, The Tommy Flanagan Tokyo Recital, was his first as leader since 1960. Prior to these performances, he had felt that his technique was inadequate for a soloist, but he enjoyed the extra exposure of being a leader, so decided to continue. Flanagan ended his role with Fitzgerald in 1978, after he had a heart attack and had become tired of extensive touring. After the heart attack, he stopped smoking, reduced the amount that he drank, and exercised by walking more than he had previously.\nFlanagan (left) with Ella Fitzgerald and Gerald Ford\nSoon after leaving Fitzgerald, Flanagan played solo piano in New York. In 1979, he was a guest on the first series of Marian McPartland''s Piano Jazz radio programs. He continued to work with other players, including as a trio with Tal Farlow and Red Mitchell in 1980. For much of the 1980s, he led a trio that featured bassist George Mraz and various drummers. By around 1990, Flanagan was concentrating on his own appearances and recordings rather than sideman activities. In the early 1990s, Mraz was replaced by Peter Washington, whose heavier bass lines added urgency to the trio''s sound.\nFlanagan''s reputation gradually grew after he moved on from being primarily an accompanist: in a 1992 article, critic Leonard Feather suggested that \"Flanagan is the pianist most likely to be named a personal idol by other jazz pianists, whether they be swing veterans or avant-gardists\". This made him more in demand; the workload may have contributed to his collapse in 1991 and subsequent quadruple bypass heart surgery. He returned to playing within weeks, but also returned to hospital for treatment for an aneurysm. Flanagan was awarded the Danish Jazzpar Prize in 1993. Three years later, he was selected for a National Endowment for the Arts Jazz Masters Fellowship. In 1990, 1993, and 1997, Flanagan toured Japan, where he was very popular, with 100 Golden Fingers, a 10-pianist group.\nFlanagan continued to be praised for the elegance of his playing – critic Ben Ratliff commented in 1998 that the trio with Washington and drummer Lewis Nash was, \"in its controlled, elegant way,  one of the more extraordinarily coordinated piano trios in jazz''s history\". Despite the near-unanimous praise from critics and musicians for Flanagan''s recordings and concert performances after he left Fitzgerald, he did not secure a recording contract with a major label for more than one album.\nIn late October 2001, Flanagan played in a John Coltrane tribute at the San Francisco Jazz Festival. The following month, he was admitted to Mount Sinai hospital in Manhattan; less than two weeks later, on November 16, he died there, from complications related to the aneurysm he had suffered a decade earlier.","Late 1978–2001 – After Ella Fitzgerald":"Soon after leaving Fitzgerald, Flanagan played solo piano in New York. In 1979, he was a guest on the first series of Marian McPartland''s Piano Jazz radio programs. He continued to work with other players, including as a trio with Tal Farlow and Red Mitchell in 1980. For much of the 1980s, he led a trio that featured bassist George Mraz and various drummers. By around 1990, Flanagan was concentrating on his own appearances and recordings rather than sideman activities. In the early 1990s, Mraz was replaced by Peter Washington, whose heavier bass lines added urgency to the trio''s sound.\nFlanagan''s reputation gradually grew after he moved on from being primarily an accompanist: in a 1992 article, critic Leonard Feather suggested that \"Flanagan is the pianist most likely to be named a personal idol by other jazz pianists, whether they be swing veterans or avant-gardists\". This made him more in demand; the workload may have contributed to his collapse in 1991 and subsequent quadruple bypass heart surgery. He returned to playing within weeks, but also returned to hospital for treatment for an aneurysm. Flanagan was awarded the Danish Jazzpar Prize in 1993. Three years later, he was selected for a National Endowment for the Arts Jazz Masters Fellowship. In 1990, 1993, and 1997, Flanagan toured Japan, where he was very popular, with 100 Golden Fingers, a 10-pianist group.\nFlanagan continued to be praised for the elegance of his playing – critic Ben Ratliff commented in 1998 that the trio with Washington and drummer Lewis Nash was, \"in its controlled, elegant way,  one of the more extraordinarily coordinated piano trios in jazz''s history\". Despite the near-unanimous praise from critics and musicians for Flanagan''s recordings and concert performances after he left Fitzgerald, he did not secure a recording contract with a major label for more than one album.\nIn late October 2001, Flanagan played in a John Coltrane tribute at the San Francisco Jazz Festival. The following month, he was admitted to Mount Sinai hospital in Manhattan; less than two weeks later, on November 16, he died there, from complications related to the aneurysm he had suffered a decade earlier.","Personal Life":"Flanagan''s mother died in 1959, and his father in 1977. Flanagan first married in 1960, to Ann. The couple had a son and two daughters, and divorced in the early 1970s; Ann was killed in a car accident in 1980. Flanagan married Diana, his second wife, in 1976. He was survived by Diana, the three children from his first marriage, and six grandchildren.\nFlanagan was usually self-effacing, reserved, and amiable. His personality was summarized by his second wife: \"His gentleness and quietness are deceptive. He is a strong man, and he has a lot of spirit and firmness.\"","Awards And Legacy":"During his career, Flanagan was nominated for five Grammy Awards. The first occasion was in 1983: The Magnificent Tommy Flanagan for Best Jazz Instrumental Performance, Soloist; and Giant Steps for Best Jazz Instrumental Performance, Group. Two years later, Thelonica was nominated for Best Jazz Instrumental Performance, Soloist. The next nomination was in 1998, for Best Jazz Instrumental Solo for his solo on \"Dear Old Stockholm\" from Sea Changes. The last, in 2003, was in the same category, for Flanagan''s solo on \"Sunset & the Mockingbird\", from A Great Night in Harlem.\nFlanagan''s influence on pianists extended from his contemporaries to younger performers. Contemporaries included fellow Detroit players Barry Harris and Roland Hanna. Lightsey was influenced by Flanagan''s musical creative thinking and pianistic fluidity. Alan Broadbent also acknowledged Flanagan as an influence, as did Helen Sung, who changed from being a classical music pianist to a jazz one after hearing the swing and logic of a Flanagan solo. Kenny Barron described Flanagan as his \"hero\" and stated that he admired the older man''s touch and phrasing from when he first heard it at junior high school: \"He became an influence and continued to be an influence till the day he died – and he still is.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (312, '1WmIo9ORq1IDlovUWFmo4Y', 'Tommy', 'Smith', 'c511b970-7016-4bd4-b54a-1cd1cb06bb34', 29988, 6, 'https://en.wikipedia.org/wiki/Tommy_Smith_(saxophonist)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/TommySmith-111-2018-DerekClarkPhoto.jpg/500px-TommySmith-111-2018-DerekClarkPhoto.jpg', 'DerekClarkPhoto', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:TommySmith-111-2018-DerekClarkPhoto.jpg', '{"Intro":"Thomas William Ellis Smith  (born 27 April 1967) is a Scottish jazz saxophonist, composer, and educator.","Early Life":"Smith was born in Edinburgh, Scotland, to Scottish parents Brenda Ann Urquhart, and father, William John Ellis, whom he never met. Smith was brought up in the Wester Hailes area of the city, where he was encouraged by his stepfather, George Smith, an avid jazz fan and drummer in the Gene Krupa style, to take up the tenor saxophone at the age of twelve. When he was thirteen he attended a weekly jazz workshop under the direction of Gordon Cruikshank. He met pathologist and pianist Vincenzo Crucioli, who became a mentor. With drummer John Rae, his first group won Edinburgh International Jazz Festival Best Group award in 1981. At fourteen Smith won ''Best Soloist''. He attributes much of his early success to the tuition of Vincenzo Crucioli. Under additional clarinettist Jim O''Malley and pianist Jean Allison at Wester Hailes Education Centre, Smith was soon performing around Edinburgh and Scotland with his quartet with John Rae (musician). In 1983, at sixteen, he recorded his first album Giant Strides, with a trio featuring Rae and Alan Taylor. During the same year, he recorded his second album, Taking Off, and won a scholarship, assisted by a fund-raising program organized by his music teacher, Jean Allison, to attend Berklee College of Music in Boston, Massachusetts. At Berklee he formed the band Forward Motion with Norwegian bassist Terje Gewelt, Canadian drummer Ian Froman, and Hungarian pianist Laszlo Gardony. The band recorded two albums, Progressions and The Berklee Tapes (1985).","Later Career":"With a recommendation from Chick Corea, Smith joined Berklee vice-president Gary Burton''s group with bassist Steve Swallow, pianist Makoto Ozone, and drummer Adam Nussbaum, touring the world and recording the album Whiz Kids for ECM.\nIn 1989, when he was twenty-two, Smith signed with Blue Note, which released his album Step by Step. Burton produced the album with a band consisting of John Scofield (guitar), Eddie Gómez (bass), and Jack DeJohnette (drums). Three more albums followed for Blue Note: Peeping Tom (1990), Standards (1991), and Paris (1992). During this period Smith hosted a series of BBC-TV specials called Jazz Types in which he performed with guests such as Tommy Flanagan, Gary Burton, Chick Corea, Bobby Watson, Arild Andersen, Hue and Cry, and the BBC Scottish Symphony Orchestra. Smith recorded and toured with Hue and Cry, a duo of brothers Pat and Greg Kane with American vibist Joe Locke, percussionist Trilok Gurtu, and Arild Andersen. Smith also examined classical composition, leading to his first saxophone concerto, Unirsi in Matrimonio, and a suite for saxophone and strings, Un Ecossais a Paris.\nIn 1993, Smith joined the Scottish record label, Linn Records. His albums, Reminiscence (1993), Misty Morning and No Time (1994), Azure (1995, with Jon Christensen, Lars Danielsson and Kenny Wheeler), and Beasts of Scotland (1996) were released. Writing in Playboy magazine, Neil Tesser noted of Beasts of Scotland that \"Smith''s artful writing makes the ensemble sound like a petite Philharmonic.\" The Sound of Love followed. Recorded in New York City in September 1997 with Kenny Barron (piano), Peter Washington (bass), and Billy Drummond (drums), it focused on the Duke Ellington-Billy Strayhorn songbook. Gymnopedie: The Classical Side of Tommy Smith (1998) was recorded with his regular duo partner, classical pianist Murray McLachlan. The disc included music by Satie, Bartok, Grieg, and Chick Corea, and Smith''s Sonatas No. 1 \"Hall of Mirrors\" and No. 2 \"Dreaming With Open Eyes\" based on Michael Tucker''s book of the same title. Returning to jazz and to New York the following year, Smith then recorded his final album for Linn, Blue Smith, with John Scofield and his regular rhythm section of bassist James Genus and drummer Clarence Penn.\nIn June 2025, Smith was dismissed from his role as Head of Jazz at the Royal Conservatoire of Scotland, a position he had held since 2009, following a disciplinary investigation into a relationship he had with a student.","Classical Music":"Smith recording his epic Modern Jacobite piece with The BBC Scottish Symphony Orchestra\nIn 1989 Smith performed An Rathad Ùr (\"The New Road\"), a concerto for saxophone by William Sweeney, with the BBC Scottish Symphony Orchestra for the television series Jazz Types, which Smith also presented. Prompted by Roger Pollen of the Scottish Ensemble, he spent six months studying orchestration for strings with a commission for saxophone and strings very much in mind. As a Blue Note musician at the time, Smith had access to the parent company EMI''s classical catalogue. He researched orchestration texts by Samuel Adler, Rimsky-Korsakov, and Cecil Forsyth, and spent two productive years in Paris where he studied classical music. He wrote his first classical composition, Unirsi in Matrimonio, for saxophone and strings in 1990. This was followed by another work for strings and saxophone, Un Ecossais À Paris in 1991, and he collaborated with classical pianist (Murray McLachlan) for Sonata No.1 – Hall of Mirrors and Sonata No.2 Dreaming with Open Eyes, both for saxophone and piano.\nThe next seven years were spent preparing for a much bigger orchestral work, the saxophone concerto Hiroshima (1998). This was premiered with the Orchestra of St. John Smith''s Square at Chelmsford Cathedral and included strings, brass, woodwinds, percussion, piano, and saxophone. Smith appeared as solo saxophonist for Sally Beamish''s The Knotgrass Elegy, commissioned for the 2001 BBC Proms, and performed with the BBC Symphony Orchestra at the Royal Albert Hall in London. In 2002, Smith performed his earlier and much lengthier re-invention of Children''s Songs for saxophone and orchestra with the Scottish Ensemble at St John''s Kirk, Perth. Other classical music endeavours have included a suite entitled Edinburgh, written for the Edinburgh Youth Orchestra''s 40th anniversary in 2003. The suite, with saxophone, bass, drums, and a one-hundred-person symphony orchestra, toured Scotland, Estonia, Russia, and Finland."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (313, '1WmIo9ORq1IDlovUWFmo4Y', 'Tony', 'Williams', 'b6a30b58-6b00-47c4-a031-c62a6981461f', 261295, 4, 'https://en.wikipedia.org/wiki/Tony_Williams_(drummer)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Tony_Williams_DownBeat.jpg/500px-Tony_Williams_DownBeat.jpg', 'Gretsch', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Tony_Williams_DownBeat.jpg', '{"Intro":"Anthony Tillmon Williams (December 12, 1945 – February 23, 1997) was an American jazz drummer. Williams first gained fame as a member of Miles Davis''s \"Second Great Quintet\", and later pioneered jazz fusion with Davis''s group and his own combo, The Tony Williams Lifetime. In 1970, music critic Robert Christgau described him as \"probably the best drummer in the world\". Williams was inducted into the Modern Drummer Hall of Fame in 1986 and the Percussive Arts Society Hall of Fame in 1997.","Life And Career":"Williams was born in Chicago, Illinois, and grew up in Boston, Massachusetts. He was of African, Portuguese, and Chinese descent. He studied with drummer Alan Dawson at the age of 11, and began playing professionally at the age of 13 with saxophonist Sam Rivers. Saxophonist Jackie McLean hired Williams when he was 16. As a young drummer, he was influenced by Max Roach, Art Blakey, Philly Joe Jones, Roy Haynes, Louis Hayes, and Jimmy Cobb.\nAt 17, Williams joined Miles Davis in what was later dubbed Davis''s Second Great Quintet—with saxophonist Wayne Shorter, pianist Herbie Hancock, and bassist Ron Carter. Davis had been in something of a creative lull, and critics noted the young Tony Williams''s playing spurred the others on. Williams was a vital element of the group, called by Davis in his autobiography \"the center that the group''s sound revolved around\". His playing helped redefine the role of the jazz rhythm section through the use of polyrhythms and metric modulation. Meanwhile, he recorded his first two albums as a leader for the Blue Note label: Life Time (1964) and Spring (1965). He also recorded as a sideman for the label including the classics Out to Lunch! with Eric Dolphy and Point of Departure with Andrew Hill, both in 1964.\nIn 1969 Williams formed The Tony Williams Lifetime, with John McLaughlin on guitar and Larry Young on organ. Lifetime was a pioneering band of the fusion movement.\nTheir first album was Emergency!. For the album Turn It Over, the trio was joined by bass guitarist and vocalist Jack Bruce. After several more releases and touring, Lifetime disbanded. In 1975, Williams formed \"The New Tony Williams Lifetime\", featuring bassist Tony Newton, keyboardist Alan Pasqua and guitarist Allan Holdsworth, who recorded two albums for Columbia Records: Believe It and Million Dollar Legs.\nIn 1976, Williams reunited with his colleagues from the Miles Davis Quintet. (Davis himself was in the midst of a six-year hiatus and was \"replaced\" by trumpeter Freddie Hubbard.)  A record of their concert was later released as V.S.O.P. (\"Very Special One-time Performance\"), the name under which the group toured and recorded for several years.Williams in Half Moon Bay, California, 1986In 1979, Williams, McLaughlin, and bassist Jaco Pastorius united for a performance at the Havana Jazz Festival. This trio came to be known as the Trio of Doom, and a recording of their performance (along with some studio tracks recorded in New York shortly thereafter) was released in 2007. Williams and Pastorius also played together on \"Good Question\" from the 1978 Herbie Hancock album Sunlight. Williams appears with the group Fuse One on their 1980 album.\nIn 1985, he returned to Blue Note with the album Foreign Intrigue. Eventually Williams formed his own acoustic quintet with trumpeter Wallace Roney, saxophonist Bill Pierce, pianist Mulgrew Miller and bassist Ira Coleman. The quintet played Williams''s compositions almost exclusively, recording and touring extensively from 1986 to 1992, culminating in the album The Story of Neptune.\nWilliams guested with the band Public Image Ltd, fronted by John Lydon, on their release titled Album (1986).\nOn February 20, 1997, Williams checked into Seton Medical Center in Daly City, California, suffering from stomach pain. Three days later, while recuperating from gallbladder surgery, he died of a heart attack. He was 51 years old.","Personal Life":"Williams lived and taught in the San Francisco Bay Area until his death in 1997. One of his final recordings was The Last Wave by the trio known as Arcana, a release organized by Bill Laswell."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (314, '1WmIo9ORq1IDlovUWFmo4Y', 'Toots', 'Thielemans', '20404789-b0f3-43de-bbe1-f4fe39e83e87', 120623, 13, 'https://en.wikipedia.org/wiki/Toots_Thielemans', 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Toots_thielemans.jpg', 'Ron van der Kolk', 'CC BY 2.5', 'https://commons.wikimedia.org/wiki/File:Toots_thielemans.jpg', '{"Intro":"Jean-Baptiste Frédéric Isidor, Baron Thielemans (29 April 1922 – 22 August 2016), known professionally as Toots Thielemans (), was a Belgian jazz musician. He was mostly known for playing the chromatic harmonica, as well as his guitar and whistling skills, and composing. According to jazz historian Ted Gioia, his most important contribution was in \"championing the humble harmonica\", which Thielemans made into a \"legitimate voice in jazz\". He eventually became the \"preeminent\" jazz harmonica player.\nHis first professional performances were with Benny Goodman''s band when they toured Europe in 1949 and 1950. He emigrated to the U.S. in 1951, becoming a citizen in 1957. From 1953 to 1959 he played with George Shearing, and then led his own groups on tours in the U.S. and Europe. In 1961 he recorded and performed live one of his own compositions, \"Bluesette\", which featured him playing guitar and whistling. In the 1970s and 1980s, he continued touring and recording, appearing with musicians such as Oscar Peterson, Elis Regina, Caetano Veloso, Ella Fitzgerald, Ivan Lins, Sarah Vaughan, Bill Evans, Dizzy Gillespie, Kenny Werner, Pat Metheny, Jaco Pastorius, Mina Mazzini, Elis Regina, Quincy Jones, George Shearing, Natalie Cole, Billy Joel, Paul Simon, and Paquito D''Rivera.\nThielemans recorded the soundtracks for The Pawnbroker (1964), The Reivers (1969), Midnight Cowboy (1969), The Getaway (1972), Cinderella Liberty (1973), Turkish Delight (1973 film), The Sugarland Express (1974) and Looking for Mr. Goodbar (1977). His harmonica theme song for the popular Sesame Street TV show was heard for 40 years. He often performed and recorded with Quincy Jones, who once called him \"one of the greatest musicians of our time.\" In 2009 he was designated a Jazz Master by the National Endowment for the Arts, the highest honor for a jazz musician in the United States.","Early Years":"Thielemans was born in Brussels on 29 April 1922. His parents owned a café. He began playing music at an early age, using a homemade accordion at age three. During the German occupation of Belgium beginning in 1940, he became attracted to jazz, but was then playing on a full-size accordion or a harmonica, which he taught himself to play in his teens.\nAfter being introduced to the music of Belgian-born jazz guitarist Django Reinhardt, he became inspired to teach himself guitar, which he did by listening to Reinhardt''s recordings. At the time he was a college student majoring in mathematics. By the war''s end in 1945, he considered himself a full-time musician. He said in 1950, \"Django is still one of my main influences, I think, for lyricism. He can make me cry when I hear him.\" During an interview in 1988, he recalled, \"I guess I was born at the right time to live and adapt and be touched by the evolution in the jazz language.\"","Career":"Thielemans, Adele Girard and Joe Marsala in front of the Onyx Club, 1948\nI used to think the chromatic had limits. But with the advent of Toots Thielemans, I have come to feel that the limitations are within the player. Because as far as I can see, Toots has no limitations.\nIn 1949 Thielemans joined a jam session in Paris with Sidney Bechet, Charlie Parker, Miles Davis, Max Roach and others. He first heard the faster bebop style of jazz from records by Parker and Dizzy Gillespie after they had reached Belgium after the war.  They became his musical \"prophets\". As his small collection of jazz records grew, the music of Benny Goodman and Lester Young began to impress him the most.\nDuring a visit to the U.S. in 1948, an agent of Benny Goodman heard him play at a small New York music club. Not long after he returned to his home in Belgium, he received a letter inviting him to join Goodman''s band while they toured in Europe. He readily accepted the invitation and joined their tours in 1949 and 1950. During the tour, Goodman was \"shocked\" when he learned that these tours were the first time Thielemans had earned money from his playing. Although Thielemans was hired on as a guitarist, when Goodman''s group debuted at the London Palladium, he played the harmonica due to union restrictions.\nDuring those years, he also made his first record with fellow band member, tenor saxophonist Zoot Sims. In 1951 he toured with singer-songwriter and compatriot Bobbejaan Schoepen, performing strictly as a guitarist.\nThielemans moved to the United States in 1952 where he was a member of Charlie Parker''s All-Stars and worked with Miles Davis and Dinah Washington.  In 1957 he became a U.S. citizen. From 1953 to 1959 he played guitar and harmonica with the George Shearing Quintet. With Shearing, he added whistling to his repertoire.  While Thielemans was playing in Hamburg in 1960 on tour with Shearing, a young musician and observer —John Lennon— noticed that Thielemans played a Rickenbacker guitar. Lennon was impressed, and felt he had to have one as well, on the principle that \"if it was good enough for Thielemans it was good enough for me.\" Lennon and the Beatles helped make Rickenbacker guitars world-famous.\nIn 1955, Thielmans recorded his first album as a band leader, The Sound. During the 1950s, Thielemans had dominated the \"miscellaneous instrument\" category in Down Beat magazine''s poll. Jerry Murad, of Jerry Murad''s Harmonicats recalls Thielemans''s mastery:\nToots played the harmonica in much the same manner that many of the great jazz artists of that time played their respective instruments. No one played harmonica like Toots. I felt like throwing my harmonica away.\nFrom 1959 on he toured internationally with his small group along with intermittently recording in the studio. He recorded with singers and musicians including Ella Fitzgerald, Pat Metheny, Jaco Pastorius, Stephane Grappelli, J.J. Johnson, Oscar Peterson, Shirley Horn, Joe Pass, and jazz pianist Bill Evans, among others. Thielemans says that his recording with Evans''s trio, Affinity, (1979) was one of his favorites.\nThielemans in 1961 (Grand Gala du Disque, The Hague)\nThielemans wrote \"Bluesette\", a jazz standard, which he performed on harmonica or while playing the guitar and whistling in unison. He said, \"If there''s a piece of music that describes me, it''s that song.\" First recorded by him in 1962, with lyrics added by Norman Gimbel, the song became a major worldwide hit. It has since been covered by over one hundred artists. Toots also wrote the ballad \"Ladyfingers\", which appeared on Herb Alpert and the Tijuana Brass''s album Whipped Cream & Other Delights.\nHe worked both as a bandleader and as a sideman, including many projects with composer/arranger Quincy Jones. In the 1960s he performed on television with Peggy Lee. In 1969 he recorded \"Honeysuckle Rose Aquarela Do Brasil\" with singer Elis Regina and performed with her on Swedish television special.\nDuring his career he performed on many film soundtracks, such as The Pawnbroker (1964), Midnight Cowboy (1969), The Getaway (1972), Turkish Delight (1973), Cinderella Liberty (1973), The Sugarland Express (1974), The Yakuza (1974), Looking for Mr. Goodbar (1977), The Wiz (1978), Jean de Florette (1986), and French Kiss (1995). His closing theme to the popular Sesame Street television show was heard for 40 years.\nHis music was heard on the Belgian television series Witse, and in the Netherlands, for the Baantjer program. He composed the music for the 1974 Swedish film Dunderklumpen!, in which he also provided the voice of the animated character Pellegnillot. His whistling and harmonica playing was heard on Old Spice commercials in the 1960s. He played harmonica on \"Night Game\" on Paul Simon''s 1975 album Still Crazy After All These Years.\nThielemans has the ultimate in technique and fantastic musical ideas of mood and expression—an unbelievable ability to translate these ideas from his mind through the instrument.\nArranger and harmonica player Richard Hayman\nDuring the early 1980s Thielemans was a guest a number of times on Late Night with David Letterman. He performed with the bassist Jaco Pastorius, and in 1983 he contributed to Billy Joel''s album An Innocent Man, playing on the song \"Leave a Tender Moment Alone.\" A year later, he appeared on the Julian Lennon song \"Too Late for Goodbyes\" from the album Valotte.\nIn 1984, he recorded with Billy Eckstine on the singer''s final album (I Am a Singer), featuring ballads and standards arranged and conducted by Angelo DiPippo. In the 1990s, Thielemans embarked on theme projects that included world music. In 1998 he released a French-flavoured album titled Chez Toots featuring guest singer Johnny Mathis.\nDuring those years, he often recorded songs as personal tributes to those who were influential during his career. On Chez Toots, for example, he included \"Dance For Victor\", which he dedicated to his sometimes keyboard accompanist, Victor Feldman. Similarly, he recorded \"Waltz for Sonny\" as a tribute to saxophonist Sonny Rollins. In June 1998, at Germany''s Jazzbaltica, he paid tribute to Frank Sinatra who died a month earlier. And during the first Caspian Jazz and Blues Festival in Azerbaijan in 2002, he performed his recorded version of \"Imagine\", his tribute to its writer, John Lennon.\nThielemans was well liked for his modesty and kind demeanor in his native Belgium, and was known for describing himself as a Brussels \"ket\", which means \"street kid\" in old Brussels slang.","Later Life":"Thielemans was nominated for the title of the Greatest Belgian in 2005. In the Flemish version, he finished in 20th place, and in the Walloon version he came 44th. On 23 January 2009, he joined guitarist Philip Catherine on stage at the Liberchies church (Belgium) in memory of the 100th anniversary of the birth of Django Reinhardt. In 2012, the Jazz at Lincoln Center concerts in New York celebrated Thieleman''s 90th birthday with, among others, Herbie Hancock, Eliane Elias, and Kenny Werner. He performed for the occasion and left the stage standing among his friends.\nBecause of health issues that led to show cancellations, Thielemans announced his retirement on 12 March 2014, cancelling all scheduled concerts. He was also hospitalized for a broken arm.  His manager stated that Thielemans \"wants to enjoy the rest he deserves.\"  However, he did make one more stage appearance, unannounced, in August 2014, at the Jazz Middelheim Festival in Antwerp.","Death":"Thielemans died on 22 August 2016 in Braine-l''Alleud, Belgium, at the age of 94.\nAfter the announcement, the Netherlands-based jazz and pop orchestra Metropole Orkest, along with American musician Quincy Jones, performed at London''s Royal Albert Hall in Thielemans'' honor. Another concert was performed at the Grand-Place, Brussels.\nThielemans was buried on 27 August 2016 in La Hulpe, just outside Brussels. Pianist Kenny Werner read a personal message from U.S. President Barack Obama for his widow, Huguette. It read: \"Dear Huguette. I was deeply saddened when I heard about your husband''s passing. I hope that shared memories will soften your suffering. Lift faith from the support of friends and family. Know that you will be in my thoughts for the next days. May Toots'' music lead you and offer you consolation. I''m sure it will do this for all of us.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (315, '1WmIo9ORq1IDlovUWFmo4Y', 'Toshiko', 'Akiyoshi', '78fe2146-ec71-44c8-86eb-117607e53933', 503241, 3, 'https://en.wikipedia.org/wiki/Toshiko_Akiyoshi', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Toshiko_Akiyoshi.jpg/500px-Toshiko_Akiyoshi.jpg', 'Brian McMillen.', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Toshiko_Akiyoshi.jpg', '{"Intro":"Toshiko Akiyoshi (秋吉敏子 or 穐吉敏子, Akiyoshi Toshiko; born 12 December 1929) is a Japanese jazz pianist, composer, arranger, and bandleader.\nAkiyoshi received fourteen Grammy Award nominations and was the first woman to win Best Arranger and Composer awards in Down Beat magazine''s annual Readers'' Poll. In 1984, she was the subject of the documentary Jazz Is My Native Language. In 1996, she published her autobiography, Life with Jazz, and in 2007 she was named an NEA Jazz Master by the U.S. National Endowment for the Arts.","Biography":"Akiyoshi was born in Liaoyang, Manchuria, to a Japanese family, the youngest of four sisters. In 1945, after World War II, Akiyoshi''s family lost their home and returned to Japan, settling in Beppu. A local record collector introduced her to jazz by playing a record of Teddy Wilson playing \"Sweet Lorraine.\" She immediately loved the sound and began to study jazz. In 1953, during a tour of Japan, pianist Oscar Peterson discovered her playing in a club on the Ginza. Peterson was impressed and convinced record producer Norman Granz to record her. In 1953, under Granz''s direction, she recorded her first album with Peterson''s rhythm section: Herb Ellis on guitar, Ray Brown on double bass, and J. C. Heard on drums. The album was released with the title Toshiko''s Piano in the U.S. and Amazing Toshiko Akiyoshi in Japan.\nAkiyoshi studied jazz at the Berklee School of Music in Boston. In 1955, she wrote a letter to Lawrence Berk, asking him to give her a chance to study at his school. After a year of wrangling with the State Department and Japanese officials, Berk was given permission for Akiyoshi to enroll. He offered her a full scholarship and mailed her a plane ticket to Boston. In January 1956, she became the first Japanese student at Berklee. Soon after, she appeared as a contestant on the 18 March 1956 broadcast of the CBS television panel show What''s My Line? In 1998, she was awarded an honorary doctorate of music from Berklee, by then known as the Berklee College of Music.\nAkiyoshi experienced some difficulties as a Japanese-born jazz musician in America. Some music fans saw her as an oddity more than a talented musician, a Japanese girl playing jazz in America. According to Akiyoshi, some of her success was attributed to her being an oddity, saying in an interview with the Los Angeles Times, “In those days, a Japanese woman playing like Bud Powell was something very new. So all the press, the attention, wasn’t because I was authentic ... It was because I was strange”. Despite being born in Manchuria, Akiyoshi considers herself Japanese and, as of 2010, had not obtained American citizenship.\nAkiyoshi married saxophonist Charlie Mariano in 1959. The couple had a daughter, Michiru. She and Mariano divorced in 1967 after forming several bands together. That same year she met saxophonist Lew Tabackin, whom she married in 1969. Akiyoshi, Tabackin, and Michiru moved to Los Angeles in 1972. In March 1973, Akiyoshi and Tabackin formed a 16-piece big band composed of studio musicians. Akiyoshi composed and arranged music for the band, and Tabackin served as the band''s featured soloist on tenor saxophone and flute. The band recorded its first album, Kogun, in 1974. The title, which translates to \"one-man army\", was inspired by the tale of a Japanese soldier lost for 30 years in the jungle who believed that World War II was still being fought and thus remained loyal to the Emperor. Kogun was commercially successful in Japan, and the band began to receive critical acclaim.\nThe couple moved to New York City in 1982 and assembled the Toshiko Akiyoshi Jazz Orchestra featuring Lew Tabackin. Akiyoshi toured with smaller bands to raise money for her big band. Years later, BMG continued to release her big band''s recordings in Japan but remained skeptical about releasing the music in the United States Although Akiyoshi was able to release several albums in the U.S. featuring her piano in solo and small combo settings, many of her later big band albums were released only in Japan.\nOn 29 December 2003, her band played its final concert at Birdland in New York City, where it had enjoyed a regular Monday night gig for more than seven years. Akiyoshi explained that she disbanded the ensemble because she was frustrated by her inability to obtain American recording contracts for the big band. She also said that she wanted to concentrate on her piano playing from which she had been distracted by years of composing and arranging. She has said that although she has rarely recorded as a solo pianist, that is her preferred format. On 24 March 2004, Warner Japan released the final recording of Akiyoshi''s big band. Titled Last Live in Blue Note Tokyo, the album was recorded 28–29 November 2003.","Music":"Akiyoshi''s Japanese heritage is distinctly present in her music and sets her compositions apart from other jazz musicians. When Duke Ellington died in 1974, Nat Hentoff wrote in The Village Voice that Ellington''s music reflected his African heritage. Akiyoshi was inspired to investigate her Japanese musical heritage. She composed using Japanese themes, harmonies, and instruments (kotsuzumi, kakko, utai, tsugaru shamisen). But her music remained planted firmly in jazz, reflecting influences from Duke Ellington, Charles Mingus, and Bud Powell.\nOne reviewer of the live album Road Time said the music on Akiyoshi''s big band albums demonstrated \"a level of compositional and orchestral ingenuity that made her one of perhaps two or three composer-arrangers in jazz whose name could seriously be mentioned in the company of Duke Ellington, Eddie Sauter, and Gil Evans.\"\nIn 1999, Akiyoshi was approached by Kyudo Nakagawa, a Buddhist priest, who asked her to write a piece for his hometown of Hiroshima. He sent her some photos of the aftermath of the nuclear bombing. Her initial reaction was horror. She could not see how she could compose anything to address the event. Finally, she found a picture of a young woman emerging from an underground shelter with a faint smile on her face. Akiyoshi said that after seeing this picture, she understood the message: hope. With that message in mind, she composed the three-part suite Hiroshima: Rising from the Abyss. The piece was premiered in Hiroshima on 6 August 2001, the 56th anniversary of the Hiroshima bombing. The Hiroshima suite appeared on the 2002 album Hiroshima – Rising from the Abyss."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (316, '1WmIo9ORq1IDlovUWFmo4Y', 'Trilok', 'Gurtu', '5af7a83c-88ba-493f-8bec-5c9e3b895e3e', 12821, 4, 'https://en.wikipedia.org/wiki/Trilok_Gurtu', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Trilok_Gurtu_WarszawaSep2007.jpg/500px-Trilok_Gurtu_WarszawaSep2007.jpg', 'Henryk Kotowski', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Trilok_Gurtu_WarszawaSep2007.jpg', '{"Intro":"Trilok Gurtu (born 30 October 1951) is an Indian percussionist and composer whose work blends the music of India with jazz fusion and world music.\nHe has worked with Terje Rypdal, Gary Moore, John McLaughlin, Jan Garbarek, Joe Zawinul, Michel Bisceglia, Bill Laswell, Maria João & Mário Laginha, Stefano Bollani and Robert Miles.","Early Life":"Gurtu was born to Hindu Brahmin parents in Mumbai, India; he had a Kashmiri Pandit father and a Marathi mother. He attended Antonio De Souza High School (ANZA) in Byculla,Mumbai. His mother, the famous Hindustani classical and semi-classical vocalist Shobha Gurtu, encouraged him to learn playing tabla, and he received formal training in percussion from Shah Abdul Karim.","Career":"Gurtu began playing a western drum kit in the 1970s, and developed an interest in jazz. In a 1995 television special on Jimi Hendrix, Gurtu mentioned having initially learned Western music without awareness of overdubbing, which, he said, forced him to learn multiple parts which most musicians would have never attempted. In the 1970s, he played with Charlie Mariano, John Tchicai, Terje Rypdal, and Don Cherry.\nOne of Gurtu''s earliest recordings was on Apo-Calypso, a 1977 album by the German ethnic fusion band Embryo. His mother also sang in that record, and later joined him on his first solo CD, Usfret.\nIn the 1980s, Gurtu played with Swiss drummer Charly Antolini and with John McLaughlin in McLaughlin''s trio, accompanied variously by bassists Jonas Hellborg, Jeff Berlin, Kai Eckhardt, and Dominique DiPiazza. The line-up with Hellborg performed at least one concert opening for Miles Davis in Berkeley, California in 1988.\nCollaboration between Gurtu and McLaughlin included vocal improvisations using the Indian tala talk method of oral drumming notations for teaching drum patterns. Sometimes, Eckhardt would join in with hip-hop beat-box vocals for a three-way vocal percussion jam, while Gurtu and McLaughlin would throw in a few amusing words such as some Japanese brand names mixed with some Indian words.\nSome of the unusual aspects of Gurtu''s drum playing include playing without a drum stool, in a half-kneeling position on the floor, and the use of an unconventional kick drum that resembles a large drum head with a kick-pedal, and a mix of tablas and western drums. Gurtu''s unique percussion signature involves dipping cymbals and strings of shells into a bucket of water to create a shimmering effect.\nGurtu joined Oregon after the death of percussionist/tabla player Collin Walcott. He played on three of their records: Ecotopia (1987), 45th Parallel (1989), and Always, Never and Forever (1991).\nIn the early 1990s, Gurtu resumed his career as a solo artist and a bandleader. Various noted musicians have backed him on a number of his CD releases.\nIn 1999, Zakir Hussain and Bill Laswell founded a musical group, Tabla Beat Science, which played a mixture of Hindustani music, Asian underground, ambient, Drum and Bass, and Electronica. Gurtu joined this group along with Karsh Kale and Talvin Singh. The group released three albums before going dormant in late 2003.\nIn 2004, Gurtu created an album, Miles Gurtu, with Robert Miles. His collaboration with the Arkè String Quartet began in 2007 with the release of the album Arkeology.\nIn 2010, Trilok Gurtu played on the album Piano Car, an opera of minimalist composer Stefano Ianne with Ricky Portera, Nick Beggs (Kajagoogoo), Mario Marzi, Terl Bryant (John Paul Jones/Led Zeppelin), John De Leo.\nIn 2012, Trilok Gurtu collaborated with electronic folk duo Hari & Sukhmani in their hometown of Chandigarh and produced a song ''Maati'' on the music documentary-travelogue The Dewarists.","Legacy":"Trilok Gurtu is acknowledged as an innovative and ground breaking percussionist, and integrates swords, buckets and other non-conventional elements and into his sound. Zakir Hussain said that if Trilok Gurtu played only the tabla, he would have been the best tabla player in the world.\nDeadmau5 (Joel Zimmerman) mentions Trilok Gurtu as his hero and once added: \"You know who''s a big hero of mine? Trilok Gurtu... Indians should know this. Indian traditional percussive algos (algorhythms) and modes blow my mind. Check him out. Full-on retarded isolation skills. I can''t even chew gum and walk. There''s a whole different language/notation to a tabla.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (317, '1WmIo9ORq1IDlovUWFmo4Y', 'Vincent', 'Herring', '67b97580-f939-470e-bfa1-c3049f69c342', 44113, 6, 'https://en.wikipedia.org/wiki/Vincent_Herring', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Vincent_Herring.jpg/500px-Vincent_Herring.jpg', 'Professor Bop', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Vincent_Herring.jpg', '{"Intro":"Vincent Dwyne Herring (born November 19, 1964) is an American jazz saxophonist, flautist, composer, and educator. Known for his fiery and soulful playing in the bands of Horace Silver, Freddie Hubbard, and Nat Adderley in the earlier stages of his career, he now frequently performs around the world with his own groups and is heavily involved in jazz education.","Biography":"He was born in Hopkinsville, Kentucky, United States. His parents divorced, and he and his mother moved to California. When he was 11, he started playing saxophone in school bands and studying privately at Dean Frederick''s School of Music in Vallejo, California. At age 16, he entered California State University, Chico on a music scholarship.\nA year later, Herring auditioned for the United States Military Academy band, Jazz Knights, playing lead alto sax. He moved to West Point and served one enlisted tour. In 1982 he moved to New York City attending Long Island University.\nHerring first toured the United States and Europe as part of the Lionel Hampton Big Band. His talents came to the attention of Nat Adderley, and the two forged a nine-year musical relationship that led to nine albums and touring around the world year after year. After Adderley''s death, Herring collaborated with former Cannonball Adderley bandmember Louis Hayes to form the Cannonball Adderley Legacy Band. He also worked and recorded with pianist Cedar Walton for over two decades. He has also appeared on stage or recordings with Dizzy Gillespie, Horace Silver, Art Blakey and the Jazz Messengers, Jack DeJohnette''s Special Edition, Freddie Hubbard, James Carter, Larry Coryell, Steve Turre, the Mingus Big Band, Billy Taylor, Nancy Wilson, Kenny Barron, Roy Hargrove, Arthur Taylor, Carla Bley, Mike LeDonne, Eric Alexander, Wallace Roney, Carl Allen, Bobby Watson, Gary Bartz, Sonny Fortune, Cyrus Chestnut, Jeremy Pelt, Joe Farnsworth, and the Phil Woods Sax Machine (a band augmenting Woods'' regular quintet to an octet with three additional alto saxophonists). Herring has appeared as a special guest soloist with Wynton Marsalis at Lincoln Center as well as with Jon Faddis and The Carnegie Hall Big Band.\nHerring has recorded over 20 albums as a leader and over 250 as a sideman. In addition to the Cannonball Adderley Legacy Band, Herring''s other projects include Something Else, The Battle with Vincent Herring and Eric Alexander, The Vincent Herring-Joris Dudli''s Soul Jazz Alliance, Earth Jazz Agents, and Jazz The Story.\nHerring has taken bands to Japan, Europe, and China on several occasions and has appeared in nearly every major jazz festival in the world. He is also involved in jazz education as a professor at William Paterson University and Manhattan School of Music. In 2024, Herring published his jazz improvisation method book, Logic and Critical Thinking in Jazz Improvisation, with Sher Music, which focuses on distilling his original improvisation concepts and techniques."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (318, '1WmIo9ORq1IDlovUWFmo4Y', 'W. C.', 'Handy', '2e37d3ed-afc7-42ca-bbb4-d21c7135f548', 782861, 7, 'https://en.wikipedia.org/wiki/W._C._Handy', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/W._C._Handy_%281941_Van_Vechten_portrait%29.jpg/500px-W._C._Handy_%281941_Van_Vechten_portrait%29.jpg', 'Carl Van Vechten', 'Public domain', 'https://commons.wikimedia.org/wiki/File:W._C._Handy_(1941_Van_Vechten_portrait).jpg', '{"Intro":"William Christopher Handy (November 16, 1873 – March 28, 1958) was an American composer and musician who referred to himself as the Father of the Blues. He was one of the most influential songwriters in the United States. One of many musicians who played the distinctively American blues music, Handy did not create the blues genre but was one of the first to publish music in the blues form, thereby taking the blues from a regional music style (Delta blues) with a limited audience to a new level of popularity.\nHandy used elements of folk music in his compositions. He was scrupulous in documenting the sources of his works, which frequently combined stylistic influences from various performers.","Early Life":"Handy was born on November 16, 1873, in Florence, Alabama, the son of Elizabeth Brewer and Charles Barnard Handy. His father was the pastor of a small church in Guntersville, a town in northern Alabama''s Marshall County. Handy wrote in his 1941 autobiography Father of the Blues that he was born in a log cabin built by his grandfather William Wise Handy, who became an African Methodist Episcopal minister after the Emancipation Proclamation. The log cabin of Handy''s birth has been preserved near downtown Florence.\nHandy''s father believed that musical instruments were tools of the devil. Without his parents'' permission, Handy bought his first guitar, which he had seen in a local shop window and secretly saved for by picking berries and nuts and making lye soap. Upon seeing the guitar, his father asked him, \"What possessed you to bring a sinful thing like that into our Christian home?\" and ordered him to \"take it back where it came from\", but he also arranged for his son to take organ lessons. The organ lessons did not last long, but Handy moved on to learn to play the cornet. He joined a local band as a teenager, but he kept this fact a secret from his parents. He purchased a cornet from a fellow band member and spent every free minute practicing it.\nWhile growing up, he apprenticed in carpentry, shoemaking, and plastering. He was deeply religious. His musical style was influenced by the church music he sang and played in his youth and by the sounds of nature. He cited as inspiration the \"whippoorwills, bats and hoot owls and their outlandish noises\", Cypress Creek washing on the fringes of the woodland, and \"the music of every songbird and all the symphonies of their unpremeditated art\".\nHe worked on a \"shovel brigade\" at the McNabb furnace, where he learned to use his shovel to make music with the other workers to pass the time. The workers would beat their shovels against hard surfaces in complex rhythms that Handy said were \"better to us than the music of a martial drum corps.\" Handy would later recall this improvisational spirit as being a formative experience for him, musically: \"Southern Negroes sang about everything....They accompany themselves on anything from which they can extract a musical sound or rhythmical effect.\" He reflected, \"In this way, and from these materials, they set the mood for what we now call Blues.\"","Career":"Handy at age 19In September 1892, Handy traveled to Birmingham, Alabama, to take a teaching exam. He passed it easily and gained a teaching job at the Teachers Agriculture and Mechanical College (the current-day Alabama A&M University) in Normal, then an independent community near Huntsville. Learning that it paid poorly, he quit the position and found employment at a pipe works plant in nearby Bessemer.\nIn his time off from his job, he organized a small string orchestra and taught musicians how to read music. He later organized the Lauzetta Quartet. When the group read about the upcoming World''s Fair in Chicago, they decided to attend. To pay their way, they performed odd jobs along the way. They arrived in Chicago and then learned that the World''s Fair had been postponed for a year. Next they headed to St. Louis, Missouri, but found no work.Handy, c. 1900, director of the Alabama Agriculture & Mechanical College Band\nAfter the quartet disbanded, Handy went to Evansville, Indiana. He played the cornet in the Chicago World''s Fair in 1893. In Evansville, he joined a successful band that performed throughout neighboring cities and states. His musical endeavors were varied: he sang first tenor in a minstrel show, worked as a band director, choral director, cornetist, and trumpeter. At the age of 23, he became the bandmaster of Mahara''s Colored Minstrels.\nIn a three-year tour they traveled to Chicago, throughout Texas and Oklahoma to Tennessee, Georgia, and Florida, and on to Cuba, Mexico and Canada. Handy was paid a salary of $6 per week. Returning from Cuba the band traveled north through Alabama, where they stopped to perform in Huntsville.\nIn 1896, while performing at a barbecue in Henderson, Kentucky, Handy met Elizabeth Price. They married on July 19, 1896. She gave birth to Lucille, the first of their  six children, on June 29, 1900. Weary of life on the road, he and his wife, Elizabeth, stayed with relatives after they had settled in Florence.\nAround that time, William Hooper Councill, the president of State Agricultural and Mechanical College for Negroes in Huntsville (which became Alabama A&M University), the same college Handy had refused to teach at in 1892 due to low pay, hired Handy to teach music. He became a faculty member in September 1900 and taught through much of 1902. He was disheartened to discover that the college emphasized teaching European \"classical\" music. He felt he was underpaid and could make more money touring with a minstrel group.\nIn 1902, Handy traveled throughout Mississippi, listening to various styles of popular black music. The state was mostly rural and music was part of the culture, especially in cotton plantations in the Mississippi Delta. Musicians usually played guitar or banjo or, to a much lesser extent, piano. Handy''s remarkable memory enabled him to recall and transcribe the music he heard in his travels.\nAfter a dispute with AAMC President Councill, Handy resigned his teaching position to return to the Mahara Minstrels and tour the Midwest and Pacific Northwest. In 1903, he became the director of a black band organized by the Knights of Pythias of North America, South America, Europe, Asia, Africa and Australia in Clarksdale, Mississippi. Handy and his family lived there for six years. During this time, he had several formative experiences that he later recalled as influential in his developing musical style. In 1903, while waiting for a train in Tutwiler, Mississippi in the Mississippi Delta, Handy overheard a black man playing a steel guitar using a knife as a slide.\nAbout 1905, while playing a dance in Cleveland, Mississippi, Handy was given a note asking for \"our native music\". He played an old-time Southern melody but was asked if a local colored band could play a few numbers. Handy assented, and three young men with well-worn instruments began to play. Research by Elliott Hurwitt for the Mississippi Blues Trail identified the leader of the band in Cleveland as Prince McCoy. In his autobiography, Handy described the music they played:\nThey struck up one of those over and over strains that seem to have no beginning and certainly no ending at all. The strumming attained a disturbing monotony, but on and on it went, a kind of stuff associated with  cane rows and levee camps. Thump-thump-thump went their feet on the floor. It was not really annoying or unpleasant. Perhaps \"haunting\" is the better word.\nHandy also took influence from the square dances held by Mississippi blacks, which typically had music in the G major key. In particular, he picked the same key for his 1914 hit, \"Saint Louis Blues\".\n\"The Memphis Blues\" sheet music cover, 1913\nIn 1909 Handy and his band moved to Memphis, Tennessee, where they played in clubs on Beale Street. \"The Memphis Blues\" was a campaign song written for Edward Crump, the successful Democratic Memphis mayoral candidate in the 1909 election and political boss. The other candidates also employed Black musicians for their campaigns. Handy later rewrote the tune and changed its name from \"Mr. Crump\" to \"Memphis Blues.\" The 1912 publication of the sheet music of \"The Memphis Blues\" introduced his style of 12-bar blues; it was credited as the inspiration for the foxtrot by Vernon and Irene Castle, a New York dance team. Handy sold the rights to the song for $100. By 1914, when he was 40, he had established his musical style, his popularity had greatly increased, and he was a prolific composer.\nIn his autobiography, Handy described how he incorporated elements of black folk music into his musical style. The basic three-chord harmonic structure of blues music and the use of flat third and seventh chords in songs played in the major key all originated in vernacular music created for and by impoverished southern blacks. Those notes are now referred to in jazz and blues as blue notes. His customary three-line lyrical structure came from a song he heard Phil Jones perform. Finding the structure too repetitive, he adapted it: \"Consequently I adopted the style of making a statement, repeating the statement in the second line, and then telling in the third line why the statement was made.\" He also made sure to leave gaps in the lyrics for the singer to provide improvisational filler, which was common in folk blues.\nHandy''s first popular success, \"Memphis Blues\", recorded by Victor Military Band, July 15, 1914\nWriting about the first time \"Saint Louis Blues\" was played, in 1914, Handy said,\nThe one-step and other dances had been done to the tempo of Memphis Blues. ... When St Louis Blues was written the tango was in vogue. I tricked the dancers by arranging a tango introduction, breaking abruptly into a low-down blues. My eyes swept the floor anxiously, then suddenly I saw lightning strike. The dancers seemed electrified. Something within them came suddenly to life. An instinct that wanted so much to live, to fling its arms to spread joy, took them by the heels.\nHis published musical works were groundbreaking because of his race. In 1912, he met Harry Pace at the Solvent Savings Bank in Memphis. Pace was the valedictorian of his graduating class at Atlanta University and a student of W. E. B. Du Bois. By the time of their meeting, Pace had demonstrated a strong understanding of business. He earned his reputation by saving failing businesses. Handy liked him, and Pace later became the manager of Pace and Handy Sheet Music.\nIn 1916, American composer William Grant Still, early in his career, worked in Memphis for W.C. Handy''s band. In 1918, Still joined the United States Navy to serve in World War I. After the war, he went to Harlem, where he continued to work for Handy.\n1914 sheet music cover of \"Yellow Dog Rag\"\nIn 1917, Handy and his publishing business moved to New York City, where he had offices in the Gaiety Theatre office building in Times Square. By the end of that year, his most successful songs had been published: \"Memphis Blues\", \"Beale Street Blues\", and \"Saint Louis Blues\". That year, the Original Dixieland Jazz Band, a white New Orleans jazz ensemble, had recorded the first jazz record, introducing the style to a wide segment of the American public. Handy had little fondness for jazz, but bands dove into his repertoire with enthusiasm, making many of these songs jazz standards.\nHandy encouraged performers such as Al Bernard, a soft-spoken white man who nonetheless was a powerful blues singer. He sent Bernard to Thomas Edison to be recorded, which resulted in a series of successful recordings. Handy also published music written by other writers, such as Bernard''s \"Shake Rattle and Roll\" and \"Saxophone Blues\", and \"Pickaninny Rose\" and \"O Saroo\", two black traditional tunes contributed by a pair of white women from Selma, Alabama. Publication of these hits, along with Handy''s blues songs, gave his business a reputation as a publisher of black music.\nIn 1919, Handy signed a contract with Victor Talking Machine Company for a third recording of his unsuccessful 1915 song \"Yellow Dog Blues\". The resulting Joe Smith recording of the song was a strong seller, with orders numbering in the hundreds of thousands of copies.\nHandy tried to interest black singers in his music but was unsuccessful; many musicians chose to play only the current hits, and did not want to take risks with new music. According to Handy, he had better luck with white bandleaders, who \"were on the alert for novelties. They were therefore the ones most ready to introduce our numbers.\" Handy also had little success selling his songs to black women singers, but in 1920, Perry Bradford convinced Mamie Smith to record two non-blues songs (\"That Thing Called Love\" and \"You Can''t Keep a Good Man Down\") that were published by Handy and accompanied by a white band. When Bradford''s \"Crazy Blues\" became a hit as recorded by Smith, black blues singers became popular. Handy''s business began to decrease because of the competition.\nIn 1920, Pace amicably dissolved his partnership with Handy, with whom he also collaborated as lyricist. Pace formed Pace Phonograph Company and Black Swan Records, and many of the employees went with him. Handy continued to operate the publishing company as a family-owned business. He published works of other black composers as well as his own, which included more than 150 sacred compositions and folk song arrangements and about 60 blues compositions. In the 1920s, he founded the Handy Record Company in New York City; while this label released no records, Handy organized recording sessions with it, and some of those recordings were eventually released on Paramount Records and Black Swan Records. So successful was \"Saint Louis Blues\" that, in 1929, he and director Dudley Murphy collaborated on a RCA motion picture of the same name, which was to be shown before the main attraction. Handy suggested blues singer Bessie Smith for the starring role because the song had made her popular. The movie was filmed in June and was shown in movie houses throughout the United States from 1929 to 1932.\nThe importance of Handy''s work as a musician and musicologist crossed the boundaries of genre, coming to influence European composers such as Maurice Ravel, who was inspired during a stay in Paris of Handy and his orchestra for the composition of the famous sonata nr 2 for violin and piano known not by chance as the Blues sonata.\nIn 1926 Handy wrote Blues: An Anthology—Complete Words and Music of 53 Great Songs. It is an early attempt to record, analyze, and describe the blues as an integral part of the South and the history of the United States. To celebrate the publication of the book and to honor Handy, Small''s Paradise in Harlem hosted a party, \"Handy Night\", on Tuesday October 5, which contained the best of jazz and blues selections provided by Adelaide Hall, Lottie Gee, Maude White, and Chic Collins.\nW. C. Handy in November 1949, playing trumpet in his music publishing office overlooking Times Square\nIn a 1938 radio episode of Ripley''s Believe It or Not! Handy was described as \"the father of jazz as well as the blues.\" Fellow blues performer Jelly Roll Morton wrote an open letter to Downbeat magazine fuming that he had invented jazz.\nAfter the publication of his autobiography, Handy published a book on African-American musicians, titled Unsung Americans Sung (1944). He wrote three other books: Blues: An Anthology: Complete Words and Music of 53 Great Songs, Book of Negro Spirituals, and Negro Authors and Composers of the United States. He lived on Strivers'' Row in Harlem. He became blind after an accidental fall from a subway platform in 1943.\nFrom 1943 until his death, he lived in Yonkers. His grandson is the physicist Carlos Handy (born 1950), who now leads the Handy Brothers Music Company. After the death of his first wife, he remarried in 1954 when he was 80. His bride was his secretary Irma Louise Logan, who he frequently said had become his eyes. In 1955, he had a stroke, and he began to use a wheelchair. More than 800 people attended his 84th birthday party at the Waldorf-Astoria Hotel.\nOn March 28, 1958, Handy died of bronchial pneumonia at Sydenham Hospital in New York City. Over 25,000 people attended his funeral in Harlem''s Abyssinian Baptist Church. Over 150,000 people gathered in the streets near the church to pay their respects. He was buried in Woodlawn Cemetery (Bronx, New York) in the bronx","Early Years":"Handy at age 19In September 1892, Handy traveled to Birmingham, Alabama, to take a teaching exam. He passed it easily and gained a teaching job at the Teachers Agriculture and Mechanical College (the current-day Alabama A&M University) in Normal, then an independent community near Huntsville. Learning that it paid poorly, he quit the position and found employment at a pipe works plant in nearby Bessemer.\nIn his time off from his job, he organized a small string orchestra and taught musicians how to read music. He later organized the Lauzetta Quartet. When the group read about the upcoming World''s Fair in Chicago, they decided to attend. To pay their way, they performed odd jobs along the way. They arrived in Chicago and then learned that the World''s Fair had been postponed for a year. Next they headed to St. Louis, Missouri, but found no work.Handy, c. 1900, director of the Alabama Agriculture & Mechanical College Band\nAfter the quartet disbanded, Handy went to Evansville, Indiana. He played the cornet in the Chicago World''s Fair in 1893. In Evansville, he joined a successful band that performed throughout neighboring cities and states. His musical endeavors were varied: he sang first tenor in a minstrel show, worked as a band director, choral director, cornetist, and trumpeter. At the age of 23, he became the bandmaster of Mahara''s Colored Minstrels.\nIn a three-year tour they traveled to Chicago, throughout Texas and Oklahoma to Tennessee, Georgia, and Florida, and on to Cuba, Mexico and Canada. Handy was paid a salary of $6 per week. Returning from Cuba the band traveled north through Alabama, where they stopped to perform in Huntsville.\nIn 1896, while performing at a barbecue in Henderson, Kentucky, Handy met Elizabeth Price. They married on July 19, 1896. She gave birth to Lucille, the first of their  six children, on June 29, 1900. Weary of life on the road, he and his wife, Elizabeth, stayed with relatives after they had settled in Florence.\nAround that time, William Hooper Councill, the president of State Agricultural and Mechanical College for Negroes in Huntsville (which became Alabama A&M University), the same college Handy had refused to teach at in 1892 due to low pay, hired Handy to teach music. He became a faculty member in September 1900 and taught through much of 1902. He was disheartened to discover that the college emphasized teaching European \"classical\" music. He felt he was underpaid and could make more money touring with a minstrel group.","Later Career And Death":"W. C. Handy in November 1949, playing trumpet in his music publishing office overlooking Times Square\nIn a 1938 radio episode of Ripley''s Believe It or Not! Handy was described as \"the father of jazz as well as the blues.\" Fellow blues performer Jelly Roll Morton wrote an open letter to Downbeat magazine fuming that he had invented jazz.\nAfter the publication of his autobiography, Handy published a book on African-American musicians, titled Unsung Americans Sung (1944). He wrote three other books: Blues: An Anthology: Complete Words and Music of 53 Great Songs, Book of Negro Spirituals, and Negro Authors and Composers of the United States. He lived on Strivers'' Row in Harlem. He became blind after an accidental fall from a subway platform in 1943.\nFrom 1943 until his death, he lived in Yonkers. His grandson is the physicist Carlos Handy (born 1950), who now leads the Handy Brothers Music Company. After the death of his first wife, he remarried in 1954 when he was 80. His bride was his secretary Irma Louise Logan, who he frequently said had become his eyes. In 1955, he had a stroke, and he began to use a wheelchair. More than 800 people attended his 84th birthday party at the Waldorf-Astoria Hotel.\nOn March 28, 1958, Handy died of bronchial pneumonia at Sydenham Hospital in New York City. Over 25,000 people attended his funeral in Harlem''s Abyssinian Baptist Church. Over 150,000 people gathered in the streets near the church to pay their respects. He was buried in Woodlawn Cemetery (Bronx, New York) in the bronx"}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (319, '1WmIo9ORq1IDlovUWFmo4Y', 'Wallace', 'Roney', '30907194-57ca-4c7f-8e10-8c2883799052', 255141, 7, 'https://en.wikipedia.org/wiki/Wallace_Roney', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Wallace_Roney_Quintet_25_maart_2015_BIM_Amsterdam_-_Wallace_Roney_%2851298397037%29.jpg/500px-Wallace_Roney_Quintet_25_maart_2015_BIM_Amsterdam_-_Wallace_Roney_%2851298397037%29.jpg', 'Dirk Neven', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Wallace_Roney_Quintet_25_maart_2015_BIM_Amsterdam_-_Wallace_Roney_(51298397037).jpg', '{"Intro":"Wallace Roney (May 25, 1960 – March 31, 2020) was an American jazz (hard bop and post-bop) trumpeter. He won one Grammy award and was nominated twice.\nRoney took lessons from Clark Terry and Dizzy Gillespie and studied with Miles Davis from 1985 until the latter''s death in 1991.  Wallace credited Davis as having helped to challenge and shape his creative approach to life as well as being his music instructor, mentor, and friend; he was the only trumpet player Davis personally mentored.","Early Life And Education":"Wallace Roney at Monterey Jazz Festival 9/92\nRoney was born in Philadelphia. He studied at Howard University and Berklee College of Music in Boston, Massachusetts, after graduating from the Duke Ellington School of the Arts of the D. C. Public Schools, where he learned trumpet with Langston Fitzgerald of the Baltimore Symphony Orchestra. Found to have perfect pitch at the age of four, Wallace began his musical and trumpet studies at Philadelphia''s Settlement School of Music.\nHe studied with trumpeter Sigmund Hering of the Philadelphia Orchestra for three years. Hering regularly presented Wallace at recitals at the Settlement School, and with the Philadelphia Brass Ensemble, during his studies in Philadelphia.","Career":"When he entered the Duke Ellington School, Roney had already made his recording debut at age 15 with Nation and Haki R. Madhubuti, and at that time met, among others, Bill Hardman, Valery Ponomarev, Woody Shaw (who befriended him), Johnny Coles and Freddie Hubbard. He played with the Cedar Walton Quartet featuring Billy Higgins, Sam Jones, and Philly Joe Jones at 16 years of age with the encouragement of his high school teacher.\nRoney attained distinction as a gifted local performer in the Washington, D.C., area. In 1979 and 1980, Roney won the DownBeat Award for Best Young Jazz Musician of the Year, and in 1989 and 1990 the DownBeat Magazine''s Critic''s Poll for Best Trumpeter to Watch.\nIn 1983, while taking part in a tribute to Miles Davis at \"The Bottom Line\" in Manhattan, he met his idol. \"He  asked me what kind of trumpet I had,\" Roney told Time magazine, \"and I told him none. So he gave me one of his.\" In 1984 and 1985, he was forced to play in Latin dance and reception bands, as the New York clubs, once a prominent part of the jazz scene, had mostly disappeared. But in 1986, he received a pair of calls, in the same month, to tour with drummers Tony Williams and Art Blakey, after which Roney became one of the most in-demand trumpet players on the professional circuit.\nIn 1986, he succeeded Terence Blanchard in Blakey''s Jazz Messengers. In the late 1980s and early 1990s, he was an integral part of Williams''s quintet. In 1991, Roney played with Davis at the Montreux Jazz Festival. After Davis''s death that year, Roney toured in memoriam with Davis alumni Wayne Shorter, Herbie Hancock, Ron Carter and Tony Williams and recorded an album, A Tribute to Miles, for which they won a Grammy Award.\nRoney learned his craft directly from Miles Davis. Critics have taken Roney to task for sounding too similar to his idol. Roney recorded his debut album as a leader, Verses, on Muse Records in 1987. A number of albums on Muse, Warner Bros. Records and Concord Records/Stretch Records followed, and by the time he turned 40 in 2000 Roney had been documented on over 250 audio recordings. His album titles from the 2000s include Mystikal (2005) and Jazz (2007) on HighNote Records. His two most recent albums are A Place in Time (HighNote 2016) and Blue Dawn - Blue Nights (HighNote 2019), which features his nephew, drummer Kojo Roney.","Personal Life":"Wallace Roney was the son of Wallace Roney, U.S. Marshal and President of the American Federation of Government Employees Local 102, grandson of Philadelphia musician Roosevelt Sherman, and older brother of tenor and soprano saxophonist Antoine Roney. In 1995, Roney married pianist Geri Allen, with whom he had two daughters and a son. The marriage ended prior to Allen''s death in 2017. The two artists collaborated on records on many occasions during the 1990s and 2000s, on records released under each artist''s name.\nEarlier in his life, Roney had been a resident of  Montclair, New Jersey.","Death":"Wallace Roney died at the age of 59 on March 31, 2020, at St. Joseph''s University Medical Center in Paterson, New Jersey. The cause was complications arising from COVID-19."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (320, '1WmIo9ORq1IDlovUWFmo4Y', 'Warne', 'Marsh', '2c409f65-1bf2-4746-9f52-6954891fe30f', 259089, 6, 'https://en.wikipedia.org/wiki/Warne_Marsh', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Internationale_Jazz_Festival_Amsterdam_121314_augustus_Warne_Marsh_Quartet_%2C_M%2C_Bestanddeelnr_932-2807.jpg/500px-Internationale_Jazz_Festival_Amsterdam_121314_augustus_Warne_Marsh_Quartet_%2C_M%2C_Bestanddeelnr_932-2807.jpg', 'Rob Bogaerts / Anefo', 'CC0', 'https://commons.wikimedia.org/wiki/File:Internationale_Jazz_Festival_Amsterdam_121314_augustus_Warne_Marsh_Quartet_,_M,_Bestanddeelnr_932-2807.jpg', '{"Intro":"Warne Marion Marsh (October 26, 1927 – December 18, 1987) was an American tenor saxophonist. Born in Los Angeles, his playing first came to prominence in the 1950s as a protégé of pianist Lennie Tristano and earned attention in the 1970s as a member of Supersax.","Biography":"Marsh came from an affluent artistic background: his father was Hollywood cinematographer Oliver T. Marsh (1892–1941), and his mother Elizabeth was a violinist. He was the nephew of actresses Mae Marsh and Marguerite Marsh and film editor Frances Marsh.\nHe was tutored by Lennie Tristano. Marsh was often recorded in the company of other Cool School musicians, and remained one of the most faithful to the Tristano philosophy of improvisation – the faith in the purity of the long line, the avoidance of licks and emotional chain-pulling, the concentration on endlessly mining the same small body of jazz standards. While Marsh was a generally cool-toned player, the critic Scott Yanow notes that Marsh played with \"more fire than one would expect\" in certain contexts.\nMarsh''s rhythmically subtle lines are immediately recognizable. He has been called by Anthony Braxton \"the greatest vertical improviser\" (i.e., improvising that emphasizes harmony/chords more than melody). In the 1970s, he gained renewed exposure as a member of Supersax, a large ensemble which played orchestral arrangements of Charlie Parker solos. Marsh also recorded one of his most celebrated albums, All Music, with the Supersax rhythm section during this period.\nMarsh died of a heart attack onstage at the Los Angeles club Donte''s in 1987, in the middle of playing the tune \"Out of Nowhere\". He left a widow, Geraldyne Marsh, and two sons, K.C. Marsh and Jason Marsh. He is interred at Forest Lawn Memorial Park in Glendale, California.\nThough he remains something of a cult figure among jazz fans and musicians, his influence has grown since his death; younger players such as Mark Turner have borrowed from his music as a way of counterbalancing the pervasive influence of John Coltrane.  Marsh''s discography remains somewhat scattered and elusive, as much of it was done for small labels, but more and more of his work has been issued on compact disc in recent years.\nA documentary is being made about him: Warne Marsh: An Improvised Life, directed by his eldest son, K.C. Marsh."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (321, '1WmIo9ORq1IDlovUWFmo4Y', 'Warren', 'Vache', '70bb863c-2539-49c2-8d8d-3712afbe24c8', 357565, 7, 'https://en.wikipedia.org/wiki/Warren_Vaché_Jr.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Warren_Vach%C3%A9_Jr._DSC0046.jpg/500px-Warren_Vach%C3%A9_Jr._DSC0046.jpg', 'Marek Lazarski', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Warren_Vach%C3%A9_Jr._DSC0046.jpg', '{"Intro":"Warren Vaché Jr. (born February 21, 1951) is an American jazz trumpeter, cornetist, and flugelhornist. He came from a musical family as his father was a bassist. In 1976, he released his first album. He has often worked with Scott Hamilton and has some popularity among swing audiences.\nBorn and raised in Rahway, New Jersey, Vaché graduated from Rahway High School, where he played in the marching band.\nWarren Vaché''s father is Warren Vaché Sr., who was a jazz double-bassist. His brother Allan Vaché is also a musician."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (322, '1WmIo9ORq1IDlovUWFmo4Y', 'Wayne', 'Shorter', '2379937f-6e0d-46a2-b8ff-633fafd72002', 29979, 6, 'https://en.wikipedia.org/wiki/Wayne_Shorter', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Wayne-Shorter_in_Amsterdam%2C_1980.jpg/500px-Wayne-Shorter_in_Amsterdam%2C_1980.jpg', 'Chris Hakkens', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Wayne-Shorter_in_Amsterdam,_1980.jpg', '{"Intro":"Wayne Shorter (August 25, 1933 – March 2, 2023) was an American jazz saxophonist, composer, and bandleader, widely regarded as one of the most important and influential figures in the history of modern jazz. Over a career spanning more than six decades, he received 12 Grammy Awards and the Polar Music Prize, and was acclaimed worldwide for his originality, compositional depth, and transformative approach to musical improvisation.\nShorter first rose to mainstream prominence in 1959 after joining Art Blakey’s Jazz Messengers, where he quickly became the ensemble’s primary composer and one of its defining creative voices. In 1964, he joined Miles Davis’s Second Great Quintet, contributing compositions and performances that helped shape one of the most innovative and influential periods in jazz history. In 1970, he co-founded the jazz fusion band Weather Report, which achieved international success and redefined the possibilities of electric jazz.\nAs a bandleader, Shorter recorded more than 20 albums, and many of his compositions—including works written for Davis, Weather Report, and his own groups—became enduring jazz standards. His music is noted for its harmonic sophistication, narrative structure, and philosophical depth, earning sustained critical praise and influence across generations of musicians.\nShorter was especially acclaimed for his mastery of the soprano saxophone, having shifted his primary focus from the tenor in the late 1960s. Beginning in 1970, he dominated DownBeat magazine’s annual critics’ and readers’ polls on soprano saxophone, winning the critics’ poll for 10 consecutive years and the readers’ poll for 18.\nIn 2008, The New York Times music critic Ben Ratliff described Shorter as “probably jazz’s greatest living small-group composer and a contender for greatest living improviser,” a characterization that reflected his towering status within the genre.","Early Life And Education":"Wayne Shorter was born in Newark, New Jersey, the son of Louise and Joseph Shorter. He graduated from Newark Arts High School in 1952. Encouraged by his parents, Shorter began taking clarinet lessons at age 16 and later switched to tenor saxophone. While in high school, Wayne performed with the Nat Phipps Band in Newark. His older brother Alan played alto saxophone before switching to the trumpet in college.\nShorter enrolled at New York University in 1952 and graduated with a degree in music education in 1956. After graduating, Shorter spent two years in the U.S. Army, during which time he played briefly with Horace Silver. After his discharge, he played with Maynard Ferguson.\nWhile growing up, Shorter loved comic books and science fiction as well as music. In his youth, Shorter acquired the nickname \"Mr. Gone\", which later became an album title for Weather Report.","Career":"This section needs additional citations for verification. Please help improve this article by adding citations to reliable sources in this section. Unsourced material may be challenged and removed.Find sources: \"Wayne Shorter\" – news · newspapers · books · scholar · JSTOR  (March 2023) (Learn how and when to remove this message)\nHis early influences include Sonny Rollins, John Coltrane and Coleman Hawkins. In 1959, Shorter joined Art Blakey''s Jazz Messengers where he stayed for four years, eventually becoming musical director and composing pieces for the band. Together they toured the US, Japan, and Europe, recording several albums. During this time, Shorter \"established himself as one of the most gifted of the young saxophonists\" and received international acknowledgment.\nHerbie Hancock said of Shorter''s tenure in Miles Davis''s Second Great Quintet: \"The master writer to me, in that group, was Wayne Shorter. He still is a master. Wayne was one of the few people who brought music to Miles that didn''t get changed.\" Davis said, \"Wayne is a real composer. He writes scores, writes the parts for everybody, just as he wants them to sound. ... Wayne also brought in a kind of curiosity about working with musical rules. If they didn''t work, then he broke them, but with musical sense; he understood that freedom in music was the ability to know the rules, in order to bend them to your own satisfaction and taste.\"\nIan Carr, musician and Rough Guide author, said that with Davis, Shorter found his own voice as a player and composer. \"Blakey''s hard-driving, straight-ahead rhythms had brought out the muscularity in Shorter''s tenor playing, but the greater freedom of the Davis rhythm-section allowed him to explore new emotional and technical dimensions.\"\nShorter remained in Davis''s band after the breakup of the quintet in 1968, playing on early jazz fusion recordings including In a Silent Way and Bitches Brew (both 1969). His last live dates and studio recordings with Davis were in 1970.\nUntil 1968, he played tenor saxophone exclusively. The final album on which he played tenor in the regular sequence of Davis albums was Filles de Kilimanjaro. In 1969, he played the soprano saxophone on the Davis album In a Silent Way and on his own Super Nova (recorded with then-current Davis sidemen Chick Corea and John McLaughlin). When performing live with Davis, and on recordings from summer 1969 to early spring 1970, he played both soprano and tenor saxophones: by the early 1970s, however, he chiefly played soprano.\nSimultaneous with his time in the Davis quintet, Shorter recorded several albums for Blue Note Records, featuring, almost exclusively, his own compositions, with a variety of line-ups, quartets and larger groups, including Blue Note favorites such as trumpeter Freddie Hubbard. His first Blue Note album (of 11 in total recorded from 1964 to 1970) was Night Dreamer, recorded at Rudy Van Gelder''s studio in 1964 with Lee Morgan (trumpet), McCoy Tyner (piano), Reggie Workman (bass) and Elvin Jones (drums). Two more albums were recorded in 1964, JuJu and Speak No Evil.\nOf the three Blue Note albums Shorter recorded in 1965, The All Seeing Eye (rec. 1965, rel. 1966) was a workout with a larger group, while Adam''s Apple (rec. 1966, rel. 1967) was back to carefully constructed melodies by Shorter leading a quartet. Then a sextet again in the following year for Schizophrenia (rec. 1967, rel. 1969) with Herbie Hancock, bassist Ron Carter, trombonist Curtis Fuller, alto saxophonist/flautist James Spaulding and strong rhythms by drummer Joe Chambers.\nShorter also recorded occasionally as a sideman (again mainly for Blue Note) with trumpeter Donald Byrd, McCoy Tyner, trombonist Grachan Moncur III, Freddie Hubbard, Lee Morgan, as well as bandmates Herbie Hancock and drummer Tony Williams.\nFollowing the release of Odyssey of Iska in 1970, Shorter formed the fusion group Weather Report with Davis veteran keyboardist Joe Zawinul and bassist Miroslav Vitouš. The other original members were percussionist Airto Moreira, and drummer Alphonse Mouzon. After Vitouš''s departure in 1973, Shorter and Zawinul co-led the group until the band''s break-up in late 1985. A variety of musicians would make up Weather Report over the years (most notably the revolutionary bassist Jaco Pastorius and drummers Peter Erskine and Omar Hakim) helping the band produce many high quality recordings in diverse styles, with funk, bebop, Latin jazz, ethnic music, and futurism being the most prevalent denominators.\nShorter also recorded critically acclaimed albums as a bandleader, notably 1974''s Native Dancer, which featured Hancock and Brazilian composer and vocalist Milton Nascimento.\nShorter at the UC Berkeley Jazz Festival, May 25, 1980\nIn the late 1970s and the early 1980s, he toured in the V.S.O.P. quintet. This group was a revival of the 1960s Davis quintet, except that Freddie Hubbard filled the trumpet chair. Shorter appeared with the same former Davis bandmates on the Carlos Santana double LP The Swing of Delight (1980), for which he also composed a number of pieces.\nFrom 1977 through 2002, he appeared on 10 Joni Mitchell studio albums, gaining him a wider audience. He played an extended solo on the title track of Steely Dan''s 1977 album Aja.\nAfter leaving Weather Report in 1986, Shorter continued to record and lead groups in jazz fusion styles, including touring in 1988 with guitarist Carlos Santana, who appeared on This is This! (1986), the last Weather Report disc. There is a concert video recorded at the Lugano Jazz Festival in 1987, with Jim Beard (keyboards), Carl James (bass), Terri Lyne Carrington (drums), and Marilyn Mazur (percussion). In 1989, he contributed to a hit on the rock charts, playing the soprano saxophone solo on Don Henley''s song \"The End of the Innocence\" and also produced the album Pilar by the Portuguese singer-songwriter Pilar Homem de Melo. He also maintained an occasional working relationship with Herbie Hancock, including a tribute album recorded shortly after Miles Davis''s death with Herbie Hancock, Ron Carter, Tony Williams and Wallace Roney. He continued to appear on Mitchell''s records in the 1990s and can be heard on the soundtrack of the Harrison Ford film The Fugitive (1993).\nIn 1995, Shorter released the album High Life, his first solo recording for seven years. It was also his debut as a leader for Verve Records. Shorter composed all the compositions on the album and co-produced it with the bassist Marcus Miller with pianist, synthesist, and sound designer Rachel Z. High Life received the Grammy Award for Best Contemporary Jazz Album in 1996.\nShorter worked with Herbie Hancock once again in 1997, on the much acclaimed and heralded album 1+1. The song \"Aung San Suu Kyi\" (named for the Burmese pro-democracy activist) won both Hancock and Shorter a Grammy Award.\nIn 2009, he was announced as one of the headline acts at the Gnaoua World Music Festival in Essaouira, Morocco. His 2013 live album Without a Net (rec. 2010) is his first with Blue Note Records since Odyssey of Iska (rec. 1970, rel. 1971).\nThe Wayne Shorter Quartet at the Teatro degli Arcimboldi, Milan, 2010\nIn 2000, Shorter formed the first permanent acoustic group under his name, a quartet with pianist Danilo Perez, bassist John Patitucci, and drummer Brian Blade, playing his own compositions, many of them reworkings of tunes going back to the 1960s. Four albums of live recordings have been released: Footprints Live! (rec. live 2001, rel. 2002); Beyond the Sound Barrier (rec. live 2002–2004, rel. 2005); Without a Net (rec. live 2010, rel. 2013); and Emanon (2018), with the latter, in addition to live material, including Shorter''s quartet in a studio session with the 34-piece Orpheus Chamber Orchestra. The quartet has received great acclaim from fans and critics, especially for the strength of Shorter''s tenor saxophone playing. The biography Footprints: The Life and Work of Wayne Shorter by journalist Michelle Mercer examines the working life of the musicians as well as Shorter''s thoughts and Buddhist beliefs. Beyond the Sound Barrier received the 2006 Grammy Award for Best Jazz Instrumental Album.\nShorter''s 2003 album Alegría (his first studio album for 10 years, since High Life) received the 2004 Grammy Award for Best Jazz Instrumental Album; it features the quartet with a host of other musicians, including pianist Brad Mehldau, drummer Terri Lyne Carrington and former Weather Report percussionist Alex Acuña. Shorter''s compositions, some new, some reworked from his Miles Davis period, feature the complex Latin rhythms that he specialized in during his Weather Report days.\nIn 2015, producer/director Dorsay Alavi began filming a documentary about the life of Wayne Shorter called Wayne Shorter: Zero Gravity. A number of high-profile musicians, including Herbie Hancock, Esperanza Spalding, and Terri Lyne Carrington, performed at a donor event to raise funds for the documentary; two of the largest donations came from the Herb Alpert Foundation and Carlos Santana. In 2018, a four-hour preliminary cut was completed. Subsequently, Brad Pitt joined the project with his production company. After some delay, partly due to the Covid crisis, from August 2023, the documentary is available as a three-hour miniseries on Amazon Prime Video.\nIn 2016, it was announced that Shorter, Carlos Santana, and Herbie Hancock would begin touring under the name Mega Nova. Also included within the supergroup was bassist Marcus Miller and drummer Cindy Blackman Santana. Their first show together was on August 24, 2016, at the Hollywood Bowl.\nIn 2018, Shorter retired from his near 70-year performing career due to health issues. He continued working as a composer, creating a \"new operatic work\" titled Iphigenia, a loose adaptation of the ancient Greek myth; with Esperanza Spalding writing the libretto and architect Frank Gehry designing the sets, which premiered on November 12, 2021, at the Cutler Majestic Theatre.","Later Career":"After leaving Weather Report in 1986, Shorter continued to record and lead groups in jazz fusion styles, including touring in 1988 with guitarist Carlos Santana, who appeared on This is This! (1986), the last Weather Report disc. There is a concert video recorded at the Lugano Jazz Festival in 1987, with Jim Beard (keyboards), Carl James (bass), Terri Lyne Carrington (drums), and Marilyn Mazur (percussion). In 1989, he contributed to a hit on the rock charts, playing the soprano saxophone solo on Don Henley''s song \"The End of the Innocence\" and also produced the album Pilar by the Portuguese singer-songwriter Pilar Homem de Melo. He also maintained an occasional working relationship with Herbie Hancock, including a tribute album recorded shortly after Miles Davis''s death with Herbie Hancock, Ron Carter, Tony Williams and Wallace Roney. He continued to appear on Mitchell''s records in the 1990s and can be heard on the soundtrack of the Harrison Ford film The Fugitive (1993).\nIn 1995, Shorter released the album High Life, his first solo recording for seven years. It was also his debut as a leader for Verve Records. Shorter composed all the compositions on the album and co-produced it with the bassist Marcus Miller with pianist, synthesist, and sound designer Rachel Z. High Life received the Grammy Award for Best Contemporary Jazz Album in 1996.\nShorter worked with Herbie Hancock once again in 1997, on the much acclaimed and heralded album 1+1. The song \"Aung San Suu Kyi\" (named for the Burmese pro-democracy activist) won both Hancock and Shorter a Grammy Award.\nIn 2009, he was announced as one of the headline acts at the Gnaoua World Music Festival in Essaouira, Morocco. His 2013 live album Without a Net (rec. 2010) is his first with Blue Note Records since Odyssey of Iska (rec. 1970, rel. 1971).\nThe Wayne Shorter Quartet at the Teatro degli Arcimboldi, Milan, 2010\nIn 2000, Shorter formed the first permanent acoustic group under his name, a quartet with pianist Danilo Perez, bassist John Patitucci, and drummer Brian Blade, playing his own compositions, many of them reworkings of tunes going back to the 1960s. Four albums of live recordings have been released: Footprints Live! (rec. live 2001, rel. 2002); Beyond the Sound Barrier (rec. live 2002–2004, rel. 2005); Without a Net (rec. live 2010, rel. 2013); and Emanon (2018), with the latter, in addition to live material, including Shorter''s quartet in a studio session with the 34-piece Orpheus Chamber Orchestra. The quartet has received great acclaim from fans and critics, especially for the strength of Shorter''s tenor saxophone playing. The biography Footprints: The Life and Work of Wayne Shorter by journalist Michelle Mercer examines the working life of the musicians as well as Shorter''s thoughts and Buddhist beliefs. Beyond the Sound Barrier received the 2006 Grammy Award for Best Jazz Instrumental Album.\nShorter''s 2003 album Alegría (his first studio album for 10 years, since High Life) received the 2004 Grammy Award for Best Jazz Instrumental Album; it features the quartet with a host of other musicians, including pianist Brad Mehldau, drummer Terri Lyne Carrington and former Weather Report percussionist Alex Acuña. Shorter''s compositions, some new, some reworked from his Miles Davis period, feature the complex Latin rhythms that he specialized in during his Weather Report days.\nIn 2015, producer/director Dorsay Alavi began filming a documentary about the life of Wayne Shorter called Wayne Shorter: Zero Gravity. A number of high-profile musicians, including Herbie Hancock, Esperanza Spalding, and Terri Lyne Carrington, performed at a donor event to raise funds for the documentary; two of the largest donations came from the Herb Alpert Foundation and Carlos Santana. In 2018, a four-hour preliminary cut was completed. Subsequently, Brad Pitt joined the project with his production company. After some delay, partly due to the Covid crisis, from August 2023, the documentary is available as a three-hour miniseries on Amazon Prime Video.\nIn 2016, it was announced that Shorter, Carlos Santana, and Herbie Hancock would begin touring under the name Mega Nova. Also included within the supergroup was bassist Marcus Miller and drummer Cindy Blackman Santana. Their first show together was on August 24, 2016, at the Hollywood Bowl.\nIn 2018, Shorter retired from his near 70-year performing career due to health issues. He continued working as a composer, creating a \"new operatic work\" titled Iphigenia, a loose adaptation of the ancient Greek myth; with Esperanza Spalding writing the libretto and architect Frank Gehry designing the sets, which premiered on November 12, 2021, at the Cutler Majestic Theatre.","Personal Life":"Shorter met Teruko (Irene) Nakagami in 1961. They married and had a daughter, Miyako. Some of his compositions are copyrighted as \"Miyako Music\" and Shorter dedicated the pieces \"Miyako\" and \"Infant Eyes\" to his daughter. The couple separated in 1964.\nShorter met Ana Maria Patricio in 1966 and they married in 1970. In 1986, their daughter Iska died of a grand mal seizure at age 14. Ana Maria and the couple''s niece, Dalila, were killed on July 17, 1996 in the crash of TWA Flight 800, while traveling to visit Shorter in Italy. Dalila was the daughter of Ana Maria Shorter''s sister and her husband, jazz vocalist Jon Lucien.\nIn 1999, Shorter married Carolina Dos Santos, a close friend of Ana Maria.\nComposer and producer Rick Shorter (1934–2017) was Shorter''s cousin.\nShorter practiced Nichiren Buddhism for more than 50 years as a longtime member of the Buddhist association Soka Gakkai International.\nSinger and actress Tina Turner credits Shorter with saving her life. In Turner''s 2020 spiritual memoir Happiness Becomes You, she states that Shorter and Ana Maria gave her critical refuge at their home for six months in 1976 after Turner left her abusive husband, Ike Turner.\nShorter died in Los Angeles, California, on March 2, 2023, aged 89."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (323, '1WmIo9ORq1IDlovUWFmo4Y', 'Wes', 'Montgomery', '663f8232-8c46-4851-803f-a91d31593b14', 129805, 2, 'https://en.wikipedia.org/wiki/Wes_Montgomery', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Wes_Montgomery_%281967_Gibson_portrait%29.jpg/500px-Wes_Montgomery_%281967_Gibson_portrait%29.jpg', 'Photo first published by Gibson. According to NPR, the photo was taken by Chuck Stewart.', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Wes_Montgomery_(1967_Gibson_portrait).jpg', '{"Intro":"John Leslie \"Wes\" Montgomery (March 6, 1923 – June 15, 1968) was an American jazz guitarist. Montgomery was known for his unusual technique of plucking the strings with the side of his thumb and for his extensive use of octaves, which gave him a distinctive sound.\nMontgomery often worked with his brothers Buddy (Charles F.) and Monk (William H.), as well as organist Melvin Rhyne. His recordings up to 1965 were oriented toward hard bop, soul jazz, and post bop, but around 1965 he began recording more pop-oriented instrumental albums that found mainstream success. His later guitar style influenced jazz fusion and smooth jazz.","Early Life And Education":"Montgomery was born in Indianapolis, Indiana. According to NPR, the nickname \"Wes\" was a child''s mispronunciation of his middle name, Leslie. His family was large, and his parents split up early in his childhood. Montgomery and his brothers moved to Columbus, Ohio, with their father and attended Champion High School. His older brother Monk dropped out of school to sell coal and ice, gradually saving enough money to buy Wes a four-string tenor guitar from a pawn shop in 1935. Although Montgomery spent many hours playing that guitar, he dismissed its usefulness, saying he had to start over when he got his first six-string several years later.","Career":"This section relies largely or entirely on a single source. Relevant discussion may be found on the talk page. Please help improve this article by introducing citations to additional sources at this section. Unsourced material may be challenged and removed.Find sources: \"Wes Montgomery\" – news · newspapers · books · scholar · JSTOR  (September 2021) (Learn how and when to remove this message)Montgomery in a mid-1960s publicity photo shot by Bruno of Hollywood studios for Verve Records\nHe and his brothers returned to Indianapolis. By 1943, Montgomery was working as a welder and had gotten married. While at a dance with his wife, he heard a Charlie Christian record for the first time. This experience inspired him to pick up the guitar at the age of 19, and he spent the next year teaching himself to play by imitating Christian''s recordings. Although he had not planned on becoming a professional musician, he felt obligated to learn after purchasing the guitar. Montgomery did not receive any formal instruction and could not read music. By the age of twenty, he was performing in clubs in Indianapolis at night, copying Christian''s solos, while working during the day at a milk company. In 1948, when Lionel Hampton was on tour in Indianapolis, he was looking for a guitarist, and after hearing Montgomery play like Christian he hired him.\nMontgomery spent two years with the Hampton band. Fear kept him from flying with the rest of the band, so he drove from city to city, town to town, while fellow musicians marveled at his stamina. When arriving at a club, the first thing he did was call home to his wife and family. He was given the opportunity to play with Charles Mingus, Milt Buckner, and Fats Navarro, but not the opportunity he hoped for , and he returned to Indianapolis a better player, though tired and discouraged. He resumed performing at local clubs, this time with the Eddie Higgins Trio and the Roger Jones Quintet, playing with  Eddie Higgins, Walter Perkins, and Leroy Vinnegar. He joined his brothers Buddy and Monk and saxophonist Alonzo \"Pookie\" Johnson in the Johnson/Montgomery Quintet, somewhat in the style of George Shearing. The band auditioned for Arthur Godfrey and recorded sessions with Quincy Jones. After a residency at a club from 1955 to 1957, Montgomery and his brothers went west.\nBuddy and Monk Montgomery formed The Mastersounds and signed a contract with Dick Bock at Pacific Jazz. Montgomery joined them for a recording session in 1957 that included Freddie Hubbard. Some of the songs were released by Pacific Jazz on the album The Montgomery Brothers and Five Others, while others were issued on Fingerpickin'' (Pacific Jazz, 1958). The Mastersounds remained in California when Montgomery returned to Indianapolis to work in his trio with organist Melvin Rhyne.\nHe worked as a welder during the day to support his wife and seven children, then performed at two clubs at night until well into the morning. He was a smoker who had blackouts while trying to maintain this busy schedule. During one performance, the audience included Cannonball Adderley, George Shearing, and Lennie Tristano. Adderley was so impressed by Montgomery''s guitar playing that he persuaded Orrin Keepnews to sign him to Riverside. Keepnews was also persuaded by a gushing review written by Gunther Schuller. In New York City Montgomery recorded A Dynamic New Sound, the Wes Montgomery Trio, his first album as a leader after twenty years as a musician. In 1960, he recorded The Incredible Jazz Guitar of Wes Montgomery with Tommy Flanagan, Percy Heath, and Albert Heath.\nHe joined his brothers in California to perform as the Montgomery Brothers for the Monterey Jazz Festival. The Mastersounds had broken up, and Buddy and Monk had signed with Fantasy and recorded (with Wes) The Montgomery Brothers, followed by Groove Yard. Montgomery recorded another album as a leader, So Much Guitar, then while visiting his brothers had a chance to perform with John Coltrane''s group in San Francisco. In 1961, work was getting harder to find. A tour in Canada led to the album The Montgomery Brothers in Canada, then the band broke up. Montgomery returned to Indianapolis to work in his trio with Rhyne. Keepnews sent him back to California to record a live album with Johnny Griffin, Wynton Kelly, Paul Chambers, and Jimmy Cobb. Their performance became the album Full House. This was followed by Fusion! (1963), his first instrumental pop album.\nAfter two more organ trio jazz sessions for Riverside Records in 1963 (Boss Guitar and Portrait of Wes), Montgomery left the label for Verve Records. At Verve, Montgomery began working with producer Creed Taylor, who produced Montgomery for the rest of the guitarist''s life. His first Verve release, Movin'' Wes (1964), was an instrumental pop album arranged by Johnny Pate. It quickly sold more than 100,000 copies and repositioned Montgomery within the recording industry as a crossover artist capable of significant LP sales. At Verve, Montgomery released his last two small-group jazz albums  (a 1965 collaboration with Wynton Kelly, and a 1966 collaboration with organist Jimmy Smith), but his main focus was recording contemporary pop hits as instrumentals. Montgomery had notable success with his versions of \"California Dreamin''\", \"Tequila\", and \"Goin'' Out of My Head\". After moving to A&M, Montgomery had his biggest radio hit, a version of \"Windy\", a pop song originally recorded by The Association. Of the ten Wes Montgomery albums that Taylor produced while Montgomery was alive (all recorded for Verve and A&M Records), eight were aimed at the pop market. The success of these albums led to invitations for Montgomery to perform on major U.S. television shows including The Hollywood Palace and The Tonight Show Starring Johnny Carson.","Death":"Montgomery died of a heart attack on June 15, 1968, while at home in Indianapolis. He was 45 years old.Montgomery in 1967","Artistry":"According to jazz guitar educator Wolf Marshall, Montgomery often approached solos in a three-tiered manner: he would begin the progression with single note lines, derived from scales or modes; after a fitting number of sequences, he would play octaves for a few more sequences, finally culminating with block chords. He used mostly superimposed triads and arpeggios as the main source for his soloing ideas and sounds.\nInstead of using a guitar pick, Montgomery plucked the strings with the fleshy part of his thumb, using down strokes for single notes and a combination of up strokes and down strokes for chords and octaves. He developed this technique not for technical reasons but for the benefit of his neighbors and not waking his children. He worked long hours as a machinist before his music career began and practised late at night. To keep everyone happy, he played quietly by using his thumb. This actually worked out well, as he used an amplifier when performing, which allowed him to really exploit his thumb-picking style. His style smoothly incorporated the guitar into jazz and was studied by many.\nMontgomery was also known for his use of octaves in his playing. In an interview with music critic Ralph J. Gleason, Montgomery was quoted saying: \"Playing octaves was just a coincidence. And it''s still such a challenge. I used to have headaches every time I played octaves, because it was extra strain, but the minute I''d quit I''d be alright. I don''t know why, but it was my way, and my way just backfired on me. But now I don''t have headaches when I play octaves. I''m just showing you how a strain can capture a cat and almost choke him, but after a while it starts to ease up because you get used to it.\"","Legacy":"Jazz guitarist Bobby Broom said that on A Dynamic New Sound in 1959, Montgomery \"introduced a brand new approach to playing the guitar... The octave technique... and his chord melody and chord soloing playing still is today unmatched\". Broom modeled his guitar-organ trio after Montgomery''s."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (324, '1WmIo9ORq1IDlovUWFmo4Y', 'Wilbur', 'Ware', 'd8718343-cdc1-49bb-b8cb-d241e5d16b79', 258089, 1, 'https://en.wikipedia.org/wiki/Wilbur_Ware', NULL, NULL, NULL, NULL, '{"Intro":"Wilbur Bernard Ware (September 8, 1923 – September 9, 1979) was an American jazz double bassist. He was a regular bassist for the Riverside record label in the 1950s, and recorded regularly in that decade with Johnny Griffin, Kenny Dorham, Kenny Drew, and Thelonious Monk. He also appeared on records released by J.R. Monterose, Toots Thielemans, Sonny Clark, Tina Brooks, Zoot Sims, Archie Shepp and Grant Green, among others.","Career":"Ware grew up in Chicago where he taught himself to play drums, banjo, bass while playing at church. In the 1940s, he worked with Stuff Smith, Sonny Stitt, and Roy Eldridge. He recorded with Sun Ra in the early 1950s. Later in the 1950s, settling in New York City, Ware played with Eddie Vinson, Art Blakey, and Buddy DeFranco. His only album recorded as a leader and released during his lifetime was The Chicago Sound, from 1957 when he worked for Riverside. He made jazz instructional albums for Music Minus One. In 1958, Ware was one of 57 jazz musicians to appear in the photograph A Great Day in Harlem.\nWare was a member of the Thelonious Monk quartet from 1957 to 1958. He also performed and recorded in 1957 with the Sonny Rollins Trio at the Village Vanguard. Largely self taught, Ware had an unorthodox but highly unique and percussive approach to the bass.\nWare''s addiction to narcotics resulted in his return to Chicago in 1963, and then to a period of incarceration. He was inactive musically for about six years. In 1969, Ware played with Clifford Jordan, Elvin Jones and Sonny Rollins. He died from emphysema in Philadelphia, Pennsylvania, in 1979."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (325, '1WmIo9ORq1IDlovUWFmo4Y', 'Willie The Lion', 'Smith', '5daad4be-e76b-40cd-9dba-459a02451e83', 307444, 3, 'https://en.wikipedia.org/wiki/Willie_"the_Lion"_Smith', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Willie_Smith_%28Gottlieb_07921%29.jpg/500px-Willie_Smith_%28Gottlieb_07921%29.jpg', 'William P. Gottlieb', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Willie_Smith_(Gottlieb_07921).jpg', '{"Intro":"William Henry Joseph Bonaparte Bertholf Smith (November 23, 1893 – April 18, 1973), nicknamed \"the Lion\", was an American jazz and stride pianist.","Early Life And Education":"William Henry Joseph Bonaparte Bertholf, known as Willie, was born in 1893 in Goshen, New York. His mother and grandmother chose his names to reflect different parts of his heritage: Joseph after Saint Joseph (Bible), Bonaparte (French), and Bertholf (biological father''s last name). William and Henry were added for \"spiritual balance\". When he was three, his mother married John Smith, and Smith was added as the boy''s surname, after his stepfather.\nIn his memoir Smith reports that his father, Frank Bertholf (incorrectly spelled Bertholoff in many sources), was Jewish. Smith''s New York birth record shows him as William H. Bertholf, with father, Frank Bertholf, an electrician from nearby Monroe, New York. Smith became at least somewhat conversant in Yiddish and studied Hebrew with children of a Jewish family who were clients of his mother''s. He made his bar mitzvah at age thirteen in Newark.\nHis mother, Ida Oliver, had \"Spanish, Negro, and Mohawk Indian blood\". Her mother, Ann Oliver, was a banjo player and had been in Primrose and West minstrel shows (Smith also had two cousins who were dancers in the shows, Etta and John Bloom). According to Ida, \"Frank Bertholoff  was a light-skinned playboy who loved his liquor, girls, and gambling.\" She threw Frank out of the house when their son Willie was two years old. After Frank Bertholf died in 1901, his mother married John Smith, a master mechanic from Paterson, New Jersey. When Willie was three, his mother and stepfather added the surname Smith to his legal name. He grew up in a large family with his mother and stepfather in Newark, New Jersey at 76 Academy Street.\nJohn Smith worked for C.M. Bailey, Pork Packers, and he would leave the house around midnight to pick up freshly killed pigs and take them to the packing house. He was supposed to be home by 4 am, but would usually go to bars after work. Eventually, Ida tasked the boy Willie with accompanying his stepfather to work in order to encourage him to come straight home and not go drinking. Willie said he enjoyed this task, but most of the time he had to drive the horses home. He only worked on Fridays and Saturdays, as his mother did not want him to miss school.\nHe later wrote in his memoir about being at the slaughterhouse with his stepfather:\nI couldn''t stand to see what I saw at the slaughterhouse. I would watch wide-eyed as the squealing pigs slid down the iron rails to the cutter where they were slashed through the middle, with the two halves falling into a tank of hot water. The kill sometimes went to as many as four hundred pigs a night. It was a sickening sight to watch. But the cries from the pigs brought forth an emotional excitement. It was another weird but musical sound that I can still hear in my head. The squeaks, the squeals, the dipping them in hot water, they put them on a hook, take off the head, the legs, going down an aisle—I hear it on an oboe. That''s what you hear in a symphony: destruction, war, peace, beauty, all mixed.\nIn 1907, the family moved to 90 Bloome Street in Newark. They moved again around 1912, when his stepfather got a new job at Crucible Steel Company, across the Passaic River in Harrison, New Jersey. The job paid more, and Willie was assigned to get him away from work before his bosses got him drunk on his own money.\nHe attended the Baxter School, rumored to be a school for bad children. The school was notorious for brawls among the ethnic Irish, Italian, and African-American children. One day Willie was in Mrs. Black''s fruit store and was caught with his hand in her register. According to his memoir, Smith had  wanted to borrow a dime to see S.H. Dudley''s traveling road show at Blaney''s Theater. The owner shocked Willie by turning him over to the police. Mrs. Black''s son-in-law was the number three tough guy in Newark; reportedly the family hated policemen and generally would not allow them into their store. Willie was charged in children''s court and sentenced to a ten dollar fine and probation.\nAfter that incident, he was transferred to Morton School (which had a lot less brawling), and began sixth grade. He attended Barringer High School (then known as Newark High School). In an effort to get the attention of girls, he attempted a variety of sports, including swimming, skating, track, basketball, sledding, cycling, and boxing. He learned to swim in the Morris Canal.\nPrizefighting was the sport he was most interested in. Smith has said that \"maybe that because I''ve known most of the great fighters from way back. They liked to visit the night clubs ...\". He got to kid around with Jack Johnson, Jack Dempsey, Battling Siki, Kid Chocolate, Sam Langford, Joe Gans, Bob Fitzsimmons, Harry Greb, Joe Louis, and Gene Tunney. Fitzsimmons owned a saloon on Market Street in Newark. It was where Smith learned about Stanley Ketchel, Kid McCoy, Benny Leonard, Jimmy Britt, and Charlie Warner.\nSmith also joined a gang; their club was called The Ramblers (two members were Abner Zwillman and Niggy Rutman). He was one of two African Americans in the gang; the other was Louis Moss, who Smith called a \"sweet talker, who could take his foes apart\". Moss later became known as \"Big Sue\" and owned a saloon in the Tenderloin, Manhattan. Moss acted as his own bouncer at his club (according to Smith, Moss was 6''4\" and about 240 pounds). Smith used to play piano in his back room to help him out.","Music Career":"When Willie was about six, he discovered an organ in the lower house, which his mother used to play. It had deteriorated and nearly half the keys were missing. After his mother saw he was interested in it, she taught him the melodies she knew. One of the first songs he learned was \"Home! Sweet Home!\". His uncle Rob, a bass singer who ran his own quartet, taught Willie how to dance. The boy entered an amateur dance contest at the Arcadia Theater and won first place, including a prize of ten dollars. After that, he focused more on playing music at the clubs.\nWillie had wanted a new piano very badly, but every time he thought his mother was able to afford it, there was a new mouth to feed. Willie got a job at Hauseman''s Footwear store shining shoes and running errands, where he was paid five dollars a week. \"Old Man\" Hauseman paid that much because he was pleased that Willie could speak Yiddish and also because Willie wanted to buy a piano with the money. As it turned out, piano sellers Marshall & Wendell''s was holding a contest: the object was to guess how many dots there were in a printed circle in their newspaper advertisement. Willie used arithmetic to help guess the number, won, and was delivered an upright piano the next day. He played the piano from then on.  He would play songs he heard in the clubs, including \"Maple Leaf Rag\" by Scott Joplin, \"Cannonball Rag\" by Joe Northrup, \"Black and White Rag\" by George Botsford, and \"Don''t Hit that Lady Dressed in Green\", about which he said \"the lyrics to this song were a sex education, especially for a twelve year old boy.\" His other favorites picked up from the saloons were \"She''s Got Good Booty\" and \"Baby, Let Your Drawers Hang Low\".\nBy the early 1910s, he was playing at clubs in New York City and Atlantic City, New Jersey. Smith served in World War I, where he saw action in France. He also played drum with the African-American regimental band led by Tim Brymn, called \"The Black Devils\", and basketball with the regimental team. Legend has it that his nickname \"The Lion\" came from his reported bravery while serving as a heavy artillery gunner. Smith recalled:\nWhen they asked for volunteers to fire the French 75, I stepped forward. French Captain-in-Charge told us: \"Well, I think it will take you a month to learn the mechanisms, and then we''ll shoot you up to the front.\"  I learned that mechanism in six hours. They tabbed me as an A-1 gunner right off the bat. I shot those 75''s at the Fritzies for forty-nine days straight without a break or any relief. Word got back and the Colonel came up and said: \"Smith, you''re a lion with that gun.\" That name stuck with me ever since.\nHe was a decorated veteran of the 350th Field Artillery, a regiment of the Buffalo Soldiers.\nAround 1915, he married Blanche Merrill (née Howard). Smith and Merrill are thought to have separated before Smith joined the army in 1917, where he served as a corporal. But they were listed in the 1920 census as living together in Newark, New Jersey. Merrill was white, and Smith was the only man in their apartment building who was classified as black on this census.\nHe returned to working in Harlem clubs and at \"rent parties\". Smith and his contemporaries James P. Johnson and Fats Waller developed a new, more sophisticated piano style later called \"stride\".\nIn the 1940s, his music found appreciation with a wider audience. Smith toured North America and Europe up to 1971. To leave the US, he needed a birth certificate. He went to the Orange County Courthouse and found it, but discovered that the birth certificate said he was born on November 25, in contradiction to his mother telling him he was born on November 23.","Personal Life":"Smith had 10 brothers and a sister (including half-siblings). His older brother Jerome died at the age of 15. His other older brother, George, became an officer in Atlantic City, and died in 1946. Willie said of George: \"Our paths didn''t cross very often in later life. His friends and connections were always on the other side of the fence from mine.\" His half-brother Robert owned a bar on West Street in Newark. His half-brother Melvin lived on Mulberry Street in Manhattan. Smith had no idea what became of his other two half-brothers, Norman and Ralph. His other siblings died as children, ranging from ages of three to seven.\nAs a boy, Smith delivered clean clothes to his mother''s clients, who included a prosperous Jewish family who invited him to sit in on Hebrew lessons on Saturday mornings. Willie made his bar mitzvah in Newark at age thirteen. Later in life he worked as a Hebrew cantor for a congregation in Harlem.","Death":"In his later years, he received frequent honors for his life''s work including a Willie \"the Lion\" Smith Day in Newark, New Jersey. Smith died at the age of 79 on April 18, 1973, in New York.","Legacy":"The liner notes of his 1958 LP The Legend of Willie \"The Lion\" Smith (Grand Awards Records GA 33-368) state: \"Duke Ellington has never lost his awe of the Lion''s prowess.\" It quotes Ellington as saying, \"Willie The Lion was the greatest influence of all the great jazz piano players who have come along. He has a beat that stays in the mind.\" This LP''s cover, features a painting of the Lion by Tracy Sugarman. Ellington attested to his admiration when he composed and recorded \"Portrait of the Lion\" in 1939.\nOrange County (NY) Executive Edward Diana issued a proclamation declaring September 18 Willie \"the Lion\" Smith Day in Orange County, the date of the first Goshen Jazz Festival."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (326, '1WmIo9ORq1IDlovUWFmo4Y', 'Woody', 'Herman', '73bb2ece-7ef7-4ee9-b3a0-bffe0b481bb0', 239399, 10, 'https://en.wikipedia.org/wiki/Woody_Herman', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Woody_Herman_ca.1943.jpg/500px-Woody_Herman_ca.1943.jpg', 'General Artists Corporation-management', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Woody_Herman_ca.1943.jpg', '{"Intro":"Woodrow Charles Herman (May 16, 1913 – October 29, 1987) was an American jazz clarinetist, saxophonist, singer, and big band leader. Leading groups called \"The Herd\", Herman came to prominence in the late 1930s and was active until his death in 1987. His bands often played music that was cutting edge and experimental; their recordings received numerous Grammy nominations with three wins plus a lifetime achievement award for Herman.","Early Life And Career":"Herman was born in Milwaukee, Wisconsin, on May 16, 1913. His parents were Otto and Myrtle (Bartoszewicz) Herrmann. His mother was born in Poland. His father had a deep love for show business and this influenced Woody at an early age.\nAs a child, Woody Herman worked as a singer and tap-dancer in vaudeville, then started to play the clarinet and saxophone by age 12. In 1931 he met Charlotte Neste, an aspiring actress; the couple married on September 27, 1936. Woody Herman joined the Tom Gerun band and his first recorded vocals were \"Lonesome Me\" and \"My Heart''s at Ease\". Herman also performed with the Harry Sosnick orchestra, Gus Arnheim and Isham Jones. Jones wrote many popular songs (including \"It Had to Be You\") and at some point was tiring of the demands of leading a band and wanted to live off the residuals of his songs. Herman saw the chance to lead his former band and eventually acquired the remains of the orchestra after Jones'' retirement.","Last Years":"Herman continued to perform into the 1980s, after the death of his wife and with his health in decline, chiefly to pay back taxes that were owed because of his business manager''s bookkeeping in the 1960s. Herman owed the IRS millions of dollars and was in danger of eviction from his home. With this added stress, Herman still kept performing. In a December 5, 1985, review of the band at the Blue Note jazz club for The New York Times, John S. Wilson pointed out: \"In a one-hour set, Mr. Herman is able to show off his latest batch of young stars—the baritone saxophonist Mike Brignola, the bassist Bill Moring, the pianist Brad Williams, the trumpeter Ron Stout—and to remind listeners that one of his own basic charms is the dry humor with which he shouts the blues.\" Wilson also spoke about arrangements by Bill Holman and John Fedchock for special attention.  Wilson spoke of the continuing influence of Duke Ellington on Woody Herman bands from the 1940s to the 1980s.  Before Woody Herman died in 1987 he delegated most of his duties to leader of the reed section, Frank Tiberi. Tiberi leads the current version of the Woody Herman orchestra. Tiberi said at the time of Herman''s death that he would not change the band''s repertoire or library. Herman died on October 29, 1987, and had a Catholic funeral on November 2 at St. Victor''s in West Hollywood, California. He is interred in a niche in the columbarium behind the Cathedral Mausoleum in the Hollywood Forever Cemetery.\nAwards won by the Woody Herman orchestras with major publications: \"Voted best swing band in 1945 DownBeat poll; Silver Award by critics in 1946 and 1947 Esquire polls; won Metronome poll, band division, 1946 and 1953.\nA documentary film titled Woody Herman: Blue Flame – Portrait of a Jazz Legend was released on DVD in late 2012 by the jazz documentary filmmaker Graham Carter, owner of Jazzed Media, to salute Herman and his centenary in May 2013."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (327, '1WmIo9ORq1IDlovUWFmo4Y', 'Woody', 'Shaw', '5cdab4ea-500b-4bcf-a5fc-92e8eb2b6ad6', 255117, 7, 'https://en.wikipedia.org/wiki/Woody_Shaw', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Woody_Shaw.jpg/500px-Woody_Shaw.jpg', 'Tom Marcello Webster, New York, USA', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Woody_Shaw.jpg', '{"Intro":"Woody Herman Shaw Jr.  (December 24, 1944 – May 10, 1989) was an American jazz trumpeter, flugelhornist, cornetist, composer, arranger, band leader, and educator. Shaw is widely known as one of the 20th century''s most important and influential jazz trumpeters and composers. He is often credited with revolutionizing the technical and harmonic language of modern jazz trumpet playing, and is regarded by many as one of the major innovators of the instrument. He was an acclaimed virtuoso,  mentor, and spokesperson for jazz and worked and recorded alongside many of the leading musicians of his time.","Early Life And Background":"Woody Shaw was born in Laurinburg, North Carolina. When Shaw was a year old, his parents, Rosalie Pegues and Woody Shaw Sr., took their son to Newark, New Jersey,. Shaw''s father was a member of the African American gospel group, The Diamond Jubilee Singers. Both parents attended Laurinburg Institute, the same secondary private school as Dizzy Gillespie. Shaw''s mother and Gillespie were both from the same town, Cheraw, South Carolina.\nShaw began playing the bugle when he was age nine and performed in the Newark Junior Elks, Junior Mason, and Washington Carver Drum and Bugle Corps. Though not his first choice of instrument, he began studying classical trumpet with Jerome Ziering at Cleveland Junior High School at the age of 11.\nThe trumpet was not my first choice for an instrument. In fact, I ended up playing it by default. When we were asked what we wanted to play in the Eighteenth Avenue School Band, I chose the violin, but I was too late since all the violins were taken. My second choice was the saxophone or the trombone but they were also all spoken for. The only instrument that was left was the trumpet, and I felt why did I have to get stuck with this \"tinny\" sounding thing.\nWhen I complained to my music teacher that I didn''t think it was fair that all the other kids got to play the instruments they wanted, he told me to just be patient. He said he had a good feeling about me and the trumpet, and he assured me I''d grow to love it. Of course my teacher was right, and it didn''t take long for me to fall in love with the trumpet. In retrospect, I believe there was some mystical force that brought us together.\nZiering encouraged him to continue his study of classical trumpet playing and pursue an education at the Juilliard School of music with trumpet instructor William Vacchiano, but Shaw had a deep interest in jazz. His first influences were Louis Armstrong and Harry James. After skipping two grades, he began attending Newark Arts High School (alma mater of Wayne Shorter, Sarah Vaughan, Melba Moore, Savion Glover, Larry Young, and many others), from which he graduated.\nAs a teenager, Shaw worked professionally at weddings, dances, and night clubs. He eventually left school but continued his study of the trumpet under the influence of Gillespie, Fats Navarro, Clifford Brown, Booker Little, Lee Morgan, and Freddie Hubbard. He later discovered that he had picked up the trumpet during the same month and year that Brown died: June 1956.","Career":"In 1963, after many local professional jobs, Shaw worked for Willie Bobo (with Chick Corea and Joe Farrell), and performed and recorded as a sideman with Eric Dolphy, with whom he made his recorded debut, Iron Man. Dolphy, who was living in Paris, unexpectedly died in June 1964. Shaw was nonetheless invited to Paris to join Dolphy''s colleague, Nathan Davis, and the two men found steady work all over Europe. While living in Paris, they frequented the club Le Chat Qui Peche, and Shaw crossed paths with musicians such as Bud Powell, Kenny Clarke, Johnny Griffin, Dexter Gordon, Art Taylor, other lesser-known musicians such as John Bodwin, and French musicians including Jean-Louis Chautemps, Rene Urtreger, Jacques Thollot and Jef Gilson. After some time, Shaw demanded that two of his contemporaries, organist Larry Young and drummer Billy Brooks, be relocated to Paris. The four young musicians – Davis, Shaw, Young, and Brooks –  continued living and performing in France, intermittently touring cities in Europe, including Berlin, Germany.\nBy the mid-1960s, Shaw had successfully absorbed the concepts and influence of his mentor and friend, saxophonist Dolphy, and was meanwhile exploring the harmonic innovations of saxophonist John Coltrane and pianist McCoy Tyner. Both musicians contributed greatly to the development of Shaw''s style as a trumpeter and composer.\nShaw returned to the U.S. from Paris in 1965, and began his career as one of the Blue Note label''s regular trumpet players, working steadily with their roster of artists. He replaced Carmell Jones in the Horace Silver quintet (1965–1966), and made his Blue Note debut on Silver''s The Cape Verdean Blues, followed by Larry Young''s Unity (1965); the album with Young featured three of his compositions (\"Zoltan\", \"Moontrane\", and \"Beyond All Limits\"). \"Moontrane\", dedicated to Coltrane, was written when Shaw was 18 years old and was his earliest composition.\nShaw also collaborated frequently and recorded with Corea (1966–67, 1969), Jackie McLean (1967), Booker Ervin (1968), Tyner (1968), Andrew Hill (1969), Herbie Hancock, and Bobby Hutcherson. In 1968–69, he worked intermittently with Max Roach, touring with him in Iran. Shaw also worked as a studio musician, in pit orchestras, and on Broadway musicals.\nContemporary and Muse (early-to-mid 1970s)\nIn 1970, Shaw recorded his first album as a leader, Blackstone Legacy, for Contemporary Records. Blackstone Legacy featured Bennie Maupin, Ron Carter, George Cables, Gary Bartz, Clint Houston, and Lenny White. This was followed by a second release under Shaw''s name, entitled Song of Songs. During this time, Shaw moved to San Francisco to explore new opportunities and became closely associated with musicians on the West Coast such as Bobby Hutcherson, Eddie Moore, Eddie Marshall, and Henry Franklin.\nIn 1974, Shaw returned from California to New York, beginning an association with Muse Records, recording the albums – The Moontrane, Love Dance, Little Red''s Fantasy and Iron Men, with musicians from the mid-western creative black arts scene such as Anthony Braxton, Arthur Blythe and Muhal Richard Abrams.\nAfter working frequently with Hutcherson, Art Blakey, Tyner and others, Shaw emerged as a band leader during the early 1970s, which was a time when many jazz artists began to explore jazz-rock. A younger statesman among his elders, Shaw saw himself as an heir to the musical legacy of trumpeters such as Gillespie, Navarro, and Brown, and, being an alumnus of Blakey''s Jazz Messengers, felt responsible for upholding the integrity and appreciation of the tradition.\nAfter releasing several albums for the Muse label, Shaw signed to Columbia Records in 1977 following an endorsement from Miles Davis. He then recorded the albums Rosewood, Stepping Stones: Live at the Village Vanguard, Woody III, For Sure!, and United.\nRosewood was nominated for two Grammys and was voted Best Jazz Album of 1978 in the DownBeat Readers'' Poll, which also voted Shaw Best Jazz Trumpeter of the Year, and No. 4 Jazz Musician of the Year.\nThroughout the 1980s, Shaw continued performing and recording as a leader with sidemen such as pianists Onaje Allan Gumbs, Mulgrew Miller, and Larry Willis, bassist David Williams, drummer Terri Lyne Carrington, and trombonist Steve Turre, recording a number of more \"traditional\" but highly lyrical albums (Solid, Setting Standards, In My Own Sweet Way) consisting mainly of standards and tunes from the hard bop repertoire. During this time he also worked on projects with saxophonists Benny Golson, Kenny Garrett and Dexter Gordon, as well as fellow trumpeter Freddie Hubbard on three albums (Double Take, and The Eternal Triangle, reissued on Blue Note as The Freddie Hubbard and Woody Shaw Sessions) and Golson''s Time Speaks.\nDuring a 1980s tour for the United States Information Service, Shaw ventured to such countries as Egypt, Sudan, and the United Arab Emirates. Recently, it has been discovered that Shaw spent significant time performing and giving clinics in India, working in cities such as New Delhi, Bombay, Bangalore, and Calcutta. When asked by film producer Chuck France in an interview whether he thought traveling was important, Shaw responded: \"Most definitely. I think every great artist should share his music with the world.\"\nBy the late 1980s, Shaw was nearly blind from retinitis pigmentosa, an incurable degenerative eye disease. A heroin user throughout his adult life, Shaw was in poor health when he returned to the U.S. in early 1989 from a lengthy stay in Europe and needed a wheelchair at the airport. On the morning of February 27, 1989, Shaw was struck by a subway car in Brooklyn, New York, which mangled his left arm and caused other injuries including head trauma; doctors were forced to amputate his arm. The night before the accident, Max Roach sent a limousine to Newark where Shaw was staying, to bring Shaw to the Village Vanguard to hear Roach play. After the set, Roach put Shaw into a taxi around midnight with enough money to get back to Newark. Shaw did not go to Newark; it is unclear what led to the accident later that morning. During his hospital stay at Bellevue, Shaw suffered kidney failure, was put on a respirator and lost consciousness for more than a month. He died from kidney failure on May 10, 1989, aged  44.","Relationship With Other Musicians":"As a musician and trumpeter, Shaw was held in high esteem by his colleagues and is seen as one of the most technically and harmonically advanced trumpet players in the history of jazz and of the instrument itself. Miles Davis, a notoriously harsh critic of fellow musicians, once said of Shaw: \"Now there''s a great trumpet player. He can play different from all of them.\" Trumpeter Dave Douglas stated: \"It''s not only the brilliant imagination that captivates with Woody Shaw – it''s how natural those fiendishly difficult lines feel... Woody Shaw is now one of the most revered figures for trumpeters today.\"\nShaw is credited with having extended the harmonic and technical vocabulary of the trumpet. Upon hearing of Shaw''s death in 1989, Wynton Marsalis stated: \"Woody added to the vocabulary of the trumpet. His whole approach influenced me tremendously.\" Multi-genre producer, instrumentalist and rapper, Madlib, also cites Shaw as an inspiration. In an interview with Red Bull Music Academy, Madlib listed Shaw as his favorite trumpet player, saying of his music: \"It’s electric and acoustic, traditional and non-traditional — that’s what I’m all about.\"","Health Issues And Death":"By the late 1980s, Shaw was nearly blind from retinitis pigmentosa, an incurable degenerative eye disease. A heroin user throughout his adult life, Shaw was in poor health when he returned to the U.S. in early 1989 from a lengthy stay in Europe and needed a wheelchair at the airport. On the morning of February 27, 1989, Shaw was struck by a subway car in Brooklyn, New York, which mangled his left arm and caused other injuries including head trauma; doctors were forced to amputate his arm. The night before the accident, Max Roach sent a limousine to Newark where Shaw was staying, to bring Shaw to the Village Vanguard to hear Roach play. After the set, Roach put Shaw into a taxi around midnight with enough money to get back to Newark. Shaw did not go to Newark; it is unclear what led to the accident later that morning. During his hospital stay at Bellevue, Shaw suffered kidney failure, was put on a respirator and lost consciousness for more than a month. He died from kidney failure on May 10, 1989, aged  44.","Image And Legacy":"The years between 2003 and 2013 saw a resurgence of interest in, and recognition of, Shaw''s music. In 2003, Shaw''s son, Woody Louis Armstrong Shaw III, launched The Official Woody Shaw Website. Since then, many of Shaw''s long-out-of-print recordings have been reissued, remastered and repackaged, under the curatorial oversight of Shaw''s son and long-time producer Michael Cuscuna.\nIn 2012, PopMarket, a division of Sony Legacy, released Woody Shaw: The Complete Columbia Albums Collection, and in 2013, Mosaic Records released Woody Shaw: The Complete Muse Sessions, for which NPR described Shaw as \"the last great trumpet innovator\".\nShaw III, the primary inspiration for Shaw''s third Columbia album, Woody III (dedicated to Shaw''s father and newborn son), is the sole heir to his father''s legacy. Today, Shaw III preserves the Shaw legacy through the production, management, archiving and preservation of his father''s life''s work.  Shaw''s legacy is kept active and relevant through the use of social media and the official website.\nAs a musician and trumpeter, Shaw was held in high esteem by his colleagues and is seen as one of the most technically and harmonically advanced trumpet players in the history of jazz and of the instrument itself. Miles Davis, a notoriously harsh critic of fellow musicians, once said of Shaw: \"Now there''s a great trumpet player. He can play different from all of them.\" Trumpeter Dave Douglas stated: \"It''s not only the brilliant imagination that captivates with Woody Shaw – it''s how natural those fiendishly difficult lines feel... Woody Shaw is now one of the most revered figures for trumpeters today.\"\nShaw is credited with having extended the harmonic and technical vocabulary of the trumpet. Upon hearing of Shaw''s death in 1989, Wynton Marsalis stated: \"Woody added to the vocabulary of the trumpet. His whole approach influenced me tremendously.\" Multi-genre producer, instrumentalist and rapper, Madlib, also cites Shaw as an inspiration. In an interview with Red Bull Music Academy, Madlib listed Shaw as his favorite trumpet player, saying of his music: \"It’s electric and acoustic, traditional and non-traditional — that’s what I’m all about.\""}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (328, '1WmIo9ORq1IDlovUWFmo4Y', 'Zbigniew', 'Namyslowski', '1fd07f25-9db5-49b4-b375-8eaaa8b53e58', 468193, 6, 'https://en.wikipedia.org/wiki/Zbigniew_Namysłowski', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Namyslowski_Zbigniew.jpg/500px-Namyslowski_Zbigniew.jpg', 'This photo was taken by Przemysław JahrAutorem zdjęcia jest Przemysław JahrWykorzystując zdjęcie proszę podać jako autora:Przemysław Jahr / Wikimedia Commons', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Namyslowski_Zbigniew.jpg', '{"Intro":"Zbigniew Jacek Namysłowski (9 September 1939 – 7 February 2022) was a Polish jazz alto saxophonist, flautist, cellist, trombonist, pianist and composer.","Life And Career":"Namysłowski was born in Warsaw, Poland, on 9 September 1939. He performed on the Krzysztof Komeda album Astigmatic recorded in 1965. He collaborated with such artists as Janusz Muniak, Leszek Możdżer, Vladislav Sendecki, Michał Urbaniak, and Andrzej Trzaskowski. Namysłowski died on 7 February 2022, at the age of 82."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (329, '1WmIo9ORq1IDlovUWFmo4Y', 'Sonny', 'Rollins', '3b47247e-5b57-49b6-a0ed-bad80243802a', 145264, 6, 'https://en.wikipedia.org/wiki/Sonny_Rollins', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Sonny_Rollins_2011.jpg/500px-Sonny_Rollins_2011.jpg', 'Tom Beetz', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Sonny_Rollins_2011.jpg', '{"Intro":"Walter Theodore \"Sonny\" Rollins (born September 7, 1930) is a retired American jazz tenor saxophonist who is widely recognized as one of the most important and influential jazz musicians.\nIn a seven-decade career, Rollins recorded more than sixty albums as a leader. A number of his compositions, including \"St. Thomas\", \"Oleo\", \"Doxy\", and \"Airegin\", have become jazz standards. Rollins has been called \"the greatest living improviser\". Due to health problems, Rollins has not performed publicly since 2012 and announced his retirement in 2014.","Early Life":"Rollins was born in New York City to parents from the Virgin Islands. The youngest of three siblings, he grew up in central Harlem and on Sugar Hill, receiving his first alto saxophone at the age of seven or eight.  He attended Edward W. Stitt Junior High School and graduated from Benjamin Franklin High School in East Harlem.  Rollins started as a pianist, then switched to alto saxophone after being inspired by Louis Jordan and finally switched to tenor saxophone in 1946, influenced by his idol Coleman Hawkins. During his high-school years, Rollins played in a band with other future jazz legends Jackie McLean, Kenny Drew, and Art Taylor.","Later Life And Career":"This section of a biography of a living person needs additional citations for verification. Please help by adding reliable sources. Contentious material about living persons that is unsourced or poorly sourced must be removed immediately from the article and its talk page, especially if potentially libelous.Find sources: \"Sonny Rollins\" – news · newspapers · books · scholar · JSTOR  (June 2023) (Learn how and when to remove this message)\nAfter graduating from high school in 1948, Rollins began performing professionally; he made his first recordings in early 1949 as a sideman with the bebop singer Babs Gonzales (trombonist J. J. Johnson was the arranger of the group).  Within the next few months, he began to make a name for himself, recording with Johnson and appearing under the leadership of pianist Bud Powell, alongside trumpeter Fats Navarro and drummer Roy Haynes, on a seminal \"hard bop\" session.\nIn early 1950, Rollins was arrested for armed robbery and spent ten months in Rikers Island jail before being released on parole; in 1952, he was re-arrested for violating the terms of his parole by using heroin.  Between 1951 and 1953, he recorded with Miles Davis, the Modern Jazz Quartet, Charlie Parker, and Thelonious Monk.  A breakthrough arrived in 1954 when he recorded his famous compositions \"Oleo\", \"Airegin\", and \"Doxy\" with a quintet led by Davis that also featured pianist Horace Silver, Percy Heath, and Kenny Clarke. These recordings appear on the album Miles Davis with Sonny Rollins.\nIn 1955, Rollins entered the Federal Medical Center, Lexington. While there, he volunteered for then-experimental methadone therapy and was able to break his heroin habit, after which he lived for a time in Chicago, briefly rooming with the trumpeter Booker Little. Rollins initially feared sobriety would impair his musicianship, but then went on to greater success.\nRollins briefly joined the Miles Davis Quintet in the summer of 1955. Later that year, he joined the Clifford Brown–Max Roach quintet; studio albums Clifford Brown and Max Roach at Basin Street and Sonny Rollins Plus 4 document his time in that band. After the deaths of Brown and band pianist Richie Powell in a June 1956 automobile accident, Rollins continued playing with Roach and began releasing albums under his own name on Prestige Records, Blue Note, Riverside, and the Los Angeles label Contemporary.\nHis widely acclaimed album Saxophone Colossus was recorded on June 22, 1956, at Rudy Van Gelder''s studio in New Jersey, with Tommy Flanagan on piano, former Jazz Messengers bassist Doug Watkins, and his favorite drummer, Roach. This was Rollins''s sixth recording as a leader and it included his best-known composition \"St. Thomas\", a Caribbean calypso based on \"Hold Him Joe\" a tune sung to him by his mother in his childhood, as well as the fast bebop number \"Strode Rode\", and \"Moritat\" (the Kurt Weill composition also known as \"Mack the Knife\"). A long blues solo on Saxophone Colossus, \"Blue 7\", was analyzed in depth by the composer and critic Gunther Schuller in a 1958 article.\nImprovisation from St. Thomas starting immediately after the melody\nIn the solo for \"St. Thomas\", Rollins uses repetition of a rhythmic pattern, and variations of that pattern, covering only a few tones in a tight range, and employing staccato and semi-detached notes. This is interrupted by a sudden flourish, utilizing a much wider range before returning to the former pattern. (Listen to the music sample.) In his book The Jazz Style of Sonny Rollins, David N. Baker explains that Rollins \"very often uses rhythm for its own sake. He will sometimes improvise on a rhythmic pattern instead of on the melody or changes.\"\nEver since recording \"St. Thomas\", Rollins''s use of calypso rhythms has been one of his signature contributions to jazz; he often performs traditional Caribbean tunes such as \"Hold ''Em Joe\" and \"Don''t Stop the Carnival\", and he has written many original calypso-influenced compositions, such as \"Duke of Iron\", \"The Everywhere Calypso\", and \"Global Warming\".\nIn 1956, Rollins recorded Tenor Madness, using Davis''s group – pianist Red Garland, bassist Paul Chambers, and drummer Philly Joe Jones. The title track is the only recording of Rollins with John Coltrane, who was also a member of Davis''s group.\nAt the end of the year, Rollins appeared as a sideman on Thelonious Monk''s album Brilliant Corners and also recorded his own first album for Blue Note Records, entitled Sonny Rollins, Volume One, with Donald Byrd on trumpet, Wynton Kelly on piano, Gene Ramey on bass, and Roach on drums.\nIn 1957, he married his first wife, actress and model Dawn Finney.\nThat year, Rollins pioneered the use of bass and drums, without piano, as accompaniment for his saxophone solos, a texture that came to be known as \"strolling\". Two early tenor/bass/drums trio recordings are Way Out West and A Night at the Village Vanguard, both recorded in 1957. Way Out West was so named because it was recorded for California-based Contemporary Records (with Los Angeles drummer Shelly Manne), and because it included country and western songs such as \"Wagon Wheels\" and \"I''m an Old Cowhand\". The Village Vanguard album consists of two sets, a matinee with bassist Donald Bailey and drummer Pete LaRoca and an evening set with bassist Wilbur Ware and drummer Elvin Jones. Rollins used the trio format intermittently throughout his career, sometimes taking the unusual step of using his sax as a rhythm section instrument during bass and drum solos.  Lew Tabackin cited Rollins''s pianoless trio as an inspiration to lead his own.  Joe Henderson, David S. Ware, Joe Lovano, Branford Marsalis, and Joshua Redman led pianoless sax trios.\nWhile in Los Angeles in 1957, Rollins met alto saxophonist Ornette Coleman and the two of them practiced together. Coleman, a pioneer of free jazz, stopped using a pianist in his own band two years later. By this time, Rollins had become well-known for improvising based on relatively banal or unconventional songs (such as \"There''s No Business Like Show Business\" on Work Time, \"Toot, Toot, Tootsie\" on The Sound of Sonny, and later \"Sweet Leilani\" on the Grammy-winning album This Is What I Do).\nRollins acquired the nickname \"Newk\" because of his facial resemblance to Brooklyn Dodgers star pitcher Don Newcombe.\nRollins at the San Francisco Opera House, February 22, 1982.\nIn 1957, Rollins made his Carnegie Hall debut, and recorded again for Blue Note with J. J. Johnson on trombone, Horace Silver or Monk on piano and drummer Art Blakey (released as Sonny Rollins, Volume Two). That December, Rollins and fellow tenor saxophonist Sonny Stitt were featured together on Dizzy Gillespie''s album Sonny Side Up. In 1958, Rollins appeared in Art Kane''s A Great Day in Harlem photograph of jazz musicians in New York; he is the last surviving musician from the photo.\nThe same year, Rollins recorded another landmark piece for saxophone, bass and drums trio: Freedom Suite. His original sleeve notes said: \"How ironic that the Negro, who more than any other people can claim America''s culture as his own, is being persecuted and repressed; that the Negro, who has exemplified the humanities in his very existence, is being rewarded with inhumanity.\" The title track is a nineteen-minute improvised bluesy suite; the other side of the album features hard bop workouts of popular show tunes. Oscar Pettiford and Max Roach provided bass and drums, respectively. The LP was available only briefly in its original form, before the record company repackaged it as Shadow Waltz, the title of another piece on the record.\nFollowing Sonny Rollins and the Big Brass (Sonny Rollins Brass/Sonny Rollins Trio), Rollins made one more studio album in 1958, Sonny Rollins and the Contemporary Leaders, before taking a three-year break from recording. This was a session for Contemporary Records and saw Rollins recording an esoteric mixture of tunes including \"Rock-a-Bye Your Baby with a Dixie Melody\" with a West Coast group made up of pianist Hampton Hawes, guitarist Barney Kessel, bassist Leroy Vinnegar and drummer Shelly Manne.\nIn 1959, Rollins toured Europe for the first time, performing in Sweden, the Netherlands, Germany, Italy, and France.\nBy 1959, Rollins had become frustrated with what he perceived as his own musical limitations and took the first – and most famous – of his musical sabbaticals. While living on the Lower East Side of Manhattan, he ventured to the pedestrian walkway of the Williamsburg Bridge to practice, in order to avoid disturbing a neighboring expectant mother. Today, a fifteen-story apartment building named \"The Rollins\" stands on the Grand Street site where he lived. Almost every day from the summer of 1959 through the end of 1961, Rollins practiced on the bridge, next to the subway tracks. Rollins admitted that he would often practice for 15 or 16 hours a day, no matter what season. In the summer of 1961, the journalist Ralph Berton happened to pass by the saxophonist on the bridge one day and published an article in Metronome magazine about the occurrence. During this period, Rollins became a dedicated practitioner of yoga.\nRollins ended his sabbatical in November 1961. He later said: \"I could have probably spent the rest of my life just going up on the bridge. I realized, no, I have to get back into the real world.\" In 2016, a campaign was initiated that seeks to have the bridge renamed in Rollins''s honor.\nIn November 1961, Rollins returned to the jazz scene with a residency at the Jazz Gallery in Greenwich Village; in March, 1962, he appeared on Ralph Gleason''s television series Jazz Casual. During the 1960s, Rollins lived on Willoughby Street in Brooklyn, New York.\nHe named his 1962 \"comeback\" album The Bridge at the start of a contract with RCA Victor. Produced by George Avakian, the disc was recorded with a quartet featuring guitarist Jim Hall, Ben Riley on drums, and bassist Bob Cranshaw. This became one of Rollins''s best-selling records; in 2015, it was inducted into the Grammy Hall of Fame.\nRollins''s contract with RCA Victor lasted through 1964. Each album he recorded differed radically from the previous one. The 1962 disc What''s New? explored Latin rhythms. On the album Our Man in Jazz, recorded live at The Village Gate, he explored avant-garde playing with a quartet that featured Cranshaw on bass, Billy Higgins on drums and Don Cherry on cornet.  He also played with a tenor saxophone hero, Coleman Hawkins, and free jazz pianist Paul Bley on Sonny Meets Hawk!, and he re-examined jazz standards and Great American Songbook melodies on Now''s the Time and The Standard Sonny Rollins (which featured pianist Herbie Hancock).\nIn 1963, Rollins made the first of many tours of Japan.\nIn 1965, he married Lucille Pearson, born on July 25, 1928, in Kansas City, Missouri. She eventually became his very effective manager/producer. They moved (partially, then completely) from New York City to Germantown, New York, where she died on November 27, 2004.\nIn 2007, recordings from a 1965 residency at Ronnie Scott''s Jazz Club were released by the Harkit label as Live in London; they offer a very different picture of Rollins''s playing from the studio albums of the period. (These are unauthorized releases, and Rollins has responded by \"bootlegging\" them himself and releasing them on his website.)\nUpon signing with Impulse! Records, he recorded a soundtrack to the 1966 film Alfie, as well as the live album There Will Never Be Another You and Sonny Rollins on Impulse! (1965). After East Broadway Run Down (1966), which featured trumpeter Freddie Hubbard, bassist Jimmy Garrison, and drummer Elvin Jones, Rollins did not release another studio album for six years.\nIn 1968, he was the subject of a television documentary entitled Who is Sonny Rollins? (in the series Creative Persons), directed by Dick Fontaine.\nIn 1969, Rollins took another two-year sabbatical from public performance. During this hiatus period, he visited Jamaica for the first time and spent several months studying yoga, meditation, and Eastern philosophies at an ashram in Powai, India, a district of Mumbai.\nSonny Rollins performing in 2005 He returned from his second sabbatical with a performance in Kongsberg, Norway, in 1971. Reviewing a March 1972 performance at New York''s Village Vanguard night club, The New Yorker critic Whitney Balliett wrote that Rollins \"had changed again. He had become a whirlwind. His runs roared, and there were jarring staccato passages and furious double-time spurts. He seemed to be shouting and gesticulating on his horn, as if he were waving his audience into battle.\" The same year, he released Next Album and moved to Germantown, New York. Also in 1972, he was awarded a Guggenheim Fellowship in composition.\nDuring the 1970s and 1980s, he also became drawn to R&B, pop, and funk rhythms. Some of his bands during this period featured electric guitar, electric bass, and usually more pop- or funk-oriented drummers.\nIn 1974, Rollins added jazz bagpiper Rufus Harley to his band; the group was filmed performing live at Ronnie Scott''s in London. For most of this period Rollins was recorded by producer Orrin Keepnews for Milestone Records (the compilation Silver City: A Celebration of 25 Years on Milestone contains a selection from these years). In 1978 he, McCoy Tyner, Ron Carter, and Al Foster toured together as the Milestone Jazzstars. In June of that year, Rollins joined many other major jazz artists in a performance for President Jimmy Carter on the South Lawn of the White House.\nIt was also during this period that Rollins''s passion for unaccompanied saxophone solos came to the forefront.  In 1979 he played unaccompanied on The Tonight Show and in 1985 he released The Solo Album, recorded live at the Museum of Modern Art in New York.  He also frequently played long, extemporaneous unaccompanied cadenzas during performances with his band; a prime example is his introduction to the tune \"Autumn Nocturne\" on the 1978 album Don''t Stop the Carnival.\nBy the 1980s, Rollins had stopped playing small nightclubs and was appearing mainly in concert halls or outdoor arenas; through the late 1990s he occasionally performed at large New York rock clubs such as Tramps and The Bottom Line. He added (uncredited) sax improvisations to three tracks by the Rolling Stones for their 1981 album Tattoo You, including the single, \"Waiting on a Friend\" and the long jam \"Slave\". That November, he led a saxophone masterclass on French television.  In 1983, he was honored as a \"Jazz Master\" by the National Endowment for the Arts.\nIn 1986, documentary filmmaker Robert Mugge released a film titled Saxophone Colossus. It featured two Rollins performances: a quintet concert at Opus 40 in upstate New York and a performance with the Yomiuri Shimbun Orchestra in Japan of his Concerto for Saxophone and Symphony, a work composed in collaboration with the Finnish pianist and composer Heikki Sarmanto.\nIn 1993, the Sonny Rollins International Jazz Archives opened at the University of Pittsburgh.\nNew York City Hall proclaimed November 13, 1995, to be \"Sonny Rollins Day\". Several days later, Rollins gave a performance at New York City''s Beacon Theatre that reunited him with musicians with whom he played as a teenager, including McLean, Walter Bishop Jr., Percy Heath, Connie Henry, and Gil Coggins.\nIn 1997, he was voted \"Jazz Artist of the Year\" in the Down Beat magazine critics'' poll.  The following year, Rollins, a dedicated advocate of environmentalism, released an album entitled Global Warming.\nRollins at the Newport Jazz Festival in 2008\nCritics such as Gary Giddins and Stanley Crouch have noted the disparity between Rollins the recording artist, and Rollins the concert artist. In a May 2005 New Yorker profile, Crouch wrote of Rollins the concert artist:\nOver and over, decade after decade, from the late seventies through the eighties and nineties, there he is, Sonny Rollins, the saxophone colossus, playing somewhere in the world, some afternoon or some eight o''clock somewhere, pursuing the combination of emotion, memory, thought, and aesthetic design with a command that allows him to achieve spontaneous grandiloquence. With its brass body, its pearl-button keys, its mouthpiece, and its cane reed, the horn becomes the vessel for the epic of Rollins''s talent and the undimmed power and lore of his jazz ancestors.\nRollins won a 2001 Grammy Award for Best Jazz Instrumental Album for This Is What I Do (2000). On September 11, 2001, the 71-year-old Rollins, who lived several blocks away, heard the World Trade Center collapse, and was forced to evacuate his Greenwich Street apartment, with only his saxophone in hand. Although he was shaken, he traveled to Boston five days later to play a concert at the Berklee School of Music. The live recording of that performance was released on CD in 2005 as Without a Song: The 9/11 Concert, from which Rollins''s performance of \"Why Was I Born?\" won the 2006 Grammy Award for Jazz Instrumental Solo.\nRollins was presented with a Grammy Award for lifetime achievement in 2004; that year also saw the death of his wife, Lucille.\nIn 2006, Rollins went on to complete a Down Beat Readers Poll triple win for: \"Jazzman of the Year\", \"No. 1 Tenor Sax Player\", and \"Recording of the Year\" for the CD Without a Song: The 9/11 Concert. The band that year featured his nephew, trombonist Clifton Anderson, and included bassist Cranshaw, pianist Stephen Scott, percussionist Kimati Dinizulu, and drummer Perry Wilson.\nRollins at the Stockholm Jazz Festival, 2009\nAfter a successful Japanese tour, Rollins returned to the recording studio for the first time in five years to record the Grammy-nominated CD Sonny, Please (2006). The CD''s title is derived from one of his wife''s favorite phrases. The album was released on Rollins''s own label, Doxy Records, following his departure from Milestone Records after many years and was produced by Anderson. Rollins''s band at this time, and on this album, included Cranshaw, guitarist Bobby Broom, drummer Steve Jordan and Dinizulu.\nDuring these years, Rollins regularly toured worldwide, playing major venues throughout Europe, South America, the Far East, and Australasia; he is estimated to have sometimes earned as much as $100,000 per performance. On September 18, 2007, he performed at Carnegie Hall in commemoration of the fiftieth anniversary of his first performance there. Appearing with him were Anderson (trombone), Bobby Broom (guitar), Cranshaw (bass), Dinizulu (percussion), Roy Haynes (drums) and Christian McBride (bass).\nAround 2000, Rollins began recording many of his live performances; since then, he has archived recordings of more than two hundred and fifty concerts.  To date, four albums have been released from these archives on Doxy Records and Okeh Records: Road Shows, Vol. 1;  Road Shows, Vol. 2 (with four tracks documenting his 80th birthday concert, which included Rollins''s first ever recorded appearance with Ornette Coleman on the twenty-minute \"Sonnymoon for Two\"); Road Shows, Vol. 3; and Holding the Stage, Road Shows, Vol. 4, released in April 2016.\nIn 2010 Rollins was awarded the National Medal of Arts and the Edward MacDowell Medal; in the fall of the same year he celebrated his 80th birthday with a concert at New York''s Beacon Theatre that included a guest appearance by Ornette Coleman. The following year he was the subject of another documentary by Dick Fontaine, entitled Beyond the Notes.\nRollins has not performed in public since 2012, and retired in 2014, due to recurring respiratory issues caused by pulmonary fibrosis.\nIn 2013, Rollins moved to Woodstock, New York. That spring, he made a guest television appearance on The Simpsons in \"Whiskey Business\" and received an honorary Doctor of Music degree from the Juilliard School in New York City.\nIn 2014, he was the subject of a Dutch television documentary entitled Sonny Rollins-Morgen Speel Ik Beter (transl: Tomorrow I''ll Play Better). He made a public appearance in June of that year introducing saxophonist Ornette Coleman at an all-star tribute performance to Coleman in Brooklyn, NY. In October 2015, he received the Jazz Foundation of America''s lifetime achievement award.\nIn the spring of 2017, Rollins donated his personal archive to the Schomburg Center for Research in Black Culture, one of the research centers of New York Public Library. Later that year, he endowed the \"Sonny Rollins Jazz Ensemble Fund\" at Oberlin College, in \"recognition of the institution''s long legacy of access and social justice advocacy.\"\nIn February 2023, Rollins sold his music catalogue to Reservoir Media. In April 2024, The Notebooks of Sonny Rollins was published, derived from notebooks he maintained from 1959 onwards.","Winter 1961–1969: Musical Explorations":"In November 1961, Rollins returned to the jazz scene with a residency at the Jazz Gallery in Greenwich Village; in March, 1962, he appeared on Ralph Gleason''s television series Jazz Casual. During the 1960s, Rollins lived on Willoughby Street in Brooklyn, New York.\nHe named his 1962 \"comeback\" album The Bridge at the start of a contract with RCA Victor. Produced by George Avakian, the disc was recorded with a quartet featuring guitarist Jim Hall, Ben Riley on drums, and bassist Bob Cranshaw. This became one of Rollins''s best-selling records; in 2015, it was inducted into the Grammy Hall of Fame.\nRollins''s contract with RCA Victor lasted through 1964. Each album he recorded differed radically from the previous one. The 1962 disc What''s New? explored Latin rhythms. On the album Our Man in Jazz, recorded live at The Village Gate, he explored avant-garde playing with a quartet that featured Cranshaw on bass, Billy Higgins on drums and Don Cherry on cornet.  He also played with a tenor saxophone hero, Coleman Hawkins, and free jazz pianist Paul Bley on Sonny Meets Hawk!, and he re-examined jazz standards and Great American Songbook melodies on Now''s the Time and The Standard Sonny Rollins (which featured pianist Herbie Hancock).\nIn 1963, Rollins made the first of many tours of Japan.\nIn 1965, he married Lucille Pearson, born on July 25, 1928, in Kansas City, Missouri. She eventually became his very effective manager/producer. They moved (partially, then completely) from New York City to Germantown, New York, where she died on November 27, 2004.\nIn 2007, recordings from a 1965 residency at Ronnie Scott''s Jazz Club were released by the Harkit label as Live in London; they offer a very different picture of Rollins''s playing from the studio albums of the period. (These are unauthorized releases, and Rollins has responded by \"bootlegging\" them himself and releasing them on his website.)\nUpon signing with Impulse! Records, he recorded a soundtrack to the 1966 film Alfie, as well as the live album There Will Never Be Another You and Sonny Rollins on Impulse! (1965). After East Broadway Run Down (1966), which featured trumpeter Freddie Hubbard, bassist Jimmy Garrison, and drummer Elvin Jones, Rollins did not release another studio album for six years.\nIn 1968, he was the subject of a television documentary entitled Who is Sonny Rollins? (in the series Creative Persons), directed by Dick Fontaine.","Artistry And Influences":"Rollins''s tone has been described as \"biting and clear\". As a saxophonist, he had initially been attracted to the jump and R&B sounds of performers such as Louis Jordan, but soon became drawn into the mainstream tenor saxophone tradition. The German critic Joachim-Ernst Berendt described this tradition as sitting between the two poles of the strong sonority of Coleman Hawkins and the light flexible phrasing of Lester Young, which did so much to inspire the fleet improvisation of bebop in the 1950s. Other tenor saxophone influences include Ben Webster and Don Byas. By his mid-teens, Rollins became heavily influenced by alto saxophonist Charlie Parker. During his high school years, he was mentored by the pianist and composer Thelonious Monk, often rehearsing at Monk''s apartment."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (330, '1WmIo9ORq1IDlovUWFmo4Y', 'John', 'Coltrane', 'b625448e-bf4a-41c3-a421-72ad46cdb831', 2766215, 6, 'https://en.wikipedia.org/wiki/John_Coltrane', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/John_Coltrane_1963_cropped_ver2.jpg/500px-John_Coltrane_1963_cropped_ver2.jpg', 'Gelderen, Hugo van / Anefo', 'CC0', 'https://commons.wikimedia.org/wiki/File:John_Coltrane_1963_cropped_ver2.jpg', '{"Intro":"John William Coltrane (September 23, 1926 – July 17, 1967) was an American jazz saxophonist, bandleader, and composer. He is among the most influential and acclaimed figures in the history of jazz and 20th-century music.\nBorn and raised in North Carolina, Coltrane moved to Philadelphia after high school, where he immersed himself in the local jazz scene, studied music, and served in the Navy toward the end of World War II before making his professional debut in 1945. Working in the bebop and hard bop idioms early in his career, Coltrane helped pioneer the use of modes and was one of the players at the forefront of free jazz. He led at least fifty recording sessions and appeared on many albums by other musicians, including trumpeter Miles Davis and pianist Thelonious Monk. Over the course of his career, Coltrane''s music took on an increasingly spiritual dimension, as exemplified on his most acclaimed album A Love Supreme (1965) and others. Decades after his death, Coltrane remains influential, and he has received numerous posthumous awards, including a special Pulitzer Prize, and was canonized by the African Orthodox Church.\nHis second wife was pianist and harpist Alice Coltrane.  The couple had three children: John Jr. (1964–1982), a bassist; Ravi (born 1965), a saxophonist; and Oran (born 1967), a saxophonist, guitarist, drummer, and singer.","Biography":"Coltrane''s first recordings were made when he was a sailor\nColtrane was born in his parents'' apartment at 200 Hamlet Avenue in Hamlet, North Carolina, on September 23, 1926. His father was John R. Coltrane and his mother was Alice Blair. He grew up in High Point, North Carolina, and attended William Penn High School. While in high school, Coltrane played clarinet and alto horn in a community band before switching to the saxophone, after being influenced by the likes of Lester Young and Johnny Hodges. Beginning in December 1938, his father, aunt, and grandparents died within a few months of one another, leaving him to be raised by his mother and a close cousin. In June 1943, shortly after graduating from high school, Coltrane and his family moved to Philadelphia, where he got a job at a sugar refinery. In September that year, for his 17th birthday, his mother bought him his first saxophone, an alto. From 1944 to 1945, Coltrane took saxophone lessons at the Ornstein School of Music with Mike Guerra. Between early to mid-1945, he had his first professional work as a musician: a \"cocktail lounge trio\" with piano and guitar.\nAn important moment in the progression of Coltrane''s musical development occurred on June 5, 1945, when he saw Charlie Parker perform for the first time. In a 1960 DownBeat magazine article, he recalled: \"the first time I heard Bird play, it hit me right between the eyes.\"\nTo avoid being drafted by the Army, Coltrane enlisted in the Navy on August 6, 1945, the day the first U.S. atomic bomb was dropped on Japan. He was trained as an apprentice seaman at Sampson Naval Training Station in upstate New York before he was shipped to Pearl Harbor, where he was stationed at Manana Barracks, the largest posting of African American servicemen in the world. By the time he got to Hawaii in late 1945, the Navy was downsizing. Coltrane''s musical talent was recognized and, when he joined the Melody Masters, the base swing band, he became one of the few Navy men to serve as a musician without having been granted musician''s rating. Because the Melody Masters was an all-white band, Coltrane was treated as a guest performer to avoid alerting superior officers of his participation in the band. He continued to perform other duties when not playing with the band, including kitchen and security details. By the end of his service, he had assumed a leadership role in the band. His first recordings, an informal session in Hawaii with Navy musicians, occurred on July 13, 1946. He played alto saxophone on a selection of jazz standards and bebop tunes. He was officially discharged from the Navy on August 8, 1946. He was awarded the American Campaign Medal, Asiatic–Pacific Campaign Medal, and the World War II Victory Medal.\nAfter being discharged from the Navy as a seaman first class in August 1946, Coltrane returned to Philadelphia, where the city''s bustling jazz scene offered him many opportunities for both learning and playing. Coltrane used the G.I. Bill to enroll at the Granoff School of Music, where he studied music theory with jazz guitarist and composer Dennis Sandole. He would continue to work under Sandole''s tutelage from 1946 into the early 1950s. Coltrane also took saxophone lessons with Matthew Rastelli, a saxophone teacher at Granoff, once a week for about two or three years. However, the lessons stopped when Coltrane''s G.I. Bill funds ran out. After touring with King Kolax, he joined a band led by Jimmy Heath, who was introduced to Coltrane''s playing by his former Navy buddy, trumpeter William Massey, who had played with Coltrane in the Melody Masters. Although he started on alto saxophone, he switched to playing tenor saxophone in 1947 with Eddie Vinson.\nColtrane called this a time when \"a wider area of listening opened up for me. There were many things that people like Hawk  and Ben  and Tab Smith were doing in the ''40s that I didn''t understand, but that I felt emotionally.\" A significant influence, according to tenor saxophonist Odean Pope, was the Philadelphia pianist, composer, and theorist Hasaan Ibn Ali: \"Hasaan was the clue to ... the system that Trane uses. Hasaan was the great influence on Trane''s melodic concept.\" Coltrane became fanatical about practicing and developing his craft, practicing \"25 hours a day\" according to Jimmy Heath. Heath recalls an incident in a hotel in San Francisco when after a complaint was issued, Coltrane took the horn out of his mouth and practiced fingering for a full hour. Such was his dedication; it was common for him to fall asleep with the horn still in his mouth or practice a single note for hours on end.\nCharlie Parker, whom Coltrane had first heard perform before his time in the Navy, became an idol, and the two would occasionally play together in the late 1940s. He was a member of groups led by Dizzy Gillespie, Earl Bostic, and Johnny Hodges in the early to mid-1950s.\nIn 1955, Coltrane was freelancing in Philadelphia while studying with Sandole when he received a call from trumpeter Miles Davis. Davis had been successful in the 1940s, but his reputation and work had been damaged in part by heroin addiction; he was again active and about to form a quintet. Coltrane was with this edition of the Davis band (known as the \"First Great Quintet\"—along with Red Garland on piano, Paul Chambers on bass, and Philly Joe Jones on drums) from October 1955 to April 1957 (with a few absences). During this period Davis released several influential recordings that revealed the first signs of Coltrane''s growing ability. This quintet, represented by two marathon recording sessions for Prestige in 1956, resulted in the albums Cookin'', Relaxin'', Workin'', and Steamin''. The \"First Great Quintet\" disbanded due in part to Coltrane''s heroin addiction.\nDuring the later part of 1957, Coltrane worked with Thelonious Monk at New York''s Five Spot Café, and played in Monk''s quartet (July through December 1957), but, owing to contractual conflicts, took part in only one official studio recording session with this group. Coltrane recorded many sessions for Prestige under his own name at this time, but Monk refused to record for his old label. A private recording made by Juanita Naima Coltrane of a late summer 1957 reunion of the group was issued by Blue Note Records as Live at the Five Spot—Discovery! in 1993. A high quality tape of a concert given by this quartet in November 1957 was found later, and was released by Blue Note in 2005. Recorded by Voice of America, the performances confirm the group''s reputation, and the resulting album, Thelonious Monk Quartet with John Coltrane at Carnegie Hall, is very highly rated.\nBlue Train, Coltrane''s sole date as leader for Blue Note, featuring trumpeter Lee Morgan, bassist Paul Chambers, and trombonist Curtis Fuller, is often considered his best album from this period. Four of its five tracks are original Coltrane compositions, and the title track, \"Moment''s Notice\", and \"Lazy Bird\", have become standards.\nColtrane rejoined Davis in December 1957 after he recovered from his addiction. In October of that year, jazz critic Ira Gitler coined the term \"sheets of sound\" to describe the style Coltrane developed with Monk and was perfecting in Davis''s group, now a sextet. His playing was compressed, with rapid runs cascading in very many notes per minute. Coltrane recalled, \"I found that there were a certain number of chord progressions to play in a given time, and sometimes what I played didn''t work out in eighth notes, sixteenth notes, or triplets. I had to put the notes in uneven groups like fives and sevens in order to get them all in.\"\nColtrane stayed with Davis until April 1960, working with alto saxophonist Cannonball Adderley; pianists Red Garland, Bill Evans, and Wynton Kelly; bassist Paul Chambers; and drummers Philly Joe Jones and Jimmy Cobb. During this time he participated in the Davis sessions Milestones and Kind of Blue, and the concert recordings Miles & Monk at Newport (1963) and Jazz at the Plaza (1958).\nAt the end of this period, Coltrane recorded Giant Steps (1960), his  first released album as leader for Atlantic that contained only his compositions. The album''s title track is generally considered to have one of the most difficult chord progressions of any widely played jazz composition, eventually referred to as Coltrane changes. His development of these cycles led to further experimentation with improvised melody and harmony that he continued throughout his career.\nOne of Coltrane''s most acclaimed recordings, \"Giant Steps\" features harmonic structures more complex than were used by most jazz musicians of the time.\nColtrane formed his first quartet for live performances in 1960 for an appearance at the Jazz Gallery in New York City. After moving through different personnel, including Steve Kuhn, Pete La Roca, and Billy Higgins, he kept pianist McCoy Tyner, bassist Steve Davis, and drummer Elvin Jones. Tyner, a native of Philadelphia, had been a friend of Coltrane for some years, and the two men had an understanding that Tyner would join the band when he felt ready. My Favorite Things (1961) was the first album recorded by this band. It was Coltrane''s first album on soprano saxophone, which he began practicing while with Miles Davis. It was considered an unconventional move because the instrument was more associated with earlier jazz.\n1961–1962: First years with Impulse! Records\nIn 1961, Coltrane received an Edison Award for Giant Steps in Amsterdam.\nIn May 1961, Coltrane''s contract with Atlantic was bought by Impulse!. The move to Impulse! meant that Coltrane resumed his recording relationship with engineer Rudy Van Gelder, who had recorded his and Davis''s sessions for Prestige. He recorded most of his albums for Impulse! at Van Gelder''s studio in Englewood Cliffs, New Jersey.\nBy early 1961, bassist Davis had been replaced by Reggie Workman, while Eric Dolphy joined the group as a second horn. The quintet had a celebrated and extensively recorded residency at the Village Vanguard, which demonstrated Coltrane''s new direction. It included the most experimental music he had played, influenced by Indian ragas, modal jazz, and free jazz. John Gilmore, a longtime saxophonist with musician Sun Ra, was particularly influential; after hearing a Gilmore performance, Coltrane is reported to have said, \"He''s got it! Gilmore''s got the concept!\" The most celebrated of the Vanguard tunes, the 15-minute blues \"Chasin'' the Trane\", was strongly inspired by Gilmore''s music.\nIn 1961, Coltrane began pairing Workman with a second bassist, usually Art Davis or Donald Garrett. Garrett recalled playing a tape for Coltrane where \"I was playing with another bass player. We were doing some things rhythmically, and Coltrane became excited about the sound. We got the same kind of sound you get from the East Indian water drum. One bass remains in the lower register and is the stabilizing, pulsating thing, while the other bass is free to improvise, like the right hand would be on the drum. So Coltrane liked the idea.\" Coltrane also recalled, \"I thought another bass would add that certain rhythmic sound. We were playing a lot of stuff with a sort of suspended rhythm, with one bass playing a series of notes around one point, and it seemed that another bass could fill in the spaces.\" According to Dolphy, one night \"Wilbur Ware came in and up on the stand so they had three basses going. John and I got off the stand and listened.\" Coltrane employed two basses on the 1961 albums Olé Coltrane and Africa/Brass, and later on The John Coltrane Quartet Plays and Ascension. Both Reggie Workman and Jimmy Garrison play bass on the 1961 Village Vanguard recordings of \"India\" and \"Miles'' Mode\".\nDuring this period, critics were divided in their estimation of Coltrane, who had radically altered his style. Audiences, too, were perplexed; in France he was booed during his final tour with Davis. In 1961, DownBeat magazine called Coltrane and Dolphy players of \"anti-jazz\" in an article that bewildered and upset the musicians. Coltrane admitted some of his early solos were based mostly on technical ideas. Furthermore, Dolphy''s angular, voice-like playing earned him a reputation as a figurehead of the New Thing, also known as free jazz, a movement led by Ornette Coleman that was denigrated by some jazz musicians (including Davis) and critics. But as Coltrane''s style developed, he was determined to make every performance \"a whole expression of one''s being\".\nIn 1962, Dolphy departed and Jimmy Garrison replaced Workman as bassist. From then on, the \"Classic Quartet\", as it came to be known, with Tyner, Garrison, and Jones, produced searching, spiritually driven work. Coltrane was moving toward a more harmonically static style that allowed him to expand his improvisations rhythmically, melodically, and motivically. Harmonically complex music was still present, but on stage Coltrane heavily favored continually reworking his standard repertoire: \"Impressions\", \"My Favorite Things\", and \"I Want to Talk About You\".\nThe romantic ballad \"In a Sentimental Mood\" features Coltrane with pianist Duke Ellington, on their eponymous album.\nThe criticism of the quintet with Dolphy may have affected Coltrane. In contrast to the radicalism of his 1961 recordings at the Village Vanguard, his studio albums in the following two years (with the exception of 1962''s Coltrane, which featured a blistering version of Harold Arlen''s \"Out of This World\") were much more conservative. He recorded an album of ballads and participated in album collaborations with Duke Ellington and with singer Johnny Hartman, a baritone who specialized in ballads. The album Ballads (recorded 1961–62) is emblematic of Coltrane''s versatility, as the quartet shed new light on standards such as \"It''s Easy to Remember\". Despite a more polished approach in the studio, in concert, the quartet continued to balance their standard repertoire with more exploratory and challenging music, as can be heard on the albums Impressions (recorded 1961–63), Live at Birdland, and Newport ''63 (both recorded 1963). Impressions consists of two extended jams including the title track along with \"Dear Old Stockholm\", \"After the Rain\", and a blues. Coltrane later said he enjoyed having a \"balanced catalogue\".\nOn March 6, 1963, the group entered Van Gelder Studio in New Jersey and recorded a session that was lost for decades after its master tape was destroyed by Impulse! Records to cut down on storage space. On June 29, 2018, Impulse! released Both Directions at Once: The Lost Album, made up of seven tracks made from a spare copy Coltrane had given to his wife. On March 7, 1963, they were joined in the studio by Hartman for the recording of six tracks for the John Coltrane and Johnny Hartman album, released that July.\nImpulse! followed the successful \"lost album\" release with 2019''s Blue World, made up of a 1964 soundtrack to the film The Cat in the Bag, recorded in June 1964.\nThe Classic Quartet produced its best-selling album, A Love Supreme, in December 1964. A culmination of much of Coltrane''s work up to this point, this four-part suite is an ode to his faith in and love for God. These spiritual concerns characterized much of Coltrane''s composing and playing from this point onward—as can be seen from album titles such as Ascension, Om, and Meditations. The fourth movement of A Love Supreme, \"Psalm\", is, in fact, a musical setting for an original poem to God written by Coltrane, and printed in the album''s liner notes. Coltrane plays almost exactly one note for each syllable of the poem, and bases his phrasing on the words. The album was composed at Coltrane''s home in Dix Hills on Long Island.\nThe quartet played A Love Supreme live only three times, recorded twice – in July 1965 at a concert in Antibes, France, and in October 1965 in Seattle, Washington. A recording of the Antibes concert was released by Impulse! in 2002 on the remastered Deluxe Edition of A Love Supreme, and again in 2015 on the \"Super Deluxe Edition\" of The Complete Masters. A recently discovered second amateur recording titled A Love Supreme: Live in Seattle was released in 2021.\nA Love Supreme was reinterpreted, arranged, and performed by Danish harmonica player and arranger Mathias Heise with the Danish Radio Big Band for the album A Love Supreme Revisited in 2026, marking the hundredth anniversary for the birth of Coltrane.\n1965: Adding to the quartet and avant-garde jazz\nAs Coltrane''s interest in jazz became experimental, he added Pharoah Sanders (center; c. 1978) to his ensemble.\nIn his late period, Coltrane showed an interest in the avant-garde jazz of Ornette Coleman, Albert Ayler, and Sun Ra. He was especially influenced by the dissonance of Ayler''s trio with bassist Gary Peacock, who had worked with Paul Bley, and drummer Sunny Murray, whose playing was honed with Cecil Taylor as leader. Coltrane championed many young free jazz musicians such as Archie Shepp, and, under his influence, Impulse! became a leading free jazz label.\nAfter A Love Supreme was recorded, Ayler''s style became more prominent in Coltrane''s music. A series of recordings with the Classic Quartet in the first half of 1965 show Coltrane''s playing becoming abstract, with greater incorporation of devices like multiphonics, use of overtones, and playing in the altissimo register, as well as a mutated return of Coltrane''s sheets of sound. In the studio, he all but abandoned soprano saxophone to concentrate on tenor. The quartet responded by playing with increasing freedom. The group''s evolution can be traced through the albums The John Coltrane Quartet Plays, Living Space, Transition, New Thing at Newport, Sun Ship, and First Meditations.\nIn June 1965, he went into Van Gelder''s studio with ten other musicians (including Shepp, Pharoah Sanders, Freddie Hubbard, Marion Brown, and John Tchicai) to record Ascension, a 38-minute piece that included solos by young avant-garde musicians. The album was controversial primarily for the collective improvisation sections that separated the solos. After recording with the quartet over the next few months, Coltrane invited Sanders to join the band in September 1965. While Coltrane frequently used overblowing as an emotional exclamation-point, Sanders \"was involved in the search for ''human'' sounds on his instrument\", and drastically expanding the vocabulary of his horn by employing multiphonics, growling, and \"high register squeals  could imitate not only the human song but the human cry and shriek as well\". Regarding Coltrane''s decision to add Sanders to the band, critic Gary Giddins wrote, \"Those who had followed Coltrane to the edge of the galaxy now had the added challenge of a player who appeared to have little contact with earth.\"\nPercussionist Rashied Ali (pictured in 2007) augmented Coltrane''s sound.\nBy late 1965, Coltrane was regularly augmenting his group with Sanders and other free jazz musicians. Rashied Ali joined the group as a second drummer. This marked the end of the quartet. Claiming he was unable to hear himself over the two drummers, Tyner left the band shortly after the recording of Meditations. Jones left in early 1966, dissatisfied by sharing drumming duties with Ali and stating that, concerning Coltrane''s latest music, \"only poets can understand it\". In interviews, Tyner and Jones both voiced their displeasure with the music''s direction; however, they would incorporate some of the intensity of free jazz in their solo work. Later, both musicians expressed tremendous respect for Coltrane: regarding his late music, Jones stated, \"Well, of course it''s far out, because this is a tremendous mind that''s involved, you know. You wouldn''t expect Einstein to be playing jacks, would you?\" Tyner recalled, \"He was constantly pushing forward. He never rested on his laurels, he was always looking for what''s next ... he was always searching, like a scientist in a lab, looking for something new, a different direction ... He kept hearing these sounds in his head\". Jones and Tyner both recorded tributes to Coltrane, Tyner with Echoes of a Friend (1972) and Blues for Coltrane: A Tribute to John Coltrane (1987), and Jones with Live in Japan 1978: Dear John C. (1978) and Tribute to John Coltrane \"A Love Supreme\" (1994).\nThere is speculation that in 1965 Coltrane began using LSD, informing the \"cosmic\" transcendence of his late period. Nat Hentoff wrote, \"it is as if he and Sanders were speaking with ''the gift of tongues'' – as if their insights were of such compelling force that they have to transcend ordinary ways of musical speech and ordinary textures to be able to convey that part of the essence of being they have touched.\" After the departure of Tyner and Jones, Coltrane led a quintet with Sanders on tenor saxophone, his second wife Alice Coltrane on piano, Garrison on bass, and Ali on drums. When touring, the group was known for playing long versions of their repertoire, many stretching beyond 30 minutes to an hour. In concert, solos by band members often extended beyond fifteen minutes.\nThe group can be heard on several concert recordings from 1966, including Live at the Village Vanguard Again! and Live in Japan. (On the latter,  Coltrane and Sanders played, for the rare occasion, alto saxophones, which were presented to them by Yamaha.) In 1967, Coltrane entered the studio several times. Although pieces with Sanders have surfaced (the unusual \"To Be\" has both men on flute), most of the recordings were either with the quartet minus Sanders (Expression and Stellar Regions) or as a duo with Ali. The latter duo produced six performances that appear on the album Interstellar Space. Coltrane also continued to tour with the second quartet up until two months before his death; his penultimate live performance and final recorded one, a radio broadcast for the Olatunji Center of African Culture in New York City, was eventually released as an album in 2001.\nColtrane died of liver cancer at the age of 40 on July 17, 1967, at Huntington Hospital on Long Island. His funeral was held four days later at St. Peter''s Lutheran Church in New York City. The service was started by the Albert Ayler Quartet and finished by the Ornette Coleman Quartet. Coltrane is buried at Pinelawn Memorial Park in Farmingdale, New York.\nBiographer Lewis Porter speculated that the cause of Coltrane''s illness was hepatitis, although he also attributed the disease to Coltrane''s heroin use at a previous period in his life. Frederick J. Spencer wrote that Coltrane''s death could be attributed to his needle use \"or the bottle, or both\". He stated that \"he needles he used to inject the drugs may have had everything to do with\" Coltrane''s liver disease: \"If any needle was contaminated with the appropriate hepatitis virus, it may have caused a chronic infection leading to cirrhosis or cancer.\" He noted that despite Coltrane''s \"spiritual awakening\" in 1957, \"y then, he may have had chronic hepatitis and cirrhosis ... Unless he developed a primary focus elsewhere in later life and that spread to his liver, the seeds of John Coltrane''s cancer were sown in his days of addiction.\"\nColtrane''s death surprised many in the music community who were unaware of his condition. Miles Davis said, \"Coltrane''s death shocked everyone, took everyone by surprise. I knew he hadn''t looked too good ... But I didn''t know he was that sick – or even sick at all.\"","1926–1945: Early Life":"Coltrane''s first recordings were made when he was a sailor\nColtrane was born in his parents'' apartment at 200 Hamlet Avenue in Hamlet, North Carolina, on September 23, 1926. His father was John R. Coltrane and his mother was Alice Blair. He grew up in High Point, North Carolina, and attended William Penn High School. While in high school, Coltrane played clarinet and alto horn in a community band before switching to the saxophone, after being influenced by the likes of Lester Young and Johnny Hodges. Beginning in December 1938, his father, aunt, and grandparents died within a few months of one another, leaving him to be raised by his mother and a close cousin. In June 1943, shortly after graduating from high school, Coltrane and his family moved to Philadelphia, where he got a job at a sugar refinery. In September that year, for his 17th birthday, his mother bought him his first saxophone, an alto. From 1944 to 1945, Coltrane took saxophone lessons at the Ornstein School of Music with Mike Guerra. Between early to mid-1945, he had his first professional work as a musician: a \"cocktail lounge trio\" with piano and guitar.\nAn important moment in the progression of Coltrane''s musical development occurred on June 5, 1945, when he saw Charlie Parker perform for the first time. In a 1960 DownBeat magazine article, he recalled: \"the first time I heard Bird play, it hit me right between the eyes.\"","1946–1954: Immediate Post-War Career":"After being discharged from the Navy as a seaman first class in August 1946, Coltrane returned to Philadelphia, where the city''s bustling jazz scene offered him many opportunities for both learning and playing. Coltrane used the G.I. Bill to enroll at the Granoff School of Music, where he studied music theory with jazz guitarist and composer Dennis Sandole. He would continue to work under Sandole''s tutelage from 1946 into the early 1950s. Coltrane also took saxophone lessons with Matthew Rastelli, a saxophone teacher at Granoff, once a week for about two or three years. However, the lessons stopped when Coltrane''s G.I. Bill funds ran out. After touring with King Kolax, he joined a band led by Jimmy Heath, who was introduced to Coltrane''s playing by his former Navy buddy, trumpeter William Massey, who had played with Coltrane in the Melody Masters. Although he started on alto saxophone, he switched to playing tenor saxophone in 1947 with Eddie Vinson.\nColtrane called this a time when \"a wider area of listening opened up for me. There were many things that people like Hawk  and Ben  and Tab Smith were doing in the ''40s that I didn''t understand, but that I felt emotionally.\" A significant influence, according to tenor saxophonist Odean Pope, was the Philadelphia pianist, composer, and theorist Hasaan Ibn Ali: \"Hasaan was the clue to ... the system that Trane uses. Hasaan was the great influence on Trane''s melodic concept.\" Coltrane became fanatical about practicing and developing his craft, practicing \"25 hours a day\" according to Jimmy Heath. Heath recalls an incident in a hotel in San Francisco when after a complaint was issued, Coltrane took the horn out of his mouth and practiced fingering for a full hour. Such was his dedication; it was common for him to fall asleep with the horn still in his mouth or practice a single note for hours on end.\nCharlie Parker, whom Coltrane had first heard perform before his time in the Navy, became an idol, and the two would occasionally play together in the late 1940s. He was a member of groups led by Dizzy Gillespie, Earl Bostic, and Johnny Hodges in the early to mid-1950s.","1955–1957: Miles And Monk Period":"In 1955, Coltrane was freelancing in Philadelphia while studying with Sandole when he received a call from trumpeter Miles Davis. Davis had been successful in the 1940s, but his reputation and work had been damaged in part by heroin addiction; he was again active and about to form a quintet. Coltrane was with this edition of the Davis band (known as the \"First Great Quintet\"—along with Red Garland on piano, Paul Chambers on bass, and Philly Joe Jones on drums) from October 1955 to April 1957 (with a few absences). During this period Davis released several influential recordings that revealed the first signs of Coltrane''s growing ability. This quintet, represented by two marathon recording sessions for Prestige in 1956, resulted in the albums Cookin'', Relaxin'', Workin'', and Steamin''. The \"First Great Quintet\" disbanded due in part to Coltrane''s heroin addiction.\nDuring the later part of 1957, Coltrane worked with Thelonious Monk at New York''s Five Spot Café, and played in Monk''s quartet (July through December 1957), but, owing to contractual conflicts, took part in only one official studio recording session with this group. Coltrane recorded many sessions for Prestige under his own name at this time, but Monk refused to record for his old label. A private recording made by Juanita Naima Coltrane of a late summer 1957 reunion of the group was issued by Blue Note Records as Live at the Five Spot—Discovery! in 1993. A high quality tape of a concert given by this quartet in November 1957 was found later, and was released by Blue Note in 2005. Recorded by Voice of America, the performances confirm the group''s reputation, and the resulting album, Thelonious Monk Quartet with John Coltrane at Carnegie Hall, is very highly rated.\nBlue Train, Coltrane''s sole date as leader for Blue Note, featuring trumpeter Lee Morgan, bassist Paul Chambers, and trombonist Curtis Fuller, is often considered his best album from this period. Four of its five tracks are original Coltrane compositions, and the title track, \"Moment''s Notice\", and \"Lazy Bird\", have become standards.","1959–1961: Period With Atlantic Records":"At the end of this period, Coltrane recorded Giant Steps (1960), his  first released album as leader for Atlantic that contained only his compositions. The album''s title track is generally considered to have one of the most difficult chord progressions of any widely played jazz composition, eventually referred to as Coltrane changes. His development of these cycles led to further experimentation with improvised melody and harmony that he continued throughout his career.\nOne of Coltrane''s most acclaimed recordings, \"Giant Steps\" features harmonic structures more complex than were used by most jazz musicians of the time.\nColtrane formed his first quartet for live performances in 1960 for an appearance at the Jazz Gallery in New York City. After moving through different personnel, including Steve Kuhn, Pete La Roca, and Billy Higgins, he kept pianist McCoy Tyner, bassist Steve Davis, and drummer Elvin Jones. Tyner, a native of Philadelphia, had been a friend of Coltrane for some years, and the two men had an understanding that Tyner would join the band when he felt ready. My Favorite Things (1961) was the first album recorded by this band. It was Coltrane''s first album on soprano saxophone, which he began practicing while with Miles Davis. It was considered an unconventional move because the instrument was more associated with earlier jazz.","1961–1962: First Years With Impulse! Records":"In 1961, Coltrane received an Edison Award for Giant Steps in Amsterdam.\nIn May 1961, Coltrane''s contract with Atlantic was bought by Impulse!. The move to Impulse! meant that Coltrane resumed his recording relationship with engineer Rudy Van Gelder, who had recorded his and Davis''s sessions for Prestige. He recorded most of his albums for Impulse! at Van Gelder''s studio in Englewood Cliffs, New Jersey.\nBy early 1961, bassist Davis had been replaced by Reggie Workman, while Eric Dolphy joined the group as a second horn. The quintet had a celebrated and extensively recorded residency at the Village Vanguard, which demonstrated Coltrane''s new direction. It included the most experimental music he had played, influenced by Indian ragas, modal jazz, and free jazz. John Gilmore, a longtime saxophonist with musician Sun Ra, was particularly influential; after hearing a Gilmore performance, Coltrane is reported to have said, \"He''s got it! Gilmore''s got the concept!\" The most celebrated of the Vanguard tunes, the 15-minute blues \"Chasin'' the Trane\", was strongly inspired by Gilmore''s music.\nIn 1961, Coltrane began pairing Workman with a second bassist, usually Art Davis or Donald Garrett. Garrett recalled playing a tape for Coltrane where \"I was playing with another bass player. We were doing some things rhythmically, and Coltrane became excited about the sound. We got the same kind of sound you get from the East Indian water drum. One bass remains in the lower register and is the stabilizing, pulsating thing, while the other bass is free to improvise, like the right hand would be on the drum. So Coltrane liked the idea.\" Coltrane also recalled, \"I thought another bass would add that certain rhythmic sound. We were playing a lot of stuff with a sort of suspended rhythm, with one bass playing a series of notes around one point, and it seemed that another bass could fill in the spaces.\" According to Dolphy, one night \"Wilbur Ware came in and up on the stand so they had three basses going. John and I got off the stand and listened.\" Coltrane employed two basses on the 1961 albums Olé Coltrane and Africa/Brass, and later on The John Coltrane Quartet Plays and Ascension. Both Reggie Workman and Jimmy Garrison play bass on the 1961 Village Vanguard recordings of \"India\" and \"Miles'' Mode\".\nDuring this period, critics were divided in their estimation of Coltrane, who had radically altered his style. Audiences, too, were perplexed; in France he was booed during his final tour with Davis. In 1961, DownBeat magazine called Coltrane and Dolphy players of \"anti-jazz\" in an article that bewildered and upset the musicians. Coltrane admitted some of his early solos were based mostly on technical ideas. Furthermore, Dolphy''s angular, voice-like playing earned him a reputation as a figurehead of the New Thing, also known as free jazz, a movement led by Ornette Coleman that was denigrated by some jazz musicians (including Davis) and critics. But as Coltrane''s style developed, he was determined to make every performance \"a whole expression of one''s being\".","1962–1965: Classic Quartet Period":"In 1962, Dolphy departed and Jimmy Garrison replaced Workman as bassist. From then on, the \"Classic Quartet\", as it came to be known, with Tyner, Garrison, and Jones, produced searching, spiritually driven work. Coltrane was moving toward a more harmonically static style that allowed him to expand his improvisations rhythmically, melodically, and motivically. Harmonically complex music was still present, but on stage Coltrane heavily favored continually reworking his standard repertoire: \"Impressions\", \"My Favorite Things\", and \"I Want to Talk About You\".\nThe romantic ballad \"In a Sentimental Mood\" features Coltrane with pianist Duke Ellington, on their eponymous album.\nThe criticism of the quintet with Dolphy may have affected Coltrane. In contrast to the radicalism of his 1961 recordings at the Village Vanguard, his studio albums in the following two years (with the exception of 1962''s Coltrane, which featured a blistering version of Harold Arlen''s \"Out of This World\") were much more conservative. He recorded an album of ballads and participated in album collaborations with Duke Ellington and with singer Johnny Hartman, a baritone who specialized in ballads. The album Ballads (recorded 1961–62) is emblematic of Coltrane''s versatility, as the quartet shed new light on standards such as \"It''s Easy to Remember\". Despite a more polished approach in the studio, in concert, the quartet continued to balance their standard repertoire with more exploratory and challenging music, as can be heard on the albums Impressions (recorded 1961–63), Live at Birdland, and Newport ''63 (both recorded 1963). Impressions consists of two extended jams including the title track along with \"Dear Old Stockholm\", \"After the Rain\", and a blues. Coltrane later said he enjoyed having a \"balanced catalogue\".\nOn March 6, 1963, the group entered Van Gelder Studio in New Jersey and recorded a session that was lost for decades after its master tape was destroyed by Impulse! Records to cut down on storage space. On June 29, 2018, Impulse! released Both Directions at Once: The Lost Album, made up of seven tracks made from a spare copy Coltrane had given to his wife. On March 7, 1963, they were joined in the studio by Hartman for the recording of six tracks for the John Coltrane and Johnny Hartman album, released that July.\nImpulse! followed the successful \"lost album\" release with 2019''s Blue World, made up of a 1964 soundtrack to the film The Cat in the Bag, recorded in June 1964.\nThe Classic Quartet produced its best-selling album, A Love Supreme, in December 1964. A culmination of much of Coltrane''s work up to this point, this four-part suite is an ode to his faith in and love for God. These spiritual concerns characterized much of Coltrane''s composing and playing from this point onward—as can be seen from album titles such as Ascension, Om, and Meditations. The fourth movement of A Love Supreme, \"Psalm\", is, in fact, a musical setting for an original poem to God written by Coltrane, and printed in the album''s liner notes. Coltrane plays almost exactly one note for each syllable of the poem, and bases his phrasing on the words. The album was composed at Coltrane''s home in Dix Hills on Long Island.\nThe quartet played A Love Supreme live only three times, recorded twice – in July 1965 at a concert in Antibes, France, and in October 1965 in Seattle, Washington. A recording of the Antibes concert was released by Impulse! in 2002 on the remastered Deluxe Edition of A Love Supreme, and again in 2015 on the \"Super Deluxe Edition\" of The Complete Masters. A recently discovered second amateur recording titled A Love Supreme: Live in Seattle was released in 2021.\nA Love Supreme was reinterpreted, arranged, and performed by Danish harmonica player and arranger Mathias Heise with the Danish Radio Big Band for the album A Love Supreme Revisited in 2026, marking the hundredth anniversary for the birth of Coltrane.","Personal Life And Religious Beliefs":"Coltrane was born and raised in a Christian home. He was influenced by religion and spirituality beginning in childhood. His maternal grandfather, the Reverend William Blair, was a minister at an African Methodist Episcopal Zion Church in High Point, North Carolina, and his paternal grandfather, the Reverend William H. Coltrane, was an A.M.E. Zion minister in Hamlet, North Carolina. Critic Norman Weinstein observed the parallel between Coltrane''s music and his experience in the southern church, which included practicing music there as a youth.\nIn 1955, Coltrane married Naima (née Juanita Grubbs). Naima Coltrane, a Muslim convert, heavily influenced his spirituality. When the couple married, she had a five-year-old daughter named Antonia, later named Syeeda, whom Coltrane adopted. He met Naima at the home of bassist Steve Davis in Philadelphia. The love ballad he wrote to honor his wife, \"Naima\", was Coltrane''s favorite composition. In 1956, the couple left Philadelphia with their daughter and moved to New York City. In August 1957, the three moved into an apartment on 103rd Street and Amsterdam Avenue in New York. A few years later, John and Naima purchased a home at 116–60 Mexico Street in St. Albans, Queens. This is the house where they would break up in 1963.\nAbout the breakup, Naima said in the biography Chasin'' the Trane by J. C. Thomas, \"I could feel it was going to happen sooner or later, so I wasn''t really surprised when John moved out of the house in the summer of 1963. He didn''t offer any explanation. He just told me there were things he had to do, and he left only with his clothes and his horns. He stayed in a hotel sometimes, other times with his mother in Philadelphia. All he said was, ''Naima, I''m going to make a change.'' Even though I could feel it coming, it hurt, and I didn''t get over it for at least another year.\" Despite this, Coltrane kept a close relationship with Naima, even calling her in 1964 to tell her that ninety percent of his playing would be prayer. They remained in touch until his death in 1967. Naima Coltrane died of a heart attack in October 1996.\nIn 1957, Coltrane had a religious experience that may have helped him overcome the heroin addiction and alcoholism he had struggled with since 1948. In the liner notes of A Love Supreme, Coltrane stated that in 1957 he experienced \"by the grace of God, a spiritual awakening which was to lead me to a richer, fuller, more productive life. At that time, in gratitude, I humbly asked to be given the means and privilege to make others happy through music.\" Further evidence of this universal view can be found in the liner notes of Meditations (1965) in which Coltrane declares, \"I believe in all religions.\"\nIn 1963, he met pianist Alice McLeod. He and Alice moved in together and had two sons before he became \"officially divorced from Naima in 1966, at which time  and Alice were immediately married.\" John Jr. was born in 1964, Ravi in 1965, and Oranyan (\"Oran\") in 1967. According to the musician Peter Lavezzoli, \"Alice brought happiness and stability to John''s life, not only because they had children, but also because they shared many of the same spiritual beliefs, particularly a mutual interest in Indian philosophy. Alice also understood what it was like to be a professional musician.\"\nSpiritual influence in music and religious exploration\nAfter A Love Supreme, many of the titles of his albums and songs had spiritual connotations: Ascension, Meditations, Om, Selflessness, \"Amen\", \"Ascent\", \"Attaining\", \"Dear Lord\", \"Prayer and Meditation Suite\", and \"The Father and the Son and the Holy Ghost\". His library of books included The Gospel of Sri Ramakrishna, the Bhagavad Gita, and Paramahansa Yogananda''s Autobiography of a Yogi. The last of these describes, in Lavezzoli''s words, a \"search for universal truth, a journey that Coltrane had also undertaken. Yogananda believed that both Eastern and Western spiritual paths were efficacious, and wrote of the similarities between Krishna and Christ. This openness to different traditions resonated with Coltrane, who studied the Qur''an, the Bible, Kabbalah, and astrology with equal sincerity.\" He also explored Hinduism, Jiddu Krishnamurti, African history, the philosophical teachings of Plato and Aristotle, and Zen Buddhism.\nIn October 1965, Coltrane recorded Om, referring to the sacred syllable in Hinduism, which symbolizes the infinite or the entire universe. Coltrane described Om as the \"first syllable, the primal word, the word of power\". The 29-minute recording contains chants from the Hindu Bhagavad Gita and the Buddhist Tibetan Book of the Dead, and a recitation of a passage describing the primal verbalization \"om\" as a cosmic and spiritual common denominator in all things.\nColtrane''s spiritual journey was interwoven with his investigation of world music. He believed in not only a universal musical structure that transcended ethnic distinctions, but also being able to harness the mystical language of music itself. His study of Indian music led him to believe that certain sounds and scales could \"produce specific emotional meanings\". According to Coltrane, the goal of a musician was to understand these forces, control them, and elicit a response from the audience. He said, \"I would like to bring to people something like happiness. I would like to discover a method so that if I want it to rain, it will start right away to rain. If one of my friends is ill, I''d like to play a certain song and he will be cured; when he''d be broke, I''d bring out a different song and immediately he''d receive all the money he needed.\"","Spiritual Influence In Music And Religious Exploration":"After A Love Supreme, many of the titles of his albums and songs had spiritual connotations: Ascension, Meditations, Om, Selflessness, \"Amen\", \"Ascent\", \"Attaining\", \"Dear Lord\", \"Prayer and Meditation Suite\", and \"The Father and the Son and the Holy Ghost\". His library of books included The Gospel of Sri Ramakrishna, the Bhagavad Gita, and Paramahansa Yogananda''s Autobiography of a Yogi. The last of these describes, in Lavezzoli''s words, a \"search for universal truth, a journey that Coltrane had also undertaken. Yogananda believed that both Eastern and Western spiritual paths were efficacious, and wrote of the similarities between Krishna and Christ. This openness to different traditions resonated with Coltrane, who studied the Qur''an, the Bible, Kabbalah, and astrology with equal sincerity.\" He also explored Hinduism, Jiddu Krishnamurti, African history, the philosophical teachings of Plato and Aristotle, and Zen Buddhism.\nIn October 1965, Coltrane recorded Om, referring to the sacred syllable in Hinduism, which symbolizes the infinite or the entire universe. Coltrane described Om as the \"first syllable, the primal word, the word of power\". The 29-minute recording contains chants from the Hindu Bhagavad Gita and the Buddhist Tibetan Book of the Dead, and a recitation of a passage describing the primal verbalization \"om\" as a cosmic and spiritual common denominator in all things.","Study Of World Music":"Coltrane''s spiritual journey was interwoven with his investigation of world music. He believed in not only a universal musical structure that transcended ethnic distinctions, but also being able to harness the mystical language of music itself. His study of Indian music led him to believe that certain sounds and scales could \"produce specific emotional meanings\". According to Coltrane, the goal of a musician was to understand these forces, control them, and elicit a response from the audience. He said, \"I would like to bring to people something like happiness. I would like to discover a method so that if I want it to rain, it will start right away to rain. If one of my friends is ill, I''d like to play a certain song and he will be cured; when he''d be broke, I''d bring out a different song and immediately he''d receive all the money he needed.\"","Veneration":"Saint John ColtraneColtrane icon at the St. John Coltrane African Orthodox ChurchVenerated inAfrican Orthodox ChurchEpiscopal ChurchCanonized1982, St. John Coltrane Church, 2097 Turk Blvd, San Francisco, California, 94115, by the African Orthodox ChurchFeastDecember 8 (AOC)PatronageAll artists\nAfter Coltrane''s death, a congregation called the Yardbird Temple in San Francisco began worshipping him as God incarnate. The group was named after Charlie \"Yardbird\" Parker, whom they equated to John the Baptist. The congregation became affiliated with the African Orthodox Church; this involved changing Coltrane''s status from a god to a saint. The resultant St. John Coltrane African Orthodox Church in San Francisco is the only African Orthodox church that incorporates Coltrane''s music and his lyrics as prayers in its liturgy.\nRev. F. W. King, describing the African Orthodox Church of Saint John Coltrane, stated, \"We are Coltrane-conscious ... God dwells in the musical majesty of his sounds.\"\nFor The New York Times, journalist Samuel G. Freedman wrote, ... the Coltrane church is not a gimmick or a forced alloy of nightclub music and ethereal faith. Its message of deliverance through divine sound is actually quite consistent with Coltrane''s own experience and message. ... In both implicit and explicit ways, Coltrane also functioned as a religious figure. Addicted to heroin in the 1950s, he quit cold turkey, and later explained that he had heard the voice of God during his anguishing withdrawal. ... In 1966, an interviewer in Japan asked Coltrane what he hoped to be in five years, and Coltrane replied, \"a saint\".\nMusicians at St. John Coltrane African Orthodox Church, San Francisco, 2009\nColtrane is depicted as one of the 90 saints in the Dancing Saints icon of St. Gregory of Nyssa Episcopal Church in San Francisco. The icon is a 3,000-square-foot (280 m2) painting in the Byzantine iconographic style that wraps around the entire church rotunda. It was executed by Mark Dukes, an ordained deacon at the Saint John Coltrane African Orthodox Church who painted other icons of Coltrane for the Coltrane Church. Saint Barnabas Episcopal Church in Newark, New Jersey, included Coltrane on its list of historical black saints and made a \"case for sainthood\" for him in an article on its website.\nDocumentaries about Coltrane and the church include Alan Klingenstein''s The Church of Saint Coltrane (1996), and a 2004 program presented by Alan Yentob for the BBC.","General And Cited References":"DeVito, Chris; Fujioka, Yasuhiro; Schmaler, Wolf; Wild, David (2008). The John Coltrane Reference. Routledge. ISBN 978-0-415-97755-5.\nLavezzoli, Peter (2006). The Dawn of Indian Music in the West. Continuum International Publishing Group. ISBN 0-8264-1815-5.\nNisenson, Eric (1995). Ascension: John Coltrane and His Quest. Da Capo Press. ISBN 0-306-80644-4.\nPorter, Lewis (1999). John Coltrane: His Life and Music. University of Michigan Press. ISBN 0-472-08643-X.","1967: Illness And Death":"Coltrane died of liver cancer at the age of 40 on July 17, 1967, at Huntington Hospital on Long Island. His funeral was held four days later at St. Peter''s Lutheran Church in New York City. The service was started by the Albert Ayler Quartet and finished by the Ornette Coleman Quartet. Coltrane is buried at Pinelawn Memorial Park in Farmingdale, New York.\nBiographer Lewis Porter speculated that the cause of Coltrane''s illness was hepatitis, although he also attributed the disease to Coltrane''s heroin use at a previous period in his life. Frederick J. Spencer wrote that Coltrane''s death could be attributed to his needle use \"or the bottle, or both\". He stated that \"he needles he used to inject the drugs may have had everything to do with\" Coltrane''s liver disease: \"If any needle was contaminated with the appropriate hepatitis virus, it may have caused a chronic infection leading to cirrhosis or cancer.\" He noted that despite Coltrane''s \"spiritual awakening\" in 1957, \"y then, he may have had chronic hepatitis and cirrhosis ... Unless he developed a primary focus elsewhere in later life and that spread to his liver, the seeds of John Coltrane''s cancer were sown in his days of addiction.\"\nColtrane''s death surprised many in the music community who were unaware of his condition. Miles Davis said, \"Coltrane''s death shocked everyone, took everyone by surprise. I knew he hadn''t looked too good ... But I didn''t know he was that sick – or even sick at all.\"","Artistry":"Coltrane started out on alto saxophone, but in 1947, when he joined King Kolax''s band, he switched to tenor saxophone, the instrument he became known for playing. In the early 1960s, during his contract with Atlantic, he also played soprano saxophone.\nAssistant music editor at Time Out John Lewis assessed, \"By 1962, Coltrane had developed a brand of modal jazz that invoked Indian and Arabic scales while maintaining an impassioned spiritual focus. As he spoke in tongues on tenor and soprano saxophone, his now legendary Fab Four rumbled beneath him, playing hard bop that pushed towards India and Africa, toward soul,  even toward psychedelia.\"\nHis preference for playing melody higher on the range of the tenor saxophone is attributed to his training on alto horn and clarinet. His \"sound concept\", manipulated in one''s vocal tract, of the tenor was set higher than the normal range of the instrument. Coltrane observed how his experience playing the soprano saxophone gradually affected his style on the tenor, stating \"the soprano, by being this small instrument, I found that playing the lowest note on it was like playing ... one of the middle notes in the tenor ... I found that I would play all over this instrument ... And on tenor, I hadn''t always played all over it, because I was playing certain ideas which would just run in certain ranges ... By playing on the soprano and becoming accustomed to playing from that low B-flat on up, it soon got so when I went to tenor, I found myself doing the same thing ... And this caused ... the willingness to change and just try to play... as much of the instrument as possible.\"\nToward the end of his career, he experimented with flute in his live performances and studio recordings (Live at the Village Vanguard Again!, Expression). After Eric Dolphy died in June 1964, his mother gave Coltrane his flute and bass clarinet.\nAccording to drummer Rashied Ali, Coltrane had an interest in the drums. He would often have a spare drum set on concert stages that he would play. His interest in the drums and his penchant for having solos with the drums resonated on tracks such as \"Pursuance\" and \"The Drum Thing\" from A Love Supreme and Crescent, respectively. It resulted in the album Interstellar Space with Ali. In an interview with Nat Hentoff in late 1965 or early 1966, Coltrane stated: \"I feel the need for more time, more rhythm all around me. And with more than one drummer, the rhythm can be more multi-directional.\" In an August 1966 interview with Frank Kofsky, Coltrane repeatedly emphasized his affinity for drums, saying \"I feel so strongly about drums, I really do.\" Later that year, Coltrane would record the music released posthumously on Offering: Live at Temple University, which features Ali on drums supplemented by three percussionists.\nColtrane''s tenor (Selmer Mark VI, serial number 125571, dated 1965) and soprano (Selmer Mark VI, serial number 99626, dated 1962) saxophones were auctioned on February 20, 2005, to raise money for the John Coltrane Foundation.\nAlthough he rarely played alto, he owned a prototype Yamaha alto saxophone given to him by the company as an endorsement in 1966. He can be heard playing it on live albums recorded in Japan, such as Second Night in Tokyo, and is pictured using it on the cover of the compilation Live in Japan. He can also be heard playing the Yamaha alto on the album Stellar Regions."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (332, '1WmIo9ORq1IDlovUWFmo4Y', 'Ralph', 'Peterson', '33283e4c-ac47-4b15-9031-49e7eda5f051', 272055, 4, 'https://en.wikipedia.org/wiki/Ralph_Peterson_Jr.', NULL, NULL, NULL, NULL, '{"Intro":"Ralph Peterson Jr. (May 20, 1962 – March 1, 2021) was an American jazz drummer, composer, teacher, and bandleader.","Early Life":"Peterson''s father, Ralph Peterson, Sr., was the first black police chief and first black mayor of Pleasantville, New Jersey, where Peterson was raised. Four of Peterson''s uncles and his grandfather were drummers, and Peterson himself began on percussion at age three. Peterson played trumpet at Pleasantville High School and worked locally in funk groups. He applied to Livingston College at Rutgers University to study drums, but he failed the percussion entrance exam and enrolled as a trumpeter instead, graduating in 1984.","Career":"In 1983, he joined Art Blakey''s Jazz Messengers as the group''s second drummer. Chosen by Blakey himself to fill the drum chair, Peterson remained with Blakey until the jazz legend’s 1990 death. He dedicated a 1994 Ralph Peterson Quintet album, Art, to the repertoire of his mentor. He worked with Terence Blanchard and Donald Harrison in 1984, and with Walter Davis (1985, 1989), Tom Harrell (1985), Out of the Blue (1985–1988), Branford Marsalis (1986), David Murray, Craig Harris (1987), James Spaulding (1988), Roy Hargrove (1989), Jon Faddis (1989), Dewey Redman, Mark Helias (1989), and Wynton Marsalis (with the Count Basie ghost band).\nDuring the 1990s, Peterson played as a sideman with Jack Walrath, Craig Handy, Charles Lloyd, Kip Hanrahan (1992), Bheki Mseleku, Courtney Pine, Steve Coleman, George Colligan, Stanley Cowell, Mark Shim, and Betty Carter.\nHe began recording as a leader in 1988, with a quintet (Terence Blanchard, Steve Wilson, Geri Allen, and Phil Bowler) on V and Volition. He also worked with Allen and Bowler as a trio in \"Triangular\"; Essiet Essiet replaced Bowler for the 1988 Triangular recording. In 1989 he recorded in the quartet format as \"The Fo''tet\" with Don Byron, Steve Wilson (later Bobby Franchesini), Melissa Slocum (later Belden Bullock), and Bryan Carrott. After living in Canada for some time, he returned to Philadelphia, where he worked again with \"The Fo''tet,” and recorded as Triangular 2 with Slocum and Uri Caine. He also led the group \"Hip Pocket,” with whom he played trumpet.\nOn May 21, 2021, Peterson’s Onyx Productions released Raise Up Off Me, Peterson’s final full-length album. Comprising five Peterson originals and compositions by Zaccai Curtis, Bud Powell, James Williams (musician), Patrice Rushen, and John Hicks, the album was hailed as Peterson’s “closing statement.” In the liner notes, Orrin Evans tied Peterson’s music to his life:\nIf you knew Ralph Peterson, you knew whenever he titled a song or album, it directly correlated to something going on in his life. Art (1994, Blue Note) was Ralph’s tribute to his mentor, Art Blakey, who had just passed. Reclamation Project (1995, Evidence) was his way of telling us he was reclaiming his life and career. “The Trials of Trust and Treachery” off of Subliminal Seduction (2002, Criss Cross) was his homage to the difficulty but importance of long-term relationships. While Raise Up Off Me can easily be associated with 2020, the Black Lives Matter Movement, and the pandemic, the message I hear is Ralph’s fight to LIVE!","Personal Life":"Peterson taught at the University of the Arts in Philadelphia and Boston’s Berklee College of Music, where he started in 2003.  In 2010, Peterson started his own Onyx Productions Music Label.\nIn his twenties, Peterson struggled with drug addiction, though after achieving sobriety used his difficulties to “help those coming up behind him, either as a compass point or a cautionary tale.”\nIn addition to his musical work, Peterson ran a Boston taekwondo studio for many years and was ranked as a fifth dan black belt in 2019.\nPeterson died at his home in Dartmouth, Massachusetts, after a six-year battle with cancer on March 1, 2021, at age 58. He was survived by his wife Linea, daughter Sonora Slocum, stepdaughters Saydee and Haylee McQuay, and his spiritual daughter Jazz Robertson."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (333, '1WmIo9ORq1IDlovUWFmo4Y', 'Bob', 'Mintzer', '1e9b47ce-21eb-480a-9c7a-ac2dd8b0502a', 200704, 6, 'https://en.wikipedia.org/wiki/Bob_Mintzer', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Yellowjackets_-_Leverkusener_Jazztage_2015-3444.jpg/500px-Yellowjackets_-_Leverkusener_Jazztage_2015-3444.jpg', 'Andreas Lawen, Fotandi', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Yellowjackets_-_Leverkusener_Jazztage_2015-3444.jpg', '{"Intro":"Robert Alan Mintzer (born January 27, 1953) is an American jazz saxophonist, composer, arranger, and big band leader.","Early Life":"Mintzer was born and raised in a Jewish family in New Rochelle, New York, on January 27, 1953. He attended the Interlochen Arts Academy, Michigan from 1969 to 1970, then was at the Hartt School of Music, Hartford, Connecticut for two years, before attending the Manhattan School of Music from 1972 to 1974.","Later Life And Career":"Early in his career, Mintzer played in various big bands, including those led by Buddy Rich (1975–77), Thad Jones and Mel Lewis (1977–79), and Sam Jones (1978–80). While with Rich, he began writing big-band music, and has since composed and arranged hundreds of pieces. In 2008, Mintzer and his family moved to Los Angeles, where he joined the faculty of the University of Southern California.\nHe is a member of the Grammy award-winning Yellowjackets and holds the Buzz McCoy endowed chair of jazz studies at the University of Southern California.\nIn 2014, he began sharing the role of Chief Conductor of the WDR Big Band in Cologne, Germany with Vince Mendoza."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (335, '1WmIo9ORq1IDlovUWFmo4Y', 'Michael', 'White', '69c60861-f0c9-463f-9b8d-fde6336afd8e', 254823, 8, 'https://en.wikipedia.org/wiki/Michael_White_(violinist)', NULL, NULL, NULL, NULL, '{"Intro":"Michael Walter White (24 May 1930 – 6 December 2016) was an American jazz violinist.\nWhite was born in Houston, Texas, and grew up in Oakland, California, taking up the violin when he was six years old.  His initial career break occurred in 1965, when he played with the John Handy Quintet at the Monterey Jazz Festival, and subsequently recorded three albums with Handy.  White was among the first to play the violin in avant-garde jazz, and in the late 1960s became one of the first jazz violinists to play jazz rock fusion (with his band The Fourth Way). During his career, he played with musicians such as Sun Ra, Prince Lasha, McCoy Tyner, Eric Dolphy, Wes Montgomery, Pharoah Sanders, Kenny Dorham, Joe Henderson, John Lee Hooker, and Richard Davis. In early 2007, The Michael White Quintet''s \"Mechanical Man\" won in the 6th Annual Independent Music Awards for Best Jazz Song.\nWhite eventually settled in Los Angeles, California. After a long period of obscurity, in the mid 1990s he was involved in a reunion of the Handy Quintet and recorded an album as co-leader with Bill Frisell, Motion Pictures (1997). In 2006 White released the album Voices."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (336, '1WmIo9ORq1IDlovUWFmo4Y', 'Dan', 'Morgenstern', '5338dd4f-5a74-4a7d-8efa-e604dac98eab', 1043095, 12, 'https://en.wikipedia.org/wiki/Dan_Morgenstern', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Dan_Morgenstern_Cropped_2012.JPG/500px-Dan_Morgenstern_Cropped_2012.JPG', 'Infrogmation (talk), same person as Infrogmation of New Orleans', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Dan_Morgenstern_Cropped_2012.JPG', '{"Intro":"Dan Michael Morgenstern (October 24, 1929 – September 7, 2024) was an American jazz historian and archivist. Born to a Jewish family in Germany, Morgenstern fled Nazi-occupied Austria with his mother and in 1947 emigrated to the United States. He first began visiting jazz clubs as a teenager and worked at The New York Times. After serving in the U.S. Army, he attended Brandeis University where he first began writing about jazz music. He went on to become a professional jazz critic and editor. Morgenstern led several jazz magazines and directed the Institute of Jazz Studies at Rutgers University from 1976 to 2012. He earned eight Grammy Awards for his album liner notes and wrote two books on jazz.","Early Life And Career":"Morgenstern was the only child of a Danish-Jewish mother, Ingeborg von Klenau, and Jewish-Ukrainian writer Soma Morgenstern. He was born in Munich on October 24, 1929, and was raised in Vienna. His mother was the daughter of the Danish composer and conductor Paul von Klenau. His father, the son of Hasidic Jews from what is now Ukraine, was a novelist, journalist and playwright. He had a cultured upbringing; the family''s friends included the composer Alban Berg, who gave Morgenstern a recording of Mozart''s Eine Kleine Nachtmusik for his sixth birthday.\nWhen the Nazis came to power, Morgenstern''s father lost his job as Viennese cultural correspondent on a German newspaper and was placed on a Gestapo blacklist. The family fled Austria following the Nazi annexation of the country. Morgenstern''s father escaped to Paris; eight-year-old Daniel and his mother, with Danish nationality, took refuge in Copenhagen, where he saw American jazz pianist Fats Waller in concert. After the German invasion of Denmark, he and his mother were smuggled out of Denmark to Sweden in a fishing boat by the Danish resistance in October 1943. Morgenstern spent the war years in a boarding school in Stockholm. He fell in love with jazz after hearing Fats Waller and Django Reinhardt play a concert in Copenhagen.\nMorgenstern arrived in the United States in 1947 and was reunited with his father in New York City. He worked at The New York Times as a copy boy. He was enthralled with New York City''s jazz scene and began sneaking into jazz clubs as a 17-year old. During the Korean War, he was drafted into the U.S. Army and was stationed in Munich. After his army service, he took advantage of the G.I. Bill and studied history at Brandeis University in Boston. While there, he wrote about jazz for the university newspaper and organized concerts on campus for jazz musicians such as pianist Art Tatum and saxophonist Stan Getz.\nMorgenstern wrote thousands of articles for magazines, newspapers and journals. He reviewed records for the Chicago Sun-Times. He returned to New York City by the late 1950s. After graduating from Brandeis, he became a jazz critic at the New York Post. He wrote for the British Jazz Journal from 1958 to 1961, then edited several jazz magazines: Metronome in 1961, Jazz from 1962 to 1963, and DownBeat from 1964 to 1973, where he began as New York editor and became chief editor. In 1976 he was made director of the Institute of Jazz Studies at Rutgers University in Newark, New Jersey, where he continued the work of Marshall Stearns and made the Institute the world''s largest repository of jazz documents, recordings, and memorabilia. The institute''s collection \"grew fivefold\" under his management. When he retired in 2012 he was acknowledged as one of the foremost authorities on jazz.\nOver the course of his career, Morgenstern arranged concerts and produced and hosted television and radio programs. He taught courses on jazz history at Brooklyn College, New York University, and the Peabody Institute of Johns Hopkins University. He was a prolific writer of comprehensive and authoritative liner notes, a sideline that won him eight Grammy Awards for Best Album Notes from 1973 on. Morgenstern was the author of two books: Jazz People (1976); and Living with Jazz (2004), a reader edited by Sheldon Meyer (1926–2006). Both won ASCAP''s Deems Taylor Award. In 2007, Morgenstern received the A.B. Spellman Jazz Masters Award for Jazz Advocacy from the National Endowment for the Arts.","Personal Life And Death":"Morgenstern married twice. He divorced his first wife, Lenore Avin. He married again in 1974 to Elsa \"Ellie\" Schochet, with whom he remained until his death; the couple had two sons, Adam and Joshua.\nMorgenstern died from heart failure in Manhattan, on September 7, 2024, at the age of 94."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (337, '1WmIo9ORq1IDlovUWFmo4Y', 'Skitch', 'Henderson', '37a31cb5-4b83-48f1-8f14-4574741526d4', 916044, 3, 'https://en.wikipedia.org/wiki/Skitch_Henderson', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Skitch_Henderson_1965.JPG/500px-Skitch_Henderson_1965.JPG', 'NBC Television', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Skitch_Henderson_1965.JPG', '{"Intro":"Lyle Russel \"Skitch\" Henderson (January 27, 1918 – November 1, 2005) was an American pianist, conductor, and composer. His nickname \"Skitch\" came from his ability to \"re-sketch\" a song in a different key. Bing Crosby suggested that he should use the name professionally.","Early Years":"As his career developed, Henderson often claimed to have been born in Birmingham, England, also adding \"Cedric\" to his name. However, he was born in the town of Halstad in northwest Minnesota in 1918, to Joseph and Josephine (Scheie) Henderson, both of Norwegian descent. After his mother died when he was two in 1920, he was raised in Halstad by his aunt Hattie Henderson Gift and uncle Frank Gift. His aunt taught him piano, starting at the age of four. Although he did not receive formal conservatory education in music, Henderson received classical training under Fritz Reiner, Albert Coates, Arnold Schoenberg, Ernst Toch and Arturo Toscanini, who invited him to conduct the NBC Symphony Orchestra. Henderson would later recount apprenticeships in pop music while playing in taverns with notable singers of the era.","Conducting Career":"In 1983, Henderson founded The New York Pops orchestra, which makes its home at Carnegie Hall in New York City. He served as the music director and conductor of the orchestra until his death in 2005. Henderson also conducted numerous symphonic orchestras throughout the world.\nCalifornia Melodies debuted 1940, Mutual Broadcasting, KHJ (AM)\nPhilco Radio Time starring Bing Crosby 1946, ABC","Personal Life":"Henderson married movie actress and television personality Faye Emerson in 1950. They were divorced seven years later.\nIn 1958, he then married Ruth Einsiedel and raised two children, Hans and Heidi. Hans was married to Sandra Watson for 18 years, before divorcing in 2000. Heidi was married to actor William Hurt from 1989 to 1992, and they have two sons.\nFrom 1972 until his death, Ruth and Skitch Henderson owned and operated The Silo, a store, art gallery, and cooking school in New Milford, Connecticut. In 2003, Ruth and Skitch Henderson co-founded the Hunt Hill Farm Trust, an effort to preserve their farm''s land and buildings and to celebrate Americana in music, art and literature through the creation of a living museum.\nHenderson died of natural causes on November 1, 2005, at age 87."}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (338, '1WmIo9ORq1IDlovUWFmo4Y', 'Frank', 'Sinatra', '197450cd-0124-4164-b723-3c22dd16494d', 52833, 5, 'https://en.wikipedia.org/wiki/Frank_Sinatra', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Frank_Sinatra_%281957_studio_portrait_close-up%29.jpg/500px-Frank_Sinatra_%281957_studio_portrait_close-up%29.jpg', 'Photograph by Capitol Records, per a credit found in the 1959 edition of the International Celebrity Register at page 696. No known source credits an individual photographer.', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Frank_Sinatra_(1957_studio_portrait_close-up).jpg', '{"Intro":"Francis Albert Sinatra (; December 12, 1915 – May 14, 1998) was an American singer and actor. Nicknamed the \"Chairman of the Board\" and \"Ol'' Blue Eyes\", he is regarded as one of the most popular entertainers of the 20th century.\nBorn to Italian immigrants in Hoboken, New Jersey, Sinatra began his musical career in the swing era. He joined the Harry James band as the vocalist in 1939 before signing with Columbia Records four years later and becoming the idol of the \"bobby soxers\". In 1946, Sinatra released his debut album, The Voice of Frank Sinatra. He then signed with Capitol Records and released several albums with arrangements by Nelson Riddle, notably In the Wee Small Hours (1955) and Songs for Swingin'' Lovers! (1956). In 1960, Sinatra left Capitol Records to start his own record label, Reprise Records, releasing a string of successful albums. He collaborated with Count Basie on Sinatra-Basie: An Historic Musical First (1962) and It Might as Well Be Swing (1964). In 1965, he recorded September of My Years and starred in the Emmy-winning television special Frank Sinatra: A Man and His Music. After releasing Sinatra at the Sands the following year, Sinatra recorded one of his most famous collaborations with Tom Jobim, Francis Albert Sinatra & Antonio Carlos Jobim. It was followed by 1968''s Francis A. & Edward K. with Duke Ellington. Sinatra retired in 1971 following the release of \"My Way\" but came out of retirement two years later. He recorded several albums and released \"New York, New York\" in 1980. Sinatra is among the world''s best-selling music artists, with an estimated 150 million record sales globally.\nSinatra also forged a highly successful acting career. After winning the Academy Award for Best Supporting Actor for From Here to Eternity (1953), he starred in The Man with the Golden Arm (1955) and The Manchurian Candidate (1962). Sinatra also appeared in musicals such as On the Town (1949); Guys and Dolls (1955); High Society (1956); and Pal Joey (1957), the last of which won him a Golden Globe Award. Toward the end of his career, Sinatra frequently played detectives, including the title character in Tony Rome (1967) and the titular The Detective (1968). He received the Golden Globe Cecil B. DeMille Award in 1971. Sinatra also directed the anti-war drama None but the Brave (1965). On television, The Frank Sinatra Show began on CBS in 1950, and Sinatra continued to make appearances on television throughout the 1950s and 1960s.\nSinatra was recognized at the Kennedy Center Honors in 1983, awarded the Presidential Medal of Freedom in 1985, and received the Congressional Gold Medal in 1997. He earned 11 Grammy Awards, including the Grammy Trustees Award, Grammy Legend Award, and the Grammy Lifetime Achievement Award. American music critic Robert Christgau called Sinatra \"the greatest singer of the 20th century\" and he continues to be regarded as an iconic figure.","Early Life":"Main article: Early life of Frank Sinatra\n\"They''d fought through his childhood and continued to do so until her dying day. But I believe that to counter her steel will he''d developed his own. To prove her wrong when she belittled his choice of career ... Their friction first had shaped him; that, I think, had remained to the end and a litmus test of the grit in his bones. It helped keep him at the top of his game.\"\n—Sinatra''s daughter Nancy on the importance of his mother Dolly in his life and character.\nFrancis Albert Sinatra was born on December 12, 1915, in a tenement at 415 Monroe Street in Hoboken, New Jersey, the only child of Italian immigrants Natalina \"Dolly\" Garaventa and Antonino Martino \"Marty\" Sinatra. Sinatra weighed 13.5 pounds (6.1 kg) at birth and had to be delivered with the aid of forceps, which caused severe scarring to his left cheek, neck, and lifelong damage to his left eardrum, delaying his baptism to April 2, 1916. A childhood operation left major scarring on his neck, and during adolescence, Sinatra was further scarred by cystic acne. His excessively skinny frame as a child and young man later became the subject of jokes during stage shows. He was raised in the Catholic Church.\nSinatra''s mother, Dolly, was energetic and driven; biographers believe that she was the dominant factor in the development of her son''s personality and self-confidence. Sinatra''s fourth wife, Barbara, would later claim that Dolly \"knocked him around a lot\" when he was a child. Dolly became influential in Hoboken and in local Democratic Party circles.  During the Great Depression, Dolly provided money to her son for outings with friends and to buy expensive clothes, resulting in neighbors describing him as the \"best-dressed kid in the neighborhood\".\nSinatra''s illiterate father, Marty, was a bantamweight boxer who later worked at the Hoboken Fire Department, working his way up to captain. Due to his illiteracy, Marty stressed the importance of a \"complete and full\" education and had instilled in his son the desire to become a civil engineer and enroll at Stevens Institute of Technology in Hoboken. Sinatra spent much time at his parents'' tavern in Hoboken, working on his homework and occasionally singing for spare change.\nAt a young age, Sinatra developed an interest in music, particularly big band jazz and listened to Gene Austin, Rudy Vallée, Russ Colombo, and Bob Eberly while idolizing Bing Crosby. For his 15th birthday, Sinatra received a ukulele from his uncle Domenico, with which he performed at family gatherings. Sinatra attended David E. Rue Jr. High School from 1928, and A. J. Demarest High School (since renamed Hoboken High School) in 1931, where he arranged bands for school dances, but left without graduating after having attended only 47 days before being expelled for \"general rowdiness\".\nTo please his mother, Sinatra enrolled at Drake Business School, but departed after 11 months. Dolly found him working as a delivery boy at the Jersey Observer newspaper (since merged into The Jersey Journal), where his godfather Frank Garrick worked; Sinatra later worked as a riveter at the Tietjen and Lang shipyard. He began performing in local Hoboken social clubs and sang for free on radio stations such as WAAT in Jersey City.","Music Career":"Sinatra (far right) with the Hoboken Four on Major Bowes'' Amateur Hour in 1935\nSinatra began singing professionally as a teenager. He never learned to read music but learned by ear. Sinatra got his first break in 1935 when his mother persuaded a local singing group called the 3 Flashes, who were auditioning for the Major Bowes Amateur Hour show, to let him join. Baritone Fred Tamburro stated, \"Frank hung around us like we were gods or something\", admitting that they only took him on board because he owned a car and could chauffeur the group.\nThe group became the \"Hoboken Four\" and passed an audition from Major Bowes to appear on the show. They each earned $12.50, and attracted 40,000 votes to win first prize—a six-month contract to perform on stage and radio across the U.S. Sinatra quickly became the group''s lead singer, and, much to the jealousy of his fellow group members, garnered most of the attention from the girls. Due to the success of the group, Bowes kept asking for them to return, disguised under different names, varying from \"The Secaucus Cockamamies\" to \"The Bayonne Bacalas,\" although this may be apocryphal, sourced from Sinatra''s humorous stage patter during his appearance with the Count Basie orchestra at the Sands (1966).\nIn March 1939, saxophone player Frank Mane, who knew Sinatra from Jersey City radio station WAAT, arranged for him to audition and record \"Our Love\", his first solo studio recording. In June, bandleader Harry James, who had heard Sinatra sing on \"Dance Parade\", signed him to a two-year contract of $75 a week after a show at the Paramount Theatre in New York. It was with the James band that Sinatra released his first commercial record \"From the Bottom of My Heart\" in July. No more than 8,000 copies were sold, and further records released with James through 1939, such as \"All or Nothing at All\", also had weak sales on their initial release. Thanks to his vocal training, Sinatra could now sing two tones higher, and developed a repertoire that included songs such as \"My Buddy\", \"Willow Weep for Me\", \"It''s Funny to Everyone but Me\", \"Here Comes the Night\", \"On a Little Street in Singapore\", \"Ciribiribin\", and \"Every Day of My Life\".\nSinatra became increasingly frustrated with the Harry James band, feeling that he was not achieving the major success and acclaim he was looking for. Sinatra''s pianist and close friend Hank Sanicola persuaded him to stay with the group, but Sinatra left James in November 1939 to replace Jack Leonard as the lead singer of the Tommy Dorsey band. Sinatra earned $125 a week, appearing at the Palmer House in Chicago, and James released Sinatra from his contract.\nSinatra and Tommy Dorsey in Ship Ahoy (1942)\nOn January 26, 1940, Sinatra made his first public appearance with the band at the Coronado Theatre in Rockford, Illinois, opening the show with \"Stardust\". Dorsey recalled: \"You could almost feel the excitement coming up out of the crowds when the kid stood up to sing. Remember, he was no matinée idol. He was just a skinny kid with big ears. I used to stand there so amazed I''d almost forget to take my own solos\".\nDorsey was a major influence on Sinatra and became a father figure. Sinatra copied Dorsey''s mannerisms and traits, becoming a demanding perfectionist like him, even adopting his hobby of toy trains. Sinatra asked Dorsey to be godfather to his daughter Nancy in June 1940. Sinatra later said that \"The only two people I''ve ever been afraid of are my mother and Tommy Dorsey.\" Although Kelley says that Sinatra and drummer Buddy Rich were bitter rivals, other authors state that they were friends and even roommates when the band was on the road, but professional jealousy surfaced as both men wanted to be considered the star of Dorsey''s band. Later, Sinatra helped Rich form his own band with a $25,000 loan and provided financial help to Rich during times of the drummer''s serious illness.\nIn his first year with Tommy Dorsey, Sinatra recorded more than 40 songs. His first vocal hit was the song \"Polka Dots and Moonbeams\" in late April 1940. Two more chart appearances followed with \"Say It\" and \"Imagination\", which was Sinatra''s first top-10 hit. His fourth chart appearance (and his first on the first officially published Billboard chart) was \"I''ll Never Smile Again\", topping the charts for twelve weeks beginning in mid-July. Other records with Dorsey issued by RCA Victor include \"Our Love Affair\" and \"Stardust\" in 1940; \"Oh! Look at Me Now\", \"Dolores\", \"Everything Happens to Me\", and \"This Love of Mine\" in 1941; \"Just as Though You Were There\", \"Take Me\", and \"There Are Such Things\" in 1942; and \"It Started All Over Again\", \"In the Blue of Evening\", and \"It''s Always You\" in 1943.\nSinatra performing with Harry James at the Hollywood Canteen in 1943\nAs his success and popularity grew, Sinatra pushed Dorsey to allow him to record some solo songs. Dorsey eventually relented, and on January 19, 1942, Sinatra recorded \"Night and Day\", \"The Night We Called It a Day\", \"The Song is You\", and \"Lamplighter''s Serenade\" at a Bluebird recording session, with Axel Stordahl as arranger and conductor. Sinatra first heard the recordings at the Hollywood Palladium and Hollywood Plaza and was astounded at how good he sounded. Stordahl recalled: \"He just couldn''t believe his ears. He was so excited you almost believed he had never recorded before. I think this was a turning point in his career. I think he began to see what he might do on his own\".\nAfter the 1942 recordings, Sinatra believed that he needed to go solo, with an insatiable desire to compete with Bing Crosby, but Sinatra was hampered by his contract which gave Dorsey 43% of Sinatra''s lifetime earnings. A legal battle ensued, eventually settled in August 1942. On September 3, 1942, Dorsey bade farewell to Sinatra, reportedly saying, \"I hope you fall on your ass\", but he was more gracious on the air when replacing Sinatra with singer Dick Haymes.\nRumors began spreading in newspapers that Sinatra''s mobster godfather, Willie Moretti, coerced Dorsey at gunpoint to let Sinatra out of his contract for a few thousand dollars. Sinatra persuaded Stordahl to come with him and become his personal arranger, offering him $650 a month, five times his salary from Dorsey. Dorsey and Sinatra, who had been very close, never reconciled their differences.\n1942–1945: Onset of Sinatramania and role in World War II\nBy May 1941, Sinatra topped the male singer polls in Billboard and DownBeat magazines. His appeal to bobby soxers, a subculture of teenage girls, revealed a new audience for popular music, which had previously been recorded mainly for adults. The phenomenon became known as \"Sinatramania\" after his opening at the Paramount Theatre in New York on December 30, 1942.\nAccording to Nancy Sinatra, Jack Benny later said, \"I thought the goddamned building was going to cave in. I never heard such a commotion ... All this for a fellow I never heard of.\" Sinatra performed for four weeks at the theatre, his act following the Benny Goodman orchestra, after which his contract was renewed for another four weeks by Bob Weitman due to his popularity. Sinatra became known as \"Swoonatra\" or \"The Voice\", and his fans \"Sinatratics\". They organized meetings and sent masses of letters of adoration, and within a few weeks of the show, some 1,000 Sinatra fan clubs had been reported across the US.\nSinatra''s publicist, George Evans, encouraged interviews and photographs with fans and was the man responsible for depicting Sinatra as a vulnerable, shy, Italian–American with a rough childhood who made good. When Sinatra returned to the Paramount in October 1944, only 250 persons left the first show, and 35,000 fans left outside caused a near riot, known as the Columbus Day Riot, outside the venue because they were not allowed in. Such was the bobby-soxer devotion to Sinatra that they were known to write his song titles on their clothing, bribe hotel maids for an opportunity to touch his bed, and steal clothing Sinatra was wearing.\nSinatra signed with Columbia Records as a solo artist on June 1, 1943, during the 1942–44 musicians'' strike. Columbia Records re-released Harry James and Sinatra''s August 1939 version of \"All or Nothing at All\", which reached number 2 on June 2 and was on the best-selling list for 18 weeks. Sinatra initially had great success, and performed on the radio on Your Hit Parade from February 1943 until December 1944, and on stage.\nSinatra (left) on the Armed Forces Radio in 1944 with Dinah Shore and Bing Crosby (right)\nColumbia wanted new recordings of their growing star as quickly as possible, so Alec Wilder was hired as an arranger and conductor for several sessions with a vocal group called the Bobby Tucker Singers. Of the nine songs recorded during these sessions, seven charted on the best-selling list. That year he made his first solo nightclub appearance at New York''s Riobamba, and a successful concert in the Wedgewood Room of the prestigious Waldorf-Astoria New York that year secured his popularity in New York high society. Sinatra released \"You''ll Never Know\", \"Close to You\", \"Sunday, Monday, or Always\" and \"People Will Say We''re in Love\" as singles. By the end of 1943, he was more popular in a DownBeat poll than Bing Crosby.\nSinatra did not serve in the military during World War II. On December 11, 1943, he was officially classified 4-F (\"Registrant not acceptable for military service\") by his draft board because of his perforated left eardrum. However, Army files reported that Sinatra had actually been rejected because he was \"not acceptable material from a psychiatric viewpoint;\" Sinatra''s emotional instability was hidden to avoid \"undue unpleasantness for both the selectee and the induction service\". Rumors reported by columnist Walter Winchell stated that Sinatra paid $40,000 to avoid military service, but the FBI found this to be without merit.\nYoung Sinatra fans listening to his records on a portable gramophone in Sydney, Australia, 1945.\nToward the end of the war, Sinatra entertained the troops during several successful overseas USO tours with comedian Phil Silvers. During one trip to Rome, he met Pope Pius XII, who asked Sinatra if he was an operatic tenor. Sinatra worked frequently with the popular Andrews Sisters in radio in the 1940s, and many USO shows were broadcast to troops via the Armed Forces Radio Service (AFRS). In 1944, he released \"I Couldn''t Sleep a Wink Last Night\" as a single and recorded his own version of Irving Berlin''s \"White Christmas\". The following year, Sinatra released \"I Dream of You (More Than You Dream I Do)\", \"Saturday Night (Is the Loneliest Night of the Week)\", \"Dream\", and \"Nancy (with the Laughing Face)\" as singles.\n1946–1952: Columbia years and career slump\nDespite being heavily involved in political activity in 1945 and 1946, Sinatra sang on 160 radio shows, recorded 36 times, and shot four films in those two years. By 1946, he was performing on stage up to 45 times a week, singing up to 100 songs daily, and earning up to $93,000 a week.\nIn 1946, Sinatra released \"Oh! What it Seemed to Be\", \"Day by Day\", \"They Say It''s Wonderful\", \"Five Minutes More\", and \"The Coffee Song\" as singles, and launched his first album, The Voice of Frank Sinatra, which reached No. 1 on the Billboard chart. William Ruhlmann of AllMusic wrote that Sinatra \"took the material very seriously, singing the love lyrics with utter seriousness\" and that his \"singing and the classically influenced settings gave the songs unusual depth of meaning.\" Sinatra was soon selling 10 million records a year.\nSuch was Sinatra''s command at Columbia that his love of conducting was indulged with the release of the set Frank Sinatra Conducts the Music of Alec Wilder, an offering unlikely to appeal to Sinatra''s core fanbase of teenage girls at the time. In 1947, he released his second album, Songs by Sinatra, featuring songs of a similar mood and tempo such as Irving Berlin''s \"How Deep is the Ocean?\" and Harold Arlen''s and Jerome Kern''s \"All The Things You Are\". \"Mam''selle\", composed by Edmund Goulding with lyrics by Mack Gordon for the film The Razor''s Edge (1946), was released as a single.\nSinatra had competition; versions by Art Lund, Dick Haymes, Dennis Day, and The Pied Pipers also reached the top ten of the Billboard charts. In December, Sinatra recorded \"Sweet Lorraine\" with the Metronome All-Stars, featuring talented jazz musicians such as Coleman Hawkins, Harry Carney and Charlie Shavers, with Nat King Cole on piano, in what Charles L. Granata describes as \"one of the highlights of Sinatra''s Columbia epoch\".\nSinatra''s third album, Christmas Songs by Sinatra, was originally released in 1948 as a 78 rpm album set, and a 10\" LP record was released two years later. When Sinatra was featured as a priest in The Miracle of the Bells, due to press negativity surrounding his Mafia connections at the time, it was announced to the public that Sinatra would donate his $100,000 in wages from the film to the Catholic Church.\nBy the end of 1948, Sinatra had slipped to fourth on DownBeat''s annual poll of most popular singers, and the following year, he was pushed out of the top spots in polls for the first time since 1943. Frankly Sentimental (1949) was panned by DownBeat, who commented that \"for all his talent, it seldom comes to life.\"\nAlthough \"The Hucklebuck\" reached the top ten, it was his last single release under the Columbia label. Sinatra''s last two albums with Columbia, Dedicated to You and Sing and Dance with Frank Sinatra, were released in 1950. He would later feature a number of the Sing and Dance with Frank Sinatra album''s songs, including \"Lover\", \"It''s Only a Paper Moon\", and \"It All Depends on You\", on his 1961 Capitol release, Sinatra''s Swingin'' Session!!!.\nCulminating the low of Sinatra''s career was the death of publicist George Evans in January 1950. According to Jimmy Van Heusen, Sinatra''s close friend and songwriter, Evans'' death to him was \"an enormous shock which defies words\", as he had been crucial to Sinatra''s career and popularity with the \"bobby soxers\".\nSinatra''s reputation continued to decline as reports broke in February of his affair with Ava Gardner and the destruction of his marriage to Nancy, although Sinatra insisted that his marriage had long been over even before meeting Gardner. In April, he was engaged to perform at the Copa club in New York, but had to cancel five days of the booking due to a submucosal hemorrhage of the throat. Evans once said that whenever Sinatra suffered from a bad throat and loss of voice, it was always due to emotional tension, which \"absolutely destroyed him\".\nThe Desert Inn, Las Vegas, where Sinatra began performing in 1951\nIn financial difficulty following his divorce and career decline, Sinatra was forced to borrow $200,000 from Columbia to pay his back taxes after MCA refused to front the money. Rejected by Hollywood, Sinatra turned to Las Vegas and made his debut at the Desert Inn in September 1951, and also began singing at the Riverside Hotel in Reno, Nevada.\nSinatra''s decline in popularity was evident in his concert appearances. At a brief run at the Paramount in New York, Sinatra drew small audiences. At the Desert Inn in Las Vegas, he performed to half-filled houses. At a concert at Chez Paree in Chicago, only 150 people turned up in a 1,200-seat venue. By April 1952, Sinatra was performing at the Kauai County Fair in Hawaii. Sinatra''s relationship with Columbia Records was disintegrating, with A&R executive Mitch Miller claiming he \"couldn''t give away\" Sinatra records. However, several notable recordings were made during this time period, such as \"If I Could Write a Book\" in January 1952, which Granata sees as a \"turning point\", forecasting his later work with its sensitivity,\nColumbia and MCA dropped Sinatra later in 1952. His last studio recording for Columbia, \"Why Try To Change Me Now\", was recorded in New York on September 17, 1952, with an orchestra arranged and conducted by Percy Faith. Journalist Burt Boyar observed, \"Sinatra had had it. It was sad. From the top to the bottom in one horrible lesson.\"\n1953–1960: Career revival and the Capitol years\nNelson Riddle, Sinatra''s album arranger for Capitol Records\nThe release of the film From Here to Eternity in August 1953 marked the beginning of a remarkable career revival. Tom Santopietro notes that Sinatra began to bury himself in his work, with an \"unparalleled frenetic schedule of recordings, movies and concerts\", in what authors Anthony Summers and Robbyn Swan describe as \"a new and brilliant phase\". On March 13, 1953, Sinatra met with Capitol Records vice president Alan Livingston and signed a seven-year recording contract. Sinatra''s first session for Capitol took place at KHJ studios at Studio C, 5515 Melrose Avenue in Los Angeles, with Axel Stordahl conducting. The session produced four recordings, including \"I''m Walking Behind You\", Sinatra''s first Capitol single.\nAfter spending two weeks on location in Hawaii filming From Here to Eternity, Sinatra returned to KHJ on April 30 for his first recording session with Nelson Riddle, an established arranger and conductor at Capitol who was Nat King Cole''s musical director. After recording the first song, \"I''ve Got the World on a String\", Sinatra offered Riddle a rare expression of praise, \"Beautiful!\", and after listening to the playbacks, he could not hide his enthusiasm, exclaiming, \"I''m back, baby, I''m back!\" In subsequent sessions in May and November 1953, Sinatra and Riddle developed and refined their musical collaboration, with Sinatra providing specific guidance on the arrangements. Sinatra''s first album for Capitol, Songs for Young Lovers, was released on January 4, 1954, and it included \"A Foggy Day\", \"I Get a Kick Out of You\", \"My Funny Valentine\", \"Violets for Your Furs\", and \"They Can''t Take That Away from Me\", songs that became staples of his later concerts.\nThat same month, Sinatra released the single \"Young at Heart\", which reached No. 2 and was awarded Song of the Year. In March, he recorded and released the single \"Three Coins in the Fountain\", a \"powerful ballad\" that reached No. 4. Sinatra''s second album with Riddle, Swing Easy!, which reflected his \"love for the jazz idiom\" according to Granata, was released on August 2 and included \"Just One of Those Things\", \"Taking a Chance on Love\", \"Get Happy\", and \"All of Me\". Swing Easy! was named Album of the Year by Billboard, and Sinatra was named \"Favorite Male Vocalist\" by Billboard, DownBeat, and Metronome in 1954. Sinatra came to consider Riddle \"the greatest arranger in the world\", and Riddle, who considered Sinatra, \"a perfectionist\", said: \"It''s not only that his intuitions as to tempo, phrasing, and even configuration are amazingly right, but his taste is so impeccable ... There is still no one who can approach him.\"\nSinatra recording at Capitol Studios, c. 1955\nSinatra became one of Las Vegas''s pioneer residency entertainers, and a prominent figure in the Vegas scene throughout the 1950s and 1960s onwards, a period described by Rojek as the \"high-water mark\" of Sinatra''s \"hedonism and self-absorption\". Rojek notes that the Rat Pack \"provided an outlet for gregarious banter and wisecracks\" but argues that it was Sinatra''s vehicle, possessing an \"unassailable command over the other performers\". Sinatra would fly to Las Vegas from Los Angeles in Van Heusen''s plane. On October 4, 1953, Sinatra made his first performance at the Sands Hotel and Casino, after an invitation by the manager Jack Entratter. Sinatra typically performed there three times a year and later acquired a share in the hotel.\nIn 1955, Sinatra released In the Wee Small Hours, his first 12\" LP, featuring songs such as \"In the Wee Small Hours of the Morning\", \"Mood Indigo\", \"Glad to Be Unhappy\" and \"When Your Lover Has Gone\". According to Granata, it was the first concept album of his to make a \"single persuasive statement\", with an extended program and \"melancholy mood\". Sinatra embarked on his first tour of Australia the same year. Another collaboration with Riddle resulted in Songs for Swingin'' Lovers!, sometimes seen as one of his best albums, which was released in March 1956. It features a recording of \"I''ve Got You Under My Skin\" by Cole Porter, which reportedly took 22 takes to perfect.\nSinatra''s February 1956 recording sessions inaugurated the studios at the Capitol Records Building, complete with a 56-piece symphonic orchestra. According to Granata, his recordings of \"Night and Day\", \"Oh! Look at Me Now\", and \"From This Moment On\" revealed \"powerful sexual overtones, stunningly achieved through the mounting tension and release of Sinatra''s best-teasing vocal lines\", while his recording of \"River, Stay ''Way from My Door\" in April demonstrated his \"brilliance as a syncopational improviser\". Riddle said that Sinatra took \"particular delight\" in singing \"The Lady is a Tramp\", commenting that he \"always sang that song with a certain amount of salaciousness\", making \"cue tricks\" with the lyrics. Sinatra''s penchant for conducting was displayed again in 1956''s Frank Sinatra Conducts Tone Poems of Color, an instrumental album that has been interpreted to be a catharsis to his failed relationship with Gardner. Sinatra also sang at that year''s Democratic National Convention and performed with The Dorsey Brothers for a week soon afterward at the Paramount Theatre.\nSinatra introducing his character to the audience in the 1957 trailer for the film Pal Joey\nIn 1957, Sinatra released Close to You, A Swingin'' Affair!, and Where Are You?—his first album in stereo, with Gordon Jenkins. Granata considers \"Close to You\" to have been thematically his closest concept album to perfection during the \"golden\" era, and Nelson Riddle''s finest work, which was \"extremely progressive\" by the standards of the day. For Granata, Sinatra''s A Swingin'' Affair! and Songs for Swingin'' Lovers! solidified \"Sinatra''s image as a ''swinger'', from both a musical and visual standpoint.\" Buddy Collette considered the swing albums to have been heavily influenced by Sammy Davis Jr. and stated that when he worked with Sinatra in the mid-1960s, he approached a song much differently than he had done in the early 1950s. On June 9, 1957, Sinatra performed in a 62-minute concert conducted by Riddle at the Seattle Civic Auditorium, his first appearance in Seattle since 1945. The recording was first released as a bootleg, but Artanis Entertainment Group officially released it as Sinatra ''57 in Concert in 1999, after Sinatra''s death.\nIn 1958, Sinatra released the concept album Come Fly with Me with Billy May, designed as a musical world tour. It reached the top spot on the Billboard album chart in its second week, remaining at the top for five weeks, and was nominated for the Grammy Award for Album of the Year at the inaugural Grammy Awards. The title song, \"Come Fly With Me\", written especially for him, would become one of Sinatra''s best-known standards. On May 29, he recorded seven songs in a single session, more than double the usual yield of a recording session, and an eighth, \"Lush Life\", was abandoned as Sinatra found it too technically demanding. In September, Sinatra released Frank Sinatra Sings for Only the Lonely, a stark collection of introspective saloon songs and blues-tinged ballads, which proved a huge commercial success, spending 120 weeks on Billboard''s album chart and peaking at No. 1. Cuts from this LP, such as \"Angel Eyes\" and \"One for My Baby (and One More for the Road)\", would remain staples of the \"saloon song\" segments of Sinatra''s concerts.\nIn 1959, Sinatra released Come Dance with Me!, a highly successful, critically acclaimed album that stayed on Billboard''s Pop album chart for 140 weeks, peaking at No. 2. It won the Grammy Award for Album of the Year, as well as Best Vocal Performance, Male and Best Arrangement for Billy May. Sinatra released No One Cares in the same year, a collection of \"brooding, lonely\" torch songs, which critic Stephen Thomas Erlewine thought was \"nearly as good as its predecessor Where Are You?, but lacked the \"lush\" arrangements of it and the \"grandiose melancholy\" of Only the Lonely.\nIn May 1959, Sinatra wrote an article entitled \"You Can''t Hate and be Happy\" for a publication called \"What the Stars Say\" published by the Stars Campaign for Inter-Racial Friendship after the murder, in London, of Kelso Cochrane. In the words of Kelley, by 1959, Sinatra was \"not simply the leader of the Rat Pack\" but had \"assumed the position of il padrone in Hollywood.\" He was asked by 20th Century Fox to be the master of ceremonies at a luncheon attended by Soviet Premier Nikita Khrushchev on September 19, 1959. Nice ''n'' Easy, a collection of ballads, topped the Billboard chart in October 1960 and remained in the charts for 86 weeks, winning critical plaudits.\nSinatra grew discontented at Capitol and feuded with Alan Livingston, which lasted over six months. Sinatra''s first attempt at owning his own label was with his pursuit of buying declining jazz label Verve Records, which ended once an initial agreement with Verve founder Norman Granz \"failed to materialize\".\nSinatra decided to form his own label, Reprise Records, and, in an effort to assert his new direction, temporarily parted with Riddle, May and Jenkins, working with other arrangers such as Neil Hefti, Don Costa, and Quincy Jones. Sinatra built the appeal of Reprise Records as one in which artists were promised creative control, as well as a guarantee that they would eventually gain \"complete ownership of their work, including publishing rights.\"\nUnder Sinatra the company developed into a music industry \"powerhouse\", and he later sold it for an estimated $80 million. Sinatra''s first album on the label, Ring-a-Ding-Ding! (1961), was a major success, peaking at No.4 on Billboard. The album was released in February 1961, the same month that Reprise Records released Ben Webster''s The Warm Moods, Sammy Davis Jr.''s The Wham of Sam, Mavis River''s Mavis and Joe E. Lewis''s It is Now Post Time. During the initial years of Reprise, Sinatra was still under contract to record for Capitol, completing his contractual commitment with the release of Point of No Return, recorded on September 11 and 12, 1961.\nSinatra with Dean Martin and Judy Garland in 1962\nIn 1962, Sinatra released Sinatra and Strings, a set of standard ballads arranged by Don Costa, which became one of the most critically acclaimed works of Sinatra''s Reprise period. Frank Jr., who was present during the recording, noted the \"huge orchestra\", which Nancy Sinatra stated \"opened a whole new era\" in pop music, with orchestras getting bigger, embracing a \"lush string sound\".\nSinatra and Count Basie collaborated for the album Sinatra-Basie the same year, a popular and successful release, which prompted them to rejoin two years later for the follow-up It Might as Well Be Swing, arranged by Quincy Jones. The two became frequent performers together, and appeared at the Newport Jazz Festival in 1965. Also in 1962, as the owner of his own record label, Sinatra was able to step on the podium as conductor again, releasing his third instrumental album Frank Sinatra Conducts Music from Pictures and Plays.\nIn 1963, Sinatra reunited with Nelson Riddle for The Concert Sinatra, an ambitious album featuring a 73-piece symphony orchestra arranged and conducted by Riddle. The concert was recorded on a motion picture scoring soundstage with the use of multiple synchronized recording machines that employed an optical signal onto 35 mm film designed for movie soundtracks. Granata considers the album to have been \"impeachable\" , \"one of the very best of the Sinatra-Riddle ballad albums\", where Sinatra displayed his vocal range, particularly in \"Ol'' Man River\", in which Sinatra darkened the hue.\nIn 1964, the song \"My Kind of Town\" was nominated for the Academy Award for Best Original Song. Sinatra released Softly, as I Leave You, and collaborated with Bing Crosby and Fred Waring on America, I Hear You Singing, a collection of patriotic songs recorded as a tribute to the assassinated President John F. Kennedy. Sinatra increasingly became involved in charitable pursuits in this period. In 1961 and 1962, he went to Mexico to put on performances for Mexican charities, and in July 1964, Sinatra was present at the dedication of the Frank Sinatra International Youth Center for Arab and Jewish children in Nazareth.\nThe Rat Pack concert, called The Frank Sinatra Spectacular, was broadcast live via satellite to numerous movie theaters across America. The album September of My Years was released September 1965, and went on to win the Grammy Award for best album of the year. Granata considers the album to have been one of the finest of his Reprise years, \"a reflective throwback to the concept records of the 1950s, and more than any of those collections, distills everything that Frank Sinatra had ever learned or experienced as a vocalist\". One of the album''s singles, \"It Was a Very Good Year\", won the Grammy Award for Best Vocal Performance, Male. A career anthology, A Man and His Music, followed in November, winning Album of the Year at the Grammys the following year.\nIn 1966, Sinatra released That''s Life, with both the single of \"That''s Life\" and album becoming Top Ten hits on Billboard''s pop charts. Strangers in the Night went on to top the Billboard and UK pop singles charts, winning the award for Record of the Year at the Grammys. Sinatra''s first live album, Sinatra at the Sands, was recorded during January and February 1966 at the Sands Hotel and Casino in Las Vegas. He was backed by the Count Basie Orchestra, with Quincy Jones conducting. Sinatra pulled out from the Sands the following year when he was driven out by its new owner Howard Hughes after a fight.\nSinatra with Jill St. John in Tony Rome (1967)\nSinatra started 1967 with a series of recording sessions with Antônio Carlos Jobim. He recorded one of his collaborations with Jobim, the Grammy-nominated album Francis Albert Sinatra & Antônio Carlos Jobim, which was one of the best-selling albums of the year, behind the Beatles''s Sgt. Pepper''s Lonely Hearts Club Band. According to Santopietro, the album \"consists of an extraordinarily effective blend of bossa nova and slightly swinging jazz vocals, and succeeds in creating an unbroken mood of romance and regret.\" Writer Stan Cornyn wrote that Sinatra sang so softly on the album that it was comparable to the time that he suffered from a vocal hemorrhage in 1950.\nSinatra released the album The World We Knew, which features a chart-topping duet of \"Somethin'' Stupid\" with daughter Nancy. In December, Sinatra collaborated with Duke Ellington on the album Francis A. & Edward K.. According to Granata, the recording of \"Indian Summer\" on the album was a favorite of Riddle''s, noting the \"contemplative mood  is heightened by a Johnny Hodges alto sax solo that will bring a tear to your eye\".\nWith Sinatra in mind, singer-songwriter Paul Anka wrote the song \"My Way\", using the melody of the French \"Comme d''habitude\" (\"As Usual\"), composed by Claude François and Jacques Revaux. Sinatra recorded it in one take, just after Christmas 1968. \"My Way\", Sinatra''s best-known song on the Reprise label, was not an instant success, charting at No. 27 in the US and No. 5 in the UK. However, it remained in the UK charts for 122 weeks, including 75 non-consecutive weeks in the Top 40, between April 1969 and September 1971, which was still a record in 2015. Sinatra told songwriter Ervin Drake in the 1970s that he \"detested\" singing the song because he believed audiences would think it was a \"self-aggrandizing tribute\". According to NPR, \"My Way\" has become one of the most requested songs at funerals.\nIn an effort to maintain his commercial viability in the late 1960s, Sinatra would record works by Paul Simon (\"Mrs. Robinson\"), the Beatles (\"Yesterday\"), and Joni Mitchell (\"Both Sides, Now\") in 1969.\nCaesars Palace in 1970, where Sinatra performed from 1967 to 1970 and 1973 onwards\nIn 1970, Sinatra released Watertown, a critically acclaimed concept album, with music by Bob Gaudio (of the Four Seasons) and lyrics by Jake Holmes. However, it sold a mere 30,000 copies that year and reached a peak chart position of 101.\nSinatra left Caesars Palace in September of that year after an incident in which executive Sanford Waterman pulled a gun on him. Sinatra performed several charity concerts with Count Basie at the Royal Festival Hall in London. On November 2, 1970, Sinatra recorded the last songs for Reprise Records before his self-imposed retirement, announced the following June at a concert in Hollywood to raise money for the Motion Picture and TV Relief Fund. He gave a \"rousing\" performance of \"That''s Life\", and finished the concert with a Matt Dennis and Earl Brent song, \"Angel Eyes\", which Sinatra had recorded on the Only the Lonely album in 1958. He sang the last line. \"''Scuse me while I disappear.\" The spotlight went dark, and he left the stage.\nSinatra told LIFE journalist Thomas Thompson, \"I''ve got things to do, like the first thing is not to do anything at all for eight months ... maybe a year\", while Barbara Sinatra later said that Sinatra had grown \"tired of entertaining people, especially when all they really wanted were the same old tunes he had long ago become bored by\". Around this time, Sinatra designed Villa Maggio, a holiday home and retreat near Palm Desert. While he was in retirement, President Richard Nixon asked Sinatra to perform at a Young Voters Rally in anticipation of the upcoming campaign. He obliged and chose to sing \"My Kind of Town\" for the rally held in Chicago on October 20, 1972.\nSinatra (center) with President Richard Nixon and Italian Prime Minister Giulio Andreotti in 1973\nIn 1973, Sinatra came out of his short-lived retirement with a television special and album. The album, entitled Ol'' Blue Eyes Is Back, arranged by Gordon Jenkins and Don Costa, was a success, reaching number 13 on Billboard and number 12 in the UK. The television special, Magnavox Presents Frank Sinatra, reunited Sinatra with Gene Kelly.\nSinatra initially developed problems with his vocal cords during the comeback due to a prolonged period without singing. That Christmas, Sinatra performed at the Sahara Hotel in Las Vegas, and returned to Caesars Palace the following month in January 1974. He began what Barbara Sinatra describes as a \"massive comeback tour of the United States, Europe, the Far East, and Australia.\" In July, while on a second tour of Australia, Sinatra caused an uproar by describing journalists there – who were aggressively pursuing his every move and pushing for a press conference – as \"bums, parasites, fags, broads and buck-and-a-half hookers.\" After he was pressured to apologize, Sinatra instead insisted that the journalists apologize for \"fifteen years of abuse I have taken from the world press.\" Union actions canceled concerts and grounded Sinatra''s plane, essentially trapping him in Australia.\nSinatra''s lawyer, Mickey Rudin, arranged for Sinatra to issue a written conciliatory note and a final concert that was televised to the nation. In October 1974, he appeared at New York City''s Madison Square Garden in a televised concert that was later released as an album under the title The Main Event – Live. Backing Sinatra was bandleader Woody Herman and the Young Thundering Herd, who accompanied Sinatra on a European tour later that month.\nIn 1975, Sinatra performed in concerts in New York with Count Basie and Ella Fitzgerald, and at the London Palladium with Basie and Sarah Vaughan, and in Tehran at Aryamehr Stadium, giving 140 performances in 105 days. In August, Sinatra held several concerts at Lake Tahoe together with the newly risen singer John Denver, who became a frequent collaborator. Sinatra had recorded Denver''s \"Leaving on a Jet Plane\" and \"My Sweet Lady\" for Sinatra & Company (1971), and according to Denver, his song \"A Baby Just Like You\", was written at Sinatra''s request for his new grandchild, Angela.\nDuring Labor Day weekend in 1976, Sinatra was responsible for reuniting old friends and comedy partners Dean Martin and Jerry Lewis for the first time in nearly 20 years, when they performed at the \"Jerry Lewis MDA Telethon\". That year, the Friars Club selected Sinatra as the \"Top Box Office Name of the Century\", and he was given the Scopus Award by the American Friends of the Hebrew University of Jerusalem in Israel and an honorary Doctor of Humane Letters from the University of Nevada.\nSinatra continued to perform at Caesars Palace in the late 1970s and was performing there in January 1977 when his mother Dolly died in a plane crash on her way to see him. Sinatra canceled two weeks of shows and spent time recovering from the shock in Barbados. In March, he performed in front of Princess Margaret at the Royal Albert Hall in London, raising money for the National Society for the Prevention of Cruelty to Children. On March 14, Sinatra recorded with Nelson Riddle for the last time, recording the songs \"Linda\", \"Sweet Lorraine\", and \"Barbara\". The two men had a major falling out and later patched up their differences in January 1985 at a dinner organized for Ronald Reagan when Sinatra asked Riddle to make another album with him. Riddle was ill at the time and died that October before they had a chance to record.\nIn 1978, Sinatra filed a $1 million lawsuit against a land developer for using his name in the \"Frank Sinatra Drive Center\" in West Los Angeles. During a party at Caesars in 1979, Sinatra was awarded the Grammy Trustees Award, while celebrating 40 years in show business and his 64th birthday. That same year, former President Gerald Ford awarded Sinatra the International Man of the Year Award, and he performed in front of the Egyptian pyramids for Anwar Sadat, which raised more than $500,000 for Sadat''s wife''s charities.\nIn 1980, Sinatra''s first album in six years was released, Trilogy: Past Present Future, a highly ambitious triple album that features an array of songs from both the pre-rock and rock eras. It was the first studio album of Sinatra''s to feature his touring pianist at the time, Vinnie Falcone, and was based on an idea by Sonny Burke. The album garnered six Grammy nominations – winning for best liner notes – and peaked at number 17 on Billboard''s album chart, and spawned yet another song that would become a signature tune, \"Theme from New York, New York\". That year, as part of the Concert of the Americas, he performed in the Maracanã Stadium in Rio de Janeiro, Brazil, which broke records for the \"largest live paid audience ever recorded for a solo performer\".\nIn 1981, Sinatra built on the success of Trilogy with She Shot Me Down, an album that was praised for embodying the dark tone of his Capitol years. That same year, Sinatra was embroiled in controversy when he worked a 10-day engagement for $2 million in Sun City, in the internationally unrecognized Bophuthatswana, breaking a cultural boycott against apartheid-era South Africa. President Lucas Mangope awarded Sinatra with the highest honor, the Order of the Leopard, and made him an honorary tribal chief.\n1982–1997: Later career and final projects\nSinatra signed a $16 million three-year deal with the Golden Nugget Las Vegas in 1982.\nHandprint of Sinatra. Atlantic City Boardwalk, New Jersey, US, 2006\nSantopietro stated that by the early 1980s, Sinatra''s voice had \"coarsened, losing much of its power and flexibility, but audiences didn''t care.\" Kelley noted that by this period, Sinatra''s voice had grown \"darker, tougher and loamier\", but he \"continued to captivate audiences with his immutable magic.\" She added that Sinatra''s baritone voice \"sometimes cracked, but the gliding intonations still aroused the same raptures of delight as they had at the Paramount Theater.\"\nAlso in 1982, Sinatra made a reported further $1.3 million from the Showtime television rights to his \"Concert of the Americas\" in the Dominican Republic, $1.6 million for a concert series at Carnegie Hall, and $250,000 in just one evening at the Chicago Fest. Sinatra donated a lot of his earnings to charity. He put on a performance at the White House for Italian president Sandro Pertini, and performed at the Radio City Music Hall with Luciano Pavarotti and George Shearing.\nSinatra was honored at the 1983 Kennedy Center Honors, alongside Katherine Dunham, James Stewart, Elia Kazan, and Virgil Thomson. Quoting Henry James, President Reagan said in honoring his old friend that \"art was the shadow of humanity\" and that Sinatra had \"spent his life casting a magnificent and powerful shadow.\"\nOn September 21, 1983, Sinatra filed a $2 million court case against Kitty Kelley, suing her for punitive damages, before her unofficial biography, His Way, was even published. The book became a best-seller for \"all the wrong reasons\" and \"the most eye-opening celebrity biography of our time\", according to William Safire of The New York Times. Sinatra was always adamant that such a book would be written on his terms, and he himself would \"set the record straight\" in details of his life.\nAccording to Kelley, the family detested her and the book, which took its toll on Sinatra''s health. Kelley says that Tina Sinatra blamed her for her father''s colon surgery in 1986. He was forced to drop the case on September 19, 1984, with several leading newspapers expressing concerns about censorship.\nIn 1984, Sinatra worked with Quincy Jones for the first time in nearly two decades on the album L.A. Is My Lady, which was well received critically. The album was a substitute for another Jones project, an album of duets with Lena Horne, which had to be abandoned. In 1986, Sinatra collapsed on stage while performing in Atlantic City and was hospitalized for diverticulitis, which left him looking frail. Two years later, Sinatra reunited with Martin and Davis and went on the Rat Pack Reunion Tour, during which they played many large arenas. When Martin dropped out of the tour early on, a rift developed between them, and the two never spoke again.\nOn June 6, 1988, Sinatra made his last recordings with Reprise for an album that was not released. He recorded \"My Foolish Heart\", \"Cry Me a River\", and other songs. Sinatra never completed the project, but take number 18 of \"My Foolish Heart\" may be heard in The Complete Reprise Studio Recordings (1995).\nIn 1990, Sinatra was awarded the second \"Ella Award\" by the Los Angeles-based Society of Singers, and performed for a final time with Ella Fitzgerald at the award ceremony. He maintained an active touring schedule in the early 1990s, performing 65 concerts in 1990, 73 in 1991, and 84 in 1992 in 17 countries.\nIn 1993, Sinatra returned to Capitol Records and the recording studio for Duets, which became his best-selling album. The album and its sequel, Duets II, released the following year, would see Sinatra remake his classic recordings with popular contemporary performers, who added their vocals to a pre-recorded tape.\nDuring his tours in the early 1990s, Sinatra''s memory failed him at times during concerts, and he fainted onstage in Richmond, Virginia in March 1994. Sinatra''s final public concerts were held in Fukuoka Dome in Japan on December 19–20, 1994. The following year, Sinatra sang for the last time on February 25, 1995, before a live audience of 1,200 select guests at the Palm Desert Marriott Ballroom on the closing night of the Frank Sinatra Desert Classic golf tournament.\nEsquire reported of the show that Sinatra was \"clear, tough, on the money\" and \"in absolute control\". He was awarded the Legend Award at the 1994 Grammy Awards, where Sinatra was introduced by Bono, who said of him, \"Frank''s the chairman of the bad attitude ... Rock ''n roll plays at being tough, but this guy is the boss – the chairman of boss\".\nIn 1995, to mark Sinatra''s 80th birthday, the Empire State Building glowed blue. A star-studded birthday tribute, Sinatra: 80 Years My Way, was held at the Shrine Auditorium in Los Angeles, featuring performers such as Ray Charles, Little Richard, Natalie Cole and Salt-N-Pepa singing his songs. At the end of the program, Sinatra performed on stage for the last time to sing the final notes of the \"Theme from New York, New York\" with an ensemble. In recognition of his many years of association with Las Vegas, Sinatra was elected to the Gaming Hall of Fame in 1997.","1935–1942: Career Beginnings":"Sinatra (far right) with the Hoboken Four on Major Bowes'' Amateur Hour in 1935\nSinatra began singing professionally as a teenager. He never learned to read music but learned by ear. Sinatra got his first break in 1935 when his mother persuaded a local singing group called the 3 Flashes, who were auditioning for the Major Bowes Amateur Hour show, to let him join. Baritone Fred Tamburro stated, \"Frank hung around us like we were gods or something\", admitting that they only took him on board because he owned a car and could chauffeur the group.\nThe group became the \"Hoboken Four\" and passed an audition from Major Bowes to appear on the show. They each earned $12.50, and attracted 40,000 votes to win first prize—a six-month contract to perform on stage and radio across the U.S. Sinatra quickly became the group''s lead singer, and, much to the jealousy of his fellow group members, garnered most of the attention from the girls. Due to the success of the group, Bowes kept asking for them to return, disguised under different names, varying from \"The Secaucus Cockamamies\" to \"The Bayonne Bacalas,\" although this may be apocryphal, sourced from Sinatra''s humorous stage patter during his appearance with the Count Basie orchestra at the Sands (1966).\nIn March 1939, saxophone player Frank Mane, who knew Sinatra from Jersey City radio station WAAT, arranged for him to audition and record \"Our Love\", his first solo studio recording. In June, bandleader Harry James, who had heard Sinatra sing on \"Dance Parade\", signed him to a two-year contract of $75 a week after a show at the Paramount Theatre in New York. It was with the James band that Sinatra released his first commercial record \"From the Bottom of My Heart\" in July. No more than 8,000 copies were sold, and further records released with James through 1939, such as \"All or Nothing at All\", also had weak sales on their initial release. Thanks to his vocal training, Sinatra could now sing two tones higher, and developed a repertoire that included songs such as \"My Buddy\", \"Willow Weep for Me\", \"It''s Funny to Everyone but Me\", \"Here Comes the Night\", \"On a Little Street in Singapore\", \"Ciribiribin\", and \"Every Day of My Life\".\nSinatra became increasingly frustrated with the Harry James band, feeling that he was not achieving the major success and acclaim he was looking for. Sinatra''s pianist and close friend Hank Sanicola persuaded him to stay with the group, but Sinatra left James in November 1939 to replace Jack Leonard as the lead singer of the Tommy Dorsey band. Sinatra earned $125 a week, appearing at the Palmer House in Chicago, and James released Sinatra from his contract.\nSinatra and Tommy Dorsey in Ship Ahoy (1942)\nOn January 26, 1940, Sinatra made his first public appearance with the band at the Coronado Theatre in Rockford, Illinois, opening the show with \"Stardust\". Dorsey recalled: \"You could almost feel the excitement coming up out of the crowds when the kid stood up to sing. Remember, he was no matinée idol. He was just a skinny kid with big ears. I used to stand there so amazed I''d almost forget to take my own solos\".\nDorsey was a major influence on Sinatra and became a father figure. Sinatra copied Dorsey''s mannerisms and traits, becoming a demanding perfectionist like him, even adopting his hobby of toy trains. Sinatra asked Dorsey to be godfather to his daughter Nancy in June 1940. Sinatra later said that \"The only two people I''ve ever been afraid of are my mother and Tommy Dorsey.\" Although Kelley says that Sinatra and drummer Buddy Rich were bitter rivals, other authors state that they were friends and even roommates when the band was on the road, but professional jealousy surfaced as both men wanted to be considered the star of Dorsey''s band. Later, Sinatra helped Rich form his own band with a $25,000 loan and provided financial help to Rich during times of the drummer''s serious illness.\nIn his first year with Tommy Dorsey, Sinatra recorded more than 40 songs. His first vocal hit was the song \"Polka Dots and Moonbeams\" in late April 1940. Two more chart appearances followed with \"Say It\" and \"Imagination\", which was Sinatra''s first top-10 hit. His fourth chart appearance (and his first on the first officially published Billboard chart) was \"I''ll Never Smile Again\", topping the charts for twelve weeks beginning in mid-July. Other records with Dorsey issued by RCA Victor include \"Our Love Affair\" and \"Stardust\" in 1940; \"Oh! Look at Me Now\", \"Dolores\", \"Everything Happens to Me\", and \"This Love of Mine\" in 1941; \"Just as Though You Were There\", \"Take Me\", and \"There Are Such Things\" in 1942; and \"It Started All Over Again\", \"In the Blue of Evening\", and \"It''s Always You\" in 1943.\nSinatra performing with Harry James at the Hollywood Canteen in 1943\nAs his success and popularity grew, Sinatra pushed Dorsey to allow him to record some solo songs. Dorsey eventually relented, and on January 19, 1942, Sinatra recorded \"Night and Day\", \"The Night We Called It a Day\", \"The Song is You\", and \"Lamplighter''s Serenade\" at a Bluebird recording session, with Axel Stordahl as arranger and conductor. Sinatra first heard the recordings at the Hollywood Palladium and Hollywood Plaza and was astounded at how good he sounded. Stordahl recalled: \"He just couldn''t believe his ears. He was so excited you almost believed he had never recorded before. I think this was a turning point in his career. I think he began to see what he might do on his own\".\nAfter the 1942 recordings, Sinatra believed that he needed to go solo, with an insatiable desire to compete with Bing Crosby, but Sinatra was hampered by his contract which gave Dorsey 43% of Sinatra''s lifetime earnings. A legal battle ensued, eventually settled in August 1942. On September 3, 1942, Dorsey bade farewell to Sinatra, reportedly saying, \"I hope you fall on your ass\", but he was more gracious on the air when replacing Sinatra with singer Dick Haymes.\nRumors began spreading in newspapers that Sinatra''s mobster godfather, Willie Moretti, coerced Dorsey at gunpoint to let Sinatra out of his contract for a few thousand dollars. Sinatra persuaded Stordahl to come with him and become his personal arranger, offering him $650 a month, five times his salary from Dorsey. Dorsey and Sinatra, who had been very close, never reconciled their differences.","1946–1952: Columbia Years And Career Slump":"Despite being heavily involved in political activity in 1945 and 1946, Sinatra sang on 160 radio shows, recorded 36 times, and shot four films in those two years. By 1946, he was performing on stage up to 45 times a week, singing up to 100 songs daily, and earning up to $93,000 a week.\nIn 1946, Sinatra released \"Oh! What it Seemed to Be\", \"Day by Day\", \"They Say It''s Wonderful\", \"Five Minutes More\", and \"The Coffee Song\" as singles, and launched his first album, The Voice of Frank Sinatra, which reached No. 1 on the Billboard chart. William Ruhlmann of AllMusic wrote that Sinatra \"took the material very seriously, singing the love lyrics with utter seriousness\" and that his \"singing and the classically influenced settings gave the songs unusual depth of meaning.\" Sinatra was soon selling 10 million records a year.\nSuch was Sinatra''s command at Columbia that his love of conducting was indulged with the release of the set Frank Sinatra Conducts the Music of Alec Wilder, an offering unlikely to appeal to Sinatra''s core fanbase of teenage girls at the time. In 1947, he released his second album, Songs by Sinatra, featuring songs of a similar mood and tempo such as Irving Berlin''s \"How Deep is the Ocean?\" and Harold Arlen''s and Jerome Kern''s \"All The Things You Are\". \"Mam''selle\", composed by Edmund Goulding with lyrics by Mack Gordon for the film The Razor''s Edge (1946), was released as a single.\nSinatra had competition; versions by Art Lund, Dick Haymes, Dennis Day, and The Pied Pipers also reached the top ten of the Billboard charts. In December, Sinatra recorded \"Sweet Lorraine\" with the Metronome All-Stars, featuring talented jazz musicians such as Coleman Hawkins, Harry Carney and Charlie Shavers, with Nat King Cole on piano, in what Charles L. Granata describes as \"one of the highlights of Sinatra''s Columbia epoch\".\nSinatra''s third album, Christmas Songs by Sinatra, was originally released in 1948 as a 78 rpm album set, and a 10\" LP record was released two years later. When Sinatra was featured as a priest in The Miracle of the Bells, due to press negativity surrounding his Mafia connections at the time, it was announced to the public that Sinatra would donate his $100,000 in wages from the film to the Catholic Church.\nBy the end of 1948, Sinatra had slipped to fourth on DownBeat''s annual poll of most popular singers, and the following year, he was pushed out of the top spots in polls for the first time since 1943. Frankly Sentimental (1949) was panned by DownBeat, who commented that \"for all his talent, it seldom comes to life.\"\nAlthough \"The Hucklebuck\" reached the top ten, it was his last single release under the Columbia label. Sinatra''s last two albums with Columbia, Dedicated to You and Sing and Dance with Frank Sinatra, were released in 1950. He would later feature a number of the Sing and Dance with Frank Sinatra album''s songs, including \"Lover\", \"It''s Only a Paper Moon\", and \"It All Depends on You\", on his 1961 Capitol release, Sinatra''s Swingin'' Session!!!.\nCulminating the low of Sinatra''s career was the death of publicist George Evans in January 1950. According to Jimmy Van Heusen, Sinatra''s close friend and songwriter, Evans'' death to him was \"an enormous shock which defies words\", as he had been crucial to Sinatra''s career and popularity with the \"bobby soxers\".\nSinatra''s reputation continued to decline as reports broke in February of his affair with Ava Gardner and the destruction of his marriage to Nancy, although Sinatra insisted that his marriage had long been over even before meeting Gardner. In April, he was engaged to perform at the Copa club in New York, but had to cancel five days of the booking due to a submucosal hemorrhage of the throat. Evans once said that whenever Sinatra suffered from a bad throat and loss of voice, it was always due to emotional tension, which \"absolutely destroyed him\".\nThe Desert Inn, Las Vegas, where Sinatra began performing in 1951\nIn financial difficulty following his divorce and career decline, Sinatra was forced to borrow $200,000 from Columbia to pay his back taxes after MCA refused to front the money. Rejected by Hollywood, Sinatra turned to Las Vegas and made his debut at the Desert Inn in September 1951, and also began singing at the Riverside Hotel in Reno, Nevada.\nSinatra''s decline in popularity was evident in his concert appearances. At a brief run at the Paramount in New York, Sinatra drew small audiences. At the Desert Inn in Las Vegas, he performed to half-filled houses. At a concert at Chez Paree in Chicago, only 150 people turned up in a 1,200-seat venue. By April 1952, Sinatra was performing at the Kauai County Fair in Hawaii. Sinatra''s relationship with Columbia Records was disintegrating, with A&R executive Mitch Miller claiming he \"couldn''t give away\" Sinatra records. However, several notable recordings were made during this time period, such as \"If I Could Write a Book\" in January 1952, which Granata sees as a \"turning point\", forecasting his later work with its sensitivity,\nColumbia and MCA dropped Sinatra later in 1952. His last studio recording for Columbia, \"Why Try To Change Me Now\", was recorded in New York on September 17, 1952, with an orchestra arranged and conducted by Percy Faith. Journalist Burt Boyar observed, \"Sinatra had had it. It was sad. From the top to the bottom in one horrible lesson.\"","1953–1960: Career Revival And The Capitol Years":"Nelson Riddle, Sinatra''s album arranger for Capitol Records\nThe release of the film From Here to Eternity in August 1953 marked the beginning of a remarkable career revival. Tom Santopietro notes that Sinatra began to bury himself in his work, with an \"unparalleled frenetic schedule of recordings, movies and concerts\", in what authors Anthony Summers and Robbyn Swan describe as \"a new and brilliant phase\". On March 13, 1953, Sinatra met with Capitol Records vice president Alan Livingston and signed a seven-year recording contract. Sinatra''s first session for Capitol took place at KHJ studios at Studio C, 5515 Melrose Avenue in Los Angeles, with Axel Stordahl conducting. The session produced four recordings, including \"I''m Walking Behind You\", Sinatra''s first Capitol single.\nAfter spending two weeks on location in Hawaii filming From Here to Eternity, Sinatra returned to KHJ on April 30 for his first recording session with Nelson Riddle, an established arranger and conductor at Capitol who was Nat King Cole''s musical director. After recording the first song, \"I''ve Got the World on a String\", Sinatra offered Riddle a rare expression of praise, \"Beautiful!\", and after listening to the playbacks, he could not hide his enthusiasm, exclaiming, \"I''m back, baby, I''m back!\" In subsequent sessions in May and November 1953, Sinatra and Riddle developed and refined their musical collaboration, with Sinatra providing specific guidance on the arrangements. Sinatra''s first album for Capitol, Songs for Young Lovers, was released on January 4, 1954, and it included \"A Foggy Day\", \"I Get a Kick Out of You\", \"My Funny Valentine\", \"Violets for Your Furs\", and \"They Can''t Take That Away from Me\", songs that became staples of his later concerts.\nThat same month, Sinatra released the single \"Young at Heart\", which reached No. 2 and was awarded Song of the Year. In March, he recorded and released the single \"Three Coins in the Fountain\", a \"powerful ballad\" that reached No. 4. Sinatra''s second album with Riddle, Swing Easy!, which reflected his \"love for the jazz idiom\" according to Granata, was released on August 2 and included \"Just One of Those Things\", \"Taking a Chance on Love\", \"Get Happy\", and \"All of Me\". Swing Easy! was named Album of the Year by Billboard, and Sinatra was named \"Favorite Male Vocalist\" by Billboard, DownBeat, and Metronome in 1954. Sinatra came to consider Riddle \"the greatest arranger in the world\", and Riddle, who considered Sinatra, \"a perfectionist\", said: \"It''s not only that his intuitions as to tempo, phrasing, and even configuration are amazingly right, but his taste is so impeccable ... There is still no one who can approach him.\"\nSinatra recording at Capitol Studios, c. 1955\nSinatra became one of Las Vegas''s pioneer residency entertainers, and a prominent figure in the Vegas scene throughout the 1950s and 1960s onwards, a period described by Rojek as the \"high-water mark\" of Sinatra''s \"hedonism and self-absorption\". Rojek notes that the Rat Pack \"provided an outlet for gregarious banter and wisecracks\" but argues that it was Sinatra''s vehicle, possessing an \"unassailable command over the other performers\". Sinatra would fly to Las Vegas from Los Angeles in Van Heusen''s plane. On October 4, 1953, Sinatra made his first performance at the Sands Hotel and Casino, after an invitation by the manager Jack Entratter. Sinatra typically performed there three times a year and later acquired a share in the hotel.\nIn 1955, Sinatra released In the Wee Small Hours, his first 12\" LP, featuring songs such as \"In the Wee Small Hours of the Morning\", \"Mood Indigo\", \"Glad to Be Unhappy\" and \"When Your Lover Has Gone\". According to Granata, it was the first concept album of his to make a \"single persuasive statement\", with an extended program and \"melancholy mood\". Sinatra embarked on his first tour of Australia the same year. Another collaboration with Riddle resulted in Songs for Swingin'' Lovers!, sometimes seen as one of his best albums, which was released in March 1956. It features a recording of \"I''ve Got You Under My Skin\" by Cole Porter, which reportedly took 22 takes to perfect.\nSinatra''s February 1956 recording sessions inaugurated the studios at the Capitol Records Building, complete with a 56-piece symphonic orchestra. According to Granata, his recordings of \"Night and Day\", \"Oh! Look at Me Now\", and \"From This Moment On\" revealed \"powerful sexual overtones, stunningly achieved through the mounting tension and release of Sinatra''s best-teasing vocal lines\", while his recording of \"River, Stay ''Way from My Door\" in April demonstrated his \"brilliance as a syncopational improviser\". Riddle said that Sinatra took \"particular delight\" in singing \"The Lady is a Tramp\", commenting that he \"always sang that song with a certain amount of salaciousness\", making \"cue tricks\" with the lyrics. Sinatra''s penchant for conducting was displayed again in 1956''s Frank Sinatra Conducts Tone Poems of Color, an instrumental album that has been interpreted to be a catharsis to his failed relationship with Gardner. Sinatra also sang at that year''s Democratic National Convention and performed with The Dorsey Brothers for a week soon afterward at the Paramount Theatre.\nSinatra introducing his character to the audience in the 1957 trailer for the film Pal Joey\nIn 1957, Sinatra released Close to You, A Swingin'' Affair!, and Where Are You?—his first album in stereo, with Gordon Jenkins. Granata considers \"Close to You\" to have been thematically his closest concept album to perfection during the \"golden\" era, and Nelson Riddle''s finest work, which was \"extremely progressive\" by the standards of the day. For Granata, Sinatra''s A Swingin'' Affair! and Songs for Swingin'' Lovers! solidified \"Sinatra''s image as a ''swinger'', from both a musical and visual standpoint.\" Buddy Collette considered the swing albums to have been heavily influenced by Sammy Davis Jr. and stated that when he worked with Sinatra in the mid-1960s, he approached a song much differently than he had done in the early 1950s. On June 9, 1957, Sinatra performed in a 62-minute concert conducted by Riddle at the Seattle Civic Auditorium, his first appearance in Seattle since 1945. The recording was first released as a bootleg, but Artanis Entertainment Group officially released it as Sinatra ''57 in Concert in 1999, after Sinatra''s death.\nIn 1958, Sinatra released the concept album Come Fly with Me with Billy May, designed as a musical world tour. It reached the top spot on the Billboard album chart in its second week, remaining at the top for five weeks, and was nominated for the Grammy Award for Album of the Year at the inaugural Grammy Awards. The title song, \"Come Fly With Me\", written especially for him, would become one of Sinatra''s best-known standards. On May 29, he recorded seven songs in a single session, more than double the usual yield of a recording session, and an eighth, \"Lush Life\", was abandoned as Sinatra found it too technically demanding. In September, Sinatra released Frank Sinatra Sings for Only the Lonely, a stark collection of introspective saloon songs and blues-tinged ballads, which proved a huge commercial success, spending 120 weeks on Billboard''s album chart and peaking at No. 1. Cuts from this LP, such as \"Angel Eyes\" and \"One for My Baby (and One More for the Road)\", would remain staples of the \"saloon song\" segments of Sinatra''s concerts.\nIn 1959, Sinatra released Come Dance with Me!, a highly successful, critically acclaimed album that stayed on Billboard''s Pop album chart for 140 weeks, peaking at No. 2. It won the Grammy Award for Album of the Year, as well as Best Vocal Performance, Male and Best Arrangement for Billy May. Sinatra released No One Cares in the same year, a collection of \"brooding, lonely\" torch songs, which critic Stephen Thomas Erlewine thought was \"nearly as good as its predecessor Where Are You?, but lacked the \"lush\" arrangements of it and the \"grandiose melancholy\" of Only the Lonely.\nIn May 1959, Sinatra wrote an article entitled \"You Can''t Hate and be Happy\" for a publication called \"What the Stars Say\" published by the Stars Campaign for Inter-Racial Friendship after the murder, in London, of Kelso Cochrane. In the words of Kelley, by 1959, Sinatra was \"not simply the leader of the Rat Pack\" but had \"assumed the position of il padrone in Hollywood.\" He was asked by 20th Century Fox to be the master of ceremonies at a luncheon attended by Soviet Premier Nikita Khrushchev on September 19, 1959. Nice ''n'' Easy, a collection of ballads, topped the Billboard chart in October 1960 and remained in the charts for 86 weeks, winning critical plaudits.","1960–1970: Reprise Years":"Sinatra grew discontented at Capitol and feuded with Alan Livingston, which lasted over six months. Sinatra''s first attempt at owning his own label was with his pursuit of buying declining jazz label Verve Records, which ended once an initial agreement with Verve founder Norman Granz \"failed to materialize\".\nSinatra decided to form his own label, Reprise Records, and, in an effort to assert his new direction, temporarily parted with Riddle, May and Jenkins, working with other arrangers such as Neil Hefti, Don Costa, and Quincy Jones. Sinatra built the appeal of Reprise Records as one in which artists were promised creative control, as well as a guarantee that they would eventually gain \"complete ownership of their work, including publishing rights.\"\nUnder Sinatra the company developed into a music industry \"powerhouse\", and he later sold it for an estimated $80 million. Sinatra''s first album on the label, Ring-a-Ding-Ding! (1961), was a major success, peaking at No.4 on Billboard. The album was released in February 1961, the same month that Reprise Records released Ben Webster''s The Warm Moods, Sammy Davis Jr.''s The Wham of Sam, Mavis River''s Mavis and Joe E. Lewis''s It is Now Post Time. During the initial years of Reprise, Sinatra was still under contract to record for Capitol, completing his contractual commitment with the release of Point of No Return, recorded on September 11 and 12, 1961.\nSinatra with Dean Martin and Judy Garland in 1962\nIn 1962, Sinatra released Sinatra and Strings, a set of standard ballads arranged by Don Costa, which became one of the most critically acclaimed works of Sinatra''s Reprise period. Frank Jr., who was present during the recording, noted the \"huge orchestra\", which Nancy Sinatra stated \"opened a whole new era\" in pop music, with orchestras getting bigger, embracing a \"lush string sound\".\nSinatra and Count Basie collaborated for the album Sinatra-Basie the same year, a popular and successful release, which prompted them to rejoin two years later for the follow-up It Might as Well Be Swing, arranged by Quincy Jones. The two became frequent performers together, and appeared at the Newport Jazz Festival in 1965. Also in 1962, as the owner of his own record label, Sinatra was able to step on the podium as conductor again, releasing his third instrumental album Frank Sinatra Conducts Music from Pictures and Plays.\nIn 1963, Sinatra reunited with Nelson Riddle for The Concert Sinatra, an ambitious album featuring a 73-piece symphony orchestra arranged and conducted by Riddle. The concert was recorded on a motion picture scoring soundstage with the use of multiple synchronized recording machines that employed an optical signal onto 35 mm film designed for movie soundtracks. Granata considers the album to have been \"impeachable\" , \"one of the very best of the Sinatra-Riddle ballad albums\", where Sinatra displayed his vocal range, particularly in \"Ol'' Man River\", in which Sinatra darkened the hue.\nIn 1964, the song \"My Kind of Town\" was nominated for the Academy Award for Best Original Song. Sinatra released Softly, as I Leave You, and collaborated with Bing Crosby and Fred Waring on America, I Hear You Singing, a collection of patriotic songs recorded as a tribute to the assassinated President John F. Kennedy. Sinatra increasingly became involved in charitable pursuits in this period. In 1961 and 1962, he went to Mexico to put on performances for Mexican charities, and in July 1964, Sinatra was present at the dedication of the Frank Sinatra International Youth Center for Arab and Jewish children in Nazareth.\nThe Rat Pack concert, called The Frank Sinatra Spectacular, was broadcast live via satellite to numerous movie theaters across America. The album September of My Years was released September 1965, and went on to win the Grammy Award for best album of the year. Granata considers the album to have been one of the finest of his Reprise years, \"a reflective throwback to the concept records of the 1950s, and more than any of those collections, distills everything that Frank Sinatra had ever learned or experienced as a vocalist\". One of the album''s singles, \"It Was a Very Good Year\", won the Grammy Award for Best Vocal Performance, Male. A career anthology, A Man and His Music, followed in November, winning Album of the Year at the Grammys the following year.\nIn 1966, Sinatra released That''s Life, with both the single of \"That''s Life\" and album becoming Top Ten hits on Billboard''s pop charts. Strangers in the Night went on to top the Billboard and UK pop singles charts, winning the award for Record of the Year at the Grammys. Sinatra''s first live album, Sinatra at the Sands, was recorded during January and February 1966 at the Sands Hotel and Casino in Las Vegas. He was backed by the Count Basie Orchestra, with Quincy Jones conducting. Sinatra pulled out from the Sands the following year when he was driven out by its new owner Howard Hughes after a fight.\nSinatra with Jill St. John in Tony Rome (1967)\nSinatra started 1967 with a series of recording sessions with Antônio Carlos Jobim. He recorded one of his collaborations with Jobim, the Grammy-nominated album Francis Albert Sinatra & Antônio Carlos Jobim, which was one of the best-selling albums of the year, behind the Beatles''s Sgt. Pepper''s Lonely Hearts Club Band. According to Santopietro, the album \"consists of an extraordinarily effective blend of bossa nova and slightly swinging jazz vocals, and succeeds in creating an unbroken mood of romance and regret.\" Writer Stan Cornyn wrote that Sinatra sang so softly on the album that it was comparable to the time that he suffered from a vocal hemorrhage in 1950.\nSinatra released the album The World We Knew, which features a chart-topping duet of \"Somethin'' Stupid\" with daughter Nancy. In December, Sinatra collaborated with Duke Ellington on the album Francis A. & Edward K.. According to Granata, the recording of \"Indian Summer\" on the album was a favorite of Riddle''s, noting the \"contemplative mood  is heightened by a Johnny Hodges alto sax solo that will bring a tear to your eye\".\nWith Sinatra in mind, singer-songwriter Paul Anka wrote the song \"My Way\", using the melody of the French \"Comme d''habitude\" (\"As Usual\"), composed by Claude François and Jacques Revaux. Sinatra recorded it in one take, just after Christmas 1968. \"My Way\", Sinatra''s best-known song on the Reprise label, was not an instant success, charting at No. 27 in the US and No. 5 in the UK. However, it remained in the UK charts for 122 weeks, including 75 non-consecutive weeks in the Top 40, between April 1969 and September 1971, which was still a record in 2015. Sinatra told songwriter Ervin Drake in the 1970s that he \"detested\" singing the song because he believed audiences would think it was a \"self-aggrandizing tribute\". According to NPR, \"My Way\" has become one of the most requested songs at funerals.\nIn an effort to maintain his commercial viability in the late 1960s, Sinatra would record works by Paul Simon (\"Mrs. Robinson\"), the Beatles (\"Yesterday\"), and Joni Mitchell (\"Both Sides, Now\") in 1969.","1982–1997: Later Career And Final Projects":"Sinatra signed a $16 million three-year deal with the Golden Nugget Las Vegas in 1982.\nHandprint of Sinatra. Atlantic City Boardwalk, New Jersey, US, 2006\nSantopietro stated that by the early 1980s, Sinatra''s voice had \"coarsened, losing much of its power and flexibility, but audiences didn''t care.\" Kelley noted that by this period, Sinatra''s voice had grown \"darker, tougher and loamier\", but he \"continued to captivate audiences with his immutable magic.\" She added that Sinatra''s baritone voice \"sometimes cracked, but the gliding intonations still aroused the same raptures of delight as they had at the Paramount Theater.\"\nAlso in 1982, Sinatra made a reported further $1.3 million from the Showtime television rights to his \"Concert of the Americas\" in the Dominican Republic, $1.6 million for a concert series at Carnegie Hall, and $250,000 in just one evening at the Chicago Fest. Sinatra donated a lot of his earnings to charity. He put on a performance at the White House for Italian president Sandro Pertini, and performed at the Radio City Music Hall with Luciano Pavarotti and George Shearing.\nSinatra was honored at the 1983 Kennedy Center Honors, alongside Katherine Dunham, James Stewart, Elia Kazan, and Virgil Thomson. Quoting Henry James, President Reagan said in honoring his old friend that \"art was the shadow of humanity\" and that Sinatra had \"spent his life casting a magnificent and powerful shadow.\"\nOn September 21, 1983, Sinatra filed a $2 million court case against Kitty Kelley, suing her for punitive damages, before her unofficial biography, His Way, was even published. The book became a best-seller for \"all the wrong reasons\" and \"the most eye-opening celebrity biography of our time\", according to William Safire of The New York Times. Sinatra was always adamant that such a book would be written on his terms, and he himself would \"set the record straight\" in details of his life.\nAccording to Kelley, the family detested her and the book, which took its toll on Sinatra''s health. Kelley says that Tina Sinatra blamed her for her father''s colon surgery in 1986. He was forced to drop the case on September 19, 1984, with several leading newspapers expressing concerns about censorship.\nIn 1984, Sinatra worked with Quincy Jones for the first time in nearly two decades on the album L.A. Is My Lady, which was well received critically. The album was a substitute for another Jones project, an album of duets with Lena Horne, which had to be abandoned. In 1986, Sinatra collapsed on stage while performing in Atlantic City and was hospitalized for diverticulitis, which left him looking frail. Two years later, Sinatra reunited with Martin and Davis and went on the Rat Pack Reunion Tour, during which they played many large arenas. When Martin dropped out of the tour early on, a rift developed between them, and the two never spoke again.\nOn June 6, 1988, Sinatra made his last recordings with Reprise for an album that was not released. He recorded \"My Foolish Heart\", \"Cry Me a River\", and other songs. Sinatra never completed the project, but take number 18 of \"My Foolish Heart\" may be heard in The Complete Reprise Studio Recordings (1995).\nIn 1990, Sinatra was awarded the second \"Ella Award\" by the Los Angeles-based Society of Singers, and performed for a final time with Ella Fitzgerald at the award ceremony. He maintained an active touring schedule in the early 1990s, performing 65 concerts in 1990, 73 in 1991, and 84 in 1992 in 17 countries.\nIn 1993, Sinatra returned to Capitol Records and the recording studio for Duets, which became his best-selling album. The album and its sequel, Duets II, released the following year, would see Sinatra remake his classic recordings with popular contemporary performers, who added their vocals to a pre-recorded tape.\nDuring his tours in the early 1990s, Sinatra''s memory failed him at times during concerts, and he fainted onstage in Richmond, Virginia in March 1994. Sinatra''s final public concerts were held in Fukuoka Dome in Japan on December 19–20, 1994. The following year, Sinatra sang for the last time on February 25, 1995, before a live audience of 1,200 select guests at the Palm Desert Marriott Ballroom on the closing night of the Frank Sinatra Desert Classic golf tournament.\nEsquire reported of the show that Sinatra was \"clear, tough, on the money\" and \"in absolute control\". He was awarded the Legend Award at the 1994 Grammy Awards, where Sinatra was introduced by Bono, who said of him, \"Frank''s the chairman of the bad attitude ... Rock ''n roll plays at being tough, but this guy is the boss – the chairman of boss\".\nIn 1995, to mark Sinatra''s 80th birthday, the Empire State Building glowed blue. A star-studded birthday tribute, Sinatra: 80 Years My Way, was held at the Shrine Auditorium in Los Angeles, featuring performers such as Ray Charles, Little Richard, Natalie Cole and Salt-N-Pepa singing his songs. At the end of the program, Sinatra performed on stage for the last time to sing the final notes of the \"Theme from New York, New York\" with an ensemble. In recognition of his many years of association with Las Vegas, Sinatra was elected to the Gaming Hall of Fame in 1997.","Vocal And Musical Style":"Voice coach John Quinlan was impressed by Sinatra''s vocal range, remarking, \"He has far more voice than people think he has. He can vocalize to a B-flat on top in full voice, and he doesn''t need a mic either\". As a singer, early on, he was primarily influenced by Bing Crosby, but later believed that Tony Bennett was \"the best singer in the business.\" Bennett himself claimed that as a performer, Sinatra had \"perfected the art of intimacy.\" According to Nelson Riddle, Sinatra had a \"fairly rangy voice\", remarking: \"His voice has a very strident, insistent sound in the top register, a smooth lyrical sound in the middle register, and a very tender sound in the low. His voice is built on infinite taste, with an overall inflection of sex. He points everything he does from a sexual standpoint\".\nDespite his heavy New Jersey accent, when Sinatra sang, his accent was barely detectable; according to Richard Schuller, Sinatra''s diction became \"precise\" while singing and his articulation \"meticulous\". Sinatra''s timing was impeccable, allowing him, according to Granata, to \"toy with the rhythm of a melody, bringing tremendous excitement to his reading of a lyric.\" Tommy Dorsey observed that Sinatra would \"take a musical phrase and play it all the way through seemingly without breathing for eight, ten, maybe sixteen bars.\" Dorsey was a considerable influence on Sinatra''s techniques for his vocal phrasing with his own exceptional breath control on the trombone, and Sinatra regularly swam and held his breath underwater, thinking of song lyrics to increase his breathing power.\n\"He''d always been critical of his voice, and that only intensified as he got older. He never liked to discuss a performance afterward because he knew his voice wasn''t as good as it used to be. If someone told him he''d been great, he''d reply, ''It was a nice crowd, but my reed was off'' or ''I wasn''t so good on the third number.'' Strangely, in spite of his hearing problems, he had the most incredible ear, which often drove those he worked with nuts. There could be an orchestra of a hundred musicians, and if one played a bum note, he''d know exactly who was responsible.\"\n—Barbara Sinatra on Sinatra''s voice and musical understanding.\nAfter a period of performing, Sinatra tired of singing a certain set of songs and was always looking for talented new songwriters and composers to work with. Once he found ones he liked, Sinatra actively sought to work with them as often as possible and made friends with many of them. Over the years, he recorded 87 of Sammy Cahn''s songs, of which 24 were composed by Jule Styne and 43 by Jimmy Van Heusen. The Cahn-Styne partnership lasted from 1942 until 1954, when Van Heusen succeeded him as Sinatra''s main composer.\nUnlike many of his contemporaries, Sinatra insisted upon direct input regarding arrangements and tempos for his recordings. Sinatra would spend weeks thinking about the songs he wanted to record and would keep an arranger in mind for each song. Barbara Sinatra notes that Sinatra would almost always credit the songwriter at the end of each number and would often make comments to the audience, such as \"Isn''t that a pretty ballad\" or \"Don''t you think that''s the most marvelous love song\", delivered with \"childlike delight\". She states that after each show, Sinatra would be \"in a buoyant, electrically charged mood, a post-show high that would take him hours to come down from as he quietly relived every note of the performance he''d just given.\"\nSinatra''s split with Ava Gardner in the fall of 1953 had a profound impact on the types of songs he sang and on his voice. Sinatra began to console himself in songs with a \"brooding melancholy\", such as \"I''m a Fool to Want You\", \"Don''t Worry ''Bout Me\", \"My One and Only Love\" and \"There Will Never Be Another You\", which Riddle believed was the direct influence of Gardner.\nLahr comments that the new Sinatra was \"not the gentle boy balladeer of the forties. Fragility had gone from his voice, to be replaced by a virile adult''s sense of happiness and hurt\". Granata considered Sinatra a \"master of the art of recording\", noting that his work in the studio \"set him apart from other gifted vocalists.\" During his career, Sinatra made over 1,000 recordings. Recording sessions would typically last three hours. However, Sinatra would always prepare for them by spending at least an hour by the piano beforehand to vocalize, followed by a short rehearsal with the orchestra to ensure the balance of sound.\nIn the 1950s, Sinatra''s career was facilitated by developments in technology. Up to 16 songs could now be held by the 12-inch L.P., and this allowed Sinatra to use song in a novelistic way, turning each track into a kind of chapter, which built and counterpointed moods to illuminate a larger theme\". Santopietro writes that through the 1950s and well into the 1960s, \"Every Sinatra LP was a masterpiece of one sort of another, whether uptempo, torch song, or swingin'' affairs. Track after track, the brilliant concept albums redefined the nature of pop vocal art\".","Film Career":"1941–1952: Debut, musical films, and career slump\nSinatra and Gene Kelly in Anchors Aweigh (1945)\nSinatra attempted to pursue an acting career in Hollywood in the early 1940s. While films appealed to him, being exceptionally self-confident, Sinatra was rarely enthusiastic about his own acting, once remarking that \"pictures stink\". Sinatra made his film debut performing in an uncredited sequence in Las Vegas Nights (1941), singing \"I''ll Never Smile Again\" with Tommy Dorsey''s Pied Pipers. Sinatra had a cameo role along with Duke Ellington and Count Basie in Charles Barton''s Reveille with Beverly (1943), making a brief appearance singing \"Night and Day\". Next, he was given leading roles in Higher and Higher and Step Lively (both 1944) for RKO.\nMetro-Goldwyn-Mayer cast Sinatra opposite Gene Kelly and Kathryn Grayson in the Technicolor musical Anchors Aweigh (1945), in which he played a sailor on leave in Hollywood. A major success, it garnered several Academy Award wins and nominations, and the song \"I Fall in Love Too Easily\", sung by Sinatra in the film, was nominated for the Academy Award for Best Original Song. He briefly appeared at the end of Richard Whorf''s commercially successful Till the Clouds Roll By (1946), a Technicolor musical biopic of Jerome Kern, in which Sinatra sang \"Ol'' Man River\".\nSinatra co-starred again with Gene Kelly in the Technicolor musical Take Me Out to the Ball Game (1949), in which they play baseball players who are part-time vaudevillians. He teamed up with Kelly for a third time in On the Town (1949), playing a sailor on leave in New York City. The film remains rated very highly by critics, and in 2006, it ranked No. 19 on the American Film Institute''s list of best musicals. Both Double Dynamite (1951), an RKO Irving Cummings comedy produced by Howard Hughes, and Joseph Pevney''s Meet Danny Wilson (1952) failed to make an impression.\nSinatra as Maggio in From Here to EternitySinatra at the 26th Academy AwardsFor his performance in From Here to Eternity (1953), Sinatra received the Academy Award for Best Supporting Actor.\nFred Zinnemann''s From Here to Eternity (1953) deals with the tribulations of three soldiers, played by Burt Lancaster, Montgomery Clift, and Sinatra, stationed on Hawaii in the months leading up to the attack on Pearl Harbor. Sinatra had long been desperate to find a film role that would bring him back into the spotlight, and Columbia Pictures boss Harry Cohn had been inundated by appeals to give Sinatra a chance to star as \"Maggio\" in the film. During production, Montgomery Clift became a close friend, and Sinatra later professed that he \"learned more about acting from him than anybody I ever knew before\". After several years of critical and commercial decline, his Academy Award for Best Supporting Actor win helped Sinatra regain his position as the top recording artist in the world. Sinatra''s performance also won a Golden Globe Award for Best Supporting Actor – Motion Picture. The Los Angeles Examiner wrote that Sinatra is \"simply superb, comical, pitiful, childishly brave, pathetically defiant\", commenting that his death scene is \"one of the best ever photographed\".\nSinatra starred opposite Doris Day in the musical film Young at Heart (1954), and earned critical praise for his performance as a psychopathic killer posing as an FBI agent opposite Sterling Hayden in the film noir Suddenly (1954).\nSinatra was nominated for an Academy Award for Best Actor and BAFTA Award for Best Actor in a Leading Role for his role as a heroin addict in The Man with the Golden Arm (1955). After roles in Guys and Dolls, and The Tender Trap (both 1955), Sinatra was nominated for a BAFTA Award for Best Actor in a Leading Role for his role as a medical student in Stanley Kramer''s directorial début, Not as a Stranger (1955). During production, Sinatra got drunk with Robert Mitchum and Broderick Crawford and trashed Kramer''s dressing room. Kramer vowed at the time never to hire Sinatra again and later regretted casting him as a Spanish guerrilla leader in The Pride and the Passion (1957).\nSinatra with Grace Kelly on the set of High Society (1956)\nSinatra featured alongside Bing Crosby and Grace Kelly in High Society (1956) for MGM, earning a reported $250,000 for the picture. The public rushed to the cinemas to see Sinatra and Crosby together on-screen, and it ended up earning over $13 million at the box office, becoming one of the highest-grossing pictures of its year. He starred opposite Rita Hayworth and Kim Novak in George Sidney''s Pal Joey (1957), for which Sinatra won a Golden Globe Award for Best Actor – Motion Picture Musical or Comedy. Santopietro considers the scene in which Sinatra sings \"The Lady Is a Tramp\" to have been the finest moment of his film career. He next portrayed comedian Joe E. Lewis in The Joker Is Wild (1957); the song \"All the Way\" won the Academy Award for Best Original Song. By 1958, Sinatra was one of the ten biggest box office draws in the United States, appearing with Dean Martin and Shirley MacLaine in Vincente Minnelli''s Some Came Running and Kings Go Forth (both 1958) with Tony Curtis and Natalie Wood. \"High Hopes\", sung by Sinatra in the Frank Capra comedy, A Hole in the Head (1959), won the Academy Award for Best Original Song, and became a chart hit, lasting on the Hot 100 for 17 weeks.\nSinatra leaving his signature in concrete at Grauman''s Chinese Theatre in Hollywood, California on July 21, 1965\nDue to an obligation, Sinatra owed to 20th Century Fox for walking off the set of Henry King''s Carousel (1956). He starred opposite Shirley MacLaine, Maurice Chevalier and Louis Jourdan in Can-Can (1960). Sinatra earned $200,000 and 25% of the profits for the performance. Around the same time, he starred in the Las Vegas-set Ocean''s 11 (1960), the first film to feature the Rat Pack together and the start of a \"new era of screen cool\" for Santopietro. Sinatra personally financed the film and paid Martin and Davis fees of $150,000 and $125,000, respectively, sums considered exorbitant for the period. He had a leading role opposite Laurence Harvey in The Manchurian Candidate (1962), which Sinatra considered to be the role he was most excited about and the high point of his film career. Vincent Canby, writing for the magazine Variety, found the portrayal of Sinatra''s character to be \"a wide-awake pro creating a straight, quietly humorous character of some sensitivity.\" He appeared with the Rat Pack in the western Sergeants 3 (1962), and again in the 1964 gangster-oriented musical Robin and the 7 Hoods. For his performance in Come Blow Your Horn (1963), adapted from the Neil Simon play, Sinatra was nominated for the Golden Globe Award for Best Actor – Motion Picture Musical or Comedy.\nSinatra directed only one film, the anti-war American-Japanese co-production None but the Brave (released in 1965), which he also starred in and co-produced; he then starred in Von Ryan''s Express (1965), another major success. In the late 1960s, he became known for playing detectives, including Tony Rome in Tony Rome (1967) and its sequel Lady in Cement (1968). Sinatra played a similar role in The Detective (1968). As Die Hard was based on the novel sequel to The Detective, 20th Century Fox was contractually obliged to offer Sinatra the lead role of John McClane. Sinatra, who was 70 years old at the time, declined.\nSinatra starred opposite George Kennedy in the western Dirty Dingus Magee (1970), an \"abysmal\" affair according to Santopietro, which was panned by the critics. The following year, Sinatra received a Golden Globe Cecil B. DeMille Award and had intended to play Detective Harry Callahan in Dirty Harry (1971), but had to turn down the role due to developing Dupuytren''s contracture in his hand. Sinatra''s last major film role was opposite Faye Dunaway in Brian G. Hutton''s The First Deadly Sin (1980). Santopietro said that as a troubled New York City homicide cop, Sinatra gave an \"extraordinarily rich\", heavily layered characterization, one which \"made for one terrific farewell\" to his film career.","1941–1952: Debut, Musical Films, And Career Slump":"Sinatra and Gene Kelly in Anchors Aweigh (1945)\nSinatra attempted to pursue an acting career in Hollywood in the early 1940s. While films appealed to him, being exceptionally self-confident, Sinatra was rarely enthusiastic about his own acting, once remarking that \"pictures stink\". Sinatra made his film debut performing in an uncredited sequence in Las Vegas Nights (1941), singing \"I''ll Never Smile Again\" with Tommy Dorsey''s Pied Pipers. Sinatra had a cameo role along with Duke Ellington and Count Basie in Charles Barton''s Reveille with Beverly (1943), making a brief appearance singing \"Night and Day\". Next, he was given leading roles in Higher and Higher and Step Lively (both 1944) for RKO.\nMetro-Goldwyn-Mayer cast Sinatra opposite Gene Kelly and Kathryn Grayson in the Technicolor musical Anchors Aweigh (1945), in which he played a sailor on leave in Hollywood. A major success, it garnered several Academy Award wins and nominations, and the song \"I Fall in Love Too Easily\", sung by Sinatra in the film, was nominated for the Academy Award for Best Original Song. He briefly appeared at the end of Richard Whorf''s commercially successful Till the Clouds Roll By (1946), a Technicolor musical biopic of Jerome Kern, in which Sinatra sang \"Ol'' Man River\".\nSinatra co-starred again with Gene Kelly in the Technicolor musical Take Me Out to the Ball Game (1949), in which they play baseball players who are part-time vaudevillians. He teamed up with Kelly for a third time in On the Town (1949), playing a sailor on leave in New York City. The film remains rated very highly by critics, and in 2006, it ranked No. 19 on the American Film Institute''s list of best musicals. Both Double Dynamite (1951), an RKO Irving Cummings comedy produced by Howard Hughes, and Joseph Pevney''s Meet Danny Wilson (1952) failed to make an impression.","1953–1959: Career Comeback And Prime":"Sinatra as Maggio in From Here to EternitySinatra at the 26th Academy AwardsFor his performance in From Here to Eternity (1953), Sinatra received the Academy Award for Best Supporting Actor.\nFred Zinnemann''s From Here to Eternity (1953) deals with the tribulations of three soldiers, played by Burt Lancaster, Montgomery Clift, and Sinatra, stationed on Hawaii in the months leading up to the attack on Pearl Harbor. Sinatra had long been desperate to find a film role that would bring him back into the spotlight, and Columbia Pictures boss Harry Cohn had been inundated by appeals to give Sinatra a chance to star as \"Maggio\" in the film. During production, Montgomery Clift became a close friend, and Sinatra later professed that he \"learned more about acting from him than anybody I ever knew before\". After several years of critical and commercial decline, his Academy Award for Best Supporting Actor win helped Sinatra regain his position as the top recording artist in the world. Sinatra''s performance also won a Golden Globe Award for Best Supporting Actor – Motion Picture. The Los Angeles Examiner wrote that Sinatra is \"simply superb, comical, pitiful, childishly brave, pathetically defiant\", commenting that his death scene is \"one of the best ever photographed\".\nSinatra starred opposite Doris Day in the musical film Young at Heart (1954), and earned critical praise for his performance as a psychopathic killer posing as an FBI agent opposite Sterling Hayden in the film noir Suddenly (1954).\nSinatra was nominated for an Academy Award for Best Actor and BAFTA Award for Best Actor in a Leading Role for his role as a heroin addict in The Man with the Golden Arm (1955). After roles in Guys and Dolls, and The Tender Trap (both 1955), Sinatra was nominated for a BAFTA Award for Best Actor in a Leading Role for his role as a medical student in Stanley Kramer''s directorial début, Not as a Stranger (1955). During production, Sinatra got drunk with Robert Mitchum and Broderick Crawford and trashed Kramer''s dressing room. Kramer vowed at the time never to hire Sinatra again and later regretted casting him as a Spanish guerrilla leader in The Pride and the Passion (1957).\nSinatra with Grace Kelly on the set of High Society (1956)\nSinatra featured alongside Bing Crosby and Grace Kelly in High Society (1956) for MGM, earning a reported $250,000 for the picture. The public rushed to the cinemas to see Sinatra and Crosby together on-screen, and it ended up earning over $13 million at the box office, becoming one of the highest-grossing pictures of its year. He starred opposite Rita Hayworth and Kim Novak in George Sidney''s Pal Joey (1957), for which Sinatra won a Golden Globe Award for Best Actor – Motion Picture Musical or Comedy. Santopietro considers the scene in which Sinatra sings \"The Lady Is a Tramp\" to have been the finest moment of his film career. He next portrayed comedian Joe E. Lewis in The Joker Is Wild (1957); the song \"All the Way\" won the Academy Award for Best Original Song. By 1958, Sinatra was one of the ten biggest box office draws in the United States, appearing with Dean Martin and Shirley MacLaine in Vincente Minnelli''s Some Came Running and Kings Go Forth (both 1958) with Tony Curtis and Natalie Wood. \"High Hopes\", sung by Sinatra in the Frank Capra comedy, A Hole in the Head (1959), won the Academy Award for Best Original Song, and became a chart hit, lasting on the Hot 100 for 17 weeks.","1960–1980: Later Career":"Sinatra leaving his signature in concrete at Grauman''s Chinese Theatre in Hollywood, California on July 21, 1965\nDue to an obligation, Sinatra owed to 20th Century Fox for walking off the set of Henry King''s Carousel (1956). He starred opposite Shirley MacLaine, Maurice Chevalier and Louis Jourdan in Can-Can (1960). Sinatra earned $200,000 and 25% of the profits for the performance. Around the same time, he starred in the Las Vegas-set Ocean''s 11 (1960), the first film to feature the Rat Pack together and the start of a \"new era of screen cool\" for Santopietro. Sinatra personally financed the film and paid Martin and Davis fees of $150,000 and $125,000, respectively, sums considered exorbitant for the period. He had a leading role opposite Laurence Harvey in The Manchurian Candidate (1962), which Sinatra considered to be the role he was most excited about and the high point of his film career. Vincent Canby, writing for the magazine Variety, found the portrayal of Sinatra''s character to be \"a wide-awake pro creating a straight, quietly humorous character of some sensitivity.\" He appeared with the Rat Pack in the western Sergeants 3 (1962), and again in the 1964 gangster-oriented musical Robin and the 7 Hoods. For his performance in Come Blow Your Horn (1963), adapted from the Neil Simon play, Sinatra was nominated for the Golden Globe Award for Best Actor – Motion Picture Musical or Comedy.\nSinatra directed only one film, the anti-war American-Japanese co-production None but the Brave (released in 1965), which he also starred in and co-produced; he then starred in Von Ryan''s Express (1965), another major success. In the late 1960s, he became known for playing detectives, including Tony Rome in Tony Rome (1967) and its sequel Lady in Cement (1968). Sinatra played a similar role in The Detective (1968). As Die Hard was based on the novel sequel to The Detective, 20th Century Fox was contractually obliged to offer Sinatra the lead role of John McClane. Sinatra, who was 70 years old at the time, declined.\nSinatra starred opposite George Kennedy in the western Dirty Dingus Magee (1970), an \"abysmal\" affair according to Santopietro, which was panned by the critics. The following year, Sinatra received a Golden Globe Cecil B. DeMille Award and had intended to play Detective Harry Callahan in Dirty Harry (1971), but had to turn down the role due to developing Dupuytren''s contracture in his hand. Sinatra''s last major film role was opposite Faye Dunaway in Brian G. Hutton''s The First Deadly Sin (1980). Santopietro said that as a troubled New York City homicide cop, Sinatra gave an \"extraordinarily rich\", heavily layered characterization, one which \"made for one terrific farewell\" to his film career.","Television And Radio Career":"After beginning on the Major Bowes Amateur Hour radio show with the Hoboken Four in 1935, and later WNEW and WAAT in Jersey City, Sinatra starred in his own radio shows on NBC and CBS from the early 1940s to the mid-1950s. In 1942, he hired arranger Axel Stordahl away from Tommy Dorsey before beginning his first radio program that year, keeping Stordahl with him for all of his radio work. By the end of 1942, Sinatra was named the \"Most Popular Male Vocalist on Radio\" in a DownBeat poll. Early on, he frequently worked with The Andrews Sisters on radio. They would appear as guests on each other''s shows, as well as on many USO shows broadcast to troops via the Armed Forces Radio Service (AFRS). Sinatra appeared as a special guest in the sisters'' ABC Eight-to-the-Bar Ranch series, while the trio in turn guested on his Songs by Sinatra series on CBS. Sinatra had two stints as a regular member of the cast of Your Hit Parade; his first was from 1943 to 1945, and second was from 1946 to May 28, 1949, during which Sinatra was paired with the then-new girl singer, Doris Day. Starting in September 1949, the BBD&O advertising agency produced a radio series starring Sinatra for Lucky Strike called Light Up Time – some 176 15-minute shows that featured him and Dorothy Kirsten singing – which lasted through to May 1950.\nIn October 1951, the second season of The Frank Sinatra Show began on CBS Television. Ultimately, Sinatra did not find the success on television for which he had hoped. Santopietro writes that Sinatra \"never appeared fully at ease on his own television series.\" In 1953 and 1954, Sinatra starred in the NBC radio program Rocky Fortune, portraying Rocco Fortunato (a.k.a. Rocky Fortune).\nDean Martin with Sinatra on The Dean Martin Show in 1958\nIn 1957, Sinatra formed a three-year, $3 million contract with ABC to launch The Frank Sinatra Show, featuring himself and guests in 36 half-hour shows. ABC agreed to allow Sinatra''s Hobart Productions to keep 60% of the residuals and bought stock in Sinatra''s film production unit, Kent Productions, guaranteeing him $7 million. Though an initial critical success upon its debut on October 18, 1957, it soon attracted negative reviews from Variety and The New Republic, and The Chicago Sun-Times thought that Sinatra and frequent guest Dean Martin \"performed like a pair of adult delinquents\", \"sharing the same cigarette and leering at girls.\" Sinatra later made numerous appearances on The Dean Martin Show and Martin''s TV specials.\nSinatra''s fourth and final Timex TV special, Welcome Home Elvis, was broadcast in March 1960, earning massive viewing figures. During the show, he performed a duet with Presley, who sang Sinatra''s 1957 hit \"Witchcraft\" with the host performing the 1956 Presley classic \"Love Me Tender\". Sinatra had previously been highly critical of Elvis Presley and rock and roll in the 1950s, describing it as a \"deplorable, a rancid smelling aphrodisiac\" that \"fosters almost totally negative and destructive reactions in young people.\" A CBS News special about Sinatra''s 50th birthday, Frank Sinatra: A Man and His Music, was broadcast on November 16, 1965, and received an Emmy award and a Peabody Award.\nContinuing his musical collaboration with Jobim and Ella Fitzgerald in 1967, Sinatra appeared in the TV special, A Man and His Music + Ella + Jobim, which was broadcast on CBS on November 13. When Sinatra came out of retirement in 1973, he appeared in a TV special that shared its title with his contemporaneously released album, Ol'' Blue Eyes Is Back. In the late 1970s, John Denver appeared as a guest in the Sinatra and Friends ABC-TV Special, singing \"September Song\" as a duet.\nSinatra starred as a detective in Contract on Cherry Street (1977), cited as his \"one starring role in a dramatic television film\". Ten years later, Sinatra made a guest appearance opposite Tom Selleck in Magnum, P.I.. Shot in January 1987, the episode aired on CBS on February 25.","Personal Life":"Main article: Personal life of Frank Sinatra\nFamily portrait, 1949. Sinatra with (from left) Nancy, Tina, Nancy Barbato and Frank Jr.\nSinatra was married to Nancy (née Barbato) from 1939 to 1951. They had three children: Nancy (born 1940), Frank Jr. (1944–2016) and Tina (born 1948).\nSinatra met Barbato in Long Branch, New Jersey, in the summer of 1934 while working as a lifeguard. He agreed to marry her after an incident at \"The Rustic Cabin\" that led to his arrest. Sinatra had numerous extramarital affairs, and gossip magazines published details of affairs with women including Marilyn Maxwell, Lana Turner and Joi Lansing.\nSinatra was married to Hollywood actress Ava Gardner from 1951 to 1957. It was a turbulent marriage with many well-publicized fights and altercations. The couple formally announced their separation on October 29, 1953, through MGM. Gardner filed for divorce in June 1954, at a time when she was dating matador Luis Miguel Dominguín, but the divorce was not settled until 1957. Sinatra continued to feel very strongly for her, and they remained lifelong friends.\nIn 1957, Sinatra moved to a home in Rancho Mirage, California, called The Compound.\nSinatra reportedly broke off engagements to Lauren Bacall in 1958 and Juliet Prowse in 1962. He was romantically linked to Marilyn Monroe, Pat Sheehan, Vikki Dougan, and Kipp Hamilton. Sinatra and Mia Farrow were married on July 19, 1966, and the couple divorced in August 1968. They remained close friends for life, and in a 2013 interview, Farrow said that Sinatra might be the father of her son, Ronan Farrow (born 1987). In a 2015 CBS Sunday Morning interview, Nancy Sinatra dismissed the claim as \"nonsense\". She said that her father had a vasectomy years before Farrow''s birth.\nSinatra was married to Barbara Marx from 1976 until his death. They got married on July 11, 1976, at Sunnylands, in Rancho Mirage, California, the estate of media magnate Walter Annenberg.\nSinatra was close friends with Jilly Rizzo, songwriter Jimmy Van Heusen, golfer Ken Venturi, comedian Pat Henry, comedian Don Rickles, baseball manager Leo Durocher, and president John F. Kennedy (for whom he organized an inaugural ball with Peter Lawford). In his spare time, Sinatra enjoyed listening to classical music. He swam daily in the Pacific Ocean. Sinatra often played golf with Venturi at the course in Palm Springs, where he lived in the house Twin Palms he had commissioned from E. Stewart Williams in 1947 Sinatra liked painting, reading, and building model railways.\nAlthough Sinatra was critical of the church on numerous occasions and had a pantheistic, Einstein-like view of God in his earlier life, Sinatra was inducted into the Catholic Sovereign Military Order of Malta in 1976, and turned to Catholicism for healing after his mother died in a plane crash in 1977. He died as a practicing Catholic and had a Catholic burial.\nSinatra was known for his immaculate sense of style. He spent lavishly on expensive custom-tailored tuxedos and stylish pin-striped suits, which made him feel wealthy and important and that he was giving his very best to the audience. Sinatra was also obsessed with cleanliness—while with the Tommy Dorsey band, he developed the nickname \"Lady Macbeth\" because of frequent showering and switching his outfits. Sinatra''s deep blue eyes earned him the popular nickname \"Ol'' Blue Eyes\".\nFor Santopietro, Sinatra was the personification of America in the 1950s: \"cocky, eye on the main chance, optimistic, and full of the sense of possibility.\" Barbara Sinatra wrote, \"A big part of Frank''s thrill was the sense of danger that he exuded, an underlying, ever-present tension only those closest to him knew could be defused with humor.\" Cary Grant, a friend of Sinatra, stated that Sinatra was the \"most honest person he''d ever met\", who spoke \"a simple truth, without artifice which scared people\", and was often moved to tears by his performances. Jo-Caroll Dennison commented that he possessed \"great inner strength\" and that his energy and drive were \"enormous.\" A workaholic, Sinatra reportedly only slept four hours a night on average. Throughout his life, Sinatra had mood swings and bouts of mild to severe depression, stating to an interviewer in the 1950s that \"I have an over-acute capacity for sadness as well as elation.\" Barbara Sinatra stated that he would \"snap at anyone for the slightest misdemeanor\", while Van Heusen said that when Sinatra got drunk, it was \"best to disappear.\"\nSinatra''s mood swings often developed into violence, directed at people he felt had crossed him, particularly journalists who gave him scathing reviews, publicists, and photographers. According to Rojek, Sinatra was \"capable of deeply offensive behavior that smacked of a persecution complex.\" He received negative press for fights with Lee Mortimer in 1947, photographer Eddie Schisser in Houston in 1950, Judy Garland''s publicist Jim Byron on the Sunset Strip in 1954, and for a confrontation with Washington Post journalist Maxine Cheshire in 1973, in which Sinatra implied that she was a cheap prostitute. His feud with then-Chicago Sun Times columnist Mike Royko began when Royko wrote a column questioning why Chicago police offered free protection to Sinatra when he had his own security. Sinatra wrote an angry letter in response, calling Royko a \"pimp\" and threatening to \"punch you in the mouth\" for speculating that he wore a toupée. Arrangers such as Nelson Riddle and Anthony Fanzo found Sinatra to be a perfectionist, approaching him with uneasiness because of his often volatile temperament. Granata comments that Sinatra was so obsessed with perfection that people began wondering if he was more concerned about the music or showing off his power over others.\nSinatra was also known for his generosity, particularly after his comeback. Kelley notes that when Lee J. Cobb nearly died from a heart attack in June 1955, Sinatra flooded him with \"books, flowers, delicacies\", paid his hospital bills, and visited him daily, telling him that his \"finest acting\" was yet to come.\nAlleged organized-crime links and Cal Neva Lodge\nSinatra became the stereotype of the \"tough working-class Italian American\", something that he embraced. Sinatra said that if it had not been for his interest in music, he would have likely ended up in a life of crime. Willie Moretti was Sinatra''s godfather and the notorious underboss of the Genovese crime family, and he helped Sinatra in exchange for kickbacks and was reported to have intervened in releasing Sinatra from his contract with Tommy Dorsey. Sinatra was present at the Mafia Havana Conference in 1946, and the press learned of his being there with Lucky Luciano. He was reported to be a good friend of mobster Sam Giancana, Kelley quoted Jo-Carrol Silvers that Sinatra \"adored\" Bugsy Siegel and boasted to friends about him and how many people Siegel had killed. Kelley says that Sinatra and mobster Joseph Fischetti had been good friends from 1938 onward and acted like \"Sicilian brothers\". She also states that Sinatra and Hank Sanicola were financial partners with Mickey Cohen in the gossip magazine Hollywood Night Life. Sinatra sponsored the membership of John Roselli, a mobster, to the Friars Club.\nThe FBI kept records amounting to 2,403 pages on Sinatra, who was a natural target with his alleged Mafia ties, his ardent New Deal politics, and his friendship with John F. Kennedy. The FBI kept him under surveillance for almost five decades beginning in the 1940s. The documents include accounts of Sinatra as the target of death threats and extortion schemes. The FBI documented that Sinatra was losing esteem with the Mafia as he grew closer to President Kennedy, whose younger brother Attorney General Robert F. Kennedy was leading a crackdown on organized crime. Sinatra said he was not involved: \"Any report that I fraternized with goons or racketeers is a vicious lie.\"\nIn 1960, Sinatra bought a share in the Cal Neva Lodge & Casino, a casino hotel on the north shore of Lake Tahoe. He built the Celebrity Room theater, which attracted his show business friends Red Skelton, Marilyn Monroe, Victor Borge, Joe E. Lewis, Lucille Ball, Lena Horne, Juliet Prowse, the McGuire Sisters, and others. By 1962, Sinatra reportedly held a 50-percent share in the hotel. His gambling license was temporarily suspended by the Nevada Gaming Control Board in 1963 after Giancana was spotted on the premises. Due to ongoing pressure from the FBI and Nevada Gaming Commission on mobster control of casinos, Sinatra agreed to give up his share in Cal Neva and the Sands. That same year, his son Frank Jr. was kidnapped but was eventually released unharmed. Sinatra''s gambling license was restored in February 1981, following support from Ronald Reagan. In May 1968 he was observed dining at the Rive Gauche Restaurant with Allen Dorfman, I. Irving Davidson and Jimmy Hoffa''s wife Josephine.","Artistry":"Sinatra with Axel Stordahl at the Liederkrantz Hall in New York, c. 1947\nWhile Sinatra never learned how to read music well, he had a natural understanding of it, and Sinatra worked very hard from a young age to improve his abilities in all aspects of music. Sinatra could follow a lead sheet (simplified sheet music showing a song''s basic structure) during a performance by \"carefully following the patterns and groupings of notes arranged on the page\" and made his own notations to the music, using his ear to detect semitonal differences.\nGranata states that some of the most accomplished classically trained musicians soon noticed his musical understanding and remarked that Sinatra had a \"sixth sense\", which \"demonstrated unusual proficiency when it came to detecting incorrect notes and sounds within the orchestra.\"\nSinatra was an aficionado of classical music, and would often request classical strains in his music, inspired by composers such as Puccini and Impressionist masters. His personal favorite was Ralph Vaughan Williams. Sinatra would insist on always recording live with the band because it gave him a \"certain feeling\" to perform live surrounded by musicians. By the mid-1940s, such was Sinatra''s understanding of music that after hearing an air check of some compositions by Alec Wilder, which were for strings and woodwinds, he became the conductor at Columbia Records for six of Wilder''s compositions. The works were considered by Wilder to have been among the finest renditions and recordings of his compositions, past or present. Critic Gene Lees, a lyricist and the author of the words to the Jobim melody \"This Happy Madness\", expressed amazement when he heard Sinatra''s recording of it on Sinatra & Company (1971), considering him to have delivered the lyrics to perfection.\nVoice coach John Quinlan was impressed by Sinatra''s vocal range, remarking, \"He has far more voice than people think he has. He can vocalize to a B-flat on top in full voice, and he doesn''t need a mic either\". As a singer, early on, he was primarily influenced by Bing Crosby, but later believed that Tony Bennett was \"the best singer in the business.\" Bennett himself claimed that as a performer, Sinatra had \"perfected the art of intimacy.\" According to Nelson Riddle, Sinatra had a \"fairly rangy voice\", remarking: \"His voice has a very strident, insistent sound in the top register, a smooth lyrical sound in the middle register, and a very tender sound in the low. His voice is built on infinite taste, with an overall inflection of sex. He points everything he does from a sexual standpoint\".\nDespite his heavy New Jersey accent, when Sinatra sang, his accent was barely detectable; according to Richard Schuller, Sinatra''s diction became \"precise\" while singing and his articulation \"meticulous\". Sinatra''s timing was impeccable, allowing him, according to Granata, to \"toy with the rhythm of a melody, bringing tremendous excitement to his reading of a lyric.\" Tommy Dorsey observed that Sinatra would \"take a musical phrase and play it all the way through seemingly without breathing for eight, ten, maybe sixteen bars.\" Dorsey was a considerable influence on Sinatra''s techniques for his vocal phrasing with his own exceptional breath control on the trombone, and Sinatra regularly swam and held his breath underwater, thinking of song lyrics to increase his breathing power.\n\"He''d always been critical of his voice, and that only intensified as he got older. He never liked to discuss a performance afterward because he knew his voice wasn''t as good as it used to be. If someone told him he''d been great, he''d reply, ''It was a nice crowd, but my reed was off'' or ''I wasn''t so good on the third number.'' Strangely, in spite of his hearing problems, he had the most incredible ear, which often drove those he worked with nuts. There could be an orchestra of a hundred musicians, and if one played a bum note, he''d know exactly who was responsible.\"\n—Barbara Sinatra on Sinatra''s voice and musical understanding.\nAfter a period of performing, Sinatra tired of singing a certain set of songs and was always looking for talented new songwriters and composers to work with. Once he found ones he liked, Sinatra actively sought to work with them as often as possible and made friends with many of them. Over the years, he recorded 87 of Sammy Cahn''s songs, of which 24 were composed by Jule Styne and 43 by Jimmy Van Heusen. The Cahn-Styne partnership lasted from 1942 until 1954, when Van Heusen succeeded him as Sinatra''s main composer.\nUnlike many of his contemporaries, Sinatra insisted upon direct input regarding arrangements and tempos for his recordings. Sinatra would spend weeks thinking about the songs he wanted to record and would keep an arranger in mind for each song. Barbara Sinatra notes that Sinatra would almost always credit the songwriter at the end of each number and would often make comments to the audience, such as \"Isn''t that a pretty ballad\" or \"Don''t you think that''s the most marvelous love song\", delivered with \"childlike delight\". She states that after each show, Sinatra would be \"in a buoyant, electrically charged mood, a post-show high that would take him hours to come down from as he quietly relived every note of the performance he''d just given.\"\nSinatra''s split with Ava Gardner in the fall of 1953 had a profound impact on the types of songs he sang and on his voice. Sinatra began to console himself in songs with a \"brooding melancholy\", such as \"I''m a Fool to Want You\", \"Don''t Worry ''Bout Me\", \"My One and Only Love\" and \"There Will Never Be Another You\", which Riddle believed was the direct influence of Gardner.\nLahr comments that the new Sinatra was \"not the gentle boy balladeer of the forties. Fragility had gone from his voice, to be replaced by a virile adult''s sense of happiness and hurt\". Granata considered Sinatra a \"master of the art of recording\", noting that his work in the studio \"set him apart from other gifted vocalists.\" During his career, Sinatra made over 1,000 recordings. Recording sessions would typically last three hours. However, Sinatra would always prepare for them by spending at least an hour by the piano beforehand to vocalize, followed by a short rehearsal with the orchestra to ensure the balance of sound.\nIn the 1950s, Sinatra''s career was facilitated by developments in technology. Up to 16 songs could now be held by the 12-inch L.P., and this allowed Sinatra to use song in a novelistic way, turning each track into a kind of chapter, which built and counterpointed moods to illuminate a larger theme\". Santopietro writes that through the 1950s and well into the 1960s, \"Every Sinatra LP was a masterpiece of one sort of another, whether uptempo, torch song, or swingin'' affairs. Track after track, the brilliant concept albums redefined the nature of pop vocal art\".","Death And Funeral":"Sinatra''s grave, as seen in 2004, located at Desert Memorial Park in Cathedral City, California (gravestone replaced in 2021)\nDuring the final years of his life, Sinatra was in ill health and was frequently hospitalized for heart and breathing problems, high blood pressure, pneumonia, and bladder cancer. He made no public appearances following a heart attack in February 1997. On the evening of May 14, 1998, Sinatra died in his sleep at age 82 after suffering another heart attack at Cedars-Sinai Medical Center in Los Angeles, with his wife Barbara at his side. Barbara encouraged Sinatra to \"fight\" while attempts were made to stabilize him, and reported that Sinatra''s final words were, \"I''m losing.\" His daughter, Tina, later wrote that she and her siblings had not been notified of their father''s final hospitalization, and it was her belief that \"the omission was deliberate. Barbara would be the grieving widow alone at her husband''s side.\" The night after Sinatra''s death, the lights on the Empire State Building were turned blue, the lights at the Las Vegas Strip were dimmed, and the casinos stopped spinning for one minute. Significant increases in recording sales worldwide were reported by Billboard in the month of Sinatra''s death.\nSinatra''s funeral was held at the Church of the Good Shepherd in Beverly Hills, California, on May 20, 1998, with 400 mourners in attendance and thousands of fans outside. Gregory Peck, Tony Bennett, and Sinatra''s son, Frank Jr., addressed the mourners.\nSinatra was buried in a blue business suit; his grave, adorned with mementos from family members, was next to his parents in Desert Memorial Park in Cathedral City, California. The phrases \"The Best Is Yet to Come\", and \"Beloved Husband & Father\" were placed on Sinatra''s modest grave marker. Sinatra''s gravestone was changed as of 2021 to read \"Sleep Warm, Poppa\", due to damage to the original gravestone.","Legacy And Honors":"See also: List of awards and nominations received by Frank Sinatra\nFrank Sinatra Park on the Hudson River Waterfront Walkway, 4th of July, 2010\nRobert Christgau referred to Sinatra as \"the greatest singer of the 20th century\". His popularity is matched only by Elvis Presley, the Beatles, and Michael Jackson. For Santopietro, Sinatra was the \"greatest male pop singer in the history of America\", who amassed \"unprecedented power onscreen and off\", and \"seemed to exemplify the common man, an ethnic twentieth-century American male who reached the ''top of the heap'', yet never forgot his roots.\" Santopietro argues that his career was centered around power, perfecting the ability to capture an audience.\nGus Levene commented that Sinatra''s strength was that when it came to lyrics, telling a story musically, Sinatra displayed a \"genius\" ability and feeling, which with the \"rare combination of voice and showmanship\" made him the \"original singer\" which others who followed most tried to emulate. George Roberts, a trombonist in Sinatra''s band, remarked that Sinatra had a \"charisma, or whatever it is about him, that no one else had.\" Biographer Arnold Shaw considered that \"If Las Vegas had not existed, Sinatra could have invented it.\" He quoted reporter James Bacon in saying that Sinatra was the \"swinging image on which the town is built\", adding that no other entertainer quite \"embodied the glamour\" associated with Las Vegas. Sinatra is seen as one of the icons of the 20th century, and has three stars on the Hollywood Walk of Fame.\nIn Sinatra''s native Hoboken, he was awarded the Key to the City on October 30, 1947. In 2003, the city''s main post office was rededicated in his honor. A bronze plaque, placed two years before Sinatra''s death, marks the site of the house where he was born. There is also a marker in front of Hoboken Historical Museum, which has artifacts from his life and conducts Sinatra walking tours. Frank Sinatra Drive runs parallel to the Hudson River Waterfront Walkway. On the waterfront is Frank Sinatra Park, where a bronze plaque was placed in 1989 upon its opening. In the Frank Sinatra Park, a 6-foot (1.8 m) tall bronze statue of Sinatra was dedicated in 2021 on December 12, Sinatra''s birthday. A residence hall at Montclair State University in New Jersey was named in his honor. Other buildings named for Sinatra include the Frank Sinatra School of the Arts in Astoria, Queens, the Frank Sinatra International Student Center at Hebrew University in Jerusalem, and the Frank Sinatra Hall at the USC School of Cinematic Arts in Los Angeles. Wynn Resorts'' Encore Las Vegas resort features a restaurant dedicated to Sinatra which opened in 2008. There are several roadways named in honor of Frank Sinatra in several states of the U.S.\nMemorabilia from Sinatra’s life and career, including awards, gold records, and personal items, are displayed at USC’s Frank Sinatra Hall in Los Angeles and at the Sinatra restaurant at Encore at Wynn Las Vegas.\nSinatra''s three stars for recording, television, and motion pictures on the Hollywood Walk of Fame in Los Angeles\nThe United States Postal Service issued a stamp in honor of Sinatra in May 2008, commemorating the tenth anniversary of his death.\nIn May 2008, the United States Congress designated May 13 as Frank Sinatra Day.\nSinatra received three honorary degrees during his lifetime. In May 1976, he was invited to speak at the University of Nevada, Las Vegas graduation commencement and was bestowed an Honorary Doctorate litterarum humanarum. During his speech, Sinatra stated that his education had come from \"the school of hard knocks\" and that \"this is the first educational degree I have ever held in my hand. I will never forget what you have done for me today\". In 1984 and 1985, Sinatra received an Honorary Doctorate of Fine Arts from Loyola Marymount University and an Honorary Doctorate of Engineering from the Stevens Institute of Technology.\nIn 2023, Rolling Stone ranked Sinatra at No. 19 on their list of the 200 Greatest Singers of All Time.\nIn 2024, a new road in North Bristol was named Sinatra Way, to commemorate Sinatra''s 1953 visit to Frenchay Hospital.\nA Jazz Portrait of Frank Sinatra by Oscar Peterson (1959)\nVoices in Standard by The Four Freshmen (1994)\nAs I Remember It by Frank Sinatra, Jr. (1996)\nBlue Note Plays Sinatra various jazz musicians - (1996)\nManilow Sings Sinatra by Barry Manilow (1998)\nSinatraland by Patrick Williams and His Big Band (1998)\nBlue Eyes Plays Ol'' Blue Eyes by Si Zentner & Orchestra (1998)\nKeely Sings Sinatra by Keely Smith (2001)\nMichael Andrew Pays Tribute to Frank Sinatra by Michael Andrew (2002)\nSteve Lawrence Sings Sinatra by Steve Lawrence (2003)\nPlays Sinatra His Way by Joey DeFrancesco (2004)\nBlue Eyes Meets Bed-Stuy The Notorious B.I.G. & Frank Sinatra by Jon Moskowitz and Dj Cappel & Smitty (2005)\nBolton Swings Sinatra by Michael Bolton (2006)\nDear Mr. Sinatra by John Pizzarelli (2006)\nRay Stevens Sings Sinatra...Say What?? by Ray Stevens (2008)\nHis Way, Our Way by various artists (2009)\nCauby Sings Sinatra by Cauby Peixoto (2010)\nSin-Atra a heavy metal tribute by various artists (2011)\nCicero Sings Sinatra by Roger Cicero (2014)\nDaniel Boaventura Sings Frank Sinatra (Ao Vivo) (2015)\nLet''s Be Frank by Trisha Yearwood (2018)\nMark Tremonti Sings Frank Sinatra by Mark Tremonti (2022)\nLush Life: The Lost Sinatra Arrangements by Seth MacFarlane (2025)"}');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (339, '1WmIo9ORq1IDlovUWFmo4Y', 'Rodney', 'Whitaker', '3dd90705-1601-412e-9cbf-0b02a68643a4', 345719, 1, 'https://en.wikipedia.org/wiki/Rodney_Whitaker', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Rodney_Whittaker1.jpg/500px-Rodney_Whittaker1.jpg', 'Brian Callahan', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Rodney_Whittaker1.jpg', '{"Intro":"Rodney Whitaker (born February 22, 1968) is an American jazz double bass player and educator.","Biography":"Born in Detroit, Whitaker attended Wayne State University, and studied with Robert Gladstone, principal bass with the Detroit Symphony Orchestra, and trumpeter Marcus Belgrave.\nHe achieved recognition performing with Terence Blanchard''s Quintet and then with Roy Hargrove. His own first album Children of the Light was released in 1996.\nHis score for the film China, directed by Jeff Wray, was released on PBS in 2002.\nIn 2006, Whitaker was nominated for the Juno Award Traditional Jazz Album of the Year for Let Me Tell You About My Day, his album in collaboration with Phil Dwyer and Alan Jones. He has also been working with the pianist Junko Onishi.\nWhitaker is professor of jazz double bass and director of jazz studies at Michigan State University''s College of Music. He has presented master classes at such institutions as Duke University, Howard University, University of Iowa, University of Michigan, the New School (NY), Lincoln Center, and the Detroit International Jazz Festival, and at the conferences of the International Association for Jazz Education (IAJE). He has also worked with Detroit Symphony Orchestra to develop a jazz education department, and conducts their Civic Jazz Orchestra, as well as being on the faculties of University of Michigan and Juilliard School."}');
