	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1520, NULL, 'Stephanie Dorothea Mills', 'Stephanie Dorothea', 'Mills', NULL, 3682, 99, NULL, NULL, NULL, NULL, NULL, 'Stephanie Mills is an American Rhythm & Blues, Soul, Disco and Gospel singer and songwriter, born on March 22, 1957, in Brooklyn, New York, U.S. Mills began her career in 1966, when she received a role in the Broadway play Maggy Flynn. In 1973, Mills signed at [l=Paramount Records] by [a=Michael Barbiero], releasing her first single. Her role as Dorothy in "The Wiz" made her a star. She has been produced by [a=James Mtume & Reggie Lucas], [a=Ashford & Simpson], [a=George Duke], [a=Angela Winbush], [a=Gene Griffin], [a=Nick Martinelli], [a=Marc Gordon] and [a=Gerald Levert], [a=LeMel Humes], [a=Robert Brookins], [a=Paul Laurence], [a=Wayne Brathwaite], [a=Russell Simmons] etc. She has dueted with [a=Teddy Pendergrass] ("Two Hearts", 1981).');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1521, NULL, 'Walter José Wanderley Mendonça', 'Walter José Wanderley', 'Mendonça', NULL, 3747, 99, NULL, NULL, NULL, NULL, NULL, 'Walter Wanderley (May 12, 1932, Recife, Brazil - September 4, 1986, San Francisco, USA) was a Brazilian pianist, organist and arranger. He moved to São Paulo in 1947 where he reportedly learned to play organ with his aunt and also studied harmony at Lyceu de Artes. 
