	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1523, NULL, 'Eduardo de Góes Lobo', 'Eduardo de Góes', 'Lobo', NULL, 3783, 99, NULL, NULL, NULL, NULL, NULL, 'Eduardo de Góes "Edu" Lobo (born August 29, 1943) is a Brazilian bossa nova singer, guitarist, and composer. He achieved fame in the 1960s as part of the bossa nova movement. His compositions include Pra Dizer Adeus (with Torquato Neto), Choro Bandido (with Chico Buarque), Beatriz (with Chico Buarque), Arrastão (with Vinicius de Moraes), Upa Neguinho (with Gianfrancesco Guarnieri) and Ponteio (with Capinam).');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1524, NULL, 'Christian Fennesz', 'Christian', 'Fennesz', NULL, 3837, 99, NULL, NULL, NULL, NULL, NULL, 'Christian Fennesz (Vienna, Austria, 1962) started his career as the singer/guitarist/songwriter in the group [a=Maische], one of the more interesting bands to occupy the Viennese underground during the late eighties.');
