	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1526, NULL, 'Bobby Broom', 'Bobby', 'Broom', NULL, 4099, 99, NULL, NULL, NULL, NULL, NULL, 'Bobby Broom is an American jazz guitarist, born in Harlem, New York, on January 18, 1961. in the world today, touring with Steely Dan. Broom has performed as a side man with Art Blakey and The Jazz Messengers , Sonny Rollins, Kenny Burrell, Stanley Turrentine, Charles Earland, Miles Davis, and Dr. John, among others, as well as with his own groups. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1527, NULL, 'Arthur Henry Baker', 'Arthur Henry', 'Baker', NULL, 4158, 99, NULL, NULL, NULL, NULL, NULL, 'Highly influential American producer, remixer, DJ and musician (drummer, percussionist). Runs [l=Baked Recordings]. Born on April 22, 1955 in Boston, Massachusetts. He is best known for his work with artists such as [a=Afrika Bambaataa], [a=Planet Patrol] and the British group [a=New Order]. Baker began working as a DJ in Boston in the mid 1970s, where he played early disco and soul for the early Boston club scene alongside famed local DJs including John Luongo and Jimmy Stuard. He had little patience for DJing, saying in an interview: "[If] I didn''t get a good reaction on a record, I''d just rip it off, break it up and throw it on the dancefloor." In 1977 he turned to production with the Hearts Of Stone project, released on the Canadian Disco 1 label. He also was part of the group [a=North End] in Boston, releasing two well-regarded 12"s, respectively on West End and Emergency Records.
