	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1581, NULL, 'Douglas Carn', 'Douglas', 'Carn', NULL, 10587, 99, NULL, NULL, NULL, NULL, NULL, 'American jazz musician and producer, playing piano, organ, keyboards. Born on 1948-07-14 in St. Augustine, Florida (USA). Former husband of [a=Jean Carn] with whom he collaborated on a series of early 1970s albums at the [l=Black Jazz Records] label. Has worked with [a=Nat Adderley], [a=Earth, Wind & Fire], [a=Shirley Horn], [a=Lou Donaldson], [a=Stanley Turrentine], and [a=Irene Reid]. Later changed his name after converting to the Islam religion, becoming Abdul Rahim Ibrahim. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1582, NULL, 'Cándido Camero Guerra', 'Cándido Camero', 'Guerra', NULL, 10589, 99, NULL, NULL, NULL, NULL, NULL, 'Cuban-born percussionist (mainly conga and bongo) who backed many Afro-Cuban and straight-ahead jazz acts starting in the 1950s. Born April 22, 1921 in Regla (Havana), Cuba. Died November, 7, 2020 in New York, USA. He started his career as a percussionist for various groups in Havana, performing at the nightclubs and radio stations. He moved to New York in 1946 and started recording with [a=Machito] and [a=Dizzy Gillespie]. During 1953-1954 he was in the [a=Billy Taylor] quartet and in 1954 he performed and recorded with [a=Stan Kenton]. He also enjoyed some hits during the disco era, most notably with his cover of [a=Babatunde Olatunji]''s classic "Jingo", which he recorded for [l=Salsoul Records].
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1583, NULL, 'Eduardo Palmieri, Sr.', 'Eduardo Palmieri,', 'Sr.', NULL, 10590, 99, NULL, NULL, NULL, NULL, NULL, 'American pianist, band leader and musician in the Latin genre, Eddie is best known for his Latin-Jazz approach that includes extended Jazz influenced solos over Latin rhythms. Born December 15, 1936, in New York City to Corsican and Puerto Rican parents, Eddie (along with his late brother [a=Charlie Palmieri]) was one of the fundamental players in the evolution of Latin Jazz and Salsa. Died on August 6, 2025 in his house in New Jersey.');
