	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1607, NULL, 'Byron Wallen', 'Byron', 'Wallen', NULL, 13591, 99, NULL, NULL, NULL, NULL, NULL, 'UK trumpet player and composer');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1608, NULL, 'Luniz', 'Luniz', NULL, NULL, 13727, 99, NULL, NULL, NULL, NULL, NULL, 'Oakland rap duo Luniz, original named Luni Tunz, consisted of Yukmouth (Jerold Ellis III) and Numskull (Garrick Husbands), two friends who knew each other since junior high. The duo gained fame after six years together when they appeared on Dru Down''s Explicit Game album. Their debut album, Operation Stackola, was released in 1995 and knocked Michael Jackson''s HIStory off the top of Billboard Top R&B/Hip-Hop Albums chart on the strength of the Club Nouveau-sampling platinum hit single "I Got 5 on It," which featured guest vocals by Michael Marshall of Timex Social Club. The album''s lyrics took novel, comic approaches to sex, drugs, and everyday occurrences. Neither Lunitik Muzik (1997) nor Silver & Black (2002) fared as well, and they subsequently split. ');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1609, NULL, 'Boyd H. Jarvis', 'Boyd H.', 'Jarvis', NULL, 13808, 99, NULL, NULL, NULL, NULL, NULL, 'American producer, remixer and musician, born October 26, 1958, died February 16, 2018.');
