	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1611, NULL, 'Gordon Matthew Thomas Sumner', 'Gordon Matthew Thomas', 'Sumner', NULL, 13961, 99, NULL, NULL, NULL, NULL, NULL, 'British musician, singer, songwriter, composer, bassist, actor, author and activist, Sting was born in Wallsend, Tyne and Wear, North East England, 2 October 1951, before moving to London in 1977 to form [a7987] with [a=Stewart Copeland] and [a=Andy Summers]. The band released five studio albums, earned six Grammy Awards and two Brits, and was inducted into The Rock and Roll Hall of Fame in 2003.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1612, NULL, 'Lonnie Rashied Lynn Jr.', 'Lonnie Rashied Lynn', 'Jr.', NULL, 14014, 99, NULL, NULL, NULL, NULL, NULL, 'Lonnie Rashied Lynn Jr., known professionally as [a=Common], was born on March 13, 1972, in Chicago, Illinois. He is a hip-hop artist, actor, and activist who emerged in the early 1990s under the name Common Sense. His debut album, Can I Borrow a Dollar? (1992), introduced his signature style, and he gained critical recognition with Resurrection (1994). His lyricism and storytelling, often infused with social commentary, set him apart in the hip-hop landscape. Common became closely associated with [a=The Soulquarians], a collective of musicians including [a=J Dilla], [a=Questlove], and [a=D''Angelo], contributing to the neo-soul and alternative hip-hop movement. His experimental fifth album, Electric Circus (2002), received mixed reviews, but he rebounded with BE (2005), a project produced largely by [a=Kanye West] and [a=J Dilla], which was widely praised. He continued this success with Finding Forever (2007), again collaborating with Kanye West, will.i.am, and Devo Springsteen. Beyond music, Common has established a career in acting, appearing in films such as American Gangster (2007), Smokin’ Aces (2006), and Wanted (2008). He has since balanced his careers in music and film while also being an advocate for social justice, education, and community empowerment.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1613, NULL, 'Milton Hamilton', 'Milton', 'Hamilton', NULL, 14048, 99, NULL, NULL, NULL, NULL, NULL, 'Latin/Jazz/Funk pianist .
