	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1677, NULL, 'Paolo Scotti', 'Paolo', 'Scotti', NULL, 21130, 99, NULL, NULL, NULL, NULL, NULL, 'Label producer of [l=Mo''Smog Records], [l=Dejavu] and [l=Synthonic].');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1678, NULL, 'Hal Willner', 'Hal', 'Willner', NULL, 21149, 99, NULL, NULL, NULL, NULL, NULL, 'Hal Willner (b. April 6, 1956, Philadelphia PA; d. April 7, 2020, NYC) was an American music producer working in recording, films, TV and live events. He is best known for assembling tribute albums and events featuring a wide variety of artists and musical styles (jazz, classical, rock, Tin Pan Alley). His first tribute album was [m=229372] in 1981. Willner produced albums for Marianne Faithfull, Lou Reed, Bill Frisell, Steven Bernstein, William S. Burroughs, Gavin Friday, Lucinda Williams, and Laurie Anderson, among others. He also helped launch the career of Jeff Buckley.  He served as a music supervisor on two Robert Altman films, and was sketch music producer for Saturday Night Live for 40 years. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1679, NULL, 'Leon Ware', 'Leon', 'Ware', NULL, 21259, 99, NULL, NULL, NULL, NULL, NULL, 'Leon Ware (born February 16, 1940, Black Bottom, Detroit, Michigan, USA - died February 23, 2017, Marina del Rey, California, USA) was an American singer-songwriter, composer, pianist, keyboardist and record producer.');
