	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1681, NULL, 'Ethel “Beatty” Barnes', 'Ethel “Beatty”', 'Barnes', NULL, 21268, 99, NULL, NULL, NULL, NULL, NULL, 'Ethel “Beatty” Barnes made her singing debut in the famous Convent Avenue Baptist Church in New York City at the age of three. Ethel is a graduate of C. W. Post, Long Island University, where she obtained her B.A. Degree in Music Education, specializing in Vocal Technique and Performance. Ethel has sung in distinguished places, nationally and internationally. Ethel has been a featured performer in various Broadway and off-Broadway shows such as "The Prodigal Sister", "Bingo Long", "Blues in the Night", "Sugar Hill", "Bubbling Brown Sugar", "Eubie!", "Dreamgirls", and ''''Showboat". Her movie credits include "The Cotton Club" and "Garbo Talks". Ethel has also recorded for numerous other artists including George Benson, Billy Ocean, Jonathan Butler, Joe Kurasz, Tyrone Brunson, The Reddings and Louis St. Louis. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1682, NULL, 'Douglas Arthur Wimbish', 'Douglas Arthur', 'Wimbish', NULL, 21658, 99, NULL, NULL, NULL, NULL, NULL, 'American bass guitarist and producer, born on September 22nd 1956 in Hartford, Connecticut, USA. Best known for his work with [a=Living Colour] (which Doug became a permanent member of during June 1992). Wimbish is also recognised in the New York City scene for his many collaborations with drummer [a=Keith LeBlanc] and guitarist [a=Skip McDonald] (real name [a=Bernard Alexander]), first in [a=Wood, Brass & Steel], and then from 1979 onwards in the [a=Sugarhill Gang Band] (the house band for [l=Sugar Hill Records]). Later Doug contributed to various [l=On-U Sound] projects such as [a=Fats Comet] and [a=Tackhead] (to name but two).');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1683, NULL, 'John Chantler', 'John', 'Chantler', NULL, 22292, 99, NULL, NULL, NULL, NULL, NULL, 'John Chantler is a musician and organiser living in Stockholm, Sweden working with synthesizers, electronics and pipe organs. 
