	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1691, NULL, 'Stephen Michael Reich', 'Stephen Michael', 'Reich', NULL, 22946, 99, NULL, NULL, NULL, NULL, NULL, 'American composer, born October 3, 1936, in New York City. He studied composition privately with Hall Overton, then moved on to Juilliard School in New-York to study with William Bergsma and Vincent Persichetti (1958 to 1961). Subsequently he attended Mills College in Oakland where he was taught by Luciano Berio and Darius Milhaud (1961-63) and earned a master''s degree in composition.
