	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1703, NULL, 'Paul Adrian Pond', 'Paul Adrian', 'Pond', NULL, 24223, 99, NULL, NULL, NULL, NULL, NULL, 'British singer and harmonica player born on February 24, 1942 in Portsmouth, Hampshire, England. Until 1966 he was the singer of [a=Manfred Mann]. Paul Jones has also recorded as a harmonica player regularly, and is President of the The National Harmonica League. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1704, NULL, 'Michelle Antoinette Wallen', 'Michelle Antoinette', 'Wallen', NULL, 25262, 99, NULL, NULL, NULL, NULL, NULL, 'Mica Paris (born April 27, 1969 in Islington, London, England) has been one of the most celebrated artists in the UK soul scene ever since she burst onto the scene with her international hit "My One Temptation," making fans (and later collaborators out of) giants in the music industry like [a=Eric B. & Rakim], [a=Nile Rodgers] and [a=Prince], to name a few.  Her career as a vocalist began when she started singing in her church when she was seven years old. Paris changed her name from Michelle to Micha at age 16 and later dropped the ''h'' in Micha, going by Mica ever since.  The change in name coincided with Mica''s signing on as a member in the gospel group Spirit Of Watts and by the mid 1980''s arrived, she was doing background vocal work for secular groups such as [a=Shakatak] and [a=Hollywood Beyond].  In the years since has continued to expand her talents to include production and songwriting and was recently involved in the BBC Radio 2 series "Soul Solutions" and a brief stint on BBC1 show “Eastenders” in 2020.
