	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1752, NULL, 'Nona Bernis Hendryx', 'Nona Bernis', 'Hendryx', NULL, 30092, 99, NULL, NULL, NULL, NULL, NULL, 'American singer born on October 9, 1944, in Trenton, New Jersey. Hendryx got her start recording in 1962 with [a=Patti LaBelle], [a=Sarah Dash] and [a=Cindy Birdsong] in the vocalgroup [a=Patti LaBelle And The Bluebells]. When Birdsong left for [a=Supremes] the other three members changed the group''s name to [a=LaBelle], transforming themselves into futuristic disco-funk divas. Nona Hendryx wrote a number of songs for the band before their breakup in 1976 and she went on to pursue a solo career with her self-titled debut album the next year. She has worked with such diverse collaborators as [a=Prince], [a=Laura Nyro], [a=Allen Toussaint], [a=Talking Heads], [a=Bill Laswell], and [a=Bootsy Collins] and many others.');
