	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1756, NULL, 'Michael Henry', 'Michael', 'Henry', NULL, 30277, 99, NULL, NULL, NULL, NULL, NULL, 'U.K. Hip Hop pioneer hailing from Battersea south London. Active since the early 80''s he was known then more for his popping skills than rapping ability and went under the tag of Moomin, being a member of various crews such as The 52 Flash Kru, the SAS (Strawberry all-stars) and Truly Unique back then. Started MC''ing in the mid 80''s and was part of the No Parking MC''s. The first release in 1988 was alongside sparring partners [a=Monie Love], [a=DJ Pogo] and [a=Sparki] under the name of The [a=Jus Badd] crew. MC Mell''o went on as a solo artist and after his debut "Comin'' Correct" on Republic Records he released the critically acclaimed debut "Thoughts Released"  on the same label in 1990. Having recorded his second album entitled "Thoughts Unleashed" Mell''O never found the right label to release it and it remains unreleased until today. Only one of the tracks got a release decades later.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (1757, NULL, 'Alex Sadkin', 'Alex', 'Sadkin', NULL, 30415, 99, NULL, NULL, NULL, NULL, NULL, 'Alex Sadkin was an American record producer, mixer and mastering engineer born April 9, 1949 in Fort Lauderdale, Florida, USA.First trained as a mastering engineer, he became an assistant engineer in 1975 at [l269412] in Miami. When [a30414], founder and owner of [l8377], in 1977 built the [l264020] in Nassau, Bahamas, Sadkin became head engineer (director) from the start, producing rock, reggae and new wave. He died in a motor bike accident 25 July 1987 in Nassau.');
