	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (2116, NULL, 'Alton Glenn Miller', 'Alton Glenn', 'Miller', NULL, 77991, 99, NULL, NULL, NULL, NULL, NULL, 'American swing trombonist, arranger, composer, and bandleader. Born 1 March 1904 in Clarinda, Iowa. Started orchestra in 1938. Best-selling recording artist from 1939 to 1943, leading best known and beloved swing band. Worked as sideman early in career. Wrote and/or arranged popular swing songs. Disbanded orchestra in 1942 to leave for Army. Too old to be drafted, created a band. Transferred to Army Air Force and raised morale for hundreds of thousands of troops before disappearing on christmas 1944 on a flight from England to France. Internationally mourned as a war hero. Last seen on December 15, 1944.
