	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (2124, NULL, 'Carlos Humberto Santana Barragán', 'Carlos Humberto Santana', 'Barragán', NULL, 79340, 99, NULL, NULL, NULL, NULL, NULL, 'Mexican and American guitarist, composer and singer. Born on 20 July 1947 in Autlán de Navarro, Jalisco, Mexico. Brother of [a501051] and uncle of [a188278]. A veteran guitarist, Santana is noted for his distinctive Tijuana jazz-influenced playing style. Born in Mexico, but resident in the USA from childhood, he has been the leader of the group [a=Santana] since 1966. After the breakup of this original group, which was filmed at the Woodstock Festival in August 1969, he worked and recorded with drummer [a=Buddy Miles]. Carlos then formed a duo with [a=John McLaughlin], becoming a follower of guru Sri Chinmoy who countenanced them the titles Devadip (the eye, the lamp, the light of God) and Mahavishnu respectively. This duo recorded the Love Devotion Surrender album. ''Devadip'' Carlos Santana then worked with another religious disciple, [a4205], widow of [a=John Coltrane]. He ended his relationship with Chinmoy followers in 1982.
