	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (2244, NULL, 'Johann Sebastian Bach', 'Johann Sebastian', 'Bach', NULL, 95537, 99, NULL, NULL, NULL, NULL, NULL, 'Johann Sebastian Bach was born on March 21, 1685 in Eisenach, Thuringia, Germany. A prolific German composer and organist, his sacred and secular works for choir, orchestra and solo instruments drew together the strands of the baroque genre and brought it to its ultimate maturity. Although he introduced no new forms, he enriched the prevailing German style with a robust contrapuntal technique, a control of harmonic and motivic organisation from the smallest to the largest scales, and the adaptation of rhythms and textures from abroad, particularly Italy and France. Many people consider him to be the greatest Baroque composer, and one of the greatest composers of all time. From 1723 until his death he was Thomascantor at Leipzig.
