	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3090, NULL, 'Eric Alexander', 'Eric', 'Alexander', NULL, 212816, 99, NULL, NULL, NULL, NULL, NULL, 'American saxophonist, born 4 August 1968 in Galesburg, Illinois, USA');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3091, NULL, 'David Dunn', 'David', 'Dunn', NULL, 213207, 99, NULL, NULL, NULL, NULL, NULL, 'Composer and sound artist David Dunn was born in 1953 in San Diego (California, USA). From 1970 to 1974 he was assistant to the American composer Harry Partch and remained active as a performer in the Harry Partch Ensemble for over a decade. He has worked in a wide variety of audio media inclusive of traditional and experimental music, installations for public exhibitions, video and film soundtracks, radio broadcasts, and bioacoustic research. His compositions and wildlife sound recordings have appeared in hundreds of international forums, concerts, broadcasts, and exhibitions. He was director of the Electronic Music Studio at San Diego State University and has taught and lectured at numerous schools and universities. From 1984 to 1988 he was Vice-President of International Synergy Institute, a media think tank centered in Hollywood, California. In 1989 he co-founded the Independent Media Labs in Santa Fe, New Mexico. Currently he is a Professor in the College of Santa Fe''s Contemporary Music Program and President of the Art and Science Laboratory in Santa Fe. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3092, NULL, 'Douglas Clare Fischer', 'Douglas Clare', 'Fischer', NULL, 213242, 99, NULL, NULL, NULL, NULL, NULL, '[b]Clare Fischer[/b] (22 October 1928, Durand, Michigan — 26 January 2012, Los Angeles, California) was an American jazz composer, arranger, bandleader, keyboardist, and multi-instrumentalist. He was the younger brother of [url=https://discogs.com/artist/2332672]Stewart "Dirk" Fischer[/url] (1924—2014), uncle of [url=https://discogs.com/artist/284968]André Fischer[/url] (b. 1948), and father of [a436604] (b. 1964), with whom Clare extensively collaborated. With a career spanning over five decades, Fischer came to prominence in the early 1960s with seminal albums in Afro-Cuban jazz, salsa, and bossa nova genres, and wrote two standards, [i]Pensativa[/i] and [i][url=https://discogs.com/master/527830]Morning[/url][/i]. Since the 1970s, Clare Fischer was a sought-after session musician and arranger, collaborating with [a=Prince], [a=João Gilberto], [a=Paul McCartney], [a19298], [a=Robert Palmer], [a=Paula Abdul], [a=Natalie Cole], [a=Branford Marsalis], and [a=Michael Jackson].
