	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3236, NULL, 'Martha Rose Reeves', 'Martha Rose', 'Reeves', NULL, 229726, 99, NULL, NULL, NULL, NULL, NULL, 'American singer born on July 18, 1941 in Eufaula, Alabama.  Together with The Vandellas she had classic hits in the first half of the 1960''s.
