	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3398, NULL, 'Marlon Lamont McClain', 'Marlon Lamont', 'McClain', NULL, 250628, 99, NULL, NULL, NULL, NULL, NULL, 'Marlon McClain began his career in 1972 as the leader and guitarist of the Funk/Rock/R&B/Jazz group Pleasure, which was a horn driven band with jazz overtones that accentuated their funk/soul foundation. In 1981 Marlon McClain released his solo album "Changes" which included special guests Jeff Lorber, Randy Jackson and Steve Smith. During the same time period Marlon formed Mac Man Music Inc with his manager David Leiken. Through Mac Man Music, Marlon produced and wrote songs with upcoming artists from the Northwest, including Shock, Jeff Lorber Fusion, Nu Shooz, and Kenny G. From 1985 to 2001, Marlon became the guitarist for the Dazz Band, contributing as a writer and producer to the "Hot Spot", "Wild & Free", "Rock the Room" and "Time Traveler" albums. His association with the leader of the band Bobby Harris led to the formation of Major Hits Records'' their greatest success, which was the # 1 UAC song "Without You" released in 2000 recorded by Charlie Wilson. As a songwriter Marlon has written songs for artists like Tower of Power, En Vogue, Gerald Albright, Curtis Salgado, Eric Benet and George Benson.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3399, NULL, 'William Roscoe Mercer', 'William Roscoe', 'Mercer', NULL, 250691, 99, NULL, NULL, NULL, NULL, NULL, 'William Roscoe Mercer (1927-2000), better known to millions of radio listeners simply as Rosko, was an American news announcer and disc jockey. He is best known for his stints on New York''s WOR-FM and WNEW-FM in the 1960s. Rosko and other DJs of the time pioneered alternative-format FM radio, in response to the restrictive playlist programming of Top 40 AM stations.
