	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3581, NULL, 'Alan Broadbent', 'Alan', 'Broadbent', NULL, 253206, 99, NULL, NULL, NULL, NULL, NULL, 'Alan Broadbent, MNZM [Member - New Zealand Order of Merit] was born on April 23, 1947 in Auckland, New Zealand. He is a jazz pianist, arranger and composer best known for his work with artists such as Woody Herman, Diane Schuur, Chet Baker, Irene Kral, Sheila Jordan, Charlie Haden, Warne Marsh, Bud Shank, and many others. He studied piano and music theory in his own country, but in the 1960s came to the US to study at the Berklee College of Music. In the 1970s he did both classical and jazz work, but from the eighties onwards he accompanied singers on piano. Later he gained note as an arranger of music and won two Grammies for arrangements he did with Natalie Cole and Shirley Horn.');
