	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (3961, NULL, 'Mauricio Smith', 'Mauricio', 'Smith', NULL, 258368, 99, NULL, NULL, NULL, NULL, NULL, 'Mauricio Smith (11 July, 1931, Colón, Panamá - 3 August, 2002, Brooklyn, New York City) saxophone and flute player, called also "Señor Saxofón", was a giant of Latin music, a genius whose work helped the development of many of the great names that we know internationally today in salsa and Latin jazz. And Mauricio, in addition to being a renowned flutist, is also an arranger par excellence. He is one of the few Panamanian musicians who settled in New York and were able to get ahead in both the world of Latin and non-Latin music, thanks to his wisdom and talent. Smith was not only supremely talented with the flute; his skill with all types of saxophones has also been in high demand. According to Smith himself, his talent extends to knowing how to play piccolo, clarinet, harmonica (chromatic and blues), classical guitar, bass (upright and fender), vibraphone and Latin percussion.
