	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (4336, NULL, 'Laurie Allan', 'Laurie', 'Allan', NULL, 266837, 99, NULL, NULL, NULL, NULL, NULL, 'Laurie Allan (born 19 February 1943, London) is an English drummer, best known for stints in Delivery and Gong. He has also played with Robert Wyatt, for example on his albums Rock Bottom and Ruth Is Stranger Than Richard.Allan started drumming when he was 12. His professional career got going in the early 1960s. In 1967 he recorded with Chris McGregor, Dudu Pukwana and others on Gwigwi Mrwebi''s Mbaqanga Songs. By 1968, he was in the Gunter Hampel trio with John McLaughlin when he met Daevid Allen. He played with Gunter Hampel at the 1968 International Essen Song Day, alongside Bruno Besse (Guitar), Freddy Gosseye (Bass) Simon Prestvitch (Fluid Lights) and Raoul Kroes (Techn.). He played in Formerly Fat Harry in 1970.In 1971, Allan joined Delivery with British keyboardist Steve Miller, replacing Pip Pyle who went on to join Gong. In 1972, Allan then joined Gong, again replacing Pyle. Allan left Gong in 1973 to join a new Delivery line-up, but this was short-lived and soon broke up; Allan did appear on Miller and Lol Coxhill''s The Story So Far/Oh Really? album (1974). He provided drums and percussion on Ralph McTell''s album Not till Tomorrow (1972) and Bert Jansch''s album Moonshine (1973).Allan re-joined Gong briefly in 1974 and maintained a connection with the band for some year afterwards, including working with Mother Gong in 1978. He played with Barbara Thompson''s Paraphernalia (1974–75). Allan also worked with Peter Lemer in the 1970s, but he largely left performing in the 1980s.');
