	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (5012, NULL, 'Jim Anderson', 'Jim', 'Anderson', NULL, 282077, 99, NULL, NULL, NULL, NULL, NULL, 'Jim Anderson is an internationally recognized recording engineer and producer of acoustic music for the recording, radio, television, and film industries. He is the recipient of numerous awards and nominations in the recording industry: his recordings have received thirteen Grammy awards and 29 Grammy nominations; his radio recordings have received two George Foster Peabody Awards and there have been two Emmy nominations for television programs. His 5.1 surround remix of Patricia Barber''s album "Modern Cool" won the Grammy for Best Surround Recording at the 55th Grammys and his 5.1 surround recording of Jane Ira Bloom''s "Sixteen Sunsets" was nominated for a Grammy at the 56th Grammys. Jim''s 5.1 mix of Jane Ira Bloom''s "Early American''s" won the Grammy for Best Surround Recording at the 60th Grammys. His recording of Gisle Kverndokk''s "Symphonic Dances" was nominated for a best Immersive Album Grammy in 2020. Jim''s recording "Clique" was nominated for a Grammy in the Best Immersive Album category in 2022 and he was also nominated in the Immersive category in 2023 for Jane Ira Bloom''s "Picturing the Invisible - focus 1." He is Professor Emeritus at NYU''s Clive Davis Institute of Recorded Music.');
