	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (5016, NULL, 'National Philharmonic Orchestra', 'National Philharmonic', 'Orchestra', NULL, 282137, 99, NULL, NULL, NULL, NULL, NULL, 'The National Philharmonic Orchestra was a British orchestra formed in 1964 to be used solely for recording purposes.  The orchestra was formed by [a=Charles Gerhardt], a producer at [l=RCA Records] and [a=Sidney Sax] partially to fill the need of [l=Reader''s Digest]. Before settling on the name in 1970 they went by a variety of other names including the [a=RCA Symphony Orchestra] and [a=The London Promenade Orchestra]. The orchestra had a variety of musicians and conductors over its lifetime and was used quite often for the soundtracks of films. The orchestra is no longer together.
