	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (5023, NULL, 'Jason Kao Hwang', 'Jason Kao', 'Hwang', NULL, 282229, 99, NULL, NULL, NULL, NULL, NULL, 'Jason Kao Hwang is a composer, violinist and educator, has created works ranging from jazz, classical, “new” and world music. Asian Improv Records recently released EDGE, Mr. Hwang''s new jazz quartet, featuring Taylo Ho Bynum(cornet), Andrew Drury(perc). Ken Filiano (bass). His chamber opera, The Floating Box, A Story in Chinatown (New World Records), was named one of the top ten opera recordings of 2005 by Opera News. Mr. Hwang''s seminal ensemble (1990-2004), The Far East Side Band, released two CDs, Urban Archaeology (Victo Records) and Caverns (New World Records). As violinist, he has worked with Anthony Braxton, Henry Threadgill, Butch Morris, Reggie Workman, Vladamir Tarasov, Tatsu Aoki, Frances Wong, and William Parker. Mr. Hwang currently performs with William Hooker''s The Gift and Pheeroan Aklaff''s Malcheck Muzikum. Mr. Hwang has received support from Meet the Composer, National Endowment for the Arts, New York State Council on the Arts, New Jersey State Council on the Arts, Rockefeller Foundation, the Mary Flagler Cary Charitable Trust and others.');
