	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6172, NULL, 'Benny Goodman Trio', 'Benny Goodman', 'Trio', NULL, 311733, 99, NULL, NULL, NULL, NULL, NULL, 'The Benny Goodman Trio created a style of ''chamber jazz'' that emphasized highly developed ensemble playing and technically brilliant solos. The Trio took the ensemble sound of the small jazz band to a new level of precision and excitement that attracted a new audience to jazz. In July 1935, after playing together in a jam session, Goodman asked Teddy Wilson to record with Krupa and himself. That summer, as the Benny Goodman Trio, they recorded four classic sides of jazz chamber music. Vibraphonist Lionel Hampton and guitarist Charlie Christian later joined Goodman to form quartets and sextets.');
