	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6185, NULL, 'Melba Doretta Liston', 'Melba Doretta', 'Liston', NULL, 311952, 99, NULL, NULL, NULL, NULL, NULL, '  American trombonist & arranger. Melba''s professional career started on the legendary Central Avenue, where she became the first woman wind-instrumentalist in the Lincoln Theater pit orchestra conducted by Bardu Ali. From the 1940s through the 1960s, she was the first woman trombonist to work in the leading big bands of Dizzy Gillespie, Count Basie, Duke Ellington, Quincy Jones, Gerald Wilson, and Clark Terry.  Melba went into performance retirement and moved to Jamaica from 1973 to 1979, where she first taught at the University of the West Indies and then became director of Popular Music Studies at the Jamaica Institute of Music in Kingston.  She was forced to give up playing in 1985 after a stroke left her partially paralyzed, but she continued to arrange music with Randy Weston, contributing her imaginative, often strikingly dramatic arrangements to a succession of his albums in the 90s. She was afflicted by a further series of strokes, which eventually proved fatal. 
