	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6525, NULL, 'John Franklin Blair', 'John Franklin', 'Blair', NULL, 315733, 99, NULL, NULL, NULL, NULL, NULL, 'John Franklin "Ellington" Blair was an American violinist & guitarist, born November 8h 1943 Toledo, Ohio, died June 3rd 2006 in New York, NY, USA. Dr. John Blair (or Master John Blair) grew up in California and began taking violin lessons as a child, graduating with honors from Lincoln High School in San Diego in 1961. Blair became a heavy academic, holding degrees from Eastman and Curtis conservatories. He even founded a school (The Universal Natural System). He is best known as the inventor of the Vitar, an acoustic combination of violin and guitar. He featured on many jazz funk LPs in the early 1970s and released a few sought after psych-funk releases on Mercury, Columbia and CTI. During the 1980s he disapeared off of the map, never to return. He died of heart failure, homeless.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6526, NULL, 'Hans Wendl', 'Hans', 'Wendl', NULL, 315782, 99, NULL, NULL, NULL, NULL, NULL, 'Producer.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6527, NULL, 'Zimbo Trio', 'Zimbo', 'Trio', NULL, 315784, 99, NULL, NULL, NULL, NULL, NULL, 'The Zimbo Trio is a Brazilian instrumental ensemble established in 1964 in São Paulo, originally comprised by Amilton Godoy (piano), Luís Chaves (bass) and Rubinho Barsotti (drums). The trio was one of the most influential groups of Brazilian music in the second half of the 20th century. An exponent of the paulista current of Bossa Nova, they have relied heavily on Godoy’s academic-schooled, brilliant playing style. After their debut in 1965, the trio traveled extensively throughout the Americas and Europe. In 1965 they were appointed as permanent performers in the TV''s station Record program, Fino da Bossa, presented by Elis Regina and Jair Rodrigues, dedicated to the fostering of novel musical talents.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6528, NULL, 'Rubens Alberto Barsotti', 'Rubens Alberto', 'Barsotti', NULL, 315785, 99, NULL, NULL, NULL, NULL, NULL, 'Brazilian producer and drummer, born in 16 October 1932 and passed away in 15 April 2020 in São Paulo, SP, Brazil');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6529, NULL, 'Arnaldo DeSouteiro', 'Arnaldo', 'DeSouteiro', NULL, 315788, 99, NULL, NULL, NULL, NULL, NULL, 'Los Angeles-based Brazilian record producer, Arnaldo DeSouteiro is the founder and CEO of the [l=JSR] (Jazz Station Records) label, a division of Jazz Station Marketing & Consulting, located in LA, California. Influenced by [a=Creed Taylor], [a=Rudy Van Gelder] and [a=Tommy LiPuma], he is also a journalist, publicist, arranger, composer, percussionist, radio DJ, sound engineer, educator, Member of IAJE, JJA (Jazz Journalists Association), LAJS (Los Angeles Jazz Society), AIM, ABI, and Voting Member of NARAS-GRAMMY. Arnaldo DeSouteiro has produced over 350 albums and sessions featuring such artists as [a=Luiz Bonfa], [a=João Gilberto], [a=Dom Um Romao], [a=Ithamara Koorax], [a=Thiago De Mello], [a=Dexter Payne], [a=João Donato], [a=Palmyra & Levita], [a=Mario Castro Neves], [a=David Sanborn], [a=Luiz Millan], [a=Mark Egan], Jorge Pescara, Paula Faour, Fabio Fonseca, [a=Claudio Roditi], Anna Ly, Carlos Barbosa-Lima, Pascoal Meirelles, Yana Purim, [a=Carlos Pingarilho], Nelson Angelo, [a=Marcelo Salazar], [a=Ron Carter], [a=Antonio Carlos Jobim], [a=Steve Swallow], [a=Herbie Hancock], [a=Hugo Fattoruso], [a=Larry Coryell], Sadao Watanabe, Jurgen Friedrich, Eloir De Moraes, Gazzara, [a=Eumir Deodato], Jadir de Castro, Azymuth, Marcio Montarroyos, Sivuca, Laudir de Oliveira, Marcos Valle, Jay Berliner, George Young, [a=David Matthews], Lew Soloff, Alphonso Johnson, [a=Gene Bertoncini], John McLaughlin, [a=Claus Ogerman], Raul de Souza, Gonzalo Rubalcaba and many others. Besides his work for JSR, DeSouteiro has produced many reissues, compilations and new projects for [l=Verve], [l=Milestone Records], [l=Fantasy Records], [l=CTI Records], [l=Kudu], Sony, [l=Sonet], JVC, Huks, Motema, Warner, RCA, BMG, [l=Paddle Wheel], [l=Rambling Records] and other labels. He is married to actress Lisa Marie.');
