	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6541, NULL, 'James Muller', 'James', 'Muller', NULL, 316446, 99, NULL, NULL, NULL, NULL, NULL, 'Australian guitarist James Muller was born in Adelaide in 1974. He became interested in music at an early age and began playing the guitar at the age of 12. Initially inspired by rock music of the sixties and seventies, a love of jazz took over by age 16. Two years later James was gigging with clarinetist/saxophonist Andrew Firth with whom he stayed for two years. After working with the cream of Adelaide’s jazz and rock musicians James relocated to Sydney in 1996, where he quickly became one of the most in-demand guitarists in the country. He played and recorded with Vince Jones, James Morrison, Dale Barlow, Mike Nock, Renee Geyer, Bernie McGann, Don Burrows, Mark Isaacs, Sean Wayland, Katie Noonan, Rai Thistlethwayte, Steve Hunter and Scott Tinkler,  as well as international artists including Chad Wackerman, Vinnie Colaiuta, Tim Ries, Christian McBride, and John Scofield. He returned to Adelaide and now plays with The Airbenders as well as teaching guitar at the Elder Conservatorium. He has also performed with the James Muller Quartet and as a guest with The New Cabal, Hindley Street Country Club.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6542, NULL, 'Dean Rudland', 'Dean', 'Rudland', NULL, 316490, 99, NULL, NULL, NULL, NULL, NULL, 'British label owner, A&R, publisher and DJ who''s frequently credited on compilations of soul, jazz, and funk. Rudland was part of the original management team at the [l=Acid Jazz] label in the early 1990s, and is today co-owner of the Acid Jazz Label Group. He went to become one of the most respected catalogue A&R men in the world, compiling the million selling Blue Break Beats Series for Blue Note, relaunching Stateside Records for EMI, and running the reissue programme for Fania Records, before becoming head of [l7305] for UK label [l=Ace], where he''s a staff member & music consultant.
