	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (6599, NULL, 'Red Nichols And His Five Pennies', 'Red Nichols And His Five', 'Pennies', NULL, 317885, 99, NULL, NULL, NULL, NULL, NULL, 'Red Nichols and his Five Pennies were one of the most popular bands of the New York Jazz scene of the 1920s. They recorded under a variety of different names, including the Arkansas Travelers, [a=The Red Heads], the [a=Louisiana Rhythm Kings], [a=The Charleston Chasers], [a=The Six Hottentots], The Hottentots and Miff Mole and his Little Molers. The band''s style was often called "Chamber Jazz" by critics and for what it lacked in hot intensity it made up for with a cool somewhat detached, yet urban and sophisticated sound. In 1959 Hollywood made a highly fictionalized movie about the band called "The Five Pennies", starring Danny Kaye as Red Nichols. ');
