	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (7145, NULL, 'Dr. Zakarya Diouf', 'Dr. Zakarya', 'Diouf', NULL, 327263, 99, NULL, NULL, NULL, NULL, NULL, 'Percussionist, and vocalist Dr. “Papa” Zakarya Diouf met [a1112168] at the First World Festival of Negro Arts, in Dakar in 1966 and agreed to join Ms. Dunham in establishing her performing arts institute associated with Southern Illinois University in in East St. Louis. This also became an opportunity to earn his first Ph.D. in biochemistry at the University of Chicago. A second doctorate in ethnomusicology was earned at UC Berkeley in later years.  Before Zak immigrated in 1969, he had a distinguished career as the artistic director of multiple national ballet companies: Les Ballet Africaines of Guinea (1963), National Ballet of Senegal (1964-68), and prior to these distinguished companies, he lead the Mali Dance Ensemble, comprised of artists from Mali, Senegal and Guinea. Once in the United States Dr. Diouf would found and direct the Diamano Coura West African Dance Company.  He received his Ph.D. in Ethnomusicology from U.C. Berkeley and was director of the Mali Ensemble, a multinational company representing the unity of the West African countries of Mali, Senegal, and Guinea.  He became director of “Les Ballet Africaines” in 1963 and later Le Ballet National du Sénégal from 1964-1968.  In 1969, he joined the faculty of Southern Illinois University, working with Ms. Katherine Dunham.  Dr. Diouf has taught at San Jose University, Sonoma State University, the University of San Diego, the University of California of Los Angeles and San Francisco, and California State University-East Bay.  Dr. Diouf currently teaches West African music, dance, and history at Laney Community College in Oakland.  He did extensive research into African music and dance along with choreographing some of the best dance and dramatic pieces for renowned companies including the San Francisco Ballet.  In 2005, along with the Honorable Ron V. Dellums, Dr. Diouf was honored with the Community Leadership Award by the San Francisco Foundation for his vision in unifying the African cultural arts community, for serving as a mentor and educator of young artists, and for his artistic contributions to the development of African-based performing arts. On June 22, 2013 he received  the Malonga Casquelourd Lifetime Achievement Award from the San Francisco Ethnic Dance Festival.​​  Dr. Diouf passed away October 9, 2021.');
