	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (8190, NULL, 'Commissioned', 'Commissioned', NULL, NULL, 350132, 99, NULL, NULL, NULL, NULL, NULL, 'Commissioned was an American, Urban Contemporary Gospel group founded in 1982. The six original members were [a178299], [a1119122], [a452651], [a3783884], [a1887224], and [a1008356]. Their music was very R&B with an occasional rock edge, because of this a lot of churches were hesitant to book them. However, Mattie Moss Clark was not afraid. She booked the group to perform at a COGIC annual convention and it gave them a needed boost. They all held day jobs while working on their debut album [m=3742158]. Within a matter of months they were all able to quit their day jobs due to their popularity. Aside from the edge in their musical style, they mixed their vocals high instead of burying them below the music as most groups did at the time. This was revolutionary and gave a fuller sound to their music. In 1991 Staten and Brooks left the group and were replaced by [a1196820], [a778806], and [a361142]. In 1994, Fred Hammond and Michael Williams made their final contributions to the group on the Top Ten album [m=1641301]. [a347091] joined the group in 1996. Around 1999-2000 Marvin Sapp left the group and two new members Chris Poole and Marcus Cole joined on their last studio release [m=1586279]. In 2002 all of the original members came together for a sold-out national concert tour and released [m=2598074] a 2 disc set and a DVD which sold more than 100,000 copies. They have now retired the name but the sound lives on.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (8191, NULL, 'Tramaine Davis Hawkins', 'Tramaine Davis', 'Hawkins', NULL, 350145, 99, NULL, NULL, NULL, NULL, NULL, 'American gospel singer, born in 1951 as Tramaine Aunzoyle Davis. Performed as [a=Tramaine Davis] until her 1971 marriage to [a=Walter Hawkins].
