	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (8507, NULL, 'Rolf-Hans Müller', 'Rolf-Hans', 'Müller', NULL, 359502, 99, NULL, NULL, NULL, NULL, NULL, 'Rolf-Hans Müller (April 10, 1928 - December 26, 1990) was a German orchestra leader and composer, born in Dresden, Germany, and passing away in Baden-Baden, Germany. He began his musical journey as a member of the Dresdner Kreuzchor and later studied at the Music Academy in Heidelberg. In 1949, he joined the Südwestfunk in Baden-Baden, where he worked as a pianist, composer, and arranger. In 1959, he founded and led the SWF Dance Orchestra until 1979, touring extensively in Asia and America. Müller was also a prominent figure on television, including the first color broadcast by ARD in 1967. He composed music for films and TV series, such as "Der Forellenhof," "Salto Mortale," and "Tatort." Notably, he collaborated with the renowned trumpeter Maynard Ferguson, enhancing the jazz and dance music scene. Müller''s contributions are remembered through the Rolf-Hans Müller Prize for Film Music, awarded to young composers by the Südwestrundfunk since 1992. He was buried in the Hauptfriedhof Baden-Baden.');
