	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (9168, NULL, 'Eugene Capobianco', 'Eugene', 'Capobianco', NULL, 380673, 99, NULL, NULL, NULL, NULL, NULL, 'Born Eugene Capobianco 29 March 1927, Hartford, Connecticut, jazz enthusiast Gene Bianco started off his career as a classical virtuoso harpist, and toured with major orchestras to rave reviews. His love for jazz, however, prompted him to explore the concept of using harp as a jazz instrument, an idea that was hitherto unheard of. Having appeared as a solo act in a variety of New York nightclubs, he later teamed up with guitarist Mundell Lowe and percussionist Joe Venuto to form a jazz trio which released an album on the obscure Major Records label. Soon after, RCA signed the group to a three-album contract, under which the albums "Stringin'' the Standards" and "Harp, Skip and Jump!" were released. 
