	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (9504, NULL, 'Mark Berry', 'Mark', 'Berry', NULL, 392350, 99, NULL, NULL, NULL, NULL, NULL, 'Producer, mixer, engineer and remixer from Brooklyn, New York. Began his music career in 1972 at the Institute of Audio Research (IAR) in New York City. Soon after he moved to London and landed a job at AIR Studios and, aged just 18, won his first Engineering credit on Carly Simon''s [i]No Secrets[/i] album. During the mid 1970s, Mark returned to the USA and freelanced around New York, until he was offered the position of Staff Engineer and in-house A&R/producer for Vanguard Records, where he stayed for 9 years. Through the mid-1980s, Mark turned his hand to remix work for mainstream artists such as David Bowie, Duran Duran, Talk Talk, Toto, Yes, Billy Idol, Boy George, Kool & The Gang and Stephanie Mills. At the beginning of the 1990s, Mark moved to Toronto, Canada and continued his A&R and production work, mostly in the Rock genre, with artists such as I Mother Earth.
