	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (9688, NULL, 'Neil Ellwood Peart', 'Neil Ellwood', 'Peart', NULL, 398982, 99, NULL, NULL, NULL, NULL, NULL, 'Neil Peart (12 September 1952, Hamilton, Ontario, Canada–7 January 2020, Santa Monica, California, US) was the drummer and primary lyricist for the progressive rock band Rush. He was known for his complicated, extremely technical drumming containing odd time signatures and complex arrangements. Peart joined the band in the summer of 1974 following previous drummer John Rutsey''s departure and has been a member ever since. He has received many awards for his performances with Rush and was widely regarded for his technical proficiency and stamina. He is one of the most popular and influential drummers in the history of rock music.');
