	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10971, NULL, 'Duane Stephen Michals', 'Duane Stephen', 'Michals', NULL, 454225, 99, NULL, NULL, NULL, NULL, NULL, 'American photographer, born 18 February 1932 in McKeesport, Pennsylvania, USA. Died 9 June 2026. Best known for this involvement with the Police - [m=39248] LP. The album''s original cover artwork was available in 36 variations, with different arrangements of the colour stripes and showing different photographs of the band members, taken by Duane. The most common version is of Sting reading a copy of Jung''s "Synchronicity". ');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10972, NULL, 'Philharmonia Orchestra', 'Philharmonia', 'Orchestra', NULL, 454293, 99, NULL, NULL, NULL, NULL, NULL, 'London-based orchestra founded in 1945 by [a841734]. [a846301] conducted the orchestra''s opening concert on 27 October 1945. In March 1964, Legge announced the orchestra’s disbanding. The players rallied, took matters into their own hands, elected a governing body, added ''New'' to the title (see [a=New Philharmonia Orchestra]) and carried on, first up with [a=Otto Klemperer] conducting [a95544]’s "Choral Symphony". The ''New'' was dropped in 1977, the orchestra’s third era celebrated with a Beethoven concert under [a=Riccardo Muti] and pianist [a=Sviatoslav Richter]. Since 1995 it has been based in the [l264335].
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10973, NULL, 'John Naprstek', 'John', 'Naprstek', NULL, 454419, 99, NULL, NULL, NULL, NULL, NULL, 'American sound engineer');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10974, NULL, 'Jacques Hermet', 'Jacques', 'Hermet', NULL, 454426, 99, NULL, NULL, NULL, NULL, NULL, 'Sound engineer (recording/mixing) and producer.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10975, NULL, 'Omar Clay', 'Omar', 'Clay', NULL, 454664, 99, NULL, NULL, NULL, NULL, NULL, 'US drummer/percussionist. Born in 1935 in St. Louis, Missouri. Died on December 4, 2008, in San Francisco, California, of complications from Lou Gehrig''s disease. He was 73. He grew in Steubenville, Ohio. Clay played actively throughout his high school career and continued as a college student at Xavier University in New Orleans, Louisiana. He switched his major from Liberal Arts to Music. He left Xavier after one year due to lack of funds and joined the Army. This decision was influenced by Curtis Fuller''s experience playing music while in the Army. After degree in Michigan established himself in the New York jazz scene. An early associate in New York was Otis (Candy) Finch. Played at the Five-Spot with Charles Mingus. Also played with Warren Smith. He was introduced to Sarah Vaughan in New York, auditioned and was hired to go with her to perform in Las Vegas. He played with Sarah Vaughan throughout 1965 touring. He met Louis Armstrong during his association with Vaughan. After parted ways with Sarah Vaughan, taught music in New York, 1967. Then Clay was featured in master drummer Max Roach''s all-percussion ensemble M''Boom, playing marimba, tympani, timbales and xylophone. He was equally at home working with singer Ernestine Anderson and hard-blowing saxophonists like David "Fathead" Newman, Frank Foster and Gene Ammons. In 1979, he moved to Mill Valley, California, earning a Master''s degree in music education from San Francisco State University.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10976, NULL, 'Gene Radice', 'Gene', 'Radice', NULL, 454776, 99, NULL, NULL, NULL, NULL, NULL, 'Well-known recording engineer who worked with artists such as Jimi Hendrix, Velvet Underground, Lovin'' Spoonful, Janis Ian, the Four Seasons, Cowsills, Mamas & the Papas, The Tokens, Vanilla Fudge and many more.  Father of [a=Mark Radice] and older brother of [a=Bill Radice].
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10977, NULL, 'Hubert Varron', 'Hubert', 'Varron', NULL, 454805, 99, NULL, NULL, NULL, NULL, NULL, 'French classical cellist. Born June 23, 1933 in Paris, France - Died August 16, 2005 in Courtonne-les-Deux-Églises, Calvados, France.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10978, NULL, 'Brian Vibberts', 'Brian', 'Vibberts', NULL, 455046, 99, NULL, NULL, NULL, NULL, NULL, 'American engineer from Portland, Connecticut. Started in New York at [l=Right Track Recording] (1991-92), [l=The Hit Factory] (1992-94) and [l=Sony Music Studios, New York City] (1995-2000). Moved to Los Angeles in 2000 to work at [l=Ocean Way Recording] (2001-05). Now scoring Warner Bros. films.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (10979, NULL, 'Jaime Salazar', 'Jaime', 'Salazar', NULL, 455071, 99, NULL, NULL, NULL, NULL, NULL, 'Born on October 18, 1965 in Santiago - Chile, drummer [a=Jaime Salazar] is mostly known for his work with the Swedish progressive rock group [a267071]. His powerful-yet-subtle style brought the bands lush arrangements a remarkable energy. His first important engagement was with ex-[a=Mahavishnu Orchestra]''s [a=Jonas Hellborg], with whom he recorded and toured in the 1980s. He also toured and recorded with the Swedish hard rock band [a=Bad Habit], the Swedish rock singer [a=Zia] Lindberg, and new country artist [a=Aaron Springfield]. In 1994, he was recruited by progressive rock guitarist [a=Roine Stolt] to work on his album The Flower King. The warm reception the album received motivated the creation of [a267071] as a full-time band and Salazar has been the driving rhythmic force of the band ever since. He also played on Stolt''s 1998 solo album [m=515885], worked with All Music Guide [a=François Couture] as well as with [a=Rheingold], [a=Last Tribe] and [a=Opus Atlantica].');
