	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (11190, NULL, 'José Monserrat Feliciano García', 'José Monserrat Feliciano', 'García', NULL, 465889, 99, NULL, NULL, NULL, NULL, NULL, 'Puerto Rican guitarist, singer and songwriter born September 10, 1945, in Lares, Puerto Rico. He was born blind. He was married to [a=Hilda Feliciano] until he divorced in 1978 and remarried to [a682242]. He recorded many international hits, including his rendition of the Doors'' "Light My Fire" and his self-penned Christmas song "Feliz Navidad". Music genres he explores consist of a fusion of many styles, such as Latin, blues, jazz, soul and rock music, created primarily with the help of his signature acoustic guitar sound. In the United States, Feliciano became popular in the 1960s, particularly after his 1968 album Feliciano! reached number 2 on the music charts.  Since then in his career, he has released over 50 albums worldwide in both the English and Spanish languages. Feliciano received his star on the Hollywood Walk of Fame on December 1, 1987. José Feliciano was presented the 2000 Grammy Legend Award at the 42nd Annual Grammy Awards. On December 15, 2010, Feliciano appeared as the featured guest on the 37th episode of Daryl Hall''s Webbie-Award-winning webcast Live From Daryl''s House. In 2011, Feliciano signed with manager Howard Perl who immediately brought him to The Agency Group. During May and June 2019, Feliciano was recording an album for Anthem Records in both Nashville and Connecticut with his long-time producer, Rick Jarrard. The album is called Behind This Guitar and was released on January 31, 2020. Feliciano returned to baseball''s post-season, and on national television, once again rendered his stylized version of the Star-Spangled Banner in San Francisco before the first game of the National League''s Championship Series against the St. Louis Cardinals. Soon Feliciano appeared on a song with reggaeton artist Farruko called Su hija me gusta, where a young man tells a father I like your daughter.[ He also began recording sessions] with Producers Howard Perl, Jon Guggenheim, Juan Cristobal Losada, Wyclef Jean, Plácido Domingo, Billy Ray Cyrus, and Frank Licari.');
