	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (11217, NULL, 'Charles Covington', 'Charles', 'Covington', NULL, 467165, 99, NULL, NULL, NULL, NULL, NULL, 'Keyboard/piano/organ player.Charles Covington, jazz organist and pianist, was one of the trailblazers playing jazz on the Hammond B3 organ back in the early 60’s who influenced and inspired most of the leading jazz organists during that period including Lou Bennett, Jimmy Smith, Larry Young Jr., Richard Groove Holmes, Don Patterson and many others. Since he refused to record under his own name during that period, he remained largely unknown except in the jazz organ circle, until recently when he was rediscovered. Covington has recorded and/or performed with scores of jazz greats such as Sonny Stitt, Gene Ammons, Eddie Harris, Milt Jackson, Clark Terry, Eddie “Cleanhead” Vincent, Zoot Simms, George Benson (a live recording at Newport Jazz Festival 3 July 1969 on Wolfgangs.com), and many others including comedians Redd Fox, Pigmeat Markham, Slappy White, Flip Wilson; also vocalists such as Abbey Lincoln, Eartha Kitt, Shirley Horn and Ethel Ennis among others.');
