	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (12603, NULL, 'Peter J. Wright', 'Peter J.', 'Wright', NULL, 555321, 99, NULL, NULL, NULL, NULL, NULL, 'Music executive. Started in Manchester in 1980 working for [a=Buzzcocks]’ management company and label [l=New Hormones]. In 1982 he moved to New York and worked in independent distribution at [l=Dutch East India Trading] and [l=Caroline Distribution] as well at [a=Sonic Youth]’s first label [l=Neutral Records (3)]. He also set up his own publicity & promotion company to represent UK labels and artists such as [l=Mute Records], [l=Red Rhino Records], [a=The Mekons] and [a=Cabaret Voltaire]. In 1988 he set up Mute Records New York office and became its Label Manager and then VP of Operations. In 1996 he moved to Boston, MA as GM for [l=Rykodisc] and in 2000 returned to NYC where he became GM of [l=Instinct Records] ([a=Moby]’s first home). In 2003 he set up [l=Virtual Label LLC], a service company for artists and indie labels offering access to physical and digital distribution, marketing and consulting services. ');
