	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (12859, NULL, 'Jonathan Schenke', 'Jonathan', 'Schenke', NULL, 570644, 99, NULL, NULL, NULL, NULL, NULL, 'Producer and recording, mixing, and mastering engineer; a sound designer for film, software, and installations; as a producer and mix engineer, Jonathan Schenke has worked on hundreds of records (for the likes of Parquet Courts, Liars, Dougie Poole, and many more). As a musician, he has released dozens of records with his various groups (including P.E., Eaters, and Gift Horse).  ‘Passages’ is the first solo outing from this prolific collaborator. He co-owns and co-operates [l=Studio Windows] in Brooklyn, NY.');
