	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (12885, NULL, 'James N. Colvard', 'James N.', 'Colvard', NULL, 572877, 99, NULL, NULL, NULL, NULL, NULL, 'Born 1943, Minnesota country guitar player Jimmy Colvard was an innovative musician and a much used session guitarist. He began playing in Minneapolis-St. Paul as early as 1957, when he was still in his teens. He performed with his steel guitar playing friend Al Udeen and in 1958 both Colvard and Udeen toured across Minnesota with stars like Wanda Jackson, George Jones, Bobby Lord, Marvin Rainwater and others. Later he founded the Jimmy Colvard Trio. Colvard was lead guitarist on Dave Dudley''s "Six Days on the Road" playing the "popping" sound which eventually would become a significant element of trucker country music. He soon left for Nashville, working as a session guitarist with Faron Young, Don Williams, Cal Smith, Connie Francis, Charlie Walker, Dolly Parton, Little Jimmy Dickens and others. He died by suicide in 1977.');
