	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (13050, NULL, 'Robert Reiniger Meredith Willson', 'Robert Reiniger Meredith', 'Willson', NULL, 583501, 99, NULL, NULL, NULL, NULL, NULL, 'Meredith Willson (born 18 May 1902, Mason City, Iowa, USA – died 15 June 1984, Santa Monica, California, USA) was an American composer, songwriter, conductor and playwright.  Willson played the flute and piccolo and was a member of John Philip Sousa’s famous band from 1921 to 1923. He then joined the New York Philharmonic Orchestra from 1924 to 1929.  He is best known for writing the book, music, and lyrics for the 1958 Tony Award winning hit musical [i]The Music Man[/i]. The cast recording of [i]The Music Man[/i] won the first Grammy Award given for best cast album. Also remembered for playing a regular character on the Burns and Allen radio program, musical director for numerous radio shows and his work on films.  He received Academy Awards nominations for writing the music for Charlie Chaplin''s [i]The Great Dictator[/i] (1940) and William Wyler''s [i]The Little Foxes[/i] (1941).  Many of his songs have become standards, including [i]Till There Was You[/i] a hit for the Beatles in 1963.');
