	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (13183, NULL, 'Gerald Thomas Moore', 'Gerald Thomas', 'Moore', NULL, 593267, 99, NULL, NULL, NULL, NULL, NULL, 'G.T. Moore is an English singer, composer and multi-instrumentalist, born on 1949-05-02 in Reading, Berkshire (UK). After starting out in brass-based soul band Gerald T. Moore And The Memphis Gents (local heroes to Reading mods) he decamped to Maidenhead to attend art school. He would reappear in folk rock band Heron, who disbanded in 1972. Moore then became a true pioneer of the British reggae scene, with a recording career that stretches from the early 1970’s. His band The Reggae Guitars were the first white group to seriously attempt an authentic reggae sound, recording two albums for Charisma Records (1972''s G.T. Moore And The Reggae Guitars 1972 and 1974''s Reggae Blue), the former album boasting the original reggae cut of Bob Dylans Knocking On Heaven’s Door an idea taken to chart success by Eric Clapton some years later. After The Reggae Guitars split in 1977, Moore worked in Nashville, USA, and then moved to Amsterdam, the Netherlands. That led to session work in Jamaica for Lee Perry and with Zap Pow at Harry J''s and with Sly & Robbie at Channel One. During the 1970s Moore also played on most of [a1344318]''s studio albums. He also appears on [m179918]. Since around 2010 he has rejoined Heron.');
