	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (13963, NULL, 'John Len Chatman', 'John Len', 'Chatman', NULL, 647746, 99, NULL, NULL, NULL, NULL, NULL, 'Peter Chatman is better known as [a=Memphis Slim], the performing name he used for almost all of his career.    Born John Len Chatman it is believed he adapted Peter as first name for his early Okeh recordings to honour his father, Peter Chatman, also a blues musician. Very soon he started using Memphis Slim as performer name, but kept using Peter Chatman for his composers credits.
