	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (13967, NULL, 'Jasper Taylor', 'Jasper', 'Taylor', NULL, 647984, 99, NULL, NULL, NULL, NULL, NULL, 'Jasper Taylor (January 1, 1894, Texarkana, Arkansas – November 7, 1964, Chicago) was an early Jazz percussionist. He left his home Texas as a teenager in 1912 playing drums with Young Buffalo Bill''s Wild West show and continued in show business playing in minstrel shows and in theatre pit bands. In 1913 he was in Memphis playing drums, xylophone and washboard in W.C. Handy''s Orchestra of Memphis and with Jelly Roll Morton. In 1917 he relocated to Chicago and played in Clarence Jones'' Orchestra. He joined the military during World War I and served in France with the 365th Infantry Band. The 365th Infantry were nicknamed the "Buffalo Soldiers," the enlisted personnel were almost entirely African-American soldiers from Texas and Oklahoma. Returning to America after the war he found work with Will Marion Cook and with W.C. Handy in New York. In the early 1920s he returned to Chicago and worked and recorded with a variety of artists throughout the decade including Dave Peyton, Fess Williams, Clarence Williams, Tiny Parham, Jimmy O''Bryant and Freddie Keppard. During the Depression he was forced to leave the music business and he worked as a shoe repairman. In the 1940s he resumed his music career and played with a variety of artists in the Chicago area including Punch Miller, Natty Dominique and Lil Hardin-Armstrong. He died in 1964 in Chicago. ');
