	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (13969, NULL, 'William K. Johnson', 'William K.', 'Johnson', NULL, 647996, 99, NULL, NULL, NULL, NULL, NULL, 'American banjoist, guitarist and singer, born 1905 in Lexington, Kentucky; died August 13, 1955 in Lexington, Kentucky in a house fire. Active in the music scene in and around Louisville, in 1926 he moved to New York with the Dixie Ramblers. Played also with George Howe (1926-1927) and [a=Luis Russell] (1927-1932). During this era he also made recordings with [a=King Oliver], [a=Henry "Red" Allen] and [a=Jack Purvis]. From 1933 to 34 he played with Fess Williams. After working as a freelance, he stopped playing and returned to Lexington.
