	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (15132, NULL, 'Itiberê Luiz Zwarg', 'Itiberê Luiz', 'Zwarg', NULL, 741621, 99, NULL, NULL, NULL, NULL, NULL, 'Bass player and composer born in São Paulo, Brazil, in 1950. After starting studying music with his father, [a=Antonio Bruno Zwarg], he began his career with Ray Carelli group, playing in ballrooms in the city of São Paulo. In the 70''s he was part of Xangô Três and Bossa Jazz Trio. He studied double bass with Nicolai Tchevtchenko. Since 1977, he has been playing with [a=Hermeto Pascoal E Grupo] all over the world, touring in Europe, North America, and Japan. In 1992, Itiberê began his career as composer and arranger, followed in 1999 by the creation of his huge youth orchestra [a=Itiberê Orquestra Família] - starting with 33 members - who changed name in 2011, being then referred to as [a=Itiberê Zwarg & Grupo].');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (15133, NULL, 'Simon O''Connor', 'Simon', 'O''Connor', NULL, 741654, 99, NULL, NULL, NULL, NULL, NULL, 'Simon O''Connor is a Dublin-based composer whose musical life began in punk bands as a young teen. Musically self-taught, he worked primarily in theatre composition before forming seminal Dublin psych-rock band The Jimmy Cake. A graduate of Trinity College, Dublin, where he studied with composers Donnacha Dennehy and Kevin Volans, O’Connor has for many years worked primarily in a tonal, minimal palette, writing for chamber ensembles and solo musicians.');
