	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (15227, NULL, 'Dave Chisholm', 'Dave', 'Chisholm', NULL, 747164, 99, NULL, NULL, NULL, NULL, NULL, 'Dave Chisholm is a trumpet player, songwriter, composer, bandleader, educator, and visual artist currently residing in Rochester, NY where he received his doctorate in jazz trumpet from the Eastman School of Music in 2013. The breadth of Chisholm''s artistic output is exemplified in a long string of widely varied projects including the big-band jazz of his debut album Radioactive (2010), the post-rock-meets-jazz-improvisation soundscapes on Calligraphy (2011), his soulful indie-rock singer-songwriter project Talking Under Water, the blistering straight-ahead jazz performed by Utah group John Henry, and the upstart jazz big bands Salt Lake Alternative Jazz Orchestra and Colossus. As a trumpet player, Dave has garnered international acclaim. In 2012, he performed six nights at the Umbria Jazz Festival as part of Ryan Truesdell''s "Gil Evans: Centennial" project. In 2009, he was one of two recipients of the Downbeat Student Music Award for outstanding collegiate soloist. He has also received numerous accolades and awards at both the Reno Jazz Festival and the University of Northern Colorado Jazz Festival. Dave wrote and illustrated his first graphic novel, LET''S GO TO UTAH!, in 2009, followed by short comics in MYSPACE DARK HORSE PRESENTS, and Locust Moon''s Eisner Award-winning anthology, DREAM ANOTHER DREAM. At the time of writing, he currently teaches at State University of New York at Brockport and at the Hochstein School of Music and Dance. ');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (15228, NULL, 'Graham Ellis', 'Graham', 'Ellis', NULL, 747206, 99, NULL, NULL, NULL, NULL, NULL, 'Trombonist and tuba player');
