	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (15302, NULL, 'David Martin (10)', 'David Martin', '(10)', NULL, 752912, 99, NULL, NULL, NULL, NULL, NULL, 'US jazz pianist -sometimes credited as Dave Martin- who enjoyed a long career as an accompanist, sometimes leading his own band. He spent most of the ''30s with a crowd of expatriate jazzmen overseas including violinist [a=Eddie South], but much of his career was spent in New York City. Martin played cello as well as piano. He did some recording with the cello in the early part of his career but most of Martin''s studio dates were on the piano. Martin''s best-known composition is "Easy Does It".
