	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (16212, NULL, 'Ronald Thomas', 'Ronald', 'Thomas', NULL, 834394, 99, NULL, NULL, NULL, NULL, NULL, 'Australian classical violinist and session musician. Originally from Kulin, Western Australia, he moved to Britain and went on to play with the London Symphony Orchestra, the London Philharmonic Orchestra, the English Chamber Orchestra, the Academy of St Martin-In-The-Fields, the Bournemouth Chamber Orchestra and many more including Australia. He worked as a session musician with the Beatles and on major Hollywood scores. He is now re-settled in Perth, Western Australia.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (16213, NULL, 'Rafal Smolen', 'Rafal', 'Smolen', NULL, 834434, 99, NULL, NULL, NULL, NULL, NULL, 'Accomplished contemporary music and film score recording and mixing engineer. Pro studio manager and chief engineer. Highly experienced in Pop, Rock, Hip-Hop, Jazz, Film and Classical. Bands and symphonic orchestras recording, music production, studio and project managing. I can take the whole project from start to finish, from studio setup, midi sequencing, recording, editing to mix in stereo, 5.1, 7.1 and Dolby Atmos formats. Play drums, piano, classical percussion.
