	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (16223, NULL, 'Gary A. Grainger', 'Gary A.', 'Grainger', NULL, 835215, 99, NULL, NULL, NULL, NULL, NULL, 'Self-taught jazz/fusion bassist from Baltimore, USA, not to be confused with the British rock/pop guitarist/bassist [a=Gary Grainger]. Gary joined the group Pockets in the 70s; a protege-group with a distribution-deal at [l=American Recording Company (ARC)], a boutique-label of [a=Earth, Wind & Fire]. He recorded 3 albums and various singles with Pockets in the late 70s, mainly productions by [a=Verdine White] of EW&F, and [a=Robert Wright]. Tracks on these productions which Gary co-wrote include "Doin'' The Do," "Sphinx,"  "Wizzard Wuzzit," and "Got To Find My Way." Around the 80s, he formed The Graingers with his brothers [a=Glenn Grainger] and [a=Greg Grainger], and they released the single "Shine Your Light" on [l=BC Records]. Gary and Greg were also hired as studio-musicians for various recording sessions during the 80s. He recorded and toured with The John Scofield Band, which included his Baltimore-buddy, session drummer [a=Dennis Chambers]. Gary appears on 2 studio-albums ("Blue Matter" + "Loud Jazz") and one live-album ("Pick Hits Live"). He formed the group Grainger with his brother Greg in the 90s, and they released 2 CDs at the GBM-label. On their first CD appears a new recorded version of "Shine Your Light." More detailed info about Gary''s career and discography is documented in the biography of his personal MySpace-page.');
