	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (16991, NULL, 'Aaron Serfaty', 'Aaron', 'Serfaty', NULL, 904027, 99, NULL, NULL, NULL, NULL, NULL, 'Drummer and percussionist');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (16992, NULL, 'Jorge Laboy', 'Jorge', 'Laboy', NULL, 904028, 99, NULL, NULL, NULL, NULL, NULL, 'Jorge Laboy is a prolific Puerto Rican guitarist from Ponce (Born in Aug. 6, 1956) whose five-decade career spans genres from pop and rock to jazz fusion and smooth jazz. A versatile and inventive performer, he has collaborated with many national and international stars — including Danny Rivera, Glenn Monroig, Nydia Caro, Ricky Martin, Ednita Nazario, Enrique Iglesias, and Lourdes Robles. Though he studied classical guitar at the University of Puerto Rico, he taught himself jazz and broadened his sound by embracing improvisation. His 1988 album Jorge Laboy & 3AM—featuring both original compositions and celebrated session musicians—was well received, opening many doors. Laboy has always worked in Puerto Rico with pride, never relocating abroad. Still driven, he continues composing and preparing new projects. In 2025 he will be honored with a concert alongside the Puerto Rican Philharmonic Orchestra in Santurce, celebrating his legacy.');
