	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (19360, NULL, 'জয়ী রহমান', 'জয়ী', 'রহমান', NULL, 1192658, 99, NULL, NULL, NULL, NULL, NULL, 'Zoe Rahman (b. 1971) is an English jazz composer and pianist, sister of clarinetist/saxophonist [a=Idris Rahman]. Born in Chichester, West Sussex to a Bengali father and an English-Irish mother, she studied classical piano at the [l=Royal Academy of Music], and earned a degree from St Hugh''s College at the University of Oxford. Zoe Rahman continued her music education abroad, and took lessons with [a=Joanne Brackeen] after winning a scholarship to study jazz performance at [l=Berklee College Of Music] in Boston, USA.
