	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (19981, NULL, 'Colin Vallon', 'Colin', 'Vallon', NULL, 1283083, 99, NULL, NULL, NULL, NULL, NULL, 'Swiss jazz pianist and composer, born November 17, 1980 in Lausanne. After studying classical music for 2 years, he took classes with jazz pianist Marc Ueter at the age of fourteen. He enrolled at the Swiss Jazz School when he was 18 and studied with Silvano Bazan, William Evans, Manuel Bärtsch and Bert Joris. Colin Vallon won the Fridl-Wald Foundation Prize, 1st Prize in the Competition Nescafé Let’s Jazz Together, and 3rd Prize in the Montreux International Jazz Piano Solo Competition. Since 2009 he is teaching at the Bern University of the Arts. He has played with such musicians as [a=Tom Harell], [a=Daniel Schläppi], [a=Adrian Mears], [a= Samuel Rohrer], [a=Andy Scherrer], [a=Steffen Schorn],  [a=John Schröder], [a=Tyshawn Sorey], [a=Dejan Terzic], [a=Nils Wogram], [a=Kenny Wheeler] and [a= Patrice Moret].');
