	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (19985, NULL, 'Howard Eugene Johnson', 'Howard Eugene', 'Johnson', NULL, 1283144, 99, NULL, NULL, NULL, NULL, NULL, '(Born: July 14, 1920 - Died: April 28, 1993) Big band vocalist and commercial photographer Gene Howard was born Howard Eugene Johnson in Nashville, Tennessee. He joined Francis Craig''s orchestra in 1939, replacing Snooky Lanson. His first recordings were with Bob Chester''s band in 1942-3. For six months in 1943 he sang with Gene Krupa''s band, then with Teddy Powell before joining the Stan Kenton band in 1944. During the next two years, Gene made numerous recordings with the Kenton band, including duet work with Anita O''Day and June Christy. Gene left the Kenton band in 1946, becoming the band''s publicity director before free-lancing. He later formed the commercial photography studio of [a=Garrett-Howard], a career that was to last the rest of Gene''s professional life. He died in Los Angeles of a heart attack at the age of 72.');
