	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20405, NULL, 'Fred Haas', 'Fred', 'Haas', NULL, 1345983, 99, NULL, NULL, NULL, NULL, NULL, 'Fred Haas has performed with the likes of Oscar Peterson, Ray Charles, Pat Metheny, Clark Terry, Milt Jackson, Joe Morello, Don Cherry, Karrin Allyson, Matt Wilson, Gene Bertoncini, John Proulx and many others. Jazz guitarist Pat Metheny calls Fred Haas "a totally world-class saxophone player." Jazz trumpet legend Clark Terry said, "You won''t find a more capable jazz player and teacher than Fred Haas, and that''s a fact!" A Dartmouth graduate (''73), Fred teaches saxophone, jazz piano, jazz improvisation, jazz history, and music theory. He also mentors jazz combos as part of the Performance Lab program in the Music Department. In 1996 he founded Interplay Jazz & Arts, an intensive holistic workshop in jazz that integrates yoga and meditation with the study of improvised music and other artistic disciplines (painting, drawing, creative writing, photography, film making). Fred has recorded many CDs, including several for his own JazzToons label. He is also an active performer and composer, traveling internationally to play and teach with a variety of jazz groups. Jazz piano legend Oscar Peterson said, "Fred, for whom I have the great love as a friend and great respect as a player."
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20406, NULL, 'Johnny Taylor (2)', 'Johnny Taylor', '(2)', NULL, 1345995, 99, NULL, NULL, NULL, NULL, NULL, 'UK jazz bassist');
