	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20598, NULL, 'Robert James Roberts, Sr.', 'Robert James Roberts,', 'Sr.', NULL, 1384584, 99, NULL, NULL, NULL, NULL, NULL, 'American guitarist born in Chicago, Illinois on June 4, 1934, died February 1, 1995 in Orlando, Florida. Robert (Bobby) Roberts grew up listening to his father''s records, especially tenor great Bud Freeman. He wanted to play drums but his parents thought guitar would be quieter. He performed around Chicago, establishing a name for himself. After meeting Sam Butera by chance some time earlier, Bobby was offered the guitar chair from the departed Jack Marshall. Bobby played with Louis Prima in Las Vegas at numerous hotels in its heyday from 1957 until 1959. Afterward, he did a lot of touring, session work, and jingle dates with Dick Marx and Dick Reynolds. Played with Billie Holliday, Mel Torme, Lena Horne, and many other great musical artists. He also worked under the conductors George Solti and Seiji Ozawa with the Chicago Symphony Orchestra. He ultimately recorded [i]The Real Bud Freeman 1984[/i] and played with him live for the 1985 Chicago Jazz Festival. He had been living in Skokie and working regular gigs around the Chicagoland area before moving to Florida. His three children are named Leonard, Laurin, and Bobby, Jr.');
