	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20778, NULL, 'John Donnelly (2)', 'John Donnelly', '(2)', NULL, 1419552, 99, NULL, NULL, NULL, NULL, NULL, 'John Donnelly (1938 - September 1, 1997) was a respected Scottish trumpet player known for his remarkable talent and contributions to the world of jazz. Born in Neilston, Renfrewshire, Scotland, John hailed from a family with a strong tradition of brass music. He displayed an early aptitude for the trumpet and began his musical journey by performing with dance bands in the Paisley area during his teens.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20779, NULL, 'Roger Quincey Dickerson', 'Roger Quincey', 'Dickerson', NULL, 1420158, 99, NULL, NULL, NULL, NULL, NULL, 'Early jazz trumpeter, born c. 1898 in Paducah, Kentucky, died January 21, 1951 in Glens Falls, New York.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (20780, NULL, 'Roberto Perera', 'Roberto', 'Perera', NULL, 1421243, 99, NULL, NULL, NULL, NULL, NULL, 'Roberto Perera is an Uruguayan Jazz harpist, in the Smooth Jazz and Fusion styles. Born in 1952 in Montevideo, the capital city of Uruguay, Perera was barely 12 years old when his mother enrolled him in a music conservatory where he selected the rare 36-string Paraguayan harp. Perera''s complex technique includes precisely bending the strings to create sharps and flats while gliding across the harp in a seemingly effortless fashion, which bespeaks the tremendous amount of skill and discipline required. About the time Perera started playing the harp, the Beatles were in their heyday. The young musician absorbed their music as well as other pop music influences into his musical muse, which included Brazilian music, folk and tango from South America, and the folk music from Paraguay. Unable to find an instructor who could teach him how to perform a pop music repertoire on the harp, the determined Perera experimented until he was able to overcome the instrument''s technical hurdles and develop his own form of expression. In 1973, after completing ten years of harp studies in Montevideo, Perera moved to New York City with hopes of pursuing a top-notch music career. At first, his experience was not the American dream he had imagined, as his performances were limited primarily to playing folk tunes at clubs and restaurants. Perera paid his dues in New York for a couple of years before he was recruited by a talent scout to entertain at an exclusive private club in Florida. There he finally was allowed to perform his own compositions and further develop his distinctive style, having applied the musical influences of Weather Report and Antonio Carlos Jobim. He''d starting approaching the harp as a percussive instrument, much like a piano, instead of a string instrument.
