	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (21863, NULL, 'Monika Lichtenfeld', 'Monika', 'Lichtenfeld', NULL, 1639280, 99, NULL, NULL, NULL, NULL, NULL, 'Monika Lichtenfeld (1938-2023), born in Düsseldorf, studied musicology, philosophy and art history in Cologne, Florence and Vienna and received her doctorate with a thesis on Josef Matthias Hauer. As a journalist and editor, she wrote for the FAZ (Frankfurter Allgemeine Zeitung) and other daily newspapers, for specialist journals and for radio. She also published independent works on 20th century music. She interpreted experimental poetry and championed avant-garde music. In June 1981, she and like-minded people founded the Kölner Gesellschaft für Neue Musik (Cologne Society for New Music) in Cologne''s Beginner Studio, which still exists today. Together with Reinhard Qehlschlägel, Renate Liesmann (now Baum), Johannes Fritsch and Martin Schulz, she formed the society''s first board. She shared her life with viennese writer, composer and visual artist Gerhard Rühm and gave spoken concerts of contemporary poetry with him, among other things. Her publications include the publication of the collected writings of György Ligeti in 2007. As the ''Grand Dame'' of New Music, she was respected on the international scene and her balanced judgement was sought after.');
