	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (22737, NULL, 'Larry Birnbaum', 'Larry', 'Birnbaum', NULL, 1775847, 99, NULL, NULL, NULL, NULL, NULL, NULL);
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (22738, NULL, 'Jerry Tyree', 'Jerry', 'Tyree', NULL, 1776842, 99, NULL, NULL, NULL, NULL, NULL, 'Jerry Tyree (May 24, 1934 - March 5, 2011) was a jazz musician, trumpet and flugelhorn player whose life was dedicated to the art of music. Born in Terre Haute, Indiana, Tyree''s journey through the world of jazz was marked by his talent and unwavering passion. He received a solid foundation in music education under the tutelage of Bill Adam at the University of Indiana, setting the stage for a remarkable career. Throughout his life, Jerry Tyree graced the stage with some of the most iconic big bands, including The Maynard Ferguson Birdland Dream Band and The Woody Herman Orchestra. His musical versatility allowed him to thrive in various settings, from Broadway productions to the vibrant jazz scene of New York City, where he shared the stage with jazz luminaries like Wes Montgomery, Sonny Rollins, Freddie Hubbard, and John Bunch. Tyree''s legacy extends beyond his instrumental prowess; he was also celebrated for his encyclopedic knowledge of jazz and his warm and compassionate personality, leaving an indelible mark on the jazz community and music enthusiasts alike.');
