	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (22852, NULL, 'Albert Gay', 'Albert', 'Gay', NULL, 1795920, 99, NULL, NULL, NULL, NULL, NULL, 'Al Gay (born Albert Goldstein, 25 February 1928 London, England - 12 October 2013) was a British jazz tenor saxophonist. After formal studies in clarinet and saxophones at the Guildhall School of Music, Gay worked in various dance bands during the mid- and late 40s. In 1953 he joined the Freddy Randall band and, after leaving three years later, he remained strongly connected with the traditional jazz scene, playing with bands led by Joe Daniels, Harry Gold and Bob Wallis. In the early 60s Gay became a member of Alex Welsh’s band, where he remained for almost five years, returning in 1977 for a further six years.  After having played with the Jive Bombers, Gay worked with Freddy Randall from 1953, and would return several times to Randall’s future line-ups. In the early 1960s, he was with Bob Wallis'' Storyville Jazzmen before going on to join Alex Welsh. With fellow tenors Dick Morrissey and Stan Robinson, baritone sax Paul Carroll, and trumpets Ian Carr, Kenny Wheeler and Greg Brown, Al Gay formed part of The Animals'' Big Band that made its one-and-only public appearance at the 5th Annual British Jazz & Blues Festival in Richmond on 5 August 1965. In 1978, he played with the World''s Greatest Jazz Band. In the 80s, Gay freelanced, working in radio and as accompanist to numerous visiting jazz artists. In the late 80s and 90s Gay could be heard leading his own band and also playing with groups such as the Pizza Express All Stars. As well as leading his own line-ups, Gay also played in bands led by Digby Fairweather, Laurie Chescoe and Ron Russell. A sound mainstream performer, Gay’s work on tenor saxophone is particularly pleasing. Gay lived in Bedfordshire until his death in 2013; an obituary appeared in Jazz Journal''s March 2014 edition. ');
