	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (23306, NULL, 'Andrew Neil MacNaughtan', 'Andrew Neil', 'MacNaughtan', NULL, 1841853, 99, NULL, NULL, NULL, NULL, NULL, 'Toronto photographer, best known for documenting [a=Rush] and many other Canadian musicians including [a=Avril Lavigne], [a=Celine Dion], [a=Simple Plan], [a=Bryan Adams], [a=The Tragically Hip], and [a=Michael Buble]. Died in Los Angeles on 24-Jan-2012 of an apparent heart attack while on an assignment shooting [a=Rush].
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (23307, NULL, 'Tim Bryant (2)', 'Tim Bryant', '(2)', NULL, 1841917, 99, NULL, NULL, NULL, NULL, NULL, 'Tim Bryant was an American art director and album cover designer whose work helped define the visual language of popular music in the 1970s and 1980s. He designed hundreds of albums for artists including Elvis Presley, Bob Dylan, David Bowie, Dolly Parton, Jimmy Buffett, John Coltrane, Jefferson Starship, Quincy Jones, Bob Seger, John Denver, Duke Ellington, the Beach Boys, and the Bee Gees, among many others. He also designed iconic covers for major cultural works, including the soundtracks to Star Wars: The Empire Strikes Back, Grease, and Carl Sagan’s Cosmos, projects that extended album art into cinema, science, and mass culture. His extensive catalog includes some of the most iconic, era-defining designs from the pinnacle of the vinyl era.
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (23308, NULL, 'Hal Miller (2)', 'Hal Miller', '(2)', NULL, 1841946, 99, NULL, NULL, NULL, NULL, NULL, 'Hal Miller is a jazz drummer, Latin percussionist, jazz historian, teacher and writer.');
