	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (23415, NULL, 'Deborah Whipple Norcross', 'Deborah Whipple', 'Norcross', NULL, 1849859, 99, NULL, NULL, NULL, NULL, NULL, '[b]Deborah Norcross[/b] (b. April 1957) is an American designer and art director based in the Boston Area. She specializes in print, branding/logo design, CD packaging, and book/magazine layouts. Between the mid-1980s and early 2000s, Norcross resided in California and worked extensively in the record industry, starting as a designer for [url=https://discogs.com/label/619035]Media Home Entertainment[/url] and later serving as art director for [b][l=Warner Bros. Records][/b] (1989–1999) and senior art director for [b][l=Virgin Records America, Inc.][/b] (1985–87) and [b][l=Virgin Records][/b] (1999–2001). In later years, Norcross was [l=Levi Strauss & Co.]''s global creative director (2005–14). She studied at the [l=Massachusetts College of Art and Design] between 1979 and 1984; two decades later, from 2005 to 2010, Deborah taught at MassArt as a visiting lecturer. In 1995, she earned a double nomination at the 37th Grammy Awards for the "Best Recording Package" of [a=Oingo Boingo]''s 1994 [i][m=102307][/i] CD on [l=Giant Records], including the best "Boxed Package" for the [url=https://discogs.com/release/1582799]digipak edition[/url].
