	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (24237, NULL, 'Dan Nooger', 'Dan', 'Nooger', NULL, 1923816, 99, NULL, NULL, NULL, NULL, NULL, 'Dan Nooger has been a musician, music writer, album reissue producer, sleeve note writer, researcher, and music business executive. In the mid 1970’s he was employed by All Platinum Records (who had purchased Chess Records from GRT) to produce the Chess Blues Masters series of double-LP reissue albums (many of them with unissued material) as well as other jazz, rock and R&B reissues from the massive Chess catalogue. During the punk rock era his band Razors Edge opened three nights for Blondie at CBGB (Valentines weekend February 1976) and also opened shows for the Dictators, among others. His Village Voice review of one of Bruce Springsteen''s earliest New York shows at Max''s Kansas City in 1973 was quoted in Will Hermes'' book "Love Goes to Buildings On Fire". He has produced and/or annotated many blues, soul and jazz reissue projects over the years for such labels as Savoy Jazz, Ace and Night Train. He has written about music for many years including stints as a staff writer for Atlantic Records and a staff reporter for the music trade publication Casbox. His writings have appeared In Rolling Stone, Goldmine, Crawdaddy, Village Voice, Circus, Rock, Fusion, New York Rocker, Phonograph Record, Record Collector, Shades of Soul, and Soul Source, among others. He wrote the Detroit and Philadelphia chapters of "Blackwell''s Guide To Soul Recordings" His name was also quoted as the "reviewer" of the Nasty Bits'' show in the final episode of HBO''s Vinyl. He also used to do some TV and movie work in the mid ''90s and was directed by Martin Scorsese in "Bringing Out The Dead".');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (24238, NULL, 'Julio Cesar Barreto Penié', 'Julio Cesar Barreto', 'Penié', NULL, 1923862, 99, NULL, NULL, NULL, NULL, NULL, 'Cuban drummer, born 19 September 1967 in Guanabacoa, Havana, Cuba, based in Switzerland.');
