	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (24661, NULL, 'Vito Pizzo', 'Vito', 'Pizzo', NULL, 1980671, 99, NULL, NULL, NULL, NULL, NULL, '"Vito Price is one of the great unknowns of jazz music, a saxophonist who made his debut album in 1959 and then didn’t release a follow-up until 2003! On the evidence of his debut, it was a loss to the music world, given that Swinging The Loop was an exceptional first time effort. “I’m thrilled that I finally got the chance to do a record. I felt ready. This is my idea of happy, swinging music,” he stated at the time of release. And indeed it is happy, swinging music, and an album that should have ushered in a major new talent. That he was allowed to pass under the radar for so long is one of jazz music’s great mysteries, for on the strength of this outing, he appeared destined for greatness." - Quoted From The Pickwick Group Ltd Website ');
