	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (27000, NULL, 'Culver Pictures', 'Culver', 'Pictures', NULL, 2276661, 99, NULL, NULL, NULL, NULL, NULL, 'Culver Pictures provides the images in its collection to publishers of books, magazines, newspapers, websites, films, and television productions. The Culver family has been collecting all manner of printed imagery since 1926-chiefly photographs and illustrations covering the nineteenth and the first half of the twentieth centuries. The archive includes nearly a million photographic images (most of which have been digitized), plus over a million engravings, illustrations and gravure prints. There are also magnificent copperplate engravings and close to two hundred thousand photographic negatives-nitrate, poly and glass-most of which are yet to be digitized.');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (27001, NULL, 'Peter Jacques (2)', 'Peter Jacques', '(2)', NULL, 2276732, 99, NULL, NULL, NULL, NULL, NULL, 'Peter was born in Franzensbad, Czechoslovakia, on May 17,1935 and died March 27, 2025. - son of a Swiss mother and a Belarusian father, who succeeded as a solo violinist and concertmaster. He made his first appearance on the classical circuit at the age of eight, dabbling with jazz during his classical education and won the first price later on at the Zürich Jazz Festival in 1953. After a brief stint with Chet Baker, he joined some of the best jazz combinations in Sweden and Denmark (Åke Persson, Foss Trio, Ernie Englund, Kurt Weill Band, Harry Arnold Radioband), and even sang background on productions of Alice Babs and Povel Ramel during his stay on the Swedish jazz scene. 
