	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (27750, NULL, 'Brett Stamps', 'Brett', 'Stamps', NULL, 2366172, 99, NULL, NULL, NULL, NULL, NULL, 'American jazz trombone player.  Brett Stamps held the position of Director of Jazz Activities at Southern Illinois University-Edwardsville (SIUE) from 1979 -2019 where he initiated the Jazz Performance Degree. He directed the SIUE Concert Jazz Band and taught jazz combo, improvisation, arranging, trombone, education, and history. After his retirement he was honored with the title of Professor Emeritus. He obtained his BA in Music from the College of William and Mary (1970) and his MM in Studio Music and Jazz Pedagogy from the University of Miami (1975). Brett performed, recorded and arranged for the United States Army Field Band Jazz Ambassadors (1970-1973), the Stan Kenton Orchestra (1973-1974), and the University of Miami Concert Jazz Band (1974-1978) before accepting a teaching position at Miami-Dade Community College New World Center (1978-1979). St. Louis area performance credits include the Jim Widner, Kim Portnoy, Mo Bottom and Gary Dammer Big Bands; Fox Theater & MUNY Orchestras; the St. Louis Rivermen; Cornet Chop Suey, Legacy; Galaxy; the SIUE Jazz Faculty; and various clinics, concerts and recordings (including his new CD release In Your Own Sweet Way for Victoria Records). Brett remains active as a composer/arranger and clinician. Past endeavors include directing Missouri and Illinois All-State/All-District Jazz Bands, presenting trombone ensemble masterclasses (USF), writing music commissioned by the IMEA, private individuals and local schools, directing annual concerts of his original music at the historic Sheldon Concert Hall in St. Louis, writing for trombone quintet, touring nationally with Cornet Chop Suey and the St. Louis Rivermen and teaching/performing at the Jim Widner Band Camps.');
