	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32012, NULL, 'Holger Martin Petersen', 'Holger Martin', 'Petersen', NULL, 3502679, 99, NULL, NULL, NULL, NULL, NULL, 'Canadian businessman, record producer and radio broadcaster (born 23 November 1949). Petersen started producing records in 1972. The first were by Walter Horton, Johnny Shines, Roosevelt Sykes, Humphrey and the Dumptrucks, Liam Clancy, and Paul Hann.  All prior to [l=Stony Plain Records] which was registered in 1975 by he and Alvin Jahns. He now runs his own label, Stony Plain Records - one of Canada''s longest surviving independent record companies - and was a founder of the Edmonton Folk Music Festival. He is a member of the Order of Canada and has an Honorary Doctorate of Letters from Athabasca University.
