	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32020, NULL, 'Bettmann Archive', 'Bettmann', 'Archive', NULL, 3503959, 99, NULL, NULL, NULL, NULL, NULL, 'American collection of photographs established in 1936 by Dr. [url=https://discogs.com/artist/2263061]Otto Ludwig Bettmann[/url] (1903—1998), former head of the [url=https://discogs.com/label/3076795]Berlin State Library[/url]''s Rare Book Department, after he immigrated to the United States. Owned by [b]Kraus-Thomson Organization, Ltd.[/b] (1981 to 1995), digital stock company [b][a=Corbis][/b], created by [l=Microsoft Corporation] co-founder [url=https://discogs.com/artist/1349328]Bill Gates[/url] (1995–2016), and [b][url=https://discogs.com/artist/7423445]Visual China Group[/url][/b] (since 2016), with international distribution managed by [b][l=Getty Images][/b]. Since 2001, the Bettmann Archive has been located at the [url=https://discogs.com/label/1705147]Iron Mountain[/url]''s climate-controlled "National Underground Storage Facility" in western Pennsylvania. The collection stores negatives for numerous iconic XX-century photographs, from the "[i]Hindenburg Disaster[/i]" (1937) and "[i]Lunch atop a Skyscraper[/i]" (1932) with high-rise ironworkers sitting on steel beam during the [l=Rockefeller Center]''s construction to the renowned 1951 portrait of 72-year-old [a=Albert Einstein] sticking his tongue out, or [a=Dr. Martin Luther King, Jr.] giving his seminal 1963 speech at [l=Lincoln Memorial, Washington].');
