	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32139, NULL, 'The Artform Studio', 'The Artform', 'Studio', NULL, 3543161, 99, NULL, NULL, NULL, NULL, NULL, 'Estab­lished in 2005, the Artform Studio has been a premiere salon for vintage photography, television, film and the thriving Los Angeles artist community and hosts special events that embrace the evolution of hair, make-up, music, and fashion. This metropolitan salon hosts a clientele of working professionals in the downtown area, TV, film, editorial, theatrical and wedding industries. A multicultural team of licensed cosmetologists specialize in hair­cuts, mens grooming, hair color, hair­styling, braids, hair extensions, lash extensions, nail art, henna tattoo, and make up application.');
