	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32146, NULL, 'Rodrigo de Castro Lopes', 'Rodrigo de Castro', 'Lopes', NULL, 3545504, 99, NULL, NULL, NULL, NULL, NULL, 'Rodrigo de Castro Lopes is a musician and recording, mixing & mastering engineer. He started musical studies at age nine. Attended the studied physics for two years at University of Brasilia, after which switched to the music major, where graduated in piano (Bachelor degree). 80´s in Brasilia, studied with Neusa França, and afterwards with Ney Salgado, at UnB, after which studied with Nise Obino. At that time, he worked as accompanist at Teatro Nacional de Brasília, conducted by the maestro Silvio Barbato, and also keyboard player in a rock band, Banda 69, which was part of a compilation and released an LP with CBS, produced by Leo Jaime. 
