	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32160, NULL, 'Seydou Barry', 'Seydou', 'Barry', NULL, 3553403, 99, NULL, NULL, NULL, NULL, NULL, 'Artist representative and producer. Husband and associate of [a3640159].');
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (32161, NULL, 'Syd Schwartz', 'Syd', 'Schwartz', NULL, 3553560, 99, NULL, NULL, NULL, NULL, NULL, 'Syd Schwartz is the force behind the influential @jazzandcoffee Instagram account—widely acknowledged as one of the jazz world’s most impactful social media platforms. He extends his passion for cultivating a global jazz community through his Jazz & Coffee Substack, recognized as a 2024 Substack Editorial Pick for its insightful explorations of contemporary jazz culture and creative entrepreneurship. Schwartz is also a prolific and acclaimed liner notes author, writing for labels such as Blue Note, Rhino/Warner Music, Craft Recordings, and Strata-East. His commentary has accompanied releases by jazz icons including Yes, Bill Evans, Wayne Shorter, Art Pepper, Donald Byrd, Kenny Burrell, Art Blakey, and Charlie Rouse, highlighting both his encyclopedic knowledge of the genre and his deep respect for its artists. An active presence on multiple social media platforms and a frequent panelist, talking head, and interviewer across the entertainment landscape, Schwartz remains a guiding force at the intersection of music, media, and cultural conversation. His writing is informed by decades of experience as a music industry veteran renowned for helping shape modern digital marketing well before it became a cornerstone of artist promotion. During his tenure at Wind-up Records, Virgin, EMI, and Sony Music''s Legacy catalog division, Schwartz oversaw digital strategy for high-profile rock and alternative acts, refining strategies that propelled both established and up-and-coming musicians to new audiences and accolades.
