	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (33227, NULL, 'Aaron Douglas (3)', 'Aaron Douglas', '(3)', NULL, 4049341, 99, NULL, NULL, NULL, NULL, NULL, 'Aaron Douglas, Jr. was an African American visual artist born in Topeka, Kansas, on May 26, 1899. He moved to Detroit after high school in 1918, labored in auto factories, and attended courses at the Detroit Institute of Arts. Shortly thereafter Douglas began college at the University of Nebraska, Lincoln, earning a BFA in 1922. He taught in Kansas City for two years until moving to New York in 1925, where he settled in Harlem. There he worked for the NAACP’s publication ''The Crisis,'' investigated African art forms, and further explored techniques and style under noted artist/graphic designer Winold Reiss (who offered his instruction to Douglas at no charge.) Aaron solidified his place within the Harlem Renaissance movement by vividly illustrating the 1927 James Weldon Johnson poetry collection, ''God’s Trombones: Seven Negro Sermons in Verse.'' In the following years, Douglas relocated to Philadelphia on a Barnes Foundation fellowship and to Paris for studies at the Académie Scandinave, but eventually he returned to Harlem where was awarded a Rosenwald travel fellowship that sent him through a number of colleges in the American South. After attending Columbia University Teachers’ College back in NYC and earning an MFA degree, Douglas built upon his relationship with Fisk University in Nashville (where he had painted a significant mural in 1930, and revisited during his Rosenwald tour.) In 1944 he founded the art department at Fisk, and remained its chair until retiring in 1966. Aaron Douglas died on February 2, 1979. ');
