	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (34866, NULL, 'Sir Mychael Gabriel Davison', 'Sir Mychael Gabriel', 'Davison', NULL, 5155500, 99, NULL, NULL, NULL, NULL, NULL, 'Sir Mychael Gabriel Davison (b. 1986, Berkeley, CA) is an American musician, songwriter, producer, and audio engineer. He''s the son of [a=Gilbert Davison] (b. 1963), former [url=https://discogs.com/label/441405]Paisley Park Enterprises[/url] president and head of [a=Prince]''s security in the 1980s, and songwriter [a=Constance Guzman] (b. 1957), who met during [i]Purple Rain Tour[/i] and got married shortly afterward. Raised in the city of Minneapolis with a passion for music at a young age, Mychael began his professional career at sixteen, engineering sessions for the legendary American percussionist, [a=Sheila E.], continuously collaborating with her since then and currently performing as lead guitarist in [b][a592915][/b]. Mychael Gabriel has also worked with many prominent artists, from [a=Ringo Starr], [a=John Legend], [a=Snoop Dogg], [a=Beck], and [a=Gary Clark Jr.] to [a=Hans Zimmer], [a=St. Vincent], [a=Joss Stone], [a22164], [a=George Clinton], [a=Freddie Stone] of [a39768], and [a=Victor Wooten]. According to interviews with Mychael Gabriel, his godparents are [a=Sheila E.] and [a=Prince].');
