	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (35116, NULL, 'Studio 49', 'Studio', '49', NULL, 5377133, 99, NULL, NULL, NULL, NULL, NULL, 'Studio49 is a German manufacturer of musical instruments founded in 1949, predominately those used within the Orff Schulwerk approach to music education. Before the Second World War, composer Carl Orff and his friend Karl Maendler - a harpsichord maker - had built the first xylophone that became indispensable for teaching at the Güntherschule and for the development of Orff''s Schulwerk. After 1948, the Schulwerk, with its foundations already laid way back in the 1920''s, suddenly became popular. The Bavarian Broadcasting Company had aired some Schulwerk programs and started a deluge of questions about where to get these "Orff instruments". Carl Orff developed a relationship with Studio 49 founder Klaus Becker-Ehmck, and the demand for these instruments came very quickly. Studio 49 would eventually expand to include the manufacture of professional orchestral instruments such as vibraphones, marimbas, concert xylophones and tubular chimes.');
