	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (35428, NULL, 'Geraldo de Magalhães Melo Filho', 'Geraldo de Magalhães Melo', 'Filho', NULL, 5729168, 99, NULL, NULL, NULL, NULL, NULL, 'Empresário Artístico, Surpervisor Musical, Diretor de documentários e séries sobre Música, Curador, Professor de Música & Negócios; pernambucano de Recife, nasceu em 01/09/67 e lá iniciou suas atividades como Produtor Musical no final dos anos 80, promotor de eventos, gravações, e dos grandes nomes locais da época como Alceu Valença, Geraldo Azevedo, Carlos Fernando e Paulo Rafael; mudou-se para o Rio de Janeiro em 1992 e passou a trabalhar com a cena nacional e intenso intercâmbio entre artistas e eventos dentro e fora do Brasil, sendo curador e consultor para diversos festivais e centros culturais em todo o mundo, tais como Central Park SummerStage e Lincoln Center (NYC), Chicago Cultural Center e Fundação Casa da Música (Porto, Portugal), Back2Black (Rio e SP), Rock in Rio (coordenou vários shows do festival e mais recentemente o espetáculo “Pará Pop” em 2019). Dirige a DIVERSÃO E ARTE coordenando projetos, prestando consultorias e curadorias da empresa e para terceiros, e empresaria artistas e gerencia turnês e exportação de nomes como Dona Onete, Orquestra Imperial (é um dos fundadores), Combo X, Lenine, além  de diversas consultorias para outros artistas e empresas. Cria, produz e dirige álbuns musicais, documentários, série para tv e internet sobre artistas, música e negócios; dá aulas e faz palestras em diversos eventos (Rio2C, PUC, Rio Music Marketing, Sebrae, secretarias de cultura em todo o Brasil), encontros e painéis. É professor do curso Música & Negócios da PUC-Rio e Instituto Gênesis. Dentre muitos artistas tem trabalhos realizados com Daniela Mercury, Lenine, Naná Vasconcelos, Virgínia Rodrigues, Sandra de Sá, Lobão, Wilson das Neves, Luiz Melodia, Dj Dolores, Cidade Negra, Arto Lindsay, Charles Gavin, Fafá de Belém, Chico Science & Nação Zumbi, Living Colour, Boca Livre, Paulo Moura. 
