	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (36095, NULL, 'Robert Johnson Jr.', 'Robert Johnson', 'Jr.', NULL, 6488843, 99, NULL, NULL, NULL, NULL, NULL, 'US jazz trumpeter from Pensacola, Florida, active in the late 40s/50s. Johnson traveled extensively, playing jazz music and keeping apartments in Kansas City, Chicago and New York. In the 1970s, as big band gave way to rock ‘n’ roll, Johnson made his home in Ellenville. He was the first black musician to play in a show band at the Granit Hotel in Kerhonkson. 
	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (36096, NULL, 'Jake Long', 'Jake', 'Long', NULL, 6493436, 99, NULL, NULL, NULL, NULL, NULL, 'Jake Long is a London based Drummer/Producer and Band Leader who has performed and record alongside some of the world leading artists such as Gary Bartz, Okay Temiz, Joe Armon-Jones, Nubya Garcia, Sons Of Kemet, Saul Williams, Poppy Ajudha, Oscar Jerome, Theon Cross, Snapped Ankles and many others. Jake has toured extensively all around the world playing sell out shows in Asia, America, Europe and the UK. Jake’s previous band Maisha released several critically acclaimed records on Gilles Peterson''s Brownswood Recordings and toured extensively. In 2019 Maisha sparked up a collaboration with legendary American Saxophonist Gary Bartz which culminated in the release of a record on Night Dreamer Records in 2020.');
