	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (36899, NULL, 'Stanley Clarke/George Duke', 'Stanley Clarke/George', 'Duke', NULL, 7890175, 99, NULL, NULL, NULL, NULL, NULL, 'In 1981 [a=Stanley Clarke] and [a=George Duke] teamed up for a funk/disco album called [i]The Clarke/Duke Project[/i]. Two more albums in the same vein were to follow over the next decade. Though these releases were just under the name Stanley Clarke/George Duke, the album title stuck with the public and the collaboration was regularly referred to (and sometimes even credited on secondary releases) as the The Clarke/Duke Project.');
