	INSERT INTO Artist (artist_id, spotify_playlist_id, artist_fullname, artist_name, artist_surname, musicbrainz_uuid, discogs_id, instrument_id, wikipedia_url, thumbnail_url, image_author, image_license, image_source_url, wikipedia_data) VALUES (36993, NULL, 'Miklós Szilveszter', 'Miklós', 'Szilveszter', NULL, 8106800, 99, NULL, NULL, NULL, NULL, NULL, 'Hungarian free jazz drummer Szilveszter Miklós (1983) began his musical career on violin but soon he switched to drums. Graduated at the Franz Liszt Academy Of Music in Budapest but he still believes that his real education is based upon the experience of playing live with his older and experienced musician friends. Regularly performs with leading Hungarian free jazz musicians and participates in international groupings alongside with top-shelf instrumentalists including Peter Brötzmann, Rudi Mahall, Alexander von Schlippenbach and Han Bennink.');
